
        let autoRefreshTimer = null;
        let backupsData = [];
        let promptDataMap = new Map(); // name -> { positive, negative }
        let frontendWs = null;
        
        // 페이지네이션 상태
        let paginationState = {
            offset: 0,
            limit: 20,
            total: 0,
            hasMore: true,
            isLoading: false,
            filter: 'all'  // 모아보기 필터: all / restore / bot:{bot_name} / bot_none
        };
        
        // 설정 상태
        let currentConfig = {};
        let currentConfigLoadPromise = null;
        let memoFeatureEnabled = false;
        let memoDirty = false;
        let memoSaveTimer = null;
        let memoSaveRevision = 0;
        let memoSaveChain = Promise.resolve();
        let memoServerInstanceId = null;
        let memoPositionFrame = null;
        let memoQueueTransitionTimer = null;
        let memoLastQueueVisible = false;
        let memoLastQueueCollapsed = false;
        let memoQueueResizeObserver = null;
        let memoQueueMutationObserver = null;
        let memoActiveTab = 'note';
        let modalWorkerFeatureEnabled = false;
        let modalWorkerExpanded = false;
        let modalWorkerPollTimer = null;
        let modalWorkerPollBusy = false;
        let modalWorkerPollPending = false;
        let modalWorkerQueueActive = false;
        let modalWorkerRuntimeActive = false;
        let modalWorkerHasSnapshot = false;
        let modalWorkerActiveRefreshSeconds = 5;
        const MODAL_WORKER_IDLE_REFRESH_MS = 60000;

        function setMemoSaveStatus(message, state = 'idle') {
            const status = document.getElementById('memo-save-status');
            if (!status) {
                console.error('[MEMO] 저장 상태 요소를 찾지 못했습니다:', { message, state });
                return;
            }
            status.textContent = message;
            status.dataset.state = state;
        }

        function setMemoKnowledgeStatus(message, state = 'idle') {
            const status = document.getElementById('memo-knowledge-status');
            if (!status) {
                console.error('[DANBOORU_KNOWLEDGE] 검색 상태 요소를 찾지 못했습니다:', {
                    message,
                    state,
                });
                return;
            }
            status.textContent = message;
            status.dataset.state = state;
        }

        function switchMemoTab(tabName, focusTarget = true) {
            const validTabs = ['note', 'search'];
            if (!validTabs.includes(tabName)) {
                console.error('[MEMO] 지원하지 않는 메모장 탭:', { tabName });
                return;
            }
            const noteTab = document.getElementById('memo-tab-note');
            const searchTab = document.getElementById('memo-tab-search');
            const notePanel = document.getElementById('memo-panel-note');
            const searchPanel = document.getElementById('memo-panel-search');
            const noteFooter = document.getElementById('memo-note-footer');
            const searchFooter = document.getElementById('memo-search-footer');
            if (!noteTab || !searchTab || !notePanel || !searchPanel || !noteFooter || !searchFooter) {
                console.error('[MEMO] 탭 전환 UI 요소 누락:', {
                    noteTab: !!noteTab,
                    searchTab: !!searchTab,
                    notePanel: !!notePanel,
                    searchPanel: !!searchPanel,
                    noteFooter: !!noteFooter,
                    searchFooter: !!searchFooter,
                });
                return;
            }

            memoActiveTab = tabName;
            const noteActive = tabName === 'note';
            noteTab.setAttribute('aria-selected', String(noteActive));
            searchTab.setAttribute('aria-selected', String(!noteActive));
            noteTab.tabIndex = noteActive ? 0 : -1;
            searchTab.tabIndex = noteActive ? -1 : 0;
            notePanel.hidden = !noteActive;
            searchPanel.hidden = noteActive;
            noteFooter.hidden = !noteActive;
            searchFooter.hidden = noteActive;

            if (!focusTarget) return;
            const target = noteActive
                ? document.getElementById('memo-textarea')
                : document.getElementById('memo-knowledge-query');
            if (target) {
                target.focus();
            } else {
                console.error('[MEMO] 활성 탭의 포커스 대상을 찾지 못했습니다:', {
                    tabName,
                });
            }
        }

        async function copyMemoKnowledgeTag(tag) {
            const value = typeof tag === 'string' ? tag.trim() : '';
            if (!value) {
                console.error('[DANBOORU_KNOWLEDGE] 복사할 태그가 비어 있습니다:', { tag });
                return;
            }
            try {
                if (!navigator.clipboard || typeof navigator.clipboard.writeText !== 'function') {
                    throw new Error('Clipboard API를 사용할 수 없습니다.');
                }
                await navigator.clipboard.writeText(value);
                showToast(`태그 복사: ${value}`, 'success');
            } catch (error) {
                console.error('[DANBOORU_KNOWLEDGE] 태그 복사 실패:', error, { tag: value });
                showToast('태그 복사에 실패했습니다.', 'error');
            }
        }

        function appendMemoKnowledgeEvidenceField(container, label, value) {
            if (!value) return;
            const row = document.createElement('div');
            const heading = document.createElement('strong');
            heading.textContent = `${label}: `;
            row.appendChild(heading);
            row.appendChild(document.createTextNode(String(value)));
            container.appendChild(row);
        }

        function renderMemoKnowledgeResult(data) {
            const results = document.getElementById('memo-knowledge-results');
            if (!results) {
                console.error('[DANBOORU_KNOWLEDGE] 검색 결과 컨테이너를 찾지 못했습니다.', data);
                return false;
            }
            if (!data || typeof data.answer !== 'string' || !Array.isArray(data.evidence)) {
                console.error('[DANBOORU_KNOWLEDGE] 검색 결과 형식 오류:', data);
                return false;
            }
            results.replaceChildren();

            const answerCard = document.createElement('section');
            answerCard.className = 'memo-knowledge-answer';
            const answerHead = document.createElement('div');
            answerHead.className = 'memo-knowledge-answer-head';
            const statusLabels = {
                answered: '근거 확인됨',
                ambiguous: '복수 후보',
                not_found: '근거 부족',
            };
            const confidenceLabels = { high: '높음', medium: '보통', low: '낮음' };
            const answerLabel = document.createElement('span');
            answerLabel.textContent = statusLabels[data.status] || '검색 답변';
            const confidence = document.createElement('span');
            confidence.textContent = `신뢰도 ${confidenceLabels[data.confidence] || data.confidence || '-'}`;
            answerHead.append(answerLabel, confidence);
            const answerText = document.createElement('p');
            answerText.className = 'memo-knowledge-answer-text';
            answerText.textContent = data.answer;
            answerCard.append(answerHead, answerText);
            results.appendChild(answerCard);

            const meta = document.createElement('div');
            meta.className = 'memo-knowledge-meta';
            const searchQueries = Array.isArray(data.search_queries)
                ? data.search_queries.filter(value => typeof value === 'string' && value.trim())
                : [];
            const lexicalTerms = Array.isArray(data.lexical_terms)
                ? data.lexical_terms.filter(value => typeof value === 'string' && value.trim())
                : [];
            const categories = Array.isArray(data.categories)
                ? data.categories.map(item => item && item.label).filter(Boolean)
                : [];
            const metaLines = [];
            if (typeof data.interpretation === 'string' && data.interpretation.trim()) {
                metaLines.push(`질문 해석: ${data.interpretation}`);
            }
            if (searchQueries.length) metaLines.push(`검색 단위: ${searchQueries.join(' · ')}`);
            if (lexicalTerms.length) metaLines.push(`태그명 후보: ${lexicalTerms.join(' · ')}`);
            if (categories.length) metaLines.push(`검색 범위: ${categories.join(' · ')}`);
            metaLines.push(`검토 후보: ${Number(data.candidate_count || 0)}개 · ${Number(data.elapsed_ms || 0)}ms`);
            meta.textContent = metaLines.join('\n');
            meta.style.whiteSpace = 'pre-wrap';
            results.appendChild(meta);

            const evidenceList = document.createElement('div');
            evidenceList.className = 'memo-evidence-list';
            for (const item of data.evidence) {
                if (!item || typeof item.tag !== 'string' || !item.tag.trim()) {
                    console.error('[DANBOORU_KNOWLEDGE] 유효하지 않은 근거 행 스킵:', item);
                    continue;
                }
                const fallbackBaseTag = item.tag
                    .replaceAll('_', ' ')
                    .replaceAll('(', '\\(')
                    .replaceAll(')', '\\)');
                const fallbackDisplayTag = Number(item.category) === 3
                    ? `(\\${fallbackBaseTag})\\`
                    : fallbackBaseTag;
                const displayTag = (
                    typeof item.display_tag === 'string' && item.display_tag.trim()
                        ? item.display_tag.trim()
                        : fallbackDisplayTag
                );
                const card = document.createElement('article');
                card.className = 'memo-evidence-card';
                const head = document.createElement('div');
                head.className = 'memo-evidence-head';
                const tag = document.createElement('span');
                tag.className = 'memo-evidence-tag';
                tag.textContent = displayTag;
                const score = document.createElement('span');
                score.className = 'memo-evidence-score';
                const numericScore = Number(item.score);
                score.textContent = Number.isFinite(numericScore)
                    ? `유사도 ${(numericScore * 100).toFixed(1)}%`
                    : '유사도 -';
                const copyButton = document.createElement('button');
                copyButton.type = 'button';
                copyButton.className = 'memo-evidence-copy';
                copyButton.textContent = '복사';
                copyButton.setAttribute('aria-label', `${displayTag} 태그 복사`);
                copyButton.addEventListener('click', () => void copyMemoKnowledgeTag(displayTag));
                head.append(tag, score, copyButton);

                const body = document.createElement('div');
                body.className = 'memo-evidence-body';
                appendMemoKnowledgeEvidenceField(
                    body,
                    '종류',
                    [item.category_label, item.major].filter(Boolean).join(' · ')
                );
                appendMemoKnowledgeEvidenceField(body, '작품/하위 분류', item.minor);
                appendMemoKnowledgeEvidenceField(body, '설명', item.definition);
                if (Array.isArray(item.aliases) && item.aliases.length) {
                    appendMemoKnowledgeEvidenceField(
                        body,
                        '별칭',
                        item.aliases.map(value => String(value).replaceAll('_', ' ')).join(', ')
                    );
                }
                card.append(head, body);
                evidenceList.appendChild(card);
            }
            if (!evidenceList.childElementCount) {
                const empty = document.createElement('div');
                empty.className = 'memo-knowledge-help';
                empty.textContent = '답변에 연결할 수 있는 RAG 근거 태그가 없습니다.';
                evidenceList.appendChild(empty);
            }
            results.appendChild(evidenceList);
            results.hidden = false;
            return true;
        }

        async function searchDanbooruKnowledge(event) {
            if (event && typeof event.preventDefault === 'function') event.preventDefault();
            const input = document.getElementById('memo-knowledge-query');
            const button = document.getElementById('memo-knowledge-submit');
            const results = document.getElementById('memo-knowledge-results');
            if (!input || !button || !results) {
                console.error('[DANBOORU_KNOWLEDGE] 검색 UI 요소 누락:', {
                    input: !!input,
                    button: !!button,
                    results: !!results,
                });
                return;
            }
            const question = input.value.trim();
            if (!question) {
                console.error('[DANBOORU_KNOWLEDGE] 빈 질문 검색 거부');
                setMemoKnowledgeStatus('찾고 싶은 내용을 자연어로 입력하세요.', 'error');
                input.focus();
                return;
            }

            button.disabled = true;
            button.textContent = '검색 중...';
            results.hidden = true;
            setMemoKnowledgeStatus(
                'LLM이 질문을 분석하고 RAG 근거를 찾은 뒤 답을 검증하는 중입니다...',
                'loading'
            );
            try {
                const response = await fetch('/api/danbooru_rag/assist', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ question }),
                });
                const data = await response.json().catch(error => {
                    console.error('[DANBOORU_KNOWLEDGE] 응답 JSON 해석 실패:', error, {
                        status: response.status,
                    });
                    return null;
                });
                if (!response.ok || !data || data.success !== true) {
                    console.error('[DANBOORU_KNOWLEDGE] 검색 API 실패:', {
                        status: response.status,
                        data,
                        question,
                    });
                    throw new Error((data && data.error) || `HTTP ${response.status}`);
                }
                if (!renderMemoKnowledgeResult(data)) {
                    throw new Error('검색 결과를 화면에 표시할 수 없습니다.');
                }
                setMemoKnowledgeStatus('RAG 근거로 답변을 만들었습니다.', 'done');
            } catch (error) {
                console.error('[DANBOORU_KNOWLEDGE] 자연어 태그 검색 실패:', error, {
                    question,
                });
                setMemoKnowledgeStatus(`검색 실패: ${error.message || String(error)}`, 'error');
                results.hidden = true;
            } finally {
                button.disabled = false;
                button.textContent = '검색';
            }
        }

        function updateMemoSettingStatus(checked) {
            const status = document.getElementById('memo-setting-status');
            if (!status) {
                console.error('[MEMO] 설정 상태 요소를 찾지 못했습니다:', { checked });
                return;
            }
            status.textContent = checked ? 'ON' : 'OFF';
            status.className = 'toggle-status ' + (checked ? 'on' : 'off');
        }

        function syncLeftUtilityStackVisibility() {
            const stack = document.getElementById('left-utility-stack');
            const widget = document.getElementById('modal-worker-widget');
            const vastWidget = document.getElementById('vast-worker-widget');
            const launcher = document.getElementById('memo-launcher');
            if (!stack || !widget || !launcher) {
                console.error('[LEFT_DOCK] 표시 상태 동기화 UI 요소 누락:', {
                    stack: !!stack,
                    widget: !!widget,
                    launcher: !!launcher,
                });
                return;
            }
            stack.hidden = widget.hidden && launcher.hidden && (vastWidget ? vastWidget.hidden : true);
            if (!stack.hidden) scheduleMemoLauncherPositionSync();
            syncCmComposeDockPadding();
        }

        function setModalWorkerPanelExpanded(expanded) {
            modalWorkerExpanded = Boolean(expanded);
            const panel = document.getElementById('modal-worker-panel');
            const wallTab = document.getElementById('modal-worker-wall-tab');
            if (!panel || !wallTab) {
                console.error('[MODAL_WORKER] 접기 UI 요소 누락:', {
                    panel: !!panel,
                    wallTab: !!wallTab,
                    expanded: modalWorkerExpanded,
                });
                return;
            }
            panel.hidden = !modalWorkerExpanded;
            panel.inert = !modalWorkerExpanded;
            panel.setAttribute('aria-hidden', String(!modalWorkerExpanded));
            wallTab.hidden = modalWorkerExpanded;
            wallTab.inert = modalWorkerExpanded;
            wallTab.setAttribute('aria-hidden', String(modalWorkerExpanded));
            wallTab.setAttribute('aria-expanded', String(modalWorkerExpanded));
            wallTab.tabIndex = modalWorkerExpanded ? -1 : 0;
        }

        function collapseModalWorkerPanel() {
            const wallTab = document.getElementById('modal-worker-wall-tab');
            if (!wallTab) {
                console.error('[MODAL_WORKER] 접은 뒤 포커스를 옮길 탭이 없습니다.');
                return;
            }
            setModalWorkerPanelExpanded(false);
            wallTab.focus();
        }

        function expandModalWorkerPanel() {
            const collapseButton = document.getElementById('modal-worker-collapse-btn');
            if (!collapseButton) {
                console.error('[MODAL_WORKER] 펼친 뒤 포커스를 옮길 버튼이 없습니다.');
                return;
            }
            setModalWorkerPanelExpanded(true);
            collapseButton.focus();
        }

        function stopModalWorkerPolling() {
            if (modalWorkerPollTimer !== null) {
                window.clearTimeout(modalWorkerPollTimer);
                modalWorkerPollTimer = null;
            }
        }

        function modalWorkerNextRefreshMs() {
            return (modalWorkerQueueActive || modalWorkerRuntimeActive)
                ? modalWorkerActiveRefreshSeconds * 1000
                : MODAL_WORKER_IDLE_REFRESH_MS;
        }

        function scheduleModalWorkerPolling() {
            stopModalWorkerPolling();
            if (!modalWorkerFeatureEnabled || document.hidden) return;
            modalWorkerPollTimer = window.setTimeout(
                () => void refreshModalWorkerStatus(false),
                modalWorkerNextRefreshMs(),
            );
        }

        function modalWorkerCount(data, key) {
            const value = Number(data?.[key]);
            if (!Number.isFinite(value) || value < 0 || !Number.isInteger(value)) {
                console.error('[MODAL_WORKER] 통계 값 형식 오류:', { key, value: data?.[key], data });
                throw new Error(`Modal ${key} 통계가 올바르지 않습니다.`);
            }
            return value;
        }

        function modalWorkerUiElements() {
            const elements = {
                widget: document.getElementById('modal-worker-widget'),
                heading: document.getElementById('modal-worker-heading'),
                state: document.getElementById('modal-worker-state'),
                runners: document.getElementById('modal-worker-runners'),
                running: document.getElementById('modal-worker-running'),
                backlog: document.getElementById('modal-worker-backlog'),
                checked: document.getElementById('modal-worker-checked'),
                wallTab: document.getElementById('modal-worker-wall-tab'),
                refreshButton: document.querySelector('.modal-worker-refresh-btn'),
            };
            const missing = Object.entries(elements).filter(([, value]) => !value).map(([key]) => key);
            if (missing.length) {
                console.error('[MODAL_WORKER] 상태 표시 UI 요소 누락:', { missing });
                return null;
            }
            return elements;
        }

        function modalWorkerErrorCopy(reason) {
            switch (String(reason || 'runtime_unavailable')) {
                case 'app_not_deployed':
                    return {
                        state: '작업 App 미배포',
                        detail: '동기화된 자산은 유지됩니다 · MODAL 탭에서 기본 앱 재배포를 실행하세요',
                    };
                case 'network_unavailable':
                    return {
                        state: 'Modal 네트워크 장애',
                        detail: 'Modal 서버에 연결하지 못했습니다',
                    };
                default:
                    return {
                        state: '상태 조회 실패',
                        detail: 'Modal 상태를 확인하지 못했습니다',
                    };
            }
        }

        function renderModalWorkerError(message, reason = 'runtime_unavailable') {
            const elements = modalWorkerUiElements();
            if (!elements) return;
            const technicalDetail = String(message || '알 수 없는 오류');
            const copy = modalWorkerErrorCopy(reason);
            modalWorkerRuntimeActive = false;
            elements.widget.dataset.state = 'error';
            elements.state.textContent = copy.state;
            elements.state.title = technicalDetail;
            elements.runners.textContent = '-';
            elements.running.textContent = '-';
            elements.backlog.textContent = '-';
            elements.wallTab.setAttribute('aria-label', `${copy.state}: ${copy.detail}`);
            elements.wallTab.title = `${copy.state}: ${copy.detail}`;
            const retrySeconds = Math.round(modalWorkerNextRefreshMs() / 1000);
            elements.checked.textContent = `${copy.detail} · ${retrySeconds}초 후 재시도`;
            elements.checked.title = technicalDetail;
        }

        function renderModalWorkerDeploying(data) {
            const elements = modalWorkerUiElements();
            if (!elements) return;
            const worker = data?.worker || {};
            const message = String(worker.message || data?.message || 'Modal 런타임을 배포하고 있습니다.');
            modalWorkerRuntimeActive = true;
            modalWorkerHasSnapshot = true;
            elements.widget.dataset.state = 'checking';
            elements.heading.textContent = `Modal ${String(data?.gpu || 'GPU')}`;
            elements.state.textContent = 'Modal 배포 중';
            elements.state.title = message;
            elements.runners.textContent = '-';
            elements.running.textContent = '-';
            elements.backlog.textContent = '-';
            elements.wallTab.setAttribute('aria-label', `Modal 배포 중: ${message}`);
            elements.wallTab.title = `Modal 배포 중: ${message}`;
            const nextSeconds = Math.round(modalWorkerNextRefreshMs() / 1000);
            elements.checked.textContent = `${message} · ${nextSeconds}초 후 확인`;
            elements.checked.title = message;
        }

        function renderModalWebStatus(web) {
            const webBlock = document.getElementById('modal-worker-web');
            const webStateEl = document.getElementById('modal-worker-web-state');
            const webLink = document.getElementById('modal-worker-web-link');
            if (!webBlock || !webStateEl) return;
            web = web || {};
            const state = String(web.state || 'unknown');
            webBlock.dataset.webState = state;
            let label;
            switch (state) {
                case 'starting': label = 'WebUI 시작 중'; break;
                case 'running': label = 'WebUI 실행 중'; break;
                case 'stopping': label = 'WebUI 종료 중'; break;
                case 'failed': label = 'WebUI 오류'; break;
                case 'stopped': label = 'WebUI 꺼짐'; break;
                case 'checking': label = 'WebUI 확인 중'; break;
                default:
                    // unknown: 배포됨(미추적) / error(확인 실패) / 그 외(미확인) 구분
                    label = web.error
                        ? 'WebUI 확인 실패'
                        : (web.deployed === true ? 'WebUI 미추적' : 'WebUI 미확인');
            }
            const runners = Number(web.runners);
            if (state === 'running' && Number.isFinite(runners) && runners > 0) {
                label += ` · ${String(web.gpu || 'GPU')} ${runners}개`;
            }
            webStateEl.textContent = label;
            const detail = web.error ? String(web.error) : (web.message || '');
            webStateEl.title = detail || '';
            if (webLink) {
                if (state === 'running' && web.url) {
                    webLink.href = web.url;
                    webLink.hidden = false;
                    webLink.title = `WebUI 접속: ${web.url}`;
                } else {
                    webLink.hidden = true;
                    webLink.removeAttribute('href');
                    webLink.title = '';
                }
            }
        }

        function renderModalWorkerStatus(data) {
            const elements = modalWorkerUiElements();
            if (!elements) return;
            if (!data || data.ok !== true || data.enabled !== true) {
                console.error('[MODAL_WORKER] 활성 상태 응답 형식 오류:', data);
                throw new Error('Modal Worker 상태 응답이 올바르지 않습니다.');
            }
            const refreshSeconds = Number(data.refresh_seconds);
            if (Number.isInteger(refreshSeconds) && refreshSeconds >= 2 && refreshSeconds <= 60) {
                modalWorkerActiveRefreshSeconds = refreshSeconds;
            } else {
                console.error('[MODAL_WORKER] 활성 갱신 주기 형식 오류, 5초 사용:', {
                    refresh_seconds: data.refresh_seconds,
                });
                modalWorkerActiveRefreshSeconds = 5;
            }
            const worker = data.worker || {};
            const wState = String(worker.state || '');
            if (wState === 'deploying' || worker.reason === 'deployment_in_progress') {
                renderModalWorkerDeploying(data);
                return;
            }
            if (wState === 'error' || worker.available !== true) {
                renderModalWorkerError(
                    worker.error || worker.reason || 'Modal runtime 통계를 사용할 수 없습니다.',
                    worker.reason,
                );
                return;
            }

            const runners = modalWorkerCount(worker, 'workers');
            const running = modalWorkerCount(worker, 'generating');
            const backlog = modalWorkerCount(worker, 'queued');
            const gpuOn = worker.gpu_on === true || runners > 0;
            if (worker.gpu_on !== undefined && Boolean(worker.gpu_on) !== gpuOn) {
                console.error('[MODAL_WORKER] GPU 상태와 Worker 수가 일치하지 않습니다:', {
                    gpu_on: worker.gpu_on,
                    workers: runners,
                });
            }
            modalWorkerRuntimeActive = gpuOn || running > 0 || backlog > 0;
            modalWorkerHasSnapshot = true;
            elements.widget.dataset.state = gpuOn ? 'on' : 'off';
            elements.heading.textContent = `Modal ${String(data.gpu || 'GPU')}`;
            elements.state.textContent = gpuOn
                ? `GPU ON · Worker ${runners}개`
                : (modalWorkerQueueActive ? 'GPU 시작 대기' : 'GPU OFF · 자동 대기');
            elements.state.removeAttribute('title');
            elements.runners.textContent = String(runners);
            elements.running.textContent = String(running);
            elements.backlog.textContent = String(backlog);
            const wallLabel = gpuOn
                ? `Modal GPU ON, Worker ${runners}개, 펼치기`
                : `Modal GPU OFF, 펼치기`;
            elements.wallTab.setAttribute('aria-label', wallLabel);
            elements.wallTab.title = wallLabel;

            const checkedDate = new Date(Number(data.checked_at || 0) * 1000);
            const checkedText = Number.isNaN(checkedDate.getTime())
                ? '방금 확인'
                : `${checkedDate.toLocaleTimeString('ko-KR', { hour12: false })} 확인`;
            const nextSeconds = Math.round(modalWorkerNextRefreshMs() / 1000);
            elements.checked.textContent = `${checkedText} · ${nextSeconds}초 주기`;
            elements.checked.removeAttribute('title');
        }

        async function refreshModalWorkerStatus(manual = false) {
            if (!modalWorkerFeatureEnabled) {
                if (manual) console.error('[MODAL_WORKER] Modal OFF 상태에서 수동 조회를 요청했습니다.');
                return;
            }
            if (document.hidden && !manual) {
                stopModalWorkerPolling();
                return;
            }
            if (modalWorkerPollBusy) {
                modalWorkerPollPending = true;
                return;
            }
            stopModalWorkerPolling();
            modalWorkerPollBusy = true;
            const elements = modalWorkerUiElements();
            if (elements) {
                elements.refreshButton.disabled = true;
                elements.checked.textContent = '상태 확인 중…';
                if (!modalWorkerHasSnapshot) {
                    elements.widget.dataset.state = 'checking';
                    elements.state.textContent = '상태 확인 중';
                }
            }
            try {
                const data = await fetchJSON('/api/modal/worker-status');
                if (data?.enabled === false) {
                    console.log('[MODAL_WORKER] 서버 설정이 OFF로 변경되어 상태 블록을 숨깁니다.');
                    applyModalWorkerFeatureConfig({ modal_enabled: false });
                    return;
                }
                // worker 블록과 web 블록은 서로 격리: 한쪽 실패가 다른 쪽을 죽이지 않는다.
                renderModalWorkerStatus(data);
                renderModalWebStatus(data?.web);
            } catch (error) {
                console.error('[MODAL_WORKER] 상태 조회 실패:', error, {
                    queueActive: modalWorkerQueueActive,
                    runtimeActive: modalWorkerRuntimeActive,
                });
                renderModalWorkerError(error?.message || String(error), 'runtime_unavailable');
                renderModalWebStatus({
                    state: 'unknown',
                    deployed: null,
                    url: '',
                    runners: null,
                    message: 'WebUI 상태 조회 실패',
                    error: error?.message || String(error),
                });
            } finally {
                modalWorkerPollBusy = false;
                const latestElements = modalWorkerUiElements();
                if (latestElements) latestElements.refreshButton.disabled = false;
                if (modalWorkerPollPending && modalWorkerFeatureEnabled && !document.hidden) {
                    modalWorkerPollPending = false;
                    window.setTimeout(() => void refreshModalWorkerStatus(false), 0);
                } else {
                    modalWorkerPollPending = false;
                    scheduleModalWorkerPolling();
                }
            }
        }

        function applyModalWorkerFeatureConfig(config) {
            if (!config || typeof config !== 'object') {
                console.error('[MODAL_WORKER] 기능 설정 형식 오류:', config);
                return;
            }
            const widget = document.getElementById('modal-worker-widget');
            if (!widget) {
                console.error('[MODAL_WORKER] 기능 상태를 적용할 위젯이 없습니다.', config);
                return;
            }
            const refreshSeconds = Number(config.modal_status_refresh_seconds ?? 5);
            if (Number.isInteger(refreshSeconds) && refreshSeconds >= 2 && refreshSeconds <= 60) {
                modalWorkerActiveRefreshSeconds = refreshSeconds;
            } else {
                console.error('[MODAL_WORKER] 설정의 갱신 주기가 올바르지 않아 5초를 사용합니다:', {
                    modal_status_refresh_seconds: config.modal_status_refresh_seconds,
                });
                modalWorkerActiveRefreshSeconds = 5;
            }
            modalWorkerFeatureEnabled = config.modal_enabled === true;
            widget.hidden = !modalWorkerFeatureEnabled;
            if (!modalWorkerFeatureEnabled) {
                stopModalWorkerPolling();
                modalWorkerPollPending = false;
                modalWorkerQueueActive = false;
                modalWorkerRuntimeActive = false;
                modalWorkerHasSnapshot = false;
            }
            syncLeftUtilityStackVisibility();
            if (modalWorkerFeatureEnabled) void refreshModalWorkerStatus(false);
        }

        function notifyModalWorkerQueueState(queueStatus) {
            const items = Array.isArray(queueStatus?.items) ? queueStatus.items : [];
            const currentModals = Array.isArray(queueStatus?.current_modals)
                ? queueStatus.current_modals
                : [];
            const candidates = [...items, ...currentModals];
            const active = candidates.some(item => {
                const status = String(item?.status || '').toLowerCase();
                if (status !== 'pending' && status !== 'processing') return false;
                const area = String(item?.execution_area || '').toLowerCase();
                const provider = String(item?.provider || '').toLowerCase();
                return area === 'modal'
                    || (area === 'comfy_parallel' && provider.split('+').includes('modal'))
                    || provider === 'modal'
                    || provider.split('+').includes('modal');
            });
            if (active === modalWorkerQueueActive) return;
            modalWorkerQueueActive = active;
            if (modalWorkerFeatureEnabled && !document.hidden) {
                void refreshModalWorkerStatus(false);
            }
        }

        function handleModalWorkerVisibilityChange() {
            if (!modalWorkerFeatureEnabled) return;
            if (document.hidden) {
                stopModalWorkerPolling();
            } else {
                void refreshModalWorkerStatus(false);
            }
        }

        function initializeModalWorkerUi() {
            const widget = document.getElementById('modal-worker-widget');
            const panel = document.getElementById('modal-worker-panel');
            const wallTab = document.getElementById('modal-worker-wall-tab');
            if (!widget || !panel || !wallTab) {
                console.error('[MODAL_WORKER] 초기화 UI 요소 누락:', {
                    widget: !!widget,
                    panel: !!panel,
                    wallTab: !!wallTab,
                });
                return;
            }
            setModalWorkerPanelExpanded(modalWorkerExpanded);
            document.addEventListener('visibilitychange', handleModalWorkerVisibilityChange);
            syncLeftUtilityStackVisibility();
        }

        function syncMemoLauncherPosition() {
            memoPositionFrame = null;
            const stack = document.getElementById('left-utility-stack');
            if (!stack) {
                console.error('[LEFT_DOCK] 위치를 조정할 유틸리티 스택이 없습니다.');
                return;
            }
            if (stack.hidden) return;

            const mobile = window.matchMedia('(max-width: 520px)').matches;
            const fallbackBottom = mobile ? 10 : 18;
            let bottom = fallbackBottom;
            const queueContainer = document.getElementById('asset-queue-container');
            if (queueContainer && getComputedStyle(queueContainer).display !== 'none') {
                let anchor = queueContainer;
                if (queueContainer.classList.contains('collapsed')) {
                    const wallTab = document.getElementById('asset-queue-wall-tab');
                    if (wallTab && getComputedStyle(wallTab).visibility !== 'hidden') {
                        anchor = wallTab;
                    } else {
                        console.error('[MEMO] 접힌 작업 큐의 위치 기준 탭을 찾지 못했습니다.');
                    }
                }
                const rect = anchor.getBoundingClientRect();
                if (rect.height > 0) {
                    bottom = Math.max(
                        fallbackBottom,
                        Math.ceil(window.innerHeight - rect.top + 10)
                    );
                } else {
                    console.error('[MEMO] 작업 큐 위치 계산 실패:', {
                        width: rect.width,
                        height: rect.height,
                    });
                }
            }
            const currentBottom = Number.parseFloat(getComputedStyle(stack).bottom);
            if (Number.isFinite(currentBottom) && bottom > currentBottom) {
                stack.classList.add('utility-position-immediate');
                stack.style.bottom = `${bottom}px`;
                requestAnimationFrame(() => {
                    stack.classList.remove('utility-position-immediate');
                });
            } else {
                stack.style.bottom = `${bottom}px`;
            }
        }

        function scheduleMemoLauncherPositionSync() {
            if (memoPositionFrame !== null) {
                cancelAnimationFrame(memoPositionFrame);
            }
            memoPositionFrame = requestAnimationFrame(syncMemoLauncherPosition);
        }

        // 캐릭터 메이커 좌측 레일(채팅 입력/버튼)이 좌하단 유틸리티 스택(메모장·Modal/Vast 워커 위젯)에
        // 가려지지 않도록, 캐릭터 메이커 탭이 활성이고 스택이 보일 때만 입력 컨테이너 왼쪽에
        // 접기 블럭 폭(30px)만큼 패딩을 띄운다. 스택이 숨겨지거나 탭을 벗어나면 0으로 되돌린다.
        function syncCmComposeDockPadding() {
            const compose = document.querySelector('#tab-character-maker-content .cm-chat-compose');
            if (!compose) return;
            const stack = document.getElementById('left-utility-stack');
            const cmTab = document.getElementById('tab-character-maker-content');
            const cmActive = !!(cmTab && cmTab.classList.contains('active'));
            const dockVisible = !!(stack && !stack.hidden && cmActive);
            compose.style.setProperty('--cm-compose-dock-pad', dockVisible ? '30px' : '0px');
        }

        function handleMemoQueueLayoutMutation() {
            const queueContainer = document.getElementById('asset-queue-container');
            if (!queueContainer) {
                console.error('[MEMO] 큐 위치 변경을 처리할 컨테이너가 없습니다.');
                return;
            }
            const queueVisible = getComputedStyle(queueContainer).display !== 'none';
            const queueCollapsed = queueContainer.classList.contains('collapsed');
            const startedCollapsing = (
                queueVisible
                && memoLastQueueVisible
                && queueCollapsed
                && !memoLastQueueCollapsed
            );
            memoLastQueueVisible = queueVisible;
            memoLastQueueCollapsed = queueCollapsed;

            if (memoQueueTransitionTimer !== null) {
                clearTimeout(memoQueueTransitionTimer);
                memoQueueTransitionTimer = null;
            }
            if (startedCollapsing) {
                memoQueueTransitionTimer = window.setTimeout(() => {
                    memoQueueTransitionTimer = null;
                    scheduleMemoLauncherPositionSync();
                }, 260);
                return;
            }
            scheduleMemoLauncherPositionSync();
        }

        function applyMemoFeatureEnabled(enabled) {
            memoFeatureEnabled = Boolean(enabled);
            const launcher = document.getElementById('memo-launcher');
            if (!launcher) {
                console.error('[MEMO] 기능 상태를 적용할 메모장 버튼이 없습니다:', {
                    enabled: memoFeatureEnabled,
                });
                return;
            }
            launcher.hidden = !memoFeatureEnabled;
            if (!memoFeatureEnabled) {
                closeMemoPad(false);
            }
            syncLeftUtilityStackVisibility();
        }

        async function loadMemoFromServer() {
            if (!memoFeatureEnabled) {
                console.error('[MEMO] 비활성 상태에서 메모 불러오기를 요청했습니다.');
                return false;
            }
            const textarea = document.getElementById('memo-textarea');
            if (!textarea) {
                console.error('[MEMO] 내용을 불러올 textarea가 없습니다.');
                return false;
            }

            await memoSaveChain;
            const pendingMemo = textarea.value;
            const hadUnsavedMemo = memoDirty;
            const previousInstanceId = memoServerInstanceId;
            textarea.disabled = true;
            setMemoSaveStatus('불러오는 중...', 'idle');
            try {
                const result = await fetchJSON('/api/memo');
                if (
                    !result
                    || result.success !== true
                    || typeof result.memo !== 'string'
                    || typeof result.instance_id !== 'string'
                    || !result.instance_id
                ) {
                    console.error('[MEMO] 불러오기 응답 형식 오류:', result);
                    throw new Error('메모 응답 형식이 올바르지 않습니다.');
                }
                memoServerInstanceId = result.instance_id;
                const serverRestarted = Boolean(
                    previousInstanceId && previousInstanceId !== result.instance_id
                );
                if (hadUnsavedMemo && !serverRestarted) {
                    textarea.value = pendingMemo;
                    memoDirty = true;
                    setMemoSaveStatus('미저장 내용 재전송 중...', 'idle');
                    void saveMemoToServer();
                } else {
                    textarea.value = result.memo;
                    memoDirty = false;
                    setMemoSaveStatus(
                        serverRestarted ? '서버 재시작으로 초기화됨' : '서버에서 불러옴',
                        'saved'
                    );
                }
                return true;
            } catch (error) {
                console.error('[MEMO] 서버 메모 불러오기 실패:', error);
                setMemoSaveStatus('불러오기 실패', 'error');
                return false;
            } finally {
                textarea.disabled = false;
            }
        }

        function saveMemoToServer() {
            if (memoSaveTimer !== null) {
                clearTimeout(memoSaveTimer);
                memoSaveTimer = null;
            }
            if (!memoDirty) return memoSaveChain;

            const textarea = document.getElementById('memo-textarea');
            if (!textarea) {
                console.error('[MEMO] 저장할 textarea가 없습니다.');
                return memoSaveChain;
            }
            if (!memoServerInstanceId) {
                console.error('[MEMO] 서버 실행 식별자가 없어 메모를 저장할 수 없습니다.');
                setMemoSaveStatus('다시 열어 불러오세요', 'error');
                return memoSaveChain;
            }
            const memo = textarea.value;
            const instanceId = memoServerInstanceId;
            const revision = ++memoSaveRevision;
            setMemoSaveStatus('저장 중...', 'idle');
            memoSaveChain = memoSaveChain.then(async () => {
                try {
                    const result = await fetchJSON('/api/memo', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ memo, instance_id: instanceId }),
                    });
                    if (
                        !result
                        || result.success !== true
                        || typeof result.instance_id !== 'string'
                    ) {
                        console.error('[MEMO] 저장 응답 형식 오류:', result);
                        throw new Error((result && result.error) || '메모 저장 응답이 올바르지 않습니다.');
                    }
                    memoServerInstanceId = result.instance_id;
                    if (textarea.value === memo) {
                        memoDirty = false;
                    }
                    if (revision === memoSaveRevision) {
                        setMemoSaveStatus('자동 저장됨', 'saved');
                    }
                } catch (error) {
                    if (String(error && error.message || error).startsWith('HTTP 409')) {
                        try {
                            const reset = await fetchJSON('/api/memo');
                            if (
                                !reset
                                || reset.success !== true
                                || typeof reset.memo !== 'string'
                                || typeof reset.instance_id !== 'string'
                                || !reset.instance_id
                            ) {
                                console.error('[MEMO] 재시작 후 초기화 응답 형식 오류:', reset);
                                throw new Error('초기화된 메모 응답이 올바르지 않습니다.');
                            }
                            textarea.value = reset.memo;
                            memoServerInstanceId = reset.instance_id;
                            memoDirty = false;
                            setMemoSaveStatus('서버 재시작으로 초기화됨', 'saved');
                            return;
                        } catch (resetError) {
                            console.error('[MEMO] 서버 재시작 후 메모 초기화 동기화 실패:', resetError);
                        }
                    }
                    console.error('[MEMO] 서버 메모 저장 실패:', error, {
                        length: memo.length,
                    });
                    if (revision === memoSaveRevision) {
                        setMemoSaveStatus('저장 실패', 'error');
                    }
                }
            });
            return memoSaveChain;
        }

        function queueMemoSave() {
            if (!memoFeatureEnabled) {
                console.error('[MEMO] 비활성 상태에서 메모 저장이 요청되었습니다.');
                return;
            }
            memoDirty = true;
            setMemoSaveStatus('저장 대기...', 'idle');
            if (memoSaveTimer !== null) {
                clearTimeout(memoSaveTimer);
            }
            memoSaveTimer = window.setTimeout(() => {
                memoSaveTimer = null;
                void saveMemoToServer();
            }, 300);
        }

        async function openMemoPad() {
            if (!memoFeatureEnabled) {
                console.error('[MEMO] 비활성 상태에서 메모장 열기를 요청했습니다.');
                return;
            }
            const overlay = document.getElementById('memo-overlay');
            const launcher = document.getElementById('memo-launcher');
            if (!overlay || !launcher) {
                console.error('[MEMO] 메모장 열기 UI 요소 누락:', {
                    overlay: !!overlay,
                    launcher: !!launcher,
                });
                return;
            }
            overlay.hidden = false;
            launcher.setAttribute('aria-expanded', 'true');
            launcher.title = '메모장 접기';
            const action = document.getElementById('memo-launcher-action');
            if (action) {
                action.textContent = '‹';
            } else {
                console.error('[MEMO] 메모장 버튼 상태 라벨이 없습니다.');
            }

            const loaded = await loadMemoFromServer();
            if (overlay.hidden) return;
            const textarea = document.getElementById('memo-textarea');
            const knowledgeInput = document.getElementById('memo-knowledge-query');
            if (memoActiveTab === 'search' && knowledgeInput) {
                knowledgeInput.focus();
            } else if (memoActiveTab === 'note' && textarea) {
                textarea.focus();
                if (loaded) {
                    textarea.setSelectionRange(textarea.value.length, textarea.value.length);
                }
            } else {
                console.error('[MEMO] 활성 탭의 포커스 대상을 찾지 못했습니다:', {
                    memoActiveTab,
                    textarea: !!textarea,
                    knowledgeInput: !!knowledgeInput,
                });
            }
        }

        function closeMemoPad(restoreFocus = true) {
            const overlay = document.getElementById('memo-overlay');
            const launcher = document.getElementById('memo-launcher');
            if (!overlay || !launcher) {
                console.error('[MEMO] 메모장 닫기 UI 요소 누락:', {
                    overlay: !!overlay,
                    launcher: !!launcher,
                });
                return;
            }
            overlay.hidden = true;
            launcher.setAttribute('aria-expanded', 'false');
            launcher.title = '메모장 펼치기';
            const action = document.getElementById('memo-launcher-action');
            if (action) {
                action.textContent = '›';
            } else {
                console.error('[MEMO] 메모장 버튼 상태 라벨이 없습니다.');
            }
            if (memoDirty) {
                void saveMemoToServer();
            }
            if (restoreFocus && !launcher.hidden) {
                launcher.focus();
            }
        }

        function toggleMemoPad() {
            const overlay = document.getElementById('memo-overlay');
            if (!overlay) {
                console.error('[MEMO] 토글할 메모장 overlay가 없습니다.');
                return;
            }
            if (overlay.hidden) {
                void openMemoPad();
            } else {
                closeMemoPad();
            }
        }

        function flushMemoWithBeacon() {
            if (!memoDirty) return;
            const textarea = document.getElementById('memo-textarea');
            if (!textarea) {
                console.error('[MEMO] 종료 직전 저장할 textarea가 없습니다.');
                return;
            }
            if (!memoServerInstanceId) {
                console.error('[MEMO] 종료 직전 저장에 필요한 서버 실행 식별자가 없습니다.');
                return;
            }
            if (memoSaveTimer !== null) {
                clearTimeout(memoSaveTimer);
                memoSaveTimer = null;
            }
            const payload = new Blob(
                [JSON.stringify({
                    memo: textarea.value,
                    instance_id: memoServerInstanceId,
                })],
                { type: 'application/json' }
            );
            if (!navigator.sendBeacon('/api/memo', payload)) {
                console.error('[MEMO] 종료 직전 sendBeacon 저장 요청 실패:', {
                    length: textarea.value.length,
                });
            }
        }

        function initializeMemoPadUi() {
            const textarea = document.getElementById('memo-textarea');
            const queueContainer = document.getElementById('asset-queue-container');
            const knowledgeInput = document.getElementById('memo-knowledge-query');
            const knowledgeSubmit = document.getElementById('memo-knowledge-submit');
            if (!textarea || !queueContainer || !knowledgeInput || !knowledgeSubmit) {
                console.error('[MEMO] 초기화 UI 요소 누락:', {
                    textarea: !!textarea,
                    queueContainer: !!queueContainer,
                    knowledgeInput: !!knowledgeInput,
                    knowledgeSubmit: !!knowledgeSubmit,
                });
                return;
            }
            textarea.addEventListener('input', queueMemoSave);
            switchMemoTab(memoActiveTab, false);
            window.addEventListener('resize', scheduleMemoLauncherPositionSync);
            window.addEventListener('beforeunload', flushMemoWithBeacon);

            memoLastQueueVisible = getComputedStyle(queueContainer).display !== 'none';
            memoLastQueueCollapsed = queueContainer.classList.contains('collapsed');
            memoQueueMutationObserver = new MutationObserver(handleMemoQueueLayoutMutation);
            memoQueueMutationObserver.observe(queueContainer, {
                attributes: true,
                attributeFilter: ['class', 'style'],
            });
            if (typeof ResizeObserver === 'function') {
                memoQueueResizeObserver = new ResizeObserver(scheduleMemoLauncherPositionSync);
                memoQueueResizeObserver.observe(queueContainer);
            } else {
                console.error('[MEMO] ResizeObserver를 지원하지 않아 큐 높이 자동 추적을 생략합니다.');
            }
            scheduleMemoLauncherPositionSync();
        }

        // ─── VAST GPU: 좌측 위젯 + 오퍼 검색·빌드 마법사 + LoRA 선택 ───
        let vastWorkerFeatureEnabled = false;
        let vastWorkerExpanded = false;
        let vastWorkerPollTimer = null;
        let vastWorkerPollBusy = false;
        let vastWorkerPollPending = false;
        let vastWorkerActiveRefreshSeconds = 5;
        let vastWorkerHasSnapshot = false;
        // 빌드 마법사 상태
        let vastOffers = [];
        let vastSelectedOfferId = null;
        let vastSelectedOffer = null;
        let vastWorkflowCatalog = [];
        let vastSelectedWorkflowPaths = new Set();
        let vastPlan = null;
        let vastLaunchPollTimer = null;
        let vastLastLaunchErrorToast = '';
        // LoRA 선택 상태
        let vastLoraCatalog = [];
        let vastLoraCatalogLoading = false;
        let vastLoraActiveCategory = 'bot';
        let vastLoraSelectedKeys = new Set();
        let vastLoraItemsByKey = new Map();

        function vastWorkerUiElements() {
            const elements = {
                widget: document.getElementById('vast-worker-widget'),
                heading: document.getElementById('vast-worker-heading'),
                state: document.getElementById('vast-worker-state'),
                credit: document.getElementById('vast-worker-credit'),
                instance: document.getElementById('vast-worker-instance'),
                stateShort: document.getElementById('vast-worker-state-short'),
                checked: document.getElementById('vast-worker-checked'),
                wallTab: document.getElementById('vast-worker-wall-tab'),
                refreshButton: document.querySelector('.vast-worker-refresh-btn'),
                panel: document.getElementById('vast-worker-panel'),
                collapseButton: document.getElementById('vast-worker-collapse-btn'),
            };
            const missing = Object.entries(elements).filter(([, v]) => !v).map(([k]) => k);
            if (missing.length) {
                console.error('[VAST_WORKER] 상태 표시 UI 요소 누락:', { missing });
                return null;
            }
            return elements;
        }

        function setVastWorkerPanelExpanded(expanded) {
            vastWorkerExpanded = Boolean(expanded);
            const e = vastWorkerUiElements();
            if (!e) return;
            e.panel.hidden = !vastWorkerExpanded;
            e.panel.inert = !vastWorkerExpanded;
            e.panel.setAttribute('aria-hidden', String(!vastWorkerExpanded));
            e.wallTab.hidden = vastWorkerExpanded;
            e.wallTab.inert = vastWorkerExpanded;
            e.wallTab.setAttribute('aria-hidden', String(vastWorkerExpanded));
            e.wallTab.setAttribute('aria-expanded', String(vastWorkerExpanded));
            e.wallTab.tabIndex = vastWorkerExpanded ? -1 : 0;
        }

        function collapseVastWorkerPanel() {
            const e = vastWorkerUiElements();
            if (!e) return;
            setVastWorkerPanelExpanded(false);
            e.wallTab.focus();
        }

        function expandVastWorkerPanel() {
            const e = vastWorkerUiElements();
            if (!e) return;
            setVastWorkerPanelExpanded(true);
            e.collapseButton.focus();
        }

        function stopVastWorkerPolling() {
            if (vastWorkerPollTimer !== null) {
                window.clearTimeout(vastWorkerPollTimer);
                vastWorkerPollTimer = null;
            }
        }

        function scheduleVastWorkerPolling() {
            stopVastWorkerPolling();
            if (!vastWorkerFeatureEnabled || document.hidden) return;
            vastWorkerPollTimer = window.setTimeout(
                () => void refreshVastStatus(false),
                vastWorkerActiveRefreshSeconds * 1000,
            );
        }

        function renderVastWorkerStatus(status) {
            const e = vastWorkerUiElements();
            if (!e) return;
            const settings = status?.settings || {};
            const account = status?.account || {};
            const launch = status?.launch || {};
            // API 키 / 계정
            const hasKey = Boolean(settings.has_api_key);
            const accountOk = account.ok === true;
            if (!hasKey) {
                e.widget.dataset.state = 'error';
                e.heading.textContent = 'VAST GPU';
                e.state.textContent = 'API 키 없음';
                e.state.title = 'key/vast_key.json 에 API 키를 설정하세요.';
                e.credit.textContent = '-';
                e.instance.textContent = '-';
                e.stateShort.textContent = '키없음';
                e.checked.textContent = 'API 키 미설정 · 설정에서 vast_enabled 활성화 필요';
                return;
            }
            if (!accountOk) {
                e.widget.dataset.state = 'error';
                e.heading.textContent = 'VAST GPU';
                e.state.textContent = '계정 확인 실패';
                e.state.title = String(account.error || 'Vast 계정 조회 실패');
                e.credit.textContent = '-';
                e.instance.textContent = '-';
                e.stateShort.textContent = '오류';
                e.checked.textContent = String(account.error || '계정 조회 실패');
                e.checked.title = String(account.error || '');
                return;
            }
            const credit = Number(account.balance_usd || 0);
            const launchState = String(launch.state || 'idle');
            const instanceId = launch.instance_id;
            const refreshSeconds = Number(settings.status_refresh_seconds);
            if (Number.isInteger(refreshSeconds) && refreshSeconds >= 2 && refreshSeconds <= 60) {
                vastWorkerActiveRefreshSeconds = refreshSeconds;
            }
            let widgetState = 'off';
            if (launchState === 'creating' || launchState === 'preparing' || launchState === 'destroying' || launchState === 'recovered') widgetState = 'checking';
            else if (launchState === 'ready') widgetState = 'on';
            else if (launchState === 'error' || launchState === 'destroy_failed') widgetState = 'error';
            e.widget.dataset.state = widgetState;
            e.heading.textContent = 'VAST GPU';
            const stateLabel = ({
                idle: '빌드 대기',
                creating: '인스턴스 생성 중',
                preparing: '준비 중',
                ready: 'ComfyUI 준비 완료',
                error: '빌드 오류',
                destroyed: '파괴됨',
                destroying: '파괴 확인 중',
                destroy_failed: '파괴 확인 실패',
                recovered: '재시작 감시 복구',
            })[launchState] || launchState;
            e.state.textContent = stateLabel;
            e.state.title = launch.error ? String(launch.error) : stateLabel;
            e.credit.textContent = `$${credit.toFixed(2)}`;
            e.credit.title = `Vast credit 잔액: $${credit.toFixed(2)}`;
            e.instance.textContent = instanceId ? `#${instanceId}` : '-';
            e.stateShort.textContent = ({
                idle: '대기', creating: '생성', preparing: '준비', ready: 'ON', error: '오류', destroyed: '파괴',
                destroying: '파괴중', destroy_failed: '확인실패', recovered: '복구',
            })[launchState] || '-';
            const nextSeconds = vastWorkerActiveRefreshSeconds;
            e.checked.textContent = `credit $${credit.toFixed(2)} · ${stateLabel} · ${nextSeconds}초 주기`;
            // 메인 패널 metrics 동기화
            const acc = document.getElementById('vast-runtime-account');
            const cred = document.getElementById('vast-runtime-credit');
            const key = document.getElementById('vast-runtime-key');
            const ins = document.getElementById('vast-runtime-instance');
            const st = document.getElementById('vast-runtime-state');
            if (acc) acc.textContent = account.username ? String(account.username) : '(계정)';
            if (cred) cred.textContent = `$${credit.toFixed(2)}`;
            if (key) key.textContent = hasKey ? '설정됨' : '없음';
            if (ins) ins.textContent = instanceId ? `#${instanceId} ${stateLabel}` : '없음';
            if (st) st.textContent = `● ${stateLabel}`;
        }

        function renderVastWorkerError(message) {
            const e = vastWorkerUiElements();
            if (!e) return;
            e.widget.dataset.state = 'error';
            e.state.textContent = '상태 조회 실패';
            e.state.title = String(message || 'Vast 상태 조회 실패');
            e.credit.textContent = '-';
            e.instance.textContent = '-';
            e.stateShort.textContent = '오류';
            const retry = Math.round(vastWorkerActiveRefreshSeconds);
            e.checked.textContent = `${String(message || '조회 실패')} · ${retry}초 후 재시도`;
            e.checked.title = String(message || '');
        }

        async function refreshVastStatus(manual = false) {
            if (!vastWorkerFeatureEnabled) {
                if (manual) console.error('[VAST_WORKER] VAST OFF 상태에서 수동 조회를 요청했습니다.');
                return;
            }
            if (document.hidden && !manual) { stopVastWorkerPolling(); return; }
            if (vastWorkerPollBusy) { vastWorkerPollPending = true; return; }
            stopVastWorkerPolling();
            vastWorkerPollBusy = true;
            const e = vastWorkerUiElements();
            if (e) {
                e.refreshButton.disabled = true;
                e.checked.textContent = '상태 확인 중…';
                if (!vastWorkerHasSnapshot) {
                    e.widget.dataset.state = 'checking';
                    e.state.textContent = '상태 확인 중';
                }
            }
            try {
                const data = await fetchJSON('/api/vast/status');
                if (data?.settings?.enabled === false) {
                    applyVastConfig({vast_enabled: false});
                    return;
                }
                vastWorkerHasSnapshot = true;
                renderVastWorkerStatus(data);
            } catch (error) {
                console.error('[VAST_WORKER] 상태 조회 실패:', error);
                vastWorkerHasSnapshot = true;
                renderVastWorkerError(error?.message || String(error));
            } finally {
                vastWorkerPollBusy = false;
                const latest = vastWorkerUiElements();
                if (latest) latest.refreshButton.disabled = false;
                if (vastWorkerPollPending && vastWorkerFeatureEnabled && !document.hidden) {
                    vastWorkerPollPending = false;
                    window.setTimeout(() => void refreshVastStatus(false), 0);
                } else {
                    vastWorkerPollPending = false;
                    scheduleVastWorkerPolling();
                }
            }
        }

        function applyVastConfig(config) {
            if (!config || typeof config !== 'object') {
                console.error('[VAST_WORKER] 기능 설정 형식 오류:', config);
                return;
            }
            const widget = document.getElementById('vast-worker-widget');
            if (!widget) {
                console.error('[VAST_WORKER] 기능 상태를 적용할 위젯이 없습니다.', config);
                return;
            }
            vastWorkerFeatureEnabled = config.vast_enabled === true;
            widget.hidden = !vastWorkerFeatureEnabled;
            if (!vastWorkerFeatureEnabled) {
                stopVastWorkerPolling();
                stopVastLaunchPolling();
                vastWorkerPollPending = false;
            }
            syncLeftUtilityStackVisibility();
            if (vastWorkerFeatureEnabled) void refreshVastStatus(false);
        }

        function initializeVastWorkerUi() {
            const e = vastWorkerUiElements();
            if (!e) return;
            setVastWorkerPanelExpanded(vastWorkerExpanded);
            document.addEventListener('visibilitychange', () => {
                if (!vastWorkerFeatureEnabled) return;
                if (document.hidden) stopVastWorkerPolling();
                else void refreshVastStatus(false);
            });
            syncLeftUtilityStackVisibility();
        }

        function openVastTab() {
            try { openSettingsModal(); } catch (e) { console.error('[VAST] openSettingsModal 실패:', e); }
            try { switchSettingsTab('comfy_runtime'); } catch (e) { console.error('[VAST] switchSettingsTab 실패:', e); }
            switchComfyRuntimeVast();
        }

        // ── 탭 전환 ──
        function switchComfyVastSection(section) {
            const sections = ['build', 'lora'];
            if (!sections.includes(section)) {
                console.warn('[VAST] 알 수 없는 내부 섹션:', section);
                return;
            }
            for (const key of sections) {
                const tab = document.getElementById(`comfy-vast-section-tab-${key}`);
                const panel = document.getElementById(`comfy-vast-panel-${key}`);
                if (!tab || !panel) continue;
                tab.classList.toggle('active', key === section);
                tab.setAttribute('aria-selected', key === section ? 'true' : 'false');
                panel.classList.toggle('active', key === section);
            }
            if (section === 'lora' && !vastLoraCatalog.length) vastLoraLoadCatalog();
        }

        function deactivateVastTab() {
            const vastTab = document.getElementById('comfy-runtime-tab-vast');
            vastTab?.classList.remove('active');
            vastTab?.setAttribute('aria-selected', 'false');
            document.getElementById('comfy-vast-panel')?.classList.remove('active');
            document.getElementById('comfy-vast-panel')?.setAttribute('hidden', '');
            stopVastLaunchPolling();
        }

        function switchComfyRuntimeVast() {
            deactivateVideoEngineTab();
            try { comfyRuntimeCaptureActiveProfile(); } catch (e) { /* capture는 best-effort */ }
            comfyRuntimeActiveView = 'vast';
            for (const id of [1, 2, 3]) {
                const tab = document.getElementById(`comfy-runtime-tab-${id}`);
                tab?.classList.remove('active');
                tab?.setAttribute('aria-selected', 'false');
            }
            const allocationTab = document.getElementById('comfy-runtime-tab-allocation');
            allocationTab?.classList.remove('active');
            allocationTab?.setAttribute('aria-selected', 'false');
            const modalTab = document.getElementById('comfy-runtime-tab-modal');
            modalTab?.classList.remove('active');
            modalTab?.setAttribute('aria-selected', 'false');
            const vastTab = document.getElementById('comfy-runtime-tab-vast');
            vastTab?.classList.add('active');
            vastTab?.setAttribute('aria-selected', 'true');
            const instancePanel = document.getElementById('comfy-runtime-instance-panel');
            if (instancePanel) instancePanel.style.display = 'none';
            document.getElementById('comfy-runtime-allocation-panel')?.classList.remove('active');
            document.getElementById('comfy-modal-runtime-panel')?.classList.remove('active');
            const vastPanel = document.getElementById('comfy-vast-panel');
            if (vastPanel) { vastPanel.classList.add('active'); vastPanel.removeAttribute('hidden'); }
            try { comfyRuntimeStopPolling(); } catch (e) { /* best-effort */ }
            try { modalRuntimeStopPolling(); } catch (e) { /* best-effort */ }
            void refreshVastStatus(true);
            if (!vastOffers.length) vastSearchOffers();
            if (!vastWorkflowCatalog.length) vastLoadWorkflows();
            vastLoadInstances();
            vastRefreshLaunchPolling();
        }

        // 빌드 디스크 입력 변경 시 저장 요금 예상을 즉시 다시 계산한다.
        document.getElementById('vast-build-disk')?.addEventListener('input', () => vastUpdateLaunchSummary());

        // ── 오퍼 검색 ──
        function vastSelectedGpuNames() {
            const boxes = document.querySelectorAll('#vast-search-gpus input[type="checkbox"]');
            const names = [];
            boxes.forEach(b => { if (b.checked) names.push(b.value); });
            return names;
        }

        async function vastSearchOffers() {
            const btn = document.getElementById('vast-search-btn');
            const container = document.getElementById('vast-offer-catalog');
            const summary = document.getElementById('vast-offer-summary');
            if (btn) btn.disabled = true;
            if (container) container.innerHTML = '<div class="modal-lora-empty">오퍼를 검색하는 중입니다.</div>';
            const gpuNames = vastSelectedGpuNames();
            if (!gpuNames.length) {
                if (container) container.innerHTML = '<div class="modal-lora-empty">최소 한 개의 GPU를 선택하세요.</div>';
                if (btn) btn.disabled = false;
                return;
            }
            const params = new URLSearchParams();
            params.set('gpu_names', gpuNames.join(','));
            const price = parseFloat(document.getElementById('vast-search-price')?.value || '');
            if (Number.isFinite(price) && price > 0) params.set('max_price_usd_hr', String(price));
            const ram = parseInt(document.getElementById('vast-search-ram')?.value || '', 10);
            if (Number.isFinite(ram) && ram > 0) params.set('min_cpu_ram_gb', String(ram));
            const gpuram = parseInt(document.getElementById('vast-search-gpuram')?.value || '', 10);
            if (Number.isFinite(gpuram) && gpuram > 0) params.set('min_gpu_ram_gb', String(gpuram));
            const disk = parseInt(document.getElementById('vast-search-disk')?.value || '', 10);
            if (Number.isFinite(disk) && disk > 0) params.set('min_disk_gb', String(disk));
            const inetdown = parseInt(document.getElementById('vast-search-inetdown')?.value || '', 10);
            if (Number.isFinite(inetdown) && inetdown > 0) params.set('inet_down_min_mbps', String(inetdown));
            const inetup = parseFloat(document.getElementById('vast-search-inetup')?.value || '');
            if (Number.isFinite(inetup) && inetup > 0) params.set('inet_up_min_mbps', String(inetup));
            const reliability = parseFloat(document.getElementById('vast-search-reliability')?.value || '');
            if (Number.isFinite(reliability) && reliability > 0) params.set('min_reliability', String(reliability));
            const cuda = parseFloat(document.getElementById('vast-search-cuda')?.value || '');
            if (Number.isFinite(cuda) && cuda > 0) params.set('min_cuda_version', String(cuda));
            const limit = parseInt(document.getElementById('vast-search-limit')?.value || '', 10);
            if (Number.isFinite(limit) && limit > 0) params.set('limit', String(limit));
            if (document.getElementById('vast-search-verified')?.checked) params.set('verified_only', '1');
            if (document.getElementById('vast-search-ondemand')?.checked) params.set('on_demand', '1');
            try {
                const data = await fetchJSON(`/api/vast/offers?${params.toString()}`);
                vastOffers = Array.isArray(data.offers) ? data.offers : [];
                vastRenderOffers();
                if (summary) {
                    summary.hidden = false;
                    summary.textContent = `검색 완료: ${vastOffers.length}개 오퍼 (가격 오름차순)`;
                }
            } catch (error) {
                console.error('[VAST] 오퍼 검색 실패:', error);
                vastOffers = [];
                if (container) container.innerHTML = `<div class="modal-lora-empty">오퍼 검색 실패: ${escapeHtml(String(error.message || error))}</div>`;
                if (summary) { summary.hidden = false; summary.textContent = '검색 실패: ' + (error.message || error); }
                showToast('VAST 오퍼 검색 실패: ' + (error.message || error), 'error');
            } finally {
                if (btn) btn.disabled = false;
            }
        }

        function vastRenderOffers() {
            const container = document.getElementById('vast-offer-catalog');
            if (!container) return;
            container.replaceChildren();
            if (!vastOffers.length) {
                const empty = document.createElement('div');
                empty.className = 'modal-lora-empty';
                empty.textContent = '조건에 맞는 오퍼가 없습니다. 검색 조건을 완화하세요.';
                container.append(empty);
                return;
            }
            for (const o of vastOffers) {
                const row = document.createElement('div');
                row.className = 'vast-offer-row';
                if (vastSelectedOfferId !== null && Number(o.id) === Number(vastSelectedOfferId)) row.classList.add('selected');
                const radio = document.createElement('input');
                radio.type = 'radio';
                radio.name = 'vast-offer';
                radio.value = String(o.id);
                radio.checked = (vastSelectedOfferId !== null && Number(o.id) === Number(vastSelectedOfferId));
                radio.setAttribute('aria-label', `${o.gpu_name} 오퍼 선택`);
                radio.addEventListener('change', () => vastSelectOffer(o));
                const main = document.createElement('div');
                main.className = 'vast-offer-main';
                const strong = document.createElement('strong');
                strong.textContent = `${o.favorite ? '★ ' : ''}${o.gpu_name || 'GPU'}${o.num_gpus && o.num_gpus > 1 ? ` ×${o.num_gpus}` : ''}`;
                main.append(strong);
                const meta = document.createElement('div');
                meta.className = 'vast-offer-meta';
                const metaItems = [
                    o.machine_id ? `머신 #${o.machine_id}` : null,
                    o.favorite ? '즐겨찾기 우선' : null,
                    o.verified ? 'verified' : 'unverified',
                    `VRAM ${o.gpu_ram_gb || 0}GB`,
                    `RAM ${o.cpu_ram_gb || 0}GB`,
                    `디스크 ${o.disk_name ? `${o.disk_name} ` : ''}${o.disk_gb || 0}GB${o.disk_bw_mb_s ? ` · ${o.disk_bw_mb_s}MB/s` : ''}`,
                    o.inet_down_mbps ? `↓${Math.round(o.inet_down_mbps)}Mbps` : null,
                    o.inet_up_mbps ? `↑${Math.round(o.inet_up_mbps)}Mbps` : null,
                    o.storage_cost_usd_per_gb_month ? `저장 $${Number(o.storage_cost_usd_per_gb_month).toFixed(2)}/GB·월` : null,
                    (o.inet_cost_usd_per_tb_down || o.inet_cost_usd_per_tb_up)
                        ? (o.inet_cost_usd_per_tb_down === o.inet_cost_usd_per_tb_up
                            ? `대역폭 $${Number(o.inet_cost_usd_per_tb_down || 0).toFixed(1)}/TB`
                            : `대역폭 ↓$${Number(o.inet_cost_usd_per_tb_down || 0).toFixed(1)}/TB ↑$${Number(o.inet_cost_usd_per_tb_up || 0).toFixed(1)}/TB`)
                        : null,
                    o.reliability ? `신뢰도 ${(Number(o.reliability) * 100).toFixed(0)}%` : null,
                    o.cuda_max_good ? `CUDA ${o.cuda_max_good}` : null,
                    o.geolocation ? String(o.geolocation) : null,
                ].filter(Boolean);
                metaItems.forEach(t => {
                    const s = document.createElement('span');
                    s.textContent = t;
                    meta.append(s);
                });
                main.append(meta);
                const price = document.createElement('div');
                price.className = 'vast-offer-price';
                price.innerHTML = `$${Number(o.dph_total || 0).toFixed(3)}<small>/시간</small>`;
                price.title = `GPU $${Number(o.dph_base || 0).toFixed(4)}/hr + Vast 기본 디스크 할당 저장료 포함. 빌드 디스크를 크게 잡으면 저장료가 추가됩니다.`;
                row.append(radio, main, price);
                container.append(row);
            }
        }

        function vastSelectOffer(offer) {
            vastSelectedOfferId = Number(offer.id);
            vastSelectedOffer = offer;
            vastRenderOffers();
            vastUpdateLaunchSummary();
        }

        // ── 워크플로우 선택 ──
        async function vastLoadWorkflows() {
            const container = document.getElementById('vast-workflow-catalog');
            if (container) container.innerHTML = '<div class="comfy-workflow-empty">워크플로우 목록을 불러오는 중입니다.</div>';
            try {
                const data = await fetchJSON('/api/workflow_files');
                vastWorkflowCatalog = Array.isArray(data.files) ? data.files : [];
                vastFilterWorkflows();
            } catch (error) {
                console.error('[VAST] 워크플로우 목록 조회 실패:', error);
                vastWorkflowCatalog = [];
                if (container) container.innerHTML = `<div class="comfy-workflow-empty">워크플로우 목록 조회 실패: ${escapeHtml(String(error.message || error))}</div>`;
            }
        }

        function vastFilterWorkflows() {
            const container = document.getElementById('vast-workflow-catalog');
            if (!container) return;
            const q = (document.getElementById('vast-workflow-search')?.value || '').toLowerCase();
            const items = vastWorkflowCatalog.filter(f => {
                if (!q) return true;
                return (f.filename || '').toLowerCase().includes(q) || (f.rel_path || '').toLowerCase().includes(q);
            });
            container.replaceChildren();
            if (!items.length) {
                const empty = document.createElement('div');
                empty.className = 'comfy-workflow-empty';
                empty.textContent = vastWorkflowCatalog.length ? '검색 결과 없음' : '워크플로우가 없습니다.';
                container.append(empty);
                return;
            }
            for (const f of items) {
                const label = document.createElement('label');
                label.style.cssText = 'display:flex; align-items:center; gap:8px; padding:6px 8px; border-bottom:1px solid var(--border); cursor:pointer; font-size:0.8rem;';
                const cb = document.createElement('input');
                cb.type = 'checkbox';
                cb.value = f.path;
                cb.checked = vastSelectedWorkflowPaths.has(f.path);
                cb.addEventListener('change', () => {
                    if (cb.checked) vastSelectedWorkflowPaths.add(f.path);
                    else vastSelectedWorkflowPaths.delete(f.path);
                    void vastRunPlan();
                });
                const span = document.createElement('span');
                span.style.cssText = 'min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;';
                span.textContent = f.rel_path || f.filename;
                span.title = f.path;
                label.append(cb, span);
                container.append(label);
            }
        }

        async function vastRunPlan() {
            const planBox = document.getElementById('vast-plan-box');
            const totals = document.getElementById('vast-plan-totals');
            const modelsEl = document.getElementById('vast-plan-models');
            const diskInput = document.getElementById('vast-build-disk');
            const workflows = Array.from(vastSelectedWorkflowPaths).map(p => {
                const f = vastWorkflowCatalog.find(x => x.path === p);
                return { path: p, name: f ? f.filename : '' };
            });
            if (!workflows.length) {
                if (planBox) planBox.hidden = true;
                vastPlan = null;
                vastUpdateLaunchSummary();
                return;
            }
            if (planBox) planBox.hidden = false;
            if (totals) totals.textContent = '계획 계산 중…';
            if (modelsEl) modelsEl.innerHTML = '';
            try {
                const data = await fetchJSON('/api/vast/plan', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ workflows, lora_item_keys: Array.from(vastLoraSelectedKeys) }),
                });
                vastPlan = data;
                const t = data.totals || {};
                if (totals) {
                    totals.textContent = `다운로드 ${(t.download_gb || 0).toFixed(2)}GB · 업로드 ${(t.upload_gb || 0).toFixed(2)}GB · LoRA ${(t.lora_upload_gb || 0).toFixed(2)}GB · 권장 디스크 ${t.recommended_disk_gb || 0}GB`;
                }
                if (modelsEl) {
                    modelsEl.replaceChildren();
                    const models = Array.isArray(data.models) ? data.models : [];
                    if (!models.length) {
                        const empty = document.createElement('div');
                        empty.className = 'vast-plan-model';
                        empty.textContent = '추가 다운로드/업로드 모델 없음';
                        modelsEl.append(empty);
                    } else {
                        for (const m of models) {
                            const div = document.createElement('div');
                            div.className = 'vast-plan-model';
                            const src = m.source || {};
                            const kind = document.createElement('strong');
                            kind.textContent = `${m.kind || ''} · ${m.filename || ''}`;
                            const meta = document.createElement('span');
                            meta.textContent = `${src.source_type || '?'} · ${comfyInstallerFormatBytes(Number(m.size_bytes || 0))}`;
                            div.append(kind, meta);
                            modelsEl.append(div);
                        }
                    }
                }
                if (diskInput && t.recommended_disk_gb) diskInput.value = String(t.recommended_disk_gb);
            } catch (error) {
                console.error('[VAST] 준비 계획 조회 실패:', error);
                if (totals) totals.textContent = '계획 조회 실패: ' + (error.message || error);
                showToast('VAST 준비 계획 조회 실패: ' + (error.message || error), 'error');
            } finally {
                vastUpdateLaunchSummary();
            }
        }

        // ── LoRA 선택 ──
        async function vastLoraLoadCatalog() {
            const note = document.getElementById('vast-lora-note');
            vastLoraCatalogLoading = true;
            vastLoraCatalog = [];
            vastLoraItemsByKey = new Map();
            if (note) note.textContent = '로컬 현재 사용본을 불러오는 중입니다.';
            vastRenderLoraCatalog();
            let loaded = false;
            try {
                const data = await fetchJSON('/api/modal/loras');
                vastLoraCatalog = Array.isArray(data.items) ? data.items : [];
                for (const item of vastLoraCatalog) {
                    if (item && item.key) vastLoraItemsByKey.set(String(item.key), item);
                }
                // 선택했던 키 중 카탈로그에 없는 것 정리
                for (const key of Array.from(vastLoraSelectedKeys)) {
                    if (!vastLoraItemsByKey.has(String(key))) vastLoraSelectedKeys.delete(key);
                }
                if (note) note.textContent = `현재 사용본 ${vastLoraCatalog.length}개 항목 · 빌드에 포함할 LoRA를 선택하세요.`;
                loaded = true;
            } catch (error) {
                console.error('[VAST] LoRA 카탈로그 조회 실패:', error);
                if (note) note.textContent = 'LoRA 목록 조회 실패: ' + (error.message || error);
                const container = document.getElementById('vast-lora-catalog');
                if (container) container.innerHTML = `<div class="modal-lora-empty">LoRA 목록을 불러오지 못했습니다: ${escapeHtml(String(error.message || error))}</div>`;
            } finally {
                vastLoraCatalogLoading = false;
                vastUpdateLoraTabCounts();
                vastRenderLoraCatalog();
            }
        }

        function vastUpdateLoraTabCounts() {
            for (const cat of ['bot', 'asset', 'instance', 'style']) {
                const el = document.getElementById(`vast-lora-tab-count-${cat}`);
                if (el) el.textContent = String(vastLoraCatalog.filter(i => String(i.category) === cat).length);
            }
        }

        function vastLoraVisibleItems() {
            const q = (document.getElementById('vast-lora-search')?.value || '').toLowerCase().trim();
            return vastLoraCatalog.filter(item => {
                if (String(item.category) !== vastLoraActiveCategory) return false;
                if (!q) return true;
                return [item.display_name, item.display_subtitle, item.name, item.subtitle, item.detail]
                    .filter(Boolean).some(t => String(t).toLowerCase().includes(q));
            });
        }

        function vastRenderLoraCatalog() {
            const container = document.getElementById('vast-lora-catalog');
            if (!container) return;
            const visible = vastLoraVisibleItems();
            container.replaceChildren();
            if (!visible.length) {
                const empty = document.createElement('div');
                empty.className = 'modal-lora-empty';
                empty.textContent = vastLoraCatalogLoading
                    ? '로컬 현재 사용본을 불러오는 중입니다.'
                    : (vastLoraCatalog.length
                        ? '현재 탭·검색 조건에 맞는 LoRA가 없습니다.'
                        : '현재 사용할 수 있는 LoRA가 없습니다.');
                container.append(empty);
                vastUpdateLoraSelectionSummary();
                return;
            }
            for (const item of visible) {
                const row = document.createElement('div');
                row.className = 'modal-lora-item';
                if (vastLoraSelectedKeys.has(String(item.key))) row.classList.add('selected');
                const checkbox = document.createElement('input');
                checkbox.type = 'checkbox';
                checkbox.className = 'modal-lora-check';
                checkbox.checked = vastLoraSelectedKeys.has(String(item.key));
                const displayName = item.display_name || item.name || '이름 없음';
                checkbox.setAttribute('aria-label', `${displayName} 선택`);
                checkbox.addEventListener('change', () => {
                    if (checkbox.checked) vastLoraSelectedKeys.add(String(item.key));
                    else vastLoraSelectedKeys.delete(String(item.key));
                    vastRenderLoraCatalog();
                });
                const copy = document.createElement('div');
                copy.className = 'modal-lora-item-copy';
                copy.addEventListener('click', event => {
                    if (event.target.closest('button,input')) return;
                    if (vastLoraSelectedKeys.has(String(item.key))) vastLoraSelectedKeys.delete(String(item.key));
                    else vastLoraSelectedKeys.add(String(item.key));
                    vastRenderLoraCatalog();
                });
                const main = document.createElement('div');
                main.className = 'modal-lora-item-main';
                const name = document.createElement('strong');
                name.textContent = displayName;
                main.append(name);
                if (item.category === 'bot') {
                    const unit = document.createElement('span');
                    unit.className = 'modal-lora-unit-badge';
                    unit.textContent = '봇 전체';
                    main.append(unit);
                }
                const detail = document.createElement('div');
                detail.className = 'modal-lora-item-meta';
                const details = [
                    item.display_subtitle || item.subtitle || '',
                    `로컬 ${Number(item.file_count || 0)}개 · ${comfyInstallerFormatBytes(Number(item.size_bytes || 0))}`,
                ].filter(Boolean);
                details.forEach(text => {
                    const s = document.createElement('span');
                    s.textContent = String(text);
                    detail.append(s);
                });
                copy.append(main, detail);
                row.append(checkbox, copy);
                container.append(row);
            }
            vastUpdateLoraSelectionSummary();
        }

        function vastLoraSetCategory(category) {
            if (!['bot', 'asset', 'instance', 'style'].includes(category)) {
                console.error('[VAST_LORA] 알 수 없는 카테고리:', category);
                return;
            }
            vastLoraActiveCategory = category;
            document.querySelectorAll('[data-vast-lora-category]').forEach(button => {
                button.classList.toggle('active', button.dataset.vastLoraCategory === category);
            });
            vastRenderLoraCatalog();
        }

        function vastLoraSelectVisible() {
            for (const item of vastLoraVisibleItems()) {
                if (item.key) vastLoraSelectedKeys.add(String(item.key));
            }
            vastRenderLoraCatalog();
        }

        function vastClearLoraSelection() {
            vastLoraSelectedKeys.clear();
            vastRenderLoraCatalog();
            vastUpdateLoraSelectionSummary();
        }

        function vastSelectedLoraStats() {
            // 공개 카탈로그는 source_path를 제공하지 않으므로 로컬 파일 목록을
            // 프론트에서 만들지 않는다. 요약 표시는 공개 필드(file_count/size_bytes)로만.
            let count = 0;
            let totalBytes = 0;
            for (const key of vastLoraSelectedKeys) {
                const item = vastLoraItemsByKey.get(String(key));
                if (!item) continue;
                count += Number(item.file_count || 0);
                totalBytes += Number(item.size_bytes || 0);
            }
            return { count, totalBytes };
        }

        function vastUpdateLoraSelectionSummary() {
            const stats = vastSelectedLoraStats();
            const note = document.getElementById('vast-lora-footer-note');
            const summary = document.getElementById('vast-lora-selection-summary');
            const text = stats.count
                ? `선택 ${stats.count}개 · ${comfyInstallerFormatBytes(stats.totalBytes)}`
                : '선택된 LoRA 없음';
            if (note) note.textContent = text;
            if (summary) summary.textContent = text;
            vastUpdateLaunchSummary();
        }

        function vastApplyLoraSelection() {
            vastUpdateLoraSelectionSummary();
            switchComfyVastSection('build');
            void vastRunPlan();
            showToast(`VAST 빌드에 LoRA ${vastLoraSelectedKeys.size}개 선택 적용`, 'success');
        }

        // ── 빌드 ──
        // Vast 저장료: storage_cost($/GB·월) ÷ 720hr/월 × 할당 GB = $/hr.
        // 오퍼 표시 dph_total은 기본 할당(약 8GB) 기준이라 실제 예상과 다르다.
        const VAST_HOURS_PER_MONTH = 720;
        function vastDiskCostPerHour(diskGb) {
            const rate = Number(vastSelectedOffer?.storage_cost_usd_per_gb_month || 0);
            if (!(rate > 0) || !(diskGb > 0)) return 0;
            return rate * diskGb / VAST_HOURS_PER_MONTH;
        }

        function vastUpdateDiskCostNote() {
            const note = document.getElementById('vast-disk-cost-note');
            if (!note) return;
            const diskGb = parseInt(document.getElementById('vast-build-disk')?.value || '0', 10);
            const rate = Number(vastSelectedOffer?.storage_cost_usd_per_gb_month || 0);
            if (!vastSelectedOffer) {
                note.textContent = '오퍼를 선택하면 디스크 저장 요금 예상이 표시됩니다.';
                return;
            }
            if (!(rate > 0)) {
                note.textContent = '이 오퍼는 저장 단가 정보가 없어 디스크 요금 예상을 계산할 수 없습니다.';
                return;
            }
            const perHour = vastDiskCostPerHour(diskGb);
            const perDay = perHour * 24;
            const down = Number(vastSelectedOffer.inet_cost_usd_per_tb_down || 0);
            const up = Number(vastSelectedOffer.inet_cost_usd_per_tb_up || 0);
            const bw = down > 0 && up > 0 && down === up
                ? `대역폭 $${down}/TB`
                : `대역폭 ↓$${down || 0}/TB · ↑$${up || 0}/TB`;
            note.textContent = `디스크 저장료 예상 +$${perHour.toFixed(4)}/hr (일 $${perDay.toFixed(3)}) · ${diskGb}GB × $${rate.toFixed(3)}/GB·월 · ${bw} (전송량 과금)`;
        }

        function vastUpdateLaunchSummary() {
            const sum = document.getElementById('vast-launch-summary');
            const btn = document.getElementById('vast-launch-btn');
            vastUpdateDiskCostNote();
            if (!sum || !btn) return;
            const parts = [];
            if (vastSelectedOffer) {
                const diskGb = parseInt(document.getElementById('vast-build-disk')?.value || '0', 10);
                const gpuRate = Number(vastSelectedOffer.dph_base || 0) || Number(vastSelectedOffer.dph_total || 0);
                const diskRate = vastDiskCostPerHour(diskGb);
                if (diskRate > 0) {
                    parts.push(`오퍼 ${vastSelectedOffer.gpu_name} GPU $${gpuRate.toFixed(4)}/hr + 디스크 $${diskRate.toFixed(4)}/hr ≈ $${(gpuRate + diskRate).toFixed(4)}/hr`);
                } else {
                    parts.push(`오퍼 ${vastSelectedOffer.gpu_name} $${Number(vastSelectedOffer.dph_total || 0).toFixed(3)}/hr`);
                }
            }
            else parts.push('오퍼 미선택');
            parts.push(vastSelectedWorkflowPaths.size ? `워크플로우 ${vastSelectedWorkflowPaths.size}개` : '워크플로우 미선택');
            parts.push(`LoRA ${vastLoraSelectedKeys.size}개`);
            sum.textContent = parts.join(' · ');
            btn.disabled = !(vastSelectedOfferId !== null && vastSelectedWorkflowPaths.size > 0);
        }

        async function vastLaunch() {
            if (vastSelectedOfferId === null) {
                showToast('오퍼를 먼저 선택하세요.', 'error');
                return;
            }
            if (!vastSelectedWorkflowPaths.size) {
                showToast('빌드할 워크플로우를 먼저 지정하세요.', 'error');
                return;
            }
            const diskGb = parseInt(document.getElementById('vast-build-disk')?.value || '0', 10);
            if (!(diskGb >= 10)) {
                showToast('빌드 디스크는 10GB 이상이어야 합니다.', 'error');
                return;
            }
            const btn = document.getElementById('vast-launch-btn');
            if (btn) btn.disabled = true;
            const workflows = Array.from(vastSelectedWorkflowPaths).map(p => {
                const f = vastWorkflowCatalog.find(x => x.path === p);
                return { path: p, name: f ? f.filename : '' };
            });
            try {
                const result = await fetchJSON('/api/vast/launch', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        ask_id: vastSelectedOfferId,
                        disk_gb: diskGb,
                        hourly_price_usd: Number(vastSelectedOffer?.dph_total || 0),
                        plan: vastPlan || {},
                        lora_item_keys: Array.from(vastLoraSelectedKeys),
                        workflows,
                    }),
                });
                if (result?.launch) vastRenderLaunchSteps(result.launch);
                showToast('VAST 인스턴스 빌드를 시작했습니다.', 'success');
                vastRefreshLaunchPolling();
            } catch (error) {
                console.error('[VAST] 빌드 시작 실패:', error);
                showToast('VAST 빌드 시작 실패: ' + (error.message || error), 'error');
            } finally {
                vastUpdateLaunchSummary();
            }
        }

        function stopVastLaunchPolling() {
            if (vastLaunchPollTimer !== null) {
                window.clearTimeout(vastLaunchPollTimer);
                vastLaunchPollTimer = null;
            }
        }

        function vastRefreshLaunchPolling() {
            stopVastLaunchPolling();
            const isActive = vastWorkerFeatureEnabled && comfyRuntimeActiveView === 'vast'
                && document.getElementById('settings-modal')?.classList.contains('visible')
                && document.getElementById('settings-tab-comfy_runtime')?.classList.contains('active')
                && document.getElementById('comfy-vast-panel')?.classList.contains('active');
            if (!isActive) return;
            void vastPollLaunch();
        }

        const VAST_LAUNCH_STEP_LABELS = {
            instance: '인스턴스 생성',
            ssh: 'SSH 접속',
            nodes: '로컬 노드 전송',
            nodes_install: '공개 노드 설치',
            upload: 'sftp 업로드',
            upload_loras: 'LoRA 업로드',
            upload_models: '모델 업로드',
            download: '원격 모델 다운로드',
            tunnel: 'SSH 로컬 터널',
            comfy: 'ComfyUI 기동',
            recovered: '재시작 복구',
        };

        function vastFormatDuration(totalSeconds) {
            const value = Math.max(0, Math.floor(Number(totalSeconds) || 0));
            const hours = Math.floor(value / 3600);
            const minutes = Math.floor((value % 3600) / 60);
            const seconds = value % 60;
            if (hours) return `${hours}시간 ${minutes}분 ${seconds}초`;
            if (minutes) return `${minutes}분 ${seconds}초`;
            return `${seconds}초`;
        }

        function vastFormatBytes(bytes) {
            const value = Math.max(0, Number(bytes) || 0);
            const gib = 1024 ** 3;
            const mib = 1024 ** 2;
            if (value >= gib) return `${(value / gib).toFixed(2)} GiB`;
            if (value >= mib) return `${(value / mib).toFixed(1)} MiB`;
            if (value >= 1024) return `${(value / 1024).toFixed(1)} KiB`;
            return `${Math.round(value)} B`;
        }

        function vastRenderPreflight(launch) {
            const preflight = launch?.preflight && typeof launch.preflight === 'object'
                ? launch.preflight
                : {};
            const state = String(preflight.state || 'waiting');
            const stateEl = document.getElementById('vast-preflight-state');
            const estimateEl = document.getElementById('vast-preflight-estimate');
            const stateLabel = ({
                waiting: '빌드 대기',
                running: 'SSH 준비 확인 중…',
                ready: 'SSH 준비 완료',
                transferring: '실제 전송 중…',
                complete: '실제 전송 완료',
                failed: '준비 또는 전송 실패',
                cancelled: '취소됨',
            })[state] || state;
            if (stateEl) {
                stateEl.dataset.state = state;
                stateEl.textContent = stateLabel;
            }

            const tests = Array.isArray(preflight.tests) ? preflight.tests : [];
            const testsByKey = new Map(tests.map(item => [String(item?.key || ''), item]));
            document.querySelectorAll('[data-vast-preflight-key]').forEach(metric => {
                const key = String(metric.dataset.vastPreflightKey || '');
                const test = testsByKey.get(key);
                const valueEl = metric.querySelector('strong');
                const detailEl = metric.querySelector('span');
                if (!test) {
                    const pending = state === 'running' || state === 'ready' || state === 'transferring';
                    metric.dataset.state = pending ? 'running' : 'waiting';
                    if (valueEl) valueEl.textContent = pending ? '순서 대기' : '대기';
                    return;
                }
                const testState = String(test.status || 'done');
                metric.dataset.state = testState;
                const mbps = Number(test.mbps || 0);
                const mbPerSecond = Number(test.mb_per_second || 0);
                if (valueEl) {
                    if (mbps > 0) {
                        valueEl.textContent = `${mbPerSecond.toFixed(1)} MB/s · ${mbps.toFixed(0)} Mbps`;
                    } else if (testState === 'error') {
                        valueEl.textContent = '실패';
                    } else if (testState === 'waiting') {
                        valueEl.textContent = '전송 대기';
                    } else if (testState === 'running') {
                        valueEl.textContent = '속도 수집 중';
                    } else if (testState === 'skipped') {
                        valueEl.textContent = '대상 없음';
                    } else if (Number(test.seconds || 0) > 0) {
                        valueEl.textContent = vastFormatDuration(test.seconds);
                    } else {
                        valueEl.textContent = '관측값 없음';
                    }
                }
                if (detailEl) {
                    const completed = Math.max(0, Number(test.bytes || 0));
                    const total = Math.max(0, Number(test.total_bytes || 0));
                    const totalKnown = test.total_known !== false;
                    let progress = '';
                    if (completed > 0 || total > 0 || testState === 'running') {
                        progress = totalKnown && total > 0
                            ? `${vastFormatBytes(completed)} / ${vastFormatBytes(total)} · `
                            : `${vastFormatBytes(completed)} / 전체 크기 미확정 · `;
                    }
                    detailEl.textContent = `${progress}${String(test.detail || '')}`;
                    detailEl.title = detailEl.textContent;
                }
            });

            if (!estimateEl) return;
            const estimate = preflight.estimate && typeof preflight.estimate === 'object'
                ? preflight.estimate
                : {};
            if (state === 'running') {
                estimateEl.textContent = 'Docker 준비 상태와 실제 SSH 공개키 인증을 확인하고 있습니다.';
                return;
            }
            if (state === 'ready') {
                estimateEl.textContent = 'SSH 준비 완료 · 실제 모델 파일 전송 시작을 기다리고 있습니다.';
                return;
            }
            if (estimate.available === true && Number.isFinite(Number(estimate.remaining_seconds))) {
                const downloadText = estimate.download_seconds === null || estimate.download_seconds === undefined
                    ? '계산 불가'
                    : vastFormatDuration(estimate.download_seconds);
                const uploadText = estimate.upload_seconds === null || estimate.upload_seconds === undefined
                    ? '계산 불가'
                    : vastFormatDuration(estimate.upload_seconds);
                const downloadProgress = `${vastFormatBytes(estimate.download_completed_bytes)} / ${vastFormatBytes(estimate.download_bytes)}`;
                const uploadProgress = `${vastFormatBytes(estimate.upload_completed_bytes)} / ${vastFormatBytes(estimate.upload_bytes)}`;
                estimateEl.innerHTML = `<strong>실제 전송 기준 남은 시간 ${escapeHtml(vastFormatDuration(estimate.remaining_seconds))}</strong>`
                    + ` · 다운로드 ${escapeHtml(downloadText)} (${escapeHtml(downloadProgress)})`
                    + ` · 업로드 ${escapeHtml(uploadText)} (${escapeHtml(uploadProgress)})`
                    + `<br>${escapeHtml(String(estimate.note || ''))}`;
                return;
            }
            if (state === 'transferring' || state === 'failed') {
                estimateEl.textContent = String(estimate.note || preflight.error || '실제 전송 속도를 수집하고 있습니다.');
                return;
            }
            estimateEl.textContent = '워크플로우를 선택하고 빌드를 시작하면 실제 전송 진행률과 예상 시간이 표시됩니다.';
        }

        function vastEventTimeLabel(value) {
            const date = new Date(value);
            if (Number.isNaN(date.getTime())) return '--:--:--';
            return date.toLocaleTimeString('ko-KR', { hour12: false });
        }

        async function vastPollLaunch() {
            try {
                const data = await fetchJSON('/api/vast/launch');
                const launch = data?.launch || {};
                vastRenderLaunchSteps(launch);
                // 메인 패널/위젯 상태 동기화
                const st = document.getElementById('vast-runtime-state');
                const ins = document.getElementById('vast-runtime-instance');
                const stateLabel = launch.state === 'destroyed' && launch.destroy_automatic
                    ? '비용 보호 자동 파괴됨'
                    : ({
                    idle: '대기', creating: '생성 중', preparing: '준비 중',
                    ready: '준비 완료', error: '오류', destroyed: '파괴됨',
                    destroying: '파괴 확인 중', destroy_failed: '파괴 확인 실패',
                    recovered: '재시작 복구',
                })[launch.state] || launch.state;
                if (st) st.textContent = `● ${stateLabel}`;
                if (ins) ins.textContent = launch.instance_id ? `#${launch.instance_id} ${stateLabel}` : '없음';
            } catch (error) {
                console.error('[VAST] 빌드 상태 조회 실패:', error);
            } finally {
                const launch = window.__vastLastLaunch || {};
                const done = launch.state === 'ready' || launch.state === 'error' || launch.state === 'idle' || launch.state === 'destroyed' || launch.state === 'destroy_failed';
                const panelActive = vastWorkerFeatureEnabled && comfyRuntimeActiveView === 'vast'
                    && document.getElementById('settings-modal')?.classList.contains('visible')
                    && document.getElementById('settings-tab-comfy_runtime')?.classList.contains('active')
                    && document.getElementById('comfy-vast-panel')?.classList.contains('active');
                if (panelActive && !done) {
                    vastLaunchPollTimer = window.setTimeout(() => void vastPollLaunch(), 3000);
                }
            }
        }

        function vastRenderLaunchSteps(launch) {
            window.__vastLastLaunch = launch;
            const vastLoraSyncBtn = document.getElementById('vast-lora-sync-open-btn');
            if (vastLoraSyncBtn) vastLoraSyncBtn.disabled = launch.state !== 'ready';
            vastRenderPreflight(launch);
            const box = document.getElementById('vast-launch-progress');
            const title = document.getElementById('vast-launch-progress-title');
            const stateEl = document.getElementById('vast-launch-progress-state');
            const stepsEl = document.getElementById('vast-launch-steps');
            const comfyBox = document.getElementById('vast-launch-comfy');
            const comfyUrl = document.getElementById('vast-launch-comfy-url');
            const comfyLink = document.getElementById('vast-launch-comfy-link');
            const destroyBtn = document.getElementById('vast-launch-destroy-btn');
            const favoriteBtn = document.getElementById('vast-launch-favorite-btn');
            const elapsedEl = document.getElementById('vast-launch-elapsed');
            const costEl = document.getElementById('vast-launch-cost');
            const rateEl = document.getElementById('vast-launch-rate');
            const deadlineEl = document.getElementById('vast-launch-deadline');
            const warningEl = document.getElementById('vast-launch-warning');
            const imagePullBox = document.getElementById('vast-image-pull');
            const imagePullSummary = document.getElementById('vast-image-pull-summary');
            const imagePullState = document.getElementById('vast-image-pull-state');
            const imagePullMeter = document.getElementById('vast-image-pull-meter');
            const imagePullMeterFill = document.getElementById('vast-image-pull-meter-fill');
            const imagePullDetail = document.getElementById('vast-image-pull-detail');
            const imagePullNote = document.getElementById('vast-image-pull-note');
            const rawStatusEl = document.getElementById('vast-launch-raw-status');
            const terminalEl = document.getElementById('vast-launch-terminal');
            if (!box || !stepsEl) return;
            box.hidden = false;
            const stateLabel = launch.state === 'destroyed' && launch.destroy_automatic
                ? '비용 보호 자동 파괴됨'
                : ({
                idle: '대기', creating: '인스턴스 생성 중', preparing: '준비 중',
                ready: 'ComfyUI 준비 완료', error: '빌드 오류', destroyed: '파괴됨',
                destroying: '파괴 요청 및 소멸 확인 중', destroy_failed: '파괴 확인 실패',
                recovered: '서버 재시작 후 감시 복구',
            })[launch.state] || launch.state;
            if (title) title.textContent = `VAST 빌드 ${launch.instance_id ? `#${launch.instance_id}` : ''}`;
            if (stateEl) {
                stateEl.textContent = launch.state === 'error' && launch.error
                    ? `오류: ${launch.error}`
                    : stateLabel;
            }
            const instanceId = Number(launch.instance_id || 0);
            if (destroyBtn) {
                destroyBtn.hidden = !(instanceId > 0);
                destroyBtn.disabled = launch.state === 'destroying';
                destroyBtn.textContent = launch.state === 'destroying' ? '파괴 확인 중…' : '즉시 파괴';
            }
            if (favoriteBtn) {
                const instance = (window.__vastInstances || []).find(
                    item => Number(item.id) === instanceId,
                );
                const isFavorite = launch.favorite === true
                    || (launch.favorite == null && instance?.favorite === true);
                favoriteBtn.hidden = !(instanceId > 0);
                favoriteBtn.disabled = launch.state === 'destroying';
                favoriteBtn.classList.toggle('is-favorite', isFavorite);
                favoriteBtn.textContent = isFavorite
                    ? '★ 즐겨찾기 해제'
                    : '이 머신을 즐겨찾기에 등록';
            }
            if (elapsedEl) elapsedEl.textContent = launch.contract_started_at_epoch
                ? vastFormatDuration(launch.elapsed_seconds)
                : '계약 생성 전';
            if (costEl) costEl.textContent = `$${Number(launch.estimated_cost_usd || 0).toFixed(4)}`;
            if (rateEl) rateEl.textContent = Number(launch.hourly_price_usd || 0) > 0
                ? `$${Number(launch.hourly_price_usd).toFixed(4)}/hr`
                : '확인 중';
            if (deadlineEl) {
                const remaining = launch.auto_destroy_remaining_seconds;
                deadlineEl.textContent = remaining === null || remaining === undefined
                    ? (launch.state === 'ready' ? '빌드 보호 해제' : '-')
                    : `${vastFormatDuration(remaining)} (${launch.auto_destroy_limit_name || '보호 제한'})`;
            }
            const imagePull = launch.image_pull && typeof launch.image_pull === 'object'
                ? launch.image_pull
                : {};
            const loraCleanup = launch.lora_cleanup && typeof launch.lora_cleanup === 'object'
                ? launch.lora_cleanup
                : {};
            if (imagePullBox) {
                const showImagePull = launch.instance_status === 'loading'
                    || imagePull.available === true
                    || imagePull.phase === 'complete'
                    || Boolean(imagePull.error);
                imagePullBox.hidden = !showImagePull;
                if (showImagePull) {
                    const minimumPercent = Math.max(
                        0,
                        Math.min(100, Number(imagePull.minimum_percent) || 0),
                    );
                    const stateKey = String(imagePull.activity_state || 'waiting');
                    const pullStateLabel = ({
                        complete: '레이어 완료 확인',
                        observed: '진행 확인됨',
                        unobserved: '활동 미관측',
                        unavailable: '관측 불가',
                        waiting: '관측 대기',
                    })[stateKey] || stateKey;
                    imagePullBox.dataset.state = stateKey;
                    if (imagePullState) imagePullState.textContent = pullStateLabel;
                    if (imagePullMeter) {
                        imagePullMeter.setAttribute('aria-valuenow', minimumPercent.toFixed(1));
                        imagePullMeter.setAttribute(
                            'aria-valuetext',
                            `확인된 최소 진행률 ${minimumPercent.toFixed(1)}%`,
                        );
                    }
                    if (imagePullMeterFill) imagePullMeterFill.style.width = `${minimumPercent}%`;
                    if (imagePullSummary) {
                        imagePullSummary.textContent = imagePull.available
                            ? `확정 ${vastFormatBytes(imagePull.confirmed_bytes)} / ${vastFormatBytes(imagePull.total_bytes)} · 최소 ${minimumPercent.toFixed(1)}%`
                            : 'Docker 이미지 상세 진행 관측 대기 중';
                    }
                    if (imagePullDetail) {
                        const pendingLayers = Array.isArray(imagePull.pending_layers)
                            ? imagePull.pending_layers
                            : [];
                        const largest = pendingLayers.slice(0, 3)
                            .map(layer => `${layer.id || '?'} ${vastFormatBytes(layer.size_bytes)}`)
                            .join(', ');
                        const pending = imagePull.available
                            ? `미확정 ${vastFormatBytes(imagePull.pending_bytes)} · 레이어 ${pendingLayers.length}개${largest ? ` (${largest})` : ''}`
                            : 'manifest와 daemon log를 요청하고 있습니다.';
                        const stale = Number(imagePull.activity_stale_seconds);
                        const hasObservedSignal = Number(imagePull.last_observed_progress_at_epoch) > 0;
                        const lastSignal = hasObservedSignal && Number.isFinite(stale) && stale >= 0
                            ? ` · 마지막 레이어 상태 변화 ${vastFormatDuration(stale)} 전`
                            : ' · 관측 가능한 레이어 변화 아직 없음';
                        imagePullDetail.textContent = `${pending}${lastSignal}`;
                    }
                    if (imagePullNote) {
                        imagePullNote.textContent = imagePull.error
                            ? `상세 진행 조회 실패: ${String(imagePull.error)} · VAST 기본 상태 polling은 계속됩니다.`
                            : '완료된 압축 레이어만 집계한 하한입니다. 현재 레이어 내부의 수신 바이트는 VAST에서 제공하지 않습니다.';
                    }
                }
            }
            if (rawStatusEl) {
                const rawLines = [
                    `actual_status: ${launch.instance_status || '(아직 없음)'}`,
                    `status_msg: ${launch.instance_status_msg || '(아직 없음)'}`,
                    `마지막 일반 상태 변화: ${vastFormatDuration(launch.progress_stale_seconds || 0)} 전`,
                    `LoRA 원격 정리: ${Number(loraCleanup.pending_count || 0)}개 · ${vastFormatBytes(loraCleanup.pending_bytes || 0)}${loraCleanup.flush_active ? ' · 재시도 실행 중' : ''}`,
                ];
                if (imagePull.available) {
                    rawLines.push(
                        `image_pull_lower_bound: ${Number(imagePull.minimum_percent || 0).toFixed(1)}% `
                        + `(${imagePull.confirmed_bytes || 0}/${imagePull.total_bytes || 0} bytes)`,
                    );
                }
                rawStatusEl.textContent = rawLines.join('\n');
            }
            if (warningEl) {
                const critical = launch.state === 'destroy_failed' || launch.protection_state === 'critical';
                const warning = critical
                    ? (launch.protection_reason || launch.error || '파괴 확인 실패 — 과금 가능성이 있습니다.')
                    : launch.activity_unobserved
                        ? launch.activity_unobserved_reason
                        : launch.state === 'destroyed' && launch.destroy_automatic
                            ? (launch.destroy_reason || '비용 보호 제한으로 자동 파괴됐습니다.')
                        : launch.state === 'recovered'
                            ? (launch.protection_reason || '서버 재시작 뒤 복구된 인스턴스입니다. 상태를 확인하세요.')
                            : Number(loraCleanup.pending_count || 0) > 0
                                ? `LoRA 원격 정리 ${Number(loraCleanup.pending_count)}개가 재시도 대기 중입니다.`
                            : '';
                warningEl.hidden = !warning;
                warningEl.classList.toggle('critical', critical);
                warningEl.textContent = warning;
            }
            const steps = Array.isArray(launch.steps) ? launch.steps : [];
            stepsEl.replaceChildren();
            for (const s of steps) {
                const li = document.createElement('li');
                const isCurrentUnobserved = launch.activity_unobserved && s.key === launch.current_step && s.state === 'running';
                li.className = `vast-launch-step state-${isCurrentUnobserved ? 'unobserved' : (s.state || 'pending')}`;
                const label = document.createElement('span');
                label.textContent = VAST_LAUNCH_STEP_LABELS[s.key] || s.key;
                const detail = document.createElement('span');
                detail.className = 'vast-launch-step-detail';
                detail.textContent = s.detail || '';
                li.append(label, detail);
                stepsEl.append(li);
            }
            if (terminalEl) {
                const nearBottom = terminalEl.scrollHeight - terminalEl.scrollTop - terminalEl.clientHeight < 36;
                const events = Array.isArray(launch.events) ? launch.events : [];
                terminalEl.textContent = events.length
                    ? events.map(event => `[${vastEventTimeLabel(event.at)}] [${String(event.level || 'info').toUpperCase()}] ${event.message || ''}`).join('\n')
                    : '[VAST] 아직 기록된 빌드 이벤트가 없습니다.';
                if (nearBottom) terminalEl.scrollTop = terminalEl.scrollHeight;
            }
            if (launch.state === 'ready' && launch.comfy_base_url) {
                if (comfyBox) comfyBox.hidden = false;
                if (comfyUrl) comfyUrl.textContent = launch.comfy_base_url;
                if (comfyLink) { comfyLink.href = launch.comfy_base_url; comfyLink.hidden = false; }
            } else {
                if (comfyBox) comfyBox.hidden = true;
                if (comfyLink) comfyLink.hidden = true;
            }
            if (launch.state === 'error') {
                const signature = String(launch.error || '알 수 없음');
                if (signature !== vastLastLaunchErrorToast) {
                    vastLastLaunchErrorToast = signature;
                    showToast('VAST 빌드 오류: ' + signature, 'error');
                }
            } else if (launch.state !== 'destroy_failed') {
                vastLastLaunchErrorToast = '';
            }
        }

        async function vastDestroyActive() {
            const launch = window.__vastLastLaunch || {};
            const instanceId = Number(launch.instance_id || 0);
            if (!(instanceId > 0)) {
                console.error('[VAST] 진행 패널 파괴 요청 실패: 활성 instance_id 없음', launch);
                showToast('파괴할 활성 Vast 인스턴스가 없습니다.', 'error');
                return;
            }
            await vastDestroy(instanceId);
        }

        async function vastFavoriteActive() {
            const launch = window.__vastLastLaunch || {};
            const instanceId = Number(launch.instance_id || 0);
            if (!(instanceId > 0)) {
                console.error('[VAST_FAVORITE] 활성 인스턴스 ID 없음:', launch);
                showToast('즐겨찾기에 등록할 활성 Vast 인스턴스가 없습니다.', 'error');
                return;
            }
            const button = document.getElementById('vast-launch-favorite-btn');
            const instance = (window.__vastInstances || []).find(
                item => Number(item.id) === instanceId,
            );
            const isFavorite = launch.favorite === true
                || (launch.favorite == null && instance?.favorite === true);
            const machineId = Number(launch.machine_id || instance?.machine_id || 0);
            if (isFavorite && machineId > 0) {
                await vastUnfavoriteMachine(machineId, button);
                return;
            }
            await vastFavoriteInstance(instanceId, button);
        }

        async function vastFavoriteInstance(instanceId, button = null) {
            if (!(Number(instanceId) > 0)) {
                console.error('[VAST_FAVORITE] 잘못된 인스턴스 ID:', instanceId);
                showToast('즐겨찾기에 등록할 Vast 인스턴스 ID가 올바르지 않습니다.', 'error');
                return;
            }
            if (button) {
                button.disabled = true;
                button.textContent = '즐겨찾기 등록 중…';
            }
            try {
                const result = await fetchJSON('/api/vast/favorites', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ instance_id: Number(instanceId) }),
                });
                const machineId = Number(result?.favorite?.machine_id || 0);
                showToast(
                    result?.added
                        ? `Vast 머신 #${machineId} 즐겨찾기 등록 완료`
                        : `Vast 머신 #${machineId}는 이미 즐겨찾기입니다.`,
                    'success',
                );
                if (window.__vastLastLaunch
                    && Number(window.__vastLastLaunch.machine_id || 0) === machineId) {
                    window.__vastLastLaunch.favorite = true;
                }
                await vastLoadInstances();
                if (vastOffers.length) await vastSearchOffers();
                vastRenderLaunchSteps(window.__vastLastLaunch || {});
            } catch (error) {
                console.error('[VAST_FAVORITE] 등록 실패:', error);
                showToast('Vast 머신 즐겨찾기 등록 실패: ' + (error.message || error), 'error');
                if (button) {
                    button.disabled = false;
                    button.textContent = '이 머신을 즐겨찾기에 등록';
                }
            }
        }

        async function vastUnfavoriteMachine(machineId, button = null) {
            if (!(Number(machineId) > 0)) {
                console.error('[VAST_FAVORITE] 잘못된 머신 ID:', machineId);
                showToast('즐겨찾기를 해제할 Vast 머신 ID가 올바르지 않습니다.', 'error');
                return;
            }
            if (button) {
                button.disabled = true;
                button.textContent = '즐겨찾기 해제 중…';
            }
            try {
                const result = await fetchJSON('/api/vast/favorites', {
                    method: 'DELETE',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ machine_id: Number(machineId) }),
                });
                showToast(
                    result?.removed
                        ? `Vast 머신 #${machineId} 즐겨찾기 해제 완료`
                        : `Vast 머신 #${machineId}는 즐겨찾기에 없습니다.`,
                    'success',
                );
                if (window.__vastLastLaunch
                    && Number(window.__vastLastLaunch.machine_id || 0) === Number(machineId)) {
                    window.__vastLastLaunch.favorite = false;
                }
                await vastLoadInstances();
                if (vastOffers.length) await vastSearchOffers();
                vastRenderLaunchSteps(window.__vastLastLaunch || {});
            } catch (error) {
                console.error('[VAST_FAVORITE] 해제 실패:', error);
                showToast('Vast 머신 즐겨찾기 해제 실패: ' + (error.message || error), 'error');
                if (button) {
                    button.disabled = false;
                    button.textContent = '★ 즐겨찾기 해제';
                }
            }
        }

        // ── 인스턴스 목록/파괴 ──
        async function vastLoadInstances() {
            const container = document.getElementById('vast-instance-catalog');
            if (container) container.innerHTML = '<div class="modal-lora-empty">인스턴스 목록을 불러오는 중입니다.</div>';
            try {
                const data = await fetchJSON('/api/vast/instances');
                const rows = Array.isArray(data.instances) ? data.instances : [];
                window.__vastInstances = rows;
                if (!container) return;
                container.replaceChildren();
                if (!rows.length) {
                    const empty = document.createElement('div');
                    empty.className = 'modal-lora-empty';
                    empty.textContent = '실행 중인 Vast 인스턴스가 없습니다.';
                    container.append(empty);
                    return;
                }
                for (const i of rows) {
                    const row = document.createElement('div');
                    row.className = 'vast-offer-row';
                    const main = document.createElement('div');
                    main.className = 'vast-offer-main';
                    const strong = document.createElement('strong');
                    strong.textContent = `${i.favorite ? '★ ' : ''}#${i.id} ${i.gpu_name || 'GPU'}${i.label ? ` · ${i.label}` : ''}`;
                    const meta = document.createElement('div');
                    meta.className = 'vast-offer-meta';
                    [i.machine_id ? `머신 #${i.machine_id}` : null, i.actual_status ? `상태 ${i.actual_status}` : null, `cur ${i.cur_state || ''}`, i.dph_total ? `$${Number(i.dph_total).toFixed(3)}/hr` : null, i.status_msg ? `Vast: ${i.status_msg}` : null]
                        .filter(Boolean).forEach(t => { const s = document.createElement('span'); s.textContent = t; meta.append(s); });
                    main.append(strong, meta);
                    const actions = document.createElement('div');
                    actions.className = 'vast-offer-price';
                    const favoriteBtn = document.createElement('button');
                    favoriteBtn.type = 'button';
                    favoriteBtn.textContent = i.favorite ? '★ 즐겨찾기 해제' : '즐겨찾기 등록';
                    favoriteBtn.className = 'vast-launch-favorite'
                        + (i.favorite === true ? ' is-favorite' : '');
                    favoriteBtn.addEventListener('click', () => {
                        if (i.favorite === true) void vastUnfavoriteMachine(i.machine_id, favoriteBtn);
                        else void vastFavoriteInstance(i.id, favoriteBtn);
                    });
                    const btn = document.createElement('button');
                    btn.type = 'button';
                    btn.textContent = '파괴';
                    btn.className = 'comfy-runtime-btn stop';
                    btn.style.cssText = 'padding:5px 10px; border-radius:7px;';
                    btn.addEventListener('click', () => void vastDestroy(i.id));
                    actions.append(favoriteBtn, btn);
                    row.append(main, actions);
                    container.append(row);
                }
                vastRenderLaunchSteps(window.__vastLastLaunch || {});
            } catch (error) {
                console.error('[VAST] 인스턴스 목록 조회 실패:', error);
                if (container) container.innerHTML = `<div class="modal-lora-empty">인스턴스 목록 조회 실패: ${escapeHtml(String(error.message || error))}</div>`;
            }
        }

        async function vastDestroy(instanceId) {
            const launch = window.__vastLastLaunch || {};
            const costText = Number(launch.instance_id) === Number(instanceId)
                ? `\n현재 예상 비용: $${Number(launch.estimated_cost_usd || 0).toFixed(4)}\n진행 단계: ${launch.current_step || '-'}`
                : '';
            if (!confirm(`Vast 인스턴스 #${instanceId} 를 즉시 파괴할까요?${costText}\n\n데이터는 삭제되며, Vast 목록에서 소멸을 확인한 뒤 완료로 표시합니다.`)) return;
            const activeButton = document.getElementById('vast-launch-destroy-btn');
            if (activeButton && Number(launch.instance_id) === Number(instanceId)) {
                activeButton.disabled = true;
                activeButton.textContent = '파괴 확인 중…';
            }
            try {
                const result = await fetchJSON('/api/vast/destroy', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ instance_id: instanceId }),
                });
                if (result?.launch) vastRenderLaunchSteps(result.launch);
                showToast(`Vast 인스턴스 #${instanceId} 파괴·소멸 확인 완료`, 'success');
                await vastLoadInstances();
                void refreshVastStatus(true);
                vastRefreshLaunchPolling();
            } catch (error) {
                console.error('[VAST] 인스턴스 파괴 실패:', error);
                showToast('VAST 인스턴스 파괴 확인 실패 — 과금 가능성 있음: ' + (error.message || error), 'error');
                vastRefreshLaunchPolling();
            }
        }

        document.addEventListener('DOMContentLoaded', initializeMemoPadUi);
        document.addEventListener('DOMContentLoaded', initializeModalWorkerUi);
        document.addEventListener('DOMContentLoaded', initializeVastWorkerUi);
        document.addEventListener('DOMContentLoaded', _renderLlmLogLock);

        function loadCurrentConfig(forceRefresh = false) {
            if (!forceRefresh && currentConfigLoadPromise) {
                return currentConfigLoadPromise;
            }

            const requestPromise = fetchJSON('/api/config')
                .then(config => {
                    if (!config || typeof config !== 'object') {
                        console.error('[CONFIG] 설정 응답 형식 오류:', config);
                        throw new Error('설정 응답 형식이 올바르지 않습니다.');
                    }
                    currentConfig = config;
                    return config;
                })
                .catch(error => {
                    console.error('[CONFIG] 설정 로드 실패:', error);
                    if (currentConfigLoadPromise === requestPromise) {
                        currentConfigLoadPromise = null;
                    }
                    throw error;
                });

            currentConfigLoadPromise = requestPromise;
            return requestPromise;
        }

        // 페이지 스크립트가 준비되는 즉시 설정 로드를 시작한다. 삽화 탭과 설정 모달은
        // 이 Promise를 공유하므로 시작 직후 탭을 눌러도 동일 요청의 완료를 기다린다.
        loadCurrentConfig()
            .then(config => {
                applyMemoFeatureEnabled(config.memo_enabled !== false);
                applyModalWorkerFeatureConfig(config);
                applyVastConfig(config);
            })
            .catch(error => console.error('[LEFT_DOCK] 초기 기능 설정 적용 실패:', error));

        // ─── 터널 공유 (공유 모달) ──────────────────────────
        let tunnelActive = false;
        let tunnelUrl = null;
        // Tailscale Serve (tailnet 고정 주소) — Cloudflare 터널과 독립적으로 동작
        let tsActive = false;
        let tsUrl = null;

        // Workflow JSON 을 모달 textarea 에 예쁘게 채운다 (1회).
        (function _fillShareWorkflow() {
            try {
                const raw = document.getElementById('share-workflow-data').textContent.trim();
                const ta = document.getElementById('share-workflow-textarea');
                if (!raw || !ta) return;
                const obj = JSON.parse(raw);
                ta.value = JSON.stringify(obj, null, 2);
            } catch (e) {
                console.error('[SHARE] workflow JSON 파싱 실패', e);
                const ta = document.getElementById('share-workflow-textarea');
                if (ta) ta.value = 'Workflow JSON 파싱 실패: ' + (e && e.message || e);
            }
        })();

        // 메인 공유 버튼 라벨/스타일 동기화
        function _syncTunnelBtn() {
            const btn = document.getElementById('tunnel-btn');
            if (!btn) return;
            if (tunnelActive) {
                btn.textContent = '🔗 공유 중';
                btn.classList.add('tunnel-active');
            } else {
                btn.textContent = '🔗 공유';
                btn.classList.remove('tunnel-active');
            }
        }

        // 모달 내 발급 영역 UI 갱신
        function _renderShareState() {
            const box = document.getElementById('share-url-box');
            const issueBtn = document.getElementById('share-issue-btn');
            const copyBtn = document.getElementById('share-copy-btn');
            const regenBtn = document.getElementById('share-regen-btn');
            const stopBtn = document.getElementById('share-stop-btn');
            if (!box) return;
            // 가이드의 "발급받은 주소" 자리(ComfyUI 요청 URL / 서버 HTTPS 주소)를
            // 실제 발급 주소로 채운다. Cloudflare 우선, 없으면 Tailscale 고정 주소.
            // 미발급 시 플레이스홀더를 유지.
            const guidePlaceholder = 'https://발급받은-주소.example.com';
            const guideVal = (tunnelActive && tunnelUrl) ? tunnelUrl
                : (tsActive && tsUrl) ? tsUrl : guidePlaceholder;
            const sgComfy = document.getElementById('sg-val-comfy');
            const sgServer = document.getElementById('sg-val-server');
            if (sgComfy) sgComfy.textContent = guideVal;
            if (sgServer) sgServer.textContent = guideVal;
            if (tunnelActive && tunnelUrl) {
                box.textContent = tunnelUrl;
                box.classList.remove('empty');
                if (issueBtn) { issueBtn.disabled = true; issueBtn.title = ''; }
                if (copyBtn) copyBtn.disabled = false;
                if (regenBtn) regenBtn.disabled = false;
                if (stopBtn) stopBtn.disabled = false;
            } else {
                box.textContent = '발급 전';
                box.classList.add('empty');
                // 한쪽이 발급되어 있으면 다른 쪽은 동시 발급 불가
                if (issueBtn) {
                    issueBtn.disabled = !!tsActive;
                    issueBtn.title = tsActive ? 'Tailscale 고정 주소가 발급 중입니다. 먼저 해지하세요.' : '';
                }
                if (copyBtn) copyBtn.disabled = true;
                if (regenBtn) regenBtn.disabled = true;
                if (stopBtn) stopBtn.disabled = true;
            }
            _renderTailscaleState();
        }

        // 서버 상태 조회 → 변수/버튼 동기화
        async function _refreshTunnelStatus() {
            try {
                const res = await fetchJSON('/api/tunnel/status');
                if (res.status === 'running' && res.url) {
                    tunnelActive = true;
                    tunnelUrl = res.url;
                } else {
                    tunnelActive = false;
                    tunnelUrl = null;
                }
            } catch (e) {
                tunnelActive = false;
                tunnelUrl = null;
            }
            _syncTunnelBtn();
            _renderShareState();
        }

        // 페이지 로드 시 터널 상태 복원 (버튼 라벨만)
        (async () => { await _refreshTunnelStatus(); })();

        function openShareModal() {
            document.getElementById('share-modal').classList.add('visible');
            // 모달을 열 때마다 서버 상태를 새로고침 — 발급 주소가 유지되어 표시됨.
            _refreshTunnelStatus();
            _refreshTailscaleStatus();
        }
        function closeShareModal() {
            document.getElementById('share-modal').classList.remove('visible');
        }

        function _setShareStatus(msg, isError) {
            const el = document.getElementById('share-status');
            if (!el) return;
            el.textContent = msg || '';
            el.style.color = isError ? 'var(--error)' : 'var(--text2)';
        }

        async function issueTunnelUrl() {
            const issueBtn = document.getElementById('share-issue-btn');
            if (issueBtn) { issueBtn.disabled = true; issueBtn.textContent = '발급 중...'; }
            _setShareStatus('터널 연결 중... (최대 20초)');
            try {
                const res = await fetch('/api/tunnel/start', {method:'POST'});
                const data = await res.json();
                if (data && data.url) {
                    tunnelActive = true;
                    tunnelUrl = data.url;
                    _syncTunnelBtn();
                    _renderShareState();
                    _setShareStatus('공유 주소가 발급되었습니다.');
                    showToast('공유 링크가 생성되었습니다!', 'success');
                } else {
                    throw new Error((data && data.error) || '터널 시작 실패');
                }
            } catch (e) {
                _setShareStatus('공유 연결 실패: ' + (e && e.message || e), true);
                showToast('공유 연결 실패: ' + (e && e.message || e), 'error');
            } finally {
                if (issueBtn) { issueBtn.textContent = '주소 발급'; }
                _renderShareState();
            }
        }

        function copyTunnelUrl() {
            if (!tunnelUrl) { showToast('복사할 주소가 없습니다.', 'error'); return; }
            navigator.clipboard.writeText(tunnelUrl).then(() => {
                showToast('공유 주소가 복사되었습니다!', 'success');
            }).catch((e) => {
                showToast('복사 실패: ' + (e && e.message || e), 'error');
            });
        }

        async function regenTunnelUrl() {
            // 끄고 바로 다시 켜기
            const regenBtn = document.getElementById('share-regen-btn');
            if (regenBtn) { regenBtn.disabled = true; regenBtn.textContent = '재발급 중...'; }
            _setShareStatus('재발급 중... 기존 연결을 종료하고 다시 엽니다.');
            try { await fetch('/api/tunnel/stop', {method:'POST'}); } catch(e) {}
            tunnelActive = false;
            tunnelUrl = null;
            _renderShareState();
            await issueTunnelUrl();
            if (regenBtn) { regenBtn.textContent = '재발급'; }
            _renderShareState();
        }

        async function stopTunnelUrl() {
            const stopBtn = document.getElementById('share-stop-btn');
            if (stopBtn) { stopBtn.disabled = true; stopBtn.textContent = '종료 중...'; }
            try { await fetch('/api/tunnel/stop', {method:'POST'}); } catch(e) {}
            tunnelActive = false;
            tunnelUrl = null;
            _syncTunnelBtn();
            _renderShareState();
            _setShareStatus('연결이 종료되었습니다.');
            showToast('공유 연결을 종료했습니다.', 'info');
            if (stopBtn) { stopBtn.textContent = '연결 종료'; }
            _renderShareState();
        }

        // ─── Tailscale Serve (tailnet 고정 주소) ─────────────
        // 이 매니저는 HTTPS 8189 -> 로컬 8189 매핑만 생성하고 종료한다.
        function _renderTailscaleState() {
            const box = document.getElementById('ts-url-box');
            const issueBtn = document.getElementById('ts-issue-btn');
            const copyBtn = document.getElementById('ts-copy-btn');
            const stopBtn = document.getElementById('ts-stop-btn');
            if (!box) return;
            if (tsActive && tsUrl) {
                box.textContent = tsUrl;
                box.classList.remove('empty');
                if (issueBtn) { issueBtn.disabled = true; issueBtn.title = ''; }
                if (copyBtn) copyBtn.disabled = false;
                if (stopBtn) stopBtn.disabled = false;
            } else {
                box.textContent = '발급 전';
                box.classList.add('empty');
                // 한쪽이 발급되어 있으면 다른 쪽은 동시 발급 불가
                if (issueBtn) {
                    issueBtn.disabled = !!tunnelActive;
                    issueBtn.title = tunnelActive ? 'Cloudflare 랜덤 주소가 발급 중입니다. 먼저 연결 종료하세요.' : '';
                }
                if (copyBtn) copyBtn.disabled = true;
                if (stopBtn) stopBtn.disabled = true;
            }
        }

        function _setTailscaleStatus(msg, isError) {
            const el = document.getElementById('ts-status');
            if (!el) return;
            if (!msg) { el.textContent = ''; el.style.color = isError ? 'var(--error)' : 'var(--text2)'; return; }
            // 오류에 URL이 포함된 경우에만 안전하게 링크로 표시한다.
            const esc = msg.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            const html = esc.replace(
                /(https:\/\/[^\s]+)/g,
                '<a href="$1" target="_blank" rel="noopener noreferrer" style="color:var(--accent);text-decoration:underline">$1</a>'
            );
            el.innerHTML = html;
            el.style.whiteSpace = 'pre-wrap';
            el.style.color = isError ? 'var(--error)' : 'var(--text2)';
        }

        async function _refreshTailscaleStatus() {
            try {
                const res = await fetchJSON('/api/tailscale/status');
                if (res.status === 'running' && res.url) {
                    tsActive = true;
                    tsUrl = res.url;
                } else {
                    tsActive = false;
                    tsUrl = null;
                }
                if (res.error) {
                    _setTailscaleStatus(res.error, true);
                } else {
                    _setTailscaleStatus('');
                }
            } catch (e) {
                tsActive = false;
                tsUrl = null;
                _setTailscaleStatus('Tailscale 상태 조회 실패: ' + (e && e.message || e), true);
            }
            _renderTailscaleState();
            // 가이드 자리 주소 후보에 Tailscale URL도 포함되므로 같이 갱신
            _renderShareState();
        }

        async function issueTailscale() {
            const issueBtn = document.getElementById('ts-issue-btn');
            if (issueBtn) { issueBtn.disabled = true; issueBtn.textContent = '발급 중...'; }
            _setTailscaleStatus('Tailscale Serve HTTPS :8189 설정 중... (최대 20초)');
            try {
                const res = await fetch('/api/tailscale/start', {method:'POST'});
                const data = await res.json();
                if (res.ok && data && data.url) {
                    tsActive = true;
                    tsUrl = data.url;
                    _renderTailscaleState();
                    _renderShareState();
                    _setTailscaleStatus('고정 주소가 발급되었습니다.');
                    showToast('Tailscale 고정 주소가 발급되었습니다!', 'success');
                } else {
                    throw new Error((data && data.error) || 'Tailscale Serve 시작 실패');
                }
            } catch (e) {
                _setTailscaleStatus(
                    '고정 주소 발급 실패: ' + (e && e.message || e),
                    true
                );
                showToast('Tailscale 발급 실패: ' + (e && e.message || e), 'error');
            } finally {
                if (issueBtn) { issueBtn.textContent = '주소 발급'; }
                _renderTailscaleState();
            }
        }

        function copyTailscale() {
            if (!tsUrl) { showToast('복사할 주소가 없습니다.', 'error'); return; }
            navigator.clipboard.writeText(tsUrl).then(() => {
                showToast('고정 주소가 복사되었습니다!', 'success');
            }).catch((e) => {
                showToast('복사 실패: ' + (e && e.message || e), 'error');
            });
        }

        async function stopTailscale() {
            const stopBtn = document.getElementById('ts-stop-btn');
            if (stopBtn) { stopBtn.disabled = true; stopBtn.textContent = '종료 중...'; }
            _setTailscaleStatus('Serve HTTPS :8189 연결 종료 중...');
            try {
                const res = await fetch('/api/tailscale/stop', {method:'POST'});
                const data = await res.json();
                if (!res.ok || (data && data.status === 'error')) {
                    throw new Error((data && data.error) || 'Tailscale Serve 종료 실패');
                }
                tsActive = false;
                tsUrl = null;
                _renderTailscaleState();
                _renderShareState();
                _setTailscaleStatus('Serve HTTPS :8189 연결이 종료되었습니다.');
                showToast('Tailscale Serve :8189 연결을 종료했습니다.', 'info');
            } catch(e) {
                _setTailscaleStatus('해지 실패: ' + (e && e.message || e), true);
                showToast('Tailscale 종료 실패: ' + (e && e.message || e), 'error');
            }
            if (stopBtn) { stopBtn.textContent = '연결 종료'; }
            _renderTailscaleState();
        }

        // ─── WebSocket 연결 ───
        let _wsReconnectTimer = null;
        let _wsConnectionReady = false;
        let _wsLastServerActivity = 0;
        let _wsOpenedAt = 0;
        let _wsHealthTimeoutMs = 50000;
        let _wsStatusDetail = 'WS 미연결';
        const _WS_READY_TIMEOUT_MS = 10000;
        const _WS_REPLACED_CLOSE_CODE = 4001;

        function isFrontendWsHealthy() {
            if (!frontendWs || frontendWs.readyState !== WebSocket.OPEN || !_wsConnectionReady) {
                return false;
            }
            return Date.now() - _wsLastServerActivity <= _wsHealthTimeoutMs;
        }

        function waitForFrontendWsHealthy(timeoutMs = 5000) {
            const deadline = Date.now() + timeoutMs;
            return new Promise(resolve => {
                const check = () => {
                    if (isFrontendWsHealthy()) {
                        resolve(true);
                        return;
                    }
                    if (Date.now() >= deadline) {
                        resolve(false);
                        return;
                    }
                    setTimeout(check, 100);
                };
                check();
            });
        }

        function _resetWsProtocolState(detail) {
            _wsConnectionReady = false;
            _wsLastServerActivity = 0;
            _wsOpenedAt = 0;
            _wsHealthTimeoutMs = 50000;
            _wsStatusDetail = detail || 'WS 미연결';
        }

        // WS 연결 상태 LED: 파란불=서버 승인+heartbeat 정상, 빨간불=끊김, 노란불=확인 중
        function updateWsStatusLed() {
            const led = document.getElementById('ws-status-led');
            if (!led) return;
            const st = frontendWs ? frontendWs.readyState : null;
            // 0=CONNECTING, 1=OPEN, 2=CLOSING, 3=CLOSED
            if (isFrontendWsHealthy()) {
                led.style.background = '#1e88e5';
                led.style.boxShadow = '0 0 4px rgba(30,136,229,0.8)';
                led.title = _wsStatusDetail || 'WS 연결 정상';
            } else if (st === WebSocket.CONNECTING || st === WebSocket.CLOSING || st === WebSocket.OPEN) {
                led.style.background = '#fbc02d';
                led.style.boxShadow = '0 0 4px rgba(251,192,45,0.8)';
                led.title = _wsStatusDetail || 'WS 서버 응답 확인 중';
            } else {
                led.style.background = '#e53935';
                led.style.boxShadow = '0 0 4px rgba(229,57,53,0.7)';
                led.title = _wsStatusDetail || 'WS 미연결';
            }
        }

        function _checkFrontendWsHealth() {
            const socket = frontendWs;
            if (!socket || socket.readyState !== WebSocket.OPEN) {
                updateWsStatusLed();
                return;
            }

            const now = Date.now();
            if (!_wsConnectionReady && _wsOpenedAt && now - _wsOpenedAt > _WS_READY_TIMEOUT_MS) {
                const age = now - _wsOpenedAt;
                console.error(`[Frontend WS] 서버 연결 승인 시간 초과: ${age}ms`);
                _wsStatusDetail = 'WS 서버 승인 시간 초과 - 재연결 중';
                updateWsStatusLed();
                try { socket.close(4002, 'connection_ready timeout'); }
                catch (e) { console.error('[Frontend WS] 승인 시간 초과 소켓 종료 실패:', e); }
                return;
            }

            if (_wsConnectionReady && now - _wsLastServerActivity > _wsHealthTimeoutMs) {
                const age = now - _wsLastServerActivity;
                _wsConnectionReady = false;
                _wsStatusDetail = 'WS heartbeat 시간 초과 - 재연결 중';
                console.error(`[Frontend WS] heartbeat 시간 초과: ${age}ms`);
                updateWsStatusLed();
                try { socket.close(4002, 'heartbeat timeout'); }
                catch (e) { console.error('[Frontend WS] heartbeat 시간 초과 소켓 종료 실패:', e); }
                return;
            }

            updateWsStatusLed();
        }

        // 네이티브 readyState와 애플리케이션 heartbeat 상태를 함께 주기 점검한다.
        if (!window._wsStatusLedTimer) {
            window._wsStatusLedTimer = setInterval(_checkFrontendWsHealth, 1000);
        }
        function _scheduleWsReconnect(delay) {
            // 이미 재연결 예약 중이면 중복 잡지 않는다(onclose/onerror 양쪽에서 호출되므로).
            if (_wsReconnectTimer) return;
            console.log(`[Frontend WS] ${delay}ms 후 재연결 시도`);
            _wsReconnectTimer = setTimeout(() => {
                _wsReconnectTimer = null;
                connectFrontendWs();
            }, delay);
        }
        function connectFrontendWs() {
            const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
            const wsUrl = `${protocol}//${window.location.host}/api/frontend_ws`;

            if (_wsReconnectTimer) {
                clearTimeout(_wsReconnectTimer);
                _wsReconnectTimer = null;
            }

            if (frontendWs) {
                // 기존 WS의 늦은 이벤트가 새 연결 상태를 덮어쓰지 않도록 모든 핸들러를 해제한다.
                const previousSocket = frontendWs;
                previousSocket.onopen = null;
                previousSocket.onmessage = null;
                previousSocket.onclose = null;
                previousSocket.onerror = null;
                try { previousSocket.close(); }
                catch (e) { console.error('[Frontend WS] 기존 소켓 종료 실패:', e); }
            }

            _resetWsProtocolState('WS 연결 중');
            let socket;
            try {
                socket = new WebSocket(wsUrl);
            } catch (e) {
                console.error('[Frontend WS] 소켓 생성 실패:', e);
                frontendWs = null;
                _wsStatusDetail = 'WS 연결 생성 실패';
                updateWsStatusLed();
                _scheduleWsReconnect(2000);
                return null;
            }
            frontendWs = socket;
            updateWsStatusLed();
            let allowAutoReconnect = true;

            socket.onopen = function() {
                if (socket !== frontendWs) return;
                _wsOpenedAt = Date.now();
                _wsStatusDetail = 'WS 전송 연결됨 - 서버 승인 대기 중';
                console.log('[Frontend WS] 전송 연결됨, 서버 승인 대기 중');
                updateWsStatusLed();
            };
            
            socket.onmessage = function(event) {
                if (socket !== frontendWs) {
                    console.error('[Frontend WS] 현재 연결이 아닌 소켓의 메시지를 무시합니다.');
                    return;
                }
                try {
                    const msg = JSON.parse(event.data);
                    _wsLastServerActivity = Date.now();
                    if (msg.type === 'ping') {
                        if (socket.readyState === WebSocket.OPEN) {
                            socket.send(JSON.stringify({type: 'pong'}));
                        } else {
                            console.error('[Frontend WS] ping 응답 실패: 소켓이 열려 있지 않음', socket.readyState);
                        }
                        updateWsStatusLed();
                        return;
                    }
                    // Queue snapshots can contain thousands of items; do not retain every snapshot in the console.

                    switch (msg.type) {
                        case 'connection_ready': {
                            refreshIllustrationFlow();
                            if (!msg.data || !msg.data.client_id) {
                                throw new Error('connection_ready에 client_id가 없습니다.');
                            }
                            const heartbeatSeconds = Number(msg.data.heartbeat_interval_seconds);
                            const staleSeconds = Number(msg.data.stale_timeout_seconds);
                            if (Number.isFinite(heartbeatSeconds) && heartbeatSeconds > 0
                                    && Number.isFinite(staleSeconds) && staleSeconds >= 0) {
                                _wsHealthTimeoutMs = Math.max(
                                    10000,
                                    (heartbeatSeconds + staleSeconds + 5) * 1000,
                                );
                            } else {
                                console.error('[Frontend WS] 서버 heartbeat 설정값 오류:', msg.data);
                            }
                            _wsConnectionReady = true;
                            _wsStatusDetail = 'WS 연결 정상';
                            updateWsStatusLed();
                            console.log(`[Frontend WS] 서버 승인 완료 client=${msg.data.client_id.slice(0, 8)}`);
                            // 승인된 활성 연결에서만 누락된 큐/스트림 상태를 동기화한다.
                            fetch('/api/queue/status').then(r => r.json()).then(data => {
                                handleQueueUpdated(data);
                            }).catch(e => console.error('[QUEUE] 초기 상태 로드 실패:', e));
                            if (_styleLora.currentProject) void loadStyleProjectImages();
                            syncLighbdActiveStreams();
                            break;
                        }
                        case 'connection_replaced':
                            allowAutoReconnect = false;
                            _wsConnectionReady = false;
                            _wsStatusDetail = '다른 화면의 WS 연결로 교체됨';
                            console.error('[Frontend WS] 다른 화면의 새 연결이 활성화되어 현재 연결이 교체되었습니다.', msg.data);
                            updateWsStatusLed();
                            showToast('다른 화면에서 WS가 연결되어 현재 화면의 실시간 연결이 중지되었습니다.', 'warning');
                            if (socket.readyState === WebSocket.OPEN) {
                                try { socket.close(_WS_REPLACED_CLOSE_CODE, 'replaced'); }
                                catch (e) { console.error('[Frontend WS] 교체된 소켓 종료 실패:', e); }
                            }
                            return;
                        case 'reschedule_changed':
                            handleRescheduleChanged(msg.data);
                            break;
                        case 'reschedule_used':
                            handleRescheduleUsed(msg.data);
                            break;
                        case 'backup_created':
                            handleBackupCreated(msg.data);
                            break;
                        case 'regeneration_completed':
                            handleRegenerationCompleted(msg.data);
                            break;
                        case 'regeneration_failed':
                            handleRegenerationFailed(msg.data);
                            break;
                        case 'backup_filter_ready':
                            // 백그라운드 필터 캐시 빌드 완료 → 드롭다운 최종 갱신
                            if (typeof loadBackupFilters === 'function') loadBackupFilters();
                            break;
                        // 캐릭터 메이커 RAG 태그 자료 설치 진행률
                        case 'character_maker_rag_install_progress':
                            if (typeof handleCmRagInstallProgress === 'function') {
                                handleCmRagInstallProgress(msg.data);
                            }
                            break;
                        // LoRA 학습 진행률
                        case 'lora_training_progress':
                            if (typeof updateLoraTrainingUI === 'function') {
                                updateLoraTrainingUI(msg.data.phase, msg.data);
                            }
                            break;
                        // 봇 LoRA 학습 진행률
                        case 'bot_lora_training_progress':
                            if (typeof updateBotLoraTrainingUI === 'function') {
                                updateBotLoraTrainingUI(msg.data.phase, msg.data);
                            }
                            break;
                        case 'instance_lora_training_progress':
                            if (typeof handleInstanceLoraTrainingProgress === 'function') {
                                handleInstanceLoraTrainingProgress(msg.data);
                            }
                            if (typeof handleStyleLoraTrainingProgress === 'function') {
                                handleStyleLoraTrainingProgress(msg.data);
                            }
                            break;
                        case 'instance_lora_face_extract_progress':
                            if (msg.data && msg.data.phase === 'complete') {
                                loadInstanceLoraGrid();
                            }
                            break;
                        case 'bot_dialogue_face_crop_progress':
                            handleDialogueFaceCropProgress(msg.data);
                            break;
                        case 'instance_lora_analyze_progress':
                            if (msg.data && msg.data.phase === 'completed') {
                                loadInstanceLoraGrid();
                                const result = msg.data.fail_count > 0
                                    ? `분석 완료 (${msg.data.success_count}성공, ${msg.data.fail_count}실패)`
                                    : '이미지 프롬프트 분석 완료';
                                showToast(result, 'success');
                            }
                            break;
                        // 공용 이미지 생성 진행도
                        case 'generation_progress':
                            updateTopProgress(msg.data.value || 0, msg.data.max || 0);
                            break;
                        // lighbd LLM 스트리밍 (우하단 위젯)
                        case 'lighbd_llm_stream':
                            handleLighbdLlmStream(msg.data);
                            break;
                        case 'illustration_auto_feedback_updated':
                            if (msg.data?.question) {
                                const analysisOverlay = document.getElementById('llm-flow-overlay');
                                if (analysisOverlay?._analysisJob?.job_id === msg.data.job_id) renderLlmFlowBody({job: msg.data});
                                break;
                            }
                            handleIllustrationAutoFeedbackUpdate(msg.data);
                            break;
                        case 'enhance_started':
                            showToast(`프롬프트 강화 시작 (${msg.data.char_count}명)`, 'info');
                            break;
                        case 'enhance_completed':
                            showToast(`프롬프트 강화 완료 (${msg.data.blocks_changed}개 변경)`, 'success');
                            break;
                        // 워크플로우 능력 테스트 이벤트
                        case 'wf_test_start':
                            handleWfTestStart(msg.data);
                            break;
                        case 'wf_test_progress':
                            handleWfTestProgress(msg.data);
                            break;
                        case 'wf_test_complete':
                            handleWfTestComplete(msg.data);
                            break;
                        case 'wf_test_stopped':
                            handleWfTestStopped(msg.data);
                            break;
                        // 에셋 생성 모드 이벤트
                        case 'asset_generation_started':
                        case 'asset_generation_progress':
                        case 'asset_generation_completed':
                            handleAssetWsEvent(msg.type, msg.data);
                            break;
                        case 'asset_video_created':
                            handleAssetVideoCreated(msg.data);
                            break;
                        case 'qwen_edit_started':
                        case 'qwen_edit_progress':
                        case 'qwen_edit_completed':
                            handleQwenEditWsEvent(msg.type, msg.data);
                            break;
                        // 통합 큐 이벤트
                        case 'illustration_flow':
                            receiveIllustrationFlow(msg.data, true);
                            break;
                        case 'video_flow':
                            receiveVideoFlow(msg.data, true);
                            break;
                        case 'video_input_flow':
                            receiveVideoInputFlow(msg.data, true);
                            break;
                        case 'lora_feedback_flow':
                            if (typeof receiveLoraFeedbackFlow === 'function') receiveLoraFeedbackFlow(msg.data, true);
                            break;
                        case 'illustration_warning':
                            showToast(msg.data.message, 'warning');
                            break;
                        case 'queue_updated':
                            handleQueueUpdated(msg.data);
                            break;
                        case 'queue_progress':
                            handleQueueProgress(msg.data);
                            break;
                        // 에셋 분석 진행률 이벤트
                        case 'asset_mode_batch_progress':
                        case 'asset_mode_selected_progress':
                            handleAssetAnalyzeProgress(msg.type, msg.data);
                            break;
                        // 태그 분석 진행률 이벤트
                        case 'tag_analysis_progress':
                            _handleTagBatchProgress(msg.data);
                            handleTagAnalysisProgress(msg.data);
                            if (typeof handleStyleLoraTagProgress === 'function') {
                                handleStyleLoraTagProgress(msg.data);
                            }
                            break;
                        case 'auto_match_batch_progress':
                            handleAutoMatchBatchProgress(msg.data);
                            break;
                        case 'data_patch_progress':
                            handleDataPatchProgress(msg.data);
                            break;
                        case 'bot_llm_face_tag_progress':
                            _handleBotLlmFaceTagProgress(msg.data);
                            break;
                        case 'lora_prompt_refine_progress':
                            _handleTagBatchProgress(msg.data);
                            _handleBotLoraBatchRefineProgress(msg.data);
                            _handleBotTestSetupProgress(msg.data);
                            _handleAssetLoraBatchRefineProgress(msg.data);
                            _handleAssetLoraTestSetupProgress(msg.data);
                            _handleLoraPromptRefineProgress(msg.data);
                            if (typeof handleStyleLoraRefineProgress === 'function') {
                                handleStyleLoraRefineProgress(msg.data);
                            }
                            break;
                        case 'text_output':
                            handleTextOutput(msg.data);
                            break;
                        case 'notification_new':
                            handleNotiWsEvent(msg.data);
                            break;
                        // 활성봇 변경(플러그인/프론트 양쪽에서 발생) — 삽화 백업 탭 동기화
                        case 'bot_selected_changed':
                            handleBotSelectedChanged(msg.data);
                            break;
                        // 헤더 시스템 모니터 갱신 (RAM/VRAM/CPU/GPU)
                        case 'system_stats':
                            updateSysmon(msg.data);
                            break;
                    }
                } catch (e) {
                    console.error('[Frontend WS] 메시지 처리 실패:', e);
                }
            };
            
            socket.onclose = function(event) {
                if (socket !== frontendWs) {
                    console.log('[Frontend WS] 이전 소켓의 종료 이벤트를 무시합니다.');
                    return;
                }
                const replaced = !allowAutoReconnect || event.code === _WS_REPLACED_CLOSE_CODE;
                frontendWs = null;
                _wsConnectionReady = false;
                _wsLastServerActivity = 0;
                _wsOpenedAt = 0;
                _wsStatusDetail = replaced
                    ? '다른 화면의 WS 연결로 교체됨 - 버튼을 눌러 다시 연결 가능'
                    : `WS 연결 종료(code=${event.code || 1006}) - 재연결 대기 중`;
                updateWsStatusLed();
                if (replaced) {
                    console.error(`[Frontend WS] 교체된 연결 종료 code=${event.code} reason=${event.reason || ''}`);
                    return;
                }
                console.error(`[Frontend WS] 연결 종료 code=${event.code} reason=${event.reason || ''}, 자동 재연결 예정`);
                _scheduleWsReconnect(2000);
            };

            socket.onerror = function(error) {
                if (socket !== frontendWs) {
                    console.error('[Frontend WS] 이전 소켓의 에러 이벤트를 무시합니다:', error);
                    return;
                }
                console.error('[Frontend WS] 에러:', error);
                _wsConnectionReady = false;
                _wsStatusDetail = 'WS 오류 - 연결 종료 중';
                updateWsStatusLed();
                // 일부 환경에서는 onerror만 발생하고 onclose가 오지 않아
                // 자동 재연결이 안 걸릴 수 있어, 명시적으로 close 하여 onclose(재연결) 경로를 태운다.
                try { socket.close(); }
                catch (e) { console.error('[Frontend WS] 오류 소켓 종료 실패:', e); }
            };
            return socket;
        }

        // ─── 큐 상태 폴백 폴링 (WS 누락 보완) ───
        let _queuePollTimer = null;
        function startQueuePoll() {
            if (_queuePollTimer) return;
            _queuePollTimer = setInterval(() => {
                if (document.hidden && !Object.keys(_tagBatches).length) return;
                fetch('/api/queue/status').then(r => r.json()).then(data => {
                    handleQueueUpdated(data);
                }).catch(error => console.warn('[QUEUE] 작업 상태 조회 실패:', error));
            }, 10000);
        }
        startQueuePoll();

        // ─── WebSocket 이벤트 핸들러 ───
        const textOutputState = {};
        function handleTextOutput(data) {
            if (!data || !data.node_title) return;
            textOutputState[data.node_title] = data;
            const preview = (data.text || '').substring(0, 80) + ((data.text || '').length > 80 ? '...' : '');
            showToast(`[Text] ${data.node_title}: ${preview}`, 'info');
        }

        function getTextOutputByNode(nodeTitle) {
            return textOutputState[nodeTitle] || null;
        }

        function getAllTextOutputs() {
            return Object.values(textOutputState);
        }

        function handleRescheduleChanged(data) {
            // 모든 버튼 상태 업데이트
            const buttons = document.querySelectorAll('.reschedule-btn');
            buttons.forEach(btn => {
                const cardName = btn.closest('.backup-card').dataset.name;
                if (data.scheduled && cardName === data.name) {
                    btn.classList.add('scheduled');
                    btn.innerHTML = '✅ 예약됨 (취소)';
                } else {
                    btn.classList.remove('scheduled');
                    btn.innerHTML = '📅 재전송 예약';
                }
            });
        }

        function handleRescheduleUsed(data) {
            // 예약된 이미지가 사용되었을 때 버튼 상태 업데이트
            const buttons = document.querySelectorAll('.reschedule-btn');
            buttons.forEach(btn => {
                const cardName = btn.closest('.backup-card').dataset.name;
                if (cardName === data.name) {
                    btn.classList.remove('scheduled');
                    btn.innerHTML = '📅 재전송 예약';
                    showToast('재전송 예약된 이미지가 전송되었습니다', 'success');
                }
            });
        }

        async function handleBackupCreated(data) {
            console.log('[Backup] 새 백업 생성:', data.name);
            if (document.getElementById('focus-edit-overlay')) _renderFocusEditPhoto(true);
            if (typeof loadBackups === 'function') {
                await loadBackups(true);
                console.log('[Backup] 목록 갱신 완료');
            }
            // 새 백업이 새 bot_name을 가져올 수 있으므로 필터 드롭다운 갱신
            if (typeof loadBackupFilters === 'function') loadBackupFilters();
        }

        function handleRegenerationCompleted(data) {
            const label = String(data?.label || '재생성');
            const fallbackText = data?.fallback_used ? ' (폴백 사용)' : '';
            console.log('[REGEN] 백그라운드 재생성 완료:', data);
            showToast(`${label} 완료${fallbackText}`, 'success');
        }

        function handleRegenerationFailed(data) {
            const message = String(data?.message || data?.error || '재생성 실패');
            console.error('[REGEN] 백그라운드 재생성 실패:', data);
            showToast(message, 'error');
        }

        // ─── API 호출 ───
        async function fetchJSON(url, options) {
            const resp = await fetch(url, options);
            if (!resp.ok) {
                // 응답 본문의 진짜 에러 사유까지 노출 (CLAUDE.md: 조용한 실패 금지)
                let detail = '';
                try {
                    const ct = resp.headers.get('content-type') || '';
                    if (ct.includes('application/json')) {
                        const j = await resp.json();
                        detail = (j && (j.error || j.message)) ? (j.error || j.message) : JSON.stringify(j).slice(0, 300);
                    } else {
                        detail = (await resp.text()).slice(0, 300);
                    }
                } catch (_) { /* 본문 읽기 실패는 무시 */ }
                if (resp.status === 401) {
                    detail = '로그인이 만료되었거나 필요합니다. 새로고침 후 다시 로그인해 주세요.';
                }
                const method = (options && options.method) || 'GET';
                const msg = `HTTP ${resp.status}${detail ? ' - ' + detail : ''}`;
                console.error(`[fetchJSON] ${method} ${url} 실패: ${msg}`);
                throw new Error(msg);
            }
            return resp.json();
        }

        // ─── 변환 정보 로드 ───
        async function loadConversionInfo() {
            try {
                const info = await fetchJSON('/api/conversion_info');
                renderConversionStatus(info);
            } catch (e) {
                console.error('[CONVERSION_STATUS] 변환 정보 조회 실패:', e);
                renderConversionStatus({error: `서버 연결 실패: ${e.message}`});
            }
        }

        function renderConversionStatus(info) {
            const container = document.getElementById('conversion-status');
            const statusBar = document.getElementById('status-bar');
            if (info.error) {
                statusBar.style.display = '';
                container.innerHTML = `
                    <div class="info-item">
                        <span class="label">상태:</span>
                        <span class="value error">변환 오류</span>
                    </div>
                    <div class="info-item">
                        <span class="label">에러:</span>
                        <span class="value error">${escapeHtml(info.error)}</span>
                    </div>`;
                scheduleIndependentScrollHeightSync();
                return;
            }

            const note = info.note || '';
            const nodeErrors = info.submit_node_errors || {};
            const nodeErrorCount = Object.keys(nodeErrors).length;

            let statusHtml = '';

            if (nodeErrorCount > 0) {
                statusHtml += `
                    <div class="info-item">
                        <span class="label">에러 노드:</span>
                        <span class="value error">${nodeErrorCount}개</span>
                    </div>`;
            }

            if (note) {
                statusHtml += `
                    <div class="info-item">
                        <span class="label">참고:</span>
                        <span class="value">${escapeHtml(note)}</span>
                    </div>`;
            }

            container.innerHTML = statusHtml;
            statusBar.style.display = statusHtml ? '' : 'none';
            scheduleIndependentScrollHeightSync();
        }

        // ─── 백업 목록 로드 (페이지네이션) ───
        let _pendingBackupReload = false;
        async function loadBackups(reset = false) {
            if (paginationState.isLoading) {
                if (reset) _pendingBackupReload = true;
                return;
            }

            paginationState.isLoading = true;
            const filter = paginationState.filter;

            try {
                const params = new URLSearchParams({
                    offset: reset ? 0 : paginationState.offset,
                    // Background refreshes must retain every page already being browsed.
                    limit: reset ? Math.max(paginationState.limit, paginationState.offset, backupsData.length) : paginationState.limit,
                    filter
                });

                const data = await fetchJSON(`/api/backups?${params}`);
                if (reset && backupsData.length > 0 && data.has_more && filter === paginationState.filter) {
                    // Include the old trailing rows displaced by newly inserted/renamed entries.
                    const knownNames = new Set(backupsData.map(backup => backup.name));
                    const addedCount = Math.max(data.total - paginationState.total,
                        data.backups.filter(backup => !knownNames.has(backup.name)).length);
                    if (addedCount > 0) {
                        params.set('offset', data.offset + data.limit);
                        params.set('limit', addedCount);
                        const tail = await fetchJSON(`/api/backups?${params}`);
                        if (tail.total !== data.total) {
                            console.info('[Backup] 갱신 중 목록 변경으로 다시 조회합니다:', data.total, tail.total);
                            _pendingBackupReload = true;
                            return;
                        }
                        data.backups.push(...tail.backups);
                        data.limit += tail.limit;
                        data.total = tail.total;
                        data.has_more = tail.has_more;
                    }
                }
                if (filter !== paginationState.filter) {
                    console.info('[Backup] 필터 변경 전 목록 응답 생략:', filter);
                    return;
                }

                if (reset) {
                    backupsData = data.backups;
                } else {
                    const knownNames = new Set(backupsData.map(backup => backup.name));
                    backupsData = backupsData.concat(data.backups.filter(backup => !knownNames.has(backup.name)));
                }

                paginationState.total = data.total;
                paginationState.offset = data.offset + data.limit;
                paginationState.hasMore = data.has_more;

                renderBackups(reset ? backupsData : data.backups, !reset);
                updateStatsBar();
                await loadConversionInfo();
                await loadRescheduleStatus();
            } catch (e) {
                console.error('[Backup] 목록 조회 실패:', {filter, reset, error: e});
                if (backupsData.length === 0) {
                    document.getElementById('content').innerHTML =
                        `<div class="empty-state"><h2>서버 연결 실패</h2><p>${escapeHtml(e.message)}</p></div>`;
                } else {
                    showToast('백업 목록 갱신 실패: ' + e.message, 'error');
                }
            } finally {
                paginationState.isLoading = false;
                if (_pendingBackupReload) {
                    _pendingBackupReload = false;
                    loadBackups(true);
                }
            }
        }

        function updateStatsBar() {
            const statsBar = document.getElementById('stats-bar');
            const totalCount = document.getElementById('total-count');
            const loadedCount = document.getElementById('loaded-count');
            const loadMoreBtn = document.getElementById('load-more-btn');
            
            if (paginationState.total > 0) {
                statsBar.style.display = document.getElementById('tab-backup-content').classList.contains('active')
                    ? 'flex' : 'none';
                totalCount.textContent = paginationState.total;
                loadedCount.textContent = `${backupsData.length}개 로드됨`;
                
                if (paginationState.hasMore) {
                    loadMoreBtn.style.display = 'block';
                    loadMoreBtn.textContent = `더 불러오기 (${paginationState.total - backupsData.length}개 남음)`;
                } else {
                    loadMoreBtn.style.display = 'none';
                }
            } else {
                statsBar.style.display = 'none';
                loadMoreBtn.style.display = 'none';
            }
        }

        async function loadMore() {
            if (!paginationState.hasMore || paginationState.isLoading) return;
            await loadBackups(false);
        }

        // ─── 모아보기 필터 ───
        let _backupFiltersLoading = false;
        let _backupFilterPollTimer = null;
        async function loadBackupFilters() {
            // 필터 드롭다운 옵션(전체/restore 프로세스/bot_name별)을 서버에서 가져와 채운다.
            // 백업이 많을 때 서버는 백그라운드에서 캐시를 점진 빌드한다. building=true 면
            // 부분 카운트를 보여주고, (1) 빌드 완료 WS(backup_filter_ready) 즉시 갱신,
            // (2) WS가 누락되더라도 주기 폴링으로 갱신한다.
            if (_backupFiltersLoading) return;
            _backupFiltersLoading = true;
            try {
                const data = await fetchJSON('/api/backups/filters');
                const sel = document.getElementById('backup-filter');
                if (!sel) return;
                const cur = paginationState.filter || 'all';
                const building = !!data.building;
                const buildTag = building
                    ? ` (집계중 ${data.scanned ?? 0}/${data.total_files ?? 0})`
                    : '';
                let html = '';
                for (const it of (data.filters || [])) {
                    const cnt = (it.key === 'all') ? `${it.count}${buildTag}` : it.count;
                    html += `<option value="${escapeAttr(it.key)}">${escapeHtml(it.label)} (${cnt})</option>`;
                }
                sel.innerHTML = html;
                sel.title = building
                    ? `필터 집계 진행 중: ${data.scanned ?? 0}/${data.total_files ?? 0} 스캔됨 (완료 시 자동 갱신)`
                    : '';
                // 현재 선택된 필터 유지 (필터 목록에 없으면 전체로 복귀)
                if ([...sel.options].some(o => o.value === cur)) {
                    sel.value = cur;
                } else {
                    paginationState.filter = 'all';
                    sel.value = 'all';
                }
                // 빌드 중이면 폴링 재시도 (WS 백업). 타이머 중복 누적 방지.
                if (building) {
                    if (_backupFilterPollTimer) clearTimeout(_backupFilterPollTimer);
                    _backupFilterPollTimer = setTimeout(() => {
                        _backupFilterPollTimer = null;
                        _backupFiltersLoading = false; // 폴링 재진입 허용
                        loadBackupFilters();
                    }, 1500);
                } else if (_backupFilterPollTimer) {
                    clearTimeout(_backupFilterPollTimer);
                    _backupFilterPollTimer = null;
                }
            } catch (e) {
                console.error('[BACKUP_FILTER] 필터 목록 로드 실패:', e);
            } finally {
                _backupFiltersLoading = false;
            }
        }

        function onBackupFilterChange() {
            const sel = document.getElementById('backup-filter');
            if (!sel) return;
            paginationState.filter = sel.value || 'all';
            // 필터 변경 시 페이지네이션 초기화 후 재조회
            paginationState.offset = 0;
            paginationState.hasMore = true;
            paginationState.total = 0;
            backupsData = [];
            renderBackups([]);
            window.scrollTo({top: 0, behavior: 'instant'});
            loadBackups(true);
        }

        function renderVideoPromptDetails(record, finalPrompt) {
            const source = String(record?.video_instruction_source || '').trim().toLowerCase();
            const sourceLabel = source === 'llm'
                ? 'LLM 자동 생성'
                : source === 'user'
                    ? '유저 입력'
                    : record?.video_auto_instruction === true
                        ? 'LLM 자동 생성'
                        : record?.video_auto_instruction === false
                            ? '유저 입력'
                            : '기록 없음';
            const instruction = String(record?.video_instruction || '').trim();
            const instructionOriginal = String(
                record?.video_instruction_original || ''
            );
            const visualContext = String(record?.video_visual_context || '').trim();
            const visualContextSource = String(record?.video_visual_context_source || '').trim().toLowerCase();
            const visualContextLabel = visualContextSource === 'prompt'
                ? 'Visual Context · 생성 프롬프트 해석'
                : visualContextSource === 'image'
                    ? 'Visual Context · 그림 직접 분석'
                    : 'Visual Context';
            const prompt = String(finalPrompt || '').trim();
            const renderValue = (value) => value
                ? escapeHtml(value).replace(/\n/g, '<br>')
                : '<span style="color:var(--text2)">(기록 없음)</span>';
            return `
                <b>[연출 지시 출처]</b><br>${escapeHtml(sourceLabel)}<br><br>
                ${instructionOriginal ? `<b>[다듬기 전 사용자 원문]</b><br>${renderValue(instructionOriginal)}<br><br>` : ''}
                <b>[연출 지시]</b><br>${renderValue(instruction)}<br><br>
                <b>[${escapeHtml(visualContextLabel)}]</b><br>${renderValue(visualContext)}<br><br>
                <b>[최종 H3 프롬프트]</b><br>${renderValue(prompt)}
            `;
        }

        function renderBackups(backups, append = false) {
            const content = document.getElementById('content');
            if (!backups || backups.length === 0) {
                if (!append) {
                    content.innerHTML = '<div class="empty-state"><h2>삽화 백업 없음</h2><p>이미지가 생성되면 여기에 표시됩니다</p></div>';
                    promptDataMap.clear();
                }
                return;
            }

            let grid = content.querySelector('.backup-grid');
            if (!grid) {
                grid = document.createElement('div');
                grid.className = 'backup-grid';
                content.replaceChildren(grid);
            }
            const existing = new Map(Array.from(grid.children, card => [card.dataset.name, card]));
            const savedScroll = window.scrollY;
            const anchor = !append && savedScroll > 0
                ? Array.from(existing.values()).find(card => {
                    const rect = card.getBoundingClientRect();
                    return rect.bottom > 0 && rect.top < window.innerHeight;
                }) : null;
            const anchorTop = anchor?.getBoundingClientRect().top;
            const retained = new Set();
            let cursor = append ? null : grid.firstElementChild;
            const template = document.createElement('template');
            for (const b of backups) {
                retained.add(b.name);
                const previous = existing.get(b.name);
                const renderData = JSON.stringify(b);
                if (previous?._backupRenderData === renderData) {
                    if (!append) {
                        if (previous !== cursor) grid.insertBefore(previous, cursor);
                        cursor = previous.nextElementSibling;
                    }
                    continue;
                }
                const dateStr = formatDate(b.mtime);
                const info = b.conversion_info || {};
                const positive = b.positive || '';
                const negative = b.negative || '';
                const hasPrompt = positive || negative;
                const isVideoPrompt = b.is_video_prompt === true;
                const isScheduled = b.is_scheduled || false;

                // 실행 출처 딱지: Modal=M, Vast=V, 챈섭=S, 로컬 GPU=배지 없음.
                // execution_source가 없는 구 백업은 provider로 chansub 여부만 fallback.
                const _src = String(info.execution_source || '').toLowerCase();
                const sourceKind = (_src === 'modal' || _src === 'vast' || _src === 'chansub')
                    ? _src
                    : (String(info.provider || '').toLowerCase() === 'chansub' ? 'chansub' : '');
                const sourceTitle = sourceKind === 'modal'
                    ? 'Modal 원격 ComfyUI 생성'
                    : (sourceKind === 'vast' ? 'Vast 원격 ComfyUI 생성' : '챈섭 API 생성');
                const legacySourceLetter = `${sourceKind === 'modal' ? 'M' : 'S'}`;
                const sourceLetter = sourceKind === 'vast' ? 'V' : legacySourceLetter;
                const sourceBadge = sourceKind
                    ? `<span class="source-badge source-${sourceKind}" title="${sourceTitle}">${sourceLetter}</span>`
                    : '';
                // animated 삽화: A 딱지(M 아래 고정 위치). 기본은 정지 poster(첫 프레임),
                // 호버 시 원본(animated)으로 src 교체 → 한 번에 한 장만 움직여 력 방지.
                const animBadge = b.is_animated
                    ? `<span class="source-badge source-anim" title="animated">A</span>`
                    : '';
                const badges = (sourceBadge || animBadge)
                    ? `<div class="badge-stack">${sourceBadge}${animBadge}</div>`
                    : '';
                const posterSrc = b.poster_url || b.image_url;
                const animAttrs = b.is_animated
                    ? `data-poster-src="${escapeAttr(posterSrc)}" data-anim-src="${escapeAttr(b.image_url)}" onmouseenter="this.src=this.dataset.animSrc" onmouseleave="this.src=this.dataset.posterSrc"`
                    : '';

                // Store prompt data in Map (avoids data-attribute truncation issues)
                promptDataMap.set(b.name, { positive, negative, image_url: b.image_url || '', raw_url: b.raw_url || '', enhanced_positive: b.enhanced_positive || '', wildcard_info: b.wildcard_info || {}, conversion_info: b.conversion_info || {}, video_instruction: b.video_instruction || '', video_instruction_original: b.video_instruction_original || '', video_instruction_source: b.video_instruction_source || '', video_auto_instruction: b.video_auto_instruction, video_visual_context: b.video_visual_context || '', video_visual_context_source: b.video_visual_context_source || '' });

                const cardClass = 'backup-card';

                const html = `
                <div class="${cardClass}" data-name="${escapeAttr(b.name)}">
                    <div class="card-image-area">
                        ${badges}
                        <img class="backup-img${b.is_animated ? ' is-anim' : ''}"
                             src="${escapeAttr(posterSrc)}" alt="${escapeAttr(b.name)}"
                             loading="lazy" ${animAttrs}
                             onclick="openLightbox('${escapeAttr(b.image_url)}')">
                        <div class="regen-result" id="regen-${escapeAttr(b.name)}">
                            <img src="" alt="재생성 결과">
                            <button class="close-btn" onclick="closeRegen('${escapeAttr(b.name)}')">&times;</button>
                        </div>
                    </div>
                    <div class="card-body">
                        <div class="card-meta">${info.bot_name ? `<span class="bot-badge">${escapeHtml(info.bot_name)}</span> ` : ''}${info.gen_method ? `<span class="gen-method-badge">${escapeHtml(info.gen_method)}</span> ` : ''}${escapeHtml(dateStr)} &mdash; ${escapeHtml(b.name)}${info.generation_time ? ` · ⏱️ ${info.generation_time.toFixed(1)}초` : ''}</div>
                        <div class="card-actions">
                            <button class="regen-btn" onclick="regenerate('${escapeAttr(b.name)}', this)"
                                    ${b.is_animated ? 'disabled title="영상 백업에는 재생성을 사용할 수 없습니다"' : (b.has_prompt ? 'title="새 시드로 다시 생성합니다"' : 'disabled title="프롬프트 없음"')}>
                                🔄 재생성
                            </button>
                            <button class="edit-prompt-btn" onclick="event.stopPropagation(); openPromptModal(this)"
                                    data-name="${escapeAttr(b.name)}"
                                    data-image-url="${escapeAttr(b.image_url)}"
                                    ${b.is_animated ? 'disabled title="영상 백업에는 프롬프트 수정을 사용할 수 없습니다"' : (b.has_prompt ? '' : 'disabled title="프롬프트 없음"')}>
                                ✏️ 수정
                            </button>
                            <button class="reschedule-btn ${isScheduled ? 'scheduled' : ''}" onclick="reschedule('${escapeAttr(b.name)}', this)"
                                    ${b.has_prompt ? '' : 'disabled title="프롬프트 없음"'}>
                                ${isScheduled ? '✅ 예약됨' : '📅 예약'}
                            </button>
                            <button onclick="event.stopPropagation(); openLlmFlowModal('${escapeAttr(b.name)}', {analysis: true})"
                                    title="궁금한 점을 입력한 뒤 이미지와 생성 기록에서 원인을 분석합니다">
                                🔍 이미지 분석
                            </button>
                            <button onclick="toggleChat('${escapeAttr(b.name)}')">
                                💬 채팅
                            </button>
                            <button onclick="openLlmFlowModal('${escapeAttr(b.name)}')"
                                    title="이 백업을 만든 LLM 단계의 입력/출력을 자르기 없이 보여줍니다">
                                🧩 LLM 흐름
                            </button>
                            <button class="video-backup-btn" onclick="event.stopPropagation(); openVideoWorkspace('${escapeAttr(b.name)}')"
                                    ${b.has_raw ? 'title="깨끗한 원본(_raw 또는 비합성 원본)으로 MiniMax H3 영상화를 시작합니다"' : 'disabled title="영상화에 쓸 대사 없는 원본이 없는 백업입니다"'}>
                                🎬 영상화
                            </button>
                            <button class="video-reprocess-btn" onclick="event.stopPropagation(); openBackupVideoReprocess('${escapeAttr(b.name)}')"
                                    ${b.is_animated ? 'title="이 animated 백업을 새 파일로 후처리합니다"' : 'disabled title="영상 후처리는 animated AVIF/WebP 백업에서만 사용할 수 있습니다"'}>
                                영상 후처리
                            </button>
                            <button class="delete-backup-btn" onclick="deleteBackup('${escapeAttr(b.name)}', this)" title="이미지와 메타데이터를 삭제합니다">
                                🗑️ 삭제
                            </button>
                        </div>
                        ${hasPrompt ? `
                            <div style="display:flex; align-items:center;">
                                <button class="prompt-toggle-btn" onclick="togglePrompt('${escapeAttr(b.name)}')" id="prompt-btn-${escapeAttr(b.name)}">📝 프롬프트 펼치기</button>
                                ${b.enhanced_positive ? `<button class="enhanced-toggle-btn" onclick="toggleEnhancedPrompt('${escapeAttr(b.name)}')" id="enhanced-btn-${escapeAttr(b.name)}">✨ 강화 프롬프트</button><button class="enhanced-report-btn" onclick="openEnhanceReportModal('${escapeAttr(b.name)}')">📋 리포트</button>` : ''}
                            </div>
                            <div class="prompt-preview" id="prompt-${escapeAttr(b.name)}">${isVideoPrompt ? renderVideoPromptDetails(b, positive) : `[긍정]\n${escapeHtml(positive)}\n\n[부정]\n${escapeHtml(negative)}`}</div>
                            ${b.enhanced_positive ? `<div class="enhanced-preview" id="enhanced-${escapeAttr(b.name)}"></div>` : ''}
                        ` : '<div class="prompt-preview" style="color:var(--text2)">프롬프트 없음</div>'}
                        <div class="conversion-info" id="conv-${escapeAttr(b.name)}" style="display:none; margin-top:8px;">
                            ${renderConversionInfoContent(info)}
                        </div>
                        <div class="chat-content" id="chat-${escapeAttr(b.name)}" style="display:none; margin-top:8px;"></div>
                    </div>
                </div>`;
                template.innerHTML = html;
                const card = template.content.firstElementChild;
                card._backupRenderData = renderData;
                if (previous) {
                    previous.replaceWith(card);
                    if (cursor === previous) cursor = card;
                }
                if (!append || !previous) {
                    if (card !== cursor) grid.insertBefore(card, cursor);
                    if (!append) cursor = card.nextElementSibling;
                }
                if (previous?.querySelector('.prompt-preview.expanded')) togglePrompt(b.name);
                if (previous?.querySelector('.enhanced-preview.expanded')) toggleEnhancedPrompt(b.name);
            }
            if (!append) {
                for (const [name, card] of existing) {
                    if (!retained.has(name)) {
                        card.remove();
                        promptDataMap.delete(name);
                    }
                }
                const nextAnchor = anchor && Array.from(grid.children).find(card => card.dataset.name === anchor.dataset.name);
                if (nextAnchor) {
                    window.scrollBy({top: nextAnchor.getBoundingClientRect().top - anchorTop, behavior: 'instant'});
                } else if (savedScroll > 0) {
                    window.scrollTo({top: savedScroll, behavior: 'instant'});
                }
            }
        }

        function renderConversionInfoContent(info) {
            if (!info || Object.keys(info).length === 0) {
                return '<span class="ok-text">변환 정보 없음</span>';
            }

            let html = '';

            // 에러
            if (info.error) {
                html += `<div class="section-title">⚠ 변환 에러</div>`;
                html += `<div class="error-item">${escapeHtml(info.error)}</div>`;
            }

            // 미사용 노드
            const unused = info.unused_nodes || [];
            if (unused.length > 0) {
                html += `<div class="section-title">미사용 노드 (${unused.length}개)</div>`;
                for (const n of unused) {
                    html += `<div class="node-item">[${escapeHtml(n.id)}] ${escapeHtml(n.type)} — ${escapeHtml(n.title)}</div>`;
                }
            }

            // 제출 시 노드 에러
            const nodeErrors = info.submit_node_errors || {};
            const errorKeys = Object.keys(nodeErrors);
            if (errorKeys.length > 0) {
                html += `<div class="section-title">노드 에러 (${errorKeys.length}개)</div>`;
                for (const key of errorKeys) {
                    const err = nodeErrors[key];
                    const msg = typeof err === 'string' ? err : JSON.stringify(err);
                    html += `<div class="error-item">[${escapeHtml(key)}] ${escapeHtml(msg.substring(0, 200))}</div>`;
                }
            }

            // 정상
            if (!info.error && unused.length === 0 && errorKeys.length === 0) {
                html += `<span class="ok-text">✓ 변환 정상 (API 노드 ${info.api_node_count || '?'}개)</span>`;
            }

            return html;
        }

        // ─── 프롬프트 펼치기/접기 ───
        function togglePrompt(name) {
            const el = document.getElementById('prompt-' + name);
            const btn = document.getElementById('prompt-btn-' + name);
            if (el) {
                el.classList.toggle('expanded');
                if (el.classList.contains('expanded')) {
                    btn.textContent = '📝 프롬프트 접기';
                } else {
                    btn.textContent = '📝 프롬프트 펼치기';
                }
            }
        }

        // ─── 강화 프롬프트 펼치기/접기 ───
        function toggleEnhancedPrompt(name) {
            const el = document.getElementById('enhanced-' + name);
            const btn = document.getElementById('enhanced-btn-' + name);
            if (!el) return;
            if (el.classList.contains('expanded')) {
                el.classList.remove('expanded');
                btn.textContent = '✨ 강화 프롬프트';
                return;
            }
            // diff 계산 후 표시
            const data = promptDataMap.get(name);
            if (!data || !data.enhanced_positive) return;
            const original = data.positive || '';
            const enhanced = data.enhanced_positive;
            el.innerHTML = '[강화 긍정]\n' + renderDiff(original, enhanced);
            el.classList.add('expanded');
            btn.textContent = '✨ 강화 프롬프트 접기';
        }

        // ─── 강화 프롬프트 리포트 ───
        let reportTargetName = null;

        function openEnhanceReportModal(name) {
            const data = promptDataMap.get(name);
            if (!data || !data.enhanced_positive) return;
            reportTargetName = name;
            document.getElementById('report-original').value = data.positive || '';
            document.getElementById('report-enhanced').value = data.enhanced_positive || '';
            document.getElementById('report-reason').value = '';
            document.getElementById('report-submit-btn').disabled = false;
            document.getElementById('report-submit-text').textContent = '리포트 제출';

            // NSFW 와일드카드 정보 표시 (항상 표시)
            const wcSection = document.getElementById('report-wildcard-section');
            const wcContent = document.getElementById('report-wildcard-content');
            const wcInfo = data.wildcard_info || {};
            wcSection.style.display = 'block';
            if (wcInfo.has_wildcards && wcInfo.characters) {
                let wcHtml = '';
                for (const c of wcInfo.characters) {
                    if (c.nsfw_replaced && c.nsfw_replaced.length > 0) {
                        wcHtml += `<div style="margin-bottom:6px;"><strong style="color:var(--accent);">${escapeHtml(c.name)}</strong>: <span style="color:var(--warning);">${c.nsfw_replaced.map(s => escapeHtml(s)).join(', ')}</span></div>`;
                    }
                    if (c.outfit_llm_raw) {
                        wcHtml += `<div style="margin-bottom:8px; padding:4px 8px; background:var(--surface2); border-radius:4px;"><strong>${escapeHtml(c.name)} LLM 원본:</strong><br><span style="color:var(--text2); font-size:0.78rem;">${escapeHtml(c.outfit_llm_raw)}</span></div>`;
                    }
                }
                wcContent.innerHTML = wcHtml || '<span style="color:var(--text2);">데이터 없음</span>';
            } else if (Object.keys(wcInfo).length > 0) {
                wcContent.innerHTML = '<span style="color:var(--text2);">미사용</span>';
            } else {
                wcContent.innerHTML = '<span style="color:var(--text2);">데이터 없음 (이전 버전 백업)</span>';
            }

            // Chat / Slot 영역 초기화
            const chatEl = document.getElementById('report-chat');
            const chatLoading = document.getElementById('report-chat-loading');
            const chatEmpty = document.getElementById('report-chat-empty');
            const slotEl = document.getElementById('report-slot');
            const slotEmpty = document.getElementById('report-slot-empty');
            chatEl.style.display = 'none'; chatEl.value = '';
            chatLoading.style.display = 'none';
            chatEmpty.style.display = 'none';
            slotEl.style.display = 'none'; slotEl.value = '';
            slotEmpty.style.display = 'none';

            document.getElementById('enhance-report-modal').classList.add('visible');

            // Chat 데이터 fetch
            chatLoading.style.display = 'block';
            fetch(`/api/backup_chat?name=${encodeURIComponent(name)}`)
                .then(r => r.json())
                .then(result => {
                    chatLoading.style.display = 'none';
                    const chat = (result.chat || '').trim();
                    if (chat) {
                        chatEl.value = chat;
                        chatEl.style.display = 'block';

                        // [SLOT] 섹션 추출
                        const slotMatch = chat.match(/\[SLOT\]\s*([\s\S]*?)(?=\n\s*\[|$)/i)
                            || data.positive.match(/\[SLOT\]\s*([\s\S]*?)(?=\n\s*\[|$)/i);
                        if (slotMatch && slotMatch[1].trim()) {
                            slotEl.value = slotMatch[1].trim();
                            slotEl.style.display = 'block';
                        } else {
                            slotEmpty.style.display = 'block';
                        }
                    } else {
                        // positive에서도 [SLOT] 확인
                        const slotMatch = data.positive.match(/\[SLOT\]\s*([\s\S]*?)(?=\n\s*\[|$)/i);
                        if (slotMatch && slotMatch[1].trim()) {
                            slotEl.value = slotMatch[1].trim();
                            slotEl.style.display = 'block';
                        }
                        chatEmpty.style.display = 'block';
                        if (!slotMatch) slotEmpty.style.display = 'block';
                    }
                })
                .catch(() => {
                    chatLoading.style.display = 'none';
                    chatEmpty.style.display = 'block';
                    slotEmpty.style.display = 'block';
                });
        }

        function closeEnhanceReportModal() {
            document.getElementById('enhance-report-modal').classList.remove('visible');
            reportTargetName = null;
        }

        async function openReportListView() {
            const modal = document.getElementById('report-list-modal');
            const content = document.getElementById('report-list-content');
            content.innerHTML = '<div class="report-list-empty">불러오는 중...</div>';
            modal.classList.add('visible');
            try {
                const resp = await fetch('/api/enhance_report');
                const result = await resp.json();
                if (result.ok && result.content) {
                    // 마크다운을 간단히 HTML로 변환
                    content.innerHTML = simpleMarkdownToHtml(result.content);
                } else {
                    content.innerHTML = '<div class="report-list-empty">리포트가 없습니다.</div>';
                }
            } catch (e) {
                content.innerHTML = '<div class="report-list-empty">불러오기 실패: ' + escapeHtml(e.message) + '</div>';
            }
        }

        function closeReportListModal() {
            document.getElementById('report-list-modal').classList.remove('visible');
        }


        async function clearReportList() {
            if (!confirm('모든 리포트를 삭제하시겠습니까? 이 작업은 되돌릴 수 없습니다.')) return;
            try {
                const resp = await fetch('/api/enhance_report', { method: 'DELETE' });
                const result = await resp.json();
                if (result.ok) {
                    alert('리포트가 모두 삭제되었습니다.');
                } else {
                    alert('삭제 실패: ' + (result.error || '알 수 없는 오류'));
                }
            } catch (e) {
                alert('전송 오류: ' + e.message);
            }
        }

        function simpleMarkdownToHtml(md) {
            let html = escapeHtml(md);
            // 헤딩
            html = html.replace(/^### (.+)$/gm, '<h3 style="color:var(--accent);margin:10px 0 4px;">$1</h3>');
            html = html.replace(/^## (.+)$/gm, '<h2 style="color:var(--accent);margin:14px 0 6px;font-size:1rem;">$1</h2>');
            html = html.replace(/^# (.+)$/gm, '<h1 style="color:var(--accent);margin:0 0 10px;font-size:1.1rem;">$1</h1>');
            // 볼드
            html = html.replace(/\*\*(.+?)\*\*/g, '<strong style="color:var(--text);">$1</strong>');
            // 인라인 코드
            html = html.replace(/`([^`]+)`/g, '<code style="background:var(--surface2);padding:1px 5px;border-radius:3px;font-size:0.8rem;">$1</code>');
            // 코드 블록
            html = html.replace(/```([\s\S]*?)```/g, '<pre style="background:var(--surface2);padding:8px;border-radius:4px;overflow-x:auto;font-size:0.8rem;margin:6px 0;">$1</pre>');
            // 구분선
            html = html.replace(/^---$/gm, '<hr style="border:none;border-top:1px solid var(--border);margin:12px 0;">');
            // 인용
            html = html.replace(/^&gt; (.+)$/gm, '<blockquote style="color:var(--text2);border-left:3px solid var(--accent2);padding-left:10px;margin:6px 0;">$1</blockquote>');
            // 줄바꿈
            html = html.replace(/\n/g, '<br>');
            return html;
        }

        async function submitEnhanceReport() {
            if (!reportTargetName) return;
            const data = promptDataMap.get(reportTargetName);
            if (!data) return;

            const reason = document.getElementById('report-reason').value.trim();
            if (!reason) {
                alert('리포트 사유를 입력해주세요.');
                return;
            }

            const btn = document.getElementById('report-submit-btn');
            const btnText = document.getElementById('report-submit-text');
            btn.disabled = true;
            btnText.textContent = '제출 중...';

            try {
                const resp = await fetch('/api/enhance_report', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        original_positive: data.positive || '',
                        enhanced_positive: data.enhanced_positive || '',
                        wildcard_info: data.wildcard_info || {},
                        reason: reason,
                        chat_content: document.getElementById('report-chat').value || '',
                        slot: document.getElementById('report-slot').value || ''
                    })
                });
                const result = await resp.json();
                if (result.ok) {
                    btnText.textContent = '✅ 제출 완료';
                    setTimeout(() => closeEnhanceReportModal(), 1000);
                } else {
                    alert('리포트 저장 실패: ' + (result.error || '알 수 없는 오류'));
                    btn.disabled = false;
                    btnText.textContent = '리포트 제출';
                }
            } catch (e) {
                alert('리포트 전송 오류: ' + e.message);
                btn.disabled = false;
                btnText.textContent = '리포트 제출';
            }
        }

        // ─── Diff 렌더링 (원본 대비 변경 부분 노랑 하이라이트) ───
        function renderDiff(original, enhanced) {
            // 토큰 단위(콤마/줄바꿈 기준)로 분리하여 diff
            const origTokens = splitToTokens(original);
            const enhTokens = splitToTokens(enhanced);
            const origSet = new Set(origTokens.map(t => t.trim().toLowerCase()).filter(t => t));

            let html = '';
            for (const token of enhTokens) {
                const trimmed = token.trim().toLowerCase();
                if (trimmed && !origSet.has(trimmed)) {
                    // 원본에 없는 토큰 = 변경/추가된 부분
                    html += `<span class="diff-highlight">${escapeHtml(token)}</span>`;
                } else {
                    html += escapeHtml(token);
                }
            }
            return html;
        }

        function splitToTokens(text) {
            // 콤마, 줄바꿈, 대괄호 섹션 헤더를 기준으로 토큰 분리
            const result = [];
            let current = '';
            for (let i = 0; i < text.length; i++) {
                const ch = text[i];
                if (ch === ',' || ch === '\n') {
                    if (current) result.push(current);
                    result.push(ch);
                    current = '';
                } else {
                    current += ch;
                }
            }
            if (current) result.push(current);
            return result;
        }

