        function snapVideoFastDimension(value) {
            if (!Number.isFinite(value) || value <= 0) {
                console.error('[VIDEO_UI] FAST 해상도 스냅값 오류:', value);
                return null;
            }
            return Math.max(
                VIDEO_FAST_RESOLUTION_MULTIPLE,
                Math.floor(value / VIDEO_FAST_RESOLUTION_MULTIPLE + 0.5)
                    * VIDEO_FAST_RESOLUTION_MULTIPLE,
            );
        }

        function chooseVideoFastAspectRatio(width, height, supportedKeys = Object.keys(VIDEO_FAST_ASPECT_RATIOS)) {
            if (!Number.isFinite(width) || !Number.isFinite(height) || width <= 0 || height <= 0) {
                console.error('[VIDEO_UI] 자동 화면 비율 계산용 원본 크기 오류:', {width, height});
                return '';
            }
            const sourceRatio = width / height;
            return supportedKeys.reduce((best, key) => {
                const pair = VIDEO_FAST_ASPECT_RATIOS[key];
                if (!pair) {
                    console.error('[VIDEO_UI] 자동 화면 비율 후보 오류:', key);
                    return best;
                }
                const distance = Math.abs(Math.log(sourceRatio / (pair[0] / pair[1])));
                return !best || distance < best.distance ? {key, distance} : best;
            }, null)?.key || '';
        }

        function calculateVideoFastResolution(
            aspectRatio,
            qualityLevel,
            nativeShortEdge = VIDEO_FAST_NATIVE_MAX_SHORT_EDGE,
            nativeLongEdge = VIDEO_FAST_NATIVE_MAX_LONG_EDGE,
        ) {
            const pair = VIDEO_FAST_ASPECT_RATIOS[aspectRatio];
            const targetMp = VIDEO_FAST_QUALITY_MP[qualityLevel];
            if (!pair || targetMp === undefined) {
                console.error('[VIDEO_UI] FAST 해상도 계산 선택값 오류:', {
                    aspectRatio,
                    qualityLevel,
                });
                return null;
            }
            if (qualityLevel === 'native') {
                const nativeScale = Math.min(
                    nativeLongEdge / Math.max(...pair),
                    nativeShortEdge / Math.min(...pair),
                );
                const width = snapVideoFastDimension(pair[0] * nativeScale);
                const height = snapVideoFastDimension(pair[1] * nativeScale);
                if (!width || !height) return null;
                return {
                    aspectRatio,
                    qualityLevel,
                    targetMp: Math.round(width * height) / 1000000,
                    width,
                    height,
                };
            }
            return calculateVideoTargetMpResolution(
                aspectRatio,
                targetMp,
                qualityLevel,
            );
        }

        function calculateVideoTargetMpResolution(aspectRatio, targetMp, qualityLevel) {
            const pair = VIDEO_FAST_ASPECT_RATIOS[aspectRatio];
            if (!pair || !Number.isFinite(targetMp) || targetMp <= 0) {
                console.error('[VIDEO_UI] MP 해상도 계산값 오류:', {
                    aspectRatio,
                    targetMp,
                    qualityLevel,
                });
                return null;
            }
            const squareEdge = snapVideoFastDimension(Math.sqrt(targetMp * 1000000));
            const ratio = pair[0] / pair[1];
            const width = snapVideoFastDimension(squareEdge * Math.sqrt(ratio));
            const height = snapVideoFastDimension(squareEdge / Math.sqrt(ratio));
            if (!width || !height) return null;
            return {aspectRatio, qualityLevel, targetMp, width, height};
        }

        function calculateVideoRefResolution(aspectRatio, qualityLevel) {
            if (!VIDEO_FAST_ASPECT_RATIOS[aspectRatio]
                    || VIDEO_FAST_QUALITY_MP[qualityLevel] === undefined) {
                console.error('[VIDEO_UI] REF 해상도 계산 선택값 오류:', {
                    aspectRatio,
                    qualityLevel,
                });
                return null;
            }
            if (qualityLevel !== VIDEO_REF_DEFAULT_QUALITY_LEVEL) {
                return calculateVideoFastResolution(aspectRatio, qualityLevel);
            }
            if (aspectRatio === VIDEO_REF_DEFAULT_ASPECT_RATIO) {
                return {
                    aspectRatio,
                    qualityLevel,
                    targetMp: VIDEO_REF_DEFAULT_TARGET_MP,
                    width: VIDEO_REF_DEFAULT_WIDTH,
                    height: VIDEO_REF_DEFAULT_HEIGHT,
                };
            }
            return calculateVideoTargetMpResolution(
                aspectRatio,
                VIDEO_REF_DEFAULT_TARGET_MP,
                qualityLevel,
            );
        }

        function calculateVideoFast768Resolution(aspectRatio) {
            if (!VIDEO_FAST_768_ASPECT_KEYS.includes(aspectRatio)) {
                console.error('[VIDEO_UI] 고속 768p 화면 비율 오류:', aspectRatio);
                return null;
            }
            const result = calculateVideoFastResolution(aspectRatio, 'native');
            if (!result || Math.min(result.width, result.height) !== VIDEO_FAST_NATIVE_MAX_SHORT_EDGE) {
                console.error('[VIDEO_UI] 고속 768p 최소변 계산 오류:', result);
                return null;
            }
            return result;
        }

        function calculateVideoFastModeResolution(aspectRatio, qualityLevel, mode = '') {
            const selectedMode = mode || document.getElementById('video-generation-mode')?.value || 'i2v';
            if (selectedMode === 'ref2v') {
                return calculateVideoRefResolution(aspectRatio, qualityLevel);
            }
            if (qualityLevel === 'native') {
                return calculateVideoFast768Resolution(aspectRatio);
            }
            if (!VIDEO_FAST_768_ASPECT_KEYS.includes(aspectRatio)) {
                console.error('[VIDEO_UI] 고속 화면 비율 오류:', aspectRatio);
                return null;
            }
            return calculateVideoFastResolution(aspectRatio, qualityLevel);
        }

        function updateVideoResolutionControls() {
            const workflowVariant = selectedVideoWorkflowVariant();
            const mode = document.getElementById('video-generation-mode')?.value || 'i2v';
            const isRef = mode === 'ref2v';
            const resolutionProfile = isRef
                ? `ref-${workflowVariant}-experimental-options`
                : (workflowVariant === 'fast' ? 'fast-768' : 'standard');
            const aspectSelect = document.getElementById('video-generation-aspect-ratio');
            const qualitySelect = document.getElementById('video-generation-quality-level');
            const qualityHint = document.getElementById('video-generation-quality-hint');
            if (!aspectSelect || !qualitySelect) {
                console.error('[VIDEO_UI] 영상 해상도 컨트롤이 누락되었습니다.', {
                    aspectSelect: !!aspectSelect,
                    qualitySelect: !!qualitySelect,
                });
                return;
            }

            const previousVariant = qualitySelect.dataset.activeVariant || 'standard';
            const previousQualityValue = qualitySelect.value || 'native';
            const previousAspect = aspectSelect.value || 'auto';
            const previousProfile = qualitySelect.dataset.activeResolutionProfile || '';
            const defaultsApplied = qualitySelect.dataset.defaultsApplied === workflowVariant;
            delete qualitySelect.dataset.defaultsApplied;
            if (isRef) {
                const enteringRef = !previousProfile.startsWith('ref-');
                qualitySelect.innerHTML = VIDEO_REF_QUALITY_OPTIONS
                    .map(([value, label]) => `<option value="${value}">${label}</option>`)
                    .join('');
                qualitySelect.value = defaultsApplied || !enteringRef
                    ? previousQualityValue
                    : VIDEO_REF_DEFAULT_QUALITY_LEVEL;
                if (!qualitySelect.value) {
                    console.error('[VIDEO_UI] REF 해상도 선택값 복원 실패:', {
                        previousQualityValue,
                        defaultsApplied,
                        enteringRef,
                    });
                    qualitySelect.value = VIDEO_REF_DEFAULT_QUALITY_LEVEL;
                }
                qualitySelect.disabled = false;
                qualitySelect.title = 'REF 기본 960×544 외 해상도는 검증되지 않은 실험 옵션입니다.';
                if (qualityHint) {
                    qualityHint.textContent = isVideoEngineSelected()
                        ? `REF ${videoEngineStepsValue()}-step · 기본 외 실험`
                        : (workflowVariant === 'fast'
                            ? 'REF 전용 4-step · 기본 외 실험'
                            : 'REF 20-step · 기본 외 실험');
                }
                qualitySelect.dataset.activeVariant = workflowVariant;
                qualitySelect.dataset.activeResolutionProfile = resolutionProfile;

                const refAspectOptions = [
                    `<option value="${VIDEO_REF_DEFAULT_ASPECT_RATIO}">REF 기본 · ${VIDEO_REF_DEFAULT_ASPECT_RATIO}</option>`,
                    '<option value="auto">자동 · REF 이미지 1 기준 (실험)</option>',
                ];
                for (const key of Object.keys(VIDEO_FAST_ASPECT_RATIOS)) {
                    if (key === VIDEO_REF_DEFAULT_ASPECT_RATIO) continue;
                    const resolution = calculateVideoRefResolution(
                        key,
                        qualitySelect.value || VIDEO_REF_DEFAULT_QUALITY_LEVEL,
                    );
                    const label = resolution
                        ? `${key} · ${resolution.width}×${resolution.height} (실험)`
                        : `${key} (실험)`;
                    refAspectOptions.push(`<option value="${key}">${label}</option>`);
                }
                aspectSelect.innerHTML = refAspectOptions.join('');
                const requestedAspect = defaultsApplied || !enteringRef
                    ? previousAspect
                    : VIDEO_REF_DEFAULT_ASPECT_RATIO;
                aspectSelect.value = requestedAspect === 'auto'
                        || Object.prototype.hasOwnProperty.call(
                            VIDEO_FAST_ASPECT_RATIOS,
                            requestedAspect,
                        )
                    ? requestedAspect
                    : VIDEO_REF_DEFAULT_ASPECT_RATIO;
                aspectSelect.disabled = false;
                aspectSelect.title = 'REF 기본 16:9 외 화면 비율은 검증되지 않은 실험 옵션입니다.';
                return;
            }

            qualitySelect.disabled = false;
            aspectSelect.disabled = false;
            aspectSelect.title = '';
            qualitySelect.innerHTML = (workflowVariant === 'fast'
                ? VIDEO_FAST_QUALITY_OPTIONS
                : VIDEO_STANDARD_QUALITY_OPTIONS
            ).map(([value, label]) => `<option value="${value}">${label}</option>`).join('');
            if (workflowVariant === 'fast') {
                if (previousVariant !== 'fast') {
                    if (!defaultsApplied) {
                        qualitySelect.dataset.standardValue = previousQualityValue;
                    }
                    qualitySelect.value = defaultsApplied ? previousQualityValue : 'native';
                } else {
                    qualitySelect.value = previousQualityValue;
                }
                qualitySelect.title = '고속 MP 선택은 권장 해상도(짧은 변 768p) 밖의 실험적 설정입니다.';
                if (qualityHint) qualityHint.textContent = '고속 · MP (실험적)';
            } else {
                if (previousVariant === 'fast' && qualitySelect.dataset.standardValue) {
                    qualitySelect.value = qualitySelect.dataset.standardValue;
                    delete qualitySelect.dataset.standardValue;
                } else {
                    qualitySelect.value = previousQualityValue;
                }
                qualitySelect.title = '';
                if (qualityHint) qualityHint.textContent = 'H3 FAST';
            }
            qualitySelect.dataset.activeVariant = workflowVariant;
            qualitySelect.dataset.activeResolutionProfile = resolutionProfile;

            const aspectKeys = workflowVariant === 'fast'
                ? VIDEO_FAST_768_ASPECT_KEYS
                : Object.keys(VIDEO_FAST_ASPECT_RATIOS);
            const autoLabel = workflowVariant === 'fast' && qualitySelect.value === 'native'
                ? '자동 · 짧은 변 768p'
                : '자동';
            const options = [`<option value="auto">${autoLabel}</option>`];
            for (const key of aspectKeys) {
                const resolution = workflowVariant === 'fast'
                    ? calculateVideoFastModeResolution(key, qualitySelect.value || 'native', mode)
                    : null;
                const label = resolution
                    ? `${key} · ${resolution.width}×${resolution.height}`
                    : key;
                options.push(`<option value="${key}">${label}</option>`);
            }
            aspectSelect.innerHTML = options.join('');
            aspectSelect.value = previousAspect === 'auto' || aspectKeys.includes(previousAspect)
                ? previousAspect
                : 'auto';
        }

        function onVideoQualityLevelChange() {
            updateVideoResolutionControls();
            updateVideoGenerationSummary();
        }

        function getVideoFastResolutionPreview() {
            const aspectInput = document.getElementById('video-generation-aspect-ratio')?.value || 'auto';
            const qualityLevel = document.getElementById('video-generation-quality-level')?.value || 'medium';
            const workflowVariant = selectedVideoWorkflowVariant();
            const mode = document.getElementById('video-generation-mode')?.value || 'i2v';
            let aspectRatio = aspectInput;
            if (aspectRatio === 'auto') {
                const sourceKey = document.getElementById('video-generation-source')?.value || '';
                const source = getVideoReferenceByKey(sourceKey);
                if (!source?.source_width || !source?.source_height) return null;
                const supportedKeys = workflowVariant === 'fast' && mode !== 'ref2v'
                    ? VIDEO_FAST_768_ASPECT_KEYS
                    : Object.keys(VIDEO_FAST_ASPECT_RATIOS);
                aspectRatio = chooseVideoFastAspectRatio(
                    source.source_width,
                    source.source_height,
                    supportedKeys,
                );
                if (!aspectRatio) return null;
            }
            if (mode === 'ref2v') {
                return calculateVideoRefResolution(aspectRatio, qualityLevel);
            }
            return workflowVariant === 'fast'
                ? calculateVideoFastModeResolution(
                    aspectRatio,
                    qualityLevel,
                    mode,
                )
                : calculateVideoFastResolution(aspectRatio, qualityLevel);
        }

        function videoReferenceKey(reference) {
            if (!reference || typeof reference !== 'object') return '';
            if (reference.kind === 'backup') {
                return `backup:${String(reference.name || '')}`;
            }
            if (reference.kind === 'asset') {
                return `asset:${JSON.stringify([
                    String(reference.character || ''),
                    String(reference.outfit || ''),
                    String(reference.expression || ''),
                    String(reference.filename || ''),
                ])}`;
            }
            console.error('[VIDEO_UI] 지원하지 않는 영상 참조:', reference);
            return '';
        }

        function normalizeVideoReferenceOption(item) {
            const reference = item?.reference || (
                item?.name ? {kind: 'backup', name: item.name} : null
            );
            const key = videoReferenceKey(reference);
            if (!key) {
                console.error('[VIDEO_UI] 영상 참조 옵션 정규화 실패:', item);
                return null;
            }
            return {
                ...item,
                reference,
                key,
                label: item.label || item.name || reference.filename || key,
                image_url: item.poster_url || item.image_url || '',
            };
        }

        function getVideoReferenceByKey(key) {
            return videoReferenceOptions.find(item => item.key === key) || null;
        }

        function registerVideoReferenceOptions(items) {
            for (const item of items || []) {
                const normalized = normalizeVideoReferenceOption(item);
                if (!normalized) continue;
                const existingIndex = videoReferenceOptions.findIndex(
                    candidate => candidate.key === normalized.key
                );
                if (existingIndex >= 0) videoReferenceOptions[existingIndex] = normalized;
                else videoReferenceOptions.push(normalized);
            }
        }

        function videoReferenceDirectEndpoint(reference) {
            const query = new URLSearchParams();
            if (reference?.kind === 'backup') {
                query.set('tab', 'illustration');
                query.set('name', String(reference.name || ''));
            } else if (reference?.kind === 'asset') {
                query.set('tab', 'asset');
                for (const field of ['character', 'outfit', 'expression', 'filename']) {
                    query.set(field, String(reference[field] || ''));
                }
            } else {
                console.error('[VIDEO_UI] 단건 참조 URL 생성 실패:', reference);
                return '';
            }
            return `/api/video/reference-options?${query.toString()}`;
        }

        function videoReferenceTargetInput(target) {
            const id = target === 'source'
                ? 'video-generation-source'
                : target === 'last'
                    ? 'video-generation-last'
                    : target === 'ref-2'
                        ? 'video-generation-ref-2'
                        : target === 'ref-3'
                            ? 'video-generation-ref-3'
                            : '';
            return id ? document.getElementById(id) : null;
        }

        function videoReferenceTargetLabel(target) {
            return ({
                source: '시작 프레임 · REF 이미지 1',
                last: '마지막 프레임',
                'ref-2': 'REF 이미지 2',
                'ref-3': 'REF 이미지 3',
            })[target] || '영상 이미지';
        }

        function selectedVideoReferenceKeysExcept(target) {
            const targets = ['source', 'last', 'ref-2', 'ref-3'];
            return new Set(targets
                .filter(candidate => candidate !== target)
                .map(candidate => videoReferenceTargetInput(candidate)?.value || '')
                .filter(Boolean));
        }

        function videoAssetReferenceImageUrl(reference, poster = false) {
            const enc = encodeURIComponent;
            const base = (
                `/api/asset_mode/characters/${enc(reference.character)}`
                + `/outfits/${enc(reference.outfit)}`
                + `/expressions/${enc(reference.expression)}`
                + `/images/${enc(reference.filename)}`
            );
            return poster ? `${base}/poster` : base;
        }

        function renderVideoAssetPickerBreadcrumb() {
            const breadcrumb = document.getElementById('video-reference-picker-breadcrumb');
            if (!breadcrumb) {
                console.error('[VIDEO_PICKER] 에셋 breadcrumb 요소가 없습니다.');
                return;
            }
            if (videoReferencePickerState.tab !== 'asset') {
                breadcrumb.style.display = 'none';
                breadcrumb.innerHTML = '';
                return;
            }
            const parts = [
                '<button type="button" onclick="openVideoAssetCharacters()">에셋</button>',
            ];
            if (videoReferencePickerState.assetCharacter) {
                parts.push('<span>›</span>');
                parts.push(
                    `<button type="button" data-character="${escapeAttr(videoReferencePickerState.assetCharacter)}"`
                    + ' onclick="openVideoAssetCharacter(this.dataset.character)">'
                    + `${escapeHtml(videoReferencePickerState.assetCharacter)}</button>`
                );
            }
            if (
                videoReferencePickerState.assetLevel === 'images'
                && videoReferencePickerState.assetOutfit
                && videoReferencePickerState.assetExpression
            ) {
                parts.push('<span>›</span>');
                parts.push(
                    `<span>${escapeHtml(videoReferencePickerState.assetOutfit)}`
                    + ` · ${escapeHtml(videoReferencePickerState.assetExpression)}</span>`
                );
            }
            breadcrumb.innerHTML = parts.join('');
            breadcrumb.style.display = 'flex';
        }

        function renderVideoReferencePicker() {
            const grid = document.getElementById('video-reference-picker-grid');
            const empty = document.getElementById('video-reference-picker-empty');
            const more = document.getElementById('video-reference-picker-more');
            const status = document.getElementById('video-reference-picker-status');
            if (!grid || !empty || !more || !status) {
                console.error('[VIDEO_PICKER] 탐색 모달 UI 요소가 누락됐습니다.');
                return;
            }
            renderVideoAssetPickerBreadcrumb();
            const targetInput = videoReferenceTargetInput(videoReferencePickerState.target);
            const selectedKey = targetInput?.value || '';
            const blocked = selectedVideoReferenceKeysExcept(videoReferencePickerState.target);
            grid.innerHTML = videoReferencePickerState.items.map(item => {
                if (item.picker_type === 'character') {
                    const thumb = item.image_url
                        ? `<img src="${escapeAttr(item.image_url)}" alt="${escapeAttr(item.label)}" loading="lazy" onerror="onVideoReferencePickerImageError(this)">`
                        : '<span class="video-reference-picker-folder-placeholder">📁</span>';
                    return `
                        <button type="button" class="video-reference-picker-card folder"
                                data-character="${escapeAttr(item.character)}"
                                onclick="openVideoAssetCharacter(this.dataset.character)">
                            ${thumb}
                            <span class="video-reference-picker-copy">
                                <span class="video-reference-picker-label">${escapeHtml(item.label)}</span>
                                <span class="video-reference-picker-date">캐릭터 폴더</span>
                            </span>
                        </button>`;
                }
                if (item.picker_type === 'combination') {
                    const thumb = item.image_url
                        ? `<img src="${escapeAttr(item.image_url)}" alt="${escapeAttr(item.label)}" loading="lazy" onerror="onVideoReferencePickerImageError(this)">`
                        : '<span class="video-reference-picker-folder-placeholder">📁</span>';
                    return `
                        <button type="button" class="video-reference-picker-card folder"
                                data-character="${escapeAttr(item.character)}"
                                data-outfit="${escapeAttr(item.outfit)}"
                                data-expression="${escapeAttr(item.expression)}"
                                onclick="openVideoAssetCombination(this.dataset.character, this.dataset.outfit, this.dataset.expression)">
                            ${thumb}
                            <span class="video-reference-picker-copy">
                                <span class="video-reference-picker-label">${escapeHtml(item.label)}</span>
                                <span class="video-reference-picker-date">${Number(item.image_count || 0)}장</span>
                            </span>
                        </button>`;
                }
                const disabled = blocked.has(item.key);
                const selected = item.key === selectedKey;
                return `
                    <button type="button" class="video-reference-picker-card${selected ? ' selected' : ''}"
                            data-reference-key="${escapeAttr(item.key)}"
                            onclick="selectVideoReferenceFromPicker(this.dataset.referenceKey)"
                            ${disabled ? 'disabled title="다른 슬롯에서 이미 선택한 이미지입니다"' : ''}>
                        <img src="${escapeAttr(item.image_url)}" alt="${escapeAttr(item.label)}" loading="lazy" onerror="onVideoReferencePickerImageError(this)">
                        <span class="video-reference-picker-copy">
                            <span class="video-reference-picker-label">${escapeHtml(item.label)}</span>
                            <span class="video-reference-picker-date">${escapeHtml(item.picker_detail || formatDate(item.mtime))}</span>
                        </span>
                    </button>`;
            }).join('');
            empty.style.display = videoReferencePickerState.items.length ? 'none' : 'grid';
            if (!videoReferencePickerState.items.length) {
                empty.textContent = videoReferencePickerState.loading
                    ? '이미지를 불러오는 중입니다.'
                    : '선택할 수 있는 이미지가 없습니다.';
            }
            more.style.display = (
                videoReferencePickerState.tab === 'illustration'
                && videoReferencePickerState.hasMore
            ) ? 'block' : 'none';
            more.disabled = videoReferencePickerState.loading;
            if (videoReferencePickerState.loading) {
                status.textContent = `${videoReferencePickerState.tab === 'illustration' ? '삽화' : '에셋'}을 불러오는 중입니다.`;
            } else if (videoReferencePickerState.tab === 'asset') {
                const unit = videoReferencePickerState.assetLevel === 'characters'
                    ? '캐릭터'
                    : videoReferencePickerState.assetLevel === 'combinations'
                        ? '의상·표정 조합'
                        : '이미지';
                status.textContent = `${videoReferencePickerState.items.length}개 ${unit}`;
            } else {
                status.textContent = `${videoReferencePickerState.items.length}개 불러옴`;
            }
        }

        function onVideoReferencePickerImageError(image) {
            const card = image?.closest('.video-reference-picker-card');
            console.error('[VIDEO_PICKER] 썸네일 로드 실패:', {
                key: card?.dataset?.referenceKey || '',
                src: image?.src || '',
            });
            if (image) image.style.visibility = 'hidden';
        }

        async function loadVideoAssetPickerLevel() {
            const requestId = ++videoReferencePickerState.requestId;
            videoReferencePickerState.loading = true;
            videoReferencePickerState.hasMore = false;
            videoReferencePickerState.items = [];
            renderVideoReferencePicker();
            try {
                const enc = encodeURIComponent;
                let data;
                if (videoReferencePickerState.assetLevel === 'characters') {
                    data = await fetchJSON('/api/asset_mode/characters');
                    if (requestId !== videoReferencePickerState.requestId) return;
                    const representatives = data?.representatives || {};
                    videoReferencePickerState.items = (Array.isArray(data?.characters) ? data.characters : [])
                        .map(character => {
                            const representative = representatives[character] || null;
                            let imageUrl = '';
                            if (
                                representative?.outfit
                                && representative?.expression
                                && representative?.filename
                            ) {
                                imageUrl = videoAssetReferenceImageUrl({
                                    character,
                                    outfit: representative.outfit,
                                    expression: representative.expression,
                                    filename: representative.filename,
                                });
                            }
                            return {
                                picker_type: 'character',
                                character: String(character || ''),
                                label: String(character || ''),
                                image_url: imageUrl,
                            };
                        })
                        .filter(item => item.character);
                } else if (videoReferencePickerState.assetLevel === 'combinations') {
                    const character = videoReferencePickerState.assetCharacter;
                    data = await fetchJSON(
                        `/api/asset_mode/characters/${enc(character)}/gallery`
                    );
                    if (requestId !== videoReferencePickerState.requestId) return;
                    videoReferencePickerState.items = (Array.isArray(data?.gallery) ? data.gallery : [])
                        .map(item => {
                            const reference = {
                                character,
                                outfit: String(item?.outfit || ''),
                                expression: String(item?.expression || ''),
                                filename: String(item?.representative || ''),
                            };
                            return {
                                picker_type: 'combination',
                                character,
                                outfit: reference.outfit,
                                expression: reference.expression,
                                label: `${reference.outfit} · ${reference.expression}`,
                                image_count: Number(item?.image_count || 0),
                                image_url: reference.filename
                                    ? videoAssetReferenceImageUrl(
                                        reference,
                                        item?.representative_is_animated === true
                                    )
                                    : '',
                            };
                        })
                        .filter(item => item.outfit && item.expression);
                } else if (videoReferencePickerState.assetLevel === 'images') {
                    const character = videoReferencePickerState.assetCharacter;
                    const outfit = videoReferencePickerState.assetOutfit;
                    const expression = videoReferencePickerState.assetExpression;
                    data = await fetchJSON(
                        `/api/asset_mode/characters/${enc(character)}`
                        + `/outfits/${enc(outfit)}/expressions/${enc(expression)}/images`
                    );
                    if (requestId !== videoReferencePickerState.requestId) return;
                    const loaded = (Array.isArray(data?.images) ? data.images : [])
                        .map(media => {
                            const reference = {
                                kind: 'asset',
                                character,
                                outfit,
                                expression,
                                filename: String(media?.filename || ''),
                            };
                            if (!reference.filename) return null;
                            const animated = media?.is_animated === true;
                            return normalizeVideoReferenceOption({
                                reference,
                                label: `${character} / ${outfit} / ${expression} / ${reference.filename}`,
                                image_url: videoAssetReferenceImageUrl(reference, animated),
                                poster_url: videoAssetReferenceImageUrl(reference, animated),
                                is_animated: animated,
                                picker_detail: animated ? '애니메이션 에셋' : '에셋 이미지',
                            });
                        })
                        .filter(Boolean);
                    registerVideoReferenceOptions(loaded);
                    videoReferencePickerState.items = loaded;
                } else {
                    console.error('[VIDEO_PICKER] 지원하지 않는 에셋 탐색 단계:', videoReferencePickerState.assetLevel);
                    throw new Error('지원하지 않는 에셋 탐색 단계입니다');
                }
            } catch (error) {
                if (requestId !== videoReferencePickerState.requestId) return;
                console.error('[VIDEO_PICKER] 에셋 폴더 조회 실패:', {
                    level: videoReferencePickerState.assetLevel,
                    character: videoReferencePickerState.assetCharacter,
                    outfit: videoReferencePickerState.assetOutfit,
                    expression: videoReferencePickerState.assetExpression,
                    error,
                });
                videoReferencePickerState.items = [];
                showToast('에셋 폴더를 불러오지 못했습니다.', 'error');
            } finally {
                if (requestId !== videoReferencePickerState.requestId) return;
                videoReferencePickerState.loading = false;
                renderVideoReferencePicker();
            }
        }

        async function openVideoAssetCharacters() {
            videoReferencePickerState.assetLevel = 'characters';
            videoReferencePickerState.assetCharacter = '';
            videoReferencePickerState.assetOutfit = '';
            videoReferencePickerState.assetExpression = '';
            await loadVideoAssetPickerLevel();
        }

        async function openVideoAssetCharacter(character) {
            const value = String(character || '').trim();
            if (!value) {
                console.error('[VIDEO_PICKER] 캐릭터 폴더 이름이 비어 있습니다.');
                return;
            }
            videoReferencePickerState.assetLevel = 'combinations';
            videoReferencePickerState.assetCharacter = value;
            videoReferencePickerState.assetOutfit = '';
            videoReferencePickerState.assetExpression = '';
            await loadVideoAssetPickerLevel();
        }

        async function openVideoAssetCombination(character, outfit, expression) {
            const values = [character, outfit, expression].map(value => String(value || '').trim());
            if (values.some(value => !value)) {
                console.error('[VIDEO_PICKER] 의상·표정 조합 경로가 비어 있습니다:', {
                    character,
                    outfit,
                    expression,
                });
                return;
            }
            videoReferencePickerState.assetLevel = 'images';
            [
                videoReferencePickerState.assetCharacter,
                videoReferencePickerState.assetOutfit,
                videoReferencePickerState.assetExpression,
            ] = values;
            await loadVideoAssetPickerLevel();
        }

        async function loadMoreVideoReferenceOptions(reset = false) {
            if (videoReferencePickerState.tab !== 'illustration') return;
            if (!reset && videoReferencePickerState.loading) return;
            if (!reset && !videoReferencePickerState.hasMore) return;
            if (reset) {
                videoReferencePickerState.offset = 0;
                videoReferencePickerState.hasMore = true;
                videoReferencePickerState.items = [];
            }
            const requestId = ++videoReferencePickerState.requestId;
            videoReferencePickerState.loading = true;
            renderVideoReferencePicker();
            try {
                const query = new URLSearchParams({
                    tab: videoReferencePickerState.tab,
                    offset: String(videoReferencePickerState.offset),
                    limit: String(VIDEO_REFERENCE_PICKER_PAGE_SIZE),
                });
                const data = await fetchJSON(`/api/video/reference-options?${query.toString()}`);
                if (requestId !== videoReferencePickerState.requestId) return;
                if (!data.success) throw new Error(data.error || '영상 참조 이미지 조회 실패');
                const loaded = (Array.isArray(data.options) ? data.options : [])
                    .map(normalizeVideoReferenceOption)
                    .filter(Boolean);
                registerVideoReferenceOptions(loaded);
                const known = new Set(videoReferencePickerState.items.map(item => item.key));
                for (const item of loaded) {
                    if (!known.has(item.key)) {
                        videoReferencePickerState.items.push(item);
                        known.add(item.key);
                    }
                }
                videoReferencePickerState.offset = Number(
                    data.next_offset ?? (videoReferencePickerState.offset + loaded.length)
                );
                videoReferencePickerState.hasMore = data.has_more === true;
            } catch (error) {
                if (requestId !== videoReferencePickerState.requestId) return;
                console.error('[VIDEO_PICKER] 이미지 페이지 조회 실패:', {
                    tab: videoReferencePickerState.tab,
                    offset: videoReferencePickerState.offset,
                    error,
                });
                videoReferencePickerState.hasMore = false;
                showToast('영상 참조 이미지를 불러오지 못했습니다.', 'error');
            } finally {
                if (requestId !== videoReferencePickerState.requestId) return;
                videoReferencePickerState.loading = false;
                renderVideoReferencePicker();
            }
        }

        async function switchVideoReferencePickerTab(tab, preserveAssetPath = false) {
            if (!['illustration', 'asset'].includes(tab)) {
                console.error('[VIDEO_PICKER] 지원하지 않는 탭:', tab);
                return;
            }
            videoReferencePickerState.tab = tab;
            for (const candidate of ['illustration', 'asset']) {
                const button = document.getElementById(`video-reference-picker-tab-${candidate}`);
                if (button) {
                    const active = candidate === tab;
                    button.classList.toggle('active', active);
                    button.setAttribute('aria-selected', active ? 'true' : 'false');
                }
            }
            if (tab === 'asset') {
                if (!preserveAssetPath) {
                    videoReferencePickerState.assetLevel = 'characters';
                    videoReferencePickerState.assetCharacter = '';
                    videoReferencePickerState.assetOutfit = '';
                    videoReferencePickerState.assetExpression = '';
                }
                await loadVideoAssetPickerLevel();
            } else {
                await loadMoreVideoReferenceOptions(true);
            }
        }

        async function openVideoReferencePicker(target) {
            const input = videoReferenceTargetInput(target);
            const modal = document.getElementById('video-reference-picker-modal');
            if (!input || !modal) {
                console.error('[VIDEO_PICKER] 탐색 대상 또는 모달이 없습니다:', target);
                return;
            }
            videoReferencePickerState.target = target;
            const title = document.getElementById('video-reference-picker-target');
            if (title) title.textContent = videoReferenceTargetLabel(target);
            const clear = document.getElementById('video-reference-picker-clear');
            if (clear) clear.style.display = target === 'source' ? 'none' : '';
            const selected = getVideoReferenceByKey(input.value);
            const selectedReference = selected?.reference || videoWorkspaceSourceRef;
            const defaultTab = selectedReference?.kind === 'asset' ? 'asset' : 'illustration';
            if (defaultTab === 'asset') {
                videoReferencePickerState.assetLevel = 'images';
                videoReferencePickerState.assetCharacter = String(selectedReference.character || '');
                videoReferencePickerState.assetOutfit = String(selectedReference.outfit || '');
                videoReferencePickerState.assetExpression = String(selectedReference.expression || '');
            }
            modal.classList.add('visible');
            await switchVideoReferencePickerTab(defaultTab, defaultTab === 'asset');
        }

        function closeVideoReferencePicker() {
            document.getElementById('video-reference-picker-modal')?.classList.remove('visible');
        }

        function selectVideoReferenceFromPicker(key) {
            const option = getVideoReferenceByKey(key);
            const input = videoReferenceTargetInput(videoReferencePickerState.target);
            if (!option || !input) {
                console.error('[VIDEO_PICKER] 선택 적용 실패:', {
                    key,
                    target: videoReferencePickerState.target,
                });
                return;
            }
            if (selectedVideoReferenceKeysExcept(videoReferencePickerState.target).has(key)) {
                console.error('[VIDEO_PICKER] 중복 이미지 선택 거부:', {key});
                showToast('각 영상 참조 슬롯에는 서로 다른 이미지를 선택하세요.', 'warning');
                return;
            }
            input.value = key;
            if (videoReferencePickerState.target === 'source') {
                videoWorkspaceSourceRef = option.reference;
                onVideoSourceChange();
            } else if (videoReferencePickerState.target === 'last') {
                onVideoLastFrameChange();
            } else {
                onVideoRefChange(Number(videoReferencePickerState.target.slice(-1)));
            }
            closeVideoReferencePicker();
        }

        function clearVideoReferenceSelection() {
            if (videoReferencePickerState.target === 'source') return;
            const input = videoReferenceTargetInput(videoReferencePickerState.target);
            if (!input) {
                console.error('[VIDEO_PICKER] 선택 해제 대상이 없습니다:', videoReferencePickerState.target);
                return;
            }
            input.value = '';
            if (videoReferencePickerState.target === 'last') onVideoLastFrameChange();
            else onVideoRefChange(Number(videoReferencePickerState.target.slice(-1)));
            closeVideoReferencePicker();
        }

        function getSelectedVideoOption(name, fallback = '') {
            return document.querySelector(`input[name="${name}"]:checked`)?.value || fallback;
        }

        function isVideoDialogueContextEnabled() {
            return document.getElementById('video-generation-include-dialogue-context')
                ?.checked === true;
        }

        function isVideoCameraMotionAllowed() {
            return document.getElementById('video-generation-allow-camera-motion')
                ?.checked === true;
        }

        function isVideoBackgroundChangeAllowed() {
            return document.getElementById('video-generation-allow-background-change')
                ?.checked === true;
        }

        function selectedVideoInstructionLanguage() {
            const language = document.getElementById('video-generation-instruction-language')
                ?.value || 'ko';
            if (!['ko', 'en'].includes(language)) {
                console.error('[VIDEO_UI] 지원하지 않는 AI 연출 초안 언어:', language);
                return 'ko';
            }
            return language;
        }

        function selectedVideoVisualContextSource() {
            const select = document.getElementById('video-generation-visual-context-source');
            if (!select) {
                console.error('[VIDEO_UI] Visual Context 입력 방식 셀렉트를 찾지 못했습니다.');
                return 'image';
            }
            const value = String(select.value || '').trim().toLowerCase();
            return value === 'prompt' ? 'prompt' : 'image';
        }

        function isVideoVisualContextFromImage() {
            return selectedVideoVisualContextSource() === 'image';
        }

        function updateVideoVisualContextSourcePresentation() {
            const fromImage = isVideoVisualContextFromImage();
            const mode = document.getElementById('video-generation-mode')?.value || 'i2v';
            const hint = document.getElementById('video-visual-context-source-hint');
            if (!hint) {
                console.error('[VIDEO_UI] Visual Context 입력 방식 표시 요소를 찾지 못했습니다.');
                return;
            }
            hint.textContent = fromImage
                ? (mode === 'ref2v'
                    ? 'LLM이 선택한 1–3장의 독립 REF 이미지를 직접 보고 정적 문맥을 만듭니다.'
                    : 'LLM이 시작·마지막 프레임을 직접 보고 정적 문맥을 만듭니다.')
                : (mode === 'ref2v'
                    ? '각 REF 이미지의 핵심 positive prompt를 독립 참조 문맥으로 다시 씁니다.'
                    : '핵심 positive prompt만 추려 LLM이 정적 문맥으로 다시 씁니다. 검열 시 유용합니다.');
        }

        function setVideoVisualContextFromImage(enabled) {
            const select = document.getElementById('video-generation-visual-context-source');
            if (!select) {
                console.error('[VIDEO_UI] Visual Context 입력 방식 셀렉트를 찾지 못했습니다.');
                return;
            }
            select.value = Boolean(enabled) ? 'image' : 'prompt';
            updateVideoVisualContextSourcePresentation();
            updateVideoInstructionDraftPresentation();
            updateVideoGenerationSummary();
        }

        function onVideoVisualContextSourceChange() {
            updateVideoVisualContextSourcePresentation();
            updateVideoInstructionDraftPresentation();
            updateVideoGenerationSummary();
        }

        function updateVideoInstructionDraftPresentation(statusText = '') {
            const includeDialogueContext = isVideoDialogueContextEnabled();
            const cameraMotion = isVideoCameraMotionAllowed();
            const backgroundChange = isVideoBackgroundChangeAllowed();
            const language = selectedVideoInstructionLanguage() === 'en' ? '영어' : '한국어';
            const mode = document.getElementById('video-generation-mode')?.value || 'i2v';
            const referenceDescription = mode === 'ref2v'
                ? `선택한 ${getSelectedVideoReferenceRefs().length}장의 독립 REF 이미지를`
                : '선택 프레임을';
            const note = document.getElementById('video-generation-draft-note');
            if (!note) {
                console.error('[VIDEO_UI] AI 연출 초안 상태 요소를 찾지 못했습니다.');
                return;
            }
            note.textContent = statusText || (
                `${referenceDescription} 직접 분석해 ${normalizedVideoDuration()}초 ${language} 초안을 만듭니다. `
                + `${includeDialogueContext ? '대사·감정 참고' : '대사·감정 제외'} · `
                + `${cameraMotion ? '카메라 이동 허용' : '고정 카메라'} · `
                + `${backgroundChange ? '배경 변화 허용' : '배경 유지'}. `
                + '완성된 초안은 입력란에만 채워지며 자동 제출되지 않습니다.'
            );
        }

        function setVideoDialogueContextEnabled(enabled) {
            const toggle = document.getElementById('video-generation-include-dialogue-context');
            if (!toggle) {
                console.error('[VIDEO_UI] 대사·감정 정보 전달 토글을 찾지 못했습니다.');
                return;
            }
            toggle.checked = Boolean(enabled);
            updateVideoInstructionDraftPresentation();
        }

        function setVideoInstructionDraftDefaults() {
            const language = document.getElementById('video-generation-instruction-language');
            const cameraMotion = document.getElementById('video-generation-allow-camera-motion');
            const backgroundChange = document.getElementById('video-generation-allow-background-change');
            if (!language || !cameraMotion || !backgroundChange) {
                console.error('[VIDEO_UI] AI 연출 초안 기본값 요소를 찾지 못했습니다.');
                return;
            }
            language.value = 'ko';
            setVideoDialogueContextEnabled(true);
            cameraMotion.checked = true;
            backgroundChange.checked = false;
            updateVideoInstructionDraftPresentation();
        }

        function onVideoDraftOptionChange() {
            updateVideoInstructionDraftPresentation();
        }

        function resetVideoInstructionDraftRequest() {
            videoInstructionDraftRequestId += 1;
            videoInstructionDraftBusy = false;
            const button = document.getElementById('video-generation-draft-button');
            if (button) {
                button.disabled = false;
                button.innerHTML = '✨ 초안 만들기';
            }
        }

        function resizeVideoInstructionToContent(input) {
            if (!input) {
                console.error('[VIDEO_UI] 내용에 맞춰 높이를 조절할 영상 지시 입력란이 없습니다.');
                return;
            }
            input.style.height = 'auto';
            input.style.height = `${input.scrollHeight}px`;
        }

        function resetVideoInstructionHeight(input) {
            if (!input) {
                console.error('[VIDEO_UI] 기본 높이로 되돌릴 영상 지시 입력란이 없습니다.');
                return;
            }
            input.style.height = '';
        }

        function videoInstructionDraftSelectionKey() {
            const sourceKey = document.getElementById('video-generation-source')?.value || '';
            const lastRef = getEffectiveLastVideoReference();
            return JSON.stringify({
                sourceKey,
                mode: document.getElementById('video-generation-mode')?.value || 'i2v',
                workflowVariant: selectedVideoWorkflowVariant(),
                last: videoReferenceKey(lastRef),
                references: getSelectedVideoReferenceRefs().map(videoReferenceKey),
                loop: isVideoLoopEnabled(),
                duration: normalizedVideoDuration(),
                aspectRatio: document.getElementById('video-generation-aspect-ratio')?.value || 'auto',
                qualityLevel: document.getElementById('video-generation-quality-level')?.value || 'medium',
                language: selectedVideoInstructionLanguage(),
                dialogue: isVideoDialogueContextEnabled(),
                cameraMotion: isVideoCameraMotionAllowed(),
                backgroundChange: isVideoBackgroundChangeAllowed(),
                refineVersion: selectedVideoInstructionRefineVersion(),
                instruction: document.getElementById('video-generation-instruction')?.value || '',
            });
        }

        async function requestVideoInstructionDraft() {
            if (videoInstructionDraftBusy || videoInstructionRefineBusy || videoInstructionDirectBusy || videoDirectionEditBusy) return;
            const sourceKey = document.getElementById('video-generation-source')?.value || '';
            const sourceRef = getVideoReferenceByKey(sourceKey)?.reference || null;
            const mode = document.getElementById('video-generation-mode')?.value || 'i2v';
            const lastRef = getEffectiveLastVideoReference();
            if (!sourceRef) {
                console.error('[VIDEO_UI] AI 연출 초안 요청 실패: 원본 참조 없음', {sourceKey});
                showToast('AI 초안을 만들 원본 이미지 정보가 없습니다.', 'error');
                return;
            }
            if (mode === 'first_last' && !lastRef) {
                console.error('[VIDEO_UI] AI 연출 초안 요청 실패: 마지막 프레임 없음');
                showToast('AI 초안을 만들 마지막 프레임을 선택하세요.', 'warning');
                return;
            }
            const requestId = ++videoInstructionDraftRequestId;
            const inputFlowSessionId = videoInputFlowSessionId;
            const selectionKey = videoInstructionDraftSelectionKey();
            const refineButton = document.getElementById('video-generation-refine-button');
            const refineVersion = document.getElementById('video-generation-refine-version');
            const directionEditButton = document.getElementById('video-generation-direction-edit-button');
            const button = document.getElementById('video-generation-draft-button');
            videoInstructionDraftBusy = true;
            if (refineButton) refineButton.disabled = true;
            if (refineVersion) refineVersion.disabled = true;
            if (directionEditButton) directionEditButton.disabled = true;
            if (button) {
                button.disabled = true;
                button.innerHTML = '<span class="spinner"></span> 초안 생성 중';
            }
            updateVideoInstructionDraftPresentation('LLM 큐 대기 및 참조 이미지 분석 중...');
            try {
                await videoInputFlowEventChain;
                const data = await fetchJSON('/api/video/instruction-draft', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        video_input_session_id: inputFlowSessionId,
                        mode,
                        instruction_before: document.getElementById('video-generation-instruction')?.value || '',
                        workflow_variant: selectedVideoWorkflowVariant(),
                        source_ref: sourceRef,
                        last_ref: lastRef,
                        reference_refs: getSelectedVideoReferenceRefs(),
                        source_backup: sourceRef.kind === 'backup' ? sourceRef.name : '',
                        last_backup: lastRef?.kind === 'backup' ? lastRef.name : '',
                        loop: isVideoLoopEnabled(),
                        aspect_ratio: document.getElementById('video-generation-aspect-ratio')?.value || 'auto',
                        quality_level: document.getElementById('video-generation-quality-level')?.value || 'medium',
                        duration: normalizedVideoDuration(),
                        language: selectedVideoInstructionLanguage(),
                        include_dialogue_context: isVideoDialogueContextEnabled(),
                        allow_camera_motion: isVideoCameraMotionAllowed(),
                        allow_background_change: isVideoBackgroundChangeAllowed(),
                    }),
                });
                if (requestId !== videoInstructionDraftRequestId) {
                    console.error('[VIDEO_UI] 닫히거나 교체된 AI 연출 초안 응답 무시:', data);
                    return;
                }
                if (!data.success || !String(data.draft || '').trim()) {
                    throw new Error(data.error || 'AI 연출 초안 생성 실패');
                }
                if (selectionKey !== videoInstructionDraftSelectionKey()) {
                    console.error('[VIDEO_UI] 선택 변경 후 도착한 AI 연출 초안 미적용:', data);
                    updateVideoInstructionDraftPresentation('선택값이 바뀌어 도착한 초안을 적용하지 않았습니다. 다시 만들어 주세요.');
                    showToast('영상화 선택값이 바뀌어 AI 초안을 적용하지 않았습니다.', 'warning');
                    return;
                }
                const instructionInput = document.getElementById('video-generation-instruction');
                if (!instructionInput) {
                    console.error('[VIDEO_UI] AI 연출 초안을 채울 입력란을 찾지 못했습니다.', data);
                    throw new Error('영상 지시 입력란을 찾지 못했습니다');
                }
                instructionInput.value = String(data.draft).trim();
                resizeVideoInstructionToContent(instructionInput);
                instructionInput.focus();
                clearVideoInstructionRefineUndo();
                replaceVideoInstructionProvenance(data.llm_trace);
                updateVideoInstructionDraftPresentation(
                    `초안 작성 완료 · 큐 ${data.item_id || ''}. 내용을 수정한 뒤 큐에 등록하세요.`
                );
                showToast('AI 연출 초안을 입력란에 채웠습니다.', 'success');
            } catch (error) {
                if (requestId !== videoInstructionDraftRequestId) return;
                console.error('[VIDEO_UI] AI 연출 초안 생성 실패:', error, {sourceRef, lastRef, mode});
                updateVideoInstructionDraftPresentation(`초안 생성 실패: ${error.message || error}`);
                showToast('AI 연출 초안 생성 실패: ' + (error.message || error), 'error');
            } finally {
                if (requestId === videoInstructionDraftRequestId) {
                    videoInstructionDraftBusy = false;
                    if (refineButton) refineButton.disabled = false;
                    if (refineVersion) refineVersion.disabled = false;
                    if (directionEditButton) directionEditButton.disabled = false;
                    if (button) {
                        button.disabled = false;
                        button.innerHTML = '✨ 초안 만들기';
                    }
                }
            }
        }

        function resetVideoInstructionRefineRequest() {
            videoInstructionRefineRequestId += 1;
            videoInstructionRefineBusy = false;
            const button = document.getElementById('video-generation-refine-button');
            const refineVersion = document.getElementById('video-generation-refine-version');
            if (button) {
                button.disabled = false;
                button.innerHTML = '✍️ 입력 다듬기';
            }
            if (refineVersion) {
                refineVersion.disabled = false;
            }
            clearVideoInstructionRefineUndo();
        }

        function clearVideoInstructionRefineUndo() {
            videoInstructionRefineUndoSnapshot = null;
            const undo = document.getElementById('video-generation-refine-undo');
            if (undo) undo.hidden = true;
        }

        function normalizeVideoInstructionLlmTrace(rawTrace) {
            if (rawTrace == null) return [];
            if (!Array.isArray(rawTrace)) {
                console.error('[VIDEO_UI] 영상 지시 LLM 흐름 응답이 목록이 아닙니다:', rawTrace);
                return [];
            }
            const normalized = [];
            const seen = new Set();
            for (const rawHistoryId of rawTrace) {
                const historyId = String(rawHistoryId || '').trim();
                if (!historyId || seen.has(historyId)) continue;
                normalized.push(historyId);
                seen.add(historyId);
            }
            return normalized;
        }

        function createVideoInputFlowSessionId() {
            if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID();
            const randomPart = Math.random().toString(36).slice(2);
            return `video-input-${Date.now().toString(36)}-${randomPart}`;
        }

        function recordVideoInputFlowEvent(action, input, output, sessionId = videoInputFlowSessionId) {
            const normalizedSessionId = String(sessionId || '').trim();
            if (!normalizedSessionId) {
                console.error('[VIDEO_INPUT_FLOW] 사람 조작을 기록할 세션 ID가 없습니다.', {action, input, output});
                return Promise.resolve(null);
            }
            const send = async () => {
                try {
                    const data = await fetchJSON('/api/video/input-flow-event', {
                        method: 'POST',
                        headers: {'Content-Type': 'application/json'},
                        body: JSON.stringify({
                            session_id: normalizedSessionId,
                            action,
                            input,
                            output,
                        }),
                    });
                    if (!data?.success) {
                        throw new Error(data?.error || '영상 입력 개선 그래프 기록 실패');
                    }
                    return data;
                } catch (error) {
                    console.error('[VIDEO_INPUT_FLOW] 사람 조작 기록 실패:', error, {
                        sessionId: normalizedSessionId,
                        action,
                        input,
                        output,
                    });
                    return null;
                }
            };
            videoInputFlowEventChain = videoInputFlowEventChain.then(send, send);
            return videoInputFlowEventChain;
        }

        function clearVideoInstructionProvenance() {
            videoInstructionOriginalInput = '';
            videoInstructionLlmTrace = [];
        }

        function replaceVideoInstructionProvenance(rawTrace) {
            videoInstructionOriginalInput = '';
            videoInstructionLlmTrace = normalizeVideoInstructionLlmTrace(rawTrace);
        }

        function appendVideoInstructionProvenance(originalInput, rawTrace) {
            if (!videoInstructionOriginalInput.trim()) {
                videoInstructionOriginalInput = String(originalInput || '');
            }
            videoInstructionLlmTrace = normalizeVideoInstructionLlmTrace([
                ...videoInstructionLlmTrace,
                ...normalizeVideoInstructionLlmTrace(rawTrace),
            ]);
        }

        function snapshotVideoInstructionProvenance(instruction) {
            return {
                instruction: String(instruction || ''),
                originalInput: videoInstructionOriginalInput,
                llmTrace: [...videoInstructionLlmTrace],
            };
        }

        function showVideoInstructionRefineUndo() {
            const undo = document.getElementById('video-generation-refine-undo');
            if (undo) undo.hidden = false;
        }

        function undoVideoInstructionRefine() {
            if (videoInstructionRefineUndoSnapshot == null) return;
            const snapshot = videoInstructionRefineUndoSnapshot;
            if (!snapshot || typeof snapshot !== 'object') {
                console.error('[VIDEO_UI] 영상 지시 되돌리기 상태 형식 오류:', snapshot);
                clearVideoInstructionRefineUndo();
                return;
            }
            const input = document.getElementById('video-generation-instruction');
            const discardedInstruction = String(input?.value || '');
            const discardedTrace = [...videoInstructionLlmTrace];
            if (input) {
                input.value = String(snapshot.instruction || '');
                resizeVideoInstructionToContent(input);
                input.focus();
            } else {
                console.error('[VIDEO_UI] 원문을 복원할 영상 지시 입력란을 찾지 못했습니다.');
            }
            videoInstructionOriginalInput = String(snapshot.originalInput || '');
            videoInstructionLlmTrace = normalizeVideoInstructionLlmTrace(snapshot.llmTrace);
            void recordVideoInputFlowEvent(
                'restore_original',
                {instruction: discardedInstruction, llm_trace: discardedTrace},
                {instruction: String(snapshot.instruction || ''), llm_trace: [...videoInstructionLlmTrace]},
            );
            clearVideoInstructionRefineUndo();
            updateVideoInstructionDraftPresentation('원문으로 되돌렸습니다. 내용을 수정한 뒤 큐에 등록하세요.');
            showToast('원문으로 되돌렸습니다.', 'info');
        }

        let _videoInstructionRefineUndoListenerAttached = false;
        function ensureVideoInstructionRefineUndoListener() {
            if (_videoInstructionRefineUndoListenerAttached) return;
            const input = document.getElementById('video-generation-instruction');
            if (!input) return;
            _videoInstructionRefineUndoListenerAttached = true;
            input.addEventListener('input', () => {
                if (videoInstructionRefineUndoSnapshot != null) clearVideoInstructionRefineUndo();
            });
        }

        function selectedVideoInstructionRefineVersion() {
            const select = document.getElementById('video-generation-refine-version');
            if (!select) {
                console.error('[VIDEO_UI] 입력 다듬기 방식 선택 요소를 찾지 못했습니다. V1을 사용합니다.');
                return 'v1';
            }
            const version = String(select.value || '').trim().toLowerCase();
            if (!['v1', 'v2', 'v3', 'v3_2', 'v4'].includes(version)) {
                console.error('[VIDEO_UI] 지원하지 않는 입력 다듬기 방식입니다. V1을 사용합니다:', select.value);
                select.value = 'v1';
                return 'v1';
            }
            return version;
        }

        function requestSelectedVideoInstructionRefine() {
            const refineVersion = selectedVideoInstructionRefineVersion();
            return refineVersion === 'v1'
                ? requestVideoInstructionRefine()
                : requestVideoInstructionDirect(refineVersion);
        }

        async function requestVideoInstructionRefine() {
            if (videoInstructionDraftBusy || videoInstructionRefineBusy || videoInstructionDirectBusy || videoDirectionEditBusy) return;
            const instructionInput = document.getElementById('video-generation-instruction');
            const instruction = (instructionInput?.value || '').trim();
            if (!instruction) {
                showToast('다듬을 상황을 먼저 입력란에 적어주세요.', 'warning');
                instructionInput?.focus();
                return;
            }
            const sourceKey = document.getElementById('video-generation-source')?.value || '';
            const sourceRef = getVideoReferenceByKey(sourceKey)?.reference || null;
            const mode = document.getElementById('video-generation-mode')?.value || 'i2v';
            const lastRef = getEffectiveLastVideoReference();
            if (!sourceRef) {
                console.error('[VIDEO_UI] AI 연출 입력 다듬기 요청 실패: 원본 참조 없음', {sourceKey});
                showToast('다듬기를 위한 원본 이미지 정보가 없습니다.', 'error');
                return;
            }
            if (mode === 'first_last' && !lastRef) {
                console.error('[VIDEO_UI] AI 연출 입력 다듬기 요청 실패: 마지막 프레임 없음');
                showToast('다듬기를 위한 마지막 프레임을 선택하세요.', 'warning');
                return;
            }
            const requestId = ++videoInstructionRefineRequestId;
            const inputFlowSessionId = videoInputFlowSessionId;
            const selectionKey = videoInstructionDraftSelectionKey();
            const draftButton = document.getElementById('video-generation-draft-button');
            const refineVersion = document.getElementById('video-generation-refine-version');
            const button = document.getElementById('video-generation-refine-button');
            const directionEditButton = document.getElementById('video-generation-direction-edit-button');
            videoInstructionRefineBusy = true;
            if (draftButton) draftButton.disabled = true;
            if (refineVersion) refineVersion.disabled = true;
            if (directionEditButton) directionEditButton.disabled = true;
            if (button) {
                button.disabled = true;
                button.innerHTML = '<span class="spinner"></span> 다듬는 중';
            }
            clearVideoInstructionRefineUndo();
            updateVideoInstructionDraftPresentation('사용자 입력을 바탕으로 참조 이미지와 함께 다듬는 중...');
            try {
                await videoInputFlowEventChain;
                const data = await fetchJSON('/api/video/instruction-refine', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        video_input_session_id: inputFlowSessionId,
                        mode,
                        workflow_variant: selectedVideoWorkflowVariant(),
                        instruction,
                        source_ref: sourceRef,
                        last_ref: lastRef,
                        reference_refs: getSelectedVideoReferenceRefs(),
                        source_backup: sourceRef.kind === 'backup' ? sourceRef.name : '',
                        last_backup: lastRef?.kind === 'backup' ? lastRef.name : '',
                        loop: isVideoLoopEnabled(),
                        aspect_ratio: document.getElementById('video-generation-aspect-ratio')?.value || 'auto',
                        quality_level: document.getElementById('video-generation-quality-level')?.value || 'medium',
                        duration: normalizedVideoDuration(),
                        language: selectedVideoInstructionLanguage(),
                        include_dialogue_context: isVideoDialogueContextEnabled(),
                        allow_camera_motion: isVideoCameraMotionAllowed(),
                        allow_background_change: isVideoBackgroundChangeAllowed(),
                    }),
                });
                if (requestId !== videoInstructionRefineRequestId) {
                    console.error('[VIDEO_UI] 닫히거나 교체된 AI 연출 입력 다듬기 응답 무시:', data);
                    return;
                }
                if (!data.success || !String(data.draft || '').trim()) {
                    throw new Error(data.error || 'AI 연출 입력 다듬기 실패');
                }
                if (selectionKey !== videoInstructionDraftSelectionKey()) {
                    console.error('[VIDEO_UI] 선택 변경 후 도착한 AI 연출 입력 다듬기 미적용:', data);
                    updateVideoInstructionDraftPresentation('선택값이 바뀌어 도착한 결과를 적용하지 않았습니다. 다시 다듬어 주세요.');
                    showToast('영상화 선택값이 바뀌어 다듬기 결과를 적용하지 않았습니다.', 'warning');
                    return;
                }
                const target = document.getElementById('video-generation-instruction');
                if (!target) {
                    console.error('[VIDEO_UI] AI 연출 입력 다듬기를 채울 입력란을 찾지 못했습니다.', data);
                    throw new Error('영상 지시 입력란을 찾지 못했습니다');
                }
                videoInstructionRefineUndoSnapshot = snapshotVideoInstructionProvenance(target.value);
                appendVideoInstructionProvenance(target.value, data.llm_trace);
                target.value = String(data.draft).trim();
                resizeVideoInstructionToContent(target);
                showVideoInstructionRefineUndo();
                target.focus();
                updateVideoInstructionDraftPresentation(
                    `입력 다듬기 완료 · 큐 ${data.item_id || ''}. ↩ 원문으로 되돌리기로 원문 복구 가능.`
                );
                showToast('입력을 풍부하게 다듬아 입력란에 채웠습니다.', 'success');
            } catch (error) {
                if (requestId !== videoInstructionRefineRequestId) return;
                console.error('[VIDEO_UI] AI 연출 입력 다듬기 실패:', error, {sourceRef, lastRef, mode, instruction});
                updateVideoInstructionDraftPresentation(`입력 다듬기 실패: ${error.message || error}`);
                showToast('AI 연출 입력 다듬기 실패: ' + (error.message || error), 'error');
            } finally {
                if (requestId === videoInstructionRefineRequestId) {
                    videoInstructionRefineBusy = false;
                    if (draftButton) draftButton.disabled = false;
                    if (refineVersion) refineVersion.disabled = false;
                    if (directionEditButton) directionEditButton.disabled = false;
                    if (button) {
                        button.disabled = false;
                        button.innerHTML = '✍️ 입력 다듬기';
                    }
                }
            }
        }

        function resetVideoInstructionDirectRequest() {
            videoInstructionDirectRequestId += 1;
            videoInstructionDirectBusy = false;
        }

        async function requestVideoInstructionDirect(requestedVersion = selectedVideoInstructionRefineVersion()) {
            if (videoInstructionDraftBusy || videoInstructionRefineBusy || videoInstructionDirectBusy || videoDirectionEditBusy) return;
            const refineVersionValue = String(requestedVersion || '').trim().toLowerCase();
            if (!['v2', 'v3', 'v3_2', 'v4'].includes(refineVersionValue)) {
                console.error('[VIDEO_UI] 제작 계획 다듬기에 지원하지 않는 방식입니다:', requestedVersion);
                showToast('시네마틱, 일본 애니메이션 또는 DaSiWa 프롬프트 방식을 선택해 주세요.', 'error');
                return;
            }
            const styleLabel = {
                v2: 'V2 시네마틱',
                v3: 'V3 일본 애니메이션',
                v3_2: 'V3_2 일본 애니메이션 2',
                v4: 'V4 DaSiWa 프롬프트',
            }[refineVersionValue];
            const styleName = {
                v2: '시네마틱 스타일',
                v3: '일본 애니메이션 스타일',
                v3_2: '일본 애니메이션 스타일 2',
                v4: 'DaSiWa 프롬프트 방식',
            }[refineVersionValue];
            const instructionInput = document.getElementById('video-generation-instruction');
            const instruction = (instructionInput?.value || '').trim();
            if (!instruction) {
                showToast(`${styleName}로 다듬을 내용을 먼저 입력란에 적어주세요.`, 'warning');
                instructionInput?.focus();
                return;
            }
            const sourceKey = document.getElementById('video-generation-source')?.value || '';
            const sourceRef = getVideoReferenceByKey(sourceKey)?.reference || null;
            const mode = document.getElementById('video-generation-mode')?.value || 'i2v';
            const lastRef = getEffectiveLastVideoReference();
            if (!sourceRef) {
                console.error(`[VIDEO_UI] AI 연출 ${styleLabel} 다듬기 요청 실패: 원본 참조 없음`, {sourceKey});
                showToast(`${styleLabel} 다듬기를 위한 원본 이미지 정보가 없습니다.`, 'error');
                return;
            }
            if (mode === 'first_last' && !lastRef) {
                console.error(`[VIDEO_UI] AI 연출 ${styleLabel} 다듬기 요청 실패: 마지막 프레임 없음`);
                showToast(`${styleLabel} 다듬기를 위한 마지막 프레임을 선택하세요.`, 'warning');
                return;
            }
            const requestId = ++videoInstructionDirectRequestId;
            const inputFlowSessionId = videoInputFlowSessionId;
            const selectionKey = videoInstructionDraftSelectionKey();
            const draftButton = document.getElementById('video-generation-draft-button');
            const refineVersion = document.getElementById('video-generation-refine-version');
            const button = document.getElementById('video-generation-refine-button');
            const directionEditButton = document.getElementById('video-generation-direction-edit-button');
            videoInstructionDirectBusy = true;
            if (draftButton) draftButton.disabled = true;
            if (refineVersion) refineVersion.disabled = true;
            if (directionEditButton) directionEditButton.disabled = true;
            if (button) {
                button.disabled = true;
                button.innerHTML = '<span class="spinner"></span> 다듬는 중';
            }
            clearVideoInstructionRefineUndo();
            updateVideoInstructionDraftPresentation(`${styleLabel} 스타일로 참조 이미지와 함께 연출을 다듬는 중...`);
            try {
                await videoInputFlowEventChain;
                const data = await fetchJSON('/api/video/instruction-direct', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        video_input_session_id: inputFlowSessionId,
                        mode,
                        refine_version: refineVersionValue,
                        workflow_variant: selectedVideoWorkflowVariant(),
                        instruction,
                        source_ref: sourceRef,
                        last_ref: lastRef,
                        reference_refs: getSelectedVideoReferenceRefs(),
                        source_backup: sourceRef.kind === 'backup' ? sourceRef.name : '',
                        last_backup: lastRef?.kind === 'backup' ? lastRef.name : '',
                        loop: isVideoLoopEnabled(),
                        aspect_ratio: document.getElementById('video-generation-aspect-ratio')?.value || 'auto',
                        quality_level: document.getElementById('video-generation-quality-level')?.value || 'medium',
                        duration: normalizedVideoDuration(),
                        language: selectedVideoInstructionLanguage(),
                        include_dialogue_context: isVideoDialogueContextEnabled(),
                        allow_camera_motion: isVideoCameraMotionAllowed(),
                        allow_background_change: isVideoBackgroundChangeAllowed(),
                    }),
                });
                if (requestId !== videoInstructionDirectRequestId) {
                    console.error(`[VIDEO_UI] 닫히거나 교체된 AI 연출 ${styleLabel} 다듬기 응답 무시:`, data);
                    return;
                }
                if (!data.success || !String(data.draft || '').trim()) {
                    throw new Error(data.error || `AI 연출 ${styleLabel} 다듬기 실패`);
                }
                if (selectionKey !== videoInstructionDraftSelectionKey()) {
                    console.error(`[VIDEO_UI] 선택 변경 후 도착한 AI 연출 ${styleLabel} 다듬기 미적용:`, data);
                    updateVideoInstructionDraftPresentation('선택값이 바뀌어 도착한 결과를 적용하지 않았습니다. 다시 다듬어 주세요.');
                    showToast(`영상화 선택값이 바뀌어 ${styleLabel} 다듬기 결과를 적용하지 않았습니다.`, 'warning');
                    return;
                }
                const target = document.getElementById('video-generation-instruction');
                if (!target) {
                    console.error(`[VIDEO_UI] AI 연출 ${styleLabel} 다듬기를 채울 입력란을 찾지 못했습니다.`, data);
                    throw new Error('영상 지시 입력란을 찾지 못했습니다');
                }
                videoInstructionRefineUndoSnapshot = snapshotVideoInstructionProvenance(target.value);
                appendVideoInstructionProvenance(target.value, data.llm_trace);
                target.value = String(data.draft).trim();
                resizeVideoInstructionToContent(target);
                showVideoInstructionRefineUndo();
                target.focus();
                updateVideoInstructionDraftPresentation(
                    `${styleLabel} 다듬기 완료 · 큐 ${data.item_id || ''}. ↩ 원문으로 되돌리기로 원문 복구 가능.`
                );
                showToast(`${styleName}로 다듬어 입력란에 채웠습니다.`, 'success');
            } catch (error) {
                if (requestId !== videoInstructionDirectRequestId) return;
                console.error(`[VIDEO_UI] AI 연출 ${styleLabel} 다듬기 실패:`, error, {sourceRef, lastRef, mode, instruction});
                updateVideoInstructionDraftPresentation(`${styleLabel} 다듬기 실패: ${error.message || error}`);
                showToast(`AI 연출 ${styleLabel} 다듬기 실패: ` + (error.message || error), 'error');
            } finally {
                if (requestId === videoInstructionDirectRequestId) {
                    videoInstructionDirectBusy = false;
                    if (draftButton) draftButton.disabled = false;
                    if (refineVersion) refineVersion.disabled = false;
                    if (directionEditButton) directionEditButton.disabled = false;
                    if (button) {
                        button.disabled = false;
                        button.innerHTML = '✍️ 입력 다듬기';
                    }
                }
            }
        }

        function setVideoDirectionEditStatus(message = '', state = '') {
            const status = document.getElementById('video-direction-edit-status');
            if (!status) {
                console.error('[VIDEO_UI] 다듬기 방향 명령 상태 요소를 찾지 못했습니다:', {message, state});
                return;
            }
            status.textContent = String(message || '');
            if (state) status.dataset.state = state;
            else delete status.dataset.state;
        }

        function getVideoDirectionEditResizeMetrics() {
            const body = document.querySelector('#video-direction-edit-modal .video-direction-edit-body');
            const grid = document.getElementById('video-direction-edit-grid');
            const guide = body?.querySelector('.video-direction-edit-guide');
            const status = document.getElementById('video-direction-edit-status');
            const review = document.getElementById('video-direction-edit-review');
            const resizer = document.getElementById('video-direction-edit-resizer');
            if (!body || !grid || !guide || !status || !review || !resizer) {
                console.error('[VIDEO_UI] 다듬기 방향 영역 크기 조절 요소가 누락되었습니다.', {
                    body: !!body,
                    grid: !!grid,
                    guide: !!guide,
                    status: !!status,
                    review: !!review,
                    resizer: !!resizer,
                });
                return null;
            }
            const topHeight = grid.getBoundingClientRect().height;
            const bodyStyle = getComputedStyle(body);
            const bodyPadding = (Number.parseFloat(bodyStyle.paddingTop) || 0)
                + (Number.parseFloat(bodyStyle.paddingBottom) || 0);
            const rowGap = Number.parseFloat(bodyStyle.rowGap) || 0;
            const fixedHeight = guide.getBoundingClientRect().height
                + status.getBoundingClientRect().height
                + resizer.getBoundingClientRect().height
                + (rowGap * 4);
            const combinedHeight = body.clientHeight - bodyPadding - fixedHeight;
            if (!Number.isFinite(combinedHeight) || combinedHeight <= 0) {
                console.error('[VIDEO_UI] 다듬기 방향 영역 크기 계산 실패:', {
                    topHeight,
                    bodyClientHeight: body.clientHeight,
                    bodyPadding,
                    fixedHeight,
                    combinedHeight,
                });
                return null;
            }
            const compactWidth = window.innerWidth <= 780;
            const compactHeight = window.innerHeight <= 720;
            const preferredMinTop = compactWidth ? 220 : (compactHeight ? 140 : 150);
            const preferredMinReview = compactWidth ? 220 : (compactHeight ? 210 : 280);
            const minTop = Math.min(preferredMinTop, combinedHeight * .42);
            const minReview = Math.min(preferredMinReview, combinedHeight * .55);
            const maxTop = Math.max(minTop, combinedHeight - minReview);
            return {body, grid, review, resizer, topHeight, combinedHeight, minTop, maxTop};
        }

        function updateVideoDirectionEditResizeA11y(metrics, topHeight) {
            if (!metrics?.resizer) {
                console.error('[VIDEO_UI] 다듬기 방향 크기 조절 접근성 상태를 갱신할 수 없습니다.', {
                    hasMetrics: !!metrics,
                });
                return;
            }
            const roundedTop = Math.round(topHeight);
            const roundedReview = Math.max(
                0,
                Math.round(metrics.review.getBoundingClientRect().height),
            );
            metrics.resizer.setAttribute('aria-valuemin', String(Math.round(metrics.minTop)));
            metrics.resizer.setAttribute('aria-valuemax', String(Math.round(metrics.maxTop)));
            metrics.resizer.setAttribute('aria-valuenow', String(roundedTop));
            metrics.resizer.setAttribute(
                'aria-valuetext',
                `상단 원문·명령 영역 ${roundedTop}px, 변경점 영역 약 ${roundedReview}px`,
            );
        }

        function setVideoDirectionEditTopHeight(requestedHeight) {
            const metrics = getVideoDirectionEditResizeMetrics();
            const numericHeight = Number(requestedHeight);
            if (!metrics || !Number.isFinite(numericHeight)) {
                console.error('[VIDEO_UI] 다듬기 방향 상단 영역 높이를 적용하지 못했습니다.', {
                    requestedHeight,
                    hasMetrics: !!metrics,
                });
                return null;
            }
            const nextHeight = Math.min(metrics.maxTop, Math.max(metrics.minTop, numericHeight));
            metrics.body.style.setProperty('--video-direction-edit-top-height', `${Math.round(nextHeight)}px`);
            updateVideoDirectionEditResizeA11y(metrics, nextHeight);
            return nextHeight;
        }

        function syncVideoDirectionEditResizeA11y() {
            const metrics = getVideoDirectionEditResizeMetrics();
            if (!metrics) return;
            const inlineHeight = Number.parseFloat(
                metrics.body.style.getPropertyValue('--video-direction-edit-top-height'),
            );
            if (Number.isFinite(inlineHeight)) {
                setVideoDirectionEditTopHeight(inlineHeight);
                return;
            }
            updateVideoDirectionEditResizeA11y(metrics, metrics.topHeight);
        }

        function setVideoDirectionEditReviewLayout(visible) {
            const body = document.querySelector('#video-direction-edit-modal .video-direction-edit-body');
            const resizer = document.getElementById('video-direction-edit-resizer');
            if (!body || !resizer) {
                console.error('[VIDEO_UI] 다듬기 방향 검토 레이아웃을 전환할 수 없습니다.', {
                    visible,
                    body: !!body,
                    resizer: !!resizer,
                });
                return;
            }
            if (visible) {
                body.classList.add('has-review');
                resizer.hidden = false;
                requestAnimationFrame(syncVideoDirectionEditResizeA11y);
                return;
            }
            finishVideoDirectionEditResize();
            body.classList.remove('has-review');
            body.style.removeProperty('--video-direction-edit-top-height');
            resizer.hidden = true;
            resizer.setAttribute('aria-valuemin', '0');
            resizer.setAttribute('aria-valuemax', '0');
            resizer.setAttribute('aria-valuenow', '0');
            resizer.removeAttribute('aria-valuetext');
        }

        function startVideoDirectionEditResize(event) {
            if (event.button !== 0) return;
            const metrics = getVideoDirectionEditResizeMetrics();
            if (!metrics) return;
            finishVideoDirectionEditResize();
            videoDirectionEditResizeSession = {
                pointerId: event.pointerId,
                startY: event.clientY,
                startTopHeight: metrics.topHeight,
                originalUserSelect: document.body.style.userSelect,
            };
            document.body.style.userSelect = 'none';
            try {
                metrics.resizer.setPointerCapture(event.pointerId);
            } catch (error) {
                console.error('[VIDEO_UI] 다듬기 방향 크기 조절 포인터 캡처 실패:', error, {
                    pointerId: event.pointerId,
                });
            }
            event.preventDefault();
        }

        function moveVideoDirectionEditResize(event) {
            const session = videoDirectionEditResizeSession;
            if (!session || event.pointerId !== session.pointerId) return;
            setVideoDirectionEditTopHeight(
                session.startTopHeight + (event.clientY - session.startY),
            );
            event.preventDefault();
        }

        function finishVideoDirectionEditResize(event = null) {
            const session = videoDirectionEditResizeSession;
            if (!session || (event && event.pointerId !== session.pointerId)) return;
            const resizer = document.getElementById('video-direction-edit-resizer');
            if (resizer?.hasPointerCapture?.(session.pointerId)) {
                try {
                    resizer.releasePointerCapture(session.pointerId);
                } catch (error) {
                    console.error('[VIDEO_UI] 다듬기 방향 크기 조절 포인터 해제 실패:', error, {
                        pointerId: session.pointerId,
                    });
                }
            }
            document.body.style.userSelect = session.originalUserSelect;
            videoDirectionEditResizeSession = null;
        }

        function resizeVideoDirectionEditWithKeyboard(event) {
            const metrics = getVideoDirectionEditResizeMetrics();
            if (!metrics) return;
            let nextHeight = metrics.topHeight;
            if (event.key === 'ArrowUp') nextHeight -= 24;
            else if (event.key === 'ArrowDown') nextHeight += 24;
            else if (event.key === 'PageUp') nextHeight -= 72;
            else if (event.key === 'PageDown') nextHeight += 72;
            else if (event.key === 'Home') nextHeight = metrics.minTop;
            else if (event.key === 'End') nextHeight = metrics.maxTop;
            else return;
            setVideoDirectionEditTopHeight(nextHeight);
            event.preventDefault();
        }

        function resetVideoDirectionEditResize() {
            const body = document.querySelector('#video-direction-edit-modal .video-direction-edit-body');
            if (!body) {
                console.error('[VIDEO_UI] 다듬기 방향 크기 조절값을 초기화할 본문이 없습니다.');
                return;
            }
            body.style.removeProperty('--video-direction-edit-top-height');
            requestAnimationFrame(syncVideoDirectionEditResizeA11y);
        }

        window.addEventListener('pointermove', moveVideoDirectionEditResize, {passive: false});
        window.addEventListener('pointerup', finishVideoDirectionEditResize);
        window.addEventListener('pointercancel', finishVideoDirectionEditResize);
        window.addEventListener('resize', () => {
            const body = document.querySelector('#video-direction-edit-modal .video-direction-edit-body');
            if (body?.classList.contains('has-review')) {
                requestAnimationFrame(syncVideoDirectionEditResizeA11y);
            }
        }, {passive: true});

        function setVideoDirectionEditBusy(busy) {
            videoDirectionEditBusy = busy === true;
            const command = document.getElementById('video-direction-edit-command');
            const run = document.getElementById('video-direction-edit-run');
            const more = document.getElementById('video-direction-edit-more');
            const revert = document.getElementById('video-direction-edit-revert');
            const accept = document.getElementById('video-direction-edit-accept');
            const draft = document.getElementById('video-generation-draft-button');
            const refine = document.getElementById('video-generation-refine-button');
            const refineVersion = document.getElementById('video-generation-refine-version');
            const editor = document.getElementById('video-generation-direction-edit-button');
            if (command) command.disabled = videoDirectionEditBusy;
            if (run) {
                run.disabled = videoDirectionEditBusy;
                run.innerHTML = videoDirectionEditBusy
                    ? '<span class="spinner"></span> 최소 수정 중'
                    : '수정안 만들기';
            }
            if (more) {
                more.disabled = videoDirectionEditBusy;
                more.innerHTML = videoDirectionEditBusy
                    ? '<span class="spinner"></span> 추가 수정 중'
                    : '더 바꾸기';
            }
            if (revert) revert.disabled = videoDirectionEditBusy;
            if (accept) accept.disabled = videoDirectionEditBusy;
            if (draft) draft.disabled = videoDirectionEditBusy;
            if (refine) refine.disabled = videoDirectionEditBusy;
            if (refineVersion) refineVersion.disabled = videoDirectionEditBusy;
            if (editor) editor.disabled = videoDirectionEditBusy;
        }

        function resetVideoDirectionEditState(closeModal = true) {
            videoDirectionEditRequestId += 1;
            setVideoDirectionEditBusy(false);
            videoDirectionEditState.baseInstruction = '';
            videoDirectionEditState.candidateInstruction = '';
            videoDirectionEditState.baseSnapshot = null;
            videoDirectionEditState.llmTrace = [];
            videoDirectionEditState.selectionKey = '';
            videoDirectionEditState.round = 0;

            const source = document.getElementById('video-direction-edit-source');
            const command = document.getElementById('video-direction-edit-command');
            const commandLabel = document.getElementById('video-direction-edit-command-label');
            const review = document.getElementById('video-direction-edit-review');
            const diff = document.getElementById('video-direction-edit-diff');
            const run = document.getElementById('video-direction-edit-run');
            const more = document.getElementById('video-direction-edit-more');
            const revert = document.getElementById('video-direction-edit-revert');
            const accept = document.getElementById('video-direction-edit-accept');
            if (source) source.value = '';
            if (command) {
                command.value = '';
                command.placeholder = '예: 카메라 움직임은 그대로 두고, 인물이 고개를 드는 속도만 더 느리게 바꿔줘.';
            }
            if (commandLabel) commandLabel.textContent = '원하는 수정 방향';
            if (review) review.hidden = true;
            setVideoDirectionEditReviewLayout(false);
            if (diff) diff.textContent = '';
            if (run) run.hidden = false;
            if (more) more.hidden = true;
            if (revert) revert.hidden = true;
            if (accept) {
                accept.hidden = true;
                accept.disabled = false;
            }
            setVideoDirectionEditStatus();
            if (closeModal) {
                document.getElementById('video-direction-edit-modal')?.classList.remove('visible');
            }
        }

        function openVideoDirectionEditModal() {
            if (videoInstructionDraftBusy || videoInstructionRefineBusy || videoInstructionDirectBusy || videoDirectionEditBusy) {
                console.error('[VIDEO_UI] 다른 영상 지시 LLM 요청 처리 중이라 방향 명령창을 열지 않았습니다.');
                showToast('진행 중인 영상 지시 작업이 끝난 뒤 다시 시도하세요.', 'warning');
                return;
            }
            const instructionInput = document.getElementById('video-generation-instruction');
            const instruction = String(instructionInput?.value || '').trim();
            if (!instruction) {
                console.error('[VIDEO_UI] 다듬기 방향 명령창 열기 실패: 영상 지시 원문이 비어 있습니다.');
                showToast('먼저 영상에서 일어날 일을 입력해 주세요.', 'warning');
                instructionInput?.focus();
                return;
            }
            const modal = document.getElementById('video-direction-edit-modal');
            const source = document.getElementById('video-direction-edit-source');
            const command = document.getElementById('video-direction-edit-command');
            if (!modal || !source || !command) {
                console.error('[VIDEO_UI] 다듬기 방향 명령 모달 요소가 누락되었습니다.', {
                    modal: !!modal,
                    source: !!source,
                    command: !!command,
                });
                showToast('다듬기 방향 명령창을 열 수 없습니다.', 'error');
                return;
            }
            resetVideoDirectionEditState(false);
            videoDirectionEditState.baseInstruction = instruction;
            videoDirectionEditState.baseSnapshot = snapshotVideoInstructionProvenance(instruction);
            videoDirectionEditState.selectionKey = videoInstructionDraftSelectionKey();
            source.value = instruction;
            setVideoDirectionEditStatus('수정 방향을 입력하면 원문을 건드리지 않고 검토용 수정안을 만듭니다.');
            modal.classList.add('visible');
            command.focus();
        }

        function closeVideoDirectionEditModal() {
            if (videoDirectionEditBusy) {
                console.error('[VIDEO_UI] 처리 중인 다듬기 방향 명령 응답을 취소하고 무시합니다.', {
                    requestId: videoDirectionEditRequestId,
                });
            }
            resetVideoDirectionEditState(true);
        }

        function videoDirectionDiffTokens(text) {
            return String(text || '').match(/[\p{L}\p{N}_]+|[^\p{L}\p{N}_\s]+|\s+/gu) || [];
        }

        function videoDirectionDiffLines(text) {
            return String(text || '').match(/[^\n]*\n|[^\n]+$/g) || [];
        }

        function mergeVideoDirectionDiffOperations(operations) {
            const merged = [];
            for (const operation of operations) {
                if (!operation?.text) continue;
                const previous = merged[merged.length - 1];
                if (previous?.type === operation.type) previous.text += operation.text;
                else merged.push({type: operation.type, text: operation.text});
            }
            return merged;
        }

        function fallbackVideoDirectionDiff(original, revised) {
            let prefixLength = 0;
            const sharedLength = Math.min(original.length, revised.length);
            while (prefixLength < sharedLength && original[prefixLength] === revised[prefixLength]) {
                prefixLength += 1;
            }
            let suffixLength = 0;
            while (
                suffixLength < original.length - prefixLength
                && suffixLength < revised.length - prefixLength
                && original[original.length - 1 - suffixLength] === revised[revised.length - 1 - suffixLength]
            ) {
                suffixLength += 1;
            }
            const originalEnd = suffixLength ? original.length - suffixLength : original.length;
            const revisedEnd = suffixLength ? revised.length - suffixLength : revised.length;
            return mergeVideoDirectionDiffOperations([
                {type: 'equal', text: original.slice(0, prefixLength)},
                {type: 'remove', text: original.slice(prefixLength, originalEnd)},
                {type: 'add', text: revised.slice(prefixLength, revisedEnd)},
                {type: 'equal', text: suffixLength ? original.slice(originalEnd) : ''},
            ]);
        }

        function computeVideoDirectionSequenceDiff(before, after, maxCells) {
            if (before.length * after.length > maxCells) return null;
            const rows = Array.from(
                {length: before.length + 1},
                () => new Uint16Array(after.length + 1),
            );
            for (let i = 1; i <= before.length; i += 1) {
                for (let j = 1; j <= after.length; j += 1) {
                    rows[i][j] = before[i - 1] === after[j - 1]
                        ? rows[i - 1][j - 1] + 1
                        : Math.max(rows[i - 1][j], rows[i][j - 1]);
                }
            }
            const operations = [];
            let i = before.length;
            let j = after.length;
            while (i > 0 || j > 0) {
                if (i > 0 && j > 0 && before[i - 1] === after[j - 1]) {
                    operations.push({type: 'equal', text: before[i - 1]});
                    i -= 1;
                    j -= 1;
                } else if (j > 0 && (i === 0 || rows[i][j - 1] >= rows[i - 1][j])) {
                    operations.push({type: 'add', text: after[j - 1]});
                    j -= 1;
                } else {
                    operations.push({type: 'remove', text: before[i - 1]});
                    i -= 1;
                }
            }
            operations.reverse();
            return mergeVideoDirectionDiffOperations(operations);
        }

        function computeVideoDirectionTokenDiff(original, revised) {
            const before = videoDirectionDiffTokens(original);
            const after = videoDirectionDiffTokens(revised);
            const operations = computeVideoDirectionSequenceDiff(before, after, 800000);
            if (operations) return operations;
            console.error('[VIDEO_UI] 방향 명령의 변경 줄이 커서 해당 줄에 안전한 단순 비교를 사용합니다.', {
                beforeTokens: before.length,
                afterTokens: after.length,
            });
            return fallbackVideoDirectionDiff(original, revised);
        }

        function computeVideoDirectionHierarchicalDiff(original, revised) {
            const beforeLines = videoDirectionDiffLines(original);
            const afterLines = videoDirectionDiffLines(revised);
            const lineOperations = computeVideoDirectionSequenceDiff(beforeLines, afterLines, 500000);
            if (!lineOperations) {
                console.error('[VIDEO_UI] 방향 명령 줄 수가 너무 많아 문서 전체 단순 비교를 사용합니다.', {
                    beforeLines: beforeLines.length,
                    afterLines: afterLines.length,
                });
                return fallbackVideoDirectionDiff(original, revised);
            }

            const refined = [];
            for (let index = 0; index < lineOperations.length;) {
                const operation = lineOperations[index];
                if (operation.type === 'equal') {
                    refined.push(operation);
                    index += 1;
                    continue;
                }

                let removed = '';
                let added = '';
                while (index < lineOperations.length && lineOperations[index].type !== 'equal') {
                    const changed = lineOperations[index];
                    if (changed.type === 'remove') removed += changed.text;
                    else if (changed.type === 'add') added += changed.text;
                    index += 1;
                }
                if (removed && added) {
                    refined.push(...computeVideoDirectionTokenDiff(removed, added));
                } else if (removed) {
                    refined.push({type: 'remove', text: removed});
                } else if (added) {
                    refined.push({type: 'add', text: added});
                }
            }
            return mergeVideoDirectionDiffOperations(refined);
        }

        function computeVideoDirectionDiff(originalValue, revisedValue) {
            const original = String(originalValue || '');
            const revised = String(revisedValue || '');
            if (original === revised) return [{type: 'equal', text: original}];
            if (original.includes('\n') || revised.includes('\n')) {
                return computeVideoDirectionHierarchicalDiff(original, revised);
            }
            return computeVideoDirectionTokenDiff(original, revised);
        }

        function renderVideoDirectionEditDiff(original, revised) {
            const diff = document.getElementById('video-direction-edit-diff');
            if (!diff) {
                console.error('[VIDEO_UI] 다듬기 방향 명령 diff 표시 요소를 찾지 못했습니다.');
                return {added: 0, removed: 0};
            }
            const operations = computeVideoDirectionDiff(original, revised);
            let added = 0;
            let removed = 0;
            diff.innerHTML = operations.map(operation => {
                const safeText = escapeHtml(operation.text);
                if (operation.type === 'add') {
                    added += operation.text.length;
                    return `<ins class="video-direction-diff-add">${safeText}</ins>`;
                }
                if (operation.type === 'remove') {
                    removed += operation.text.length;
                    return `<del class="video-direction-diff-remove">${safeText}</del>`;
                }
                return safeText;
            }).join('');
            return {added, removed};
        }

        function showVideoDirectionEditReview() {
            const review = document.getElementById('video-direction-edit-review');
            const round = document.getElementById('video-direction-edit-round');
            const command = document.getElementById('video-direction-edit-command');
            const commandLabel = document.getElementById('video-direction-edit-command-label');
            const run = document.getElementById('video-direction-edit-run');
            const more = document.getElementById('video-direction-edit-more');
            const revert = document.getElementById('video-direction-edit-revert');
            const accept = document.getElementById('video-direction-edit-accept');
            if (!review || !round || !command || !run || !more || !revert || !accept) {
                console.error('[VIDEO_UI] 다듬기 방향 명령 검토 UI 요소가 누락되었습니다.');
                return;
            }
            const counts = renderVideoDirectionEditDiff(
                videoDirectionEditState.baseInstruction,
                videoDirectionEditState.candidateInstruction,
            );
            review.hidden = false;
            setVideoDirectionEditReviewLayout(true);
            round.textContent = `수정안 ${videoDirectionEditState.round}`;
            command.value = '';
            command.placeholder = '추가로 바꿀 내용을 입력한 뒤 “더 바꾸기”를 누르세요.';
            if (commandLabel) commandLabel.textContent = '추가 수정 방향';
            run.hidden = true;
            more.hidden = false;
            revert.hidden = false;
            accept.hidden = false;
            accept.disabled = videoDirectionEditState.candidateInstruction === videoDirectionEditState.baseInstruction;
            const summary = counts.added || counts.removed
                ? `수정안 ${videoDirectionEditState.round} 준비 완료 · 원문 대비 추가 ${counts.added}자, 삭제 ${counts.removed}자`
                : `수정안 ${videoDirectionEditState.round}에 원문과 다른 내용이 없습니다.`;
            setVideoDirectionEditStatus(summary, 'ready');
        }

        async function requestVideoDirectionEdit() {
            if (videoInstructionDraftBusy || videoInstructionRefineBusy || videoInstructionDirectBusy || videoDirectionEditBusy) return;
            const commandInput = document.getElementById('video-direction-edit-command');
            const editDirection = String(commandInput?.value || '').trim();
            if (!editDirection) {
                console.error('[VIDEO_UI] 다듬기 방향 명령 요청 실패: 수정 방향이 비어 있습니다.');
                showToast('원하는 수정 방향을 입력해 주세요.', 'warning');
                commandInput?.focus();
                return;
            }
            const instruction = videoDirectionEditState.candidateInstruction
                || videoDirectionEditState.baseInstruction;
            if (!instruction) {
                console.error('[VIDEO_UI] 다듬기 방향 명령 요청 실패: 수정 기준 문장이 비어 있습니다.');
                showToast('수정할 영상 지시 원문이 없습니다.', 'error');
                return;
            }
            const sourceKey = document.getElementById('video-generation-source')?.value || '';
            const sourceRef = getVideoReferenceByKey(sourceKey)?.reference || null;
            const mode = document.getElementById('video-generation-mode')?.value || 'i2v';
            const lastRef = getEffectiveLastVideoReference();
            if (!sourceRef) {
                console.error('[VIDEO_UI] 다듬기 방향 명령 요청 실패: 원본 참조 없음', {sourceKey});
                showToast('수정을 위한 원본 이미지 정보가 없습니다.', 'error');
                return;
            }
            if (mode === 'first_last' && !lastRef) {
                console.error('[VIDEO_UI] 다듬기 방향 명령 요청 실패: 마지막 프레임 없음');
                showToast('수정을 위한 마지막 프레임을 선택하세요.', 'warning');
                return;
            }
            const requestId = ++videoDirectionEditRequestId;
            const inputFlowSessionId = videoInputFlowSessionId;
            const selectionKey = videoDirectionEditState.selectionKey;
            setVideoDirectionEditBusy(true);
            setVideoDirectionEditStatus('원문을 보존하며 명령한 부분만 최소 수정하는 중...', 'busy');
            try {
                await videoInputFlowEventChain;
                const data = await fetchJSON('/api/video/instruction-refine', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        video_input_session_id: inputFlowSessionId,
                        mode,
                        workflow_variant: selectedVideoWorkflowVariant(),
                        instruction,
                        edit_direction: editDirection,
                        source_ref: sourceRef,
                        last_ref: lastRef,
                        reference_refs: getSelectedVideoReferenceRefs(),
                        source_backup: sourceRef.kind === 'backup' ? sourceRef.name : '',
                        last_backup: lastRef?.kind === 'backup' ? lastRef.name : '',
                        loop: isVideoLoopEnabled(),
                        aspect_ratio: document.getElementById('video-generation-aspect-ratio')?.value || 'auto',
                        quality_level: document.getElementById('video-generation-quality-level')?.value || 'medium',
                        duration: normalizedVideoDuration(),
                        language: selectedVideoInstructionLanguage(),
                        include_dialogue_context: isVideoDialogueContextEnabled(),
                        allow_camera_motion: isVideoCameraMotionAllowed(),
                        allow_background_change: isVideoBackgroundChangeAllowed(),
                    }),
                });
                if (requestId !== videoDirectionEditRequestId) {
                    console.error('[VIDEO_UI] 닫히거나 교체된 다듬기 방향 명령 응답 무시:', data);
                    return;
                }
                if (!data.success || !String(data.draft || '').trim()) {
                    throw new Error(data.error || '다듬기 방향 명령 처리 실패');
                }
                if (selectionKey !== videoInstructionDraftSelectionKey()) {
                    console.error('[VIDEO_UI] 원본 선택 변경 후 도착한 다듬기 방향 명령 결과 미적용:', data);
                    setVideoDirectionEditStatus('영상화 선택값이 바뀌어 수정안을 적용하지 않았습니다. 창을 닫고 다시 시도해 주세요.', 'error');
                    showToast('영상화 선택값이 바뀌어 수정안을 적용하지 않았습니다.', 'warning');
                    return;
                }
                videoDirectionEditState.candidateInstruction = String(data.draft).trim();
                videoDirectionEditState.llmTrace = normalizeVideoInstructionLlmTrace([
                    ...videoDirectionEditState.llmTrace,
                    ...normalizeVideoInstructionLlmTrace(data.llm_trace),
                ]);
                videoDirectionEditState.round += 1;
                showVideoDirectionEditReview();
            } catch (error) {
                if (requestId !== videoDirectionEditRequestId) return;
                console.error('[VIDEO_UI] 다듬기 방향 명령 처리 실패:', error, {
                    mode,
                    instruction,
                    editDirection,
                    sourceRef,
                    lastRef,
                });
                setVideoDirectionEditStatus(`수정안 생성 실패: ${error.message || error}`, 'error');
                showToast('수정안 생성 실패: ' + (error.message || error), 'error');
            } finally {
                if (requestId === videoDirectionEditRequestId) {
                    setVideoDirectionEditBusy(false);
                    const accept = document.getElementById('video-direction-edit-accept');
                    if (accept && !accept.hidden) {
                        accept.disabled = videoDirectionEditState.candidateInstruction === videoDirectionEditState.baseInstruction;
                    }
                }
            }
        }

        function requestMoreVideoDirectionEdit() {
            const command = document.getElementById('video-direction-edit-command');
            if (!String(command?.value || '').trim()) {
                console.error('[VIDEO_UI] 추가 다듬기 방향 명령 요청 실패: 추가 수정 방향이 비어 있습니다.');
                showToast('추가로 바꿀 내용을 입력해 주세요.', 'warning');
                command?.focus();
                return;
            }
            return requestVideoDirectionEdit();
        }

        function revertVideoDirectionEditPreview() {
            if (videoDirectionEditBusy) {
                console.error('[VIDEO_UI] 처리 중에는 다듬기 방향 수정안을 되돌릴 수 없습니다.');
                return;
            }
            const discardedState = {
                instruction: String(videoDirectionEditState.candidateInstruction || ''),
                base_instruction: String(videoDirectionEditState.baseInstruction || ''),
                round: videoDirectionEditState.round,
                llm_trace: [...videoDirectionEditState.llmTrace],
            };
            videoDirectionEditState.candidateInstruction = '';
            videoDirectionEditState.llmTrace = [];
            videoDirectionEditState.round = 0;
            const review = document.getElementById('video-direction-edit-review');
            const diff = document.getElementById('video-direction-edit-diff');
            const command = document.getElementById('video-direction-edit-command');
            const commandLabel = document.getElementById('video-direction-edit-command-label');
            const run = document.getElementById('video-direction-edit-run');
            const more = document.getElementById('video-direction-edit-more');
            const revert = document.getElementById('video-direction-edit-revert');
            const accept = document.getElementById('video-direction-edit-accept');
            if (review) review.hidden = true;
            setVideoDirectionEditReviewLayout(false);
            if (diff) diff.textContent = '';
            if (command) {
                command.value = '';
                command.placeholder = '예: 카메라 움직임은 그대로 두고, 인물이 고개를 드는 속도만 더 느리게 바꿔줘.';
                command.focus();
            }
            if (commandLabel) commandLabel.textContent = '원하는 수정 방향';
            if (run) run.hidden = false;
            if (more) more.hidden = true;
            if (revert) revert.hidden = true;
            if (accept) accept.hidden = true;
            void recordVideoInputFlowEvent(
                'discard_direction',
                discardedState,
                {instruction: discardedState.base_instruction},
            );
            setVideoDirectionEditStatus('검토 중이던 수정안을 버리고 최초 원문으로 되돌렸습니다.');
            showToast('수정안을 버리고 최초 원문으로 되돌렸습니다.', 'info');
        }

        function acceptVideoDirectionEdit() {
            const candidate = String(videoDirectionEditState.candidateInstruction || '').trim();
            const baseInstruction = String(videoDirectionEditState.baseInstruction || '').trim();
            const baseSnapshot = videoDirectionEditState.baseSnapshot;
            if (!candidate || !baseInstruction || !baseSnapshot) {
                console.error('[VIDEO_UI] 다듬기 방향 수정안 적용 상태가 올바르지 않습니다.', {
                    candidateLength: candidate.length,
                    baseLength: baseInstruction.length,
                    hasSnapshot: !!baseSnapshot,
                });
                showToast('적용할 수정안이 없습니다.', 'error');
                return;
            }
            if (candidate === baseInstruction) {
                console.error('[VIDEO_UI] 원문과 같은 다듬기 방향 수정안은 적용하지 않습니다.');
                showToast('원문과 달라진 내용이 없습니다.', 'info');
                return;
            }
            const target = document.getElementById('video-generation-instruction');
            if (!target) {
                console.error('[VIDEO_UI] 다듬기 방향 수정안을 적용할 영상 지시 입력란을 찾지 못했습니다.');
                showToast('영상 지시 입력란을 찾지 못했습니다.', 'error');
                return;
            }
            if (String(target.value || '').trim() !== baseInstruction) {
                console.error('[VIDEO_UI] 검토 중 원문이 변경되어 다듬기 방향 수정안을 적용하지 않았습니다.', {
                    expected: baseInstruction,
                    actual: target.value,
                });
                showToast('검토 중 원문이 바뀌었습니다. 창을 닫고 다시 시도해 주세요.', 'warning');
                return;
            }
            videoInstructionRefineUndoSnapshot = baseSnapshot;
            videoInstructionOriginalInput = String(baseSnapshot.originalInput || '');
            videoInstructionLlmTrace = normalizeVideoInstructionLlmTrace(baseSnapshot.llmTrace);
            appendVideoInstructionProvenance(baseInstruction, videoDirectionEditState.llmTrace);
            void recordVideoInputFlowEvent(
                'apply_direction',
                {
                    instruction: baseInstruction,
                    candidate_instruction: candidate,
                    round: videoDirectionEditState.round,
                    llm_trace: [...videoDirectionEditState.llmTrace],
                },
                {instruction: candidate, llm_trace: [...videoInstructionLlmTrace]},
            );
            target.value = candidate;
            resizeVideoInstructionToContent(target);
            showVideoInstructionRefineUndo();
            const appliedRound = videoDirectionEditState.round;
            closeVideoDirectionEditModal();
            target.focus();
            updateVideoInstructionDraftPresentation(
                `방향 명령 수정안 ${appliedRound} 적용 완료 · ↩ 원문으로 되돌리기로 복구 가능.`
            );
            showToast('검토한 수정안을 영상 지시에 적용했습니다.', 'success');
        }

        function selectVideoUpscaleScale(value, userInitiated = false) {
            const normalized = ['2', '3', '4'].includes(String(value)) ? String(value) : '2';
            const hidden = document.getElementById('video-generation-upscale-scale');
            if (!hidden) {
                console.error('[VIDEO_UI] 업스케일 배율 값을 저장할 요소가 없습니다.');
                return;
            }
            if (userInitiated) videoPostprocessSynced = true;
            hidden.value = normalized;
            const radio = document.querySelector(`input[name="video-upscale-scale-choice"][value="${normalized}"]`);
            if (radio) radio.checked = true;
            updateVideoGenerationSummary();
        }

        function onVideoUpscaleModelChange() {
            // 서버 기본값은 최초 한 번만 적용하고, 이후에는 현재 페이지에서 고른 값을 유지한다.
            videoPostprocessSynced = true;
            updateVideoUpscaleControls();
        }

        function updateVideoUpscaleControls() {
            const enabled = document.getElementById('video-generation-upscale-enabled');
            const scaleGrid = document.getElementById('video-generation-upscale-scale-grid');
            const method = getSelectedVideoOption('video-upscale-model', 'realesr-animevideov3');
            if (!enabled || !scaleGrid) {
                console.error('[VIDEO_UI] 업스케일 컨트롤을 찾지 못했습니다.');
                return;
            }
            enabled.checked = method !== 'none';
            scaleGrid.classList.toggle('disabled', !enabled.checked);
            scaleGrid.setAttribute('aria-disabled', enabled.checked ? 'false' : 'true');
            updateVideoGenerationSummary();
        }

        function applyVideoGenerationDefaults(config) {
            const settings = config && typeof config.video_generation_defaults === 'object'
                ? config.video_generation_defaults
                : null;
            if (!settings) {
                console.error('[VIDEO_UI] 영상화 모달 기본 설정이 없거나 형식이 올바르지 않습니다:', config);
                return;
            }
            const duration = document.getElementById('video-generation-duration');
            const aspectRatio = document.getElementById('video-generation-aspect-ratio');
            const qualityLevel = document.getElementById('video-generation-quality-level');
            const workflowVariant = document.getElementById('video-generation-workflow-variant');
            const promptGenerationMode = document.getElementById('video-generation-prompt-generation-mode');
            const translateInstructionToEnglish = document.getElementById('video-generation-translate-instruction-to-english');
            const loop = document.getElementById('video-generation-loop');
            const language = document.getElementById('video-generation-instruction-language');
            const cameraMotion = document.getElementById('video-generation-allow-camera-motion');
            const backgroundChange = document.getElementById('video-generation-allow-background-change');
            const enabled = document.getElementById('video-generation-upscale-enabled');
            if (!duration || !aspectRatio || !qualityLevel || !workflowVariant || !promptGenerationMode || !translateInstructionToEnglish || !loop || !language
                    || !cameraMotion || !backgroundChange || !enabled) {
                console.error('[VIDEO_UI] 영상화 기본 설정을 적용할 컨트롤이 누락되었습니다.', {
                    duration: !!duration,
                    aspectRatio: !!aspectRatio,
                    qualityLevel: !!qualityLevel,
                    workflowVariant: !!workflowVariant,
                    promptGenerationMode: !!promptGenerationMode,
                    translateInstructionToEnglish: !!translateInstructionToEnglish,
                    loop: !!loop,
                    language: !!language,
                    cameraMotion: !!cameraMotion,
                    backgroundChange: !!backgroundChange,
                    upscaleEnabled: !!enabled,
                });
                return;
            }

            duration.value = String(settings.duration);
            aspectRatio.value = settings.aspect_ratio;
            qualityLevel.value = settings.quality_level;
            qualityLevel.dataset.defaultsApplied = settings.workflow_variant || 'standard';
            if (settings.workflow_variant === 'standard') {
                qualityLevel.dataset.standardValue = settings.quality_level;
            }
            updateVideoDuration();
            const defaultVariant = settings.workflow_variant || 'standard';
            selectVideoMode(settings.mode, defaultVariant);
            loop.checked = settings.mode === 'first_last' && settings.loop === true;
            onVideoLoopChange();

            setVideoVisualContextFromImage(settings.visual_context_source !== 'prompt');
            const savedPromptGenerationMode = String(
                settings.prompt_generation_mode || 'single'
            ).trim().toLowerCase();
            if (savedPromptGenerationMode === 'single' || savedPromptGenerationMode === 'best_of_three') {
                promptGenerationMode.value = savedPromptGenerationMode;
            } else {
                console.error('[VIDEO_UI] 저장된 최종 프롬프트 생성 방식이 올바르지 않습니다:', settings.prompt_generation_mode);
                promptGenerationMode.value = 'single';
            }
            translateInstructionToEnglish.checked = settings.translate_instruction_to_english === true;
            const refineVersionSelect = document.getElementById('video-generation-refine-version');
            if (refineVersionSelect) {
                const refineVersionValue = String(settings.refine_version || 'v1').trim().toLowerCase();
                if (['v1', 'v2', 'v3', 'v3_2', 'v4'].includes(refineVersionValue)) {
                    refineVersionSelect.value = refineVersionValue;
                } else {
                    console.error('[VIDEO_UI] 저장된 입력 다듬기 방식이 올바르지 않습니다:', settings.refine_version);
                    refineVersionSelect.value = 'v1';
                }
            }
            language.value = settings.instruction_language;
            setVideoDialogueContextEnabled(settings.include_dialogue_context === true);
            cameraMotion.checked = settings.allow_camera_motion === true;
            backgroundChange.checked = settings.allow_background_change === true;
            applyVideoSecondaryMotionConfig(config);
            updateVideoInstructionDraftPresentation();

            const model = settings.upscale_model;
            const modelRadio = document.querySelector(`input[name="video-upscale-model"][value="${model}"]`);
            if (!modelRadio) {
                console.error('[VIDEO_UI] 저장된 업스케일 방식에 대응하는 컨트롤이 없습니다:', model);
                return;
            }
            modelRadio.checked = true;
            enabled.checked = model !== 'none';
            const normalizedScale = String(settings.upscale_scale);
            selectVideoUpscaleScale(normalizedScale);
            updateVideoUpscaleControls();

            const outputRadio = document.querySelector(
                `input[name="video-output-format"][value="${settings.output_format}"]`
            );
            if (!outputRadio) {
                console.error('[VIDEO_UI] 저장된 출력 형식에 대응하는 컨트롤이 없습니다:', settings.output_format);
                return;
            }
            outputRadio.checked = true;

            const encodeQualityInput = document.getElementById('video-generation-encode-quality');
            if (encodeQualityInput) {
                const encodeQuality = Math.max(1, Math.min(100, Number.parseInt(settings.encode_quality, 10) || 80));
                encodeQualityInput.value = String(encodeQuality);
                onVideoEncodeQualityInput(String(encodeQuality));
            }

            const sharpenEnabled = document.getElementById('video-generation-sharpen-enabled');
            const sharpenRadius = document.getElementById('video-generation-sharpen-radius');
            const sharpenAmount = document.getElementById('video-generation-sharpen-amount');
            const sharpenThreshold = document.getElementById('video-generation-sharpen-threshold');
            if (sharpenEnabled && sharpenRadius && sharpenAmount && sharpenThreshold) {
                sharpenEnabled.checked = settings.sharpen_enabled === true;
                sharpenRadius.value = String(settings.sharpen_radius ?? 0.8);
                sharpenAmount.value = String(settings.sharpen_amount ?? 0.5);
                sharpenThreshold.value = String(settings.sharpen_threshold ?? 4);
                onVideoSharpenSliderInput('radius', sharpenRadius.value);
                onVideoSharpenSliderInput('amount', sharpenAmount.value);
                onVideoSharpenSliderInput('threshold', sharpenThreshold.value);
                onVideoSharpenToggle();
            }
            videoPostprocessSynced = true;
            updateVideoGenerationSummary();
        }

        function collectVideoGenerationDefaults() {
            const secondaryMotion = document.getElementById('video-generation-secondary-motion');
            const translateInstructionToEnglish = document.getElementById('video-generation-translate-instruction-to-english');
            if (!secondaryMotion || !translateInstructionToEnglish) {
                console.error('[VIDEO_UI] 영상화 저장 설정 컨트롤이 없습니다.', {
                    secondaryMotion: !!secondaryMotion,
                    translateInstructionToEnglish: !!translateInstructionToEnglish,
                });
                throw new Error('영상화 저장 설정 컨트롤을 찾지 못했습니다.');
            }
            return {
                defaults: {
                    mode: document.getElementById('video-generation-mode')?.value || 'i2v',
                    workflow_variant: selectedVideoWorkflowVariant(),
                    duration: normalizedVideoDuration(),
                    aspect_ratio: document.getElementById('video-generation-aspect-ratio')?.value || 'auto',
                    quality_level: document.getElementById('video-generation-quality-level')?.value || 'medium',
                    loop: isVideoLoopEnabled(),
                    visual_context_source: selectedVideoVisualContextSource(),
                    prompt_generation_mode: document.getElementById('video-generation-prompt-generation-mode')?.value || 'single',
                    translate_instruction_to_english: translateInstructionToEnglish.checked,
                    instruction_language: selectedVideoInstructionLanguage(),
                    refine_version: selectedVideoInstructionRefineVersion(),
                    include_dialogue_context: isVideoDialogueContextEnabled(),
                    allow_camera_motion: isVideoCameraMotionAllowed(),
                    allow_background_change: isVideoBackgroundChangeAllowed(),
                    upscale_model: getSelectedVideoOption('video-upscale-model', 'realesr-animevideov3'),
                    upscale_scale: Number(document.getElementById('video-generation-upscale-scale')?.value || 2),
                    output_format: getSelectedVideoOption('video-output-format', 'avif'),
                    encode_quality: normalizedVideoEncodeQuality(),
                    ...collectVideoSharpenParams(),
                },
                secondaryMotion: secondaryMotion.checked,
            };
        }

        async function saveVideoGenerationDefaults() {
            const button = document.getElementById('video-generation-save-settings');
            if (!button) {
                console.error('[VIDEO_UI] 영상화 설정 저장 버튼을 찾지 못했습니다.');
                return;
            }
            const originalText = button.innerHTML;
            button.disabled = true;
            button.innerHTML = '<span class="spinner"></span> 저장 중';
            try {
                const collected = collectVideoGenerationDefaults();
                const result = await fetchJSON('/api/config', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        _origin: 'saveVideoGenerationDefaults',
                        video_generation_defaults: collected.defaults,
                        video_secondary_motion: collected.secondaryMotion,
                    }),
                });
                if (!result?.success || !result.config) {
                    console.error('[VIDEO_UI] 영상화 설정 저장 응답 형식 오류:', result);
                    throw new Error(result?.error || '설정 저장 응답이 올바르지 않습니다.');
                }
                currentConfig = result.config;
                currentConfigLoadPromise = Promise.resolve(currentConfig);
                showToast('영상화 설정을 영구 저장했습니다.', 'success');
            } catch (error) {
                console.error('[VIDEO_UI] 영상화 설정 저장 실패:', error);
                showToast('영상화 설정 저장 실패: ' + (error?.message || error), 'error');
            } finally {
                button.disabled = false;
                button.innerHTML = originalText;
            }
        }

        function normalizedVideoDuration() {
            const input = document.getElementById('video-generation-duration');
            const parsed = Number.parseInt(input?.value || '5', 10);
            return Math.max(1, Math.min(15, Number.isFinite(parsed) ? parsed : 5));
        }

        function updateVideoDuration() {
            const input = document.getElementById('video-generation-duration');
            const duration = normalizedVideoDuration();
            if (input) input.value = String(duration);
            const header = document.getElementById('video-generation-header-summary');
            if (header) header.textContent = `MiniMax H3 · ${duration}초`;
            updateVideoInstructionDraftPresentation();
            updateVideoWorkspaceMode();
            updateVideoGenerationSummary();
        }

        function adjustVideoDuration(delta) {
            const input = document.getElementById('video-generation-duration');
            if (!input) {
                console.error('[VIDEO_UI] 영상 길이 입력 요소를 찾지 못했습니다.');
                return;
            }
            input.value = String(normalizedVideoDuration() + Number(delta || 0));
            updateVideoDuration();
        }

        function updateVideoGenerationSummary() {
            const target = document.getElementById('video-generation-summary-detail');
            if (!target) return;
            const duration = normalizedVideoDuration();
            const aspectSelect = document.getElementById('video-generation-aspect-ratio');
            const qualitySelect = document.getElementById('video-generation-quality-level');
            const requestedAspect = aspectSelect?.value || 'auto';
            const workflowVariant = selectedVideoWorkflowVariant();
            const resolution = getVideoFastResolutionPreview();
            const aspectLabel = requestedAspect === 'auto'
                ? resolution ? `자동→${resolution.aspectRatio}` : '자동'
                : requestedAspect;
            const qualityLabel = qualitySelect?.selectedOptions?.[0]?.textContent
                ?.replace(' · ', ' ') || 'FAST 기본 0.35 MP';
            const resolutionLabel = resolution
                ? `${resolution.width}×${resolution.height}`
                : '원본 분석 후 결정';
            const method = getSelectedVideoOption('video-upscale-model', 'realesr-animevideov3');
            const scale = document.getElementById('video-generation-upscale-scale')?.value || '2';
            const upscaleLabel = method === 'none'
                ? VIDEO_UPSCALE_LABELS.none
                : `${VIDEO_UPSCALE_LABELS[method] || method} ${scale}×`;
            const output = getSelectedVideoOption('video-output-format', 'avif').toUpperCase();
            const encodeQuality = normalizedVideoEncodeQuality();
            const visualContextLabel = isVideoVisualContextFromImage()
                ? ' · VC 그림 분석'
                : ' · VC 프롬프트';
            const sharpenOn = document.getElementById('video-generation-sharpen-enabled')?.checked === true;
            const sharpenLabel = sharpenOn
                ? ` · 선명화 r${Number(document.getElementById('video-generation-sharpen-radius')?.value || 0.8).toFixed(1)}/a${Number(document.getElementById('video-generation-sharpen-amount')?.value || 0.5).toFixed(2)}/t${document.getElementById('video-generation-sharpen-threshold')?.value || 4}`
                : '';
            target.textContent = `${duration}초 · ${aspectLabel} · ${qualityLabel} · ${resolutionLabel} · ${upscaleLabel} · ${output} · 품질${encodeQuality}${visualContextLabel}${sharpenLabel}`;
        }

        function onVideoSharpenToggle() {
            const enabled = document.getElementById('video-generation-sharpen-enabled')?.checked === true;
            const controls = document.getElementById('video-sharpen-controls');
            if (controls) controls.hidden = !enabled;
            updateVideoGenerationSummary();
        }

        function onVideoSharpenSliderInput(name, value) {
            const valEl = document.getElementById(`video-generation-sharpen-${name}-val`);
            if (valEl) {
                if (name === 'amount') valEl.textContent = Number(value).toFixed(2);
                else if (name === 'radius') valEl.textContent = Number(value).toFixed(1);
                else valEl.textContent = String(value);
            }
            updateVideoGenerationSummary();
        }

        function normalizedVideoEncodeQuality() {
            const input = document.getElementById('video-generation-encode-quality');
            const parsed = Number.parseInt(input?.value || '80', 10);
            return Math.max(1, Math.min(100, Number.isFinite(parsed) ? parsed : 80));
        }

        function onVideoEncodeQualityInput(value) {
            const quality = normalizedVideoEncodeQuality();
            const input = document.getElementById('video-generation-encode-quality');
            if (input) input.value = String(quality);
            const valEl = document.getElementById('video-generation-encode-quality-val');
            if (valEl) valEl.textContent = String(quality);
            updateVideoGenerationSummary();
        }

        function collectVideoSharpenParams() {
            return {
                sharpen_enabled: document.getElementById('video-generation-sharpen-enabled')?.checked === true,
                sharpen_radius: Number(document.getElementById('video-generation-sharpen-radius')?.value || 0.8),
                sharpen_amount: Number(document.getElementById('video-generation-sharpen-amount')?.value || 0.5),
                sharpen_threshold: Number(document.getElementById('video-generation-sharpen-threshold')?.value || 4),
            };
        }

        async function previewVideoSharpen() {
            const sourceKey = document.getElementById('video-generation-source')?.value || '';
            const sourceRef = getVideoReferenceByKey(sourceKey)?.reference || null;
            if (!sourceRef) {
                showToast('시작 프레임 이미지를 먼저 선택하세요.', 'warning');
                return;
            }
            const button = document.getElementById('video-generation-sharpen-preview');
            const originalText = button?.innerHTML || '🔍 미리보기';
            if (button) {
                button.disabled = true;
                button.innerHTML = '<span class="spinner"></span> 생성 중';
            }
            try {
                const params = Object.assign({
                    source_ref: sourceRef,
                    source_backup: sourceRef.kind === 'backup' ? sourceRef.name : '',
                    workflow_variant: selectedVideoWorkflowVariant(),
                    aspect_ratio: document.getElementById('video-generation-aspect-ratio')?.value || 'auto',
                    quality_level: document.getElementById('video-generation-quality-level')?.value || 'medium',
                }, collectVideoSharpenParams());
                const resp = await fetch('/api/video/sharpen_preview', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify(params),
                });
                if (!resp.ok) {
                    let msg = `미리보기 생성 실패 (HTTP ${resp.status})`;
                    try {
                        const err = await resp.json();
                        if (err?.error) msg = err.error;
                    } catch (_) {}
                    throw new Error(msg);
                }
                const blob = await resp.blob();
                openLightbox(URL.createObjectURL(blob));
            } catch (error) {
                console.error('[VIDEO_UI] 샤프닝 미리보기 실패:', error);
                showToast('샤프닝 미리보기 실패: ' + (error?.message || error), 'error');
            } finally {
                if (button) {
                    button.disabled = false;
                    button.innerHTML = originalText;
                }
            }
        }

        function updateVideoWorkspaceMode() {
            const mode = document.getElementById('video-generation-mode')?.value || 'i2v';
            const workflowVariant = selectedVideoWorkflowVariant();
            const fixedSteps = selectedVideoEngineFixedSteps();
            const engineSelected = isVideoEngineSelected();
            const steps = engineSelected ? videoEngineStepsValue() : null;
            const isLast = mode === 'first_last';
            const isRef = mode === 'ref2v';
            const lastFrame = document.getElementById('video-frame-last');
            const referencePanel = document.getElementById('video-frame-references');
            const modeNote = document.getElementById('video-generation-mode-note');
            const sourceTitle = document.getElementById('video-generation-source-title');
            const sourceBadge = document.getElementById('video-generation-source-badge');
            const sharpenSection = document.getElementById('video-sharpen-section');
            const duration = normalizedVideoDuration();
            const header = document.getElementById('video-generation-header-summary');
            if (header) {
                header.textContent = engineSelected
                    ? `MiniMax H3 · ${steps}-step${fixedSteps !== null ? ' 고정' : ''} · ${duration}초`
                    : `MiniMax H3${workflowVariant === 'fast' ? ' 고속' : ''} · ${duration}초`;
            }
            if (lastFrame) lastFrame.style.display = isLast ? 'block' : 'none';
            if (referencePanel) referencePanel.style.display = isRef ? 'block' : 'none';
            if (sourceTitle) sourceTitle.textContent = isRef ? 'REF 이미지 1' : '시작 프레임';
            if (sourceBadge) {
                const sourceKind = videoWorkspaceSourceRef?.kind === 'asset' ? '에셋' : '삽화';
                sourceBadge.textContent = isRef
                    ? `${sourceKind} · 참조 1`
                    : `선택 ${sourceKind}`;
            }
            if (sharpenSection) sharpenSection.style.display = isRef ? 'none' : '';
            if (modeNote) {
                const sourceLabel = videoWorkspaceSourceRef?.kind === 'asset'
                    ? '선택 에셋'
                    : '선택 삽화의 원본';
                const speedLabel = workflowVariant === 'fast' ? '고속으로 ' : '';
                modeNote.textContent = engineSelected
                    ? `${sourceLabel}을 사용해 설정에서 선택한 H3 모델과 ${steps}-step${fixedSteps !== null ? ' 고정값' : ''}으로 ${duration}초 영상을 만듭니다.`
                    : (isRef
                        ? `${sourceLabel}을 참조 1로 사용하고, 선택한 총 ${getSelectedVideoReferenceRefs().length}장의 독립 REF 이미지로 ${duration}초 영상을 만듭니다. ${workflowVariant === 'fast' ? '전용 4-step' : 'Base 20-step + TeaCache 0.10'}의 REF 기본은 16:9 · 960×544이며, 그 밖의 비율·MP는 실험 옵션입니다.`
                        : (isLast
                            ? `${speedLabel}${sourceLabel}을 0초, 선택한 마지막 프레임을 ${duration}초에 정렬합니다.`
                            : `${speedLabel}${sourceLabel}을 시작 프레임으로 사용해 ${duration}초 영상을 만듭니다.`));
            }
            const loopCheckbox = document.getElementById('video-generation-loop');
            if (loopCheckbox) {
                loopCheckbox.style.visibility = isLast ? 'visible' : 'hidden';
                if (!isLast) {
                    loopCheckbox.checked = false;
                    onVideoLoopChange();
                }
            }
        }

        function selectVideoMode(mode, workflowVariant = 'standard') {
            if (!['i2v', 'first_last', 'ref2v'].includes(mode)) {
                console.error('[VIDEO_UI] 지원하지 않는 내부 탭:', mode);
                return;
            }
            if (!['standard', 'fast'].includes(workflowVariant)) {
                console.error('[VIDEO_UI] 지원하지 않는 워크플로우 변형:', workflowVariant);
                return;
            }
            if (isVideoEngineSelected()) workflowVariant = 'standard';
            const input = document.getElementById('video-generation-mode');
            const variantInput = document.getElementById('video-generation-workflow-variant');
            if (input) input.value = mode;
            if (variantInput) variantInput.value = workflowVariant;
            const radio = document.querySelector(
                `input[name="video-mode-choice"][value="${mode}:${workflowVariant}"]`
            );
            if (radio) radio.checked = true;
            updateVideoResolutionControls();
            refreshVideoRefOptions(
                document.getElementById('video-generation-source')?.value || ''
            );
            updateVideoWorkspaceMode();
            updateVideoVisualContextSourcePresentation();
            updateVideoInstructionDraftPresentation();
            updateVideoGenerationSummary();
            updateVideoEngineFixedStepControls();
        }

        function refreshVideoLastFrameOptions(sourceKey) {
            const input = document.getElementById('video-generation-last');
            if (!input) {
                console.error('[VIDEO_UI] 마지막 프레임 값을 찾지 못했습니다.');
                return;
            }
            if (input.value && input.value === sourceKey) {
                console.error('[VIDEO_UI] 시작·마지막 프레임 중복 선택 해제:', sourceKey);
                input.value = '';
            }
            onVideoLastFrameChange();
        }

        function onVideoLastFrameChange() {
            const input = document.getElementById('video-generation-last');
            const preview = document.getElementById('video-generation-last-preview');
            const empty = document.getElementById('video-generation-last-empty');
            const nameLabel = document.getElementById('video-generation-last-name');
            if (!input || !preview || !empty || !nameLabel) {
                console.error('[VIDEO_UI] 마지막 프레임 미리보기 UI 요소를 찾지 못했습니다.');
                return;
            }
            const last = getVideoReferenceByKey(input.value);
            if (!last) {
                preview.removeAttribute('src');
                preview.style.display = 'none';
                empty.style.display = 'flex';
                nameLabel.textContent = '';
                updateVideoInstructionDraftPresentation();
                return;
            }
            preview.onerror = () => {
                console.error('[VIDEO_UI] 마지막 프레임 미리보기 로드 실패:', last.image_url);
                preview.style.display = 'none';
                empty.textContent = '미리보기를 불러오지 못했습니다.';
                empty.style.display = 'flex';
            };
            empty.textContent = '마지막 프레임으로 사용할 이미지를 선택하세요.';
            preview.src = last.image_url;
            preview.style.display = 'block';
            empty.style.display = 'none';
            nameLabel.textContent = last.label;
            updateVideoInstructionDraftPresentation();
        }

        function isVideoLoopEnabled() {
            const mode = document.getElementById('video-generation-mode')?.value || 'i2v';
            if (mode !== 'first_last') return false;
            return document.getElementById('video-generation-loop')?.checked === true;
        }

        function getEffectiveLastVideoReference() {
            const mode = document.getElementById('video-generation-mode')?.value || 'i2v';
            if (mode !== 'first_last') return null;
            if (isVideoLoopEnabled()) {
                return getVideoReferenceByKey(
                    document.getElementById('video-generation-source')?.value || ''
                )?.reference || null;
            }
            return getVideoReferenceByKey(
                document.getElementById('video-generation-last')?.value || ''
            )?.reference || null;
        }

        function getSelectedVideoReferenceRefs() {
            const sourceKey = document.getElementById('video-generation-source')?.value || '';
            const source = getVideoReferenceByKey(sourceKey)?.reference || null;
            if (!source) return [];
            const refs = [source];
            for (const index of [2, 3]) {
                const key = document.getElementById(`video-generation-ref-${index}`)?.value || '';
                const reference = getVideoReferenceByKey(key)?.reference || null;
                if (reference) refs.push(reference);
            }
            return refs;
        }

        function renderVideoRefPreview(index) {
            const select = document.getElementById(`video-generation-ref-${index}`);
            const preview = document.getElementById(`video-generation-ref-${index}-preview`);
            const empty = document.getElementById(`video-generation-ref-${index}-empty`);
            const nameLabel = document.getElementById(`video-generation-ref-${index}-name`);
            if (!select || !preview || !empty || !nameLabel) {
                console.error('[VIDEO_UI] REF 미리보기 UI 요소 누락:', index);
                return;
            }
            const option = getVideoReferenceByKey(select.value);
            if (!option) {
                preview.onerror = null;
                preview.removeAttribute('src');
                preview.style.display = 'none';
                empty.textContent = '선택 안 함';
                empty.style.display = 'flex';
                nameLabel.textContent = '';
                return;
            }
            preview.onerror = () => {
                console.error('[VIDEO_UI] REF 미리보기 로드 실패:', {
                    index,
                    url: option.image_url,
                });
                preview.style.display = 'none';
                empty.textContent = '미리보기를 불러오지 못했습니다.';
                empty.style.display = 'flex';
            };
            preview.src = option.image_url;
            preview.style.display = 'block';
            empty.style.display = 'none';
            nameLabel.textContent = option.label;
        }

        function refreshVideoRefOptions(sourceKey) {
            const selections = {
                2: document.getElementById('video-generation-ref-2')?.value || '',
                3: document.getElementById('video-generation-ref-3')?.value || '',
            };
            for (const index of [2, 3]) {
                const input = document.getElementById(`video-generation-ref-${index}`);
                if (!input) {
                    console.error('[VIDEO_UI] REF 값 누락:', index);
                    continue;
                }
                const otherIndex = index === 2 ? 3 : 2;
                if (input.value && (input.value === sourceKey || input.value === selections[otherIndex])) {
                    console.error('[VIDEO_UI] REF 중복 선택 해제:', {
                        index,
                        value: input.value,
                    });
                    input.value = '';
                    selections[index] = '';
                }
                renderVideoRefPreview(index);
            }
            updateVideoInstructionDraftPresentation();
            updateVideoWorkspaceMode();
        }

        function onVideoRefChange(index) {
            const input = document.getElementById(`video-generation-ref-${index}`);
            const otherIndex = index === 2 ? 3 : 2;
            const otherValue = document.getElementById(`video-generation-ref-${otherIndex}`)?.value || '';
            const sourceKey = document.getElementById('video-generation-source')?.value || '';
            if (!input) {
                console.error('[VIDEO_UI] 변경된 REF 값을 찾지 못했습니다:', index);
                return;
            }
            if (input.value && (input.value === sourceKey || input.value === otherValue)) {
                console.error('[VIDEO_UI] REF 이미지 중복 선택:', {
                    index,
                    value: input.value,
                    sourceKey,
                    otherValue,
                });
                input.value = '';
                showToast('REF 이미지는 서로 다르게 선택하세요.', 'warning');
            }
            refreshVideoRefOptions(sourceKey);
            updateVideoGenerationSummary();
        }

        function syncVideoLastPreviewToSource() {
            const preview = document.getElementById('video-generation-last-preview');
            const empty = document.getElementById('video-generation-last-empty');
            const nameLabel = document.getElementById('video-generation-last-name');
            if (!preview || !empty || !nameLabel) {
                console.error('[VIDEO_UI] 마지막 프레임 미리보기 UI 요소를 찾지 못했습니다.');
                return;
            }
            const sourceKey = document.getElementById('video-generation-source')?.value || '';
            const source = getVideoReferenceByKey(sourceKey);
            if (!source) {
                preview.onerror = null;
                preview.removeAttribute('src');
                preview.style.display = 'none';
                empty.textContent = '먼저 첫 프레임 백업을 선택하세요.';
                empty.style.display = 'flex';
                nameLabel.textContent = '';
                return;
            }
            preview.onerror = () => {
                console.error('[VIDEO_UI] 루프 모드 마지막 프레임 미리보기 로드 실패:', source.image_url);
                preview.style.display = 'none';
                empty.textContent = '미리보기를 불러오지 못했습니다.';
                empty.style.display = 'flex';
            };
            empty.style.display = 'none';
            preview.src = source.image_url;
            preview.style.display = 'block';
            nameLabel.textContent = source.label + ' · (첫 프레임과 동일 · 루프)';
        }

        function onVideoLoopChange() {
            const input = document.getElementById('video-generation-last');
            const selectButton = document.getElementById('video-generation-last-select');
            if (!input || !selectButton) {
                console.error('[VIDEO_UI] 루프 모드 마지막 프레임 UI가 없습니다.');
                return;
            }
            if (isVideoLoopEnabled()) {
                selectButton.disabled = true;
                input.value = '';
                syncVideoLastPreviewToSource();
            } else {
                selectButton.disabled = false;
                refreshVideoLastFrameOptions(document.getElementById('video-generation-source')?.value || '');
            }
            updateVideoInstructionDraftPresentation();
        }

        function onVideoSourceChange() {
            const select = document.getElementById('video-generation-source');
            const preview = document.getElementById('video-generation-source-preview');
            const empty = document.getElementById('video-generation-source-empty');
            const nameLabel = document.getElementById('video-generation-source-name');
            if (!select || !preview || !empty || !nameLabel) {
                console.error('[VIDEO_UI] 영상화 원본 UI 요소를 찾지 못했습니다.');
                return;
            }
            const source = getVideoReferenceByKey(select.value);
            if (!source) {
                preview.onload = null;
                preview.removeAttribute('src');
                preview.style.display = 'none';
                empty.style.display = 'flex';
                nameLabel.textContent = '';
                if (isVideoLoopEnabled()) syncVideoLastPreviewToSource();
                else refreshVideoLastFrameOptions('');
                refreshVideoRefOptions('');
                updateVideoInstructionDraftPresentation();
                updateVideoGenerationSummary();
                return;
            }
            preview.onload = () => {
                if (!preview.naturalWidth || !preview.naturalHeight) {
                    console.error('[VIDEO_UI] 기준 삽화 원본 크기를 읽지 못했습니다:', source);
                    return;
                }
                source.source_width = preview.naturalWidth;
                source.source_height = preview.naturalHeight;
                updateVideoGenerationSummary();
            };
            preview.onerror = () => {
                console.error('[VIDEO_UI] 기준 삽화 미리보기 로드 실패:', source.image_url);
                preview.style.display = 'none';
                empty.textContent = '미리보기를 불러오지 못했습니다. 원본 선택은 유지됩니다.';
                empty.style.display = 'flex';
                updateVideoGenerationSummary();
            };
            empty.textContent = '영상화할 원본 이미지를 선택하세요.';
            preview.src = source.image_url;
            preview.style.display = 'block';
            empty.style.display = 'none';
            nameLabel.textContent = source.label;
            if (isVideoLoopEnabled()) syncVideoLastPreviewToSource();
            else refreshVideoLastFrameOptions(source.key);
            refreshVideoRefOptions(source.key);
            updateVideoInstructionDraftPresentation();
            updateVideoGenerationSummary();
        }

        async function loadVideoReferenceOptions(preferredReference) {
            const sourceInput = document.getElementById('video-generation-source');
            if (!sourceInput) {
                console.error('[VIDEO_UI] 현재 카드 원본 값을 저장할 요소가 없습니다.');
                return;
            }
            const preferredKey = videoReferenceKey(preferredReference);
            const endpoint = videoReferenceDirectEndpoint(preferredReference);
            videoReferenceOptions = [];
            sourceInput.value = '';
            for (const id of [
                'video-generation-last',
                'video-generation-ref-2',
                'video-generation-ref-3',
            ]) {
                const input = document.getElementById(id);
                if (input) input.value = '';
            }
            onVideoSourceChange();
            if (!endpoint) {
                console.error('[VIDEO_UI] 현재 영상 참조 단건 URL을 만들지 못했습니다:', preferredReference);
                showToast('현재 영상 참조 정보를 불러오지 못했습니다.', 'error');
                return;
            }
            try {
                const data = await fetchJSON(endpoint);
                if (!data.success) throw new Error(data.error || '현재 영상 참조 조회 실패');
                registerVideoReferenceOptions(data.options);
                if (!videoReferenceOptions.length) {
                    console.error('[VIDEO_UI] 현재 영상화 참조 이미지를 찾지 못했습니다.');
                    sourceInput.value = '';
                    onVideoSourceChange();
                    return;
                }
                if (!videoReferenceOptions.some(item => item.key === preferredKey)) {
                    console.error('[VIDEO_UI] 현재 카드가 영상화 참조 목록에 없습니다:', preferredReference);
                    sourceInput.value = '';
                } else {
                    sourceInput.value = preferredKey;
                }
                onVideoSourceChange();
            } catch (error) {
                console.error('[VIDEO_UI] 현재 영상 참조 단건 로드 실패:', {
                    preferredReference,
                    error,
                });
                videoReferenceOptions = [];
                sourceInput.value = '';
                onVideoSourceChange();
                showToast('현재 영상화 이미지를 불러오지 못했습니다.', 'error');
            }
        }

        function applyVideoSecondaryMotionConfig(cfg) {
            const el = document.getElementById('video-generation-secondary-motion');
            if (!el) {
                console.error('[VIDEO_UI] 세컨더리 애니메이션 설정 컨트롤이 없습니다.');
                return;
            }
            // 기본 True: config 에 명시적 false 가 없으면 켜짐 유지
            el.checked = cfg?.video_secondary_motion !== false;
        }

        function onVideoSecondaryMotionChange() {
            const el = document.getElementById('video-generation-secondary-motion');
            if (!el) {
                console.error('[VIDEO_UI] 세컨더리 애니메이션 체크박스를 찾지 못했습니다.');
                return;
            }
            updateVideoGenerationSummary();
        }

        async function openVideoWorkspace(name) {
            const source = backupsData.find(item => item.name === name);
            if (!source) {
                console.error('[VIDEO_UI] 원본 백업을 찾지 못했습니다:', name);
                showToast('영상화할 백업 정보를 찾지 못했습니다.', 'error');
                return;
            }
            if (!source.has_raw) {
                console.error('[VIDEO_UI] 영상화에 쓸 깨끗한 원본 없는 백업:', name);
                showToast('이 백업에는 영상화에 쓸 대사 없는 원본이 없습니다.', 'error');
                return;
            }
            await openVideoWorkspaceForReference({kind: 'backup', name});
        }

        async function openAssetVideoWorkspace(data) {
            const reference = {
                kind: 'asset',
                character: String(data?.character || ''),
                outfit: String(data?.outfit || ''),
                expression: String(data?.expression || ''),
                filename: String(data?.filename || ''),
            };
            if (!reference.character || !reference.outfit || !reference.expression || !reference.filename) {
                console.error('[ASSET_VIDEO_UI] 영상화 에셋 참조 누락:', data);
                showToast('영상화할 에셋 정보를 찾지 못했습니다.', 'error');
                return;
            }
            await openVideoWorkspaceForReference(reference);
        }

        async function openVideoWorkspaceForReference(reference) {
            const modal = document.getElementById('video-modal');
            if (!modal) {
                console.error('[VIDEO_UI] 영상화 모달을 찾지 못했습니다.');
                return;
            }
            videoWorkspaceSourceRef = reference;
            videoInputFlowSessionId = createVideoInputFlowSessionId();
            const inputFlowStart = recordVideoInputFlowEvent(
                'session_start',
                {reference},
                {instruction: document.getElementById('video-generation-instruction')?.value || ''},
                videoInputFlowSessionId,
            );
            resetVideoInstructionDraftRequest();
            resetVideoInstructionRefineRequest();
            resetVideoInstructionDirectRequest();
            resetVideoDirectionEditState();
            ensureVideoInstructionRefineUndoListener();
            const badge = document.querySelector('#video-modal .video-source-badge');
            if (badge) badge.textContent = reference.kind === 'asset' ? '현재 에셋' : '현재 카드';
            const sourceEmpty = document.getElementById('video-generation-source-empty');
            if (sourceEmpty) {
                sourceEmpty.textContent = reference.kind === 'asset'
                    ? '현재 에셋 원본을 불러오는 중입니다.'
                    : '현재 카드의 `_raw` 원본을 불러오는 중입니다.';
            }
            if (currentConfig && typeof currentConfig.video_generation_defaults === 'object') {
                applyVideoGenerationDefaults(currentConfig);
            } else {
                setVideoVisualContextFromImage(true);
                setVideoInstructionDraftDefaults();
                selectVideoMode('i2v');
                updateVideoDuration();
                updateVideoWorkspaceMode();
            }

            // 참조 목록이나 설정 응답을 기다리지 않고 모달부터 표시한다.
            modal.classList.add('visible');

            const configSync = (async () => {
                try {
                    const cfg = await loadCurrentConfig();
                    applyVideoGenerationDefaults(cfg);
                    if (cfg?.comfy_task_allocations?.video_generation === 'video_engine') {
                        await videoEngineRefreshModels(false);
                        updateVideoEngineFixedStepControls();
                        updateVideoWorkspaceMode();
                    }
                } catch (error) {
                    console.error('[VIDEO_UI] 영상화 모달 기본 설정 동기화 실패:', error);
                    updateVideoUpscaleControls();
                }
            })();
            await Promise.all([
                configSync,
                loadVideoReferenceOptions(reference),
                inputFlowStart,
            ]);
        }

        function closeVideoModal() {
            const modal = document.getElementById('video-modal');
            if (modal) modal.classList.remove('visible');
            closeVideoReferencePicker();
            resetVideoInstructionDraftRequest();
            resetVideoInstructionRefineRequest();
            resetVideoInstructionDirectRequest();
            resetVideoDirectionEditState();
        }

        async function submitVideoGeneration() {
            const sourceKey = document.getElementById('video-generation-source')?.value || '';
            const sourceRef = getVideoReferenceByKey(sourceKey)?.reference || null;
            const mode = document.getElementById('video-generation-mode')?.value || 'i2v';
            const lastRef = getEffectiveLastVideoReference();
            const aspectRatio = document.getElementById('video-generation-aspect-ratio')?.value || 'auto';
            const qualityLevel = document.getElementById('video-generation-quality-level')?.value || 'medium';
            const duration = normalizedVideoDuration();
            const upscaleEnabled = document.getElementById('video-generation-upscale-enabled')?.checked !== false;
            const upscaleScale = parseInt(document.getElementById('video-generation-upscale-scale')?.value || '2', 10);
            const upscaleModel = getSelectedVideoOption('video-upscale-model', 'realesr-animevideov3');
            const outputFormat = getSelectedVideoOption('video-output-format', 'avif');
            const instruction = document.getElementById('video-generation-instruction')?.value.trim() || '';
            const visualContextSource = selectedVideoVisualContextSource();
            const promptGenerationMode = document.getElementById('video-generation-prompt-generation-mode')?.value || 'single';
            const translateInstructionToEnglish = document.getElementById('video-generation-translate-instruction-to-english')?.checked === true;
            const secondaryMotion = document.getElementById('video-generation-secondary-motion')?.checked !== false;
            const button = document.getElementById('video-generation-submit');
            if (!sourceRef) {
                console.error('[VIDEO_UI] 제출 실패: 원본 참조 없음', {sourceKey});
                showToast('원본 이미지 정보가 없습니다.', 'error');
                return;
            }
            if (!instruction) {
                showToast('영상에서 일어날 일을 입력하세요.', 'warning');
                document.getElementById('video-generation-instruction')?.focus();
                return;
            }
            if (mode === 'first_last' && !lastRef) {
                showToast('마지막 프레임을 선택하세요.', 'warning');
                return;
            }
            const originalText = button?.innerHTML || '🎬 큐에 등록';
            if (button) {
                button.disabled = true;
                button.innerHTML = '<span class="spinner"></span> 등록 중';
            }
            try {
                const data = await fetchJSON('/api/video/enqueue', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        mode,
                        workflow_variant: selectedVideoWorkflowVariant(),
                        source_ref: sourceRef,
                        last_ref: lastRef,
                        reference_refs: getSelectedVideoReferenceRefs(),
                        source_backup: sourceRef.kind === 'backup' ? sourceRef.name : '',
                        last_backup: lastRef?.kind === 'backup' ? lastRef.name : '',
                        loop: isVideoLoopEnabled(),
                        aspect_ratio: aspectRatio,
                        quality_level: qualityLevel,
                        duration,
                        upscale_enabled: upscaleEnabled,
                        upscale_scale: upscaleScale,
                        upscale_model: upscaleEnabled ? upscaleModel : '',
                        output_format: outputFormat,
                        encode_quality: normalizedVideoEncodeQuality(),
                        visual_context_source: visualContextSource,
                        prompt_generation_mode: promptGenerationMode,
                        refine_version: selectedVideoInstructionRefineVersion(),
                        translate_instruction_to_english: translateInstructionToEnglish,
                        secondary_motion: secondaryMotion,
                        instruction,
                        instruction_original: videoInstructionOriginalInput,
                        instruction_llm_trace: [...videoInstructionLlmTrace],
                        ...collectVideoSharpenParams(),
                    }),
                });
                if (!data.success) throw new Error(data.error || '영상화 큐 등록 실패');
                showToast(`영상화 프롬프트 작업을 큐에 등록했습니다. (${data.item_id})`, 'success');
                const instructionInput = document.getElementById('video-generation-instruction');
                if (instructionInput) {
                    instructionInput.value = '';
                    resetVideoInstructionHeight(instructionInput);
                } else {
                    console.error('[VIDEO_UI] 큐 등록 후 초기화할 영상 지시 입력란을 찾지 못했습니다.');
                }
                clearVideoInstructionProvenance();
                clearVideoInstructionRefineUndo();
                closeVideoModal();
            } catch (error) {
                console.error('[VIDEO_UI] 영상화 큐 등록 실패:', error);
                showToast('영상화 큐 등록 실패: ' + (error.message || error), 'error');
            } finally {
                if (button) {
                    button.disabled = false;
                    button.innerHTML = originalText;
                }
            }
        }

        function formatVideoReprocessBytes(value) {
            const bytes = Number(value || 0);
            if (!Number.isFinite(bytes) || bytes <= 0) return '용량 정보 없음';
            return bytes >= 1024 * 1024
                ? `${(bytes / (1024 * 1024)).toFixed(2)}MB`
                : `${Math.max(1, Math.round(bytes / 1024))}KB`;
        }

        function openBackupVideoReprocess(name) {
            const source = backupsData.find(item => item.name === name);
            if (!source) {
                console.error('[VIDEO_REPROCESS_UI] 원본 백업을 찾지 못했습니다:', name);
                showToast('후처리할 백업 정보를 찾지 못했습니다.', 'error');
                return;
            }
            if (!source.is_animated) {
                console.error('[VIDEO_REPROCESS_UI] animated 백업이 아닙니다:', source);
                showToast('영상 후처리는 animated 백업에서만 사용할 수 있습니다.', 'warning');
                return;
            }
            const info = source.conversion_info || {};
            openVideoReprocessModal({
                reference: {kind: 'backup', name: source.name},
                label: source.name,
                previewUrl: source.poster_url || source.image_url,
                animatedUrl: source.image_url,
                sizeBytes: source.file_size_bytes || 0,
                fps: info.video_fps || 24,
                width: info.video_width || 0,
                height: info.video_height || 0,
            });
        }

        function openAssetVideoReprocess(reference, media, posterUrl, animatedUrl) {
            if (!media?.is_animated) {
                console.error('[VIDEO_REPROCESS_UI] animated 에셋이 아닙니다:', {reference, media});
                showToast('영상 후처리는 animated 에셋에서만 사용할 수 있습니다.', 'warning');
                return;
            }
            const normalizedReference = {
                kind: 'asset',
                character: String(reference?.character || ''),
                outfit: String(reference?.outfit || ''),
                expression: String(reference?.expression || ''),
                filename: String(reference?.filename || ''),
            };
            if (!normalizedReference.character || !normalizedReference.outfit || !normalizedReference.expression || !normalizedReference.filename) {
                console.error('[VIDEO_REPROCESS_UI] 에셋 참조 필수값 누락:', reference);
                showToast('후처리할 에셋 정보를 찾지 못했습니다.', 'error');
                return;
            }
            openVideoReprocessModal({
                reference: normalizedReference,
                label: `${normalizedReference.outfit} / ${normalizedReference.expression} / ${normalizedReference.filename}`,
                previewUrl: posterUrl,
                animatedUrl,
                sizeBytes: media.file_size_bytes || 0,
                fps: media.video_fps || 24,
                width: media.video_width || 0,
                height: media.video_height || 0,
            });
        }

        function openVideoReprocessModal(source) {
            const modal = document.getElementById('video-reprocess-modal');
            if (!modal) {
                console.error('[VIDEO_REPROCESS_UI] 영상 후처리 모달을 찾지 못했습니다.');
                showToast('영상 후처리 화면을 열지 못했습니다.', 'error');
                return;
            }
            if (!source?.reference || !source?.animatedUrl) {
                console.error('[VIDEO_REPROCESS_UI] 후처리 원본 정보 누락:', source);
                showToast('후처리할 영상 정보가 없습니다.', 'error');
                return;
            }
            videoReprocessSource = source;
            const preview = document.getElementById('video-reprocess-source-preview');
            const empty = document.getElementById('video-reprocess-source-empty');
            if (preview) {
                preview.src = source.previewUrl || source.animatedUrl;
                preview.style.display = 'block';
            } else {
                console.error('[VIDEO_REPROCESS_UI] 원본 미리보기 요소가 없습니다.');
            }
            if (empty) empty.style.display = 'none';
            const name = document.getElementById('video-reprocess-source-name');
            if (name) name.textContent = source.label || '';
            const sourceFps = Number(source.fps || 0);
            const fpsInput = document.getElementById('video-reprocess-fps');
            if (fpsInput && Number.isInteger(sourceFps) && sourceFps >= 1 && sourceFps <= 60) {
                fpsInput.value = String(sourceFps);
            }
            const sizeStat = document.getElementById('video-reprocess-stat-size');
            const fpsStat = document.getElementById('video-reprocess-stat-fps');
            const dimStat = document.getElementById('video-reprocess-stat-dim');
            if (sizeStat) {
                sizeStat.textContent = Number(source.sizeBytes) > 0
                    ? formatVideoReprocessBytes(source.sizeBytes)
                    : '—';
            }
            if (fpsStat) {
                fpsStat.textContent = sourceFps > 0 ? String(sourceFps) : '—';
            }
            if (dimStat) {
                dimStat.textContent = Number(source.width) > 0 && Number(source.height) > 0
                    ? `${source.width}×${source.height}`
                    : '—';
            }
            const workerCountInput = document.getElementById('video-reprocess-worker-count');
            if (workerCountInput) {
                const savedWorkers = Number(currentConfig?.video_postprocess?.worker_count);
                workerCountInput.value = String(
                    Number.isInteger(savedWorkers) && savedWorkers >= 1 ? savedWorkers : 1
                );
            } else {
                console.error('[VIDEO_REPROCESS_UI] 동시 처리 수 입력 요소가 없습니다.');
            }
            updateVideoReprocessUpscaleControls();
            updateVideoReprocessSummary();
            modal.classList.add('visible');
        }

        function closeVideoReprocessModal() {
            const modal = document.getElementById('video-reprocess-modal');
            if (modal) modal.classList.remove('visible');
            videoReprocessSource = null;
        }

        async function saveVideoPostprocessWorkerCount() {
            const input = document.getElementById('video-reprocess-worker-count');
            const value = Number(input?.value || 0);
            if (!Number.isInteger(value) || value < 1) {
                console.error('[VIDEO_REPROCESS_UI] 동시 처리 수 입력 오류:', value);
                showToast('동시 처리 수는 1 이상의 정수로 입력하세요.', 'warning');
                const fallback = Number(currentConfig?.video_postprocess?.worker_count);
                if (input) {
                    input.value = String(
                        Number.isInteger(fallback) && fallback >= 1 ? fallback : 1
                    );
                }
                return;
            }
            try {
                const videoPostprocess = {
                    ...(currentConfig.video_postprocess || {}),
                    worker_count: value,
                };
                const result = await fetchJSON('/api/config', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({_origin: 'saveVideoPostprocessWorkerCount', video_postprocess: videoPostprocess}),
                });
                if (!result?.success || !result.config) {
                    throw new Error(result?.error || '설정 저장 응답이 올바르지 않습니다.');
                }
                currentConfig = result.config;
                currentConfigLoadPromise = Promise.resolve(currentConfig);
                showToast(`영상 후처리 동시 실행 수를 ${value}(으)로 저장했습니다.`, 'success');
            } catch (error) {
                console.error('[VIDEO_REPROCESS_UI] 동시 처리 수 저장 실패:', error);
                showToast('동시 처리 수 저장 실패: ' + (error.message || error), 'error');
            }
        }

        function updateVideoReprocessUpscaleControls() {
            const enabled = document.getElementById('video-reprocess-upscale-enabled')?.checked === true;
            const fields = document.getElementById('video-reprocess-upscale-fields');
            if (!fields) {
                console.error('[VIDEO_REPROCESS_UI] 업스케일 상세 설정 요소가 없습니다.');
                return;
            }
            fields.classList.toggle('disabled', !enabled);
            fields.setAttribute('aria-disabled', enabled ? 'false' : 'true');
            updateVideoReprocessSummary();
        }

        function updateVideoReprocessSummary() {
            const summary = document.getElementById('video-reprocess-summary-detail');
            if (!summary) return;
            const targetSize = Number(document.getElementById('video-reprocess-target-size')?.value || 0);
            const fps = Number(document.getElementById('video-reprocess-fps')?.value || 0);
            const enabled = document.getElementById('video-reprocess-upscale-enabled')?.checked === true;
            const model = document.getElementById('video-reprocess-upscale-model')?.value || 'realesr-animevideov3';
            const scale = document.getElementById('video-reprocess-upscale-scale')?.value || '2';
            const format = getSelectedVideoOption('video-reprocess-output-format', 'avif').toUpperCase();
            const upscale = enabled
                ? `${VIDEO_UPSCALE_LABELS[model] || model} ${scale}×`
                : '원본 크기';
            summary.textContent = `${targetSize || '-'}MB 이하 · ${fps || '-'}FPS · ${upscale} · ${format}`;
        }

        async function submitVideoReprocess() {
            const sourceRef = videoReprocessSource?.reference || null;
            const targetSizeMb = Number(document.getElementById('video-reprocess-target-size')?.value || 0);
            const fps = Number(document.getElementById('video-reprocess-fps')?.value || 0);
            const upscaleEnabled = document.getElementById('video-reprocess-upscale-enabled')?.checked === true;
            const upscaleScale = Number(document.getElementById('video-reprocess-upscale-scale')?.value || 2);
            const upscaleModel = document.getElementById('video-reprocess-upscale-model')?.value || 'realesr-animevideov3';
            const outputFormat = getSelectedVideoOption('video-reprocess-output-format', 'avif');
            const button = document.getElementById('video-reprocess-submit');
            if (!sourceRef) {
                console.error('[VIDEO_REPROCESS_UI] 제출 실패: 원본 참조 없음');
                showToast('후처리할 영상 정보가 없습니다.', 'error');
                return;
            }
            if (!Number.isFinite(targetSizeMb) || targetSizeMb < 0.1 || targetSizeMb > 2048) {
                console.error('[VIDEO_REPROCESS_UI] 목표 용량 입력 오류:', targetSizeMb);
                showToast('목표 용량은 0.1MB부터 2048MB까지 입력하세요.', 'warning');
                document.getElementById('video-reprocess-target-size')?.focus();
                return;
            }
            if (!Number.isInteger(fps) || fps < 1 || fps > 60) {
                console.error('[VIDEO_REPROCESS_UI] FPS 입력 오류:', fps);
                showToast('FPS는 1부터 60까지의 정수로 입력하세요.', 'warning');
                document.getElementById('video-reprocess-fps')?.focus();
                return;
            }
            const originalText = button?.innerHTML || '영상 후처리 큐에 등록';
            if (button) {
                button.disabled = true;
                button.innerHTML = '<span class="spinner"></span> 등록 중';
            }
            try {
                const data = await fetchJSON('/api/video/reprocess/enqueue', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        source_ref: sourceRef,
                        target_size_mb: targetSizeMb,
                        fps,
                        upscale_enabled: upscaleEnabled,
                        upscale_scale: upscaleScale,
                        upscale_model: upscaleEnabled ? upscaleModel : '',
                        output_format: outputFormat,
                    }),
                });
                if (!data.success) throw new Error(data.error || '영상 후처리 큐 등록 실패');
                showToast(`영상 후처리를 큐에 등록했습니다. (${data.item_id})`, 'success');
                closeVideoReprocessModal();
            } catch (error) {
                console.error('[VIDEO_REPROCESS_UI] 큐 등록 실패:', error);
                showToast('영상 후처리 큐 등록 실패: ' + (error.message || error), 'error');
            } finally {
                if (button) {
                    button.disabled = false;
                    button.innerHTML = originalText;
                }
            }
        }

        // ─── 백업 삭제 (이미지 + 메타데이터 3개 + 보조 파일 전부) ───
        async function deleteBackup(name, btn) {
            if (!confirm(`이 백업을 삭제하시겠습니까?\n\n${name}\n\n이미지와 메타데이터가 모두 삭제되며, 삭제된 이미지 파일은 복구되지 않습니다.`)) {
                return;
            }
            const originalText = btn.innerHTML;
            btn.disabled = true;
            btn.innerHTML = '<span class="spinner"></span>';
            try {
                const data = await fetchJSON('/api/backup_delete/' + encodeURIComponent(name), {
                    method: 'POST',
                });
                if (data.error) {
                    showToast('삭제 실패: ' + data.error, 'error');
                    btn.disabled = false;
                    btn.innerHTML = originalText;
                    return;
                }
                showToast('백업 삭제 완료', 'success');
                // 로컬 목록/통계 갱신 (전체 새로고침 없이)
                const idx = backupsData.findIndex(b => b.name === name);
                if (idx >= 0) backupsData.splice(idx, 1);
                paginationState.total = Math.max(0, paginationState.total - 1);
                renderBackups(backupsData);
                updateStatsBar();
                // 삭제로 인해 필터 카운트/옵션이 달라질 수 있으므로 드롭다운 갱신
                loadBackupFilters();
            } catch (e) {
                // fetchJSON이 HTTP 에러 본문까지 노출 (CLAUDE.md: 구체적 에러 메시지)
                showToast('삭제 실패: ' + (e.message || e), 'error');
                btn.disabled = false;
                btn.innerHTML = originalText;
            }
        }

        // ─── 재생성 ───
        // 재생성은 서버가 원본과 다른 시드를 뽑아 생성한다. 원본 백업은 그대로 둔다.
        async function regenerate(name, btn) {
            await doRegenerate(name, btn);
        }

        // 실제 재생성 (새 시드로 생성)
        async function doRegenerate(name, btn) {
            const originalText = btn.innerHTML;
            btn.disabled = true;
            btn.innerHTML = '<span class="spinner"></span>';
            showTopProgress();

            try {
                const data = await fetchJSON('/api/regenerate', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ name: name })
                });

                if (data.error) {
                    alert('재생성 실패: ' + data.error);
                    return;
                }

                showToast(data.message || '재생성 요청을 큐에 등록했습니다', 'info');
            } catch (e) {
                alert('재생성 실패: ' + e.message);
            } finally {
                btn.disabled = false;
                btn.innerHTML = originalText;
                hideTopProgress();
            }
        }

        // ─── 재전송 예약 ───
        async function loadRescheduleStatus() {
            try {
                const data = await fetchJSON('/api/reschedule');
                if (data.scheduled) {
                    console.log('Reschedule status:', data);
                }
            } catch (e) {
                console.error('Failed to load reschedule status:', e);
            }
        }

        async function reschedule(name, btn) {
            const originalText = btn.innerHTML;
            const isScheduled = btn.classList.contains('scheduled');
            
            btn.disabled = true;
            btn.innerHTML = '<span class="spinner"></span>';

            try {
                const data = await fetchJSON('/api/reschedule', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ name: name, action: 'toggle' })
                });

                if (data.error) {
                    alert('재전송 예약 실패: ' + data.error);
                    btn.disabled = false;
                    btn.innerHTML = originalText;
                    return;
                }

                // 버튼 상태는 WebSocket 이벤트로 업데이트됨
                if (data.scheduled) {
                    showToast('재전송 예약 완료', 'success');
                } else {
                    showToast('재전송 예약 취소', 'success');
                }

                // 전체 목록을 다시 로드하지 않고 버튼만 업데이트
                // WebSocket 이벤트가 도착하면 버튼 상태가 자동으로 업데이트됨
                btn.disabled = false;
            } catch (e) {
                alert('재전송 예약 실패: ' + e.message);
                btn.disabled = false;
                btn.innerHTML = originalText;
            }
        }

        // ─── 프롬프트 수정 모달 ───
        let currentModalBackupName = null;
        let llmEditInFlight = false;
        let currentModalIdentityEdit = null;
        let currentModalMultiChar = null;
        let currentModalFlowRunId = '';
        let llmEditModalState = null;
        let illustrationAutoFeedbackState = {
            jobId: '',
            sourceBackupName: '',
            job: null,
            pollTimer: null,
            terminalHandled: false,
        };
        let currentModalCameraSupported = false;
        let currentModalCameraAppliedControl = null;
        let currentModalCameraDirty = false;
        let currentModalCameraPrompt = '';

        let illustrationCameraDraft = null;
        let illustrationCameraDraftDirty = false;
        let illustrationCameraCanvasBound = false;
        let illustrationCameraDrag = null;

        function clampIllustrationCamera(value, min = -1, max = 1) {
            return Math.max(min, Math.min(max, Number(value) || 0));
        }

        function normalizeIllustrationCameraControlForUi(raw) {
            const source = raw && typeof raw === 'object' ? raw : {};
            let axes = source;
            if (!['pos_x', 'pos_y', 'pos_z', 'roll'].every(key => key in source)) {
                const direction = { keep: 0, front: 0, left: -0.5, right: 0.5, behind: 1 };
                const elevation = { keep: 0, overhead: 0.9, high: 0.5, eye: 0, low: -0.5, ground: -0.9 };
                const distance = { keep: 0, extreme_close: 0.85, close: 0.45, medium: 0, full: -0.45, wide: -0.85 };
                const roll = { keep: 0, level: 0, dutch: 0.6 };
                axes = {
                    pos_x: direction[String(source.direction || 'keep')] ?? 0,
                    pos_y: elevation[String(source.elevation || 'keep')] ?? 0,
                    pos_z: distance[String(source.distance || 'keep')] ?? 0,
                    roll: roll[String(source.roll || 'keep')] ?? 0,
                    weight: source.weight,
                };
            }
            const parsedWeight = Number(axes.weight);
            return {
                version: 3,
                pos_x: Math.round(clampIllustrationCamera(axes.pos_x) * 10000) / 10000,
                pos_y: Math.round(clampIllustrationCamera(axes.pos_y) * 10000) / 10000,
                pos_z: Math.round(clampIllustrationCamera(axes.pos_z) * 10000) / 10000,
                roll: Math.round(clampIllustrationCamera(axes.roll) * 10000) / 10000,
                weight: Number.isFinite(parsedWeight)
                    ? Math.max(1, Math.min(5, Math.round(parsedWeight * 10) / 10)) : 3,
            };
        }

        function defaultIllustrationCameraControl() {
            return normalizeIllustrationCameraControlForUi({
                pos_x: 0, pos_y: 0, pos_z: 0, roll: 0, weight: 3,
            });
        }

        function illustrationCameraSummary(control) {
            const value = normalizeIllustrationCameraControlForUi(control);
            const degrees = Math.round(Math.abs(value.pos_x) * 180);
            const direction = Math.abs(value.pos_x) >= 0.95
                ? '후면'
                : (value.pos_x > 0.05 ? `오른쪽 ${degrees}°`
                    : (value.pos_x < -0.05 ? `왼쪽 ${degrees}°` : '정면'));
            const elevation = value.pos_y > 0.7 ? '수직 탑뷰'
                : (value.pos_y > 0.2 ? '하이 앵글'
                    : (value.pos_y >= -0.2 ? '눈높이'
                        : (value.pos_y >= -0.7 ? '로우 앵글' : '바닥 시점')));
            const distance = value.pos_z > 0.7 ? '극근접'
                : (value.pos_z > 0.2 ? '근접'
                    : (value.pos_z >= -0.2 ? '중경'
                        : (value.pos_z >= -0.7 ? '전신' : '원경')));
            return `${direction} · ${elevation} · ${distance} · 롤 ${Math.round(value.roll * 45)}°`;
        }

        function compileIllustrationCameraPreview(control) {
            const value = normalizeIllustrationCameraControlForUi(control);
            const parts = [];
            const seen = new Set();
            const weighted = (tag, weight) => {
                if (!tag || seen.has(tag)) return;
                seen.add(tag);
                parts.push(`(${tag}:${Math.max(0.1, Math.min(10, weight)).toFixed(2)})`);
            };
            const distributeAxisBudget = (tags, budget) => {
                if (!tags.length || budget <= 0) return;
                const ranks = tags.map((_tag, index) => 1 / (index + 1));
                const rankTotal = ranks.reduce((sum, rank) => sum + rank, 0);
                tags.forEach((tag, index) => {
                    const amount = budget * ranks[index] / rankTotal;
                    if (amount >= 0.1) weighted(tag, amount);
                });
            };
            const axisBudget = 1 + (value.weight - 1) * 0.5;
            const angle = value.pos_x * Math.PI;
            const directions = [
                ['from front', Math.max(0, Math.cos(angle))],
                ['from behind', Math.max(0, -Math.cos(angle))],
                ['from right', Math.max(0, Math.sin(angle))],
                ['from left', Math.max(0, -Math.sin(angle))],
            ];
            const total = directions.reduce((sum, item) => sum + item[1], 0);
            const poleGate = clampIllustrationCamera((1 - Math.abs(value.pos_y)) / 0.1, 0, 1);
            for (const [tag, rawRatio] of directions) {
                const amount = total > 0 ? rawRatio / total * axisBudget * poleGate : 0;
                if (amount >= 0.2) weighted(tag, amount);
            }
            const elevationBudget = Math.abs(value.pos_y) * axisBudget;
            let elevationTags = [];
            if (value.pos_y > 0.7) elevationTags = ['directly above', 'from above', 'aerial view'];
            else if (value.pos_y > 0.2) elevationTags = ['high angle', 'from above'];
            else if (value.pos_y < -0.7) elevationTags = ['directly below'];
            else if (value.pos_y < -0.2) elevationTags = ['low angle', 'from below'];
            else if (Math.abs(value.pos_y) >= 0.05) elevationTags = ['eye-level'];
            if (elevationBudget >= 0.2) {
                distributeAxisBudget(elevationTags, elevationBudget);
            }
            const distanceTag = value.pos_z > 0.7 ? 'extreme close-up'
                : (value.pos_z > 0.2 ? 'close-up'
                    : (value.pos_z >= -0.2 ? 'medium shot'
                        : (value.pos_z >= -0.7 ? 'full body' : 'wide shot')));
            weighted(distanceTag, 1);
            if (Math.abs(value.roll) >= 0.15) {
                weighted('dutch angle', 1);
            }
            return parts.join(', ');
        }

        function updateIllustrationCameraOpenButton() {
            const button = document.getElementById('modal-camera-open-btn');
            if (!button) {
                console.error('[ILLUST_CAMERA] 구도 조정 버튼을 찾지 못했습니다.');
                return;
            }
            button.disabled = !currentModalCameraSupported;
            button.style.opacity = currentModalCameraSupported ? '1' : '0.45';
            button.style.cursor = currentModalCameraSupported ? 'pointer' : 'not-allowed';
            button.textContent = currentModalCameraDirty
                ? '🧭 구도 조정 · 재반영 필요'
                : (currentModalCameraAppliedControl ? '🧭 구도 조정 · 적용됨' : '🧭 구도 조정');
            button.title = currentModalCameraSupported
                ? (currentModalCameraDirty
                    ? '프롬프트 변경 후 구도 정리가 필요합니다.'
                    : '카메라를 움직여 Anima 구도를 조정합니다.')
                : 'V3 Comfy/Modal Anima 백업에서만 사용할 수 있습니다.';
        }

        function onIllustrationPromptManualEdit() {
            if (!currentModalCameraSupported || !currentModalCameraAppliedControl) return;
            currentModalCameraDirty = true;
            updateIllustrationCameraOpenButton();
        }

        function initializeIllustrationCameraPanel(promptData, format, promptProvider) {
            currentModalCameraSupported = format === 'v3' && promptProvider === 'comfy';
            currentModalCameraDirty = false;
            currentModalCameraAppliedControl = null;
            currentModalCameraPrompt = '';
            illustrationCameraDraft = null;
            const generationParams = promptData?.conversion_info?.generation_params;
            const storedControl = generationParams?.illustration_camera_control;
            if (currentModalCameraSupported && storedControl && typeof storedControl === 'object') {
                currentModalCameraAppliedControl = normalizeIllustrationCameraControlForUi(storedControl);
                currentModalCameraPrompt = String(
                    generationParams?.illustration_camera_prompt || ''
                ).trim();
            }
            updateIllustrationCameraOpenButton();
        }

        function setIllustrationCameraDraft(control) {
            illustrationCameraDraft = normalizeIllustrationCameraControlForUi(control);
            for (const key of ['pos_x', 'pos_y', 'pos_z', 'roll', 'weight']) {
                const input = document.getElementById(`illustration-camera-${key.replace('_', '-')}`);
                const output = document.getElementById(`illustration-camera-${key.replace('_', '-')}-value`);
                if (input) input.value = String(illustrationCameraDraft[key]);
                if (output) output.textContent = key === 'weight'
                    ? illustrationCameraDraft[key].toFixed(1)
                    : illustrationCameraDraft[key].toFixed(2);
            }
            drawIllustrationCamera();
            renderIllustrationCameraDraft();
        }

        function renderIllustrationCameraDraft(statusOverride = '') {
            if (!illustrationCameraDraft) return;
            const selection = document.getElementById('illustration-camera-selection');
            const preview = document.getElementById('illustration-camera-prompt-preview');
            const status = document.getElementById('illustration-camera-status');
            const prompt = compileIllustrationCameraPreview(illustrationCameraDraft);
            if (selection) {
                selection.textContent = `${illustrationCameraSummary(illustrationCameraDraft)} · 강도 ${illustrationCameraDraft.weight.toFixed(1)}`;
            }
            if (preview) {
                preview.style.display = prompt ? 'block' : 'none';
                preview.textContent = prompt ? `예상 Anima 태그: ${prompt}` : '';
            }
            if (status) {
                status.textContent = statusOverride || (
                    illustrationCameraDraftDirty
                        ? '카메라 위치 변경됨 · 적용하면 LLM이 기존 구도를 다시 정리합니다.'
                        : (currentModalCameraAppliedControl
                            ? '이 백업에 저장된 카메라 위치를 불러왔습니다.'
                            : '카메라를 드래그하거나 휠로 움직이세요.')
                );
            }
        }

        function openIllustrationCameraModal() {
            if (!currentModalBackupName || !currentModalCameraSupported) {
                showToast('구도 조정은 V3 Comfy/Modal Anima 백업에서만 사용할 수 있습니다.', 'warning');
                return;
            }
            illustrationCameraDraftDirty = false;
            setIllustrationCameraDraft(
                currentModalCameraAppliedControl || defaultIllustrationCameraControl()
            );
            const sourceImage = document.getElementById('illustration-camera-source-image');
            if (sourceImage) sourceImage.src = document.getElementById('modal-preview-img').src || '';
            const backupName = document.getElementById('illustration-camera-backup-name');
            if (backupName) backupName.textContent = currentModalBackupName;
            bindIllustrationCameraCanvas();
            document.getElementById('illustration-camera-modal').classList.add('visible');
            requestAnimationFrame(drawIllustrationCamera);
        }

        function closeIllustrationCameraModal(force = false) {
            if (llmEditInFlight && !force) return;
            const modal = document.getElementById('illustration-camera-modal');
            if (modal) modal.classList.remove('visible');
            illustrationCameraDrag = null;
        }

        function onIllustrationCameraAxisInput(key, rawValue) {
            if (!illustrationCameraDraft) illustrationCameraDraft = defaultIllustrationCameraControl();
            const max = key === 'weight' ? 5 : 1;
            const min = key === 'weight' ? 1 : -1;
            const digits = key === 'weight' ? 1 : 4;
            illustrationCameraDraft[key] = Number(clampIllustrationCamera(rawValue, min, max).toFixed(digits));
            illustrationCameraDraftDirty = true;
            setIllustrationCameraDraft(illustrationCameraDraft);
        }

        function setIllustrationCameraPreset(posX, posY, posZ, roll) {
            const weight = illustrationCameraDraft?.weight || 3;
            illustrationCameraDraftDirty = true;
            setIllustrationCameraDraft({ pos_x: posX, pos_y: posY, pos_z: posZ, roll, weight });
        }

        function randomizeIllustrationCamera() {
            const weight = illustrationCameraDraft?.weight || 3;
            illustrationCameraDraftDirty = true;
            setIllustrationCameraDraft({
                pos_x: Math.round((Math.random() * 2 - 1) * 100) / 100,
                pos_y: Math.round((Math.random() * 2 - 1) * 100) / 100,
                pos_z: Math.round((Math.random() * 2 - 1) * 100) / 100,
                roll: Math.round((Math.random() * 1.2 - 0.6) * 100) / 100,
                weight,
            });
        }

        function bindIllustrationCameraCanvas() {
            if (illustrationCameraCanvasBound) return;
            const canvas = document.getElementById('illustration-camera-canvas');
            if (!canvas) {
                console.error('[ILLUST_CAMERA] 카메라 캔버스를 찾지 못했습니다.');
                return;
            }
            illustrationCameraCanvasBound = true;
            const point = event => {
                const rect = canvas.getBoundingClientRect();
                return {
                    x: (event.clientX - rect.left) * canvas.width / rect.width,
                    y: (event.clientY - rect.top) * canvas.height / rect.height,
                };
            };
            canvas.addEventListener('pointerdown', event => {
                if (!illustrationCameraDraft) return;
                const start = point(event);
                illustrationCameraDrag = {
                    pointerId: event.pointerId,
                    x: start.x,
                    y: start.y,
                    posX: illustrationCameraDraft.pos_x,
                    posY: illustrationCameraDraft.pos_y,
                };
                canvas.setPointerCapture(event.pointerId);
                canvas.style.cursor = 'grabbing';
                event.preventDefault();
            });
            canvas.addEventListener('pointermove', event => {
                if (!illustrationCameraDrag || illustrationCameraDrag.pointerId !== event.pointerId) return;
                const current = point(event);
                let posX = illustrationCameraDrag.posX
                    + (current.x - illustrationCameraDrag.x) / (canvas.width / 2);
                while (posX > 1) posX -= 2;
                while (posX < -1) posX += 2;
                illustrationCameraDraft.pos_x = Number(posX.toFixed(4));
                illustrationCameraDraft.pos_y = Number(clampIllustrationCamera(
                    illustrationCameraDrag.posY - (current.y - illustrationCameraDrag.y) / (canvas.height / 2)
                ).toFixed(4));
                illustrationCameraDraftDirty = true;
                setIllustrationCameraDraft(illustrationCameraDraft);
                event.preventDefault();
            });
            const stop = event => {
                if (!illustrationCameraDrag || illustrationCameraDrag.pointerId !== event.pointerId) return;
                illustrationCameraDrag = null;
                canvas.style.cursor = 'crosshair';
            };
            canvas.addEventListener('pointerup', stop);
            canvas.addEventListener('pointercancel', stop);
            canvas.addEventListener('contextmenu', event => event.preventDefault());
            canvas.addEventListener('wheel', event => {
                if (!illustrationCameraDraft) return;
                const amount = event.deltaY * 0.001;
                if (event.shiftKey) {
                    illustrationCameraDraft.roll = Number(clampIllustrationCamera(
                        illustrationCameraDraft.roll - amount
                    ).toFixed(4));
                } else {
                    illustrationCameraDraft.pos_z = Number(clampIllustrationCamera(
                        illustrationCameraDraft.pos_z - amount
                    ).toFixed(4));
                }
                illustrationCameraDraftDirty = true;
                setIllustrationCameraDraft(illustrationCameraDraft);
                event.preventDefault();
            }, { passive: false });
            canvas.addEventListener('dblclick', event => {
                if (!illustrationCameraDraft) return;
                illustrationCameraDraft.pos_x = 0;
                illustrationCameraDraft.pos_y = 0;
                illustrationCameraDraftDirty = true;
                setIllustrationCameraDraft(illustrationCameraDraft);
                event.preventDefault();
            });
        }

        function drawIllustrationCamera() {
            const canvas = document.getElementById('illustration-camera-canvas');
            if (!canvas || !illustrationCameraDraft) return;
            const ctx = canvas.getContext('2d');
            if (!ctx) {
                console.error('[ILLUST_CAMERA] 카메라 캔버스 2D 컨텍스트를 만들지 못했습니다.');
                return;
            }
            const width = canvas.width;
            const height = canvas.height;
            const centerX = width / 2;
            const centerY = height / 2 + 5;
            const gradient = ctx.createLinearGradient(0, 0, 0, height);
            gradient.addColorStop(0, '#101820');
            gradient.addColorStop(0.58, '#18232d');
            gradient.addColorStop(1, '#27333e');
            ctx.fillStyle = gradient;
            ctx.fillRect(0, 0, width, height);

            // 같은 좌표로 다시 그릴 때 별이 흔들리지 않도록 고정된 심도를 사용한다.
            for (let index = 0; index < 46; index++) {
                const x = (index * 97 + 31) % width;
                const y = (index * 53 + 19) % height;
                const alpha = 0.10 + (index % 5) * 0.035;
                ctx.fillStyle = `rgba(187,224,238,${alpha.toFixed(3)})`;
                ctx.fillRect(x, y, index % 7 === 0 ? 2 : 1, index % 7 === 0 ? 2 : 1);
            }

            const radius = 1.72 - illustrationCameraDraft.pos_z * 0.68;
            const angle = illustrationCameraDraft.pos_x * Math.PI;
            const elevation = illustrationCameraDraft.pos_y * Math.PI / 2;
            const viewYaw = -0.56;
            const viewPitch = 0.47;
            const scale = 68;
            const projectOrbitPoint = (x, y, z) => {
                const yawCos = Math.cos(viewYaw);
                const yawSin = Math.sin(viewYaw);
                const horizontal = x * yawCos + z * yawSin;
                const yawDepth = -x * yawSin + z * yawCos;
                const pitchCos = Math.cos(viewPitch);
                const pitchSin = Math.sin(viewPitch);
                const vertical = y * pitchCos - yawDepth * pitchSin;
                const depth = y * pitchSin + yawDepth * pitchCos;
                return {
                    x: centerX + horizontal * scale,
                    y: centerY - vertical * scale,
                    depth,
                };
            };
            const orbitPoints = (steps, pointAt) => Array.from(
                { length: steps + 1 },
                (_unused, index) => pointAt(index / steps)
            );
            const strokeProjectedOrbit = (points, backColor, frontColor, lineWidth, dash = []) => {
                ctx.lineWidth = lineWidth;
                ctx.setLineDash(dash);
                for (let index = 1; index < points.length; index++) {
                    const start = points[index - 1];
                    const end = points[index];
                    ctx.strokeStyle = (start.depth + end.depth) / 2 >= 0
                        ? frontColor : backColor;
                    ctx.beginPath();
                    ctx.moveTo(start.x, start.y);
                    ctx.lineTo(end.x, end.y);
                    ctx.stroke();
                }
                ctx.setLineDash([]);
            };

            const equatorOrbit = orbitPoints(120, ratio => {
                const orbitAngle = ratio * Math.PI * 2;
                return projectOrbitPoint(
                    radius * Math.sin(orbitAngle),
                    0,
                    radius * Math.cos(orbitAngle)
                );
            });
            strokeProjectedOrbit(
                equatorOrbit,
                'rgba(80,187,209,.10)',
                'rgba(100,211,229,.34)',
                1.25,
                [4, 7]
            );

            const meridianOrbit = orbitPoints(120, ratio => {
                const orbitAngle = ratio * Math.PI * 2 - Math.PI;
                const horizontal = radius * Math.cos(orbitAngle);
                return projectOrbitPoint(
                    horizontal * Math.sin(angle),
                    radius * Math.sin(orbitAngle),
                    horizontal * Math.cos(angle)
                );
            });
            strokeProjectedOrbit(
                meridianOrbit,
                'rgba(91,181,210,.15)',
                'rgba(118,216,236,.52)',
                1.75,
                [3, 7]
            );

            const latitudeRadius = radius * Math.cos(elevation);
            const latitudeHeight = radius * Math.sin(elevation);
            const activeOrbit = orbitPoints(144, ratio => {
                const orbitAngle = ratio * Math.PI * 2;
                return projectOrbitPoint(
                    latitudeRadius * Math.sin(orbitAngle),
                    latitudeHeight,
                    latitudeRadius * Math.cos(orbitAngle)
                );
            });
            strokeProjectedOrbit(
                activeOrbit,
                'rgba(255,140,73,.18)',
                'rgba(255,166,89,.78)',
                2.35
            );

            // 정면 기준점부터 현재 카메라까지 진행한 공전 구간을 밝게 표시한다.
            if (Math.abs(angle) > 0.008) {
                const activeTrail = orbitPoints(48, ratio => {
                    const orbitAngle = angle * ratio;
                    return projectOrbitPoint(
                        latitudeRadius * Math.sin(orbitAngle),
                        latitudeHeight,
                        latitudeRadius * Math.cos(orbitAngle)
                    );
                });
                strokeProjectedOrbit(
                    activeTrail,
                    'rgba(255,184,102,.38)',
                    'rgba(255,205,117,.96)',
                    3.5
                );
            }

            const axisPoints = [
                ['F', projectOrbitPoint(0, 0, radius)],
                ['B', projectOrbitPoint(0, 0, -radius)],
                ['L', projectOrbitPoint(-radius, 0, 0)],
                ['R', projectOrbitPoint(radius, 0, 0)],
            ];
            ctx.font = '700 14px ui-monospace, Menlo, monospace';
            ctx.textAlign = 'center';
            for (const [label, point] of axisPoints) {
                ctx.fillStyle = point.depth >= 0 ? '#7fdceb' : 'rgba(127,220,235,.42)';
                ctx.beginPath();
                ctx.arc(point.x, point.y, 4.5, 0, Math.PI * 2);
                ctx.fill();
                ctx.fillStyle = point.depth >= 0 ? '#eef8ff' : 'rgba(238,248,255,.5)';
                ctx.fillText(label, point.x, point.y - 10);
            }

            const targetPoint = projectOrbitPoint(0, 0, 0);
            const cameraPoint = projectOrbitPoint(
                latitudeRadius * Math.sin(angle),
                latitudeHeight,
                latitudeRadius * Math.cos(angle)
            );
            ctx.strokeStyle = 'rgba(255,216,126,.72)';
            ctx.lineWidth = 1.5;
            ctx.setLineDash([5, 6]);
            ctx.beginPath();
            ctx.moveTo(targetPoint.x, targetPoint.y);
            ctx.lineTo(cameraPoint.x, cameraPoint.y);
            ctx.stroke();
            ctx.setLineDash([]);

            const targetGlow = ctx.createRadialGradient(
                targetPoint.x - 6,
                targetPoint.y - 7,
                2,
                targetPoint.x,
                targetPoint.y,
                25
            );
            targetGlow.addColorStop(0, '#e5ffff');
            targetGlow.addColorStop(0.42, '#58aeb9');
            targetGlow.addColorStop(1, '#24535e');
            ctx.fillStyle = targetGlow;
            ctx.beginPath();
            ctx.arc(targetPoint.x, targetPoint.y, 23, 0, Math.PI * 2);
            ctx.fill();
            ctx.strokeStyle = 'rgba(180,244,250,.38)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.ellipse(targetPoint.x, targetPoint.y, 23, 8, -0.18, 0, Math.PI * 2);
            ctx.stroke();
            ctx.fillStyle = 'rgba(229,249,251,.72)';
            ctx.font = '600 10px ui-monospace, Menlo, monospace';
            ctx.fillText('SUBJECT', targetPoint.x, targetPoint.y + 40);

            ctx.save();
            ctx.translate(cameraPoint.x, cameraPoint.y);
            ctx.rotate(
                Math.atan2(targetPoint.y - cameraPoint.y, targetPoint.x - cameraPoint.x)
                + illustrationCameraDraft.roll * Math.PI / 4
            );
            ctx.shadowColor = 'rgba(255,153,78,.72)';
            ctx.shadowBlur = 12;
            ctx.fillStyle = '#74cddd';
            ctx.fillRect(-29, -5, 11, 10);
            ctx.fillRect(18, -5, 11, 10);
            ctx.fillStyle = '#ff9857';
            ctx.fillRect(-17, -10, 34, 20);
            ctx.shadowBlur = 0;
            ctx.fillStyle = '#111820';
            ctx.beginPath();
            ctx.arc(8, 0, 6.5, 0, Math.PI * 2);
            ctx.fill();
            ctx.strokeStyle = '#ffd29a';
            ctx.lineWidth = 1.5;
            ctx.strokeRect(-17, -10, 34, 20);
            ctx.restore();

            ctx.fillStyle = '#ffb375';
            ctx.font = '700 10px ui-monospace, Menlo, monospace';
            ctx.fillText('ORBIT CAM', cameraPoint.x, cameraPoint.y - 18);

            ctx.textAlign = 'left';
            ctx.strokeStyle = '#ffa659';
            ctx.lineWidth = 2.5;
            ctx.beginPath();
            ctx.moveTo(16, height - 18);
            ctx.lineTo(48, height - 18);
            ctx.stroke();
            ctx.fillStyle = 'rgba(232,242,247,.72)';
            ctx.font = '600 10px ui-monospace, Menlo, monospace';
            ctx.fillText('AZIMUTH ORBIT', 56, height - 14);
            ctx.strokeStyle = '#76d8ec';
            ctx.beginPath();
            ctx.moveTo(158, height - 18);
            ctx.lineTo(190, height - 18);
            ctx.stroke();
            ctx.fillText('ELEVATION ORBIT', 198, height - 14);

            const status = document.getElementById('illustration-camera-canvas-status');
            if (status) status.textContent = `${illustrationCameraSummary(illustrationCameraDraft)}\nX ${illustrationCameraDraft.pos_x.toFixed(2)} · Y ${illustrationCameraDraft.pos_y.toFixed(2)} · Z ${illustrationCameraDraft.pos_z.toFixed(2)}`;
        }

        async function applyIllustrationCameraAdjustment() {
            if (!currentModalBackupName || !currentModalCameraSupported || llmEditInFlight) return;
            if (!illustrationCameraDraft) {
                console.error('[ILLUST_CAMERA] 적용할 카메라 좌표가 없습니다.');
                alert('적용할 카메라 위치가 없습니다.');
                return;
            }
            const positive = document.getElementById('modal-positive').value;
            const negative = document.getElementById('modal-negative').value;
            const button = document.getElementById('illustration-camera-apply-btn');
            const originalText = button.textContent;
            llmEditInFlight = true;
            button.disabled = true;
            button.textContent = 'LLM 구도 정리 중...';
            renderIllustrationCameraDraft('기존 카메라 구도를 의미적으로 정리하는 중...');

            try {
                const data = await fetchJSON('/api/llm_edit_prompt', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        name: currentModalBackupName,
                        positive,
                        negative,
                        camera_control: illustrationCameraDraft,
                        illustration_multi_char: currentModalMultiChar,
                        illustration_flow_run_id: currentModalFlowRunId,
                    }),
                });
                if (data.error) throw new Error(data.error);
                if (data.parse_failed) {
                    throw new Error('LLM 응답을 파싱하지 못해 구도를 반영하지 않았습니다.');
                }
                if (!data.positive || !data.camera_control) {
                    throw new Error('서버가 구도 조정 결과를 완전하게 반환하지 않았습니다.');
                }
                document.getElementById('modal-positive').value = data.positive;
                if (typeof data.negative === 'string') {
                    document.getElementById('modal-negative').value = data.negative;
                }
                currentModalCameraAppliedControl = normalizeIllustrationCameraControlForUi(data.camera_control);
                currentModalFlowRunId = data.illustration_flow_run_id || '';
                currentModalCameraPrompt = String(data.camera_prompt || '').trim();
                currentModalCameraDirty = false;
                illustrationCameraDraftDirty = false;
                if (data.plan) {
                    document.getElementById('modal-llm-plan-text').textContent = data.plan;
                    document.getElementById('modal-llm-plan').style.display = 'block';
                }
                updateIllustrationCameraOpenButton();
                closeIllustrationCameraModal(true);
                showToast('Anima 구도 조정을 프롬프트에 반영했습니다.', 'success');
            } catch (error) {
                console.error('[ILLUST_CAMERA] LLM 구도 조정 실패:', error);
                renderIllustrationCameraDraft(`구도 조정 실패: ${error.message}`);
                alert('Anima 구도 조정 실패: ' + error.message);
            } finally {
                llmEditInFlight = false;
                button.disabled = false;
                button.textContent = originalText;
            }
        }

        // 챈섭은 키워드가 없는 평탄 프롬프트이므로 백업 provider 메타데이터로 감지한다.
        function detectPromptFormat(positive, provider = '') {
            if (provider === 'chansub') return 'chansub';
            if (!positive) return '';
            // V3: ANIMA_CONTENT 등 핵심 헤더 존재
            if (/\[ANIMA_CONTENT\]\n/.test(positive) && /\[SDXL\]\n/.test(positive)) return 'v3';
            // V1: ILXL + UPSCALE 헤더 존재 (V3 헤더는 없음)
            if (/\[ILXL\]\n/.test(positive) && /\[UPSCALE\]\n/.test(positive)) return 'v1';
            return '';
        }

        function openPromptModal(btn) {
            const card = btn.closest('.backup-card');
            const name = card.dataset.name;
            const imageUrl = btn.dataset.imageUrl;
            // Look up prompt from Map instead of data-attributes (avoids truncation)
            const promptData = promptDataMap.get(name) || {};
            // 강화 프롬프트가 있으면 강화 버전 사용, 없으면 원본
            const positive = promptData.enhanced_positive || promptData.positive || '';
            const negative = promptData.negative || '';

            currentModalBackupName = name;
            currentModalIdentityEdit = null;
            currentModalMultiChar = null;
            currentModalFlowRunId = '';
            llmEditModalState = null;
            document.getElementById('modal-backup-name').textContent = name;
            const previewImg = document.getElementById('modal-preview-img');
            const preview = document.getElementById('modal-mask-preview');
            const info = promptData.conversion_info || {};
            const faces = info.face_positions || [];
            const maskUrl = info.mask_url || '';
            preview.hidden = false;
            preview.textContent = faces.length || maskUrl ? 'FACE · 최종 마스크 불러오는 중…' : '저장된 FACE·최종 마스크 정보가 없습니다.';
            previewImg.onload = () => {
                if (!faces.length && !maskUrl) return;
                renderIllustrationMaskPreview(null, previewImg, maskUrl, preview, faces);
                if (maskUrl) {
                    const legend = preview.querySelector('.prompt-mask-legend:last-child');
                    const colors = ['#ef4444', '#22c55e', '#3b82f6'];
                    (info.illustration_multi_char?.layout?.regions || []).forEach((region, index) => {
                        const line = document.createElement('span');
                        const channel = region.channel || 'RGB'[index];
                        line.textContent = `${channel} · ${region.name}`;
                        line.style.color = colors['RGB'.indexOf(channel)];
                        legend.append(line);
                    });
                }
            };
            previewImg.onerror = () => {
                console.error('[BACKUP_PREVIEW] 이미지 표시 실패:', {name, url: previewImg.src});
                preview.textContent = '미리보기 이미지를 불러오지 못했습니다.';
            };
            previewImg.src = promptData.raw_url || imageUrl;
            document.getElementById('modal-positive').value = positive;
            document.getElementById('modal-negative').value = negative;
            document.getElementById('modal-submit-btn').disabled = false;
            document.getElementById('modal-submit-text').textContent = '프롬프트 수정 후 재생성';

            // 편하게 수정 버튼: V3(빌드본) 또는 V1(ILXL/UPSCALE)일 때 활성화
            const llmBtn = document.getElementById('modal-llm-edit-btn');
            const provider = (
                (promptData.conversion_info || {}).prompt_provider
                || (promptData.conversion_info || {}).provider
                || 'comfy'
            );
            const fmt = detectPromptFormat(positive, provider);
            const supported = !!fmt;
            llmBtn.disabled = !supported;
            llmBtn.title = supported ? '' : '삽화 V3, V1 또는 챈섭 Comfy 프롬프트에서만 동작합니다.';
            initializeIllustrationCameraPanel(promptData, fmt, provider);
            // 계획 영역 초기화
            document.getElementById('modal-llm-plan').style.display = 'none';
            document.getElementById('modal-llm-plan-text').textContent = '';
            document.getElementById('modal-llm-edit-text').textContent = '✨ 편하게 수정';

            document.getElementById('prompt-modal').classList.add('visible');
        }

        function closePromptModal() {
            document.getElementById('prompt-modal').classList.remove('visible');
            document.getElementById('illustration-camera-modal')?.classList.remove('visible');
            // 방향 입력 모달도 함께 닫기
            closeLlmEditModal();
            currentModalBackupName = null;
            llmEditInFlight = false;
            currentModalIdentityEdit = null;
            currentModalMultiChar = null;
            currentModalFlowRunId = '';
            llmEditModalState = null;
            currentModalCameraSupported = false;
            currentModalCameraAppliedControl = null;
            currentModalCameraDirty = false;
            currentModalCameraPrompt = '';
            illustrationCameraDraft = null;
            illustrationCameraDraftDirty = false;
            illustrationCameraDrag = null;
        }

        function updateLlmEditCharacterSelection() {
            const state = llmEditModalState;
            if (!state || !state.identityEnabled) return true;
            const selects = Array.from(document.querySelectorAll('.llm-edit-character-select'));
            const names = selects.map(select => select.value.trim());
            state.slotNames = names;
            state.visualProfileIds = {};
            selects.forEach((select, index) => {
                const character = state.characters.find(item => item.name === select.value);
                const profileSelect = document.getElementById(`llm-edit-profile-select-${index}`);
                const profile = (character?.profiles || []).find(
                    item => item.id === profileSelect?.value
                ) || null;
                if (character && profile) {
                    state.visualProfileIds[character.name] = profile.id;
                }
                const img = document.getElementById(`llm-edit-character-img-${index}`);
                if (img) {
                    const profileFilename = String(profile?.rep_image || '').trim();
                    const profileUrl = profileFilename
                        ? `/api/bot_mode/image/${encodeURIComponent(state.botName)}/${encodeURIComponent(character?.name || '')}/${encodeURIComponent(profileFilename)}`
                        : '';
                    const previewUrl = profileUrl || character?.rep_url || '';
                    img.onerror = () => {
                        console.error('[EASY_EDIT] 프로필 대표 이미지 로드 실패:', {
                            character: character?.name || '',
                            profile: profile?.id || '',
                            url: previewUrl,
                        });
                        img.style.display = 'none';
                    };
                    img.src = previewUrl;
                    img.alt = character && profile
                        ? `${character.name} · ${profile.label || profile.id}`
                        : '';
                    img.style.display = previewUrl ? 'block' : 'none';
                }
            });
            let error = '';
            if (names.some(name => !name)) error = '각 슬롯의 캐릭터를 선택해주세요.';
            else if (new Set(names.map(name => name.toLowerCase())).size !== names.length) {
                error = '같은 캐릭터를 여러 슬롯에 선택할 수 없습니다.';
            } else if (names.some(name => !state.visualProfileIds[name])) {
                error = '각 슬롯의 프로필 카드를 선택해주세요.';
            }
            const errorEl = document.getElementById('llm-edit-character-error');
            if (errorEl) {
                errorEl.textContent = error;
                errorEl.style.display = error ? 'block' : 'none';
            }
            const runBtn = document.getElementById('llm-edit-run-btn');
            if (runBtn && !llmEditInFlight) runBtn.disabled = !!error;
            return !error;
        }

        function fillLlmEditProfileSelect(index, preferredProfileId = '') {
            const state = llmEditModalState;
            const characterSelect = document.querySelector(
                `.llm-edit-character-select[data-slot-index="${index}"]`
            );
            const profileSelect = document.getElementById(`llm-edit-profile-select-${index}`);
            if (!state || !characterSelect || !profileSelect) {
                console.error('[EASY_EDIT] 프로필 선택 요소 없음:', index);
                return;
            }
            const character = state.characters.find(
                item => item.name === characterSelect.value
            ) || null;
            const profiles = Array.isArray(character?.profiles) ? character.profiles : [];
            profileSelect.innerHTML = '';
            profiles.forEach(profile => {
                const option = document.createElement('option');
                option.value = String(profile.id || '');
                option.textContent = `${profile.label || profile.id}${profile.is_default ? ' · 기본' : ''}`;
                profileSelect.appendChild(option);
            });
            const preferred = profiles.find(profile => profile.id === preferredProfileId);
            const fallback = profiles.find(profile => profile.is_default) || profiles[0] || null;
            profileSelect.value = String((preferred || fallback)?.id || '');
            profileSelect.disabled = profiles.length <= 1;
            if (!profiles.length) {
                console.error('[EASY_EDIT] 선택 가능한 프로필 카드 없음:', character?.name || '');
            }
        }

        function renderLlmEditCharacterSlots(currentNames, currentVisualProfileIds = {}) {
            const state = llmEditModalState;
            const host = document.getElementById('llm-edit-character-slots');
            host.innerHTML = '';
            currentNames.forEach((currentName, index) => {
                const card = document.createElement('div');
                card.style.cssText = 'display:grid;grid-template-columns:52px minmax(0,1fr);gap:9px;align-items:center;padding:9px;border:1px solid var(--border);border-radius:7px;background:var(--surface1);';
                const img = document.createElement('img');
                img.id = `llm-edit-character-img-${index}`;
                img.alt = '';
                img.style.cssText = 'display:none;width:52px;height:52px;object-fit:cover;border-radius:6px;background:var(--surface2);';
                const control = document.createElement('div');
                const label = document.createElement('div');
                label.textContent = currentNames.length === 1 ? '캐릭터' : `슬롯 ${index + 1}`;
                label.style.cssText = 'margin-bottom:4px;font-size:0.7rem;color:var(--text-secondary);font-weight:600;';
                const select = document.createElement('select');
                select.className = 'llm-edit-character-select';
                select.dataset.slotIndex = String(index);
                select.style.cssText = 'width:100%;padding:6px 8px;border:1px solid var(--border);border-radius:5px;background:var(--surface2);color:var(--text);font-size:0.8rem;';
                const placeholder = document.createElement('option');
                placeholder.value = '';
                placeholder.textContent = '캐릭터 선택';
                select.appendChild(placeholder);
                state.characters.forEach(character => {
                    const option = document.createElement('option');
                    option.value = character.name;
                    option.textContent = character.name;
                    if (character.name.toLowerCase() === String(currentName).toLowerCase()) option.selected = true;
                    select.appendChild(option);
                });
                select.addEventListener('change', () => {
                    fillLlmEditProfileSelect(index);
                    updateLlmEditCharacterSelection();
                });
                const profileLabel = document.createElement('div');
                profileLabel.textContent = '프로필 카드';
                profileLabel.style.cssText = 'margin:6px 0 4px;font-size:0.7rem;color:var(--text-secondary);font-weight:600;';
                const profileSelect = document.createElement('select');
                profileSelect.id = `llm-edit-profile-select-${index}`;
                profileSelect.className = 'llm-edit-profile-select';
                profileSelect.style.cssText = select.style.cssText;
                profileSelect.addEventListener('change', updateLlmEditCharacterSelection);
                control.appendChild(label);
                control.appendChild(select);
                control.appendChild(profileLabel);
                control.appendChild(profileSelect);
                card.appendChild(img);
                card.appendChild(control);
                host.appendChild(card);
                const savedProfileEntry = Object.entries(currentVisualProfileIds || {}).find(
                    ([name]) => String(name).toLowerCase() === String(currentName).toLowerCase()
                );
                fillLlmEditProfileSelect(index, String(savedProfileEntry?.[1] || ''));
            });
            updateLlmEditCharacterSelection();
        }

        async function openLlmEditModal() {
            if (!currentModalBackupName) return;
            const openingBackupName = currentModalBackupName;
            const positive = document.getElementById('modal-positive').value || '';
            const promptData = promptDataMap.get(currentModalBackupName) || {};
            const provider = ((promptData.conversion_info || {}).provider || 'comfy');
            const fmt = detectPromptFormat(positive, provider);
            if (!fmt) {
                alert('삽화 V3, V1 또는 챈섭 Comfy 프롬프트에서만 동작합니다.');
                return;
            }
            const openingState = {
                format: fmt,
                provider,
                identityEnabled: false,
                botName: '',
                characters: [],
                slotNames: [],
                visualProfileIds: {},
            };
            llmEditModalState = openingState;
            const responseLanguage = document.getElementById('llm-edit-response-language');
            responseLanguage.disabled = true;
            const maskToggle = document.getElementById('llm-edit-allow-mask-edit');
            let hasMask = false;
            try {
                const maskBlock = positive.match(/^[ \t]*\[MULTI_CHAR\][ \t]*\r?\n([\s\S]*?)(?=^[ \t]*\[[A-Z0-9_]+\][ \t]*\r?$|(?![\s\S]))/m);
                hasMask = fmt === 'v3' && provider === 'comfy'
                    && !!maskBlock && JSON.parse(maskBlock[1]).enable === true;
            } catch (error) {
                console.error('[EASY_EDIT] 마스크 제어 블록 확인 실패:', error);
            }
            maskToggle.disabled = !hasMask;
            maskToggle.checked = hasMask && localStorage.getItem('llmEditAllowMaskEdit') !== 'false';
            // 감지된 형식 배지 표시
            const badge = document.getElementById('llm-edit-format-badge');
            if (badge) {
                const label = fmt === 'chansub'
                    ? '챈섭 (NAI 요청 · Comfy 프롬프트)'
                    : (fmt === 'v1' ? 'V1 (ILXL/UPSCALE)' : 'V3 (삽화 빌드본)');
                badge.textContent = '감지된 형식: ' + label;
            }
            document.getElementById('llm-edit-preview-img').src = document.getElementById('modal-preview-img').src || '';
            document.getElementById('llm-edit-backup-name').textContent = currentModalBackupName;
            const botBadge = document.getElementById('llm-edit-bot-badge');
            botBadge.style.display = 'none';
            botBadge.textContent = '';
            const charSection = document.getElementById('llm-edit-character-section');
            const charSlots = document.getElementById('llm-edit-character-slots');
            const charError = document.getElementById('llm-edit-character-error');
            const scopeNote = document.getElementById('llm-edit-scope-note');
            charSection.style.display = 'none';
            charSlots.innerHTML = '';
            charError.style.display = 'none';
            charError.textContent = '';
            const input = document.getElementById('llm-edit-direction-input');
            input.value = '';
            document.getElementById('llm-edit-run-text').textContent = '수정 적용';
            document.getElementById('llm-edit-run-btn').disabled = false;
            document.getElementById('llm-edit-direction-modal').classList.add('visible');
            if (
                illustrationAutoFeedbackState.jobId
                && illustrationAutoFeedbackState.sourceBackupName === openingBackupName
                && !['completed', 'failed', 'cancelled'].includes(
                    String(illustrationAutoFeedbackState.job?.status || '')
                )
            ) {
                renderIllustrationAutoFeedbackJob(illustrationAutoFeedbackState.job);
            } else {
                resetIllustrationAutoFeedbackUi();
            }

            try {
                const result = await fetchJSON('/api/llm_edit_prompt_template');
                if (!result.success) throw new Error(result.error || '답변 언어를 불러오지 못했습니다.');
                if (llmEditModalState !== openingState) return;
                responseLanguage.value = result.data.response_language || 'en';
                responseLanguage.dataset.savedValue = responseLanguage.value;
                responseLanguage.disabled = false;
            } catch (error) {
                console.error('[EASY_EDIT] 답변 언어 로드 실패:', error);
                showToast('답변 언어 로드 실패: ' + error.message, 'error');
                return;
            }

            if (fmt === 'v3') {
                charSection.style.display = 'block';
                charSlots.innerHTML = '<div style="grid-column:1/-1;color:var(--text-secondary);font-size:0.76rem;">백업의 캐릭터 교체 가능 여부를 확인하는 중...</div>';
                scopeNote.textContent = '백업 원본과 마스크 스냅샷을 서버에서 검증하고 있습니다.';
                try {
                    const capability = await fetchJSON(
                        '/api/llm_edit_prompt/capability?name=' + encodeURIComponent(openingBackupName)
                    );
                    if (capability.error) throw new Error(capability.error);
                    if (currentModalBackupName !== openingBackupName || llmEditModalState !== openingState) return;

                    if (!capability.enabled) {
                        openingState.identityEnabled = false;
                        charSection.style.display = 'none';
                        charSlots.innerHTML = '';
                        scopeNote.textContent = capability.reason
                            || '이 백업은 캐릭터 교체를 지원하지 않습니다. 장면·표정·복장 수정만 사용할 수 있습니다.';
                        setTimeout(() => input.focus(), 50);
                        return;
                    }

                    const backupNames = Array.isArray(capability.character_names)
                        ? capability.character_names.map(v => String(v || '').trim()).filter(Boolean)
                        : [];
                    const carriedNames = Array.isArray(currentModalIdentityEdit?.character_names)
                        ? currentModalIdentityEdit.character_names.map(v => String(v || '').trim()).filter(Boolean)
                        : [];
                    const currentNames = carriedNames.length === backupNames.length
                        ? carriedNames
                        : backupNames;
                    if (!currentNames.length) {
                        throw new Error('백업에 교체할 캐릭터 슬롯이 없습니다.');
                    }

                    charSlots.innerHTML = '<div style="grid-column:1/-1;color:var(--text-secondary);font-size:0.76rem;">활성 봇의 캐릭터 목록을 불러오는 중...</div>';
                    const data = await fetchJSON('/api/restore_manual/characters');
                    if (data.error) throw new Error(data.error);
                    if (!Array.isArray(data.characters) || data.characters.length === 0) {
                        throw new Error('활성 봇에 선택할 캐릭터가 없습니다.');
                    }
                    if (currentModalBackupName !== openingBackupName || llmEditModalState !== openingState) return;
                    openingState.identityEnabled = true;
                    openingState.botName = data.bot_name || '';
                    openingState.characters = data.characters;
                    openingState.slotNames = currentNames;
                    const carriedProfileIds = currentModalIdentityEdit?.visual_profile_ids;
                    openingState.visualProfileIds = (
                        carriedNames.length === currentNames.length
                        && carriedProfileIds
                        && typeof carriedProfileIds === 'object'
                    ) ? { ...carriedProfileIds } : (
                        capability.visual_profile_ids
                        && typeof capability.visual_profile_ids === 'object'
                    ) ? { ...capability.visual_profile_ids } : {};
                    botBadge.textContent = `활성 봇: ${openingState.botName}`;
                    botBadge.style.display = 'block';
                    scopeNote.textContent = currentNames.length > 1
                        ? '슬롯별 캐릭터·프로필·FACE·LoRA를 수정합니다. 영역 좌표 수정은 마스크 편집 토글로 선택합니다.'
                        : '장면을 자연어로 수정하고, 선택한 프로필 카드의 고정 외형·LoRA·Face LoRA·FACE-ID·얼굴 태그를 함께 적용합니다.';
                    renderLlmEditCharacterSlots(
                        currentNames,
                        openingState.visualProfileIds
                    );
                } catch (e) {
                    if (currentModalBackupName !== openingBackupName || llmEditModalState !== openingState) return;
                    console.error('[EASY_EDIT] 캐릭터 교체 가능 여부/목록 확인 실패:', e);
                    openingState.identityEnabled = false;
                    charSection.style.display = 'none';
                    charSlots.innerHTML = '';
                    scopeNote.textContent = `캐릭터 교체 확인 실패: ${e.message} · 장면·표정·복장 수정만 사용할 수 있습니다.`;
                    document.getElementById('llm-edit-run-btn').disabled = false;
                }
            } else {
                scopeNote.textContent = fmt === 'chansub'
                    ? '챈섭 백업은 기존 장면·표정·복장 수정만 지원합니다. 로컬 캐릭터 LoRA/FACE 데이터는 적용되지 않습니다.'
                    : 'V1 백업은 기존 장면·표정·복장 수정만 지원합니다. 캐릭터·FACE·LoRA 교체는 V3 Comfy 전용입니다.';
            }
            setTimeout(() => input.focus(), 50);
        }

        function closeLlmEditModal() {
            const el = document.getElementById('llm-edit-direction-modal');
            if (el) el.classList.remove('visible');
        }

        function openIllustrationAutoFeedbackModal() {
            const modal = document.getElementById('illustration-auto-feedback-modal');
            if (!modal) {
                console.error('[AUTO_FEEDBACK_UI] 오토피드백 모달을 찾을 수 없습니다.');
                return;
            }
            modal.classList.add('visible');
            if (illustrationAutoFeedbackState.job) {
                renderIllustrationAutoFeedbackJob(illustrationAutoFeedbackState.job);
            } else {
                resetIllustrationAutoFeedbackUi();
            }
        }

        function closeIllustrationAutoFeedbackModal() {
            const modal = document.getElementById('illustration-auto-feedback-modal');
            if (modal) modal.classList.remove('visible');
        }

        function isIllustrationAutoFeedbackActive() {
            const status = String(illustrationAutoFeedbackState.job?.status || '');
            return !!illustrationAutoFeedbackState.jobId
                && !['completed', 'failed', 'cancelled'].includes(status);
        }

        function resetIllustrationAutoFeedbackUi() {
            const status = document.getElementById('llm-edit-auto-feedback-status');
            const statusBadge = document.getElementById('llm-edit-auto-feedback-status-badge');
            const roundBadge = document.getElementById('llm-edit-auto-feedback-round-badge');
            const statusText = document.getElementById('llm-edit-auto-feedback-status-text');
            const progressText = document.getElementById('llm-edit-auto-feedback-progress-text');
            const progressBar = document.getElementById('llm-edit-auto-feedback-progress-bar');
            const goal = document.getElementById('llm-edit-auto-feedback-goal');
            const currentDirection = document.getElementById('llm-edit-auto-feedback-current-direction');
            const best = document.getElementById('llm-edit-auto-feedback-best');
            const rounds = document.getElementById('llm-edit-auto-feedback-rounds');
            const empty = document.getElementById('llm-edit-auto-feedback-empty');
            const runButton = document.getElementById('llm-edit-auto-feedback-run-btn');
            const cancelButton = document.getElementById('llm-edit-auto-feedback-cancel-btn');
            const editButton = document.getElementById('llm-edit-run-btn');
            const directionInput = document.getElementById('llm-edit-direction-input');
            const maxInput = document.getElementById('llm-edit-auto-feedback-max');
            if (status) status.style.display = 'block';
            if (statusBadge) {
                statusBadge.textContent = '대기';
                statusBadge.style.background = 'rgba(83,183,168,.14)';
                statusBadge.style.color = '#53b7a8';
            }
            if (roundBadge) roundBadge.textContent = '0/0회';
            if (statusText) {
                statusText.textContent = '서버 작업을 준비하고 있습니다.';
                statusText.style.color = 'var(--text)';
            }
            if (progressText) progressText.textContent = '0%';
            if (progressBar) {
                progressBar.style.width = '0%';
                progressBar.style.background = 'var(--accent)';
            }
            if (goal) goal.textContent = '-';
            if (currentDirection) currentDirection.textContent = '-';
            if (best) {
                best.style.display = 'none';
                best.textContent = '';
            }
            if (rounds) rounds.innerHTML = '';
            if (empty) empty.style.display = 'block';
            if (runButton) {
                runButton.disabled = false;
                runButton.textContent = '오토피드백';
            }
            if (cancelButton) {
                cancelButton.style.display = 'none';
                cancelButton.disabled = true;
                cancelButton.textContent = '안전 중지';
            }
            if (editButton) editButton.disabled = false;
            if (directionInput) directionInput.disabled = false;
            if (maxInput) maxInput.disabled = false;
        }

        function autoFeedbackPhaseLabel(phase) {
            return ({
                queued: '큐 등록',
                preparing: '준비',
                editing: '프롬프트 수정',
                generating: '이미지 생성',
                reviewing: '비전 검수',
                completed: '완료',
                failed: '실패',
                cancelled: '중지',
            })[String(phase || '')] || String(phase || '진행 중');
        }

        function renderIllustrationAutoFeedbackJob(job) {
            if (!job || typeof job !== 'object') {
                console.error('[AUTO_FEEDBACK_UI] 표시할 작업 상태가 없습니다:', job);
                return;
            }
            illustrationAutoFeedbackState.job = job;
            const active = !['completed', 'failed', 'cancelled'].includes(String(job.status || ''));
            const progress = Math.max(0, Math.min(100, Number(job.progress) || 0));
            const status = document.getElementById('llm-edit-auto-feedback-status');
            const statusBadge = document.getElementById('llm-edit-auto-feedback-status-badge');
            const roundBadge = document.getElementById('llm-edit-auto-feedback-round-badge');
            const statusText = document.getElementById('llm-edit-auto-feedback-status-text');
            const progressText = document.getElementById('llm-edit-auto-feedback-progress-text');
            const progressBar = document.getElementById('llm-edit-auto-feedback-progress-bar');
            const goal = document.getElementById('llm-edit-auto-feedback-goal');
            const currentDirection = document.getElementById('llm-edit-auto-feedback-current-direction');
            const best = document.getElementById('llm-edit-auto-feedback-best');
            const rounds = document.getElementById('llm-edit-auto-feedback-rounds');
            const empty = document.getElementById('llm-edit-auto-feedback-empty');
            const runButton = document.getElementById('llm-edit-auto-feedback-run-btn');
            const cancelButton = document.getElementById('llm-edit-auto-feedback-cancel-btn');
            const editButton = document.getElementById('llm-edit-run-btn');
            const directionInput = document.getElementById('llm-edit-direction-input');
            const maxInput = document.getElementById('llm-edit-auto-feedback-max');
            if (status) status.style.display = 'block';
            if (statusBadge) {
                const badge = job.status === 'failed'
                    ? {text: '실패', background: 'rgba(239,68,68,.14)', color: 'var(--error)'}
                    : job.status === 'cancelled'
                        ? {text: '안전 중지', background: 'rgba(148,163,184,.14)', color: 'var(--text-secondary)'}
                        : job.status === 'completed' && job.achieved
                            ? {text: '성공', background: 'rgba(83,183,168,.14)', color: 'var(--success)'}
                            : job.status === 'completed'
                                ? {text: '목표 미달 종료', background: 'rgba(227,167,80,.14)', color: '#e3a750'}
                                : {text: autoFeedbackPhaseLabel(job.phase), background: 'rgba(83,183,168,.14)', color: '#53b7a8'};
                statusBadge.textContent = badge.text;
                statusBadge.style.background = badge.background;
                statusBadge.style.color = badge.color;
            }
            if (roundBadge) roundBadge.textContent = `${Number(job.round) || 0}/${Number(job.max_rounds) || 0}회`;
            if (statusText) {
                statusText.textContent = job.message || autoFeedbackPhaseLabel(job.phase);
                statusText.style.color = job.status === 'failed'
                    ? 'var(--error)'
                    : job.status === 'completed' && job.achieved
                        ? 'var(--success)'
                        : job.status === 'completed'
                            ? '#e3a750'
                        : 'var(--text)';
            }
            if (goal) goal.textContent = job.goal || '-';
            if (currentDirection) currentDirection.textContent = job.current_direction || job.goal || '-';
            if (progressText) progressText.textContent = `${Math.round(progress)}%`;
            if (progressBar) {
                progressBar.style.width = `${progress}%`;
                progressBar.style.background = job.status === 'failed'
                    ? 'var(--error)'
                    : job.status === 'completed' && job.achieved
                        ? 'var(--success)'
                        : job.status === 'completed'
                            ? '#e3a750'
                        : 'var(--accent)';
            }
            if (best) {
                if (job.best_backup_name) {
                    best.style.display = 'block';
                    best.textContent = `현재 최고 결과: ${Number(job.best_round) || 0}회 · ${Number(job.best_score) || 0}점 · ${job.best_backup_name}`;
                } else {
                    best.style.display = 'none';
                    best.textContent = '';
                }
            }
            if (rounds) {
                const entries = Array.isArray(job.rounds) ? job.rounds : [];
                rounds.innerHTML = entries.map(entry => {
                    const review = entry.review && typeof entry.review === 'object' ? entry.review : null;
                    const verdict = !review
                        ? '검수 대기'
                        : review.achieved
                            ? `목표 달성 · ${review.score}점`
                            : `목표 미달 · ${review.score}점`;
                    const verdictColor = review?.achieved ? 'var(--success)' : (review ? '#e3a750' : 'var(--text-secondary)');
                    const summary = review?.summary
                        ? `<div style="margin-top:7px;color:var(--text-secondary);"><strong>검수:</strong> ${escapeHtml(review.summary)}</div>`
                        : '';
                    const appliedDirection = entry.edit_direction
                        ? `<div style="margin-top:7px;color:var(--text);"><strong>실제 수정 계획:</strong> ${escapeHtml(entry.edit_direction)}</div>`
                        : '';
                    const remainingGaps = review?.remaining_gaps
                        ? `<div style="margin-top:5px;color:#e3a750;"><strong>남은 차이:</strong> ${escapeHtml(review.remaining_gaps)}</div>`
                        : '';
                    const nextDirection = review?.next_direction && !review?.achieved
                        ? `<div style="margin-top:5px;color:#53b7a8;"><strong>다음 회차 지시:</strong> ${escapeHtml(review.next_direction)}</div>`
                        : '';
                    return `<div style="padding:9px 10px;border:1px solid var(--border);border-radius:7px;background:var(--surface1);font-size:0.72rem;line-height:1.45;">
                        <div style="display:flex;justify-content:space-between;gap:8px;">
                            <strong>${escapeHtml(String(entry.round || ''))}회 · 백업 보존</strong>
                            <span style="color:${verdictColor};">${escapeHtml(verdict)}</span>
                        </div>
                        <div style="margin-top:3px;color:var(--text-secondary);word-break:break-all;">${escapeHtml(entry.backup_name || '')}</div>
                        ${appliedDirection}
                        ${summary}
                        ${remainingGaps}
                        ${nextDirection}
                    </div>`;
                }).join('');
                rounds.scrollTop = rounds.scrollHeight;
                if (empty) empty.style.display = entries.length ? 'none' : 'block';
            }
            if (runButton) {
                runButton.disabled = false;
                runButton.textContent = active ? '진행 보기' : '오토피드백';
            }
            if (cancelButton) {
                const hasServerJob = !!(job.job_id || illustrationAutoFeedbackState.jobId);
                cancelButton.style.display = active ? '' : 'none';
                cancelButton.disabled = !hasServerJob || !!job.cancel_requested;
                cancelButton.textContent = !hasServerJob
                    ? '작업 등록 중...'
                    : job.cancel_requested
                        ? '안전 중지 대기 중...'
                        : '안전 중지';
            }
            if (editButton) editButton.disabled = active;
            if (directionInput) directionInput.disabled = active;
            if (maxInput) maxInput.disabled = active;

            if (!active && !illustrationAutoFeedbackState.terminalHandled) {
                illustrationAutoFeedbackState.terminalHandled = true;
                stopIllustrationAutoFeedbackPolling();
                if (job.status === 'completed') {
                    const resultText = job.achieved
                        ? `${job.round}회 만에 목표 달성`
                        : `최대 횟수 완료 · 최고 ${job.best_score ?? 0}점`;
                    showToast(`${resultText} · 모든 생성 이미지는 백업에 보존됨`, 'success');
                } else if (job.status === 'cancelled') {
                    showToast(`오토피드백 중지 · 생성 완료된 ${(job.rounds || []).length}개 이미지는 백업에 보존됨`, 'warning');
                } else {
                    showToast(job.message || `오토피드백 실패: ${job.error || '알 수 없는 오류'}`, 'error');
                }
                if (typeof loadBackups === 'function') loadBackups(true);
            }
        }

        function stopIllustrationAutoFeedbackPolling() {
            if (illustrationAutoFeedbackState.pollTimer) {
                clearInterval(illustrationAutoFeedbackState.pollTimer);
                illustrationAutoFeedbackState.pollTimer = null;
            }
        }

        function startIllustrationAutoFeedbackPolling() {
            stopIllustrationAutoFeedbackPolling();
            illustrationAutoFeedbackState.pollTimer = setInterval(async () => {
                const jobId = illustrationAutoFeedbackState.jobId;
                if (!jobId || !isIllustrationAutoFeedbackActive()) {
                    stopIllustrationAutoFeedbackPolling();
                    return;
                }
                try {
                    const data = await fetchJSON(`/api/illustration_auto_feedback/${encodeURIComponent(jobId)}`);
                    if (data.job) handleIllustrationAutoFeedbackUpdate(data.job);
                } catch (error) {
                    console.error('[AUTO_FEEDBACK_UI] 상태 폴링 실패:', {jobId, error});
                }
            }, 1500);
        }

        function handleIllustrationAutoFeedbackUpdate(job) {
            if (!job || !job.job_id) {
                console.error('[AUTO_FEEDBACK_UI] 잘못된 상태 이벤트:', job);
                return;
            }
            if (
                !illustrationAutoFeedbackState.jobId
                && (!illustrationAutoFeedbackState.sourceBackupName
                    || illustrationAutoFeedbackState.sourceBackupName !== job.source_backup_name)
            ) {
                return;
            }
            if (illustrationAutoFeedbackState.jobId && illustrationAutoFeedbackState.jobId !== job.job_id) {
                return;
            }
            illustrationAutoFeedbackState.jobId = job.job_id;
            illustrationAutoFeedbackState.sourceBackupName = job.source_backup_name || '';
            renderIllustrationAutoFeedbackJob(job);
        }

        async function startIllustrationAutoFeedback() {
            if (isIllustrationAutoFeedbackActive()) {
                closePromptModal();
                openIllustrationAutoFeedbackModal();
                return;
            }
            if (!currentModalBackupName || llmEditInFlight) return;
            if (document.getElementById('llm-edit-response-language').disabled) {
                showToast('답변 언어를 불러오거나 저장하는 중입니다. 잠시 후 다시 시도해주세요.', 'info');
                return;
            }
            const sourceBackupName = currentModalBackupName;
            const directionInput = document.getElementById('llm-edit-direction-input');
            const direction = String(directionInput?.value || '').trim();
            const maxInput = document.getElementById('llm-edit-auto-feedback-max');
            const maxRounds = Number(maxInput?.value || 3);
            if (!direction) {
                alert('오토피드백의 최종 목표를 입력해주세요.');
                directionInput?.focus();
                return;
            }
            if (!Number.isInteger(maxRounds) || maxRounds < 1 || maxRounds > 10) {
                alert('최대 횟수는 1~10 사이 정수로 입력해주세요.');
                maxInput?.focus();
                return;
            }
            let selectedCharacters = null;
            let selectedVisualProfileIds = null;
            if (llmEditModalState?.identityEnabled) {
                if (!updateLlmEditCharacterSelection()) return;
                selectedCharacters = [...llmEditModalState.slotNames];
                selectedVisualProfileIds = { ...llmEditModalState.visualProfileIds };
            }
            const requestBody = {
                name: sourceBackupName,
                positive: document.getElementById('modal-positive').value || '',
                negative: document.getElementById('modal-negative').value || '',
                direction,
                max_rounds: maxRounds,
                allow_mask_edit: document.getElementById('llm-edit-allow-mask-edit')?.checked === true,
                illustration_multi_char: currentModalMultiChar,
            };
            if (selectedCharacters) requestBody.characters = selectedCharacters;
            if (selectedVisualProfileIds) requestBody.visual_profile_ids = selectedVisualProfileIds;
            if (selectedCharacters && currentModalIdentityEdit) {
                requestBody.previous_identity = currentModalIdentityEdit;
            }
            if (currentModalCameraAppliedControl) {
                requestBody.camera_control = currentModalCameraAppliedControl;
            }
            illustrationAutoFeedbackState = {
                jobId: '',
                sourceBackupName,
                job: {
                    status: 'queued',
                    phase: 'queued',
                    progress: 0,
                    round: 0,
                    max_rounds: maxRounds,
                    rounds: [],
                    goal: direction,
                    current_direction: '이미지와 기존 프롬프트를 분석해 구체적인 수정 계획을 준비하고 있습니다.',
                    message: '서버에 오토피드백 작업을 등록하고 있습니다',
                },
                pollTimer: null,
                terminalHandled: false,
            };
            closePromptModal();
            openIllustrationAutoFeedbackModal();
            renderIllustrationAutoFeedbackJob(illustrationAutoFeedbackState.job);
            try {
                const data = await fetchJSON('/api/illustration_auto_feedback', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(requestBody),
                });
                if (!data.job?.job_id) {
                    throw new Error('서버가 오토피드백 작업 ID를 반환하지 않았습니다.');
                }
                illustrationAutoFeedbackState.jobId = data.job.job_id;
                illustrationAutoFeedbackState.sourceBackupName = data.job.source_backup_name || sourceBackupName;
                illustrationAutoFeedbackState.terminalHandled = false;
                renderIllustrationAutoFeedbackJob(data.job);
                startIllustrationAutoFeedbackPolling();
                showToast(`오토피드백 최대 ${maxRounds}회 작업을 시작했습니다`, 'info');
            } catch (error) {
                console.error('[AUTO_FEEDBACK_UI] 작업 시작 실패:', {requestBody, error});
                illustrationAutoFeedbackState.job = {
                    ...illustrationAutoFeedbackState.job,
                    status: 'failed',
                    phase: 'failed',
                    message: `오토피드백 시작 실패: ${error.message}`,
                    error: error.message,
                };
                renderIllustrationAutoFeedbackJob(illustrationAutoFeedbackState.job);
            }
        }

        async function cancelIllustrationAutoFeedback() {
            const jobId = illustrationAutoFeedbackState.jobId;
            if (!jobId || !isIllustrationAutoFeedbackActive()) return;
            const button = document.getElementById('llm-edit-auto-feedback-cancel-btn');
            if (button) {
                button.disabled = true;
                button.textContent = '안전 중지 요청 중...';
            }
            try {
                const data = await fetchJSON(
                    `/api/illustration_auto_feedback/${encodeURIComponent(jobId)}/cancel`,
                    { method: 'POST' },
                );
                if (data.job) handleIllustrationAutoFeedbackUpdate(data.job);
            } catch (error) {
                console.error('[AUTO_FEEDBACK_UI] 중지 요청 실패:', {jobId, error});
                showToast(`오토피드백 중지 요청 실패: ${error.message}`, 'error');
                if (button) {
                    button.disabled = false;
                    button.textContent = '안전 중지';
                }
            }
        }

        async function llmEditPrompt() {
            if (!currentModalBackupName) return;
            if (llmEditInFlight) return;
            if (document.getElementById('llm-edit-response-language').disabled) {
                showToast('답변 언어를 불러오거나 저장하는 중입니다. 잠시 후 다시 시도해주세요.', 'info');
                return;
            }
            const positive = document.getElementById('modal-positive').value;
            const negative = document.getElementById('modal-negative').value;
            const direction = (document.getElementById('llm-edit-direction-input').value || '').trim();
            let selectedCharacters = null;
            let selectedVisualProfileIds = null;
            if (llmEditModalState?.identityEnabled) {
                if (!updateLlmEditCharacterSelection()) return;
                selectedCharacters = [...llmEditModalState.slotNames];
                selectedVisualProfileIds = { ...llmEditModalState.visualProfileIds };
            }
            if (!direction) {
                alert('수정 방향을 입력해주세요.');
                return;
            }

            llmEditInFlight = true;
            const btn = document.getElementById('llm-edit-run-btn');
            const btnText = document.getElementById('llm-edit-run-text');
            const origText = btnText.textContent;
            btn.disabled = true;
            btnText.textContent = 'LLM 분석 중...';

            try {
                const requestBody = {
                    name: currentModalBackupName,
                    positive: positive,
                    negative: negative,
                    direction: direction,
                    allow_mask_edit: document.getElementById('llm-edit-allow-mask-edit')?.checked === true,
                    illustration_multi_char: currentModalMultiChar,
                    illustration_flow_run_id: currentModalFlowRunId,
                };
                if (selectedCharacters) requestBody.characters = selectedCharacters;
                if (selectedVisualProfileIds) {
                    requestBody.visual_profile_ids = selectedVisualProfileIds;
                }
                if (selectedCharacters && currentModalIdentityEdit) {
                    requestBody.previous_identity = currentModalIdentityEdit;
                }
                const data = await fetchJSON('/api/llm_edit_prompt', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(requestBody)
                });

                if (data.error) {
                    alert('편하게 수정 실패: ' + data.error);
                    return;
                }

                // 수정된 positive 반영 + 계획 표시 (prompt-modal 본문 인라인)
                if (data.positive) {
                    document.getElementById('modal-positive').value = data.positive;
                }
                if (typeof data.negative === 'string') {
                    document.getElementById('modal-negative').value = data.negative;
                }
                if (currentModalCameraAppliedControl) {
                    currentModalCameraDirty = true;
                    updateIllustrationCameraOpenButton();
                }
                if (data.plan) {
                    document.getElementById('modal-llm-plan-text').textContent = data.plan;
                    document.getElementById('modal-llm-plan').style.display = 'block';
                }
                // 파싱 실패(원본 유지)는 "완료"가 아님 — 원인을 우하단 LIGHBD 위젯에서 확인
                if (data.parse_failed) {
                    showToast('LLM 응답 파싱 실패 — 원본 유지. 우하단 LIGHBD 위젯(자세히) 확인', 'warning');
                    return;
                }
                currentModalIdentityEdit = data.identity_edit || currentModalIdentityEdit;
                currentModalMultiChar = data.illustration_multi_char || currentModalMultiChar;
                currentModalFlowRunId = data.illustration_flow_run_id || '';
                showToast(data.mask_edit_error
                    ? '프롬프트를 수정했습니다. 일부 마스크 좌표는 적용하지 못했습니다. 수정 계획을 확인해주세요.'
                    : data.identity_edit
                    ? '장면과 캐릭터·프로필·FACE·LoRA 수정 적용 완료'
                    : '편하게 수정 적용 완료', data.mask_edit_error ? 'warning' : 'success');
                closeLlmEditModal();
            } catch (e) {
                console.error('[EASY_EDIT] 수정 요청 실패:', e);
                alert('편하게 수정 실패: ' + e.message);
            } finally {
                llmEditInFlight = false;
                btn.disabled = false;
                btnText.textContent = origText;
                if (document.getElementById('llm-edit-direction-modal').classList.contains('visible')) {
                    updateLlmEditCharacterSelection();
                }
            }
        }

        // ─── LLM 보조 프롬프트(builtin/custom) 편집 오버레이 ───
        async function openLlmEditTemplateOverlay() {
            const existing = document.getElementById('llm-edit-template-overlay');
            if (existing) existing.remove();

            const overlay = document.createElement('div');
            overlay.id = 'llm-edit-template-overlay';
            overlay.style.cssText = 'position:fixed; inset:0; z-index:290; background:rgba(0,0,0,0.6); display:flex; align-items:center; justify-content:center;';
            // 바깥 클릭으로 닫기 금지 — ✕/닫기/저장 버튼만
            overlay.innerHTML = `
                <div style="background:var(--surface); border:1px solid var(--border); border-radius:12px; width:92vw; max-width:820px; height:86vh; display:flex; flex-direction:column; overflow:hidden;">
                    <div style="display:flex; align-items:center; padding:12px 16px; border-bottom:1px solid var(--border); gap:12px; flex-shrink:0;">
                        <span style="font-weight:700; font-size:1.0rem;">🛠 LLM 보조 프롬프트</span>
                        <div style="flex:1;"></div>
                        <button onclick="document.getElementById('llm-edit-template-overlay').remove()" style="background:none; border:none; color:var(--text2); font-size:1.2rem; cursor:pointer;">✕</button>
                    </div>
                    <div style="padding:8px 16px; font-size:0.72rem; color:var(--text2); border-bottom:1px solid var(--border); flex-shrink:0;">
                        글로벌은 배포용(읽기 전용), 커스텀은 이 PC 전용(편집 가능). 드롭다운으로 System과 V3·V1·챈섭 User 템플릿을 전환하며 편집. 커스텀 사용 스위치가 켜져 있어도, 해당 칸이 비어 있으면 그 슬롯만 글로벌 적용.
                    </div>
                    <div id="llm-tpl-panel" style="flex:1; display:flex; flex-direction:column; padding:12px 16px; overflow:hidden; gap:10px; min-height:0;">
                        <div style="display:flex; align-items:center; gap:8px; flex-shrink:0;">
                            <label for="llm-tpl-slot" style="font-size:0.78rem; font-weight:600; color:var(--text);">편집 대상</label>
                            <select id="llm-tpl-slot" onchange="_llmTplSwitchSlot(this)" style="flex:1; padding:4px 8px; border:1px solid var(--border); border-radius:6px; background:var(--surface); color:var(--text); font-size:0.8rem; cursor:pointer;">
                                <option value="system">System 역할 (V3·V1 공통)</option>
                                <option value="system_chansub">System 역할 — 챈섭 (Comfy)</option>
                                <option value="user_v3">User 지시 — V3 (삽화 빌드본)</option>
                                <option value="user_v1">User 지시 — V1 (ILXL·UPSCALE)</option>
                                <option value="user_chansub">User 지시 — 챈섭 (Comfy)</option>
                            </select>
                            <div id="llm-tpl-badge" style="font-size:0.68rem; padding:1px 6px; border-radius:4px; background:var(--surface2); color:var(--text2); white-space:nowrap;">이 슬롯: 글로벌</div>
                        </div>
                        <div style="display:flex; flex-direction:column; gap:4px; flex:1; min-height:0;">
                            <div style="font-size:0.78rem; font-weight:600; color:var(--text);">글로벌 <span style="font-size:0.7rem; color:var(--text2); font-weight:400;">(배포용 · 읽기 전용)</span></div>
                            <textarea id="llm-tpl-builtin" readonly style="flex:1; min-height:100px; width:100%; resize:none; padding:8px; border:1px solid var(--border); border-radius:6px; background:var(--surface2); color:var(--text2); font-size:0.75rem; font-family:ui-monospace,Menlo,monospace; line-height:1.4;"></textarea>
                        </div>
                        <div style="display:flex; flex-direction:column; gap:4px; flex:1; min-height:0;">
                            <div style="display:flex; justify-content:space-between; align-items:center;">
                                <div style="font-size:0.78rem; font-weight:600; color:var(--text);">커스텀 <span style="font-size:0.7rem; color:var(--text2); font-weight:400;">(이 PC 전용 · 편집 가능)</span></div>
                                <button onclick="_llmTplCopyBuiltin()" style="background:var(--surface2); color:var(--text); border:1px solid var(--border); padding:2px 8px; border-radius:4px; cursor:pointer; font-size:0.7rem;">글로벌에서 복사</button>
                            </div>
                            <textarea id="llm-tpl-custom" placeholder="비어 있음 — 이 슬롯은 글로벌 적용. 직접 작성하거나 '글로벌에서 복사'로 시작" style="flex:1; min-height:140px; width:100%; resize:vertical; padding:8px; border:1px solid var(--accent); border-radius:6px; background:var(--surface); color:var(--text); font-size:0.78rem; font-family:ui-monospace,Menlo,monospace; line-height:1.4;"></textarea>
                            <div id="llm-tpl-hint" style="font-size:0.7rem; color:var(--text2);"></div>
                        </div>
                    </div>
                    <div style="padding:10px 16px; border-top:1px solid var(--border); display:flex; justify-content:space-between; align-items:center; gap:8px; flex-shrink:0;">
                        <label style="display:flex; align-items:center; gap:6px; font-size:0.8rem; cursor:pointer;">
                            <input type="checkbox" id="llm-tpl-use" style="cursor:pointer;">
                            <span>커스텀 프롬프트 사용 <span style="color:var(--text2); font-size:0.72rem;">(체크 해제 시 전부 글로벌)</span></span>
                        </label>
                        <div style="display:flex; gap:8px;">
                            <button onclick="document.getElementById('llm-edit-template-overlay').remove()" style="background:var(--surface2); color:var(--text); border:1px solid var(--border); padding:6px 14px; border-radius:6px; cursor:pointer; font-size:0.8rem;">닫기</button>
                            <button onclick="_saveLlmEditTemplate()" style="background:#1565C0; color:#fff; border:none; padding:6px 16px; border-radius:6px; cursor:pointer; font-size:0.8rem; font-weight:600;">저장</button>
                        </div>
                    </div>
                </div>`;
            document.body.appendChild(overlay);

            // 슬롯 메타데이터(라벨/힌트)
            const LLM_TPL_SLOTS = {
                system:  { hint: 'LLM의 역할·출력 형식(JSON only)을 정의. 모든 포맷에 공통 적용.' },
                system_chansub: { hint: '챈섭 Comfy 프롬프트 편집 전용 system 역할과 positive/negative JSON 출력 규칙.' },
                user_v3: { hint: '삽화 빌드본(ANIMA/ILXL)용 user 지시. 플레이스홀더 {direction} {scene_current} {scene_sdxl} 은 자동 치환됨.' },
                user_v1: { hint: 'ILXL/UPSCALE(V1)용 user 지시. 플레이스홀더 {direction} {setup} {char} {supplement} 은 자동 치환됨.' },
                user_chansub: { hint: '챈섭 Comfy 프롬프트용 user 지시. 플레이스홀더 {direction} {positive} {negative} 는 자동 치환됨.' },
            };

            // 데이터 로드 → 3슬롯 상태 구성
            window._llmTplState = {
                current: 'system',
                builtins: { system: '', system_chansub: '', user_v3: '', user_v1: '', user_chansub: '' },
                customs: { system: '', system_chansub: '', user_v3: '', user_v1: '', user_chansub: '' },
            };
            try {
                const resp = await fetch('/api/llm_edit_prompt_template');
                const result = await resp.json();
                const d = (result.data || {});
                document.getElementById('llm-tpl-use').checked = !!d.use_custom;
                const tpls = d.templates || {};
                for (const slot of Object.keys(window._llmTplState.builtins)) {
                    const t = tpls[slot] || {};
                    window._llmTplState.builtins[slot] = t.builtin || '';
                    window._llmTplState.customs[slot] = t.custom || '';
                }
            } catch (e) {
                console.error('[LLM_EDIT_TEMPLATE] 로드 실패:', e);
                showToast(`보조 프롬프트 로드 실패: ${e.message}`, 'error');
            }
            window._llmTplSlotsMeta = LLM_TPL_SLOTS;
            _llmTplRenderSlot();
            document.getElementById('llm-tpl-custom').addEventListener('input', () => { _llmTplSyncCurrent(); _llmTplUpdateBadge(); });
            document.getElementById('llm-tpl-use').addEventListener('change', _llmTplUpdateBadge);
        }

        // 현재 슬롯의 커스텀 textarea 값을 state 에 동기화(슬롯 전환/저장 전 호출)
        function _llmTplSyncCurrent() {
            const st = window._llmTplState;
            const ta = document.getElementById('llm-tpl-custom');
            if (!st || !ta) return;
            st.customs[st.current] = ta.value;
        }

        // state 의 현재 슬롯 값을 UI 에 렌더
        function _llmTplRenderSlot() {
            const st = window._llmTplState;
            if (!st) return;
            const slot = st.current;
            document.getElementById('llm-tpl-slot').value = slot;
            document.getElementById('llm-tpl-builtin').value = st.builtins[slot] || '';
            document.getElementById('llm-tpl-custom').value = st.customs[slot] || '';
            const meta = (window._llmTplSlotsMeta || {})[slot] || {};
            document.getElementById('llm-tpl-hint').textContent = meta.hint || '';
            _llmTplUpdateBadge();
        }

        // 드롭다운 슬롯 전환: 현재 값 동기화 후 새 슬롯 렌더
        function _llmTplSwitchSlot(sel) {
            _llmTplSyncCurrent();
            window._llmTplState.current = sel.value;
            _llmTplRenderSlot();
        }

        function _llmTplUpdateBadge() {
            const badge = document.getElementById('llm-tpl-badge');
            if (!badge) return;
            const useCustom = document.getElementById('llm-tpl-use')?.checked;
            const customText = (document.getElementById('llm-tpl-custom')?.value || '').trim();
            const eff = useCustom && customText;
            badge.textContent = eff ? '이 슬롯: 커스텀' : '이 슬롯: 글로벌';
            badge.style.background = eff ? 'rgba(124,58,237,0.18)' : 'var(--surface2)';
            badge.style.color = eff ? '#7C3AED' : 'var(--text2)';
        }

        function _llmTplCopyBuiltin() {
            const builtin = document.getElementById('llm-tpl-builtin')?.value || '';
            const ta = document.getElementById('llm-tpl-custom');
            if (!ta) return;
            if (ta.value.trim() && !confirm('현재 슬롯의 커스텀 내용을 글로벌로 덮어쓸까요?')) return;
            ta.value = builtin;
            const chk = document.getElementById('llm-tpl-use');
            if (chk) chk.checked = true;
            _llmTplSyncCurrent();
            _llmTplUpdateBadge();
            showToast('글로벌을 커스텀으로 복사했습니다 (저장 필요)', 'info');
        }

        async function _saveLlmEditTemplate(responseLanguage) {
            const languageSelect = document.getElementById('llm-edit-response-language');
            let body;
            if (responseLanguage !== undefined) {
                languageSelect.disabled = true;
                body = { response_language: responseLanguage };
            } else {
                _llmTplSyncCurrent();
                const st = window._llmTplState;
                body = {
                    use_custom: document.getElementById('llm-tpl-use').checked,
                    templates: {
                        system: st.customs.system || '',
                        system_chansub: st.customs.system_chansub || '',
                        user_v3: st.customs.user_v3 || '',
                        user_v1: st.customs.user_v1 || '',
                        user_chansub: st.customs.user_chansub || '',
                    },
                };
            }
            try {
                const resp = await fetch('/api/llm_edit_prompt_template', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(body)
                });
                const result = await resp.json();
                if (!resp.ok || !result.success) throw new Error(result.error || '알 수 없는 오류');
                if (responseLanguage !== undefined) {
                    languageSelect.dataset.savedValue = responseLanguage;
                    showToast('답변 언어 저장 완료', 'success');
                } else {
                    showToast('보조 프롬프트 저장 완료', 'success');
                    document.getElementById('llm-edit-template-overlay').remove();
                }
            } catch (e) {
                console.error('[EASY_EDIT] 설정 저장 실패:', { body, error: e });
                if (responseLanguage !== undefined) {
                    languageSelect.value = languageSelect.dataset.savedValue || 'en';
                    showToast('답변 언어 저장 실패: ' + e.message, 'error');
                } else {
                    alert('보조 프롬프트 저장 실패: ' + e.message);
                }
            } finally {
                if (responseLanguage !== undefined) languageSelect.disabled = false;
            }
        }

        async function submitModifiedPrompt() {
            if (!currentModalBackupName) return;

            if (currentModalCameraSupported && currentModalCameraDirty) {
                alert('구도 선택 또는 프롬프트가 변경되었습니다. 먼저 “LLM으로 구도 반영”을 실행해주세요.');
                return;
            }

            const positive = document.getElementById('modal-positive').value.trim();
            const negative = document.getElementById('modal-negative').value.trim();

            if (!positive && !negative) {
                alert('적어도 하나의 프롬프트를 입력해야 합니다.');
                return;
            }

            const submitBtn = document.getElementById('modal-submit-btn');
            const originalText = document.getElementById('modal-submit-text').textContent;
            submitBtn.disabled = true;
            document.getElementById('modal-submit-text').textContent = '생성중...';
            showTopProgress();

            try {
                const requestBody = {
                    name: currentModalBackupName,
                    positive: positive,
                    negative: negative,
                    identity_edit: currentModalIdentityEdit,
                    illustration_multi_char: currentModalMultiChar,
                    illustration_flow_run_id: currentModalFlowRunId,
                };
                if (currentModalCameraAppliedControl) {
                    requestBody.camera_control = currentModalCameraAppliedControl;
                }
                const data = await fetchJSON('/api/reschedule_with_modified_prompt', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(requestBody)
                });

                if (data.error) {
                    alert('프롬프트 수정 후 재생성 실패: ' + data.error);
                    submitBtn.disabled = false;
                    document.getElementById('modal-submit-text').textContent = originalText;
                    hideTopProgress();
                    return;
                }

                // 큐 등록 성공: 입력 모달은 즉시 닫고 최종 결과는 WebSocket으로 알린다.
                closePromptModal();
                showToast(data.message || '프롬프트 수정 재생성을 큐에 등록했습니다', 'info');
            } catch (e) {
                alert('프롬프트 수정 후 재생성 실패: ' + e.message);
                submitBtn.disabled = false;
                document.getElementById('modal-submit-text').textContent = originalText;
            } finally {
                hideTopProgress();
            }
        }

        function closeRegen(name) {
            const overlay = document.getElementById('regen-' + name);
            if (overlay) {
                overlay.classList.remove('visible');
                overlay.querySelector('img').src = '';
            }
        }

        // ─── 워크플로우 가져오기 ───
        async function reloadWorkflow() {
            try {
                const data = await fetchJSON('/api/reload_workflow', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({})
                });
                if (data.error) {
                    showToast(data.error, 'error');
                } else {
                    showToast(data.message || '워크플로우를 성공적으로 가져왔습니다', 'success');
                    await loadConversionInfo();
                }
            } catch (e) {
                showToast('워크플로우 가져오기 실패: ' + e.message, 'error');
            }
        }

        function updateCharacterMakerRagSettingStatus(enabled) {
            const status = document.getElementById('setting-character-maker-rag-status');
            if (!status) return;
            status.textContent = enabled ? 'ON' : 'OFF';
            status.className = 'toggle-status ' + (enabled ? 'on' : 'off');
        }

        function updateCharacterMakerRagAutostartStatus(enabled) {
            const status = document.getElementById('setting-character-maker-rag-autostart-status');
            if (!status) return;
            status.textContent = enabled ? 'ON' : 'OFF';
            status.className = 'toggle-status ' + (enabled ? 'on' : 'off');
        }

        function cmApplyRagAutostartDisabledState(dataReady) {
            const toggle = document.getElementById('setting-character-maker-rag-autostart');
            if (!toggle) return;
            toggle.disabled = !dataReady;
            if (!dataReady && toggle.checked) {
                toggle.checked = false;
                updateCharacterMakerRagAutostartStatus(false);
            }
        }

        let cmRagRuntimeState = 'stopped';
        let cmRagRuntimeLoaded = false;
        let cmRagIndexInstalled = false;
        let cmRagDatasetBusy = false;
        let cmRagLoadingPollTimer = null;

        function cmFormatDatasetBytes(bytes) {
            const size = Number(bytes || 0);
            if (size < 1024) return `${size} B`;
            if (size < 1024 * 1024) return `${(size / 1024).toFixed(1)} KB`;
            return `${(size / (1024 * 1024)).toFixed(1)} MB`;
        }

        function cmRenderRagRuntimeStatus(data) {
            const status = document.getElementById('setting-character-maker-rag-runtime-state');
            const startButton = document.getElementById('setting-character-maker-rag-runtime-start');
            const stopButton = document.getElementById('setting-character-maker-rag-runtime-stop');
            const installButton = document.getElementById('setting-character-maker-rag-data-install-btn');
            const state = String(data?.state || 'stopped');
            const installed = !!data?.installed;
            const loaded = !!data?.ready || state === 'running';
            cmRagRuntimeState = state;
            cmRagRuntimeLoaded = loaded;
            cmRagIndexInstalled = installed;

            if (status) {
                if (state === 'error') {
                    status.textContent = `내장 RAG 오류 · ${data?.error || '로그를 확인하세요.'}`;
                    status.className = 'cm-rag-runtime-state error';
                } else if (loaded) {
                    const rows = Number(data?.row_count || 0);
                    status.textContent = `내장 RAG 준비됨${rows ? ` · ${rows.toLocaleString()}태그` : ''}`;
                    status.className = 'cm-rag-runtime-state running';
                } else if (state === 'loading') {
                    status.textContent = '내장 RAG 로드 중… · 서버는 계속 응답합니다';
                    status.className = 'cm-rag-runtime-state starting';
                } else if (installed) {
                    status.textContent = '인덱스 설치됨 · 첫 검색 때 자동 로드';
                    status.className = 'cm-rag-runtime-state stopped';
                } else {
                    status.textContent = '인덱스 미설치 · 오른쪽에서 다운로드하세요.';
                    status.className = 'cm-rag-runtime-state stopped';
                }
            }
            const isLoading = state === 'loading';
            if (startButton) {
                startButton.disabled = !installed || loaded || cmRagDatasetBusy || isLoading;
            }
            if (stopButton) {
                stopButton.disabled = !loaded || cmRagDatasetBusy || isLoading;
            }
            // 로드 중에는 완료를 감지하도록 주기 재폴링(서버는 논블로킹이라 응답 가능).
            if (cmRagLoadingPollTimer) {
                clearTimeout(cmRagLoadingPollTimer);
                cmRagLoadingPollTimer = null;
            }
            if (isLoading) {
                cmRagLoadingPollTimer = setTimeout(() => {
                    cmRagLoadingPollTimer = null;
                    void cmRefreshRagRuntimeStatus(false);
                }, 2500);
            }
            if (installButton) {
                installButton.disabled = cmRagDatasetBusy || loaded;
            }
            cmApplyRagAutostartDisabledState(installed);
            cmRagVerified = loaded;
            if (cmSession) cmRenderStatus();
        }

        async function cmRefreshRagRuntimeStatus(showError = false) {
            try {
                const response = await fetch('/api/character_maker/rag/runtime', {
                    cache: 'no-store',
                });
                const data = await response.json().catch(error => {
                    console.error('[CHARACTER_MAKER_RAG] 상태 JSON 해석 실패:', error);
                    return {};
                });
                if (!response.ok || data.success === false || data.error) {
                    throw new Error(data.error || `HTTP ${response.status}`);
                }
                cmRenderRagRuntimeStatus(data);
                return data;
            } catch (error) {
                console.error('[CHARACTER_MAKER_RAG] 상태 확인 실패:', error);
                const status = document.getElementById('setting-character-maker-rag-runtime-state');
                if (status) {
                    status.textContent = `상태 확인 실패 · ${error.message || String(error)}`;
                    status.className = 'cm-rag-runtime-state error';
                }
                if (showError) {
                    showToast('내장 RAG 상태 확인 실패: ' + (error.message || error), 'error');
                }
                return null;
            }
        }

        async function cmStartRagRuntime() {
            const startButton = document.getElementById('setting-character-maker-rag-runtime-start');
            if (startButton) {
                startButton.disabled = true;
                startButton.textContent = '로드 중...';
            }
            try {
                const response = await fetch('/api/character_maker/rag/runtime/start', {
                    method: 'POST',
                });
                const data = await response.json().catch(error => {
                    console.error('[CHARACTER_MAKER_RAG] 로드 JSON 해석 실패:', error);
                    return {};
                });
                if (!response.ok || data.success === false || data.error) {
                    throw new Error(data.error || `HTTP ${response.status}`);
                }
                cmRenderRagRuntimeStatus(data);
                showToast('내장 Danbooru RAG를 메모리에 로드했습니다.', 'success');
            } catch (error) {
                console.error('[CHARACTER_MAKER_RAG] 로드 실패:', error);
                showToast('내장 RAG 로드 실패: ' + (error.message || error), 'error');
                await cmRefreshRagRuntimeStatus(false);
            } finally {
                if (startButton) startButton.textContent = '미리 로드';
            }
        }

        async function cmStopRagRuntime() {
            const stopButton = document.getElementById('setting-character-maker-rag-runtime-stop');
            if (stopButton) {
                stopButton.disabled = true;
                stopButton.textContent = '해제 중...';
            }
            try {
                const response = await fetch('/api/character_maker/rag/runtime/stop', {
                    method: 'POST',
                });
                const data = await response.json().catch(error => {
                    console.error('[CHARACTER_MAKER_RAG] 언로드 JSON 해석 실패:', error);
                    return {};
                });
                if (!response.ok || data.success === false || data.error) {
                    throw new Error(data.error || `HTTP ${response.status}`);
                }
                cmRenderRagRuntimeStatus(data);
                showToast('내장 Danbooru RAG 메모리를 해제했습니다.', 'success');
            } catch (error) {
                console.error('[CHARACTER_MAKER_RAG] 언로드 실패:', error);
                showToast('내장 RAG 메모리 해제 실패: ' + (error.message || error), 'error');
                await cmRefreshRagRuntimeStatus(false);
            } finally {
                if (stopButton) stopButton.textContent = '메모리 해제';
            }
        }

        async function testCharacterMakerRag() {
            const button = document.getElementById('setting-character-maker-rag-test-btn');
            const output = document.getElementById('setting-character-maker-rag-test-output');
            if (!button || !output) {
                console.error('[CHARACTER_MAKER_RAG] 설정 테스트 UI를 찾지 못했습니다.');
                return;
            }
            button.disabled = true;
            button.textContent = '테스트 중...';
            output.textContent = '내장 모델과 인덱스를 준비하고 직접 검색하는 중입니다...';
            try {
                const payload = {
                    top_k: Number(document.getElementById('setting-character-maker-rag-top-k')?.value || 5),
                    threshold: Number(document.getElementById('setting-character-maker-rag-threshold')?.value || 0),
                    timeout_sec: Number(document.getElementById('setting-character-maker-rag-timeout')?.value || 20),
                    query: document.getElementById('setting-character-maker-rag-query')?.value.trim() || '',
                };
                const response = await fetch('/api/character_maker/rag/test', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload),
                });
                const data = await response.json().catch(error => {
                    console.error('[CHARACTER_MAKER_RAG] 테스트 JSON 해석 실패:', error);
                    return {};
                });
                if (!response.ok || data.success === false || data.error) {
                    throw new Error(data.error || `HTTP ${response.status}`);
                }
                output.textContent = JSON.stringify(data, null, 2);
                cmRagVerified = true;
                if (cmSession) cmRenderStatus();
                await cmRefreshRagRuntimeStatus(false);
                showToast('내장 Danbooru Tag RAG 테스트에 성공했습니다.', 'success');
            } catch (error) {
                console.error('[CHARACTER_MAKER_RAG] 테스트 실패:', error);
                cmRagVerified = false;
                if (cmSession) cmRenderStatus();
                output.textContent = `테스트 실패\n${error.message || String(error)}`;
                showToast('내장 RAG 테스트 실패: ' + (error.message || error), 'error');
            } finally {
                button.disabled = false;
                button.textContent = '테스트';
            }
        }

        function handleCmRagInstallProgress(data) {
            const pct = Math.max(0, Math.min(100, Number(data?.progress || 0)));
            const phase = data?.phase || '';
            const detail = data?.detail || '';
            const wrap = document.getElementById('setting-character-maker-rag-data-progress');
            const fill = document.getElementById('setting-character-maker-rag-data-progress-fill');
            const text = document.getElementById('setting-character-maker-rag-data-progress-text');
            const state = document.getElementById('setting-character-maker-rag-data-state');
            if (wrap) wrap.style.display = 'flex';
            if (fill) fill.style.width = pct + '%';
            if (text) text.textContent = pct + '%';
            if (state) {
                state.textContent = detail
                    ? `${phase} · ${pct}% · ${detail}`
                    : `${phase} · ${pct}%`;
            }
        }

        async function cmRefreshRagArtifactStatus(showError = false) {
            const state = document.getElementById('setting-character-maker-rag-data-state');
            const result = document.getElementById('setting-character-maker-rag-data-result');
            try {
                const response = await fetch('/api/character_maker/rag/dataset', {
                    cache: 'no-store',
                });
                const data = await response.json().catch(error => {
                    console.error('[CHARACTER_MAKER_RAG] 인덱스 상태 JSON 해석 실패:', error);
                    return {};
                });
                if (!response.ok || data.success === false || data.error) {
                    throw new Error(data.error || `HTTP ${response.status}`);
                }
                const artifact = data.artifact || {};
                cmRagIndexInstalled = !!artifact.installed;
                if (state) {
                    state.textContent = artifact.installed
                        ? `설치됨 · ${artifact.artifact_version || '버전 미상'} · ${Number(artifact.row_count || 0).toLocaleString()}태그`
                        : '미설치 · Hugging Face에서 약 365MB를 다운로드합니다.';
                }
                if (artifact.installed) {
                    const version = document.getElementById('cm-rag-result-version');
                    const rows = document.getElementById('cm-rag-result-rows');
                    const size = document.getElementById('cm-rag-result-size');
                    if (version) version.textContent = artifact.artifact_version || '-';
                    if (rows) rows.textContent = Number(artifact.row_count || 0).toLocaleString();
                    if (size) size.textContent = cmFormatDatasetBytes(artifact.archive_size || 0);
                    result?.classList.add('visible');
                } else {
                    result?.classList.remove('visible');
                }
                cmApplyRagAutostartDisabledState(cmRagIndexInstalled);
                return data;
            } catch (error) {
                console.error('[CHARACTER_MAKER_RAG] 인덱스 상태 확인 실패:', error);
                if (state) state.textContent = `인덱스 상태 확인 실패 · ${error.message || error}`;
                if (showError) {
                    showToast('RAG 인덱스 상태 확인 실패: ' + (error.message || error), 'error');
                }
                return null;
            }
        }

        async function cmInstallRagDataset() {
            if (cmRagDatasetBusy) return;
            if (cmRagRuntimeLoaded) {
                showToast('먼저 내장 RAG 메모리를 해제하세요.', 'error');
                return;
            }
            const button = document.getElementById('setting-character-maker-rag-data-install-btn');
            const state = document.getElementById('setting-character-maker-rag-data-state');
            const result = document.getElementById('setting-character-maker-rag-data-result');
            cmRagDatasetBusy = true;
            if (button) {
                button.disabled = true;
                button.classList.add('is-busy');
                button.textContent = '설치 중...';
            }
            result?.classList.remove('visible');
            handleCmRagInstallProgress({phase: '시작', progress: 0, detail: 'Hugging Face 설치 시작'});

            try {
                const response = await fetch('/api/character_maker/rag/install', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: '{}',
                });
                const payload = await response.json().catch(error => {
                    console.error('[CHARACTER_MAKER_RAG] 설치 JSON 해석 실패:', error);
                    return {};
                });
                if (!response.ok || payload.success === false || payload.error) {
                    throw new Error(payload.error || `HTTP ${response.status}`);
                }
                const installed = payload.installed || {};
                const version = document.getElementById('cm-rag-result-version');
                const rows = document.getElementById('cm-rag-result-rows');
                const size = document.getElementById('cm-rag-result-size');
                if (version) version.textContent = installed.artifact_version || '-';
                if (rows) rows.textContent = Number(installed.row_count || 0).toLocaleString();
                if (size) size.textContent = cmFormatDatasetBytes(installed.archive_size || 0);
                result?.classList.add('visible');
                const progress = document.getElementById('setting-character-maker-rag-data-progress');
                if (progress) progress.style.display = 'none';
                if (state) {
                    state.textContent = `설치 완료 · ${installed.artifact_version || '버전 미상'} · 첫 검색 때 자동 로드`;
                }
                showToast('Hugging Face Danbooru RAG 인덱스 설치 완료', 'success');
            } catch (error) {
                console.error('[CHARACTER_MAKER_RAG] 설치 실패:', error);
                if (state) state.textContent = `설치 실패 · ${error.message || String(error)}`;
                showToast('RAG 인덱스 설치 실패: ' + (error.message || error), 'error');
            } finally {
                cmRagDatasetBusy = false;
                if (button) {
                    button.disabled = false;
                    button.classList.remove('is-busy');
                    button.textContent = '다운로드 및 설치';
                }
                await cmRefreshRagArtifactStatus(false);
                await cmRefreshRagRuntimeStatus(false);
            }
        }

