        function modalOperationLockActive() {
            const overlay = document.getElementById('modal-operation-lock-modal');
            return !!overlay && !overlay.hidden;
        }

        function modalRedeployChoiceActive() {
            const overlay = document.getElementById('modal-redeploy-choice-modal');
            return !!overlay && !overlay.hidden;
        }

        function modalLoraSyncActive() {
            const overlay = document.getElementById('modal-lora-sync-modal');
            return !!overlay && !overlay.hidden;
        }

        function modalTrapActionFocus(event) {
            const overlay = modalOperationLockActive()
                ? document.getElementById('modal-operation-lock-modal')
                : (modalRedeployChoiceActive()
                    ? document.getElementById('modal-redeploy-choice-modal')
                    : (modalLoraSyncActive()
                        ? document.getElementById('modal-lora-sync-modal')
                        : null));
            if (!overlay) return false;
            if (event.key === 'Escape') {
                if (overlay.id === 'modal-lora-sync-modal') modalCloseLoraSync();
                return true;
            }
            if (event.key !== 'Tab') return false;
            const focusable = Array.from(overlay.querySelectorAll(
                'button:not([disabled]):not([hidden]), input:not([disabled]):not([hidden])',
            )).filter(element => element.offsetParent !== null);
            event.preventDefault();
            if (!focusable.length) {
                overlay.querySelector('.modal-action-dialog')?.focus({preventScroll: true});
                return true;
            }
            const current = focusable.indexOf(document.activeElement);
            const direction = event.shiftKey ? -1 : 1;
            const next = current < 0
                ? (event.shiftKey ? focusable.length - 1 : 0)
                : (current + direction + focusable.length) % focusable.length;
            focusable[next].focus({preventScroll: true});
            return true;
        }

        function modalLockSettingsInteraction(locked) {
            const settings = document.getElementById('settings-modal');
            if (!settings) {
                console.error('[MODAL_RUNTIME] 설정 모달 요소가 없어 상호작용 잠금을 적용할 수 없습니다.');
                return;
            }
            if (locked) settings.setAttribute('inert', '');
            else if (!modalOperationLockActive() && !modalRedeployChoiceActive() && !modalLoraSyncActive()) {
                settings.removeAttribute('inert');
            }
        }

        function modalLoraStateMeta(state, item = null) {
            const states = {
                unchecked: {label: '조회 필요', detail: '상태 조회를 실행하면 원격과 비교합니다.'},
                synced: {label: '동기화 완료', detail: '현재 사용본과 원격 파일이 같습니다.'},
                update: {label: '업데이트 필요', detail: '누락·변경 또는 원격 잔여 파일이 있습니다.'},
                local_only: {label: '로컬만', detail: '현재 사용본이 원격에 없습니다.'},
                remote_only: {label: '원격만', detail: '로컬 현재 사용본에서 찾을 수 없는 원격 항목입니다.'},
            };
            const meta = states[String(state || '')] || states.unchecked;
            if (state !== 'update' || !item) return meta;
            const parts = [];
            if (Number(item.missing_count || 0)) parts.push(`누락 ${Number(item.missing_count)}개`);
            if (Number(item.different_count || 0)) parts.push(`변경 ${Number(item.different_count)}개`);
            if (Number(item.extra_count || 0)) parts.push(`원격 잔여 ${Number(item.extra_count)}개`);
            return {...meta, detail: parts.length ? parts.join(' · ') : meta.detail};
        }

        function modalLoraItemByKey(key) {
            return modalLoraCatalog.find(item => String(item.key) === String(key));
        }

        function modalLoraOperationRunning() {
            return String(modalLoraOperationState?.state || '') === 'running';
        }

        function modalLoraVisibleItems() {
            const query = (document.getElementById('modal-lora-search')?.value || '').trim().toLowerCase();
            return modalLoraCatalog.filter(item => {
                if (String(item.category) !== modalLoraActiveCategory) return false;
                if (modalLoraStateFilter !== 'all' && String(item.sync_state) !== modalLoraStateFilter) return false;
                if (!query) return true;
                return [item.display_name, item.display_subtitle, item.name, item.subtitle, item.detail]
                    .some(value => String(value || '').toLowerCase().includes(query));
            });
        }

        function modalLoraUpdateSummary() {
            const states = ['all', 'synced', 'update', 'local_only', 'remote_only'];
            const counts = {all: modalLoraCatalog.length, synced: 0, update: 0, local_only: 0, remote_only: 0};
            if (modalLoraRemoteLoaded) {
                modalLoraCatalog.forEach(item => {
                    const state = String(item.sync_state || '');
                    if (Object.prototype.hasOwnProperty.call(counts, state)) counts[state] += 1;
                });
            }
            if (modalLoraStateFilter !== 'all' && !modalLoraRemoteLoaded) modalLoraStateFilter = 'all';
            states.forEach(state => {
                const count = document.getElementById(`modal-lora-count-${state}`);
                if (count) count.textContent = String(counts[state]);
            });
            document.querySelectorAll('#modal-lora-summary [data-lora-state]').forEach(button => {
                const active = button.dataset.loraState === modalLoraStateFilter;
                button.classList.toggle('active', active);
                button.setAttribute('aria-pressed', active ? 'true' : 'false');
            });
            for (const category of ['bot', 'asset', 'instance', 'style']) {
                const count = modalLoraCatalog.filter(item => String(item.category) === category).length;
                const element = document.getElementById(`modal-lora-tab-count-${category}`);
                if (element) element.textContent = String(count);
            }
        }

        function modalLoraUpdateControls() {
            const selected = Array.from(modalLoraSelectedKeys)
                .map(modalLoraItemByKey)
                .filter(Boolean);
            const busy = modalLoraOperationRunning();
            const actionBusy = busy || modalLoraStatusQueryPending;
            const hasSelection = selected.length > 0;
            const everyLocal = hasSelection && selected.every(item => Number(item.file_count || 0) > 0);
            const everyChecked = hasSelection && selected.every(
                item => String(item.sync_state || 'unchecked') !== 'unchecked',
            );
            const anyRemote = selected.some(item => Number(item.remote_file_count || 0) > 0);
            const upload = document.getElementById('modal-lora-upload-btn');
            const sync = document.getElementById('modal-lora-sync-btn');
            const remove = document.getElementById('modal-lora-delete-btn');
            if (upload) upload.disabled = actionBusy || !everyLocal;
            if (sync) sync.disabled = actionBusy || !everyLocal;
            if (remove) remove.disabled = actionBusy || !everyChecked || !anyRemote;
            const statusButton = document.getElementById('modal-lora-status-query-btn');
            if (statusButton) {
                statusButton.disabled = modalLoraCatalogLoading || modalLoraStatusQueryPending || busy;
                statusButton.textContent = modalLoraStatusQueryPending
                    ? `↻ ${modalLoraStatusQueryCount ? `선택 ${modalLoraStatusQueryCount}개` : '전체'} 조회 중...`
                    : (hasSelection ? `↻ 선택 ${selected.length}개 상태 조회` : '↻ 전체 상태 조회');
            }
            const fileCount = selected.reduce((sum, item) => sum + Number(item.file_count || 0), 0);
            const bytes = selected.reduce((sum, item) => sum + Number(item.size_bytes || 0), 0);
            const botCount = selected.filter(item => item.category === 'bot').length;
            const note = document.getElementById('modal-lora-selection-note');
            if (note) {
                note.textContent = hasSelection
                    ? `${selected.length}개 항목${botCount ? ` · 봇 ${botCount}개 전체 단위` : ''} · 현재 사용 파일 ${fileCount}개 · ${comfyInstallerFormatBytes(bytes)}`
                    : (modalLoraIsVast()
                        ? '선택 없음 · 경로·용량이 같은 원격 파일은 업로드에서 건너뜁니다.'
                        : '선택 없음 · 원격 삭제는 로컬 파일을 건드리지 않습니다.');
            }
        }

        function modalRenderLoraCatalog() {
            const container = document.getElementById('modal-lora-catalog');
            if (!container) return;
            modalLoraUpdateSummary();
            const visible = modalLoraVisibleItems();
            container.replaceChildren();
            if (!visible.length) {
                const empty = document.createElement('div');
                empty.className = 'modal-lora-empty';
                empty.textContent = modalLoraCatalogLoading
                    ? '로컬 현재 사용본을 불러오는 중입니다.'
                    : (modalLoraCatalog.length
                        ? '현재 탭·검색·상태 조건에 맞는 LoRA가 없습니다.'
                        : '현재 사용할 수 있는 LoRA가 없습니다. 전체 상태 조회로 원격에만 있는 항목을 확인할 수 있습니다.');
                container.append(empty);
            }
            const busy = modalLoraOperationRunning();
            const actionBusy = busy || modalLoraStatusQueryPending;
            for (const item of visible) {
                const row = document.createElement('div');
                const state = String(item.sync_state || 'unchecked');
                const itemRemoteChecked = state !== 'unchecked';
                row.className = `modal-lora-item state-${state}`;
                if (modalLoraSelectedKeys.has(item.key)) row.classList.add('selected');

                const checkbox = document.createElement('input');
                checkbox.type = 'checkbox';
                checkbox.className = 'modal-lora-check';
                checkbox.checked = modalLoraSelectedKeys.has(item.key);
                checkbox.disabled = busy;
                const displayName = item.display_name || item.name || '이름 없음';
                const displaySubtitle = item.display_subtitle || item.subtitle || '';
                checkbox.setAttribute('aria-label', `${displayName} 선택`);
                checkbox.addEventListener('change', () => {
                    if (checkbox.checked) modalLoraSelectedKeys.add(item.key);
                    else modalLoraSelectedKeys.delete(item.key);
                    modalRenderLoraCatalog();
                });

                const copy = document.createElement('div');
                copy.className = 'modal-lora-item-copy';
                copy.addEventListener('click', event => {
                    if (busy || event.target.closest('button,input')) return;
                    if (modalLoraSelectedKeys.has(item.key)) modalLoraSelectedKeys.delete(item.key);
                    else modalLoraSelectedKeys.add(item.key);
                    modalRenderLoraCatalog();
                });
                const main = document.createElement('div');
                main.className = 'modal-lora-item-main';
                const name = document.createElement('strong');
                name.textContent = displayName;
                main.append(name);
                if (item.category === 'bot') {
                    const unit = document.createElement('span');
                    unit.className = 'modal-lora-unit-badge';
                    unit.textContent = '봇 전체';
                    main.append(unit);
                }
                const meta = modalLoraStateMeta(state, item);
                const badge = document.createElement('span');
                badge.className = 'modal-lora-state';
                badge.textContent = meta.label;
                badge.title = meta.detail;
                main.append(badge);
                const detail = document.createElement('div');
                detail.className = 'modal-lora-item-meta';
                const details = [
                    displaySubtitle,
                    `로컬 ${Number(item.file_count || 0)}개 · ${comfyInstallerFormatBytes(Number(item.size_bytes || 0))}`,
                ];
                if (itemRemoteChecked) details.push(`원격 ${Number(item.remote_file_count || 0)}개 · ${comfyInstallerFormatBytes(Number(item.remote_size_bytes || 0))}`);
                if (state === 'update') details.push(meta.detail);
                if (item.detail) details.push(item.detail);
                details.filter(Boolean).forEach(text => {
                    const span = document.createElement('span');
                    span.textContent = String(text);
                    detail.append(span);
                });
                copy.append(main, detail);

                const actions = document.createElement('div');
                actions.className = 'modal-lora-row-actions';
                const hasLocal = Number(item.file_count || 0) > 0;
                const hasRemote = itemRemoteChecked && Number(item.remote_file_count || 0) > 0;
                for (const [action, label] of [['upload', '업로드'], ['sync', '동기화'], ['delete', '원격 삭제']]) {
                    const button = document.createElement('button');
                    button.type = 'button';
                    button.textContent = label;
                    if (action === 'delete') button.classList.add('danger');
                    button.disabled = actionBusy || (action === 'delete' ? !hasRemote : !hasLocal);
                    button.addEventListener('click', event => {
                        event.stopPropagation();
                        void modalLoraRunAction(action, [item.key]);
                    });
                    actions.append(button);
                }
                row.append(checkbox, copy, actions);
                container.append(row);
            }
            modalLoraUpdateControls();
        }

        function modalLoraSetCategory(category) {
            if (!['bot', 'asset', 'instance', 'style'].includes(category)) {
                console.error('[MODAL_LORA] 알 수 없는 카테고리:', category);
                return;
            }
            modalLoraActiveCategory = category;
            document.querySelectorAll('#modal-lora-sync-modal [data-lora-category]').forEach(button => {
                const active = button.dataset.loraCategory === category;
                button.classList.toggle('active', active);
                button.setAttribute('aria-selected', active ? 'true' : 'false');
            });
            modalRenderLoraCatalog();
        }

        function modalLoraSetStateFilter(state) {
            if (!['all', 'synced', 'update', 'local_only', 'remote_only'].includes(state)) {
                console.error('[MODAL_LORA] 알 수 없는 상태 필터:', state);
                return;
            }
            if (state !== 'all' && !modalLoraRemoteLoaded) {
                showToast('먼저 Modal LoRA 상태를 조회하세요', 'warning');
                return;
            }
            modalLoraStateFilter = state;
            modalRenderLoraCatalog();
        }

        function modalLoraSelectVisible() {
            if (modalLoraOperationRunning()) return;
            modalLoraVisibleItems().forEach(item => modalLoraSelectedKeys.add(item.key));
            modalRenderLoraCatalog();
        }

        function modalLoraClearSelection() {
            if (modalLoraOperationRunning()) return;
            modalLoraSelectedKeys.clear();
            modalRenderLoraCatalog();
        }

        async function modalLoraLoadCatalog() {
            const note = document.getElementById('modal-lora-query-note');
            modalLoraCatalogLoading = true;
            modalLoraCatalog = [];
            modalLoraRemoteLoaded = false;
            modalLoraCheckedAt = '';
            modalLoraStateFilter = 'all';
            if (note) note.textContent = '로컬 현재 사용본을 확인하고 있습니다.';
            modalRenderLoraCatalog();
            let loaded = false;
            try {
                const data = await fetchJSON(modalLoraApi(''));
                modalLoraCatalog = Array.isArray(data.items) ? data.items : [];
                const present = new Set(modalLoraCatalog.map(item => item.key));
                for (const key of Array.from(modalLoraSelectedKeys)) {
                    if (!present.has(key)) modalLoraSelectedKeys.delete(key);
                }
                const errors = Array.isArray(data.errors) ? data.errors : [];
                if (errors.length) console.error('[MODAL_LORA] 일부 로컬 카탈로그 실패:', errors);
                if (note) note.textContent = `현재 사용본 ${modalLoraCatalog.length}개 항목 · 항목을 선택하면 선택 조회, 선택하지 않으면 전체 조회합니다.`;
                loaded = true;
            } catch (error) {
                console.error('[MODAL_LORA] 로컬 카탈로그 조회 실패:', error);
                if (note) note.textContent = '로컬 목록 조회 실패: ' + (error.message || error);
                const container = document.getElementById('modal-lora-catalog');
                if (container) container.innerHTML = '<div class="modal-lora-empty">LoRA 목록을 불러오지 못했습니다. 서버 로그를 확인하세요.</div>';
            } finally {
                modalLoraCatalogLoading = false;
                if (loaded) modalRenderLoraCatalog();
                else modalLoraUpdateControls();
            }
        }

        async function modalLoraQueryStatus() {
            if (modalLoraCatalogLoading || modalLoraStatusQueryPending || modalLoraOperationRunning()) return;
            const note = document.getElementById('modal-lora-query-note');
            const requestedKeys = Array.from(modalLoraSelectedKeys)
                .map(key => String(key || '').trim())
                .filter(Boolean);
            const uniqueKeys = Array.from(new Set(requestedKeys));
            const partial = uniqueKeys.length > 0;
            const params = new URLSearchParams({remote: '1'});
            uniqueKeys.forEach(key => params.append('item_key', key));
            modalLoraStatusQueryPending = true;
            modalLoraStatusQueryCount = uniqueKeys.length;
            modalLoraUpdateControls();
            if (note) {
                const compareText = modalLoraIsVast()
                    ? 'Vast 인스턴스 실제 파일과 경로·용량 기준으로 비교하고 있습니다'
                    : 'SHA-256과 Modal Volume 명세를 비교하고 있습니다';
                note.textContent = partial
                    ? `선택한 ${uniqueKeys.length}개 LoRA의 ${compareText}. 목록 선택은 계속 변경할 수 있습니다.`
                    : `전체 LoRA의 ${compareText}. 목록 선택은 계속 변경할 수 있습니다.`;
            }
            try {
                const data = await fetchJSON(`${modalLoraApi('')}?${params.toString()}`);
                const queriedItems = Array.isArray(data.items) ? data.items : [];
                if (partial) {
                    const queriedByKey = new Map(queriedItems.map(item => [String(item.key), item]));
                    modalLoraCatalog = modalLoraCatalog.map(item => queriedByKey.get(String(item.key)) || item);
                    for (const item of queriedItems) {
                        if (!modalLoraItemByKey(item.key)) modalLoraCatalog.push(item);
                    }
                } else {
                    modalLoraCatalog = queriedItems;
                    const present = new Set(modalLoraCatalog.map(item => item.key));
                    for (const key of Array.from(modalLoraSelectedKeys)) {
                        if (!present.has(key)) modalLoraSelectedKeys.delete(key);
                    }
                }
                modalLoraRemoteLoaded = modalLoraCatalog.some(
                    item => String(item.sync_state || 'unchecked') !== 'unchecked',
                );
                modalLoraCheckedAt = String(data.checked_at || '');
                const checked = modalLoraCheckedAt
                    ? new Date(modalLoraCheckedAt).toLocaleTimeString('ko-KR', {hour12: false})
                    : '방금';
                const counts = data.counts || {};
                if (note) note.textContent = `${checked} ${partial ? `선택 ${uniqueKeys.length}개` : '전체'} 조회 · 완료 ${Number(counts.synced || 0)} · 업데이트 ${Number(counts.update || 0)} · 로컬만 ${Number(counts.local_only || 0)} · 원격만 ${Number(counts.remote_only || 0)}`;
                const remoteErrors = Array.isArray(data.remote_errors) ? data.remote_errors : [];
                if (remoteErrors.length) console.error('[MODAL_LORA] 원격 명세 경고:', remoteErrors);
                modalRenderLoraCatalog();
                showToast(`${modalLoraTargetLabel()} LoRA ${partial ? `선택 ${uniqueKeys.length}개` : '전체'} 상태를 조회했습니다`, 'success');
            } catch (error) {
                console.error('[MODAL_LORA] 원격 상태 조회 실패:', error);
                if (note) note.textContent = '원격 상태 조회 실패: ' + (error.message || error);
                showToast(`${modalLoraTargetLabel()} LoRA 상태 조회 실패: ` + (error.message || error), 'error');
            } finally {
                modalLoraStatusQueryPending = false;
                modalLoraStatusQueryCount = 0;
                modalLoraUpdateControls();
            }
        }

        function modalRenderLoraOperation(operation) {
            modalLoraOperationState = operation && typeof operation === 'object' ? operation : {state: 'idle'};
            const panel = document.getElementById('modal-lora-operation');
            if (!panel) return;
            const state = String(modalLoraOperationState.state || 'idle');
            panel.hidden = state === 'idle';
            if (panel.hidden) {
                modalRenderLoraCatalog();
                return;
            }
            const progress = modalLoraOperationState.progress || {};
            const totalFiles = Number(progress.total_files || 0);
            const completedFiles = Number(progress.completed_files || 0);
            let percent = totalFiles > 0 ? completedFiles / totalFiles * 100 : 0;
            if (state === 'running' && percent <= 0) percent = 8;
            if (state === 'completed') percent = 100;
            const title = document.getElementById('modal-lora-operation-title');
            const count = document.getElementById('modal-lora-operation-count');
            const fill = document.getElementById('modal-lora-operation-fill');
            const track = panel.querySelector('[role="progressbar"]');
            const log = document.getElementById('modal-lora-operation-log');
            if (title) title.textContent = modalLoraOperationState.message || 'LoRA 작업 진행 중';
            if (count) count.textContent = totalFiles
                ? `${completedFiles} / ${totalFiles} · ${comfyInstallerFormatBytes(Number(progress.completed_bytes || 0))} / ${comfyInstallerFormatBytes(Number(progress.total_bytes || 0))}`
                : `${modalLoraOperationState.action_label || '원격 작업'} · 경과 ${modalFormatInstallDuration(Number(modalLoraOperationState.elapsed_seconds || 0))}`;
            if (fill) fill.style.width = `${Math.max(0, Math.min(100, percent))}%`;
            if (track) track.setAttribute('aria-valuenow', String(Math.round(percent)));
            if (log) {
                const logs = Array.isArray(modalLoraOperationState.logs) ? modalLoraOperationState.logs : [];
                log.textContent = logs.length
                    ? logs.slice(-8).map(entry => `[${String(entry.source || 'system').toUpperCase()}] ${String(entry.message || '')}`).join('\n')
                    : '작업 로그를 기다리고 있습니다.';
                log.scrollTop = log.scrollHeight;
            }
            modalRenderLoraCatalog();
        }

        function modalLoraScheduleOperationPoll(delay = 900) {
            if (modalLoraOperationPollTimer !== null) window.clearTimeout(modalLoraOperationPollTimer);
            if (!modalLoraOperationRunning()) return;
            modalLoraOperationPollTimer = window.setTimeout(() => void modalLoraPollOperation(), delay);
        }

        async function modalLoraPollOperation() {
            try {
                const data = await fetchJSON(modalLoraApi('/operation'));
                const operation = data.operation || {state: 'idle'};
                const wasRunning = modalLoraOperationRunning() || modalLoraOperationWasRunning;
                modalRenderLoraOperation(operation);
                if (operation.state === 'running') {
                    modalLoraOperationWasRunning = true;
                    modalLoraScheduleOperationPoll();
                    return;
                }
                if (wasRunning) {
                    modalLoraOperationWasRunning = false;
                    showToast(
                        operation.state === 'completed' ? (operation.message || 'LoRA 작업 완료') : (operation.message || 'LoRA 작업 실패'),
                        operation.state === 'completed' ? 'success' : 'error',
                    );
                    if (operation.state === 'completed') void modalLoraLoadCatalog();
                }
            } catch (error) {
                console.error('[MODAL_LORA] 작업 상태 조회 실패:', error);
                modalLoraScheduleOperationPoll(1600);
            }
        }

        async function modalLoraRunAction(action, explicitKeys = null) {
            if (modalLoraOperationRunning()) return;
            if (modalLoraStatusQueryPending) {
                showToast('상태 조회가 끝난 뒤 LoRA 작업을 시작하세요', 'warning');
                return;
            }
            const keys = Array.isArray(explicitKeys) ? explicitKeys : Array.from(modalLoraSelectedKeys);
            const items = keys.map(modalLoraItemByKey).filter(Boolean);
            if (!items.length) {
                showToast('관리할 LoRA 항목을 선택하세요', 'warning');
                return;
            }
            if ((action === 'upload' || action === 'sync') && items.some(item => !Number(item.file_count || 0))) {
                showToast('원격에만 있는 항목은 업로드하거나 동기화할 수 없습니다', 'warning');
                return;
            }
            if (modalLoraIsVast() && action !== 'upload') {
                showToast('VAST 빌드 후에는 업로드만 지원합니다', 'warning');
                return;
            }
            if (action === 'delete' && items.some(item => String(item.sync_state || 'unchecked') === 'unchecked')) {
                showToast('원격 삭제 전에 선택 항목의 상태를 먼저 조회하세요', 'warning');
                return;
            }
            if (action === 'delete' && !items.some(item => Number(item.remote_file_count || 0) > 0)) {
                showToast('선택 항목에 삭제할 원격 LoRA가 없습니다', 'warning');
                return;
            }
            const botCount = items.filter(item => item.category === 'bot').length;
            const labels = {upload: '업로드', sync: '동기화', delete: '원격 삭제'};
            let question = `선택한 ${items.length}개 항목을 ${labels[action]}할까요?`;
            if (action === 'upload') question += modalLoraIsVast()
                ? '\n\n경로·용량이 같은 원격 파일은 건너뛰고, 나머지만 Vast 인스턴스로 올립니다. ComfyUI는 재시작 없이 자동 인식합니다.'
                : '\n\n현재 사용본만 추가·갱신하고 원격 잔여 파일은 유지합니다.';
            if (action === 'sync') question += `\n\n업로드 성공 후 현재 구성에서 빠진 원격 파일을 정리합니다.${botCount ? ` 봇 ${botCount}개는 각 봇 전체 구성을 기준으로 처리합니다.` : ''}`;
            if (action === 'delete') question += '\n\n원격 Volume에서만 삭제하며 로컬 파일은 그대로 유지합니다.';
            if (!window.confirm(question)) return;
            try {
                modalLoraOperationWasRunning = true;
                modalLoraOperationState = {state: 'running', action, action_label: labels[action], message: `LoRA ${labels[action]} 요청을 준비하고 있습니다.`, progress: {total_files: 0}, logs: []};
                modalRenderLoraOperation(modalLoraOperationState);
                const data = await fetchJSON(modalLoraApi('/operation'), {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({action, item_keys: keys}),
                });
                modalRenderLoraOperation(data.operation || modalLoraOperationState);
                modalLoraScheduleOperationPoll(400);
            } catch (error) {
                modalLoraOperationWasRunning = false;
                modalLoraOperationState = {state: 'failed', action, action_label: labels[action], message: `LoRA ${labels[action]} 시작 실패: ${error.message || error}`, logs: []};
                modalRenderLoraOperation(modalLoraOperationState);
                console.error(`[MODAL_LORA] ${labels[action]} 시작 실패:`, error);
                showToast(`LoRA ${labels[action]} 시작 실패: ` + (error.message || error), 'error');
            }
        }

        async function modalOpenLoraSync(target = 'modal') {
            modalLoraTarget = target === 'vast' ? 'vast' : 'modal';
            if (modalLoraIsVast()) {
                const launch = window.__vastLastLaunch || {};
                if (launch.state !== 'ready') {
                    modalLoraTarget = 'modal';
                    showToast('VAST 인스턴스가 준비 완료 상태일 때 LoRA 동기화를 사용할 수 있습니다', 'warning');
                    return;
                }
            } else if (modalOperationLockActive() || modalRedeployChoiceActive()) {
                showToast('현재 Modal 작업이 끝난 뒤 LoRA 동기화를 열어주세요', 'warning');
                return;
            }
            const overlay = document.getElementById('modal-lora-sync-modal');
            if (!overlay) {
                console.error('[MODAL_LORA] 동기화 모달 요소가 없습니다.');
                return;
            }
            overlay.hidden = false;
            if (!modalLoraIsVast()) modalLockSettingsInteraction(true);
            modalLoraApplyTargetChrome();
            modalLoraSelectedKeys.clear();
            modalLoraStateFilter = 'all';
            modalLoraSetCategory('bot');
            overlay.querySelector('.modal-action-dialog')?.focus({preventScroll: true});
            await modalLoraLoadCatalog();
            try {
                const data = await fetchJSON(modalLoraApi('/operation'));
                modalRenderLoraOperation(data.operation || {state: 'idle'});
                if (data.operation?.state === 'running') {
                    modalLoraOperationWasRunning = true;
                    modalLoraScheduleOperationPoll();
                }
            } catch (error) {
                console.error('[MODAL_LORA] 기존 작업 상태 확인 실패:', error);
            }
        }

        function modalCloseLoraSync() {
            if (modalLoraOperationRunning()) {
                showToast('LoRA 작업이 끝난 뒤 창을 닫을 수 있습니다', 'warning');
                return;
            }
            const overlay = document.getElementById('modal-lora-sync-modal');
            if (overlay) overlay.hidden = true;
            if (modalLoraOperationPollTimer !== null) {
                window.clearTimeout(modalLoraOperationPollTimer);
                modalLoraOperationPollTimer = null;
            }
            if (!modalLoraIsVast()) modalLockSettingsInteraction(false);
            document.getElementById(modalLoraIsVast() ? 'vast-lora-sync-open-btn' : 'modal-lora-sync-open-btn')?.focus({preventScroll: true});
        }

        function modalShowOperationLock(kind, title, message) {
            const overlay = document.getElementById('modal-operation-lock-modal');
            if (!overlay) {
                console.error('[MODAL_RUNTIME] 작업 차단 모달 요소가 없습니다.');
                return;
            }
            const wasHidden = overlay.hidden;
            modalOperationLockKind = kind;
            overlay.hidden = false;
            modalLockSettingsInteraction(true);
            const titleElement = document.getElementById('modal-operation-lock-title');
            const messageElement = document.getElementById('modal-operation-lock-message');
            if (titleElement) titleElement.textContent = title;
            if (messageElement) messageElement.textContent = message;
            if (wasHidden) overlay.querySelector('.modal-action-dialog')?.focus({preventScroll: true});
        }

        function modalHideOperationLock() {
            const overlay = document.getElementById('modal-operation-lock-modal');
            if (overlay) overlay.hidden = true;
            modalOperationLockKind = '';
            const cancelButton = document.getElementById('modal-operation-cancel-web-btn');
            if (cancelButton) cancelButton.hidden = true;
            if (!modalRedeployChoiceActive()) modalLockSettingsInteraction(false);
        }

        function modalUpdateOperationProgress(percent, meta, logText) {
            const normalized = Math.max(0, Math.min(100, Number(percent) || 0));
            const track = document.getElementById('modal-operation-lock-track');
            const fill = document.getElementById('modal-operation-lock-fill');
            const metaElement = document.getElementById('modal-operation-lock-meta');
            const logElement = document.getElementById('modal-operation-lock-log');
            if (track) track.setAttribute('aria-valuenow', String(Math.round(normalized)));
            if (fill) fill.style.width = `${normalized}%`;
            if (metaElement) metaElement.textContent = meta || '진행 상태를 확인하고 있습니다.';
            if (logElement) logElement.textContent = logText || '최신 로그를 기다리고 있습니다.';
        }

        function modalSyncOperationLock(data) {
            const deployment = data?.deployment || {};
            const deploymentRunning = deployment.state === 'running';
            if (modalDeploymentRequestPending || deploymentRunning) {
                const kind = String(deployment.kind || modalDeploymentPendingKind || 'redeploy');
                const customNodes = kind === 'custom_nodes';
                const phase = String(deployment.phase || 'inventory');
                const percentByPhase = {inventory: 10, worker: 40, web: 70, shutdown: 90, complete: 100};
                const logs = Array.isArray(deployment.logs) ? deployment.logs : [];
                const logText = logs.slice(-8).map(entry => {
                    const source = String(entry?.source || 'system').toUpperCase();
                    return `[${source}] ${String(entry?.message || '')}`;
                }).join('\n');
                modalShowOperationLock(
                    'deployment',
                    customNodes ? 'Custom Node 포함 재배포 중' : '기본 앱 재배포 중',
                    String(deployment.message || (
                        customNodes
                            ? 'Custom Node 인벤토리와 이미지 빌드를 준비하고 있습니다.'
                            : 'Modal 작업 App과 웹 App 재배포를 준비하고 있습니다.'
                    )),
                );
                modalUpdateOperationProgress(
                    percentByPhase[phase] || 10,
                    `${customNodes ? 'Custom Node 포함 재배포' : '기본 앱 재배포'} · ${phase} · 경과 ${modalFormatInstallDuration(Number(deployment.elapsed_seconds || 0))}`,
                    logText,
                );
                return;
            }
            if (modalOperationLockKind === 'deployment') {
                modalHideOperationLock();
            }

            if (!data?.web || typeof data.web !== 'object') return;
            const web = data.web;
            const webState = String(web.state || 'stopped');
            const lockingWebStart = modalWebStartRequestPending
                || webState === 'starting'
                || (modalOperationLockKind === 'web_start' && webState === 'stopping');
            if (lockingWebStart) {
                const stopping = webState === 'stopping';
                modalShowOperationLock(
                    'web_start',
                    stopping ? 'Modal ComfyUI 시작 취소 처리 중' : 'Modal ComfyUI 시작 중',
                    String(web.message || (
                        stopping
                            ? '웹 App과 GPU를 안전하게 종료하고 있습니다.'
                            : '웹 App을 선택 GPU로 재배포하고 ComfyUI 준비를 기다리고 있습니다. GPU 아키텍처는 공통 이미지에 포함되어 있습니다.'
                    )),
                );
                const webLogs = modalRuntimeLogEntries
                    .filter(entry => String(entry?.category || '') === 'web')
                    .slice(-8)
                    .map(entry => `[${String(entry?.source || 'web').toUpperCase()}] ${String(entry?.message || '')}`)
                    .join('\n');
                modalUpdateOperationProgress(
                    stopping ? 88 : (modalWebStartRequestPending ? 12 : 58),
                    stopping ? '시작 취소 후 종료 중' : 'Modal WebUI 준비 상태 확인 중',
                    webLogs || String(web.message || ''),
                );
                const cancelButton = document.getElementById('modal-operation-cancel-web-btn');
                if (cancelButton) cancelButton.hidden = stopping || modalWebStartRequestPending;
                return;
            }
            if (modalOperationLockKind === 'web_start') {
                modalHideOperationLock();
            }
        }

        function modalOpenRedeployChoice() {
            if (modalDeploymentRequestPending || modalOperationLockActive()) return;
            const overlay = document.getElementById('modal-redeploy-choice-modal');
            if (!overlay) {
                console.error('[MODAL_RUNTIME] 재배포 선택 모달 요소가 없습니다.');
                showToast('재배포 선택 화면을 열 수 없습니다', 'error');
                return;
            }
            const basic = overlay.querySelector('input[name="modal-redeploy-kind"][value="redeploy"]');
            if (basic) basic.checked = true;
            modalRedeployInventoryState = 'idle';
            modalRedeployInventoryText = '';
            modalRedeployPreviewRequestId += 1;
            overlay.hidden = false;
            modalLockSettingsInteraction(true);
            modalRedeployChoiceChanged();
            overlay.querySelector('input[name="modal-redeploy-kind"]:checked')?.focus({preventScroll: true});
        }

        function modalCloseRedeployChoice() {
            if (modalDeploymentRequestPending) return;
            const overlay = document.getElementById('modal-redeploy-choice-modal');
            if (overlay) overlay.hidden = true;
            modalRedeployPreviewRequestId += 1;
            if (!modalOperationLockActive()) modalLockSettingsInteraction(false);
        }

        async function modalLoadRedeployCustomNodePreview() {
            if (modalRedeployInventoryState === 'loading') return;
            const requestId = ++modalRedeployPreviewRequestId;
            modalRedeployInventoryState = 'loading';
            const preview = document.getElementById('modal-redeploy-custom-preview');
            if (preview) preview.textContent = 'Custom Node 인벤토리를 확인하고 있습니다…';
            modalRedeployChoiceChanged();
            try {
                const data = await fetchJSON('/api/modal/custom-nodes');
                if (requestId !== modalRedeployPreviewRequestId) return;
                modalRedeployInventoryText = modalRuntimeCustomNodeInventoryText(data.custom_nodes || {});
                modalRedeployInventoryState = 'loaded';
                if (preview) preview.textContent = modalRedeployInventoryText;
            } catch (error) {
                if (requestId !== modalRedeployPreviewRequestId) return;
                console.error('[MODAL_RUNTIME] custom node 인벤토리 확인 실패:', error);
                modalRedeployInventoryState = 'failed';
                modalRedeployInventoryText = 'Custom Node 인벤토리 확인 실패: ' + (error.message || error);
                if (preview) preview.textContent = modalRedeployInventoryText;
                showToast(modalRedeployInventoryText, 'error');
            } finally {
                if (requestId === modalRedeployPreviewRequestId) modalRedeployChoiceChanged();
            }
        }

        function modalRedeployChoiceChanged() {
            const selected = document.querySelector('input[name="modal-redeploy-kind"]:checked')?.value || 'redeploy';
            const customNodes = selected === 'custom_nodes';
            const previewWrap = document.getElementById('modal-redeploy-custom-preview-wrap');
            const confirmButton = document.getElementById('modal-redeploy-confirm-btn');
            if (previewWrap) previewWrap.hidden = !customNodes;
            if (confirmButton) {
                confirmButton.textContent = customNodes
                    ? (modalRedeployInventoryState === 'failed'
                        ? 'Custom Node 인벤토리 다시 확인'
                        : 'Custom Node 포함 재배포 시작')
                    : '기본 앱 재배포 시작';
                confirmButton.disabled = customNodes && modalRedeployInventoryState === 'loading';
            }
            if (customNodes && modalRedeployInventoryState === 'idle') {
                void modalLoadRedeployCustomNodePreview();
            }
        }

        function modalConfirmRedeployChoice() {
            const kind = document.querySelector('input[name="modal-redeploy-kind"]:checked')?.value || 'redeploy';
            if (kind === 'custom_nodes' && modalRedeployInventoryState !== 'loaded') {
                if (modalRedeployInventoryState === 'failed') {
                    void modalLoadRedeployCustomNodePreview();
                    return;
                }
                console.error('[MODAL_RUNTIME] custom node 인벤토리 확인 전 재배포 시작을 거부합니다.');
                showToast('Custom Node 인벤토리 확인이 끝날 때까지 기다리세요', 'warning');
                return;
            }
            const overlay = document.getElementById('modal-redeploy-choice-modal');
            if (overlay) overlay.hidden = true;
            void modalStartRedeploy(kind);
        }

        window.addEventListener('beforeunload', event => {
            if (!modalOperationLockActive()) return;
            event.preventDefault();
            event.returnValue = '';
        });

        function updateModalEnabledStatus(checked) {
            const status = document.getElementById('setting-modal-enabled-status');
            if (!status) {
                console.error('[MODAL] 사용 상태 요소가 없습니다.');
                return;
            }
            status.textContent = checked ? 'ON' : 'OFF';
            status.className = 'toggle-status ' + (checked ? 'on' : 'off');
        }

        const MODAL_CPU_MEMORY_PER_HOUR = 0.3165;

        function modalSelectedGpuMeta(selectId) {
            const select = document.getElementById(selectId);
            const option = select?.selectedOptions?.[0];
            if (!select || !option) {
                console.error('[MODAL_RUNTIME] GPU 선택 요소 또는 option이 없습니다:', {selectId});
                return {id: 'L4', vramGib: 24, gpuHour: 0.7992};
            }
            const gpuHour = Number(option.dataset.gpuHour);
            const vramGib = Number(option.dataset.vramGib);
            if (!Number.isFinite(gpuHour) || !Number.isFinite(vramGib)) {
                console.error('[MODAL_RUNTIME] GPU 비용 메타데이터가 올바르지 않습니다:', {
                    selectId,
                    value: select.value,
                    gpuHour: option.dataset.gpuHour,
                    vramGib: option.dataset.vramGib,
                });
                return {id: select.value || 'L4', vramGib: 0, gpuHour: 0};
            }
            return {id: select.value, vramGib, gpuHour};
        }

        function modalSetGpuSelectValue(selectId, value) {
            const select = document.getElementById(selectId);
            if (!select) {
                console.error('[MODAL_RUNTIME] GPU 선택 요소가 없습니다:', {selectId});
                return;
            }
            const normalized = String(value || 'L4').toUpperCase();
            if (Array.from(select.options).some(option => option.value === normalized)) {
                select.value = normalized;
                return;
            }
            console.error('[MODAL_RUNTIME] 저장된 GPU를 지원하지 않아 L4로 복구합니다:', {
                selectId,
                value,
            });
            select.value = 'L4';
        }

        function modalGpuContainerCostText(meta) {
            const containerHour = meta.gpuHour + MODAL_CPU_MEMORY_PER_HOUR;
            return `GPU $${meta.gpuHour.toFixed(2)} + CPU/RAM $${MODAL_CPU_MEMORY_PER_HOUR.toFixed(2)} = 약 $${containerHour.toFixed(2)}/시간`;
        }

        // GPU·최대 병렬 수·유휴 자동 종료·상태 갱신은 Comfy 실행 관리 탭의
        // 런타임 패널 입력(modal-runtime-*)이 저장 소스다. 외부 API 탭의 중복 입력은 제거됐다.
        function modalSyncRuntimeControls(_source = 'runtime') {
            const runtimeScaledown = document.getElementById('modal-runtime-scaledown-window');
            const installerScaledown = document.getElementById('modal-installer-scaledown');
            if (installerScaledown) {
                installerScaledown.textContent = `작업 후 ${Number(runtimeScaledown?.value || 15)}초`;
            }
            const worker = modalSelectedGpuMeta('modal-runtime-worker-gpu');
            const web = modalSelectedGpuMeta('modal-runtime-web-gpu');
            const workerCost = document.getElementById('modal-runtime-worker-gpu-cost');
            const webCost = document.getElementById('modal-runtime-web-gpu-cost');
            const combinedCost = document.getElementById('modal-runtime-combined-cost');
            if (workerCost) workerCost.textContent = modalGpuContainerCostText(worker);
            if (webCost) webCost.textContent = modalGpuContainerCostText(web);
            if (combinedCost) {
                const total = worker.gpuHour + web.gpuHour + (MODAL_CPU_MEMORY_PER_HOUR * 2);
                combinedCost.textContent = `약 $${total.toFixed(2)}/시간`;
            }
            const workerMetric = document.getElementById('modal-runtime-worker-metric-label');
            if (workerMetric) workerMetric.textContent = `작업 워커 · ${worker.id}`;
            const concurrencyLabel = document.getElementById('modal-runtime-concurrency-label');
            if (concurrencyLabel) concurrencyLabel.textContent = `최대 병렬 ${worker.id} 워커`;
            const probeButton = document.getElementById('modal-runtime-probe-btn');
            if (probeButton) probeButton.textContent = `${worker.id} 연결 테스트`;
            const syncGpu = document.getElementById('modal-runtime-sync-gpu');
            if (syncGpu) syncGpu.textContent = `${worker.id} · ${worker.vramGib}GB`;
            if (comfyRuntimeActiveView === 'modal') modalRuntimeStartPolling();
        }

        function modalScheduleStatusPoll() {
            if (modalStatusPollTimer) clearTimeout(modalStatusPollTimer);
            modalStatusPollTimer = setTimeout(() => void modalRefreshStatus(false), 2000);
        }

        function modalRuntimeLogMatches(entry) {
            const category = String(entry?.category || 'jobs');
            if (modalRuntimeLogFilter === 'all') return true;
            if (modalRuntimeLogFilter === 'sync') {
                return category === 'sync' || category === 'deployment';
            }
            return category === modalRuntimeLogFilter;
        }

        function modalRuntimeLogTime(value) {
            const timestamp = new Date(Number(value || 0) * 1000);
            return Number.isNaN(timestamp.getTime())
                ? '--:--:--'
                : timestamp.toLocaleTimeString('ko-KR', {hour12: false});
        }

        function modalRuntimeLogLine(entry) {
            const app = String(entry?.app_name || entry?.app_role || 'modal');
            const fn = String(entry?.function_name || entry?.function_id || '-');
            const container = String(entry?.container_id || '');
            const source = String(entry?.source || 'system');
            const prefix = [
                `[${modalRuntimeLogTime(entry?.time)}]`,
                `[${app}]`,
                `[${fn}]`,
                container ? `[${container}]` : '',
                `[${source}]`,
            ].filter(Boolean).join(' ');
            const message = String(entry?.message || '');
            return `${prefix} ${message}`;
        }

        function modalRuntimeRenderLogs() {
            const terminal = document.getElementById('modal-runtime-log');
            if (!terminal) return;
            const entries = modalRuntimeLogEntries.filter(entry => (
                Number(entry?.time || 0) > modalRuntimeLogClearedAt
                && modalRuntimeLogMatches(entry)
            ));
            terminal.textContent = entries.length
                ? entries.map(modalRuntimeLogLine).join('\n')
                : '선택한 그룹에 표시할 Modal 로그가 없습니다.';
            if (document.getElementById('modal-runtime-log-autoscroll')?.checked) {
                terminal.scrollTop = terminal.scrollHeight;
            }
            document.querySelectorAll('[data-modal-log-filter]').forEach(button => {
                button.classList.toggle('active', button.dataset.modalLogFilter === modalRuntimeLogFilter);
            });
        }

        function modalRuntimeSelectLogTab(filter) {
            modalRuntimeLogFilter = String(filter || 'all');
            modalRuntimeRenderLogs();
        }

        async function modalRuntimeRefreshLogs(showResult = false) {
            if (modalRuntimeLogBusy) return;
            if (modalRuntimeLogPollTimer !== null) {
                window.clearTimeout(modalRuntimeLogPollTimer);
                modalRuntimeLogPollTimer = null;
            }
            modalRuntimeLogBusy = true;
            const status = document.getElementById('modal-runtime-log-status');
            try {
                const data = await fetchJSON('/api/modal/runtime/logs?entries=500');
                modalRuntimeLogEntries = Array.isArray(data.logs) ? data.logs : [];
                modalRuntimeRenderLogs();
                const errorCount = Array.isArray(data.errors) ? data.errors.length : 0;
                if (status) {
                    status.textContent = errorCount
                        ? `${modalRuntimeLogEntries.length}줄 · 일부 조회 실패 ${errorCount}`
                        : `${modalRuntimeLogEntries.length}줄 · ${new Date().toLocaleTimeString('ko-KR', {hour12: false})}`;
                }
                if (showResult) showToast('Modal 로그를 새로고침했습니다', errorCount ? 'warning' : 'success');
            } catch (error) {
                console.error('[MODAL_RUNTIME] 로그 조회 실패:', error);
                if (status) status.textContent = '로그 조회 실패';
                if (showResult) showToast('Modal 로그 조회 실패: ' + (error.message || error), 'error');
            } finally {
                modalRuntimeLogBusy = false;
                modalRuntimeScheduleLogPolling();
            }
        }

        async function modalRuntimeCopyLogs() {
            const text = document.getElementById('modal-runtime-log')?.textContent || '';
            try {
                await navigator.clipboard.writeText(text);
                showToast('현재 Modal 로그를 복사했습니다', 'success');
            } catch (error) {
                console.error('[MODAL_RUNTIME] 로그 복사 실패:', error);
                showToast('Modal 로그 복사 실패: ' + (error.message || error), 'error');
            }
        }

        function modalRuntimeClearLogs() {
            modalRuntimeLogClearedAt = Date.now() / 1000;
            modalRuntimeRenderLogs();
            const status = document.getElementById('modal-runtime-log-status');
            if (status) status.textContent = '화면 비움 · 원격 로그는 보존됨';
        }

        function modalFormatUsd(value) {
            const amount = Number(value);
            if (!Number.isFinite(amount)) return '-';
            return new Intl.NumberFormat('en-US', {
                style: 'currency',
                currency: 'USD',
                minimumFractionDigits: 2,
                maximumFractionDigits: 4,
            }).format(amount);
        }

        function modalRenderBilling(billing) {
            const metered = document.getElementById('modal-runtime-metered-cost');
            const adjustments = document.getElementById('modal-runtime-adjustments');
            const billed = document.getElementById('modal-runtime-billed-cost');
            const remaining = document.getElementById('modal-runtime-credit-remaining');
            const creditLabel = document.getElementById('modal-runtime-credit-label');
            const note = document.getElementById('modal-runtime-billing-note');
            if (!billing?.available || !billing.summary) {
                if (metered) metered.textContent = '-';
                if (adjustments) adjustments.textContent = '-';
                if (billed) billed.textContent = '-';
                if (remaining) remaining.textContent = '-';
                if (creditLabel) creditLabel.textContent = '월 크레딧 잔여 추정';
                const reason = billing?.reason;
                if (note) {
                    note.textContent = reason === 'disabled'
                        ? 'Modal OFF · 원격 계정과 비용을 조회하지 않습니다.'
                        : (reason === 'account_not_connected'
                            ? 'Modal 계정 연결 후 비용을 자동 조회합니다.'
                            : (billing?.error
                                ? `비용 조회 실패: ${billing.error}`
                                : 'Modal ON 및 계정 연결 후 60초 캐시로 자동 조회합니다.'));
                }
                return;
            }
            const summary = billing.summary;
            if (metered) metered.textContent = modalFormatUsd(summary.metered_cost);
            if (adjustments) adjustments.textContent = modalFormatUsd(summary.adjustment_total);
            if (billed) billed.textContent = modalFormatUsd(summary.billed_cost);
            if (remaining) remaining.textContent = modalFormatUsd(summary.remaining_credit_estimate);
            if (creditLabel) {
                creditLabel.textContent = `${modalFormatUsd(summary.configured_credit)} 기준 잔여 추정`;
            }
            if (note) {
                const fetched = summary.fetched_at
                    ? new Date(summary.fetched_at).toLocaleTimeString()
                    : '시간 정보 없음';
                const freshness = billing.cached
                    ? `캐시 ${Math.round(Number(billing.cache_age_seconds || 0))}초 경과`
                    : '방금 원격 조회';
                note.textContent = `${Number(billing.cache_seconds || 60)}초 캐시 · ${freshness} · ${fetched} · 잔여액은 설정된 월 크레딧 기준 추정치입니다.`;
            }
        }

        function modalFormatInstallDuration(value) {
            const seconds = Math.max(0, Math.floor(Number(value) || 0));
            if (seconds < 60) return `${seconds}초`;
            const minutes = Math.floor(seconds / 60);
            const remainSeconds = seconds % 60;
            if (minutes < 60) return `${minutes}분 ${remainSeconds}초`;
            const hours = Math.floor(minutes / 60);
            return `${hours}시간 ${minutes % 60}분`;
        }

        function modalRenderInstallProgress(install) {
            const panel = document.getElementById('modal-install-progress');
            const button = document.getElementById('modal-installer-start-btn');
            if (!panel) {
                console.error('[MODAL] 설치 진행 패널 요소가 없습니다.');
                return;
            }
            const state = String(install?.state || 'idle');
            if (button) button.disabled = state === 'running';
            if (state === 'idle') {
                panel.hidden = true;
                panel.dataset.state = 'idle';
                return;
            }
            panel.hidden = false;
            panel.dataset.state = state;

            const phaseOrder = ['assets', 'upload', 'complete'];
            const phase = String(install?.phase || 'assets');
            const fallbackIndex = Math.max(0, phaseOrder.indexOf(phase));
            const rawPhaseIndex = Number(install?.phase_index);
            const phaseIndex = Number.isInteger(rawPhaseIndex)
                ? Math.max(0, Math.min(rawPhaseIndex, phaseOrder.length - 1))
                : fallbackIndex;
            document.querySelectorAll('#modal-install-progress .modal-install-step').forEach((step, index) => {
                const complete = state === 'completed' || index < phaseIndex;
                step.classList.toggle('complete', complete);
                step.classList.toggle('active', index === phaseIndex && state !== 'completed');
            });

            const title = document.getElementById('modal-install-progress-title');
            const elapsed = document.getElementById('modal-install-progress-elapsed');
            if (title) title.textContent = `${install?.phase_label || phase} · ${install?.message || state}`;
            if (elapsed) elapsed.textContent = `경과 ${modalFormatInstallDuration(install?.elapsed_seconds)}`;

            const progress = install?.progress || {};
            const totalFiles = Math.max(0, Number(progress.total_files) || 0);
            const completedFiles = Math.max(0, Number(progress.completed_files) || 0);
            const totalBytes = Math.max(0, Number(progress.total_bytes) || 0);
            const completedBytes = Math.max(0, Number(progress.completed_bytes) || 0);
            const determinate = progress.mode === 'determinate' || progress.mode === 'complete';
            let percent = 0;
            if (progress.mode === 'complete' || state === 'completed') {
                percent = 100;
            } else if (determinate && totalBytes > 0) {
                percent = Math.min(100, completedBytes / totalBytes * 100);
            } else if (determinate && totalFiles > 0) {
                percent = Math.min(100, completedFiles / totalFiles * 100);
            }
            const track = document.getElementById('modal-install-progress-track');
            const fill = document.getElementById('modal-install-progress-fill');
            if (track) {
                track.classList.toggle('indeterminate', state === 'running' && !determinate);
                if (determinate || state === 'completed') {
                    track.setAttribute('aria-valuemin', '0');
                    track.setAttribute('aria-valuemax', '100');
                    track.setAttribute('aria-valuenow', String(Math.round(percent)));
                } else {
                    track.removeAttribute('aria-valuenow');
                }
            }
            if (fill) fill.style.width = `${percent.toFixed(2)}%`;

            const current = document.getElementById('modal-install-progress-current');
            const count = document.getElementById('modal-install-progress-count');
            if (current) {
                current.textContent = progress.current_item
                    ? `${progress.current_label || '파일'} · ${progress.current_item}`
                    : (progress.current_label || install?.message || '진행 정보를 기다리고 있습니다.');
                current.title = current.textContent;
            }
            if (count) {
                const parts = [];
                if (totalFiles > 0) parts.push(`${Math.min(completedFiles, totalFiles)}/${totalFiles}개`);
                if (totalBytes > 0) {
                    parts.push(`${comfyInstallerFormatBytes(Math.min(completedBytes, totalBytes))} / ${comfyInstallerFormatBytes(totalBytes)}`);
                } else if (Number(install?.size_bytes) > 0) {
                    parts.push(comfyInstallerFormatBytes(install.size_bytes));
                }
                if (Number(progress.skipped_files) > 0) parts.push(`기존 ${Number(progress.skipped_files)}개`);
                count.textContent = parts.join(' · ') || (Number(install?.model_count) > 0 ? `모델 ${Number(install.model_count)}개` : '-');
            }

            const log = document.getElementById('modal-install-progress-log');
            if (log) {
                const stickToBottom = log.scrollHeight - log.scrollTop - log.clientHeight < 28;
                const entries = Array.isArray(install?.logs) ? install.logs : [];
                log.textContent = entries.length
                    ? entries.map(item => {
                        const timestamp = new Date(Number(item?.time || 0) * 1000);
                        const timeText = Number.isNaN(timestamp.getTime())
                            ? '--:--:--'
                            : timestamp.toLocaleTimeString('ko-KR', { hour12: false });
                        return `[${timeText}] [${String(item?.source || 'system')}] ${String(item?.message || '')}`;
                    }).join('\n')
                    : '실시간 로그를 기다리고 있습니다.';
                if (stickToBottom) log.scrollTop = log.scrollHeight;
            }
        }

        function modalRenderDeploymentProgress(deployment) {
            const panel = document.getElementById('modal-deploy-progress');
            if (!panel) {
                console.error('[MODAL_RUNTIME] 전용 배포 진행 패널 요소가 없습니다.');
                return;
            }
            const pending = modalDeploymentRequestPending;
            let state = String(deployment?.state || 'idle');
            let phase = String(deployment?.phase || 'inventory');
            let kind = String(deployment?.kind || modalDeploymentPendingKind || 'redeploy');
            let message = String(deployment?.message || 'Modal 배포 요청을 준비하고 있습니다.');
            const deploymentStartedAt = Number(deployment?.started_at || 0) * 1000;
            const staleWhilePending = pending
                && modalDeploymentRequestStartedAt > 0
                && (!deploymentStartedAt || deploymentStartedAt < modalDeploymentRequestStartedAt - 1500);
            if (pending && (state === 'idle' || staleWhilePending)) {
                state = 'running';
                phase = 'inventory';
                kind = modalDeploymentPendingKind || 'redeploy';
                message = kind === 'custom_nodes'
                    ? '로컬 custom node 인벤토리를 확인하고 있습니다.'
                    : '재배포할 코드와 custom node 인벤토리를 확인하고 있습니다.';
            }
            if (state === 'idle') {
                panel.hidden = true;
                panel.dataset.state = 'idle';
                return;
            }
            panel.hidden = false;
            panel.dataset.state = state;

            const kindLabel = kind === 'custom_nodes'
                ? 'Custom Node 포함 재배포'
                : '기본 앱 재배포';
            const title = document.getElementById('modal-deploy-progress-title');
            const elapsed = document.getElementById('modal-deploy-progress-elapsed');
            if (title) title.textContent = `${kindLabel} · ${message}`;
            let elapsedSeconds = Number(deployment?.elapsed_seconds || 0);
            if (pending && modalDeploymentRequestStartedAt > 0 && elapsedSeconds <= 0) {
                elapsedSeconds = Math.max(0, (Date.now() - modalDeploymentRequestStartedAt) / 1000);
            }
            if (elapsed) elapsed.textContent = `경과 ${modalFormatInstallDuration(elapsedSeconds)}`;

            const phaseOrder = ['inventory', 'worker', 'web', 'shutdown', 'complete'];
            const phaseIndex = Math.max(0, phaseOrder.indexOf(phase));
            panel.querySelectorAll('.modal-deploy-step').forEach((step, index) => {
                const complete = state === 'completed' || index < phaseIndex;
                const active = state !== 'completed' && index === phaseIndex;
                step.classList.toggle('complete', complete);
                step.classList.toggle('active', active);
            });

            const percentByPhase = {inventory: 10, worker: 40, web: 70, shutdown: 90, complete: 100};
            const percent = state === 'completed'
                ? 100
                : Number(percentByPhase[phase] || 12);
            const track = document.getElementById('modal-deploy-progress-track');
            const fill = document.getElementById('modal-deploy-progress-fill');
            if (track) track.setAttribute('aria-valuenow', String(percent));
            if (fill) fill.style.width = `${percent}%`;

            const current = document.getElementById('modal-deploy-progress-current');
            const count = document.getElementById('modal-deploy-progress-count');
            const phaseLabels = {
                inventory: '인벤토리 확인',
                worker: '작업 App 빌드·배포',
                web: '웹 App 배포',
                shutdown: '웹 App·GPU 자동 종료',
                complete: '배포 완료',
            };
            if (current) {
                current.textContent = `${phaseLabels[phase] || phase} · ${message}`;
                current.title = current.textContent;
            }
            if (count) {
                const summary = deployment?.inventory?.summary || {};
                count.textContent = deployment?.inventory
                    ? `manifest ${Number(summary.manifest || 0)} · Git ${Number(summary.git || 0)} · 로컬 ${Number(summary.local || 0)} · 제외 ${Number(summary.skipped || 0)}`
                    : (phase === 'inventory' ? '대상 확인 중' : '-');
            }

            const log = document.getElementById('modal-deploy-progress-log');
            if (log) {
                const entries = Array.isArray(deployment?.logs) ? deployment.logs.slice(-10) : [];
                log.textContent = entries.length
                    ? entries.map(item => {
                        const timestamp = new Date(Number(item?.time || 0) * 1000);
                        const timeText = Number.isNaN(timestamp.getTime())
                            ? '--:--:--'
                            : timestamp.toLocaleTimeString('ko-KR', {hour12: false});
                        return `[${timeText}] [${String(item?.source || 'system')}] ${String(item?.message || '')}`;
                    }).join('\n')
                    : (phase === 'inventory'
                        ? '로컬 custom node와 manifest를 비교하고 있습니다.'
                        : 'Modal CLI 출력을 기다리고 있습니다.');
                log.scrollTop = log.scrollHeight;
            }
        }

        function modalApplyStatus(data, showResult = false) {
            const account = document.getElementById('modal-account-status');
            const cost = document.getElementById('modal-cost-status');
            const installStatus = document.getElementById('modal-installer-status');
            const auth = data.auth || {};
            const install = data.install || {};
            const deployment = data.deployment || {};
            const workerGpu = String(data.settings?.worker_gpu || data.settings?.gpu || 'GPU');
            const webGpu = String(data.settings?.web_gpu || 'GPU');
            const deploymentRunning = deployment.state === 'running';
            if (account) {
                const onoff = data.settings.enabled ? 'Modal ON' : 'Modal OFF';
                const connection = data.connected ? '연결됨' : '연결 안 됨';
                account.textContent = `${onoff} · ${connection} · profile=${data.settings.profile} · SDK ${data.sdk_version}`
                    + (data.pending_lora_deletes ? ` · LoRA 삭제 대기 ${data.pending_lora_deletes}건` : '')
                    + (auth.state === 'running' ? `\n${auth.message}` : '');
                account.style.color = data.connected ? '#4caf50' : '#e6a23c';
            }
            // 인증 진행 중에는 계정 연결 버튼을 비활성화하고, 끝나면 다시 활성화.
            // 반복 클릭으로 인증 태스크가 살아있는 동안 400이 무한히 나오는 것을 방지.
            const connectBtn = document.getElementById('modal-connect-btn');
            if (connectBtn) connectBtn.disabled = (auth.state === 'running');
            if (cost && data.cost) {
                const workerCost = data.cost.worker || {};
                const webCost = data.cost.web || {};
                const lines = [
                    `작업 ${workerGpu} GPU $${workerCost.gpu_per_hour ?? data.cost.gpu_per_hour}/시간 · CPU/RAM 포함 $${workerCost.container_per_hour ?? data.cost.estimated_container_per_hour}/컨테이너시간`,
                    `웹 ${webGpu} GPU $${webCost.gpu_per_hour}/시간 · CPU/RAM 포함 $${webCost.container_per_hour}/컨테이너시간 · 동시 실행 $${data.cost.combined_container_per_hour}/시간`,
                    `$${data.cost.monthly_credit}로 약 ${data.cost.estimated_container_hours} 컨테이너시간 · 동시 ${data.settings.max_concurrency}개 연속 사용 시 약 ${data.cost.estimated_wall_hours_at_max_concurrency}시간`,
                ];
                if (data.billing?.available && data.billing.summary) {
                    lines.push(
                        `이번 달 사용 ${modalFormatUsd(data.billing.summary.metered_cost)} · 조정 ${modalFormatUsd(data.billing.summary.adjustment_total)} · 실제 청구 ${modalFormatUsd(data.billing.summary.billed_cost)} · 잔여 추정 ${modalFormatUsd(data.billing.summary.remaining_credit_estimate)}`,
                    );
                }
                cost.textContent = lines.join('\n');
            }
            if (installStatus && install.state && install.state !== 'idle') {
                installStatus.textContent = install.message || install.state;
                installStatus.style.color = install.state === 'failed'
                    ? '#ff6b6b'
                    : (install.state === 'completed' ? '#4caf50' : 'var(--text-secondary,#aaa)');
            }
            modalRenderInstallProgress(install);
            const deploymentStartedAt = Number(deployment.started_at || 0) * 1000;
            const deploymentAcknowledgesRequest = modalDeploymentRequestPending
                && deployment.state
                && deployment.state !== 'idle'
                && deploymentStartedAt > 0
                && deploymentStartedAt >= modalDeploymentRequestStartedAt - 1500;
            if (deploymentAcknowledgesRequest) {
                modalDeploymentRequestPending = false;
                modalDeploymentPendingKind = String(deployment.kind || modalDeploymentPendingKind || '');
                modalDeploymentRequestStartedAt = 0;
            }
            modalRenderDeploymentProgress(deployment);
            const deploymentStatus = document.getElementById('modal-runtime-deployment-status');
            const redeployButton = document.getElementById('modal-runtime-redeploy-btn');
            const installButton = document.getElementById('modal-installer-start-btn');
            const deploymentBusy = deploymentRunning || modalDeploymentRequestPending;
            if (redeployButton) redeployButton.disabled = deploymentBusy || install.state === 'running';
            if (installButton) installButton.disabled = install.state === 'running' || deploymentBusy;
            const activeDeploymentKind = deploymentRunning
                ? String(deployment.kind || '')
                : (modalDeploymentRequestPending ? modalDeploymentPendingKind : '');
            if (redeployButton) {
                redeployButton.textContent = deploymentBusy
                    ? (activeDeploymentKind === 'custom_nodes'
                        ? 'Custom Node 포함 재배포 중…'
                        : '기본 앱 재배포 중…')
                    : '앱·Custom Node 재배포';
                redeployButton.classList.toggle('modal-deployment-busy', deploymentBusy);
            }
            if (deploymentStatus && deployment.state && deployment.state !== 'idle') {
                const summary = deployment.inventory?.summary || {};
                const counts = deployment.inventory
                    ? ` · manifest ${Number(summary.manifest || 0)} · 추가 Git ${Number(summary.git || 0)} · 로컬 ${Number(summary.local || 0)} · 제외 ${Number(summary.skipped || 0)}`
                    : '';
                deploymentStatus.textContent = `${deployment.message || deployment.state}${counts}`;
                deploymentStatus.style.color = deployment.state === 'failed'
                    ? '#ff6b6b'
                    : (deployment.state === 'completed' ? '#4caf50' : 'var(--text-secondary,#aaa)');
            }

            const runtimeState = document.getElementById('modal-runtime-state');
            const runtimeAccount = document.getElementById('modal-runtime-account');
            const runtimeRunners = document.getElementById('modal-runtime-runners');
            const runtimeInputs = document.getElementById('modal-runtime-inputs');
            const runtime = data.runtime || null;
            if (runtimeAccount) {
                runtimeAccount.textContent = !data.settings.enabled
                    ? 'OFF'
                    : (data.connected ? data.settings.profile : '연결 필요');
            }
            if (runtimeRunners) {
                runtimeRunners.textContent = runtime?.available
                    ? `${Number(runtime.num_total_runners || 0)}개`
                    : (runtime?.reason === 'deployment_in_progress'
                        ? '배포 중'
                        : (data.settings.enabled ? '배포 확인 필요' : '사용 안 함'));
            }
            if (runtimeInputs) {
                runtimeInputs.textContent = runtime?.available
                    ? `${Number(runtime.num_running_inputs || 0)} 실행 · ${Number(runtime.backlog || 0)} 대기`
                    : '0';
            }
            const isRunning = !!runtime?.available && (
                Number(runtime.num_total_runners || 0) > 0
                || Number(runtime.num_running_inputs || 0) > 0
            );
            const modalTab = document.getElementById('comfy-runtime-tab-modal');
            modalTab?.classList.toggle('running', isRunning);
            if (runtimeState) {
                runtimeState.classList.toggle('running', isRunning);
                runtimeState.textContent = !data.settings.enabled
                    ? '● 사용 안 함'
                    : (!data.connected
                        ? '● 계정 연결 필요'
                        : (runtime?.reason === 'deployment_in_progress'
                            ? '● Modal 배포 중'
                            : (isRunning ? `● ${workerGpu} 실행 중` : '● 자동 대기')));
            }
            const runtimeEnabledStatus = document.getElementById('modal-runtime-enabled-status');
            if (runtimeEnabledStatus) {
                runtimeEnabledStatus.textContent = data.settings.enabled ? 'ON' : 'OFF';
                runtimeEnabledStatus.className = 'toggle-status ' + (data.settings.enabled ? 'on' : 'off');
            }
            modalRenderBilling(data.billing);
            const probe = data.probe || {};
            const probeButton = document.getElementById('modal-runtime-probe-btn');
            if (probeButton) {
                probeButton.disabled = probe.state === 'running';
                probeButton.textContent = probe.state === 'running'
                    ? `${workerGpu} 연결 확인 중…`
                    : `${workerGpu} 연결 테스트`;
            }
            const web = data.web || {};
            const webState = String(web.state || 'stopped');
            const webBusy = webState === 'starting' || webState === 'stopping';
            const webRunning = webState === 'running';
            const webStartButton = document.getElementById('modal-runtime-web-start-btn');
            const webConnectButton = document.getElementById('modal-runtime-web-connect-btn');
            const webStopButton = document.getElementById('modal-runtime-web-stop-btn');
            const webStateBadge = document.getElementById('modal-runtime-web-state');
            const webMetric = document.getElementById('modal-runtime-web-status');
            if (modalWebStartRequestPending && webState !== 'stopped') {
                modalWebStartRequestPending = false;
            }
            const showWebStopAction = webState === 'starting' || webRunning || webState === 'stopping';
            if (webStartButton) {
                webStartButton.hidden = showWebStopAction;
                webStartButton.disabled = modalWebStartRequestPending || deploymentBusy || webBusy || webRunning || !data.connected;
                webStartButton.textContent = modalWebStartRequestPending || webState === 'starting'
                    ? 'ComfyUI 시작 중…'
                    : 'ComfyUI 시작';
            }
            if (webConnectButton) webConnectButton.disabled = !webRunning || !web.url;
            if (webStopButton) {
                webStopButton.hidden = !showWebStopAction;
                webStopButton.disabled = deploymentBusy || webState === 'stopping';
                webStopButton.textContent = webState === 'starting'
                    ? 'ComfyUI 시작 취소'
                    : (webState === 'stopping'
                        ? 'ComfyUI 종료 중…'
                        : 'ComfyUI 완전 종료');
            }
            if (webStateBadge) {
                const labels = {
                    starting: '시작 중',
                    running: '실행 중',
                    stopping: '종료 중',
                    failed: '오류',
                    stopped: '꺼짐',
                };
                webStateBadge.textContent = labels[webState] || webState;
                webStateBadge.classList.toggle('running', webRunning);
                webStateBadge.title = web.message || '';
            }
            if (webMetric) {
                webMetric.textContent = webRunning
                    ? `${webGpu} 실행 중 · ${Number(web.num_total_runners || 0)}개`
                    : (webBusy ? (webState === 'starting' ? '시작 중' : '종료 중') : '꺼짐');
                webMetric.title = web.message || '';
            }
            modalSyncOperationLock(data);
            if (showResult) {
                showToast(
                    data.connected ? 'Modal 계정이 연결되어 있습니다' : 'Modal 계정 연결이 필요합니다',
                    data.connected ? 'success' : 'warning',
                );
            }
            if (auth.state === 'running' || install.state === 'running' || deploymentRunning || probe.state === 'running' || webBusy) {
                _modalAuthWasRunning = _modalAuthWasRunning || auth.state === 'running';
                _modalInstallWasRunning = _modalInstallWasRunning || install.state === 'running';
                _modalDeploymentWasRunning = _modalDeploymentWasRunning || deploymentRunning;
                _modalProbeWasRunning = _modalProbeWasRunning || probe.state === 'running';
                modalScheduleStatusPoll();
            } else {
                // running 이었다가 터미널(completed/failed)로 넘어간 경우:
                // 폴링이 여기서 멈추므로, 최종 연결 상태를 한 번 더 가져와 반영한다.
                // (인증 완료 후 "연결 안 됨"이 화면에 남는 현상 방지)
                if (_modalDeploymentWasRunning && deployment.state === 'completed') {
                    showToast(deployment.message || 'Modal 배포가 완료되었습니다', 'success');
                } else if (_modalDeploymentWasRunning && deployment.state === 'failed') {
                    showToast(deployment.message || 'Modal 배포에 실패했습니다', 'error');
                }
                const justFinished = _modalAuthWasRunning || _modalInstallWasRunning || _modalDeploymentWasRunning || _modalProbeWasRunning;
                _modalAuthWasRunning = false;
                _modalInstallWasRunning = false;
                _modalDeploymentWasRunning = false;
                _modalProbeWasRunning = false;
                if (justFinished) modalScheduleStatusPoll();
            }
        }

        async function modalRefreshStatus(showResult = false) {
            const account = document.getElementById('modal-account-status');
            try {
                const data = await fetchJSON('/api/modal/status');
                modalApplyStatus(data, showResult);
            } catch (error) {
                console.error('[MODAL] 상태 조회 실패:', error);
                if (account) {
                    account.textContent = '상태 조회 실패: ' + (error.message || error);
                    account.style.color = '#ff6b6b';
                }
                if (showResult) showToast('Modal 상태 조회 실패: ' + (error.message || error), 'error');
            }
        }

        async function modalConnectAccount() {
            const profile = document.getElementById('setting-modal-profile')?.value.trim() || 'soya-comfy';
            const button = document.getElementById('modal-connect-btn');
            if (button) button.disabled = true;
            try {
                await fetchJSON('/api/modal/connect', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({profile}),
                });
                showToast('브라우저에서 Modal 인증을 완료하세요', 'warning');
                modalScheduleStatusPoll();
            } catch (error) {
                console.error('[MODAL] 계정 연결 시작 실패:', error);
                showToast('Modal 계정 연결 실패: ' + (error.message || error), 'error');
                if (button) button.disabled = false;
            }
            // 성공 시 버튼은 modalApplyStatus가 auth.state==='running'을 보고 비활성화를 유지.
            // 따라서 finally에서 무조건 풀지 않는다(진행 중 풀면 반복 클릭 → 400 스팸).
        }

        async function modalRefreshBilling() {
            const cost = document.getElementById('modal-cost-status');
            try {
                const data = await fetchJSON('/api/modal/billing?refresh=1');
                modalRenderBilling({available: true, ...data});
                if (cost) {
                    cost.textContent = `이번 달 사용 ${modalFormatUsd(data.summary.metered_cost)} · 조정 ${modalFormatUsd(data.summary.adjustment_total)} · 실제 청구 ${modalFormatUsd(data.summary.billed_cost)} · 잔여 추정 ${modalFormatUsd(data.summary.remaining_credit_estimate)}`;
                }
                showToast('Modal 이번 달 비용을 조회했습니다', 'success');
            } catch (error) {
                console.error('[MODAL] 비용 조회 실패:', error);
                if (cost) cost.textContent = '비용 조회 실패: ' + (error.message || error);
                showToast('Modal 비용 조회 실패: ' + (error.message || error), 'error');
            }
        }

        function modalSelectedWorkflows() {
            // DOM 체크박스가 아니라 Set이 진원. 필터로 감춰진 항목도 선택 유지.
            return Array.from(modalSelectedWorkflowIds);
        }

        function modalUpdateWorkflowSelectionSummary() {
            const selected = modalSelectedWorkflowIds;
            let modelCount = 0;
            let rawBytes = 0;
            for (const item of modalWorkflowCatalog) {
                if (!selected.has(item.id)) continue;
                modelCount += Number(item.model_count || 0);
                rawBytes += Number(item.size_bytes || 0);
            }
            const summary = document.getElementById('modal-installer-selection-summary');
            if (summary) {
                summary.textContent = selected.size
                    ? `${selected.size}개 워크플로우 · 참조 모델 최대 ${modelCount}개 · 중복 전 최대 ${(rawBytes / 1024 ** 3).toFixed(2)} GiB (서버에서 중복 제거)`
                    : '선택 없음';
            }
        }

        function modalWorkflowSearchText() {
            const input = document.getElementById('modal-workflow-search');
            return (input?.value || '').trim().toLowerCase();
        }

        function modalFilterWorkflows() {
            // 검색 입력 변경 시 재렌더. 카탈로그 재조회 없이 로컬 필터만.
            modalRenderWorkflowCatalog();
        }

        function modalRemoteWorkflowStateMeta(item) {
            const states = {
                synced: {
                    label: '동기화 완료',
                    detail: '로컬과 Modal Volume의 파일이 같습니다.',
                },
                different: {
                    label: '내용 다름',
                    detail: 'SHA-256 해시가 일치하지 않습니다. 실행은 Modal Volume의 원격 사본을 기준으로 이루어지므로, 다시 동기화하기 전까지 로컬 수정 사항은 반영되지 않습니다.',
                },
                missing: {
                    label: 'Modal에 없음',
                    detail: 'Modal Volume에 워크플로우 파일이 없습니다.',
                },
                invalid: {
                    label: '원격 파일 오류',
                    detail: 'Modal Volume의 워크플로우 파일을 읽을 수 없습니다.',
                },
            };
            return states[String(item?.sync_state || item || '')] || {
                label: '조회 필요',
                detail: '워크플로우 동기화 조회를 실행하세요.',
            };
        }

        function modalRemoteWorkflowStateText(item) {
            return modalRemoteWorkflowStateMeta(item).label;
        }

        function modalSetRemoteWorkflowFilter(state) {
            const allowed = new Set(['all', 'synced', 'different', 'missing', 'invalid']);
            modalRemoteWorkflowFilter = allowed.has(String(state || '')) ? String(state) : 'all';
            modalRenderWorkflowCatalog();
        }

        function modalRenderWorkflowSyncSummary() {
            const summary = document.getElementById('modal-workflow-sync-summary');
            if (!summary) return;
            const loaded = modalRemoteWorkflowQueryState === 'loaded';
            summary.hidden = !loaded;
            if (!loaded) return;

            const counts = {
                all: modalWorkflowCatalog.length,
                synced: 0,
                different: 0,
                missing: 0,
                invalid: 0,
            };
            for (const item of modalWorkflowCatalog) {
                const state = String(item?.sync_state || '');
                if (Object.prototype.hasOwnProperty.call(counts, state)) counts[state] += 1;
            }
            if (modalRemoteWorkflowFilter !== 'all' && !counts[modalRemoteWorkflowFilter]) {
                modalRemoteWorkflowFilter = 'all';
            }
            for (const [state, count] of Object.entries(counts)) {
                const countElement = document.getElementById(`modal-workflow-sync-count-${state}`);
                if (countElement) countElement.textContent = String(count);
            }
            summary.querySelectorAll('[data-modal-workflow-sync-filter]').forEach(button => {
                const active = button.dataset.modalWorkflowSyncFilter === modalRemoteWorkflowFilter;
                button.classList.toggle('active', active);
                button.setAttribute('aria-pressed', active ? 'true' : 'false');
            });
        }

        function modalRenderWorkflowCatalog(errors) {
            const container = document.getElementById('modal-workflow-catalog');
            if (!container) return;
            modalRenderWorkflowSyncSummary();
            const query = modalWorkflowSearchText();
            const filtered = modalWorkflowCatalog.filter(item => {
                const name = String(item.source_name || item.id || '').toLowerCase();
                const matchesSearch = !query || name.includes(query);
                const matchesSync = modalRemoteWorkflowQueryState !== 'loaded'
                    || modalRemoteWorkflowFilter === 'all'
                    || String(item.sync_state || '') === modalRemoteWorkflowFilter;
                return matchesSearch && matchesSync;
            });
            container.replaceChildren();
            if (errors && errors.length) {
                const note = document.createElement('p');
                note.className = 'comfy-installer-note';
                note.style.cssText = 'color:#d77;margin:0 0 6px;';
                note.textContent = `처리 실패(${errors.length}개, 제외됨): ${errors.map(e => e.name).join(', ')} — 서버 로그를 확인하세요.`;
                container.append(note);
            }
            if (!modalWorkflowCatalog.length) {
                const empty = document.createElement('div');
                empty.className = 'comfy-workflow-empty';
                empty.textContent = '관리 워크플로우 폴더에 동기화할 워크플로우 파일이 없습니다.';
                container.append(empty);
            } else if (!filtered.length) {
                const empty = document.createElement('div');
                empty.className = 'comfy-workflow-empty';
                const rawQuery = (document.getElementById('modal-workflow-search')?.value || '').trim();
                empty.textContent = rawQuery
                    ? `검색 "${rawQuery}"에 일치하는 워크플로우가 없습니다.`
                    : `${modalRemoteWorkflowStateMeta(modalRemoteWorkflowFilter).label} 상태의 워크플로우가 없습니다.`;
                container.append(empty);
            }
            for (const item of filtered) {
                const label = document.createElement('label');
                label.className = 'modal-workflow-row';
                const checkbox = document.createElement('input');
                checkbox.type = 'checkbox';
                checkbox.className = 'modal-workflow-checkbox';
                checkbox.value = item.id;
                checkbox.checked = modalSelectedWorkflowIds.has(item.id);
                checkbox.addEventListener('change', () => {
                    if (checkbox.checked) modalSelectedWorkflowIds.add(item.id);
                    else modalSelectedWorkflowIds.delete(item.id);
                    modalUpdateWorkflowSelectionSummary();
                });
                const copy = document.createElement('span');
                copy.className = 'modal-workflow-copy';
                const main = document.createElement('span');
                main.className = 'modal-workflow-main';
                const name = document.createElement('strong');
                name.textContent = item.source_name || item.id;
                main.append(name);
                if (modalRemoteWorkflowQueryState === 'loaded') {
                    const syncState = String(item.sync_state || 'invalid');
                    const meta = modalRemoteWorkflowStateMeta(syncState);
                    label.classList.add('has-sync', `state-${syncState}`);
                    const badge = document.createElement('span');
                    badge.className = `modal-workflow-sync-badge state-${syncState}`;
                    badge.textContent = meta.label;
                    badge.title = String(item.remote_error || meta.detail);
                    main.append(badge);
                }
                const detail = document.createElement('small');
                detail.className = 'modal-workflow-detail';
                detail.textContent = `${Number(item.model_count || 0)} 모델 · ${(Number(item.size_gib) || 0).toFixed(2)} GiB`;
                copy.append(main, detail);
                label.append(checkbox, copy);
                container.append(label);
            }
            const countEl = document.getElementById('modal-workflow-search-count');
            if (countEl) {
                countEl.textContent = modalWorkflowCatalog.length
                    ? `${filtered.length} / ${modalWorkflowCatalog.length}개`
                    : '';
            }
        }

        async function modalInstallerLoadCatalog() {
            const container = document.getElementById('modal-workflow-catalog');
            if (!container) return;
            try {
                const data = await fetchJSON('/api/modal/workflows');
                modalWorkflowCatalog = data.workflows || [];
                modalRemoteWorkflowQueryState = 'idle';
                modalRemoteWorkflowCheckedAt = '';
                modalRemoteWorkflowFilter = 'all';
                const errors = Array.isArray(data.errors) ? data.errors : [];
                // 새로고침 후 사라진 항목은 선택에서 제거(스테일 선택 방지).
                const present = new Set(modalWorkflowCatalog.map(item => item.id));
                for (const id of Array.from(modalSelectedWorkflowIds)) {
                    if (!present.has(id)) modalSelectedWorkflowIds.delete(id);
                }
                modalRenderWorkflowCatalog(errors);
                modalUpdateWorkflowSelectionSummary();
                const queryStatus = document.getElementById('modal-runtime-workflow-query-status');
                if (queryStatus) queryStatus.textContent = '원격 조회 후 로컬과 Modal Volume의 동기화 상태를 확인할 수 있습니다.';
            } catch (error) {
                console.error('[MODAL] 워크플로우 목록 로드 실패:', error);
                container.textContent = '목록 로드 실패: ' + (error.message || error);
            }
        }

        async function modalInstallerStart() {
            const workflowIds = modalSelectedWorkflows();
            if (!workflowIds.length) {
                showToast('Modal에 동기화할 워크플로우를 선택하세요', 'warning');
                return;
            }
            if (!window.confirm(`선택한 ${workflowIds.length}개 관리 워크플로우와 현재 로컬에서 참조하는 모델·LoRA 파일을 사용자 Modal 계정에 직접 업로드할까요? 앱과 Custom Node는 재배포하지 않으며, GPU는 생성 요청 전까지 켜지지 않습니다.`)) return;
            const button = document.getElementById('modal-installer-start-btn');
            if (button) button.disabled = true;
            let started = false;
            try {
                const data = await fetchJSON('/api/modal/install', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({workflow_ids: workflowIds}),
                });
                const status = document.getElementById('modal-installer-status');
                if (status) status.textContent = data.install?.message || 'Modal 동기화를 시작했습니다.';
                started = true;
                _modalInstallWasRunning = true;
                modalRemoteWorkflowQueryState = 'idle';
                modalRemoteWorkflowCheckedAt = '';
                modalRemoteWorkflowFilter = 'all';
                modalRenderWorkflowCatalog();
                const queryStatus = document.getElementById('modal-runtime-workflow-query-status');
                if (queryStatus) queryStatus.textContent = '동기화가 끝난 뒤 원격 조회를 다시 실행하세요.';
                modalRenderInstallProgress(data.install || {state: 'running', phase: 'assets'});
                showToast('Modal 동기화를 시작했습니다', 'success');
                modalScheduleStatusPoll();
            } catch (error) {
                console.error('[MODAL] 동기화 시작 실패:', error);
                showToast('Modal 동기화 시작 실패: ' + (error.message || error), 'error');
            } finally {
                if (button && !started) button.disabled = false;
            }
        }

        async function modalRuntimeQueryWorkflows() {
            const button = document.getElementById('modal-runtime-workflow-query-btn');
            const status = document.getElementById('modal-runtime-workflow-query-status');
            if (button) button.disabled = true;
            modalRemoteWorkflowQueryState = 'loading';
            modalRemoteWorkflowFilter = 'all';
            modalRenderWorkflowCatalog();
            if (status) status.textContent = '로컬 관리 워크플로우와 Modal Volume의 SHA-256을 비교하고 있습니다.';
            try {
                const data = await fetchJSON('/api/modal/workflows/remote');
                modalWorkflowCatalog = Array.isArray(data.workflows) ? data.workflows : [];
                modalRemoteWorkflowQueryState = 'loaded';
                modalRemoteWorkflowCheckedAt = String(data.checked_at || '');
                const present = new Set(modalWorkflowCatalog.map(item => item.id));
                for (const id of Array.from(modalSelectedWorkflowIds)) {
                    if (!present.has(id)) modalSelectedWorkflowIds.delete(id);
                }
                const errors = Array.isArray(data.errors) ? data.errors : [];
                const remoteErrors = Array.isArray(data.remote_errors) ? data.remote_errors : [];
                if (remoteErrors.length) {
                    console.error('[MODAL_RUNTIME] 원격 워크플로우 검사 실패:', remoteErrors);
                }
                modalRenderWorkflowCatalog(errors);
                modalUpdateWorkflowSelectionSummary();
                const counts = data.counts || {};
                const checked = modalRemoteWorkflowCheckedAt
                    ? new Date(modalRemoteWorkflowCheckedAt).toLocaleTimeString('ko-KR', {hour12: false})
                    : '방금';
                if (status) {
                    status.textContent = `${checked} 조회 · 완료 ${Number(counts.synced || 0)}개 · 내용 다름 ${Number(counts.different || 0)}개 · Modal에 없음 ${Number(counts.missing || 0)}개 · 오류 ${Number(counts.invalid || 0)}개`;
                }
                showToast('Modal 워크플로우 동기화 상태를 조회했습니다', 'success');
            } catch (error) {
                modalRemoteWorkflowQueryState = 'failed';
                modalRemoteWorkflowCheckedAt = '';
                modalRemoteWorkflowFilter = 'all';
                modalRenderWorkflowCatalog();
                console.error('[MODAL_RUNTIME] 원격 워크플로우 조회 실패:', error);
                if (status) status.textContent = '원격 조회 실패: ' + (error.message || error);
                showToast('Modal 원격 워크플로우 조회 실패: ' + (error.message || error), 'error');
            } finally {
                if (button) button.disabled = false;
            }
        }

        async function modalQueryModelInventory() {
            const button = document.getElementById('modal-model-inventory-btn');
            const status = document.getElementById('modal-model-inventory-status');
            const list = document.getElementById('modal-model-inventory-list');
            if (button) button.disabled = true;
            if (status) status.textContent = 'Modal Volume의 Model 및 LoRA 목록을 조회 중입니다...';
            try {
                const data = await fetchJSON('/api/modal/models');
                const summary = data.summary || {};
                const items = Array.isArray(data.items) ? data.items : [];
                const orphans = Array.isArray(data.orphans) ? data.orphans : [];
                // 진단 목적이므로 결손 및 크기 불일치 항목을 정상 항목보다 먼저 노출합니다.
                const problems = items.filter(item => item.state === 'missing' || !item.size_match);
                const rows = [...problems, ...orphans];
                if (list) {
                    list.hidden = false;
                    list.innerHTML = rows.length ? rows.map(item => {
                        const label = item.state === 'orphan'
                            ? 'Orphan (Manifest 누락)'
                            : (item.state === 'missing' ? 'Remote 누락' : '용량 불일치');
                        const name = escapeHtml(String(item.id || item.path || ''));
                        const path = escapeHtml(String(item.path || ''));
                        const kind = item.kind === 'lora' ? 'loras Volume' : 'models Volume';
                        return `<div class="comfy-workflow-user-file"><strong>${name}</strong><small>${label} · ${kind} · ${path}</small></div>`;
                    }).join('') : '<div class="comfy-workflow-empty">Manifest 데이터와 Volume 내용이 모두 일치합니다.</div>';
                }
                const totalGiB = ((Number(summary.model_bytes || 0) + Number(summary.lora_bytes || 0)) / (1024 ** 3)).toFixed(2);
                if (status) {
                    status.textContent = `기대 ${Number(summary.expected || 0)}개 · 존재 ${Number(summary.present || 0)}개 · 누락 ${Number(summary.missing || 0)}개 · 용량 불일치 ${Number(summary.size_mismatch || 0)}개 · Orphan ${Number(summary.orphans || 0)}개 · Volume 크기 ${totalGiB} GiB (저장 공간에 따른 과금이 발생합니다)`;
                }
                showToast('Remote 모델 Inventory를 조회했습니다.', 'success');
            } catch (error) {
                console.error('[MODAL_RUNTIME] Remote 모델 Inventory 조회 실패:', error);
                if (status) status.textContent = 'Remote 모델 Inventory 조회 실패: ' + (error.message || error);
                showToast('Remote 모델 Inventory 조회 실패: ' + (error.message || error), 'error');
            } finally {
                if (button) button.disabled = false;
            }
        }

        function modalRuntimeCustomNodeInventoryText(customNodes) {
            const summary = customNodes?.summary || {};
            const lines = [
                `Manifest 노드 ${Number(summary.manifest || 0)}개`,
                `추가 Git 노드 ${Number(summary.git || 0)}개`,
                `로컬 소스 복사 ${Number(summary.local || 0)}개 (${comfyInstallerFormatBytes(Number(summary.local_bytes || 0))})`,
                `제외 ${Number(summary.skipped || 0)}개 · 경고 ${Number(summary.warning || 0)}건`,
            ];
            const discovered = Array.isArray(customNodes?.discovered_nodes)
                ? customNodes.discovered_nodes
                : [];
            if (discovered.length) {
                lines.push('', '추가 동기화 대상:');
                discovered.slice(0, 12).forEach(item => {
                    const kind = item.source_type === 'git' ? 'Git' : '로컬 복사';
                    lines.push(`- ${item.name} (${kind})`);
                });
                if (discovered.length > 12) lines.push(`- 외 ${discovered.length - 12}개`);
            }
            const skipped = Array.isArray(customNodes?.skipped) ? customNodes.skipped : [];
            if (skipped.length) {
                lines.push('', '제외 항목:');
                skipped.slice(0, 8).forEach(item => lines.push(`- ${item.name}: ${item.reason}`));
                if (skipped.length > 8) lines.push(`- 외 ${skipped.length - 8}개`);
            }
            const warnings = Array.isArray(customNodes?.warnings) ? customNodes.warnings : [];
            if (warnings.length) {
                lines.push('', '경고:');
                warnings.slice(0, 8).forEach(item => lines.push(`- ${item}`));
                if (warnings.length > 8) lines.push(`- 외 ${warnings.length - 8}건`);
            }
            return lines.join('\n');
        }

        function modalRuntimeRedeploy() {
            modalOpenRedeployChoice();
        }

        async function modalStartRedeploy(kind) {
            if (modalDeploymentRequestPending || modalOperationLockActive()) return;
            const customNodes = kind === 'custom_nodes';
            const endpoint = customNodes ? '/api/modal/custom-nodes/sync' : '/api/modal/redeploy';
            const label = customNodes ? 'Custom Node 포함 재배포' : '기본 앱 재배포';
            const button = document.getElementById('modal-runtime-redeploy-btn');
            modalDeploymentRequestPending = true;
            modalDeploymentPendingKind = customNodes ? 'custom_nodes' : 'redeploy';
            modalDeploymentRequestStartedAt = Date.now();
            document.getElementById('modal-runtime-web-start-btn')?.setAttribute('disabled', '');
            if (button) {
                button.disabled = true;
                button.textContent = `${label} 요청 중…`;
                button.classList.add('modal-deployment-busy');
            }
            modalShowOperationLock(
                'deployment',
                `${label} 중`,
                customNodes
                    ? 'Custom Node 인벤토리를 반영한 강제 이미지 빌드를 요청하고 있습니다.'
                    : 'Modal 작업 App과 웹 App의 기본 재배포를 요청하고 있습니다.',
            );
            modalUpdateOperationProgress(10, '배포 요청 중', `${label} 요청을 서버에 전달하고 있습니다.`);
            modalRenderDeploymentProgress({state: 'idle'});
            try {
                const data = await fetchJSON(endpoint, {method: 'POST'});
                const deployment = data.deployment || {};
                modalDeploymentRequestStartedAt = Number(deployment.started_at || 0) * 1000
                    || modalDeploymentRequestStartedAt;
                _modalDeploymentWasRunning = deployment.state === 'running';
                modalRenderDeploymentProgress(deployment);
                modalSyncOperationLock({deployment});
                const status = document.getElementById('modal-runtime-deployment-status');
                if (status) status.textContent = deployment.message || `${label}를 시작했습니다.`;
                showToast(deployment.message || `${label}를 시작했습니다`, 'success');
                modalRuntimeStartPolling();
            } catch (error) {
                const elapsedSeconds = Math.max(0, (Date.now() - modalDeploymentRequestStartedAt) / 1000);
                modalDeploymentRequestPending = false;
                modalDeploymentPendingKind = '';
                modalDeploymentRequestStartedAt = 0;
                console.error(`[MODAL_RUNTIME] ${label} 시작 실패:`, error);
                showToast(`${label} 시작 실패: ` + (error.message || error), 'error');
                modalRenderDeploymentProgress({
                    state: 'failed',
                    kind: customNodes ? 'custom_nodes' : 'redeploy',
                    phase: 'inventory',
                    message: `${label} 요청 실패: ` + (error.message || error),
                    elapsed_seconds: elapsedSeconds,
                    logs: [{time: Date.now() / 1000, source: 'error', message: error.message || String(error)}],
                });
                modalHideOperationLock();
                if (button) {
                    button.disabled = false;
                    button.textContent = '앱·Custom Node 재배포';
                    button.classList.remove('modal-deployment-busy');
                }
                void modalRuntimeRefresh(false);
            }
        }

        function modalRuntimeViewIsActive() {
            return comfyRuntimeActiveView === 'modal'
                && document.getElementById('settings-modal')?.classList.contains('visible')
                && document.getElementById('settings-tab-comfy_runtime')?.classList.contains('active');
        }

        function modalRuntimeScheduleLogPolling() {
            if (modalRuntimeLogPollTimer !== null) {
                window.clearTimeout(modalRuntimeLogPollTimer);
                modalRuntimeLogPollTimer = null;
            }
            if (!modalRuntimeViewIsActive() || !modalWorkerFeatureEnabled) return;
            modalRuntimeLogPollTimer = window.setTimeout(
                () => void modalRuntimeRefreshLogs(false),
                MODAL_RUNTIME_LOG_REFRESH_MS,
            );
        }

        function modalRuntimeStopPolling() {
            if (modalRuntimePollTimer !== null) {
                window.clearTimeout(modalRuntimePollTimer);
                modalRuntimePollTimer = null;
            }
            if (modalRuntimeLogPollTimer !== null) {
                window.clearTimeout(modalRuntimeLogPollTimer);
                modalRuntimeLogPollTimer = null;
            }
        }

        function modalRuntimeStartPolling() {
            modalRuntimeStopPolling();
            if (modalRuntimeViewIsActive()) {
                void modalRuntimeRefresh(false);
                if (modalWorkerFeatureEnabled) void modalRuntimeRefreshLogs(false);
            }
        }

        async function modalRuntimeRefresh(showResult = false) {
            if (modalRuntimePollBusy) return;
            if (modalRuntimePollTimer !== null) {
                window.clearTimeout(modalRuntimePollTimer);
                modalRuntimePollTimer = null;
            }
            modalRuntimePollBusy = true;
            let keepPolling = true;
            try {
                const data = await fetchJSON('/api/modal/status?runtime=1');
                modalApplyStatus(data, showResult);
                keepPolling = data.settings?.enabled === true;
                if (!keepPolling) {
                    modalRuntimeStopPolling();
                    console.debug('[MODAL_RUNTIME] Modal OFF 상태로 자동 상태 조회를 중지합니다.');
                }
            } catch (error) {
                console.error('[MODAL_RUNTIME] 런타임 상태 조회 실패:', error);
                const state = document.getElementById('modal-runtime-state');
                if (state) {
                    state.textContent = '● 상태 조회 실패';
                    state.classList.remove('running');
                }
                if (showResult) showToast('Modal 런타임 상태 조회 실패: ' + (error.message || error), 'error');
            } finally {
                modalRuntimePollBusy = false;
                if (keepPolling && modalRuntimeViewIsActive()) {
                    const refreshInput = document.getElementById('modal-runtime-status-refresh');
                    const seconds = Math.max(2, Math.min(60, Number(refreshInput?.value || 5)));
                    modalRuntimePollTimer = window.setTimeout(
                        () => void modalRuntimeRefresh(false),
                        seconds * 1000,
                    );
                }
            }
        }

        async function modalRuntimeSaveAndApply() {
            const saved = await saveSettings();
            if (saved !== true) {
                console.error('[MODAL_RUNTIME] 설정 저장이 완료되지 않아 autoscaler 적용을 중단합니다.');
                return;
            }
            modalRuntimeStartPolling();
        }

        async function modalRuntimeStartProbe() {
            const button = document.getElementById('modal-runtime-probe-btn');
            const workerGpu = modalSelectedGpuMeta('modal-runtime-worker-gpu').id;
            if (button) button.disabled = true;
            try {
                await fetchJSON('/api/modal/probe', { method: 'POST' });
                showToast(`Modal ${workerGpu} CUDA·SageAttention 연결 테스트를 시작했습니다`, 'success');
                modalRuntimeStartPolling();
            } catch (error) {
                console.error(`[MODAL_RUNTIME] ${workerGpu} 연결 테스트 시작 실패:`, error);
                showToast(`${workerGpu} 연결 테스트 실패: ` + (error.message || error), 'error');
                if (button) button.disabled = false;
            }
        }

        function modalOpenExternalSettings() {
            switchSettingsTab('api');
            window.setTimeout(() => {
                document.getElementById('modal-external-api-group')?.scrollIntoView({behavior: 'smooth', block: 'start'});
            }, 80);
        }

        // ─── 설정 모달 탭 전환 ───
        function switchSettingsTab(tabName) {
            document.querySelectorAll('.settings-tab-btn').forEach(btn => btn.classList.remove('active'));
            document.querySelectorAll('.settings-tab-panel').forEach(panel => panel.classList.remove('active'));
            const targetBtn = document.querySelector(`.settings-tab-btn[onclick*="'${tabName}'"]`);
            targetBtn.classList.add('active');
            document.getElementById('settings-tab-' + tabName).classList.add('active');
            document.getElementById('settings-modal')?.classList.toggle(
                'character-maker-layout',
                tabName === 'character_maker',
            );
            document.getElementById('settings-modal')?.classList.toggle(
                'comfy-installer-layout',
                tabName === 'comfy_install',
            );
            document.getElementById('settings-modal')?.classList.toggle(
                'comfy-runtime-layout',
                tabName === 'comfy_runtime',
            );
            document.getElementById('settings-modal')?.classList.toggle(
                'queue-priority-layout',
                tabName === 'queue',
            );
            if (tabName === 'character_maker') {
                void cmRefreshRagArtifactStatus(false);
                void cmRefreshRagRuntimeStatus(false);
            }
            if (tabName === 'comfy_install') {
                void comfyInstallerRefreshStatus(true);
                void comfyInstallerLoadCivitaiKey();
                void comfyInstallerLoadWorkflowLibrary();
                void modalInstallerLoadCatalog();
                void modalRefreshStatus(false);
                if (!comfyInstallerPreflightLoaded) {
                    void comfyInstallerRunPreflight(true);
                }
            }
            if (tabName === 'comfy_runtime') {
                if (comfyRuntimeActiveView === 'modal') {
                    switchComfyRuntimeModal();
                } else if (comfyRuntimeActiveView === 'allocation') {
                    switchComfyRuntimeAllocation();
                } else if (comfyRuntimeActiveView === 'vast') {
                    switchComfyRuntimeVast();
                } else if (comfyRuntimeActiveView === 'video_engine') {
                    switchComfyRuntimeVideoEngine();
                } else {
                    switchComfyRuntimeInstance(comfyRuntimeActiveInstance);
                }
            } else {
                comfyRuntimeStopPolling();
                modalRuntimeStopPolling();
                stopVastLaunchPolling();
                videoEngineStopPolling();
            }
            // 활성 탭이 보이도록 최소 스크롤.
            // 이전에는 활성 탭을 우측 끝으로 밀어붙이는(scrollTo right) 로직 때문에,
            // 우측 탭을 누를 때마다 탭 바가 우측으로 계속 밀려 좌측 탭이 잘리고
            // debug→common 복귀 시에도 sl=57에 멈춰 0으로 돌아오지 않는
            // "우측 드리프트"가 발생했다. inline:'nearest' 는 탭이 보이지 않을
            // 때만 최소한으로 스크롤하므로 드리프트가 사라진다.
            // (상위 modal-content/modal-body 는 overflow-x:clip 이라 가로 스크롤
            //  컨테이너가 아니므로 scrollIntoView 가 가로로 끌고 가지 않고
            //  settings-tab-scroll 만 가로 스크롤한다.)
            if (targetBtn) {
                targetBtn.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'nearest' });
                setTimeout(updateSettingsTabArrows, 300);
            }
            // 탭 전환 시 모든 자동완성 닫기
            document.querySelectorAll('.autocomplete-list').forEach(list => list.classList.remove('visible'));
        }

        // ─── 설정 모달 탭 스크롤 화살표 ───
        function scrollSettingsTabs(dir) {
            const scroll = document.getElementById('settings-tab-scroll');
            if (!scroll) return;
            scroll.scrollBy({ left: dir * 200, behavior: 'smooth' });
        }
        function updateSettingsTabArrows() {
            const scroll = document.getElementById('settings-tab-scroll');
            if (!scroll) return;
            const prev = document.getElementById('settings-tab-prev');
            const next = document.getElementById('settings-tab-next');
            if (prev) prev.disabled = scroll.scrollLeft <= 0;
            if (next) next.disabled = scroll.scrollLeft + scroll.clientWidth >= scroll.scrollWidth - 1;
        }

        // ─── 설정 모달 ───
        // Form이 실제 설정값으로 채워졌는지 여부를 확인합니다.
        // saveSettings()는 DOM 전체를 읽어오기 때문에, Form이 초기화되기 전에 저장하면
        // Workflow 경로, comfy_task_allocations 등 수십 개의 키가 HTML 기본값으로 덮어씌워져
        // 기존 설정이 유실될 수 있습니다.
        let settingsFormPopulated = false;

        function updateVideoEncodingDefaultControls() {
            const gpuEnabled = document.getElementById('setting-video-avif-gpu-enabled');
            const gpuPreset = document.getElementById('setting-video-avif-gpu-preset');
            if (!gpuEnabled || !gpuPreset) {
                console.error('[VIDEO_SETTINGS] AVIF GPU 인코딩 설정 컨트롤을 찾지 못했습니다.', {
                    gpuEnabled: !!gpuEnabled,
                    gpuPreset: !!gpuPreset,
                });
                return;
            }
            gpuPreset.disabled = !gpuEnabled.checked;
        }

        // Modal을 열지 않고 저장하는 경우(예: Modal Runtime의 '설정 저장·적용')를 대비해,
        // 저장 전 반드시 Form을 현재 값으로 채우도록 처리합니다.
        async function populateSettingsForm() {
            settingsFormPopulated = false;
            // 현재 설정 로드
            try {
                currentConfig = await loadCurrentConfig(true);
            } catch (e) {
                console.error('설정 로드 실패:', e);
                throw e;
            }
            await loadLlmServiceCatalog();

            // 폼에 값 설정
            document.getElementById('setting-comfyui-port').value = currentConfig.comfyui_port || 8188;
            document.getElementById('setting-comfyui-port-2').value = currentConfig.comfyui_port_2
                || currentConfig.comfyui_port_illustration
                || 8187;
            document.getElementById('setting-comfyui-port-3').value = currentConfig.comfyui_port_3 || 8186;
            document.getElementById('setting-video-engine-port').value = currentConfig.video_engine_port || 8093;
            document.getElementById('setting-video-engine-project-path').value = currentConfig.video_engine_project_path || '';
            document.getElementById('setting-video-engine-auto-start').checked = currentConfig.video_engine_auto_start === true;
            const videoEngineSteps = document.getElementById('setting-video-engine-steps');
            videoEngineSteps.value = String(currentConfig.video_engine_steps ?? 4);
            videoEngineSteps.dataset.editableSteps = String(currentConfig.video_engine_steps ?? 4);
            videoEngineSetPendingProfile(currentConfig.video_engine_profile || '');
            const memoEnabled = currentConfig.memo_enabled !== false;
            document.getElementById('setting-memo-enabled').checked = memoEnabled;
            updateMemoSettingStatus(memoEnabled);
            comfyRuntimeInitializeProfiles(currentConfig);
            comfyAllocationInitialize(currentConfig);
            const modalEnabled = !!currentConfig.modal_enabled;
            const modalEnabledEl = document.getElementById('setting-modal-enabled');
            if (modalEnabledEl) modalEnabledEl.checked = modalEnabled;
            updateModalEnabledStatus(modalEnabled);
            const vastEnabled = !!currentConfig.vast_enabled;
            const vastEnabledEl = document.getElementById('setting-vast-enabled');
            if (vastEnabledEl) vastEnabledEl.checked = vastEnabled;
            updateVastEnabledStatus(vastEnabled);
            const modalProfileEl = document.getElementById('setting-modal-profile');
            if (modalProfileEl) modalProfileEl.value = currentConfig.modal_profile || 'soya-comfy';
            const modalEnvironmentEl = document.getElementById('setting-modal-environment');
            if (modalEnvironmentEl) modalEnvironmentEl.value = currentConfig.modal_environment || 'main';
            const modalDeploymentEl = document.getElementById('setting-modal-deployment-name');
            if (modalDeploymentEl) modalDeploymentEl.value = currentConfig.modal_deployment_name || 'soya-comfy-worker';
            const modalModelSourceEl = document.getElementById('setting-modal-model-source');
            if (modalModelSourceEl) modalModelSourceEl.value = currentConfig.modal_model_source || 'local_first';
            modalSetGpuSelectValue(
                'modal-runtime-worker-gpu',
                currentConfig.modal_worker_gpu || currentConfig.modal_gpu || 'L4',
            );
            modalSetGpuSelectValue(
                'modal-runtime-web-gpu',
                currentConfig.modal_web_gpu || currentConfig.modal_gpu || 'L4',
            );
            const modalConcurrencyEl = document.getElementById('modal-runtime-max-concurrency');
            if (modalConcurrencyEl) modalConcurrencyEl.value = currentConfig.modal_max_concurrency ?? 2;
            const modalStartRetriesEl = document.getElementById('modal-runtime-container-start-max-retries');
            if (modalStartRetriesEl) modalStartRetriesEl.value = currentConfig.modal_container_start_max_retries ?? 2;
            const modalScaledownEl = document.getElementById('modal-runtime-scaledown-window');
            if (modalScaledownEl) modalScaledownEl.value = currentConfig.modal_scaledown_window_seconds ?? 15;
            const modalRefreshEl = document.getElementById('modal-runtime-status-refresh');
            if (modalRefreshEl) modalRefreshEl.value = currentConfig.modal_status_refresh_seconds ?? 5;
            const modalWebFastEl = document.getElementById('modal-runtime-web-fast');
            if (modalWebFastEl) modalWebFastEl.checked = currentConfig.modal_web_fast === true;
            const modalVramModeEl = document.getElementById('modal-runtime-vram-mode');
            if (modalVramModeEl) modalVramModeEl.value = currentConfig.modal_vram_mode || 'highvram';
            const vastVramModeEl = document.getElementById('setting-vast-vram-mode');
            if (vastVramModeEl) vastVramModeEl.value = currentConfig.vast_vram_mode || 'highvram';
            const modalCreditEl = document.getElementById('setting-modal-monthly-credit');
            if (modalCreditEl) modalCreditEl.value = currentConfig.modal_monthly_credit_usd ?? 30;
            modalSyncRuntimeControls('runtime');
            void modalRefreshStatus(false);
            document.getElementById('setting-send-original').checked = currentConfig.send_original || false;
            document.getElementById('setting-webp-quality').disabled = currentConfig.send_original || false;
            document.getElementById('setting-webp-quality').value = currentConfig.webp_quality || 85;
            document.getElementById('quality-value').textContent = currentConfig.webp_quality || 85;
            document.getElementById('setting-backup-webp-quality').value = currentConfig.backup_webp_quality || 80;
            document.getElementById('backup-quality-value').textContent = currentConfig.backup_webp_quality || 80;
            document.getElementById('setting-backup-webp-lossless').checked = currentConfig.backup_webp_lossless || false;
            document.getElementById('setting-backup-webp-quality').disabled = currentConfig.backup_webp_lossless || false;
            const videoEncodingDefaults = currentConfig.video_postprocess || {};
            document.getElementById('setting-video-webp-compression-level').value =
                String(videoEncodingDefaults.webp_compression_level ?? 4);
            document.getElementById('setting-video-avif-gpu-enabled').checked =
                videoEncodingDefaults.avif_gpu_enabled === true;
            document.getElementById('setting-video-avif-gpu-preset').value =
                videoEncodingDefaults.avif_gpu_preset || 'p4';
            updateVideoEncodingDefaultControls();

            // 선택된 삽화 프로필의 로컬 워크플로우 경로를 베이스 경로/파일명으로 분리
            const illustrationPaths = currentConfig.illustration_workflow_source_paths || {};
            const initialIllustrationType = normalizeIllustrationWorkflowType(currentConfig.illustration_workflow_type);
            const initialLocalProfile = illustrationLocalProfile(initialIllustrationType);
            const workflowPath = (initialLocalProfile && illustrationPaths[initialLocalProfile])
                || currentConfig.comfy_workflow_source_path || '';
            const pathParts = splitWorkflowPath(workflowPath);
            document.getElementById('setting-workflow-base-dir').value =
                currentConfig.workflow_base_dir || pathParts.baseDir;
            document.getElementById('setting-workflow-path').value = workflowPath;
            for (const profile of ['v3', 'v3_anima']) {
                const profilePath = illustrationPaths[profile]
                    || (profile === initialLocalProfile ? workflowPath : '');
                const profileParts = splitWorkflowPath(profilePath);
                document.getElementById(`setting-illustration-${profile.replace('_', '-')}-workflow-filename`).value = profileParts.filename;
                document.getElementById(`setting-illustration-${profile.replace('_', '-')}-workflow-source-path`).value = profilePath;
            }
            applyIllustrationProviderConfig(currentConfig);

            // 삽화 유틸리티 워크플로우 경로를 파일명으로 분리
            const utilityPath = currentConfig.utility_workflow_source_path || '';
            const utilityParts = splitWorkflowPath(utilityPath);
            document.getElementById('setting-utility-filename').value = utilityParts.filename;
            document.getElementById('setting-utility-workflow-source-path').value = utilityPath;

            document.getElementById('setting-comfy-input-dir').value = currentConfig.comfy_input_dir || '';
            refreshAutoPathField(
                'setting-workflow-base-dir',
                '워크플로우 팩을 먼저 가져오세요',
                '"삽화 워크플로 가져오기"로 팩을 임포트하면 자동으로 채워집니다.'
            );
            refreshAutoPathField(
                'setting-comfy-input-dir',
                'ComfyUI를 먼저 설치/업데이트하세요',
                'ComfyUI 설치·업데이트를 실행하면 자동으로 채워집니다.'
            );
            document.getElementById('setting-backup-dir').value = currentConfig.backup_base_dir || '';
            document.getElementById('setting-backup-max-count').value = currentConfig.backup_max_count || 500;

            // 가중치 클램프 설정
            const clampEnabled = currentConfig.clamp_enabled || false;
            document.getElementById('setting-clamp-enabled').checked = clampEnabled;
            document.getElementById('setting-clamp-value').value = currentConfig.clamp_value || 1.2;
            document.getElementById('clamp-value-row').style.display = clampEnabled ? 'flex' : 'none';
            updateClampStatus(clampEnabled);

            // LLM1~N 슬롯 설정. LLM1만 기존 config 계약 때문에 접미사가 없다.
            ensureLlmCustomHeaderFields();
            for (const slot of LLM_SLOTS) {
                const suffix = llmSlotSuffix(slot);
                const el = id => document.getElementById(id);
                const configValue = (base, fallback) => (
                    currentConfig[`${base}${suffix}`] ?? fallback
                );
                const serviceEl = el(`setting-llm-service${suffix}`);
                if (serviceEl) setLlmServiceSelection(slot, configValue('llm_service', 'openai'));
                const modelEl = el(`setting-llm-model${suffix}`);
                if (modelEl) modelEl.value = configValue('llm_model', '');
                const aliasEl = el(`setting-llm-alias${suffix}`);
                if (aliasEl) aliasEl.value = configValue('llm_alias', '');
                const streamEnabled = !!configValue('llm_stream', false);
                const streamEl = el(`setting-llm-stream${suffix}`);
                if (streamEl) streamEl.checked = streamEnabled;
                updateLlmStreamStatus(slot, streamEnabled);
                const visionCompress = !!configValue('llm_vision_compress', false);
                const visionEl = el(`setting-llm-vision-compress${suffix}`);
                if (visionEl) visionEl.checked = visionCompress;
                updateLlmVisionCompressStatus(slot, visionCompress);
                const geminiBase64 = !!configValue('llm_gemini_base64', false);
                const geminiBase64El = el(`setting-llm-gemini-base64${suffix}`);
                if (geminiBase64El) geminiBase64El.checked = geminiBase64;
                updateLlmGeminiBase64Status(slot, geminiBase64);
                const pdfPrompt = !!configValue('llm_pdf_prompt', false);
                const pdfPromptEl = el(`setting-llm-pdf-prompt${suffix}`);
                if (pdfPromptEl) pdfPromptEl.checked = pdfPrompt;
                const pdfFormatEl = el(`setting-llm-pdf-prompt-format${suffix}`);
                if (pdfFormatEl) pdfFormatEl.value = configValue('llm_pdf_prompt_format', 'pdf') === 'image' ? 'image' : 'pdf';
                updateLlmPdfPromptStatus(slot, pdfPrompt);
                const urlEl = el(`setting-llm-url${suffix}`);
                if (urlEl) urlEl.value = configValue('llm_url', '');
                const maxTokensEl = el(`setting-llm-max-tokens${suffix}`);
                if (maxTokensEl) maxTokensEl.value = configValue('llm_max_tokens', 0);
                const temperatureEl = el(`setting-llm-temperature${suffix}`);
                if (temperatureEl) temperatureEl.value = configValue('llm_temperature', 1.0);
                const concurrencyEl = el(`setting-llm-max-concurrency${suffix}`);
                if (concurrencyEl) concurrencyEl.value = configValue('llm_max_concurrency', 1);
                const idleEl = el(`setting-llm-stream-idle-timeout${suffix}`);
                if (idleEl) idleEl.value = configValue('llm_stream_idle_timeout_seconds', 90);
                const presetEl = el(`setting-llm-reasoning-preset${suffix}`);
                if (presetEl) presetEl.value = configValue('llm_reasoning_preset', 'auto') || 'auto';
                const effortEl = el(`setting-llm-reasoning-effort${suffix}`);
                if (effortEl) effortEl.value = configValue('llm_reasoning_effort', '');
                const bodyEl = el(`setting-llm-custom-body${suffix}`);
                if (bodyEl) bodyEl.value = configValue('llm_custom_body', '');
                const headersEl = el(`setting-llm-custom-headers${suffix}`);
                if (headersEl) headersEl.value = configValue('llm_custom_headers', '');
            }
            const chansubRetriesEl = document.getElementById('setting-chansub-max-retries');
            if (chansubRetriesEl) chansubRetriesEl.value = (currentConfig.chansub_max_retries ?? 2);
            const chansubRetryDelayEl = document.getElementById('setting-chansub-retry-delay');
            if (chansubRetryDelayEl) chansubRetryDelayEl.value = (currentConfig.chansub_retry_delay_sec ?? 3.0);
            const chansubConcurrencyEl = document.getElementById('setting-chansub-max-concurrency');
            if (chansubConcurrencyEl) chansubConcurrencyEl.value = (currentConfig.chansub_max_concurrency ?? 1);
            const chansubStripQualityTags = currentConfig.chansub_strip_builtin_quality_tags !== false;
            const chansubStripQualityTagsEl = document.getElementById('setting-chansub-strip-builtin-quality-tags');
            if (chansubStripQualityTagsEl) chansubStripQualityTagsEl.checked = chansubStripQualityTags;
            updateChansubStripQualityTagsStatus(chansubStripQualityTags);
            for (const slot of LLM_SLOTS) {
                renderReasoningControls(slot);
            }
            onLlmServiceChange();

            // LLM API 키 별도 로드 (key/llm_keys.json)
            loadLlmKeys();
            // 챈섭 API 키 별도 로드 (key/chansub_key.json)
            loadChansubKey();
            // Vast API 키 별도 로드 (key/vast_key.json)
            loadVastKey();

            // 외부 LLM 분기(작업별 LLM1/LLM2 라우팅) 테이블 빌드
            renderLlmRoutingTable();
            switchLlmRoutingMode('easy');

            // LoRA 프롬프트 2차 검수 설정
            const loraPromptReviewEnabled = !!currentConfig.lora_prompt_review_enabled;
            const loraPromptReviewEnabledEl = document.getElementById('setting-lora-prompt-review-enabled');
            if (loraPromptReviewEnabledEl) {
                loraPromptReviewEnabledEl.checked = loraPromptReviewEnabled;
            } else {
                console.error('[SETTINGS] LoRA 프롬프트 2차 검수 토글 요소가 없습니다.');
            }
            updateLoraPromptReviewStatus(loraPromptReviewEnabled);

            // 캐릭터 메이커 내장 RAG 설정
            const cmRagEnabled = !!currentConfig.character_maker_rag_enabled;
            const cmRagEnabledEl = document.getElementById('setting-character-maker-rag-enabled');
            if (cmRagEnabledEl) cmRagEnabledEl.checked = cmRagEnabled;
            updateCharacterMakerRagSettingStatus(cmRagEnabled);
            const cmRagAutostart = !!currentConfig.character_maker_rag_autostart;
            const cmRagAutostartEl = document.getElementById('setting-character-maker-rag-autostart');
            if (cmRagAutostartEl) cmRagAutostartEl.checked = cmRagAutostart;
            updateCharacterMakerRagAutostartStatus(cmRagAutostart);
            const cmRagTopKEl = document.getElementById('setting-character-maker-rag-top-k');
            if (cmRagTopKEl) cmRagTopKEl.value = currentConfig.character_maker_rag_top_k ?? 5;
            const cmRagThresholdEl = document.getElementById('setting-character-maker-rag-threshold');
            if (cmRagThresholdEl) cmRagThresholdEl.value = currentConfig.character_maker_rag_threshold ?? 0;
            const cmRagTimeoutEl = document.getElementById('setting-character-maker-rag-timeout');
            if (cmRagTimeoutEl) cmRagTimeoutEl.value = currentConfig.character_maker_rag_timeout_sec ?? 20;
            void cmRefreshRagArtifactStatus(false);
            void cmRefreshRagRuntimeStatus(false);

            // 임베딩 설정
            const embProvider = currentConfig.embedding_provider || 'voyage';
            document.getElementById('setting-embedding-provider').value = embProvider;
            document.getElementById('setting-embedding-url').value = currentConfig.embedding_url || '';
            document.getElementById('setting-embedding-api-key').value = currentConfig.embedding_api_key || '';
            document.getElementById('setting-embedding-model').value = currentConfig.embedding_model || 'voyage-4-large';
            onEmbeddingProviderChange();

            // 삽화 모드: 항상 ON 고정 (서버가 True 강제). 토글은 비활성화.
            document.getElementById('bot-mode-toggle').checked = true;
            updateBotModeStatus(true);
            // 디버깅 모드 설정
            const debugModeEnabled = currentConfig.debug_mode_enabled || false;
            document.getElementById('debug-mode-toggle').checked = debugModeEnabled;
            updateDebugModeStatus(debugModeEnabled);
            // 후처리([SPEAK]) 모드 설정
            const postprocessEnabled = currentConfig.postprocess_enabled || false;
            const ppToggle = document.getElementById('postprocess-toggle');
            if (ppToggle) ppToggle.checked = postprocessEnabled;
            updatePostprocessStatus(postprocessEnabled);
            // 삽화 모드 선택 봇 복원
            const botSelected = currentConfig.bot_selected || '';
            if (botSelected) {
                botCurrentBot = botSelected;
                const botSelect = document.getElementById('bot-select');
                if (botSelect) botSelect.value = botSelected;
            }
            // 프롬프트 파일 목록 로드
            await loadCustompromptFiles();

            // 워크플로우 복원 프롬프트 파일 목록 로드
            await loadRestorePromptFiles();
            // loadRestorePromptFiles가 현재 삽화 프로필과 호환되는 값만 자동 선택한다.

            // 워크플로우 복원 프롬프트 수동 작동 설정
            const restoreManualEnabled = currentConfig.restore_manual_enabled || false;
            document.getElementById('setting-restore-manual-enabled').checked = restoreManualEnabled;
            updateRestoreManualStatus(restoreManualEnabled);

            // 프롬프트 강화 모드 설정
            const enhanceEnabled = currentConfig.enhance_mode_enabled || false;
            document.getElementById('setting-enhance-enabled').checked = enhanceEnabled;
            updateEnhanceStatus(enhanceEnabled);
            // 강화 프롬프트 파일 목록 로드 (customprompt 파일과 공유)
            document.getElementById('setting-enhance-prompt-file').value = currentConfig.enhance_prompt_file || '';

            // 에셋 생성 모드
            const assetPath = currentConfig.asset_workflow_source_path || '';
            const assetSplit = splitWorkflowPath(assetPath);
            document.getElementById('setting-asset-workflow-filename').value = assetSplit.filename;
            document.getElementById('setting-asset-workflow-source-path').value = assetPath;

            // ANIMA 에셋 생성 모드
            const animaAssetPath = currentConfig.anima_asset_workflow_source_path || '';
            const animaAssetSplit = splitWorkflowPath(animaAssetPath);
            document.getElementById('setting-anima-asset-workflow-filename').value = animaAssetSplit.filename;
            document.getElementById('setting-anima-asset-workflow-source-path').value = animaAssetPath;

            // ONLY ANIMA 에셋 생성 모드
            const animaOnlyAssetPath = currentConfig.anima_only_asset_workflow_source_path || '';
            const animaOnlyAssetSplit = splitWorkflowPath(animaOnlyAssetPath);
            document.getElementById('setting-anima-only-asset-workflow-filename').value = animaOnlyAssetSplit.filename;
            document.getElementById('setting-anima-only-asset-workflow-source-path').value = animaOnlyAssetPath;

            // EDIT 툴 및 ANIMA Inpainting 워크플로우
            const animaInpaintingPath =
                currentConfig.anima_inpainting_workflow_source_path || '';
            const animaInpaintingSplit = splitWorkflowPath(animaInpaintingPath);
            document.getElementById('setting-anima-inpainting-workflow-filename').value =
                animaInpaintingSplit.filename;
            document.getElementById('setting-anima-inpainting-workflow-source-path').value =
                animaInpaintingPath;

            // 워크플로우 타입
            const workflowType = normalizeAssetWorkflowType(currentConfig.asset_workflow_type);
            document.getElementById('setting-workflow-type-select').value = workflowType;
            onWorkflowTypeChange(workflowType);

            // 태그 분석 모드
            const tagAnalysisPath = currentConfig.tag_analysis_workflow_source_path || '';
            const tagAnalysisSplit = splitWorkflowPath(tagAnalysisPath);
            document.getElementById('setting-tag-analysis-workflow-filename').value = tagAnalysisSplit.filename;
            document.getElementById('setting-tag-analysis-workflow-source-path').value = tagAnalysisPath;

            // 내장 WD Tagger 사용 여부
            document.getElementById('setting-use-builtin-tagger').checked = !!(currentConfig.use_builtin_tagger);
            onUseBuiltinTaggerChange(!!(currentConfig.use_builtin_tagger));

            // 에셋용 태그 분석 모드
            const assetTagAnalysisPath = currentConfig.asset_tag_analysis_workflow_source_path || '';
            const assetTagAnalysisSplit = splitWorkflowPath(assetTagAnalysisPath);
            document.getElementById('setting-asset-tag-analysis-workflow-filename').value = assetTagAnalysisSplit.filename;
            document.getElementById('setting-asset-tag-analysis-workflow-source-path').value = assetTagAnalysisPath;

            // 영상 워크플로우 (일반/고속 I2V / FLF2V / REF2V)
            const videoWorkflowPaths = currentConfig.video_workflow_source_paths || {};
            for (const mode of [
                'i2v', 'first_last', 'ref2v',
                'i2v_fast', 'first_last_fast', 'ref2v_fast',
            ]) {
                const videoPath = videoWorkflowPaths[mode] || '';
                const videoSplit = splitWorkflowPath(videoPath);
                document.getElementById(`setting-video-${mode.replaceAll('_', '-')}-workflow-filename`).value =
                    videoSplit.filename;
                document.getElementById(`setting-video-${mode.replaceAll('_', '-')}-workflow-source-path`).value =
                    videoPath;
            }

            // 디버그 워크플로우
            const debugWfPath = currentConfig.debug_workflow_source_path || '';
            const debugWfSplit = splitWorkflowPath(debugWfPath);
            document.getElementById('setting-debug-workflow-filename').value = debugWfSplit.filename;
            document.getElementById('setting-debug-workflow-source-path').value = debugWfPath;

            // 로라 학습 워크플로우 (profile별)
            const loraPaths = currentConfig.lora_training_workflow_source_paths || {};
            // Anima
            const loraAnimaPath = loraPaths.anima || '';
            const loraAnimaSplit = splitWorkflowPath(loraAnimaPath);
            document.getElementById('setting-lora-workflow-anima-filename').value = loraAnimaSplit.filename;
            document.getElementById('setting-lora-workflow-anima-source-path').value = loraAnimaPath;
            // SDXL
            const loraSdxlPath = loraPaths.sdxl || '';
            const loraSdxlSplit = splitWorkflowPath(loraSdxlPath);
            document.getElementById('setting-lora-workflow-sdxl-filename').value = loraSdxlSplit.filename;
            document.getElementById('setting-lora-workflow-sdxl-source-path').value = loraSdxlPath;

            // 스타일로라 학습 워크플로우 (profile별)
            const styleLoraPaths = currentConfig.style_lora_training_workflow_source_paths || {};
            // Anima
            const styleLoraAnimaPath = styleLoraPaths.anima || '';
            const styleLoraAnimaSplit = splitWorkflowPath(styleLoraAnimaPath);
            document.getElementById('setting-style-lora-workflow-anima-filename').value = styleLoraAnimaSplit.filename;
            document.getElementById('setting-style-lora-workflow-anima-source-path').value = styleLoraAnimaPath;
            // SDXL
            const styleLoraSdxlPath = styleLoraPaths.sdxl || '';
            const styleLoraSdxlSplit = splitWorkflowPath(styleLoraSdxlPath);
            document.getElementById('setting-style-lora-workflow-sdxl-filename').value = styleLoraSdxlSplit.filename;
            document.getElementById('setting-style-lora-workflow-sdxl-source-path').value = styleLoraSdxlPath;

            // 얼굴 추출 워크플로우
            const faceExtractPath = currentConfig.face_extract_workflow_source_path || '';
            const faceExtractSplit = splitWorkflowPath(faceExtractPath);
            document.getElementById('setting-face-extract-workflow-filename').value = faceExtractSplit.filename;
            document.getElementById('setting-face-extract-workflow-source-path').value = faceExtractPath;

            // 로라 폴더는 관리형 ComfyUI 설치의 models/loras로 고정된다. 표시만 한다.
            const loraLoadPath = currentConfig.lora_load_path || '';
            const loraFolderEl = document.getElementById('setting-lora-folder-path');
            if (loraFolderEl) {
                loraFolderEl.textContent = stripManagedLoraPath(loraLoadPath) || loraLoadPath || '-';
            }

            settingsFormPopulated = true;
        }

        async function openSettingsModal() {
            await populateSettingsForm();
            document.getElementById('settings-modal').classList.add('visible');
            // 큐 우선순위 리스트 렌더링
            renderQueueTypeList();
            // 항상 첫 번째 탭으로 시작
            switchSettingsTab('common');
        }

        // 워크플로우 경로를베이스 경로와 파일명으로 분리
        function splitWorkflowPath(fullPath) {
            if (!fullPath) {
                return { baseDir: '', filename: '' };
            }
            // 경로를 / 또는 \로 분리
            const normalized = fullPath.replace(/\//g, '\\');
            const lastSepIndex = Math.max(
                normalized.lastIndexOf('\\'),
                normalized.lastIndexOf('/')
            );
            if (lastSepIndex === -1) {
                return { baseDir: '', filename: fullPath };
            }
            return {
                baseDir: fullPath.substring(0, lastSepIndex),
                filename: fullPath.substring(lastSepIndex + 1)
            };
        }

        // 설치기/워크플로우 임포터가 관리하는 경로는 기본 잠금하고,
        // 명시적으로 직접 지정을 선택한 경우에만 편집을 허용한다.
        function toggleAutoPathField(inputId) {
            const input = document.getElementById(inputId);
            const checkbox = document.getElementById(inputId + '-manual');
            if (!input || !checkbox) {
                console.error('[SETTINGS] 자동 경로 필드 토글 대상 없음:', inputId, {
                    inputFound: !!input,
                    checkboxFound: !!checkbox
                });
                return;
            }
            input.disabled = !checkbox.checked;
            input.style.opacity = checkbox.checked ? '' : '0.6';
            if (checkbox.checked) input.focus();
        }

        function refreshAutoPathField(inputId, emptyMessage, emptyHint) {
            const input = document.getElementById(inputId);
            const checkbox = document.getElementById(inputId + '-manual');
            const hint = document.getElementById(inputId + '-hint');
            if (!input || !checkbox) {
                console.error('[SETTINGS] 자동 경로 필드 갱신 대상 없음:', inputId, {
                    inputFound: !!input,
                    checkboxFound: !!checkbox
                });
                return;
            }

            const hasValue = !!String(input.value || '').trim();
            checkbox.checked = false;
            input.disabled = true;
            input.style.opacity = '0.6';
            if (!hasValue) {
                input.placeholder = emptyMessage;
                if (hint) {
                    hint.textContent = emptyHint;
                    hint.style.color = 'var(--text-secondary)';
                }
            } else if (hint) {
                hint.textContent = '자동 설정됨 — 수정하려면 아래 "직접 지정"을 체크하세요.';
                hint.style.color = '';
            }
        }

        // 워크플로우 경로 업데이트
        function updateWorkflowPath() {
            for (const profile of ['v3', 'v3_anima']) {
                updateIllustrationWorkflowPath(profile);
            }
            // 베이스 경로 변경 시 에셋/로라/유틸리티 경로도 함께 갱신
            updateUtilityWorkflowPath();
            updateAssetWorkflowPath();
            updateAnimaAssetWorkflowPath();
            updateAnimaOnlyAssetWorkflowPath();
            updateAnimaInpaintingWorkflowPath();
            updateTagAnalysisWorkflowPath();
            updateAssetTagAnalysisWorkflowPath();
            updateVideoWorkflowPath('i2v');
            updateVideoWorkflowPath('first_last');
            updateVideoWorkflowPath('ref2v');
            updateVideoWorkflowPath('i2v_fast');
            updateVideoWorkflowPath('first_last_fast');
            updateVideoWorkflowPath('ref2v_fast');
            updateLoraAnimaWorkflowPath();
            updateLoraSdxlWorkflowPath();
            updateStyleLoraAnimaWorkflowPath();
            updateStyleLoraSdxlWorkflowPath();
            updateFaceExtractWorkflowPath();
            updateDebugWorkflowPath();
        }

        // 베이스 경로와 파일명을 결합
        function combineWorkflowPath(baseDir, filename) {
            if (!baseDir && !filename) return '';
            if (!baseDir) return filename;
            if (!filename) return baseDir;

            const isUnix = baseDir.startsWith('/');
            const sep = isUnix ? '/' : '\\';
            const normalizedBase = baseDir.replace(/[/\\]/g, sep);
            if (normalizedBase.endsWith(sep)) {
                return normalizedBase + filename;
            }
            return normalizedBase + sep + filename;
        }

        function stripManagedLoraPath(path) {
            return String(path || '').trim().replace(
                /[\\/]SOYA_(?:ASSET|BOT|STYLE)_LORA$/i,
                ''
            );
        }

        // 가중치 클램프 상태 업데이트
        function updateClampStatus(checked) {
            const statusEl = document.getElementById('clamp-status');
            const valueRow = document.getElementById('clamp-value-row');
            if (checked) {
                statusEl.textContent = 'ON';
                statusEl.className = 'toggle-status on';
                valueRow.style.display = 'flex';
            } else {
                statusEl.textContent = 'OFF';
                statusEl.className = 'toggle-status off';
                valueRow.style.display = 'none';
            }
        }

        function updateLoraPromptReviewStatus(checked) {
            const statusEl = document.getElementById('lora-prompt-review-status');
            if (!statusEl) {
                console.error('[SETTINGS] LoRA 프롬프트 2차 검수 상태 요소가 없습니다.');
                return;
            }
            statusEl.textContent = checked ? 'ON' : 'OFF';
            statusEl.className = 'toggle-status ' + (checked ? 'on' : 'off');
        }

