        function escapeQueuePriorityHtml(value) {
            return String(value ?? '')
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;')
                .replace(/'/g, '&#039;');
        }

        function getQueueSequenceSet(setId) {
            return QUEUE_SEQUENCE_SETS.find(sequenceSet => sequenceSet.id === setId) || null;
        }

        function renderQueueSequenceSets() {
            const container = document.getElementById('queue-sequence-set-list');
            if (!container) {
                console.error('[QUEUE_SETTINGS] 연속 실행 세트 컨테이너를 찾지 못했습니다');
                return;
            }
            container.innerHTML = '';
            QUEUE_SEQUENCE_SETS.forEach(sequenceSet => {
                const card = document.createElement('article');
                card.className = `queue-sequence-card${sequenceSet.fixed ? ' is-fixed' : ''}`;
                card.setAttribute('role', 'listitem');
                card.setAttribute('data-queue-set-id', sequenceSet.id);
                card.style.setProperty('--queue-set-color', sequenceSet.color);

                const stages = sequenceSet.steps.map((step, stepIndex) => {
                    const connector = stepIndex === 0
                        ? ''
                        : `<span class="queue-sequence-connector${step.relation === 'parallel' ? ' is-parallel' : ''}" aria-hidden="true">${step.relation === 'parallel' ? '∥' : '→'}</span>`;
                    const optionLabel = step.qualifier || (step.optional ? '선택' : '');
                    const option = optionLabel
                        ? `<em class="queue-sequence-step-option">${escapeQueuePriorityHtml(optionLabel)}</em>`
                        : '';
                    const accessibilityLabel = [
                        `${stepIndex + 1}단계`,
                        step.laneLabel,
                        step.label,
                        optionLabel ? `${optionLabel} 단계` : '',
                        stepIndex > 0 ? (step.relationLabel || '이전 단계 이후') : '',
                    ].filter(Boolean).join(' · ');
                    return `
                        <li class="queue-sequence-stage" aria-label="${escapeQueuePriorityHtml(accessibilityLabel)}">
                            ${connector}
                            <span class="queue-sequence-step"
                                  data-queue-step-type="${escapeQueuePriorityHtml(step.type)}"
                                  data-queue-step-lane="${escapeQueuePriorityHtml(step.lane)}">
                                <b class="queue-sequence-step-lane">${escapeQueuePriorityHtml(step.laneLabel)}</b>
                                <span class="queue-sequence-step-label">${escapeQueuePriorityHtml(step.label)}</span>
                                ${option}
                            </span>
                        </li>
                    `;
                }).join('');

                card.innerHTML = `
                    <div class="queue-sequence-card-head">
                        <span class="queue-sequence-number"><span class="queue-priority-visually-hidden">세트 </span>${escapeQueuePriorityHtml(sequenceSet.number)}</span>
                        <div class="queue-sequence-heading">
                            <div class="queue-sequence-title-line">
                                <span class="queue-sequence-title">${escapeQueuePriorityHtml(sequenceSet.label)}</span>
                                <span class="queue-sequence-state">${sequenceSet.fixed ? '0~9 고정' : '레인 연결'}</span>
                            </div>
                            <div class="queue-sequence-description">${escapeQueuePriorityHtml(sequenceSet.description)}</div>
                        </div>
                    </div>
                    <ol class="queue-sequence-flow" aria-label="${escapeQueuePriorityHtml(sequenceSet.label)} 실행 단계">
                        ${stages}
                    </ol>
                `;
                container.appendChild(card);
            });
        }

        // 각 레인의 독립 항목 + 고정 묶음 항목(분석→학습)을 현재 설정 순서로 반환.
        function getQueueGroups(laneKey) {
            const lane = QUEUE_PRIORITY_LANES[laneKey];
            if (!lane) {
                console.error('[QUEUE_SETTINGS] 알 수 없는 실행 레인:', laneKey);
                return [];
            }
            const orderMap = currentConfig[lane.configKey] || {};
            return lane.groups
                .map((group, defaultIndex) => ({
                    ...group,
                    types: [...group.types],
                    defaultIndex,
                    order: Math.min(...group.types.map(type => orderMap[type] ?? 999)),
                }))
                .sort((a, b) => (a.order - b.order) || (a.defaultIndex - b.defaultIndex));
        }

        function renderQueueTypeList() {
            renderQueueSequenceSets();
            renderQueuePriorityLane('gpu');
            renderQueuePriorityLane('llm');
        }

        function renderQueuePriorityGroupFlow(group, laneKey) {
            if (!Array.isArray(group.steps) || group.steps.length < 2) return '';
            return `
                <ol class="queue-priority-group-flow" aria-label="${escapeQueuePriorityHtml(group.label)} 고정 단계">
                    ${group.steps.map((step, stepIndex) => `
                        <li class="queue-priority-group-stage">
                            ${stepIndex === 0 ? '' : '<span class="queue-priority-group-connector" aria-hidden="true">→</span>'}
                            <span class="queue-priority-group-step"
                                  data-queue-step-type="${escapeQueuePriorityHtml(step.type)}"
                                  data-queue-step-lane="${escapeQueuePriorityHtml(laneKey)}">
                                <b class="queue-priority-group-step-lane">${laneKey === 'llm' ? 'LLM' : 'GPU'}</b>
                                <span class="queue-priority-group-step-label">${escapeQueuePriorityHtml(step.label)}</span>
                            </span>
                        </li>
                    `).join('')}
                </ol>
            `;
        }

        function renderQueuePriorityLane(laneKey) {
            const lane = QUEUE_PRIORITY_LANES[laneKey];
            const container = document.getElementById(lane?.containerId || '');
            if (!lane || !container) {
                console.error(
                    '[QUEUE_SETTINGS] 우선순위 목록 렌더링 실패:',
                    laneKey,
                    lane?.containerId,
                );
                return;
            }
            const groups = getQueueGroups(laneKey);
            container.innerHTML = '';
            let rank = 10;
            groups.forEach((group, gIdx) => {
                const isFirst = gIdx === 0;
                const isLast = gIdx === groups.length - 1;
                const rankEnd = rank + group.types.length - 1;
                const rankLabel = rankEnd === rank ? String(rank) : `${rank}–${rankEnd}`;
                const sequenceSet = getQueueSequenceSet(group.sequenceSetId);
                const setBadge = sequenceSet
                    ? `<span class="queue-priority-set-badge">세트 ${escapeQueuePriorityHtml(sequenceSet.number)}</span>`
                    : '';
                const lockBadge = group.locked
                    ? '<span class="queue-priority-lock-badge">고정 묶음</span>'
                    : '';

                const row = document.createElement('div');
                row.className = 'queue-priority-card';
                row.setAttribute('role', 'listitem');
                row.setAttribute('aria-label', `${rankLabel}순위 · ${group.label}`);
                row.setAttribute('data-queue-group-types', group.types.join(','));
                row.tabIndex = -1;
                if (sequenceSet) {
                    row.setAttribute('data-queue-set-id', sequenceSet.id);
                    row.style.setProperty('--queue-set-color', sequenceSet.color);
                }
                row.innerHTML = `
                    <span class="queue-priority-rank" aria-label="우선순위 ${escapeQueuePriorityHtml(rankLabel)}">${escapeQueuePriorityHtml(rankLabel)}</span>
                    <div class="queue-priority-card-main">
                        <div class="queue-priority-card-heading">
                            <span class="queue-priority-card-title">${escapeQueuePriorityHtml(group.label)}</span>
                            ${setBadge}
                            ${lockBadge}
                        </div>
                        <div class="queue-priority-card-description">${escapeQueuePriorityHtml(group.description || '')}</div>
                        ${renderQueuePriorityGroupFlow(group, laneKey)}
                    </div>
                    <div class="queue-priority-actions" role="group" aria-label="${escapeQueuePriorityHtml(group.label)} 우선순위 변경">
                        <button type="button"
                                data-move-direction="up"
                                onclick="moveQueueGroupUp('${laneKey}', ${gIdx})"
                                aria-label="${escapeQueuePriorityHtml(group.label)} 카드를 위로 이동"
                                title="위로 이동"
                                ${isFirst ? 'disabled' : ''}>▲</button>
                        <button type="button"
                                data-move-direction="down"
                                onclick="moveQueueGroupDown('${laneKey}', ${gIdx})"
                                aria-label="${escapeQueuePriorityHtml(group.label)} 카드를 아래로 이동"
                                title="아래로 이동"
                                ${isLast ? 'disabled' : ''}>▼</button>
                    </div>
                `;
                container.appendChild(row);
                rank = rankEnd + 1;
            });
        }


        function moveQueueGroupUp(laneKey, gIdx) {
            const groups = getQueueGroups(laneKey);
            if (gIdx <= 0) return;
            const movedGroup = groups[gIdx];
            [groups[gIdx - 1], groups[gIdx]] = [groups[gIdx], groups[gIdx - 1]];
            applyQueueTypeOrder(laneKey, groups);
            renderQueuePriorityLane(laneKey);
            announceQueueGroupMove(laneKey, movedGroup, gIdx - 1, 'up');
        }

        function moveQueueGroupDown(laneKey, gIdx) {
            const groups = getQueueGroups(laneKey);
            if (gIdx >= groups.length - 1) return;
            const movedGroup = groups[gIdx];
            [groups[gIdx], groups[gIdx + 1]] = [groups[gIdx + 1], groups[gIdx]];
            applyQueueTypeOrder(laneKey, groups);
            renderQueuePriorityLane(laneKey);
            announceQueueGroupMove(laneKey, movedGroup, gIdx + 1, 'down');
        }

        function announceQueueGroupMove(laneKey, group, newIndex, direction) {
            const liveRegion = document.getElementById('queue-priority-live');
            if (liveRegion) {
                liveRegion.textContent = `${group.label}, ${newIndex + 1}번째로 이동됨`;
            }
            const lane = QUEUE_PRIORITY_LANES[laneKey];
            const container = document.getElementById(lane?.containerId || '');
            if (!container) {
                console.error('[QUEUE_SETTINGS] 이동 후 포커스 복원 실패:', laneKey, group.types);
                return;
            }
            const groupKey = group.types.join(',');
            const movedCard = Array.from(container.querySelectorAll('.queue-priority-card'))
                .find(card => card.getAttribute('data-queue-group-types') === groupKey);
            if (!movedCard) {
                console.error('[QUEUE_SETTINGS] 이동한 카드를 찾지 못했습니다:', laneKey, groupKey);
                return;
            }
            const preferredButton = movedCard.querySelector(
                `[data-move-direction="${direction}"]:not(:disabled)`,
            );
            const fallbackButton = movedCard.querySelector('.queue-priority-actions button:not(:disabled)');
            (preferredButton || fallbackButton || movedCard).focus();
        }

        function applyQueueTypeOrder(laneKey, groups) {
            const lane = QUEUE_PRIORITY_LANES[laneKey];
            if (!lane) {
                console.error('[QUEUE_SETTINGS] 우선순위 저장 실패, 알 수 없는 레인:', laneKey);
                return;
            }
            const orderMap = {};
            groups
                .flatMap(group => group.types)
                .forEach((type, index) => {
                    orderMap[type] = index + 10;
                });
            currentConfig[lane.configKey] = orderMap;
        }

        // ─── 태그 분석 진행률 이벤트 처리 ───
        async function handleTagAnalysisProgress(data) {
            // 이미지별 분할 배치는 _handleTagBatchProgress가 처리 → 여기서는 폴백(자동매치/봇단일)만.
            if (data && data.batch_id) return;
            const source = data.source || '';
            const phase = data.phase || '';
            if (phase === 'completed') {
                // source별 완료 처리
                if (source === 'asset_batch') {
                    const statusEl = document.getElementById('au-analyze-status');
                    if (statusEl) statusEl.textContent = `완료: 성공 ${data.success_count}건, 실패 ${data.fail_count}건`;
                    if (typeof auSetAnalyzingState === 'function') auSetAnalyzingState(false);
                } else if (source === 'asset_selected') {
                    const statusEl = document.getElementById('au-analyze-status');
                    if (statusEl) statusEl.textContent = `완료: 성공 ${data.success_count}건, 실패 ${data.fail_count}건`;
                    if (typeof auSetAnalyzingState === 'function') auSetAnalyzingState(false);
                    if (typeof auNavLevel !== 'undefined' && auNavLevel >= 2 && auNavOutfit && auNavExpression) {
                        auRenderImages(auNavCharacter, auNavOutfit, auNavExpression);
                    }
                } else if (source === 'bot_rep') {
                    const statusEl = document.getElementById('bot-analyze-status');
                    if (statusEl) statusEl.textContent = `완료: 성공 ${data.success_count}건, 실패 ${data.fail_count}건`;
                    const btn = document.getElementById('bot-analyze-confirm-btn');
                    if (btn) { btn.disabled = false; btn.textContent = '선택 분석 실행'; }
                    if (typeof renderBotCharacters === 'function') renderBotCharacters();
                    if (botCurrentChar && typeof loadBotCharDetailImages === 'function') loadBotCharDetailImages(botCurrentChar);
                } else if (source === 'bot_utility') {
                    const statusEl = document.getElementById('bot-util-status');
                    if (statusEl) statusEl.textContent = `완료: 성공 ${data.success_count}건, 실패 ${data.fail_count}건`;
                    const btn = document.getElementById('btn-bot-util-analyze');
                    if (btn) { btn.disabled = false; btn.textContent = '선택 분석 실행'; }
                    if (typeof renderBotCharacters === 'function') renderBotCharacters();
                } else if (source === 'bot_single') {
                    // 단일 분석 결과를 전역 변수에 저장
                    window._pendingBotSingleResult = data;
                    const btn = window._pendingBotSingleBtn;
                    if (btn) { btn.disabled = false; btn.textContent = '태그 분석'; }
                    if (data.tags && data.prompt) {
                        const ta = window._pendingBotSingleTa;
                        if (ta) ta.value = data.prompt;
                        showToast(`태그 분석 완료 (${data.tags_count || 0}개)`, 'success');
                    }
                } else if (source === 'auto_match') {
                    // 개별 이미지 분석 완료
                    if (data.results) {
                        data.results.forEach(r => {
                            const img = atState.images.find(i => i.file && i.file.name === r.filename);
                            if (img) {
                                if (r.success) { img.tags = r.tags; img.status = 'done'; }
                                else { img.error = r.error || '분석 실패'; img.status = 'error'; }
                            }
                        });
                    }
                    if (typeof atRenderImages === 'function') atRenderImages();

                    atState.analyzeCompleted++;
                    const progressInner = document.getElementById('at-progress-inner');
                    if (progressInner && atState.analyzeTotal > 0) {
                        progressInner.style.width = Math.round((atState.analyzeCompleted / atState.analyzeTotal) * 100) + '%';
                    }

                    // 전체 분석 완료 확인
                    if (atState.analyzeCompleted >= atState.analyzeTotal) {
                        atState.queueItemIds = [];
                        const doMatch = document.getElementById('at-do-match');
                        if (doMatch && doMatch.checked) {
                            showToast('태그 분석 완료, 배치 매칭 시작...', 'info');
                            if (typeof atProceedToMatching === 'function') atProceedToMatching();
                        } else {
                            document.getElementById('at-analyze-btn').disabled = false;
                            document.getElementById('at-stop-btn').style.display = 'none';
                            setTimeout(() => { document.getElementById('at-progress-bar').style.display = 'none'; }, 500);
                            showToast('태그 분석 완료', 'success');
                        }
                    }
                } else if (source === 'instance_lora') {
                    if (typeof loadInstanceLoraGrid === 'function') loadInstanceLoraGrid();
                    showToast(`분석 완료: 성공 ${data.success_count}건, 실패 ${data.fail_count}건`, data.success_count > 0 ? 'success' : 'error');
                }
                return;
            }
            // 진행 중 표시
            if (phase === 'started') {
                if (source === 'auto_match' && typeof atRenderImages === 'function') atRenderImages();
            } else if (phase === 'analyzing') {
                if (source === 'asset_batch') {
                    const statusEl = document.getElementById('au-analyze-status');
                    if (statusEl) statusEl.textContent = `분석 중... (${data.current}/${data.total}) ${data.filename || ''}`;
                } else if (source === 'asset_selected') {
                    const statusEl = document.getElementById('au-analyze-status');
                    if (statusEl) statusEl.textContent = `분석 중... (${data.current}/${data.total}) ${data.filename || ''}`;
                } else if (source === 'bot_rep') {
                    const statusEl = document.getElementById('bot-analyze-status');
                    if (statusEl) statusEl.textContent = `분석 중... (${data.current}/${data.total})`;
                } else if (source === 'bot_utility') {
                    const statusEl = document.getElementById('bot-util-status');
                    if (statusEl) statusEl.textContent = `분석 중... (${data.current}/${data.total})`;
                } else if (source === 'auto_match') {
                    const total = data.total || 1;
                    const progressInner = document.getElementById('at-progress-inner');
                    if (progressInner) progressInner.style.width = `${(data.current / total) * 100}%`;
                    // auto_match는 per-image 업데이트를 completed에서만 함 (results 배열에 있을 때)
                }
            }
        }

        // ─── 일괄 태깅/정제 배치 추적 (이미지별 분할 큐 + 장당 디바운스 화면 갱신) ───
        // 완료 수와 단계 전환은 서버 큐의 배치 집계로만 결정한다.
        // 개별 이미지 이벤트는 디바운스 화면 갱신에만 사용한다.
        const _tagBatches = {};

        function _tagBatchStatusEl(source) {
            const m = {
                'asset_batch': 'au-analyze-status', 'asset_selected': 'au-analyze-status',
                'bot_rep': 'bot-analyze-status', 'bot_utility': 'bot-util-status',
            };
            return document.getElementById(m[source] || '');
        }

        function _tagBatchRefreshFn(source) {
            switch (source) {
                case 'style_lora': case 'style_refine':
                    return () => { if (_styleLora.currentProject) renderStyleGrid(); };
                case 'instance_lora':
                    return () => { if (typeof loadInstanceLoraGrid === 'function') loadInstanceLoraGrid(); };
                case 'asset_batch': case 'asset_selected':
                    return () => {
                        if (typeof auRenderImages === 'function' && typeof auNavLevel !== 'undefined' && auNavLevel >= 2 && auNavOutfit && auNavExpression) {
                            auRenderImages(auNavCharacter, auNavOutfit, auNavExpression);
                        }
                    };
                case 'bot_rep':
                    return () => {
                        if (typeof renderBotCharacters === 'function') renderBotCharacters();
                        if (typeof botCurrentChar !== 'undefined' && botCurrentChar && typeof loadBotCharDetailImages === 'function') loadBotCharDetailImages(botCurrentChar);
                    };
                case 'bot_utility':
                    return () => { if (typeof renderBotCharacters === 'function') renderBotCharacters(); };
                default:
                    return null;
            }
        }

        function _startTagBatch(batchId, label, total, source, opts) {
            if (!batchId || !total) return;
            opts = opts || {};
            _tagBatches[batchId] = {
                label: label || '', total: total, remaining: total, success: 0, fail: 0, cancelled: 0,
                failures: [],
                project: opts.project || ((source === 'style_lora' || source === 'style_refine') ? _styleLora.currentProject : null),
                source: source, refreshFn: opts.refreshFn || _tagBatchRefreshFn(source),
                refreshTimer: null, finalizeFn: opts.finalizeFn || null,
            };
        }

        function _scheduleTagBatchRefresh(batchId) {
            const b = _tagBatches[batchId];
            if (!b || !b.refreshFn) return;
            if (b.refreshTimer) return;
            b.refreshTimer = setTimeout(() => {
                b.refreshTimer = null;
                try { b.refreshFn(); } catch (e) { console.warn('[TAG_BATCH] 화면 갱신 실패:', e); }
            }, 600);
        }

        function _finalizeTagBatch(batchId) {
            const b = _tagBatches[batchId];
            if (!b) return;
            if (b.refreshTimer) { clearTimeout(b.refreshTimer); b.refreshTimer = null; }
            try {
                if ((b.source === 'style_lora' || b.source === 'style_refine') && b.project === _styleLora.currentProject) loadStyleProjectImages();
                else if (b.refreshFn) b.refreshFn();
            } catch (e) { console.warn('[TAG_BATCH] 최종 갱신 실패:', e); }
            const msg = `${b.label || '일괄 작업'} 완료: 성공 ${b.success}건${b.fail ? ` / 실패 ${b.fail}건` : ''}${b.cancelled ? ` / 취소 ${b.cancelled}건` : ''}`;
            showToast(msg, b.fail ? 'error' : 'success');
            const statusEl = _tagBatchStatusEl(b.source);
            if (statusEl) statusEl.textContent = msg;
            if (typeof b.finalizeFn === 'function') { try { b.finalizeFn(b); } catch (e) { console.warn('[TAG_BATCH] finalize 실패:', e); } }
            delete _tagBatches[batchId];
        }

        // tag_analysis_progress(6 소스) + lora_prompt_refine_progress(style) 양쪽에서 호출.
        // batch_id 없는 이벤트(자동매치/봇단일/단일 정제)는 여기서 무시 → 기존 핸들러가 처리.
        function _handleTagBatchProgress(data) {
            if (!data || !data.batch_id) return;
            const b = _tagBatches[data.batch_id];
            if (!b) return;
            if (data.phase === 'completed') {
                if ((b.source === 'style_lora' || b.source === 'style_refine')
                    && (data.project || b.project) === _styleLora.currentProject
                    && typeof data.positive === 'string' && data.filename) {
                    const previous = _styleLora.prompts.get(data.filename) || {};
                    _styleLora.prompts.set(data.filename, b.source === 'style_lora'
                        ? {positive: data.positive, negative: '', original_positive: data.positive, original_negative: ''}
                        : {...previous, positive: data.positive});
                }
                _scheduleTagBatchRefresh(data.batch_id);
            }
        }

        // queue_updated와 /api/queue/status 모두 같은 서버 집계를 사용한다.
        // items가 비어 있어도 보관된 배치 결과로 완료하고 다음 단계를 시작한다.
        function _reconcileTagBatchesFromQueue(items, batches) {
            if (!batches) return;
            // Reattach style batches after a page reload or server-side queue restore.
            for (const item of items || []) {
                if (!item.batch_id || _tagBatches[item.batch_id] || !['pending', 'waiting', 'processing'].includes(item.status)) continue;
                const params = item.params || {};
                const source = item.type === 'tag_analysis' && params.source === 'style_lora'
                    ? 'style_lora'
                    : item.type === 'instance_lora_prompt_refine' && params.source_type === 'style'
                        ? 'style_refine' : null;
                if (source && batches[item.batch_id]) {
                    _startTagBatch(item.batch_id, item.batch_label, batches[item.batch_id].total, source, {
                        project: params.project || params.image?.project,
                    });
                }
            }
            for (const batchId of Object.keys(_tagBatches)) {
                const b = _tagBatches[batchId];
                const batch = batches[batchId];
                if (!batch) continue;
                const done = batch.success + batch.fail + batch.cancelled;
                // HTTP 응답이 더 최신 WS 상태보다 늦게 도착해도 집계를 되돌리지 않는다.
                if (done < b.success + b.fail + b.cancelled) continue;
                const changed = done !== b.success + b.fail + b.cancelled;
                b.total = batch.total;
                b.success = batch.success;
                b.fail = batch.fail;
                b.cancelled = batch.cancelled;
                b.remaining = batch.remaining;
                b.failures = batch.failures || [];
                _botOneClickSyncTagBatchRecord(batchId);
                const statusEl = _tagBatchStatusEl(b.source);
                if (statusEl) statusEl.textContent = `${b.label || '일괄 작업'}: 완료 ${b.success} / 실패 ${b.fail} / 취소 ${b.cancelled} (남은 ${b.remaining})`;
                if (b.remaining === 0 && done === b.total) _finalizeTagBatch(batchId);
                else if (changed) _scheduleTagBatchRefresh(batchId);
            }
        }

        function fileToBase64(file) {
            return new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.onload = () => {
                    const base64 = reader.result.split(',')[1];
                    resolve(base64);
                };
                reader.onerror = reject;
                reader.readAsDataURL(file);
            });
        }

        function closeSettingsModal() {
            if (modalOperationLockActive() || modalRedeployChoiceActive()) return;
            comfyRuntimeStopPolling();
            modalRuntimeStopPolling();
            stopVastLaunchPolling();
            videoEngineStopPolling();
            if (modalStatusPollTimer) {
                clearTimeout(modalStatusPollTimer);
                modalStatusPollTimer = null;
            }
            document.getElementById('settings-modal').classList.remove('visible');
            // 모든 자동완성 닫기
            document.querySelectorAll('.autocomplete-list').forEach(list => list.classList.remove('visible'));
            // config 미리보기 모달도 닫기
            const previewModal = document.getElementById('config-preview-modal');
            if (previewModal) previewModal.classList.remove('visible');
        }

