                backup_base_dir: '백업 폴더',
                backup_max_count: '백업 최대 수',
                clamp_enabled: '가중치 클램프',
                clamp_value: '클램프 값',
                lora_prompt_review_enabled: 'LoRA 프롬프트 2차 검수',
                embedding_provider: '임베딩 프로바이더',
                embedding_url: '임베딩 URL',
                embedding_api_key: '임베딩 API Key',
                embedding_model: '임베딩 모델',
                restore_prompt_file: '복원 프롬프트 파일',
                restore_manual_enabled: '수동 복원 모드',
                enhance_mode_enabled: '프롬프트 강화 모드',
                enhance_prompt_file: '강화 프롬프트 파일',
                asset_workflow_source_path: 'ILXL 에셋 생성 워크플로우',
                anima_asset_workflow_source_path: 'ANIMA+ILXL 에셋 생성 워크플로우',
                anima_only_asset_workflow_source_path: 'ONLY ANIMA 에셋 생성 워크플로우',
                anima_inpainting_workflow_source_path: 'ANIMA Inpainting 워크플로우',
