        const LLM_ROUTING_MODALITIES = [
            {
                key: 'text',
                label: '텍스트 요구 작업',
                description: '이미지를 전송하지 않는 일반 텍스트·JSON 작업',
            },
            {
                key: 'vision',
                label: '비전 요구 작업',
                description: '한 장 이상의 이미지를 LLM에 함께 전달할 수 있는 작업',
            },
        ];
        const llmRoutingEasyAppliedTaskKeys = new Set();

        function llmRouteNumber(value, fallback, integer = false) {
            const parsed = Number(value);
            if (!Number.isFinite(parsed)) return fallback;
            return integer ? Math.trunc(parsed) : parsed;
        }

        function llmRouteSlotReady(slotId) {
            return !!llmRouteSlotModelName(slotId);
        }

        function llmRouteSlotModelName(slotId, displayAlias = false, model = null, config = currentConfig) {
            let slot = Number(String(slotId || '').toLowerCase().replace('llm', ''));
            // 예전 로그에 슬롯이 없으면 모델이 일치하는 연결이 하나일 때만 별칭을 쓴다.
            if (!LLM_SLOTS.includes(slot) && displayAlias && model) {
                const matches = LLM_SLOTS.filter(number =>
                    String(config?.[`llm_model${llmSlotSuffix(number)}`] || '').trim() === String(model).trim()
                );
                if (matches.length === 1) slot = matches[0];
            }
            if (!LLM_SLOTS.includes(slot)) return String(model || '').trim();
            const suffix = llmSlotSuffix(slot);
            // 명시적인 모델이 있는 로그·상태 표시는 저장된 설정만 사용한다.
            const modelInput = model == null ? document.getElementById(`setting-llm-model${suffix}`) : null;
            const actualModel = String(model ?? (modelInput
                ? modelInput.value
                : config?.[`llm_model${suffix}`]) ?? '').trim();
            if (!displayAlias || !actualModel) return actualModel;
            const aliasInput = model == null ? document.getElementById(`setting-llm-alias${suffix}`) : null;
            const alias = aliasInput ? aliasInput.value : config?.[`llm_alias${suffix}`];
            return String(alias || '').trim() || actualModel;
        }

        function updateLlmRouteSelectTitle(select) {
            if (!select) return;
            const slotId = select.value;
            if (slotId === 'none') {
                select.title = '폴백 사용 안 함';
                return;
            }
            if (!slotId) {
                select.title = '개별 설정이 혼합되어 있습니다.';
                return;
            }
            const slot = Number(String(slotId).replace('llm', ''));
            const modelName = llmRouteSlotModelName(slotId, true);
            select.title = modelName
                ? `LLM${slot} 모델: ${modelName}`
                : `LLM${slot} 모델명 미설정`;
        }

        function updateLlmRouteSelectOptionLabels(select) {
            if (!select) return;
            for (const option of select.options) {
                const slot = Number(String(option.value).replace('llm', ''));
                if (!LLM_SLOTS.includes(slot)) continue;
                const modelName = llmRouteSlotModelName(option.value, true);
                option.textContent = `LLM${slot} · ${modelName || '모델명 미설정'}`;
            }
        }

        function updateLlmRouteSelectPresentation(select) {
            updateLlmRouteSelectOptionLabels(select);
            updateLlmRouteSelectTitle(select);
        }

        function initializeLlmRouteSelectTooltips(container) {
            if (!container) {
                console.error('[LLM_ROUTE] 모델명 툴팁 컨테이너가 없습니다.');
                return;
            }
            for (const select of container.querySelectorAll('select[data-route-slot-select]')) {
                updateLlmRouteSelectPresentation(select);
                select.addEventListener('mouseenter', () => updateLlmRouteSelectPresentation(select));
                select.addEventListener('focus', () => updateLlmRouteSelectPresentation(select));
                select.addEventListener('change', () => updateLlmRouteSelectPresentation(select));
            }
        }

        function llmRouteResolvedFallback(entry, primary) {
            const routeSlots = LLM_SLOTS.map(slot => `llm${slot}`);
            if (routeSlots.includes(entry?.fallback_target)) return entry.fallback_target;
            return 'none';
        }

        function readDetailedLlmRoute(task) {
            const field = (selector, name) => {
                const control = document.querySelector(selector);
                if (!control) {
                    console.error('[LLM_ROUTE_EASY] 상세 설정 컨트롤을 찾지 못했습니다:', {
                        task: task.key,
                        field: name,
                        selector,
                    });
                    return null;
                }
                return control;
            };
            const primary = field(
                `select[data-route-key="${task.key}"][data-route-field="primary"]`,
                'primary',
            );
            const fallback = field(
                `select[data-route-key="${task.key}"][data-route-field="fallback_target"]`,
                'fallback_target',
            );
            const retryDelay = field(
                `input[data-route-key="${task.key}"][data-route-field="retry_delay_sec"]`,
                'retry_delay_sec',
            );
            const maxRetries = field(
                `input[data-route-key="${task.key}"][data-route-field="max_retries"]`,
                'max_retries',
            );
            const fallbackRetryDelay = field(
                `input[data-route-key="${task.key}"][data-route-field="fallback_retry_delay_sec"]`,
                'fallback_retry_delay_sec',
            );
            const fallbackMaxRetries = field(
                `input[data-route-key="${task.key}"][data-route-field="fallback_max_retries"]`,
                'fallback_max_retries',
            );
            if (!primary || !fallback || !retryDelay || !maxRetries || !fallbackRetryDelay || !fallbackMaxRetries) {
                return null;
            }
            return {
                primary: primary.value,
                fallback_target: fallback.value,
                retry_delay_sec: llmRouteNumber(retryDelay.value, 0),
                max_retries: llmRouteNumber(maxRetries.value, 0, true),
                fallback_retry_delay_sec: llmRouteNumber(fallbackRetryDelay.value, 0),
                fallback_max_retries: llmRouteNumber(fallbackMaxRetries.value, 0, true),
            };
        }

        function llmRouteCommonValue(routes, field) {
            if (!routes.length) return {mixed: false, value: null};
            const value = routes[0][field];
            return {
                mixed: routes.some(route => route[field] !== value),
                value,
            };
        }

        function switchLlmRoutingMode(mode) {
            if (mode !== 'easy' && mode !== 'detail') {
                console.error('[LLM_ROUTE] 알 수 없는 설정 화면 요청:', mode);
                showToast('외부 LLM 분기 화면을 전환하지 못했습니다.', 'error');
                return;
            }
            for (const targetMode of ['easy', 'detail']) {
                const button = document.getElementById(`llm-route-mode-${targetMode}-btn`);
                const panel = document.getElementById(`llm-routing-${targetMode}-panel`);
                const active = targetMode === mode;
                if (button) {
                    button.classList.toggle('active', active);
                    button.setAttribute('aria-selected', active ? 'true' : 'false');
                } else {
                    console.error('[LLM_ROUTE] 설정 방식 버튼이 없습니다:', targetMode);
                }
                if (panel) {
                    panel.hidden = !active;
                } else {
                    console.error('[LLM_ROUTE] 설정 방식 패널이 없습니다:', targetMode);
                }
            }
            if (mode === 'easy') renderLlmRoutingEasySettings();
        }

        function renderLlmRoutingEasySettings() {
            const container = document.getElementById('llm-routing-easy');
            if (!container) {
                console.error('[LLM_ROUTE_EASY] 쉬운 설정 컨테이너가 없습니다.');
                return;
            }
            const routeSlots = LLM_SLOTS.map(slot => `llm${slot}`);
            const fieldLabels = {
                primary: '메인 LLM',
                retry_delay_sec: '메인 대기',
                max_retries: '메인 추가 횟수',
                fallback_target: '폴백 LLM',
                fallback_retry_delay_sec: '폴백 대기',
                fallback_max_retries: '폴백 추가 횟수',
            };
            let html = '';
            for (const modality of LLM_ROUTING_MODALITIES) {
                const tasks = LLM_ROUTING_TASKS.filter(task => !task.locked && !task.hidden && task.modality === modality.key && LLM_ROUTING_GROUPS.some(group => group.key === task.group));
                const routes = tasks.map(readDetailedLlmRoute);
                if (routes.some(route => !route)) {
                    console.error('[LLM_ROUTE_EASY] 상세 설정을 읽지 못해 쉬운 설정 렌더링을 중단합니다:', modality.key);
                    container.innerHTML = '<div class="llm-route-notice">쉬운 설정을 불러오지 못했습니다. 상세 설정을 확인하세요.</div>';
                    return;
                }
                const values = {};
                for (const fieldName of [
                    'primary',
                    'retry_delay_sec',
                    'max_retries',
                    'fallback_target',
                    'fallback_retry_delay_sec',
                    'fallback_max_retries',
                ]) {
                    values[fieldName] = llmRouteCommonValue(routes, fieldName);
                }
                const mixedFields = Object.entries(values)
                    .filter(([_fieldName, state]) => state.mixed)
                    .map(([fieldName]) => fieldLabels[fieldName]);
                const primary = values.primary.mixed ? '' : values.primary.value;
                const fallback = values.fallback_target.mixed ? '' : values.fallback_target.value;
                const mixedOption = '<option value="" disabled>개별 설정 혼합됨</option>';

                html += `<article class="llm-route-easy-card ${modality.key}">`;
                html += '<div class="llm-route-easy-head"><div>';
                html += `<div class="llm-route-easy-title">${modality.label}</div>`;
                html += `<div class="llm-route-easy-description">${modality.description}</div>`;
                html += `</div><span class="llm-route-easy-count">${tasks.length}개 작업</span></div>`;
                html += '<div class="llm-route-easy-paths">';
                html += '<section class="llm-route-path-panel primary">';
                html += '<div class="llm-route-path-head"><span class="llm-route-path-title">메인 경로</span>';
                html += `<select id="llm-route-easy-${modality.key}-primary" data-route-slot-select aria-label="${modality.label} 메인 LLM">`;
                if (!primary) html += mixedOption.replace('disabled', 'disabled selected');
                for (const slotId of routeSlots) {
                    const slot = Number(slotId.replace('llm', ''));
                    const ready = llmRouteSlotReady(slotId);
                    html += `<option value="${slotId}"${primary === slotId ? ' selected' : ''}${ready ? '' : ' disabled'}>LLM${slot}${ready ? '' : ' (미설정)'}</option>`;
                }
                html += '</select></div><div class="llm-route-path-fields">';
                html += `<label class="llm-route-retry-field"><span>대기(초)</span><input id="llm-route-easy-${modality.key}-retry-delay" type="number" min="0" max="300" step="0.5" value="${values.retry_delay_sec.mixed ? '' : values.retry_delay_sec.value}" placeholder="혼합"></label>`;
                html += `<label class="llm-route-retry-field"><span>추가 횟수</span><input id="llm-route-easy-${modality.key}-max-retries" type="number" min="0" max="10" step="1" value="${values.max_retries.mixed ? '' : values.max_retries.value}" placeholder="혼합"></label>`;
                html += '</div></section>';
                html += `<section class="llm-route-path-panel fallback${fallback === 'none' ? ' is-disabled' : ''}">`;
                html += '<div class="llm-route-path-head"><span class="llm-route-path-title">폴백 경로</span>';
                html += `<select id="llm-route-easy-${modality.key}-fallback" data-route-slot-select onchange="updateLlmRouteEasyFallbackState('${modality.key}')" aria-label="${modality.label} 폴백 LLM">`;
                if (!fallback) html += mixedOption.replace('disabled', 'disabled selected');
                html += `<option value="none"${fallback === 'none' ? ' selected' : ''}>없음</option>`;
                for (const slotId of routeSlots) {
                    const slot = Number(slotId.replace('llm', ''));
                    html += `<option value="${slotId}"${fallback === slotId ? ' selected' : ''}>LLM${slot}</option>`;
                }
                html += '</select></div><div class="llm-route-path-fields">';
                html += `<label class="llm-route-retry-field"><span>대기(초)</span><input id="llm-route-easy-${modality.key}-fallback-retry-delay" type="number" min="0" max="300" step="0.5" value="${values.fallback_retry_delay_sec.mixed ? '' : values.fallback_retry_delay_sec.value}" placeholder="혼합"></label>`;
                html += `<label class="llm-route-retry-field"><span>추가 횟수</span><input id="llm-route-easy-${modality.key}-fallback-max-retries" type="number" min="0" max="10" step="1" value="${values.fallback_max_retries.mixed ? '' : values.fallback_max_retries.value}" placeholder="혼합"></label>`;
                html += '</div></section></div>';
                html += '<div class="llm-route-easy-actions">';
                html += `<span id="llm-route-easy-${modality.key}-status" class="llm-route-easy-status${mixedFields.length ? ' mixed' : ''}">`;
                html += mixedFields.length
                    ? `개별 설정 혼합됨: ${mixedFields.join(', ')}`
                    : `현재 ${tasks.length}개 작업의 설정이 동일합니다.`;
                html += '</span>';
                html += `<button type="button" class="llm-route-easy-apply" onclick="applyLlmRoutingEasy('${modality.key}')">${modality.label} 일괄 적용</button>`;
                html += '</div></article>';
            }
            container.innerHTML = html;
            initializeLlmRouteSelectTooltips(container);
            for (const modality of LLM_ROUTING_MODALITIES) {
                updateLlmRouteEasyFallbackState(modality.key);
            }
        }

        function updateLlmRouteEasyFallbackState(modality) {
            const fallback = document.getElementById(`llm-route-easy-${modality}-fallback`);
            const disabled = !fallback || fallback.value === 'none';
            const card = fallback?.closest('.llm-route-easy-card');
            const panel = fallback?.closest('.llm-route-path-panel');
            if (panel) panel.classList.toggle('is-disabled', disabled);
            for (const suffix of ['fallback-retry-delay', 'fallback-max-retries']) {
                const input = document.getElementById(`llm-route-easy-${modality}-${suffix}`);
                if (input) input.disabled = disabled;
                else console.error('[LLM_ROUTE_EASY] 폴백 입력을 찾지 못했습니다:', {modality, suffix, card});
            }
        }

        function readLlmRouteEasyNumber(modality, suffix, label, max, integer) {
            const input = document.getElementById(`llm-route-easy-${modality}-${suffix}`);
            if (!input) throw new Error(`${label} 입력을 찾지 못했습니다.`);
            if (input.value.trim() === '') throw new Error(`${label} 값을 선택하세요.`);
            const value = Number(input.value);
            if (!Number.isFinite(value) || value < 0 || value > max || (integer && !Number.isInteger(value))) {
                throw new Error(`${label} 값이 유효하지 않습니다.`);
            }
            return value;
        }

        function applyLlmRoutingEasy(modality) {
            try {
                const modalityInfo = LLM_ROUTING_MODALITIES.find(item => item.key === modality);
                if (!modalityInfo) throw new Error(`알 수 없는 작업 분류입니다: ${modality}`);
                const tasks = LLM_ROUTING_TASKS.filter(task => !task.locked && !task.hidden && task.modality === modality && LLM_ROUTING_GROUPS.some(group => group.key === task.group));
                if (!tasks.length) throw new Error(`${modalityInfo.label}에 포함된 작업이 없습니다.`);
                const routeSlots = LLM_SLOTS.map(slot => `llm${slot}`);
                const primary = document.getElementById(`llm-route-easy-${modality}-primary`)?.value || '';
                const fallback = document.getElementById(`llm-route-easy-${modality}-fallback`)?.value || '';
                if (!routeSlots.includes(primary)) throw new Error('메인 LLM을 선택하세요.');
                if (fallback !== 'none' && !routeSlots.includes(fallback)) throw new Error('폴백 LLM을 선택하세요.');
                const values = {
                    primary,
                    fallback_target: fallback,
                    retry_delay_sec: readLlmRouteEasyNumber(modality, 'retry-delay', '메인 재시도 대기', 300, false),
                    max_retries: readLlmRouteEasyNumber(modality, 'max-retries', '메인 추가 횟수', 10, true),
                    fallback_retry_delay_sec: fallback === 'none'
                        ? 0
                        : readLlmRouteEasyNumber(modality, 'fallback-retry-delay', '폴백 재시도 대기', 300, false),
                    fallback_max_retries: fallback === 'none'
                        ? 0
                        : readLlmRouteEasyNumber(modality, 'fallback-max-retries', '폴백 추가 횟수', 10, true),
                };
                const controls = tasks.map(task => {
                    const byField = (tag, field) => document.querySelector(
                        `${tag}[data-route-key="${task.key}"][data-route-field="${field}"]`,
                    );
                    const taskControls = {
                        task,
                        primary: byField('select', 'primary'),
                        fallback_target: byField('select', 'fallback_target'),
                        retry_delay_sec: byField('input', 'retry_delay_sec'),
                        max_retries: byField('input', 'max_retries'),
                        fallback_retry_delay_sec: byField('input', 'fallback_retry_delay_sec'),
                        fallback_max_retries: byField('input', 'fallback_max_retries'),
                    };
                    const missing = Object.entries(taskControls)
                        .filter(([fieldName, control]) => fieldName !== 'task' && !control)
                        .map(([fieldName]) => fieldName);
                    if (missing.length) {
                        throw new Error(`${task.label} 상세 컨트롤 누락: ${missing.join(', ')}`);
                    }
                    return taskControls;
                });

                for (const taskControls of controls) {
                    taskControls.primary.value = values.primary;
                    taskControls.fallback_target.value = values.fallback_target;
                    taskControls.retry_delay_sec.value = String(values.retry_delay_sec);
                    taskControls.max_retries.value = String(values.max_retries);
                    taskControls.fallback_retry_delay_sec.value = String(values.fallback_retry_delay_sec);
                    taskControls.fallback_max_retries.value = String(values.fallback_max_retries);
                    llmRoutingEasyAppliedTaskKeys.add(taskControls.task.key);
                    updateLlmRouteFallbackState(taskControls.task.key);
                }
                const status = document.getElementById(`llm-route-easy-${modality}-status`);
                if (status) {
                    status.classList.remove('mixed');
                    status.textContent = `${tasks.length}개 작업에 적용됨 · 저장 필요`;
                } else {
                    console.error('[LLM_ROUTE_EASY] 적용 상태 요소를 찾지 못했습니다:', modality);
                }
                showToast(`${modalityInfo.label} ${tasks.length}개에 일괄 적용했습니다. 저장 버튼을 눌러 확정하세요.`, 'success');
            } catch (error) {
                console.error('[LLM_ROUTE_EASY] 일괄 적용 실패:', {modality, error});
                showToast(`LLM 쉬운 설정 적용 실패: ${error.message}`, 'error');
            }
        }

        function updateLlmRouteFallbackState(taskKey) {
            const fallbackSelect = document.querySelector(
                `select[data-route-key="${taskKey}"][data-route-field="fallback_target"]`
            );
            const primarySelect = document.querySelector(
                `select[data-route-key="${taskKey}"][data-route-field="primary"]`
            );
            updateLlmRouteSelectPresentation(primarySelect);
            updateLlmRouteSelectPresentation(fallbackSelect);
            const disabled = !fallbackSelect || fallbackSelect.value === 'none';
            const fallbackPanel = document.querySelector(
                `[data-route-key="${taskKey}"][data-route-role="fallback-panel"]`
            );
            if (fallbackPanel) fallbackPanel.classList.toggle('is-disabled', disabled);
            for (const field of ['fallback_retry_delay_sec', 'fallback_max_retries']) {
                const input = document.querySelector(
                    `input[data-route-key="${taskKey}"][data-route-field="${field}"]`
                );
                if (input) input.disabled = disabled;
            }
        }

        function renderLlmRoutingTable() {
            const container = document.getElementById('llm-routing-table');
            if (!container) {
                console.error('[LLM_ROUTE] 상세 설정 컨테이너가 없습니다.');
                return;
            }
            llmRoutingEasyAppliedTaskKeys.clear();
            const routing = (currentConfig && currentConfig.llm_routing) || {};
            // 모든 슬롯의 모델명 설정 여부로 라우팅 사용 가능 상태를 판단한다.
            const slotReady = {};
            for (const s of LLM_SLOTS) {
                slotReady['llm' + s] = llmRouteSlotReady('llm' + s);
            }
            const VALID_ROUTE_SLOTS = LLM_SLOTS.map(s => 'llm' + s);

            // 작업 카테고리 안에서 메인 경로와 폴백 경로를 독립 패널로 표시한다.
            let html = '';

            for (const [groupIndex, group] of LLM_ROUTING_GROUPS.entries()) {
                // 잠긴 작업은 등록과 저장값만 유지하고 분기 설정에서는 숨긴다.
                const groupTasks = LLM_ROUTING_TASKS.filter(task => !task.locked && !task.hidden && task.group === group.key);
                html += `<section class="llm-route-group" style="--route-group-color: ${group.color};" aria-labelledby="llm-route-group-${group.key}">`;
                html += '<header class="llm-route-group-header">';
                html += `<span class="llm-route-group-number">${String(groupIndex + 1).padStart(2, '0')}</span>`;
                html += '<div class="llm-route-group-heading">';
                html += `<div class="llm-route-group-title" id="llm-route-group-${group.key}">${group.label}</div>`;
                html += `<div class="llm-route-group-description">${group.description}</div>`;
                html += '</div>';
                html += `<span class="llm-route-group-count">${groupTasks.length}개 작업</span>`;
                html += '</header><div class="llm-route-group-body">';

                for (const t of groupTasks) {
                    const entry = routing[t.key] || {};
                    const primary = VALID_ROUTE_SLOTS.includes(entry.primary) ? entry.primary : '';
                    // 명시적으로 지정된 폴백 대상만 사용한다.
                    const fbTarget = llmRouteResolvedFallback(entry, primary);
                    const retryDelay = llmRouteNumber(entry.retry_delay_sec, 0);
                    const maxRetries = llmRouteNumber(entry.max_retries, 0, true);
                    const fallbackRetryDelay = llmRouteNumber(entry.fallback_retry_delay_sec, 0);
                    const fallbackMaxRetries = llmRouteNumber(entry.fallback_max_retries, 0, true);
                    const fallbackDisabled = fbTarget === 'none' ? ' disabled' : '';

                    html += `<article class="llm-route-card ${t.locked ? 'ui-locked' : ''}"${t.locked ? ' data-lock-reason="현재 미사용으로 일시 잠금" title="현재 미사용으로 일시 잠금"' : ''}>`;
                    html += '<div class="llm-route-task-header">';
                    html += `<div class="llm-route-task-title">${t.label}</div>`;
                    html += `<span class="llm-route-kind">${t.kind}</span>`;
                    if (t.locked) html += '<span class="llm-route-lock-badge">잠금</span>';
                    html += '</div><div class="llm-route-path-grid">';

                    html += '<section class="llm-route-path-panel primary">';
                    html += '<div class="llm-route-path-head"><span class="llm-route-path-title">메인 경로</span>';
                    html += `<select data-route-key="${t.key}" data-route-field="primary" data-route-slot-select aria-label="${t.label} 메인 LLM">`;
                    if (!primary) html += '<option value="" selected disabled>LLM 선택</option>';
                    for (const s of LLM_SLOTS) {
                        const slotId = 'llm' + s;
                        const ready = slotReady[slotId];
                        html += `<option value="${slotId}"${primary === slotId ? ' selected' : ''}${ready ? '' : ' disabled'}>LLM${s}${ready ? '' : ' (미설정)'}</option>`;
                    }
                    html += '</select></div><div class="llm-route-path-fields">';
                    html += `<label class="llm-route-retry-field"><span>대기(초)</span><input type="number" min="0" max="300" step="0.5" value="${retryDelay}" data-route-key="${t.key}" data-route-field="retry_delay_sec" aria-label="${t.label} 메인 재시도 대기초"></label>`;
                    html += `<label class="llm-route-retry-field"><span>추가 횟수</span><input type="number" min="0" max="10" step="1" value="${maxRetries}" data-route-key="${t.key}" data-route-field="max_retries" aria-label="${t.label} 메인 재시도 횟수"></label>`;
                    html += '</div></section>';

                    html += `<section class="llm-route-path-panel fallback${fbTarget === 'none' ? ' is-disabled' : ''}" data-route-key="${t.key}" data-route-role="fallback-panel">`;
                    html += '<div class="llm-route-path-head"><span class="llm-route-path-title">폴백 경로</span>';
                    html += `<select data-route-key="${t.key}" data-route-field="fallback_target" data-route-slot-select onchange="updateLlmRouteFallbackState('${t.key}')" aria-label="${t.label} 폴백 LLM">`;
                    html += `<option value="none"${fbTarget === 'none' ? ' selected' : ''}>없음</option>`;
                    for (const s of LLM_SLOTS) {
                        const slotId = 'llm' + s;
                        html += `<option value="${slotId}"${fbTarget === slotId ? ' selected' : ''}>LLM${s}</option>`;
                    }
                    html += '</select></div><div class="llm-route-path-fields">';
                    html += `<label class="llm-route-retry-field"><span>대기(초)</span><input type="number" min="0" max="300" step="0.5" value="${fallbackRetryDelay}" data-route-key="${t.key}" data-route-field="fallback_retry_delay_sec" aria-label="${t.label} 폴백 재시도 대기초"${fallbackDisabled}></label>`;
                    html += `<label class="llm-route-retry-field"><span>추가 횟수</span><input type="number" min="0" max="10" step="1" value="${fallbackMaxRetries}" data-route-key="${t.key}" data-route-field="fallback_max_retries" aria-label="${t.label} 폴백 재시도 횟수"${fallbackDisabled}></label>`;
                    html += '</div></section>';
                    html += '</div></article>';
                }
                html += '</div></section>';
            }

            for (const s of LLM_SLOTS) {
                if (!slotReady['llm' + s]) {
                    html += `<div class="llm-route-notice">⚠ 외부 API 탭에서 LLM${s} 모델명을 설정해야 LLM${s}(메인/폴백) 선택지가 활성화됩니다.</div>`;
                }
            }
            html += '<div class="llm-route-tip">💡 메인 재시도를 모두 소진한 뒤 폴백으로 넘어갑니다.</div>';
            container.innerHTML = html;
            initializeLlmRouteSelectTooltips(container);
        }

        function collectLlmRouting() {
            const routing = {};
            const prevRouting = (currentConfig && currentConfig.llm_routing) || {};
            const ROUTE_SLOTS = LLM_SLOTS.map(s => 'llm' + s);
            for (const t of LLM_ROUTING_TASKS) {
                // 잠긴 항목은 UI에서 편집 불가하므로 기존 설정값을 그대로 보존
                if (t.locked && !llmRoutingEasyAppliedTaskKeys.has(t.key)) {
                    const entry = { ...(prevRouting[t.key] || { primary: '', fallback: false }) };
                    delete entry.json_mode;
                    routing[t.key] = entry;
                    continue;
                }
                const sel = document.querySelector(`select[data-route-key="${t.key}"][data-route-field="primary"]`);
                const fbSel = document.querySelector(`select[data-route-key="${t.key}"][data-route-field="fallback_target"]`);
                const primary = (sel && ROUTE_SLOTS.includes(sel.value)) ? sel.value : '';
                const fbVal = fbSel ? fbSel.value : 'none';
                const entry = { primary };
                const retryDelayInput = document.querySelector(`input[data-route-key="${t.key}"][data-route-field="retry_delay_sec"]`);
                const maxRetriesInput = document.querySelector(`input[data-route-key="${t.key}"][data-route-field="max_retries"]`);
                const fallbackRetryDelayInput = document.querySelector(`input[data-route-key="${t.key}"][data-route-field="fallback_retry_delay_sec"]`);
                const fallbackMaxRetriesInput = document.querySelector(`input[data-route-key="${t.key}"][data-route-field="fallback_max_retries"]`);
                entry.retry_delay_sec = llmRouteNumber(retryDelayInput?.value, 0);
                entry.max_retries = llmRouteNumber(maxRetriesInput?.value, 0, true);
                entry.fallback_retry_delay_sec = llmRouteNumber(fallbackRetryDelayInput?.value, 0);
                entry.fallback_max_retries = llmRouteNumber(fallbackMaxRetriesInput?.value, 0, true);
                // 폴백 대상은 fallback_target 으로 저장. '없음'이면 폴백 미사용(false).
                if (ROUTE_SLOTS.includes(fbVal)) {
                    entry.fallback_target = fbVal;
                    entry.fallback = true;
                } else {
                    entry.fallback = false;
                }
                routing[t.key] = entry;
            }
            return routing;
        }

        // ─── LLM API 키 별도 저장 (key/llm_keys.json) ───
        async function loadLlmKeys() {
            try {
                const data = await fetchJSON('/api/llm/keys');
                for (const slot of LLM_SLOTS) {
                    const suffix = llmSlotSuffix(slot);
                    const el = document.getElementById(`setting-llm-api-key${suffix}`);
                    if (el) el.value = data[`llm_api_key${suffix}`] || '';
                }
            } catch (e) {
                console.error('load LLM keys:', e);
                showToast('LLM API 키 조회 실패: ' + e.message, 'error');
            }
        }

        async function saveLlmKeys() {
            const payload = {};
            for (const slot of LLM_SLOTS) {
                const suffix = llmSlotSuffix(slot);
                payload[`llm_api_key${suffix}`] = (document.getElementById(`setting-llm-api-key${suffix}`) || {}).value || '';
            }
            try {
                await fetchJSON('/api/llm/keys', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload),
                });
            } catch (e) {
                console.error('save LLM keys:', e);
                throw new Error('LLM API 키 저장 실패: ' + e.message);
            }
        }

        // ─── 챈섭 설정 및 API 키 별도 저장 (key/chansub_key.json) ───
        function updateChansubStripQualityTagsStatus(checked) {
            const status = document.getElementById('setting-chansub-strip-builtin-quality-tags-status');
            if (!status) {
                console.error('[CHANSUB] 내장 품질 태그 제외 상태 표시 요소를 찾을 수 없습니다.');
                return;
            }
            status.textContent = checked ? 'ON' : 'OFF';
            status.classList.toggle('on', checked);
            status.classList.toggle('off', !checked);
        }

        async function loadChansubKey() {
            try {
                const resp = await fetch('/api/chansub/key');
                const data = await resp.json();
                if (!resp.ok || data.error) throw new Error(data.error || `HTTP ${resp.status}`);
                const el = document.getElementById('setting-chansub-api-key');
                if (el) el.value = data.api_key || '';
                const rotationEl = document.getElementById('setting-chansub-rotation-api-key');
                if (rotationEl) rotationEl.value = data.rotation_api_key || '';
            } catch (e) {
                console.error('[CHANSUB_KEY] load failed:', e);
                showToast('챈섭 API 키 로드 실패: ' + e.message, 'error');
            }
        }

        async function saveChansubKey() {
            const apiKey = (document.getElementById('setting-chansub-api-key') || {}).value || '';
            const rotationApiKey = (document.getElementById('setting-chansub-rotation-api-key') || {}).value || '';
            try {
                const resp = await fetch('/api/chansub/key', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        api_key: apiKey,
                        rotation_api_key: rotationApiKey,
                    }),
                });
                const data = await resp.json();
                if (!resp.ok || data.error) throw new Error(data.error || `HTTP ${resp.status}`);
            } catch (e) {
                console.error('[CHANSUB_KEY] save failed:', e);
                throw e;
            }
        }

        async function deleteChansubKey() {
            if (!confirm('저장된 챈섭 API 키를 삭제하시겠습니까?')) return;
            try {
                const resp = await fetch('/api/chansub/key', { method: 'DELETE' });
                const data = await resp.json();
                if (!resp.ok || data.error) throw new Error(data.error || `HTTP ${resp.status}`);
                document.getElementById('setting-chansub-api-key').value = '';
                document.getElementById('setting-chansub-rotation-api-key').value = '';
                showToast('챈섭 API 키를 삭제했습니다.', 'success');
            } catch (e) {
                console.error('[CHANSUB_KEY] delete failed:', e);
                showToast('챈섭 API 키 삭제 실패: ' + e.message, 'error');
            }
        }

        // ─── Vast.ai 설정 및 API 키 별도 저장 (key/vast_key.json) ───
        function updateVastEnabledStatus(checked) {
            const status = document.getElementById('setting-vast-enabled-status');
            if (!status) {
                console.error('[VAST] 활성화 상태 표시 요소를 찾을 수 없습니다.');
                return;
            }
            status.textContent = checked ? 'ON' : 'OFF';
            status.className = 'toggle-status ' + (checked ? 'on' : 'off');
        }

        async function loadVastKey() {
            const el = document.getElementById('setting-vast-api-key');
            const statusEl = document.getElementById('setting-vast-key-status');
            try {
                const resp = await fetch('/api/vast/key');
                const data = await resp.json();
                if (!resp.ok || data.error) throw new Error(data.error || `HTTP ${resp.status}`);
                if (el) el.value = data.api_key || '';
                if (statusEl) statusEl.textContent = data.set ? '저장됨' : '미설정';
            } catch (e) {
                console.error('[VAST_KEY] load failed:', e);
                if (statusEl) statusEl.textContent = '로드 실패: ' + (e.message || e);
                showToast('Vast API 키 로드 실패: ' + (e.message || e), 'error');
            }
        }

        async function saveVastKey() {
            const el = document.getElementById('setting-vast-api-key');
            const statusEl = document.getElementById('setting-vast-key-status');
            const apiKey = (el || {}).value || '';
            try {
                const resp = await fetch('/api/vast/key', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ api_key: apiKey }),
                });
                const data = await resp.json();
                if (!resp.ok || data.error) throw new Error(data.error || `HTTP ${resp.status}`);
                if (statusEl) statusEl.textContent = data.set ? '저장됨' : '미설정';
                showToast(data.set ? 'Vast API 키를 저장했습니다.' : 'Vast API 키를 비웠습니다.', 'success');
                void refreshVastStatus(true);
                void vastRefreshAccountStatus();
            } catch (e) {
                console.error('[VAST_KEY] save failed:', e);
                showToast('Vast API 키 저장 실패: ' + (e.message || e), 'error');
            }
        }

        async function deleteVastKey() {
            if (!confirm('저장된 Vast API 키를 삭제하시겠습니까?')) return;
            const el = document.getElementById('setting-vast-api-key');
            const statusEl = document.getElementById('setting-vast-key-status');
            try {
                const resp = await fetch('/api/vast/key', { method: 'DELETE' });
                const data = await resp.json();
                if (!resp.ok || data.error) throw new Error(data.error || `HTTP ${resp.status}`);
                if (el) el.value = '';
                if (statusEl) statusEl.textContent = '미설정';
                showToast('Vast API 키를 삭제했습니다.', 'success');
                void refreshVastStatus(true);
                void vastRefreshAccountStatus();
            } catch (e) {
                console.error('[VAST_KEY] delete failed:', e);
                showToast('Vast API 키 삭제 실패: ' + (e.message || e), 'error');
            }
        }

        function vastToggleKeyVisible() {
            const el = document.getElementById('setting-vast-api-key');
            if (!el) return;
            el.type = el.type === 'password' ? 'text' : 'password';
        }

        async function vastRefreshAccountStatus() {
            const el = document.getElementById('vast-account-status');
            if (el) el.textContent = '상태 확인 중…';
            try {
                const data = await fetchJSON('/api/vast/status');
                const account = data?.account || {};
                const settings = data?.settings || {};
                const launch = data?.launch || {};
                if (account.ok === true) {
                    const credit = Number(account.balance_usd || 0).toFixed(2);
                    el.textContent = `계정: ${account.username || '(이름 없음)'}\ncredit: $${credit}\nAPI 키: ${settings.has_api_key ? '설정됨' : '없음'}\n인스턴스: ${launch.instance_id ? '#' + launch.instance_id + ' ' + (launch.state || '') : '없음'}`;
                } else {
                    el.textContent = '연결 실패: ' + (account.error || '알 수 없음') + (settings.has_api_key ? '' : '\n(API 키가 설정되지 않았습니다.)');
                }
            } catch (e) {
                console.error('[VAST] 상태 확인 실패:', e);
                if (el) el.textContent = '상태 확인 실패: ' + (e.message || e);
            }
        }

        const ILLUSTRATION_WORKFLOW_TYPES = new Set(['v3', 'v3_anima', 'chansub', 'chansub_v3_anima']);
        const ILLUSTRATION_LOCAL_PROFILES = ['v3', 'v3_anima'];

        function normalizeIllustrationWorkflowType(value) {
            const normalized = String(value || '').trim().toLowerCase();
            if (ILLUSTRATION_WORKFLOW_TYPES.has(normalized)) return normalized;
            if (normalized) console.error('[ILLUST] 알 수 없는 삽화 워크플로우 타입:', value);
            return 'v3';
        }

        function illustrationLocalProfile(type) {
            const normalized = normalizeIllustrationWorkflowType(type);
            if (normalized === 'chansub_v3_anima') return 'v3_anima';
            if (normalized === 'chansub') return null;
            return normalized;
        }

        function illustrationPromptFormatForType(type) {
            const normalized = normalizeIllustrationWorkflowType(type);

            if (normalized === 'chansub') return 'chansub';
            return 'v3';
        }

        function getIllustrationCapabilities(type = null) {
            const normalized = normalizeIllustrationWorkflowType(
                type || document.getElementById('setting-illustration-workflow-type')?.value
                    || currentConfig?.illustration_workflow_type
            );
            const chansubFamily = document.getElementById('setting-chansub-workflow-type')?.value === 'sdxl' ? 'sdxl' : 'anima';
            // MOSS 워크플로우는 이미지 레퍼런스와 고해상도·디테일러 노드가 없어
            // 레퍼런스/HIRESFIX 고급 옵션을 잠근다.
            const localProfile = illustrationLocalProfile(normalized);
            const sourcePath = String(currentConfig?.illustration_workflow_source_paths?.[localProfile] || '');
            const moss = sourcePath.toLowerCase().includes('moss');

            if (normalized === 'v3') return { anima: true, sdxl: true, ipadapter: true, localAdvanced: !moss, chansub: false, v1: false, moss, mossReference: moss, reference: true };
            if (normalized === 'v3_anima') return { anima: true, sdxl: false, ipadapter: false, localAdvanced: !moss, chansub: false, v1: false, moss, mossReference: moss, reference: true };
            if (normalized === 'chansub') return { anima: chansubFamily === 'anima', sdxl: chansubFamily === 'sdxl', ipadapter: false, localAdvanced: false, chansub: true, v1: false };
            return { anima: true, sdxl: false, ipadapter: false, localAdvanced: false, chansub: true, v1: false };
        }

        function persistIllustrationWorkflowPaths() {
            if (!currentConfig) return;
            const paths = currentConfig.illustration_workflow_source_paths
                || (currentConfig.illustration_workflow_source_paths = {});
            for (const profile of ILLUSTRATION_LOCAL_PROFILES) {
                const uiKey = illustrationWorkflowUiKey(profile);
                const pathInput = document.getElementById(`setting-illustration-${uiKey}-workflow-source-path`);
                if (pathInput) paths[profile] = pathInput.value || '';
            }
            const selectedType = normalizeIllustrationWorkflowType(
                document.getElementById('setting-illustration-workflow-type')?.value
                    || currentConfig.illustration_workflow_type
            );
            const localProfile = illustrationLocalProfile(selectedType);
            document.getElementById('setting-workflow-path').value = localProfile
                ? (paths[localProfile] || '')
                : '';
        }

        function applyIllustrationProviderConfig(config = {}) {
            let workflowType = config.illustration_workflow_type;
            if (!workflowType) {
                const provider = String(config.illustration_provider || 'comfy').trim().toLowerCase();
                const format = String(config.illustration_context_toggles?.prompt_format || 'v3').trim().toLowerCase();
                workflowType = provider === 'chansub' ? 'chansub' : 'v3';
            }
            workflowType = normalizeIllustrationWorkflowType(workflowType);
            const select = document.getElementById('setting-illustration-workflow-type');
            const chansubSelect = document.getElementById('setting-chansub-workflow-type');
            if (!select || !chansubSelect) {
                console.error('[ILLUST] 삽화 워크플로우 선택 UI를 찾을 수 없습니다.');
                return;
            }
            let chansubType = String(config.chansub_workflow_type || 'anima').trim().toLowerCase();
            if (chansubType !== 'anima' && chansubType !== 'sdxl') {
                console.error('[ILLUST] 알 수 없는 챈섭 워크플로우, ANIMA로 표시:', chansubType);
                chansubType = 'anima';
            }
            if (workflowType === 'chansub_v3_anima') chansubType = 'anima';
            chansubSelect.value = chansubType;
            select.value = workflowType;
            onIllustrationWorkflowTypeChange(workflowType, { persist: false });
        }

        function onIllustrationWorkflowTypeChange(type, options = {}) {
            if (options.persist !== false) persistIllustrationWorkflowPaths();
            const normalized = normalizeIllustrationWorkflowType(type);
            const select = document.getElementById('setting-illustration-workflow-type');
            if (select) select.value = normalized;
            if (currentConfig) currentConfig.illustration_workflow_type = normalized;

            const localProfile = illustrationLocalProfile(normalized);
            const paths = currentConfig?.illustration_workflow_source_paths || {};
            const localPath = localProfile ? (paths[localProfile] || '') : '';
            const hiddenPath = document.getElementById('setting-workflow-path');
            if (hiddenPath) hiddenPath.value = localPath;

            const isChansub = normalized === 'chansub';
            const isHybrid = normalized === 'chansub_v3_anima';
            for (const profile of ILLUSTRATION_LOCAL_PROFILES) {
                const uiKey = illustrationWorkflowUiKey(profile);
                const active = profile === localProfile;
                const card = document.getElementById(`setting-illustration-${uiKey}-workflow-card`);
                const input = document.getElementById(`setting-illustration-${uiKey}-workflow-filename`);
                const cardStatus = document.getElementById(`setting-illustration-${uiKey}-workflow-status`);
                card?.classList.toggle('active', active);
                card?.classList.toggle('inactive', !active);
                if (input) input.disabled = !active;
                if (cardStatus) cardStatus.textContent = active
                    ? (isHybrid ? '하이브리드 로컬' : '현재 사용')
                    : '비활성';
                if (!active) {
                    document.getElementById(`illustration-${uiKey}-workflow-autocomplete`)?.classList.remove('visible');
                }
            }
            const chansubSelect = document.getElementById('setting-chansub-workflow-type');
            if (chansubSelect) {
                if (isHybrid) chansubSelect.value = 'anima';
                chansubSelect.disabled = !isChansub;
                chansubSelect.style.opacity = isChansub ? '1' : '0.45';
            }
            const status = document.getElementById('setting-illustration-provider-status');
            if (status) {
                status.textContent = isHybrid ? 'ComfyUI + 챈섭' : (isChansub ? '챈섭' : 'ComfyUI');
                status.className = (isChansub || isHybrid) ? 'toggle-status on' : 'toggle-status off';
            }
            const desc = document.getElementById('setting-illustration-workflow-desc');
            if (desc) desc.textContent = isHybrid
                ? '로컬 ONLY ANIMA와 챈섭 ANIMA에 장면을 교대 분배합니다.'
                : (isChansub ? '챈섭 단독 모드에서는 로컬 JSON 파일을 사용하지 않습니다.' : '선택한 로컬 JSON 파일을 사용합니다.');

            updateChansubAdvancedOptions();
            _applyPromptFormatChansubLock();
            applyIllustImageSizeLock();
            loadRestorePromptFiles();
        }

        // 레거시 호출부 호환: 공급자 토글 대신 선택된 프로필을 다시 적용한다.
        function onIllustrationProviderChange() {
            onIllustrationWorkflowTypeChange(document.getElementById('setting-illustration-workflow-type')?.value || 'v3');
        }

        function onChansubWorkflowTypeChange() {
            if (currentConfig) currentConfig.chansub_workflow_type = document.getElementById('setting-chansub-workflow-type')?.value || 'anima';
            updateChansubWorkflowOptions();
        }

        // ─── Vertex JSON key 핸들러 ───
        async function loadVertexKeyStatus(slot) {
            const statusEl = document.getElementById(`vertex-key${llmSlotSuffix(slot)}-status`);
            if (!statusEl) return;
            try {
                const resp = await fetch(`/api/llm/vertex_key?slot=llm${slot}`);
                const data = await resp.json();
                if (!resp.ok || data.error) throw new Error(data.error || `HTTP ${resp.status}`);
                if (data.exists) {
                    statusEl.textContent = `✓ 저장됨: project=${data.project_id || '(알 수 없음)'} email=${data.client_email || ''}`;
                    statusEl.style.color = '#5cd5a0';
                } else {
                    statusEl.textContent = '✗ 키 없음';
                    statusEl.style.color = '#ff6b6b';
                }
            } catch (e) {
                console.error(`[LLM${slot}] Vertex 키 조회 실패:`, e);
                statusEl.textContent = `키 조회 실패: ${e.message}`;
                statusEl.style.color = '#ff6b6b';
            }
        }

        function loadVertexKeyFile(slot) {
            const suffix = llmSlotSuffix(slot);
            const input = document.getElementById(`setting-vertex-key-file${suffix}`);
            if (!input.files || !input.files[0]) {
                showToast(`LLM${slot}에 불러올 JSON 파일을 선택하세요.`, 'warning');
                return;
            }
            const reader = new FileReader();
            reader.onload = (e) => {
                document.getElementById(`setting-vertex-key-json${suffix}`).value = e.target.result;
            };
            reader.onerror = () => {
                console.error(`[LLM${slot}] Vertex 키 파일 읽기 실패:`, reader.error);
                showToast(`LLM${slot} Vertex 키 파일 읽기 실패`, 'error');
            };
            reader.readAsText(input.files[0], 'UTF-8');
        }

        async function saveVertexKey(slot) {
            const textarea = document.getElementById(`setting-vertex-key-json${llmSlotSuffix(slot)}`);
            const text = textarea.value.trim();
            if (!text) {
                alert('JSON 내용이 비었음');
                return;
            }
            try {
                const resp = await fetch(`/api/llm/vertex_key?slot=llm${slot}`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ json: text }),
                });
                const data = await resp.json();
                if (resp.ok) {
                    textarea.value = '';
                    await loadVertexKeyStatus(slot);
                    showToast(`LLM${slot} Vertex 키 저장 완료`, 'success');
                } else {
                    console.error(`[LLM${slot}] Vertex 키 저장 실패:`, data.error || resp.status);
                    alert('저장 실패: ' + (data.error || resp.status));
                }
            } catch (e) {
                console.error(`[LLM${slot}] Vertex 키 저장 실패:`, e);
                alert('저장 실패: ' + e.message);
            }
        }

        async function deleteVertexKey(slot) {
            if (!confirm(`LLM${slot}의 Vertex 키를 삭제하시겠습니까?`)) return;
            try {
                const resp = await fetch(`/api/llm/vertex_key?slot=llm${slot}`, { method: 'DELETE' });
                const data = await resp.json();
                if (!resp.ok) throw new Error(data.error || `HTTP ${resp.status}`);
                document.getElementById(`setting-vertex-key-json${llmSlotSuffix(slot)}`).value = '';
                await loadVertexKeyStatus(slot);
                showToast(`LLM${slot} Vertex 키 삭제 완료`, 'success');
            } catch (e) {
                console.error(`[LLM${slot}] Vertex 키 삭제 실패:`, e);
                alert('삭제 실패: ' + e.message);
            }
        }

        // ─── 프롬프트 강화 파일 목록 로드 ───
        async function loadCustompromptFiles() {
            try {
                const resp = await fetch('/api/customprompt_files');
                const data = await resp.json();
                const files = data.files || [];
                // 프롬프트 강화 select 채우기
                const enhanceSelect = document.getElementById('setting-enhance-prompt-file');
                const enhanceValue = enhanceSelect.value;
                while (enhanceSelect.options.length > 1) enhanceSelect.remove(1);
                files.forEach(f => {
                    const opt = document.createElement('option');
                    opt.value = f;
                    opt.textContent = f;
                    enhanceSelect.appendChild(opt);
                });
                enhanceSelect.value = enhanceValue;
            } catch (e) {
                console.error('customprompt 파일 목록 로드 실패:', e);
            }
        }


        // ─── 워크플로우 복원 프롬프트 파일 목록 로드 ───
        async function loadRestorePromptFiles() {
            try {
                const resp = await fetch('/api/customprompt_files');
                const data = await resp.json();
                const select = document.getElementById('setting-restore-prompt-file');
                if (!select) {
                    console.error('[ILLUST_RESTORE] 복원 프롬프트 선택 요소를 찾지 못했습니다.');
                    return;
                }
                const selectedType = normalizeIllustrationWorkflowType(
                    document.getElementById('setting-illustration-workflow-type')?.value
                        || currentConfig?.illustration_workflow_type
                        || data.illustration_workflow_type
                );
                const requiredFamilies = selectedType === 'chansub'
                    ? ['chansub']
                    : (selectedType === 'chansub_v3_anima' ? ['v3', 'chansub'] : ['v3']);
                const registry = data.restore_compatibility || {};
                const currentValue = select.value || currentConfig?.restore_prompt_file || '';
                while (select.options.length > 1) select.remove(1);
                (data.files || []).forEach(f => {
                    const opt = document.createElement('option');
                    opt.value = f;
                    opt.textContent = f;
                    const families = Array.isArray(registry[f]) ? registry[f] : [];
                    opt.disabled = !requiredFamilies.every(family => families.includes(family));
                    select.appendChild(opt);
                });
                const compatible = Array.from(select.options).filter(opt => opt.value && !opt.disabled);
                const selectedOption = Array.from(select.options).find(opt => opt.value === currentValue && !opt.disabled);
                select.value = selectedOption ? currentValue : (compatible[0]?.value || '');
            } catch (e) {
                console.error('복원 프롬프트 파일 목록 로드 실패:', e);
            }
        }

        function updateUtilityWorkflowPath() {
            const baseDir = document.getElementById('setting-workflow-base-dir').value.trim();
            const filename = document.getElementById('setting-utility-filename').value.trim();
            const sep = baseDir && baseDir.includes('\\') ? '\\' : '/';
            const fullPath = baseDir && filename ? baseDir.replace(/[\\/]+$/, '') + sep + filename : '';
            document.getElementById('setting-utility-workflow-source-path').value = fullPath;
        }


        // 에셋 생성 워크플로우 자동완성
        let assetAutocompleteTimeout;
