            const baseDir = document.getElementById('setting-workflow-base-dir').value;
            const filename = document.getElementById('setting-asset-workflow-filename').value;
            document.getElementById('setting-asset-workflow-source-path').value = combineWorkflowPath(baseDir, filename);
