        function onWorkflowTypeChange(type) {
            const normalized = normalizeAssetWorkflowType(type);
            const typeSelect = document.getElementById('setting-workflow-type-select');
            const regularCard = document.getElementById('setting-regular-workflow-card');
            const animaCard = document.getElementById('setting-anima-workflow-card');
            const animaOnlyCard = document.getElementById('setting-anima-only-workflow-card');
            const regularInput = document.getElementById('setting-asset-workflow-filename');
            const animaInput = document.getElementById('setting-anima-asset-workflow-filename');
            const animaOnlyInput = document.getElementById('setting-anima-only-asset-workflow-filename');
            const regularStatus = document.getElementById('setting-regular-workflow-status');
            const animaStatus = document.getElementById('setting-anima-workflow-status');
            const animaOnlyStatus = document.getElementById('setting-anima-only-workflow-status');

            if (typeSelect) typeSelect.value = normalized;
            const states = [
                [regularCard, regularInput, regularStatus, normalized === 'ilxl'],
                [animaCard, animaInput, animaStatus, normalized === 'anima_ilxl'],
                [animaOnlyCard, animaOnlyInput, animaOnlyStatus, normalized === 'anima_only'],
            ];
            states.forEach(([card, input, status, active]) => {
                card?.classList.toggle('active', active);
                card?.classList.toggle('inactive', !active);
                if (input) input.disabled = !active;
                if (status) status.textContent = active ? '현재 사용' : '비활성';
            });
            document.getElementById('asset-workflow-autocomplete')?.classList.remove('visible');
            document.getElementById('anima-asset-workflow-autocomplete')?.classList.remove('visible');
            document.getElementById('anima-only-asset-workflow-autocomplete')?.classList.remove('visible');
            if (currentConfig) currentConfig.asset_workflow_type = normalized;
            updateAnimaUIVisibility();
        }

