        function onUseBuiltinTaggerChange(checked) {
            const ids = [
                'setting-tag-analysis-workflow-filename',      // 스마트매치용 (얼굴)
                'setting-asset-tag-analysis-workflow-filename' // 폴백 (범용)
            ];
            ids.forEach(id => {
                const el = document.getElementById(id);
                if (!el) return;
                el.disabled = checked;
                el.style.opacity = checked ? '0.4' : '';
                el.style.cursor = checked ? 'not-allowed' : '';
            });
            // 자동완성 리스트도 숨김
            if (checked) {
                document.getElementById('tag-analysis-workflow-autocomplete')?.classList.remove('visible');
                document.getElementById('asset-tag-analysis-workflow-autocomplete')?.classList.remove('visible');
            }
        }

