        function openModeLogModal() {
            document.getElementById('mode-log-modal').classList.add('visible');
            refreshModeLogs();
        }

        function closeModeLogModal() {
            document.getElementById('mode-log-modal').classList.remove('visible');
        }

        async function refreshModeLogs() {
            const body = document.getElementById('mode-log-body');
            try {
                const resp = await fetch('/api/mode_logs?count=200');
                const data = await resp.json();
                const logs = data.logs || [];

                if (logs.length === 0) {
                    body.innerHTML = `<div class="empty-state"><p>로그가 없습니다</p></div>`;
                    return;
                }

                let html = '<div style="font-family: monospace; font-size: 0.8rem; line-height: 1.6;">';
                logs.reverse().forEach(log => {
                    const ts = log.timestamp ? log.timestamp.split('T')[1]?.split('.')[0] || log.timestamp : '';
                    const mode = log.mode || '';
                    const action = log.action || '';
                    const dataStr = log.data ? JSON.stringify(log.data, null, 0) : '';
                    const modeColor = 'var(--text2)';
                    html += `<div style="padding: 2px 0; border-bottom: 1px solid var(--border);">`;
                    html += `<span style="color: var(--text2);">${ts}</span> `;
                    html += `<span style="color: ${modeColor}; font-weight: 600;">[${mode}]</span> `;
                    html += `<span style="color: var(--text);">${action}</span>`;
                    if (dataStr) {
                        html += ` <span style="color: var(--text2); font-size: 0.75rem;">${dataStr}</span>`;
                    }
                    html += `</div>`;
                });
                html += '</div>';
                body.innerHTML = html;
            } catch (e) {
                body.innerHTML = `<div style="color: var(--error);">로그 로드 실패: ${e.message}</div>`;
            }
        }

