        let epRefPickerState = { level: 'characters', char: '', target: 'sidebar' };

        function epRefPickerGoBack() {
            epRefPickerState = { level: 'characters', char: '', target: epRefPickerState.target };
            loadEpRefPickerCharacters();
        }

        async function loadEpRefPickerCharacters() {
            const grid = document.getElementById('ep-ref-picker-grid');
            if (!grid) return;
            grid.innerHTML = '<div style="grid-column:1/-1; text-align:center; color:var(--text-secondary);">로딩중...</div>';
            document.getElementById('ep-ref-picker-back').style.display = 'none';
            try {
                const resp = await fetch('/api/asset_mode/characters');
                const data = await resp.json();
                const chars = data.characters || [];
                grid.innerHTML = '';
                if (chars.length === 0) { grid.innerHTML = '<div style="grid-column:1/-1; text-align:center; color:var(--text-secondary);">캐릭터가 없습니다</div>'; return; }
                chars.forEach(ch => {
                    const card = document.createElement('div');
                    card.style.cssText = 'cursor:pointer; border-radius:8px; border:2px solid var(--border); padding:16px 8px; text-align:center; transition:border-color 0.2s, background 0.2s;';
                    card.innerHTML = `<div style="font-size:1.2rem; margin-bottom:4px;">📁</div><div style="font-size:0.85rem; word-break:break-all;">${escapeHtml(ch)}</div>`;
                    card.onmouseenter = () => { card.style.borderColor = 'var(--accent)'; card.style.background = 'var(--surface2)'; };
                    card.onmouseleave = () => { card.style.borderColor = 'var(--border)'; card.style.background = 'transparent'; };
                    card.onclick = () => {
                        epRefPickerState = { level: 'gallery', char: ch, target: epRefPickerState.target };
                        loadEpRefPickerGallery(ch);
                    };
                    grid.appendChild(card);
                });
            } catch (e) { grid.innerHTML = '<div style="grid-column:1/-1; text-align:center; color:var(--error);">로드 실패</div>'; }
        }

        async function loadEpRefPickerGallery(char) {
            const grid = document.getElementById('ep-ref-picker-grid');
            if (!grid) return;
            const enc = encodeURIComponent;
            document.getElementById('ep-ref-picker-back').style.display = 'block';
            grid.innerHTML = '<div style="grid-column:1/-1; text-align:center; color:var(--text-secondary);">로딩중...</div>';
            try {
                const resp = await fetch(`/api/asset_mode/characters/${enc(char)}/gallery`);
                const data = await resp.json();
                const gallery = data.gallery || [];
                grid.innerHTML = '';
                if (gallery.length === 0) { grid.innerHTML = '<div style="grid-column:1/-1; text-align:center; color:var(--text-secondary);">에셋이 없습니다</div>'; return; }
                for (const item of gallery) {
                    const thumbUrl = item.representative
                        ? `/api/asset_mode/characters/${enc(char)}/outfits/${enc(item.outfit)}/expressions/${enc(item.expression)}/images/${enc(item.representative)}`
                        : '';
                    const card = document.createElement('div');
                    card.style.cssText = 'cursor:pointer; border-radius:8px; overflow:hidden; border:2px solid var(--border); transition:border-color 0.2s;';
                    card.innerHTML = thumbUrl
                        ? `<img src="${thumbUrl}" style="width:100%; display:block; aspect-ratio:1; object-fit:contain;" loading="lazy">`
                        : `<div style="width:100%; aspect-ratio:1; background:var(--surface2); display:flex; align-items:center; justify-content:center;">📁</div>`;
                    card.innerHTML += `<div style="font-size:0.7rem; padding:4px; text-align:center; background:var(--surface2);">${escapeHtml(item.outfit)} / ${escapeHtml(item.expression)}</div>`;
                    card.onmouseenter = () => card.style.borderColor = 'var(--accent)';
                    card.onmouseleave = () => card.style.borderColor = 'var(--border)';
                    card.onclick = async () => {
                        if (!thumbUrl) { showToast('대표 이미지가 없습니다', 'error'); return; }
                        if (epRefPickerState.target === 'sidebar') {
                            epRefImage = item.representative;
                            epRefImageLocalPath = item.local_path || '';
                            epRefPreviewUrl = thumbUrl;
                            document.getElementById('ep-ref-preview-img').src = thumbUrl;
                            document.getElementById('ep-ref-preview').style.display = 'block';
                        }
                        showToast('FACE-IPAdapter 이미지 선택 완료', 'success');
                        document.getElementById('ep-ref-picker-overlay').remove();
                    };
                    grid.appendChild(card);
                }
            } catch (e) { grid.innerHTML = '<div style="grid-column:1/-1; text-align:center; color:var(--error);">로드 실패</div>'; }
        }

