        async function startExprProfileGeneration() {
            if (epRunning) return;
            const selectedProfiles = epProfiles.filter(p => p.selected);
            if (selectedProfiles.length === 0) { showToast('선택된 표정이 없습니다', 'error'); return; }
            const charName = document.getElementById('ep-character-select').value;
            const appearanceName = document.getElementById('ep-appearance-select').value;
            const outfitName = document.getElementById('ep-outfit-select').value;
            if (!charName || !appearanceName || !outfitName) {
                showToast('캐릭터, 외모, 복장을 모두 선택하세요', 'error');
                return;
            }
            const sidebarRefEnabled = document.getElementById('ep-ref-toggle').checked;
            const sidebarRefStrength = parseFloat(document.getElementById('ep-ref-strength').value);
            const sidebarRefImage = epRefImage;
            const hrfEnabled = document.getElementById('ep-hrf-toggle').checked;
            const epHrfMode = document.getElementById('ep-hrf-mode')?.value || 'both';
            const epIsAnima = getAssetWorkflowCapabilities().dual;
            if (getAssetWorkflowCapabilities().type !== 'ilxl') { showToast('현재 ILXL 단독 모드만 지원합니다', 'error'); return; }
            const epAnimaHrf = epIsAnima && hrfEnabled ? (epHrfMode === 'sdxl' ? false : true) : false;
            const epEffectiveHrf = epIsAnima && hrfEnabled ? (epHrfMode === 'anima' ? false : true) : hrfEnabled;
            const fdEnabled = document.getElementById('ep-fd-toggle').checked;
            const hdEnabled = document.getElementById('ep-hd-toggle').checked;
            const edEnabled = document.getElementById('ep-ed-toggle').checked;
            const compositionPreset = document.getElementById('ep-composition-select').value;
            const qualityPreset = document.getElementById('ep-quality-select').value;
            const negativePreset = document.getElementById('ep-negative-select').value;
            const characterNegativePreset = document.getElementById('ep-character-negative-select').value;
            const artistPreset = document.getElementById('ep-artist-select').value;
            const naturalLanguagePreset = document.getElementById('ep-natural-language-select').value;

            const repeatCount = Math.max(1, parseInt(document.getElementById('ep-repeat-count').value) || 1);
            const totalJobs = selectedProfiles.length * repeatCount;

            epRunning = true;
            document.getElementById('ep-start-btn').disabled = true;
            document.getElementById('ep-stop-btn').style.display = 'inline-block';
            document.getElementById('ep-progress-bar').style.display = 'block';
            document.getElementById('ep-progress-inner').style.width = '0%';
            document.getElementById('ep-status-text').style.display = 'block';
            document.getElementById('ep-status-text').textContent = `준비중... (0/${totalJobs})`;
            showTopProgress();

            let completed = 0;
            let successCount = 0;
            let failCount = 0;
            const startTime = Date.now();

            function formatDuration(ms) {
                const s = Math.floor(ms / 1000);
                const m = Math.floor(s / 60);
                const sec = s % 60;
                return m > 0 ? `${m}분 ${sec}초` : `${sec}초`;
            }

            try {
                for (let round = 0; round < repeatCount; round++) {
                    for (let i = 0; i < selectedProfiles.length; i++) {
                        if (!epRunning) break;
                        const profile = selectedProfiles[i];
                        const jobNum = completed + 1;
                        const elapsed = Date.now() - startTime;
                        const avgMs = completed > 0 ? elapsed / completed : 0;
                        const remainMs = completed > 0 ? avgMs * (totalJobs - completed) : 0;

                        document.getElementById('ep-status-text').textContent =
                            `${round + 1}바퀴 — ${profile.name} (${jobNum}/${totalJobs}) | 경과: ${formatDuration(elapsed)} | 남은 시간: ~${formatDuration(remainMs)}`;
                        document.getElementById('ep-progress-inner').style.width =
                            `${(completed / totalJobs * 100).toFixed(1)}%`;

                        const useRef = profile.ref_enabled ? true : sidebarRefEnabled;
                        const useRefImage = profile.ref_enabled ? profile.ref_image : sidebarRefImage;
                        const useRefLocalPath = profile.ref_enabled ? (profile.ref_local_path || '') : epRefImageLocalPath;
                        const useRefStrength = profile.ref_enabled ? profile.ref_strength : sidebarRefStrength;

                        const genPayload = {
                            character: charName,
                            appearance: appearanceName,
                            outfit: outfitName,
                            expression: profile.name,
                            face_id_enabled: useRef,
                            face_id_strength: useRefStrength,
                            reference_images: useRefImage ? [{filename: useRefImage, local_path: useRefLocalPath}] : [],
                            pose_enabled: false,
                            pose_id: '',
                            fd_activate: profile.fd_enabled ? true : fdEnabled,
                            hrf_activate: (function() {
                                const hrfOn = profile.hrf_enabled ? true : hrfEnabled;
                                if (!epIsAnima) return hrfOn;
                                const mode = profile.hrf_mode || epHrfMode;
                                return hrfOn ? (mode === 'anima' ? false : true) : false;
                            })(),
                            anima_hrf_activate: (function() {
                                const hrfOn = profile.hrf_enabled ? true : hrfEnabled;
                                if (!epIsAnima) return false;
                                const mode = profile.hrf_mode || epHrfMode;
                                return hrfOn ? (mode === 'sdxl' ? false : true) : false;
                            })(),
                            hd_activate: profile.hd_enabled ? true : hdEnabled,
                            ed_activate: profile.ed_enabled ? true : edEnabled,
                            artist_preset: artistPreset || '',
                            natural_language: naturalLanguagePreset
                                ? (assetTags?.natural_language_presets?.[naturalLanguagePreset] || '')
                                : '',
                        };

                        // 개별 고급 설정 우선, 없으면 글로벌 설정 사용
                        const effectiveComp = profile.composition_preset || compositionPreset;
                        const effectiveQual = profile.quality_preset || qualityPreset;
                        const effectiveNeg = profile.negative_preset || negativePreset;

                        try {
                            if (effectiveComp) {
                                await fetch('/api/asset_mode/tags', {
                                    method: 'POST',
                                    headers: { 'Content-Type': 'application/json' },
                                    body: JSON.stringify({ action: 'load_composition_preset', name: effectiveComp })
                                });
                            }
                            if (effectiveQual) {
                                await fetch('/api/asset_mode/tags', {
                                    method: 'POST',
                                    headers: { 'Content-Type': 'application/json' },
                                    body: JSON.stringify({ action: 'load_quality_preset', name: effectiveQual })
                                });
                            }
                            if (effectiveNeg) {
                                await fetch('/api/asset_mode/tags', {
                                    method: 'POST',
                                    headers: { 'Content-Type': 'application/json' },
                                    body: JSON.stringify({ action: 'load_negative_preset', name: effectiveNeg })
                                });
                            }
                            if (characterNegativePreset) {
                                await fetch('/api/asset_mode/tags', {
                                    method: 'POST',
                                    headers: { 'Content-Type': 'application/json' },
                                    body: JSON.stringify({ action: 'load_character_negative_preset', name: characterNegativePreset })
                                });
                            }
                            // ANIMA 프리셋 로드
                            if (epIsAnima) {
                                const animaQualPreset = getAssetSelectValue('anima-quality-preset-select') || '';
                                const animaNegPreset = getAssetSelectValue('anima-negative-preset-select') || '';
                                if (animaQualPreset) {
                                    await fetch('/api/asset_mode/tags', {
                                        method: 'POST',
                                        headers: { 'Content-Type': 'application/json' },
                                        body: JSON.stringify({ action: 'load_anima_quality_preset', name: animaQualPreset })
                                    });
                                }
                                if (animaNegPreset) {
                                    await fetch('/api/asset_mode/tags', {
                                        method: 'POST',
                                        headers: { 'Content-Type': 'application/json' },
                                        body: JSON.stringify({ action: 'load_anima_negative_preset', name: animaNegPreset })
                                    });
                                }
                            }

                            const resp = await fetch('/api/asset_mode/generate', {
                                method: 'POST',
                                headers: { 'Content-Type': 'application/json' },
                                body: JSON.stringify(genPayload)
                            });
                            const result = await resp.json();
                            if (result.success) {
                                successCount++;
                            } else {
                                failCount++;
                                showToast(`[${profile.name}] ${result.error || '생성 실패'}`, 'error');
                            }
                        } catch (e) {
                            failCount++;
                            showToast(`[${profile.name}] 요청 실패: ${e.message}`, 'error');
                        }
                        completed++;
                        document.getElementById('ep-progress-inner').style.width =
                            `${(completed / totalJobs * 100).toFixed(1)}%`;
                        try { await scanExprProfilePresets(); } catch(e) {}
                    }
                    if (!epRunning) break;
                }

                document.getElementById('ep-status-text').textContent =
                    `완료 — 성공: ${successCount}, 실패: ${failCount} (총 ${totalJobs}건) | 소요: ${formatDuration(Date.now() - startTime)}`;
                if (successCount > 0) showToast(`표정 프로필 생성 완료 (${successCount}장)`, 'success');
                if (failCount > 0 && successCount === 0) showToast('모든 생성 실패', 'error');
            } finally {
                epRunning = false;
                document.getElementById('ep-start-btn').disabled = false;
                document.getElementById('ep-stop-btn').style.display = 'none';
                hideTopProgress();
                await scanExprProfilePresets();
            }
        }

        function stopExprProfileGeneration() {
            epRunning = false;
        }

        let epColumns = 3;
        function epChangeColumns(delta) {
            epColumns = Math.min(8, Math.max(2, epColumns + delta));
            document.getElementById('ep-col-count').textContent = epColumns;
            const grid = document.getElementById('ep-grid');
            if (grid) grid.style.gridTemplateColumns = `repeat(${epColumns}, minmax(120px, 1fr))`;
        }

        // ─── 오토매치 ────────────────────────────────────────────
        const atState = {
            images: [],          // {file, url, tags, status: 'pending'|'analyzing'|'done'|'error', error}
            matches: [],         // [{...match_result, selected: bool}] (태그 매칭 결과)
            imageMatches: [],    // [{imageName, tags, matches: [{...match_result, selected: bool}]}] (이미지별 결과)
            embeddingMatches: [], // [{...embedding_result, selected: bool}] (임베딩 매칭 결과)
            compareImages: {},    // {presetName: imageUrl} 비교 캐릭터 이미지 맵
            compareImageMeta: {}, // {presetName: {source, outfit, expression, filename}}
            chains: [],          // 제안된 체인
            // 개별 큐 추적
            queueItemIds: [],    // 현재 세션에서 추가한 큐 아이템 ID 목록
            analyzeTotal: 0,     // 전체 분석/매칭 큐 아이템 수
            analyzeCompleted: 0, // 완료된 큐 아이템 수
        };

        const atFillSlot = {
            character: '', appearance: '', outfit: '', expression: '',
            use_existing_assets: true,
            composition_preset: '', quality_preset: '', negative_preset: '',
            character_negative_preset: '', artist_preset: '', natural_language_preset: '',
            anima_artist_preset: '', anima_quality_preset: '', anima_negative_preset: '',
            natural_language: '',
            ref_enabled: false, ref_strength: 0.55, ref_images: [], ref_dir: '',
            style_ref_enabled: false, style_ref_strength: 0.55, style_ref_images: [], style_ref_dir: '',
            snapref_enabled: false, snapref_images: [], snapref_dir: '',
            snapref_strength: 0, snapref_mode: 'char', snapref_megapixels: 1,
            lora_enabled: false, lora_list: [], style_lora_enabled: false, style_lora_list: [],
            face_lora_enabled: false, face_lora_list: [], face_tags: '', eye_tags: '',
            face_crop_top: 2.5, face_crop_bottom: 1, face_lora_upscale_size: '',
            pose_enabled: false, pose_id: '',
            hrf_sdxl: false, hrf_anima: false, hrf_size: 2.0,
            hrf_restore_size: true, hrf_control_net: false,
            img_w: 700, img_h: 1024,
            sdxl_fd_enabled: false, sdxl_hd_enabled: false, sdxl_ed_enabled: false,
            anima_fd_enabled: false, anima_hd_enabled: false, anima_ed_enabled: false,
            seed: -1,
        };
        const AT_MATCH_RESULT_LIMIT = 12;
        const AT_MATCH_PAGE_SIZE = 4;
        const atMatchPages = { embedding: {}, tag: {} };
        function atCreateFillRunState(matchType) {
            return {
                matchType,
                running: false,
                queueing: false,
                pendingExpressions: new Set(),
                queueItems: new Map(),
                completed: 0,
                failed: 0,
                cancelled: 0,
                total: 0,
            };
        }
        const atFillRuns = {
            embedding: atCreateFillRunState('embedding'),
            tag: atCreateFillRunState('tag'),
        };
        const atFillReservedExpressions = new Set();
        let atFillPreviewMatchType = 'embedding';

        _atLoadState();
        // 초기 업로드 화면 렌더 (이미지가 없으면 빈 상태 안내 표시)
        if (typeof atRenderImages === 'function') atRenderImages();

        function atOnFilesSelected(files) {
            for (const file of files) {
                if (!file.type.startsWith('image/')) continue;
                const url = URL.createObjectURL(file);
                atState.images.push({ file, url, tags: null, status: 'pending', error: null });
            }
            // 새 이미지 추가 시 업로드 태그 미리보기 상태 리셋
            atTagPreviewDone = false;
            atCheckReadyStates();
            atRenderImages();
            atEmotionUpdatePreview();
            document.getElementById('at-analyze-btn').disabled = atState.images.length === 0;
            document.getElementById('at-clear-btn').disabled = atState.images.length === 0;
        }

        function atRemoveImage(index) {
            const item = atState.images[index];
            if (item.url) URL.revokeObjectURL(item.url);
            atState.images.splice(index, 1);
            atRenderImages();
            atEmotionUpdatePreview();
            document.getElementById('at-analyze-btn').disabled = atState.images.length === 0;
        }

        function atSwitchView(view) {
            atCloseUploadModal();
            document.getElementById('at-view-upload').style.display = view === 'upload' ? '' : 'none';
            document.getElementById('at-view-result').style.display = view === 'result' ? 'flex' : 'none';
            document.getElementById('at-view-embed').style.display = view === 'embed' ? '' : 'none';
            document.getElementById('at-sidebar-upload').classList.toggle('active', view === 'upload');
            document.getElementById('at-sidebar-result').classList.toggle('active', view === 'result');
            document.getElementById('at-sidebar-embed').classList.toggle('active', view === 'embed');
            if (view === 'result') {
                atInitFillPanel();
                atRenderSourceCards();
            }
            if (view === 'embed') atInitEmbedView();
            if (view === 'upload') { atCheckReadyStates(); atRenderImages(); }
        }

        function atSetFillSelectOptions(id, values, selected, placeholder) {
            const select = document.getElementById(id);
            if (!select) return;
            select.innerHTML = '';
            const empty = document.createElement('option');
            empty.value = '';
            empty.textContent = placeholder;
            select.appendChild(empty);
            Object.keys(values || {}).sort().forEach(name => {
                const option = document.createElement('option');
                option.value = name;
                option.textContent = name;
                select.appendChild(option);
            });
            if (selected && Object.prototype.hasOwnProperty.call(values || {}, selected)) {
                select.value = selected;
            }
        }

        function atInitFillPanel() {
            const capabilities = getAssetWorkflowCapabilities();
            const badge = document.getElementById('at-fill-mode-badge');
            if (badge) {
                badge.textContent = capabilities.type === 'anima_only' ? 'ONLY ANIMA' : (capabilities.dual ? 'ANIMA+ILXL' : 'ILXL');
                badge.classList.toggle('anima', capabilities.anima);
            }
            atApplyFillWorkflowAvailability();
            atUpdateFillHiresAvailability();
            if (!assetTags) {
                console.warn('[AUTOMATCH] 생성 패널 초기화 보류: assetTags가 아직 로드되지 않음');
                atUpdateFillPromptPreview();
                return;
            }
            atSetFillSelectOptions('at-fill-appearance', assetTags.appearances, atFillSlot.appearance, '-- 외모 --');
            atSetFillSelectOptions('at-fill-outfit', assetTags.outfits, atFillSlot.outfit, '-- 복장 --');
            atSetFillSelectOptions('at-fill-composition', assetTags.composition_presets, atFillSlot.composition_preset, '-- 구도 프리셋 --');
            atSetFillSelectOptions('at-fill-quality', assetTags.quality_presets, atFillSlot.quality_preset, '-- ILXL 품질 프리셋 --');
            atSetFillSelectOptions('at-fill-character-negative', assetTags.character_negative_presets, atFillSlot.character_negative_preset, '-- 캐릭터 부정 --');
            atSetFillSelectOptions('at-fill-negative', assetTags.negative_presets, atFillSlot.negative_preset, '-- ILXL 부정 프리셋 --');
            atSetFillSelectOptions('at-fill-artist', assetTags.artist_presets, atFillSlot.artist_preset, '-- ILXL 아티스트 --');
            atSetFillSelectOptions('at-fill-anima-artist', assetTags.artist_presets, atFillSlot.anima_artist_preset, '-- ANIMA 아티스트 --');
            atSetFillSelectOptions('at-fill-anima-quality', assetTags.quality_presets, atFillSlot.anima_quality_preset, '-- ANIMA 품질 프리셋 --');
            atSetFillSelectOptions('at-fill-anima-negative', assetTags.negative_presets, atFillSlot.anima_negative_preset, '-- ANIMA 부정 프리셋 --');
            atSetFillSelectOptions('at-fill-natural-language', assetTags.natural_language_presets, atFillSlot.natural_language_preset, '-- 자연어 프리셋 --');
            const characterSelect = document.getElementById('at-compare-char');
            if (characterSelect && atFillSlot.character) characterSelect.value = atFillSlot.character;
            const controlValues = {
                'at-fill-ref-enabled': !!atFillSlot.ref_enabled,
                'at-fill-style-ref-enabled': !!atFillSlot.style_ref_enabled,
                'at-fill-lora-enabled': !!atFillSlot.lora_enabled,
                'at-fill-style-lora-enabled': !!atFillSlot.style_lora_enabled,
                'at-fill-snapref-enabled': !!atFillSlot.snapref_enabled,
                'at-fill-face-lora-enabled': !!atFillSlot.face_lora_enabled,
                'at-fill-pose-enabled': !!atFillSlot.pose_enabled,
                'at-fill-hrf': !!atFillSlot.hrf_sdxl,
                'at-fill-anima-hrf': !!atFillSlot.hrf_anima,
                'at-fill-hrf-restore': atFillSlot.hrf_restore_size !== false,
                'at-fill-hrf-control': !!atFillSlot.hrf_control_net,
                'at-fill-fd': !!atFillSlot.sdxl_fd_enabled,
                'at-fill-hd': !!atFillSlot.sdxl_hd_enabled,
                'at-fill-ed': !!atFillSlot.sdxl_ed_enabled,
                'at-fill-anima-fd': !!atFillSlot.anima_fd_enabled,
                'at-fill-anima-hd': !!atFillSlot.anima_hd_enabled,
                'at-fill-anima-ed': !!atFillSlot.anima_ed_enabled,
                'at-fill-use-existing': atFillSlot.use_existing_assets !== false,
            };
            Object.entries(controlValues).forEach(([id, checked]) => {
                const element = document.getElementById(id);
                if (element) element.checked = checked;
            });
            const numericValues = {
                'at-fill-ref-strength': atFillSlot.ref_strength,
                'at-fill-style-ref-strength': atFillSlot.style_ref_strength,
                'at-fill-snapref-strength': atFillSlot.snapref_strength ?? 0,
                'at-fill-snapref-megapixels': atFillSlot.snapref_megapixels ?? 1,
                'at-fill-hrf-size': atFillSlot.hrf_size,
                'at-fill-img-w': atFillSlot.img_w,
                'at-fill-img-h': atFillSlot.img_h,
                'at-fill-face-crop-top': atFillSlot.face_crop_top,
                'at-fill-face-crop-bottom': atFillSlot.face_crop_bottom,
                'at-fill-face-upscale': atFillSlot.face_lora_upscale_size,
                'at-fill-seed': atFillSlot.seed,
            };
            Object.entries(numericValues).forEach(([id, value]) => {
                const element = document.getElementById(id);
                if (element) element.value = value;
            });
            const refControls = document.getElementById('at-fill-ref-controls');
            const styleRefControls = document.getElementById('at-fill-style-ref-controls');
            if (refControls) refControls.style.display = atFillSlot.ref_enabled ? 'block' : 'none';
            if (styleRefControls) styleRefControls.style.display = atFillSlot.style_ref_enabled ? 'block' : 'none';
            const conditionalControls = {
                'at-fill-lora-controls': !!atFillSlot.lora_enabled,
                'at-fill-style-lora-controls': !!atFillSlot.style_lora_enabled,
                'at-fill-snapref-controls': !!atFillSlot.snapref_enabled,
                'at-fill-face-lora-controls': !!atFillSlot.face_lora_enabled,
                'at-fill-pose-controls': !!atFillSlot.pose_enabled,
            };
            Object.entries(conditionalControls).forEach(([id, visible]) => {
                const element = document.getElementById(id);
                if (element) element.style.display = visible ? 'block' : 'none';
            });
            const snaprefPreview = document.getElementById('at-fill-snapref-preview');
            if (snaprefPreview) {
                snaprefPreview.innerHTML = (atFillSlot.snapref_images || []).slice(0, 1).map(image => `<img src="${escapeHtml(image.preview_url || '')}" alt="Ref 이미지">`).join('');
                snaprefPreview.style.display = atFillSlot.snapref_images?.length ? 'grid' : 'none';
            }
            const textValues = {
                'at-fill-snapref-mode': atFillSlot.snapref_mode || 'char',
                'at-fill-natural-language-text': atFillSlot.natural_language || '',
                'at-fill-face-tags': atFillSlot.face_tags || '',
                'at-fill-eye-tags': atFillSlot.eye_tags || '',
            };
            Object.entries(textValues).forEach(([id, value]) => {
                const element = document.getElementById(id);
                if (element) element.value = value;
            });
            const refStrengthValue = document.getElementById('at-fill-ref-strength-value');
            if (refStrengthValue) refStrengthValue.textContent = Number(atFillSlot.ref_strength ?? 0.55).toFixed(2);
            const styleRefStrengthValue = document.getElementById('at-fill-style-ref-strength-value');
            if (styleRefStrengthValue) styleRefStrengthValue.textContent = Number(atFillSlot.style_ref_strength ?? 0.55).toFixed(2);
            const hrfSizeValue = document.getElementById('at-fill-hrf-size-value');
            if (hrfSizeValue) hrfSizeValue.textContent = Number(atFillSlot.hrf_size || 2).toFixed(2);
            atRenderFillLoraList('lora');
            atRenderFillLoraList('style_lora');
            atRenderFillLoraList('face_lora');
            atUpdateFillPoseDisplay();
            atUpdateFillAvailability();
        }

        async function atLoadAssetSettings() {
            let raw;
            try {
                raw = localStorage.getItem('assetModeSettings');
            } catch (e) {
                console.error('[AUTOMATCH] 에셋 생성 설정 불러오기 실패: 캐시 접근 오류', e);
                showToast('에셋 생성 설정 불러오기 실패', 'error');
                return;
            }
            if (!raw) {
                console.error('[AUTOMATCH] 에셋 생성 설정 불러오기 실패: 저장된 캐시 없음');
                showToast('에셋 생성에 저장된 설정이 없습니다', 'error');
                return;
            }

            let settings;
            try {
                settings = JSON.parse(raw);
            } catch (e) {
                console.error('[AUTOMATCH] 에셋 생성 설정 불러오기 실패: 캐시 JSON 파싱 오류', e);
                showToast('저장된 설정 형식이 올바르지 않습니다', 'error');
                return;
            }
            if (!settings || typeof settings !== 'object' || Array.isArray(settings)) {
                console.error('[AUTOMATCH] 에셋 생성 설정 불러오기 실패: 캐시 형식 오류', settings);
                showToast('저장된 설정 형식이 올바르지 않습니다', 'error');
                return;
            }

            try {
                if (!assetTags) {
                    const response = await fetch('/api/asset_mode/tags');
                    if (!response.ok) throw new Error(`태그 데이터 HTTP ${response.status}`);
                    assetTags = await response.json();
                }
                if (!assetTags || typeof assetTags !== 'object') {
                    throw new Error('에셋 태그 데이터가 준비되지 않았습니다');
                }

                const capabilities = getAssetWorkflowCapabilities();
                const failures = [];
                let loadedCount = 0;
                const recordFailure = (label, reason, value) => {
                    failures.push(label);
                    console.error(`[AUTOMATCH] 에셋 생성 설정 항목 불러오기 실패: ${label} - ${reason}`, value);
                };
                const setSelect = (target, sourceKey, label, available = true) => {
                    if (!available || settings[sourceKey] === undefined) return;
                    const value = settings[sourceKey] === null ? '' : String(settings[sourceKey]);
                    const optionSourceKey = sourceKey.startsWith('anima_') ? sourceKey.slice('anima_'.length) : sourceKey;
                    const options = assetTags[optionSourceKey === 'character' ? 'characters' : optionSourceKey === 'appearance' ? 'appearances'
                        : optionSourceKey === 'outfit' ? 'outfits' : `${optionSourceKey.replace(/_preset$/, '')}_presets`] || {};
                    if (value && !Object.prototype.hasOwnProperty.call(options, value)) {
                        recordFailure(label, '저장값과 일치하는 옵션 없음', value);
                        return;
                    }
                    atFillSlot[target] = value;
                    loadedCount++;
                };
                const setBoolean = (target, sourceKey, label, available = true) => {
                    if (!available || settings[sourceKey] === undefined) return;
                    if (typeof settings[sourceKey] !== 'boolean') {
                        recordFailure(label, 'ON/OFF 값 형식 오류', settings[sourceKey]);
                        return;
                    }
                    atFillSlot[target] = settings[sourceKey];
                    loadedCount++;
                };
                const setNumber = (target, sourceKey, label, available = true) => {
                    if (!available || settings[sourceKey] === undefined || settings[sourceKey] === null) return;
                    const value = Number(settings[sourceKey]);
                    if (!Number.isFinite(value)) {
                        recordFailure(label, '숫자 값 형식 오류', settings[sourceKey]);
                        return;
                    }
                    atFillSlot[target] = value;
                    loadedCount++;
                };
                const setString = (target, sourceKey, label, available = true) => {
                    if (!available || settings[sourceKey] === undefined || settings[sourceKey] === null) return;
                    if (typeof settings[sourceKey] !== 'string' && typeof settings[sourceKey] !== 'number') {
                        recordFailure(label, '문자열 값 형식 오류', settings[sourceKey]);
                        return;
                    }
                    atFillSlot[target] = String(settings[sourceKey]);
                    loadedCount++;
                };
                const setLoraList = (target, sourceKey, label, available = true) => {
                    if (!available || settings[sourceKey] === undefined) return;
                    if (!Array.isArray(settings[sourceKey])) {
                        recordFailure(label, '목록 형식 오류', settings[sourceKey]);
                        return;
                    }
                    const invalidIndex = settings[sourceKey].findIndex(item => {
                        return !item || typeof item !== 'object' || Array.isArray(item)
                            || !Number.isFinite(Number(item.strength));
                    });
                    if (invalidIndex >= 0) {
                        recordFailure(label, `목록 ${invalidIndex + 1}번 항목 형식 오류`, settings[sourceKey][invalidIndex]);
                        return;
                    }
                    const clonedItems = settings[sourceKey].map(item => ({ ...item, strength: Number(item.strength) }));
                    const compatibleItems = filterAssetLorasForCapabilities(clonedItems, capabilities);
                    if (compatibleItems.length !== clonedItems.length) {
                        console.warn(
                            `[AUTOMATCH] ${label}에서 현재 워크플로와 호환되지 않는 항목을 제외했습니다:`,
                            clonedItems.filter(item => !compatibleItems.includes(item)),
                        );
                    }
                    atFillSlot[target] = compatibleItems;
                    loadedCount++;
                };

                setSelect('character', 'character', '캐릭터');
                setSelect('appearance', 'appearance', '외모');
                setSelect('outfit', 'outfit', '복장');
                setSelect('composition_preset', 'composition_preset', '구도 프리셋');
                setSelect('character_negative_preset', 'character_negative_preset', '캐릭터 부정 프리셋');
                setSelect('natural_language_preset', 'natural_language_preset', '자연어 프리셋');
                setSelect('quality_preset', 'quality_preset', 'ILXL 품질 프리셋', capabilities.ilxl);
                setSelect('negative_preset', 'negative_preset', 'ILXL 부정 프리셋', capabilities.ilxl);
                setSelect('artist_preset', 'artist_preset', 'ILXL 아티스트 프리셋', capabilities.ilxl);
                setSelect('anima_artist_preset', 'anima_artist_preset', 'ANIMA 아티스트 프리셋', capabilities.anima);
                setSelect('anima_quality_preset', 'anima_quality_preset', 'ANIMA 품질 프리셋', capabilities.anima);
                setSelect('anima_negative_preset', 'anima_negative_preset', 'ANIMA 부정 프리셋', capabilities.anima);

                // 표정은 매칭 결과별로 자동 결정되므로 에셋 생성의 저장 표정은 적용하지 않는다.
                setString('natural_language', 'natural_language_text', '자연어 직접 입력');
                setBoolean('ref_enabled', 'ref_enabled', 'FACE-IPAdapter 사용 상태', capabilities.ipadapter);
                setNumber('ref_strength', 'ref_strength', 'FACE-IPAdapter 강도', capabilities.ipadapter);
                setString('ref_dir', 'ref_dir', 'FACE-IPAdapter 저장 폴더', capabilities.ipadapter);
                setBoolean('style_ref_enabled', 'style_ref_enabled', 'IPAdapter 사용 상태', capabilities.ipadapter);
                setNumber('style_ref_strength', 'style_ref_strength', 'IPAdapter 강도', capabilities.ipadapter);
                setString('style_ref_dir', 'style_ref_dir', 'IPAdapter 저장 폴더', capabilities.ipadapter);
                setBoolean('snapref_enabled', 'snapref_enabled', 'Ref 이미지 사용 상태', capabilities.anima);
                setString('snapref_dir', 'snapref_dir', 'Ref 이미지 저장 폴더', capabilities.anima);
                setNumber('snapref_strength', 'snapref_strength', 'Ref 이미지 강도', capabilities.anima);
                setString('snapref_mode', 'snapref_mode', 'Ref 이미지 모드', capabilities.anima);
                setNumber('snapref_megapixels', 'snapref_megapixels', 'Ref 이미지 참조 해상도', capabilities.anima);
                if (capabilities.anima && Array.isArray(settings.snapref_images)) {
                    atFillSlot.snapref_images = settings.snapref_images.slice(0, 1).map(image => ({...image}));
                }
                setBoolean('lora_enabled', 'lora_enabled', 'LoRA 사용 상태');
                setLoraList('lora_list', 'lora_list', 'LoRA 목록');
                setBoolean('style_lora_enabled', 'style_lora_enabled', 'Style LoRA 사용 상태');
                setLoraList('style_lora_list', 'style_lora_list', 'Style LoRA 목록');
                setBoolean('pose_enabled', 'pose_enabled', '포즈 사용 상태', capabilities.pose);
                setString('pose_id', 'pose_id', '포즈', capabilities.pose);
                setNumber('img_w', 'img_w', '이미지 너비');
                setNumber('img_h', 'img_h', '이미지 높이');
                setBoolean('hrf_sdxl', 'hrf_sdxl', 'HRF ILXL', capabilities.ilxl);
                setBoolean('hrf_anima', 'hrf_anima', 'HRF ANIMA', capabilities.anima);
                setNumber('hrf_size', 'hrf_size', 'HRF 업스케일링 비율');
                setBoolean('hrf_restore_size', 'hrf_restore_size', 'HRF RESTORE SIZE');
                setBoolean('hrf_control_net', 'hrf_control_net', 'HRF CONTROL NET');
                setBoolean('sdxl_fd_enabled', 'sdxl_fd', 'ILXL FD', capabilities.ilxl);
                setBoolean('sdxl_hd_enabled', 'sdxl_hd', 'ILXL HD', capabilities.ilxl);
                setBoolean('sdxl_ed_enabled', 'sdxl_ed', 'ILXL ED', capabilities.ilxl);
                setBoolean('anima_fd_enabled', 'anima_fd', 'ANIMA FD', capabilities.anima);
                setBoolean('anima_hd_enabled', 'anima_hd', 'ANIMA HD', capabilities.anima);
                setBoolean('anima_ed_enabled', 'anima_ed', 'ANIMA ED', capabilities.anima);
                setBoolean('face_lora_enabled', 'face_lora_enabled', 'Face LoRA 사용 상태', capabilities.anima);
                setLoraList('face_lora_list', 'face_lora_list', 'Face LoRA 목록', capabilities.anima);
                setNumber('face_crop_top', 'face_crop_top', 'FACE_CROP TOP', capabilities.anima);
                setNumber('face_crop_bottom', 'face_crop_bottom', 'FACE_CROP BOTTOM', capabilities.anima);
                setString('face_tags', 'face_tags', 'FACE_TAGS', capabilities.anima);
                setString('eye_tags', 'eye_tags', 'EYE_TAGS', capabilities.anima);
                setString('face_lora_upscale_size', 'face_lora_upscale_size', 'Face LoRA 고정 사이즈', capabilities.anima);
                setNumber('seed', 'seed', 'Seed', capabilities.anima);

                ['ref_images', 'style_ref_images'].forEach(key => {
                    (atFillSlot[key] || []).forEach(image => {
                        if (typeof image?.preview_url === 'string' && image.preview_url.startsWith('blob:')) {
                            URL.revokeObjectURL(image.preview_url);
                        }
                    });
                    atFillSlot[key] = [];
                });
                ['at-fill-ref-preview', 'at-fill-style-ref-preview'].forEach(id => {
                    const preview = document.getElementById(id);
                    if (preview) {
                        preview.innerHTML = '';
                        preview.style.display = 'none';
                    }
                });

                if (loadedCount === 0) {
                    console.error('[AUTOMATCH] 에셋 생성 설정 불러오기 실패: 지원하는 저장 항목 없음', settings);
                    showToast('오토매치에서 불러올 수 있는 저장 설정이 없습니다', 'error');
                    return;
                }

                atInitFillPanel();
                const characterSelect = document.getElementById('at-compare-char');
                if (characterSelect) {
                    const character = atFillSlot.character || '';
                    if (character && !Array.from(characterSelect.options).some(option => option.value === character)) {
                        characterSelect.appendChild(new Option(character, character));
                    }
                    characterSelect.value = character;
                } else {
                    recordFailure('비교 캐릭터', '선택 컨트롤 없음', 'at-compare-char');
                }
                await atLoadCompareImages({ silent: true });
                _atSaveState();

                if (failures.length) {
                    const uniqueFailures = [...new Set(failures)];
                    console.error('[AUTOMATCH] 에셋 생성 설정 일부 불러오기 실패:', uniqueFailures);
                    showToast(`일부 저장 설정을 불러오지 못했습니다: ${uniqueFailures.join(', ')}`, 'warning');
                    return;
                }
                showToast('에셋 생성의 저장 설정을 불러왔습니다 (표정 제외)', 'success');
            } catch (e) {
                console.error('[AUTOMATCH] 에셋 생성 설정 불러오기 예외:', e);
                showToast('에셋 생성 설정 불러오기 실패: ' + e.message, 'error');
            }
        }

        function atApplyFillWorkflowAvailability() {
            const capabilities = getAssetWorkflowCapabilities();
            document.querySelectorAll('#at-view-result [data-at-availability]').forEach(container => {
                const availability = container.dataset.atAvailability;
                const available = availability === 'anima' ? capabilities.anima
                    : availability === 'sdxl-only' || availability === 'ilxl' ? capabilities.ilxl
                    : availability === 'pose' ? capabilities.pose
                    : availability === 'ipadapter' ? capabilities.ipadapter
                    : true;
                container.classList.toggle('is-unavailable', !available);
                container.querySelectorAll('input, select, button').forEach(control => {
                    control.disabled = !available;
                });
            });
        }

        function atUpdateFillHiresAvailability() {
            const capabilities = getAssetWorkflowCapabilities();
            const enabled = (capabilities.ilxl && !!atFillSlot.hrf_sdxl) || (capabilities.anima && !!atFillSlot.hrf_anima);
            const container = document.getElementById('at-fill-hrf-options');
            if (!container) return;
            container.classList.toggle('is-unavailable', !enabled);
            container.setAttribute('aria-disabled', enabled ? 'false' : 'true');
            container.querySelectorAll('input').forEach(control => { control.disabled = !enabled; });
        }

        function atUpdateFillPoseDisplay() {
            const display = document.getElementById('at-fill-pose-display');
            if (!display) return;
            if (atFillSlot.pose_id) {
                const imageUrl = `/api/pose_mode/poses/${encodeURIComponent(atFillSlot.pose_id)}/image`;
                display.innerHTML = `<img src="${imageUrl}" loading="lazy"><span>${escapeHtml(atFillSlot.pose_id)}</span>`;
            } else {
                display.innerHTML = '<span class="placeholder">클릭하여 포즈 선택</span>';
            }
        }

        async function atLoadCharacterList() {
            try {
                const resp = await fetch('/api/asset_mode/characters');
                if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
                const data = await resp.json();
                const sel = document.getElementById('at-compare-char');
                if (!sel) {
                    console.error('[AUTOMATCH] 비교 캐릭터 선택 요소를 찾지 못했습니다');
                    return;
                }
                const curVal = atFillSlot.character || sel.value;
                sel.innerHTML = '<option value="">-- 캐릭터 --</option>';
                (data.characters || []).forEach(name => {
                    const opt = document.createElement('option');
                    opt.value = name;
                    opt.textContent = name;
                    sel.appendChild(opt);
                });
                if (curVal && (data.characters || []).includes(curVal)) {
                    sel.value = curVal;
                    atFillSlot.character = curVal;
                }
                atInitFillPanel();
                if (atFillSlot.character) await atLoadCompareImages({ silent: true });
            } catch (e) {
                console.error('[AUTOMATCH] 캐릭터 목록 로드 오류:', e);
            }
        }

        let atManagerLoadToken = 0;

        async function atOpenImageManager() {
            const modal = document.getElementById('at-image-manager-modal');
            const select = document.getElementById('at-manager-character');
            const grid = document.getElementById('at-manager-grid');
            const summary = document.getElementById('at-manager-summary');
            if (!modal || !select || !grid || !summary) {
                console.error('[AUTOMATCH_MANAGE] 이미지 관리 창 요소를 찾지 못했습니다', {
                    modal: !!modal,
                    select: !!select,
                    grid: !!grid,
                    summary: !!summary,
                });
                showToast('오토매치 이미지 관리 창을 열 수 없습니다', 'error');
                return;
            }

            modal.classList.add('visible');
            select.disabled = true;
            summary.textContent = '캐릭터 목록을 불러오는 중…';
            grid.innerHTML = '<div class="at-manager-message">불러오는 중…</div>';
            try {
                const response = await fetch('/api/asset_mode/characters');
                const data = await response.json();
                if (!response.ok) throw new Error(data.error || `HTTP ${response.status}`);
                const characters = data.characters || [];
                const currentCharacter = document.getElementById('at-compare-char')?.value || atFillSlot.character || '';
                select.innerHTML = '<option value="">-- 캐릭터 --</option>';
                characters.forEach(character => {
                    const option = document.createElement('option');
                    option.value = character;
                    option.textContent = character;
                    select.appendChild(option);
                });
                if (currentCharacter && characters.includes(currentCharacter)) {
                    select.value = currentCharacter;
                } else if (characters.length === 1) {
                    select.value = characters[0];
                }
                select.disabled = false;
                if (select.value) {
                    await atLoadManagedImages();
                } else {
                    summary.textContent = characters.length ? '캐릭터를 선택하세요.' : '등록된 캐릭터가 없습니다.';
                    grid.innerHTML = `<div class="at-manager-message">${characters.length ? '관리할 캐릭터를 선택하세요.' : '등록된 캐릭터가 없습니다.'}</div>`;
                }
            } catch (e) {
                select.disabled = false;
                summary.textContent = '목록 로드 실패';
                grid.innerHTML = '<div class="at-manager-message">이미지 목록을 불러오지 못했습니다.</div>';
                console.error('[AUTOMATCH_MANAGE] 이미지 관리 창 초기화 실패:', e);
                showToast('오토매치 이미지 관리 창 로드 실패: ' + e.message, 'error');
            }
        }

        function atCloseImageManager() {
            atManagerLoadToken++;
            document.getElementById('at-image-manager-modal')?.classList.remove('visible');
        }

        async function atLoadManagedImages() {
            const select = document.getElementById('at-manager-character');
            const grid = document.getElementById('at-manager-grid');
            const summary = document.getElementById('at-manager-summary');
            if (!select || !grid || !summary) {
                console.error('[AUTOMATCH_MANAGE] 이미지 목록 요소를 찾지 못했습니다');
                return;
            }
            const character = select.value || '';
            const loadToken = ++atManagerLoadToken;
            if (!character) {
                summary.textContent = '캐릭터를 선택하세요.';
                grid.innerHTML = '<div class="at-manager-message">캐릭터를 선택하면 생성된 오토매치 이미지를 확인할 수 있습니다.</div>';
                return;
            }

            summary.textContent = '이미지 목록을 불러오는 중…';
            grid.innerHTML = '<div class="at-manager-message">불러오는 중…</div>';
            try {
                const response = await fetch(`/api/asset_mode/characters/${encodeURIComponent(character)}/automatch_defaults`);
                const data = await response.json();
                if (!response.ok || !data.success) throw new Error(data.error || `HTTP ${response.status}`);
                if (loadToken !== atManagerLoadToken) return;
                atRenderManagedImages(character, data);
            } catch (e) {
                if (loadToken !== atManagerLoadToken) return;
                summary.textContent = '이미지 목록 로드 실패';
                grid.innerHTML = '<div class="at-manager-message">이미지 목록을 불러오지 못했습니다.</div>';
                console.error(`[AUTOMATCH_MANAGE] 이미지 목록 로드 실패: character=${character}`, e);
                showToast('오토매치 이미지 목록 로드 실패: ' + e.message, 'error');
            }
        }

        function atRenderManagedImages(character, data) {
            const grid = document.getElementById('at-manager-grid');
            const summary = document.getElementById('at-manager-summary');
            if (!grid || !summary) {
                console.error('[AUTOMATCH_MANAGE] 이미지 렌더링 요소를 찾지 못했습니다');
                return;
            }
            const images = data.images || [];
            summary.textContent = `${data.expression_count || 0}개 감정 · ${data.image_count || 0}장`;
            grid.innerHTML = '';
            if (!images.length) {
                grid.innerHTML = '<div class="at-manager-message">이 캐릭터로 생성한 오토매치 이미지가 없습니다.</div>';
                return;
            }

            const enc = encodeURIComponent;
            images.forEach(item => {
                const card = document.createElement('article');
                card.className = 'at-manager-card';
                const image = document.createElement('img');
                image.src = `/api/asset_mode/characters/${enc(character)}/outfits/${enc('_automatch_defaults')}/expressions/${enc(item.expression)}/images/${enc(item.filename)}`;
                image.alt = `${item.expression} 오토매치 이미지`;
                image.loading = 'lazy';
                image.addEventListener('click', () => openLightbox(image.src));

                const body = document.createElement('div');
                body.className = 'at-manager-card-body';
                const expression = document.createElement('div');
                expression.className = 'at-manager-card-expression';
                expression.textContent = item.expression;
                const meta = document.createElement('div');
                meta.className = 'at-manager-card-meta';
                const modified = Number(item.modified_at) > 0
                    ? new Date(Number(item.modified_at) * 1000).toLocaleString()
                    : '생성 시각 없음';
                meta.textContent = `${item.filename} · ${modified}`;
                meta.title = meta.textContent;
                const deleteButton = document.createElement('button');
                deleteButton.type = 'button';
                deleteButton.className = 'at-manager-delete';
                deleteButton.textContent = '삭제';
                deleteButton.addEventListener('click', () => atDeleteManagedImage(
                    character,
                    item.expression,
                    item.filename,
                    deleteButton,
                ));
                body.append(expression, meta, deleteButton);
                card.append(image, body);
                grid.appendChild(card);
            });
        }

        async function atDeleteManagedImage(character, expression, filename, button) {
            if (!confirm(`오토매치 이미지를 삭제할까요?\n\n캐릭터: ${character}\n감정: ${expression}\n파일: ${filename}\n\n삭제한 파일은 복구할 수 없습니다.`)) return;
            if (button) {
                button.disabled = true;
                button.textContent = '삭제 중…';
            }
            try {
                const response = await fetch('/api/asset_mode/automatch_defaults/delete', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ character, expression, filename }),
                });
                const result = await response.json();
                if (!response.ok || !result.success) throw new Error(result.error || `HTTP ${response.status}`);
                showToast(`${expression} 오토매치 이미지 삭제 완료`, 'success');
                await atLoadManagedImages();
                const compareCharacter = document.getElementById('at-compare-char')?.value || '';
                if (compareCharacter === character) await atLoadCompareImages({ silent: true });
            } catch (e) {
                if (button) {
                    button.disabled = false;
                    button.textContent = '삭제';
                }
                console.error(
                    `[AUTOMATCH_MANAGE] 이미지 삭제 실패: character=${character}, expression=${expression}, filename=${filename}`,
                    e,
                );
                showToast('오토매치 이미지 삭제 실패: ' + e.message, 'error');
            }
        }

        async function atOnFillCharacterChange() {
            const charName = document.getElementById('at-compare-char')?.value || '';
            atFillSlot.character = charName;
            const charDefaults = assetTags?.characters?.[charName] || {};
            atFillSlot.appearance = charDefaults.appearance || '';
            atFillSlot.outfit = charDefaults.outfit || '';
            atInitFillPanel();
            await atLoadCompareImages({ silent: false });
            _atSaveState();
        }

        function atOnFillFieldChange(element) {
            if (!element?.dataset?.atFillField) {
                console.error('[AUTOMATCH] 생성 설정 필드 정보가 없습니다:', element);
                return;
            }
            atFillSlot[element.dataset.atFillField] = element.value;
            if (element.dataset.atFillField === 'outfit') {
                atLoadCompareImages({ silent: true });
            }
            atUpdateFillAvailability();
            _atSaveState();
        }

        function atOnFillToggle(field, checked) {
            atFillSlot[field] = !!checked;
            if (field === 'ref_enabled') document.getElementById('at-fill-ref-controls').style.display = checked ? 'block' : 'none';
            if (field === 'style_ref_enabled') document.getElementById('at-fill-style-ref-controls').style.display = checked ? 'block' : 'none';
            if (field === 'lora_enabled') document.getElementById('at-fill-lora-controls').style.display = checked ? 'block' : 'none';
            if (field === 'style_lora_enabled') document.getElementById('at-fill-style-lora-controls').style.display = checked ? 'block' : 'none';
            if (field === 'snapref_enabled') document.getElementById('at-fill-snapref-controls').style.display = checked ? 'block' : 'none';
            if (field === 'face_lora_enabled') document.getElementById('at-fill-face-lora-controls').style.display = checked ? 'block' : 'none';
            if (field === 'pose_enabled') document.getElementById('at-fill-pose-controls').style.display = checked ? 'block' : 'none';
            if (field === 'hrf_sdxl' || field === 'hrf_anima') atUpdateFillHiresAvailability();
            atUpdateFillPromptPreview();
            _atSaveState();
        }

        function atOnFillRange(field, value, valueId) {
            atFillSlot[field] = Number.parseFloat(value);
            const valueElement = document.getElementById(valueId);
            if (valueElement) valueElement.textContent = Number.parseFloat(value).toFixed(2);
            atUpdateFillPromptPreview();
            _atSaveState();
        }

        function atOnFillNumber(field, value) {
            const parsed = Number.parseInt(value, 10);
            if (!Number.isFinite(parsed)) {
                console.error(`[AUTOMATCH] 숫자 설정 변환 실패: field=${field}, value=${value}`);
                return;
            }
            atFillSlot[field] = parsed;
            atUpdateFillPromptPreview();
            _atSaveState();
        }

        function atOnFillFloat(field, value) {
            const parsed = Number.parseFloat(value);
            if (!Number.isFinite(parsed)) {
                console.error(`[AUTOMATCH] 소수 설정 변환 실패: field=${field}, value=${value}`);
                return;
            }
            atFillSlot[field] = parsed;
            atUpdateFillPromptPreview();
            _atSaveState();
        }

        function atOnFillOptionalNumber(field, value) {
            const trimmed = String(value || '').trim();
            if (!trimmed) {
                atFillSlot[field] = '';
                atUpdateFillPromptPreview();
                _atSaveState();
                return;
            }
            const parsed = Number.parseInt(trimmed, 10);
            if (!Number.isFinite(parsed)) {
                console.error(`[AUTOMATCH] 선택 숫자 설정 변환 실패: field=${field}, value=${value}`);
                return;
            }
            atFillSlot[field] = parsed;
            atUpdateFillPromptPreview();
            _atSaveState();
        }

        function atOnFillText(field, value) {
            atFillSlot[field] = String(value || '');
            atUpdateFillPromptPreview();
            _atSaveState();
        }

        function atGetFillLoraConfig(type) {
            const configs = {
                lora: { field: 'lora_list', container: 'at-fill-lora-list', overlay: 'at-fill-lora-picker-overlay', title: 'LoRA 선택', showStyleTab: false, placeholder: '📦' },
                style_lora: { field: 'style_lora_list', container: 'at-fill-style-lora-list', overlay: 'at-fill-style-lora-picker-overlay', title: 'Style LoRA 선택', showStyleTab: true, placeholder: '🎨' },
                face_lora: { field: 'face_lora_list', container: 'at-fill-face-lora-list', overlay: 'at-fill-face-lora-picker-overlay', title: 'Face LoRA 선택', showStyleTab: false, placeholder: '👤' },
            };
            return configs[type] || null;
        }

        function atRenderFillLoraList(type) {
            const config = atGetFillLoraConfig(type);
            if (!config) {
                console.error(`[AUTOMATCH] 알 수 없는 LoRA 목록 유형: ${type}`);
                return;
            }
            const container = document.getElementById(config.container);
            if (!container) return;
            const items = Array.isArray(atFillSlot[config.field]) ? atFillSlot[config.field] : [];
            container.innerHTML = '';
            items.forEach((item, index) => {
                const capabilities = getAssetWorkflowCapabilities();
                const base = String(item.BASE || 'anima').trim().toLowerCase();
                const baseLabel = (base === 'sdxl' || base === 'ilxl') ? 'ILXL' : 'ANIMA';
                const baseAvailable = baseLabel === 'ILXL' ? capabilities.ilxl : capabilities.anima;
                const row = document.createElement('div');
                row.className = 'at-fill-lora-item';
                if (!baseAvailable) {
                    row.classList.add('is-unavailable');
                    row.style.opacity = '0.42';
                    row.title = `${baseLabel}을 지원하지 않는 현재 워크플로우에서는 적용되지 않습니다.`;
                }

                const thumbnail = document.createElement('button');
                thumbnail.type = 'button';
                thumbnail.className = 'at-fill-lora-thumb';
                const renderThumbnailPlaceholder = () => {
                    thumbnail.classList.add('is-placeholder');
                    thumbnail.replaceChildren();
                    thumbnail.onclick = null;
                    thumbnail.title = '등록된 썸네일 없음';
                    const placeholder = document.createElement('span');
                    placeholder.className = 'at-fill-lora-placeholder';
                    placeholder.textContent = config.placeholder;
                    thumbnail.appendChild(placeholder);
                };
                const previewUrl = typeof item.preview_url === 'string' ? item.preview_url.trim() : '';
                if (previewUrl) {
                    const image = document.createElement('img');
                    image.src = previewUrl;
                    image.alt = `${item.name || 'LoRA'} 썸네일`;
                    image.loading = 'lazy';
                    image.addEventListener('error', () => {
                        console.warn(`[AUTOMATCH] LoRA 썸네일 로드 실패: type=${type}, name=${item.name || ''}, url=${previewUrl}`);
                        renderThumbnailPlaceholder();
                    }, { once: true });
                    thumbnail.title = '썸네일 확대';
                    thumbnail.setAttribute('aria-label', `${item.name || 'LoRA'} 썸네일 확대`);
                    thumbnail.onclick = () => openLightbox(previewUrl);
                    thumbnail.appendChild(image);
                } else {
                    renderThumbnailPlaceholder();
                }

                const main = document.createElement('div');
                main.className = 'at-fill-lora-main';
                const name = document.createElement('div');
                name.className = 'at-fill-lora-name';
                name.textContent = item.name || item.lora_path || 'LoRA';
                name.title = name.textContent;
                const sourceLabels = { asset: '에셋', bot: '봇', instance: '인스턴스', style: '스타일' };
                const meta = document.createElement('div');
                meta.className = 'at-fill-lora-meta';
                meta.textContent = [sourceLabels[item.source] || 'LoRA', item.character || '', baseLabel].filter(Boolean).join(' · ');
                meta.title = meta.textContent;
                const strengthRow = document.createElement('div');
                strengthRow.className = 'at-fill-lora-strength-row';
                const strength = document.createElement('input');
                strength.type = 'range';
                strength.min = '0';
                strength.max = '1';
                strength.step = '0.01';
                strength.value = Number.isFinite(Number(item.strength)) ? String(item.strength) : '0.5';
                strength.disabled = !baseAvailable;
                strength.title = `강도 ${Number(strength.value).toFixed(2)}`;
                const strengthValue = document.createElement('span');
                strengthValue.className = 'at-fill-lora-strength-value';
                strengthValue.textContent = Number(strength.value).toFixed(2);
                strength.oninput = () => {
                    item.strength = Number.parseFloat(strength.value);
                    strength.title = `강도 ${item.strength.toFixed(2)}`;
                    strengthValue.textContent = item.strength.toFixed(2);
                    atUpdateFillPromptPreview();
                    _atSaveState();
                };
                strengthRow.append(strength, strengthValue);
                main.append(name, meta, strengthRow);
                const remove = document.createElement('button');
                remove.type = 'button';
                remove.className = 'at-fill-lora-remove';
                remove.textContent = '×';
                remove.title = '목록에서 제거';
                remove.onclick = () => {
                    items.splice(index, 1);
                    atRenderFillLoraList(type);
                    atUpdateFillPromptPreview();
                    _atSaveState();
                };
                row.append(thumbnail, main, remove);
                container.appendChild(row);
            });
        }

        async function atOpenFillLoraPicker(type) {
            const config = atGetFillLoraConfig(type);
            if (!config) {
                console.error(`[AUTOMATCH] LoRA 선택기 열기 실패: 알 수 없는 유형 ${type}`);
                return;
            }
            if (!Array.isArray(atFillSlot[config.field])) atFillSlot[config.field] = [];
            _loraPickerCfg = {
                list: atFillSlot[config.field],
                render: () => {
                    atRenderFillLoraList(type);
                    atUpdateFillPromptPreview();
                    _atSaveState();
                },
                overlayId: config.overlay,
                showStyleTab: config.showStyleTab,
            };
            await _openLoraPickerModal(config.title, config.overlay);
        }

        async function atOpenFillPosePicker() {
            try {
                if (!Array.isArray(batchLoadedPoseList) || batchLoadedPoseList.length === 0) {
                    await loadBatchPoseList();
                }
                const overlay = document.createElement('div');
                overlay.id = 'at-fill-pose-picker-overlay';
                overlay.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.6); z-index:270; display:flex; align-items:center; justify-content:center;';
                overlay.innerHTML = `
                    <div style="background:var(--surface); border-radius:12px; padding:20px; max-width:700px; width:90%; max-height:80vh; display:flex; flex-direction:column;">
                        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;"><h3 style="margin:0;">포즈 선택</h3><button type="button" id="at-fill-pose-close" style="background:none;border:none;color:var(--text);font-size:1.2rem;cursor:pointer;">×</button></div>
                        <input type="text" id="at-fill-pose-search" placeholder="포즈 이름 검색..." style="width:100%;padding:8px 10px;border:1px solid var(--border);background:var(--surface2);color:var(--text);border-radius:6px;font-size:0.85rem;margin-bottom:10px;box-sizing:border-box;">
                        <div id="at-fill-pose-grid" class="batch-pose-modal-grid" style="overflow-y:auto;flex:1;min-height:0;"></div>
                    </div>`;
                document.body.appendChild(overlay);
                overlay.onclick = event => { if (event.target === overlay) overlay.remove(); };
                document.getElementById('at-fill-pose-close').onclick = () => overlay.remove();
                const search = document.getElementById('at-fill-pose-search');
                const grid = document.getElementById('at-fill-pose-grid');
                const render = query => {
                    const normalized = String(query || '').toLowerCase().trim();
                    const filtered = batchLoadedPoseList.filter(pose => !normalized || pose.id.toLowerCase().includes(normalized));
                    grid.innerHTML = '';
                    if (!filtered.length) {
                        grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;color:var(--text2);padding:20px;">선택 가능한 포즈가 없습니다</div>';
                        return;
                    }
                    filtered.forEach(pose => {
                        const item = document.createElement('div');
                        item.className = 'batch-pose-modal-item' + (pose.id === atFillSlot.pose_id ? ' selected' : '');
                        const imageUrl = pose.has_image ? `/api/pose_mode/poses/${encodeURIComponent(pose.id)}/image` : '';
                        item.innerHTML = `${imageUrl ? `<img src="${imageUrl}" loading="lazy">` : '<div class="no-img">미리보기 없음</div>'}<div class="pose-name">${escapeHtml(pose.id)}</div>`;
                        item.onclick = () => {
                            atFillSlot.pose_id = pose.id;
                            atUpdateFillPoseDisplay();
                            atUpdateFillPromptPreview();
                            _atSaveState();
                            overlay.remove();
                            showToast('기본 이미지 포즈 선택 완료', 'success');
                        };
                        grid.appendChild(item);
                    });
                };
                search.oninput = () => render(search.value);
                render('');
            } catch (e) {
                console.error('[AUTOMATCH] 포즈 선택기 열기 실패:', e);
                showToast('포즈 목록을 불러오지 못했습니다: ' + e.message, 'error');
            }
        }

        async function atOnUseExistingAssetsChange(checked) {
            atFillSlot.use_existing_assets = !!checked;
            _atSaveState();
            await atLoadCompareImages({ silent: true });
            showToast(checked ? '기존 에셋의 같은 표정을 우선 사용합니다' : '선택 복장과 기본 이미지만 사용합니다', 'info');
        }

        async function atUploadFillReferences(input, type) {
            if (!input?.files?.length) {
                console.warn(`[AUTOMATCH] ${type} 참조 이미지 업로드 건너뜀: 선택 파일 없음`);
                return;
            }
            const formData = new FormData();
            Array.from(input.files).forEach(file => formData.append('image', file));
            try {
                const response = await fetch('/api/asset_mode/upload_reference', { method: 'POST', body: formData });
                const result = await response.json();
                if (!response.ok || !result.success) throw new Error(result.error || `HTTP ${response.status}`);
                const refs = (result.images || []).map((image, index) => ({
                    name: image.name,
                    local_path: image.local_path,
                    orig_filename: image.orig_filename,
                    preview_url: result.asset_info
                        ? `/api/asset_mode/characters/${encodeURIComponent(result.asset_info.character)}/outfits/${encodeURIComponent(result.asset_info.outfit)}/expressions/${encodeURIComponent(result.asset_info.expression)}/images/${encodeURIComponent(image.name)}`
                        : URL.createObjectURL(input.files[index] || new Blob()),
                }));
                const isStyle = type === 'style';
                const prefix = isStyle ? 'style_ref' : type === 'snapref' ? 'snapref' : 'ref';
                atFillSlot[`${prefix}_images`] = refs;
                const preview = document.getElementById(`at-fill-${isStyle ? 'style-ref' : prefix}-preview`);
                preview.innerHTML = refs.map(ref => `<img src="${ref.preview_url}" alt="참조 이미지">`).join('');
                preview.style.display = refs.length ? 'grid' : 'none';
                if (type === 'snapref') {
                    const hashResponse = await fetchJSON('/api/asset_mode/compute_ref_hash', {
                        method: 'POST', headers: {'Content-Type': 'application/json'},
                        body: JSON.stringify({filenames: refs.map(image => image.local_path || image.name)}),
                    });
                    atFillSlot.snapref_dir = hashResponse?.hash ? 'soya_snapref/' + hashResponse.hash : '';
                    atUpdateFillPromptPreview();
                    _atSaveState();
                }
                showToast(`${refs.length}장 참조 이미지 업로드 완료`, 'success');
            } catch (e) {
                console.error(`[AUTOMATCH] ${type} 참조 이미지 업로드 실패:`, e);
                showToast('참조 이미지 업로드 실패: ' + e.message, 'error');
            } finally {
                input.value = '';
            }
        }

        async function atLoadCompareImages(options = {}) {
            const charName = document.getElementById('at-compare-char')?.value || atFillSlot.character || '';
            const statusEl = document.getElementById('at-compare-status');
            if (!charName) {
                atState.compareImages = {};
                atState.compareImageMeta = {};
                atRenderMatches();
                if (!options.silent) showToast('비교 캐릭터를 선택하세요', 'warning');
                return;
            }
            const outfitName = atFillSlot.outfit || '';
            statusEl.style.display = 'inline';
            statusEl.textContent = '이미지 확인 중…';
            try {
                const enc = encodeURIComponent;
                const imgMap = {};
                const includeExisting = atFillSlot.use_existing_assets !== false ? '1' : '0';
                const url = `/api/asset_mode/characters/${enc(charName)}/automatch_compare?outfit=${enc(outfitName)}&include_existing=${includeExisting}`;
                const response = await fetch(url);
                const data = await response.json();
                if (!response.ok || !data.success) throw new Error(data.error || `HTTP ${response.status}`);
                const metaMap = data.images || {};
                Object.entries(metaMap).forEach(([expression, info]) => {
                    imgMap[expression] = `/api/asset_mode/characters/${enc(charName)}/outfits/${enc(info.outfit)}/expressions/${enc(info.expression)}/images/${enc(info.filename)}`;
                });
                atState.compareImages = imgMap;
                atState.compareImageMeta = metaMap;
                atRenderMatches();
                const count = Object.keys(imgMap).length;
                if (!options.silent && count > 0) showToast(`${charName} 비교 이미지 ${count}개 적용`, 'success');
            } catch (e) {
                atState.compareImages = {};
                atState.compareImageMeta = {};
                console.error('[AUTOMATCH] 비교 이미지 로드 오류:', e);
                showToast('비교 이미지 로드 실패: ' + e.message, 'error');
            } finally {
                statusEl.style.display = 'none';
                atUpdateFillAvailability();
            }
        }

        function atFillMatchTypeLabel(matchType) {
            return matchType === 'tag' ? '태그 매칭' : '임베딩 매칭';
        }

        function atCollectEmptyTopMatches(matchType = 'embedding') {
            if (!Object.prototype.hasOwnProperty.call(atFillRuns, matchType)) {
                console.error('[AUTOMATCH] 빈 슬롯 수집 실패: 알 수 없는 매칭 유형', matchType);
                return [];
            }
            const topNInput = document.getElementById('at-fill-top-n');
            const topN = Math.max(1, Math.min(AT_MATCH_RESULT_LIMIT, Number.parseInt(topNInput?.value || '3', 10) || 3));
            if (topNInput) topNInput.value = topN;
            const groups = matchType === 'tag' ? atState.imageMatches : atState.embeddingMatches;
            const expressions = [];
            groups.forEach(group => {
                const ranked = Array.isArray(group?.matches) ? group.matches : [];
                ranked.slice(0, topN).forEach(match => {
                    if (
                        match?.name
                        && !atState.compareImages[match.name]
                        && !atFillReservedExpressions.has(match.name)
                        && !expressions.includes(match.name)
                    ) {
                        expressions.push(match.name);
                    }
                });
            });
            return expressions;
        }

        function atToggleFillPromptPreview(labelElement) {
            const preview = labelElement?.nextElementSibling;
            if (!preview) {
                console.error('[AUTOMATCH] 프롬프트 미리보기 토글 실패: 대상 요소 없음');
                return;
            }
            preview.classList.toggle('collapsed');
            const label = labelElement.dataset.label || '프롬프트';
            labelElement.textContent = `${label} ${preview.classList.contains('collapsed') ? '▼' : '▲'}`;
        }

        function atUpdateFillPromptPreview() {
            const positive = document.getElementById('at-fill-positive-preview');
            const negative = document.getElementById('at-fill-negative-preview');
            const targetLabel = document.getElementById('at-fill-preview-target');
            if (!positive || !negative || !targetLabel) return;
            if (!assetTags) {
                targetLabel.textContent = '태그 데이터 로딩 중';
                positive.textContent = '태그 데이터를 불러온 뒤 표시됩니다.';
                negative.textContent = '태그 데이터를 불러온 뒤 표시됩니다.';
                return;
            }

            const preferredTargets = atCollectEmptyTopMatches(atFillPreviewMatchType);
            const fallbackMatchType = atFillPreviewMatchType === 'embedding' ? 'tag' : 'embedding';
            const targets = preferredTargets.length ? preferredTargets : atCollectEmptyTopMatches(fallbackMatchType);
            const previewMatchType = preferredTargets.length ? atFillPreviewMatchType : fallbackMatchType;
            if (!targets.length) {
                targetLabel.textContent = '빈 표정 없음';
                positive.textContent = '현재 TOP 범위에 미리볼 빈 표정이 없습니다.';
                negative.textContent = '현재 TOP 범위에 미리볼 빈 표정이 없습니다.';
                return;
            }

            const previewSlot = {
                ...atFillSlot,
                expression: targets[0],
                asset_workflow_type: normalizeAssetWorkflowType(currentConfig?.asset_workflow_type),
            };
            targetLabel.textContent = `${atFillMatchTypeLabel(previewMatchType)} 기준 · ${targets[0]} (${targets.length}개 대상)`;
            renderAssetPromptPreview(previewSlot, positive, negative);
        }

        function atUpdateFillAvailability() {
            const targetsByType = {
                embedding: atCollectEmptyTopMatches('embedding'),
                tag: atCollectEmptyTopMatches('tag'),
            };
            const expression = document.getElementById('at-fill-expression');
            const ready = !!atFillSlot.character && !!atFillSlot.appearance && !!atFillSlot.outfit;
            if (expression) {
                expression.textContent = targetsByType.embedding.length || targetsByType.tag.length
                    ? `임베딩 ${targetsByType.embedding.length}개 · 태그 ${targetsByType.tag.length}개 자동 지정`
                    : '매칭 결과에서 자동 지정';
            }
            [
                ['embedding', 'at-fill-start-embedding', '임베딩'],
                ['tag', 'at-fill-start-tag', '태그'],
            ].forEach(([matchType, buttonId, shortLabel]) => {
                const button = document.getElementById(buttonId);
                if (!button) return;
                const run = atFillRuns[matchType];
                const targets = targetsByType[matchType];
                const done = run.completed + run.failed + run.cancelled;
                button.disabled = run.running || !ready || targets.length === 0;
                button.textContent = run.running
                    ? `${shortLabel} 생성 중 · ${done}/${run.total}`
                    : (targets.length ? `${shortLabel} ${targets.length}개 생성` : `${shortLabel} 빈 슬롯 없음`);
            });
            atUpdateFillPromptPreview();
        }

        function atSetFillProgress(matchType, message) {
            const run = atFillRuns[matchType];
            if (!run) {
                console.error('[AUTOMATCH] 생성 진행률 표시 실패: 알 수 없는 매칭 유형', matchType);
                return;
            }
            const status = document.getElementById('at-fill-status');
            const progress = document.getElementById('at-fill-progress');
            const inner = document.getElementById('at-fill-progress-inner');
            const done = run.completed + run.failed + run.cancelled;
            if (status) {
                status.style.display = 'block';
                status.textContent = `${atFillMatchTypeLabel(matchType)} · ${message}`;
            }
            if (progress) progress.style.display = 'block';
            if (inner) inner.style.width = `${run.total ? (done / run.total) * 100 : 0}%`;
            atUpdateFillAvailability();
        }

        function atFinalizeFillRun(matchType) {
            const run = atFillRuns[matchType];
            if (!run) {
                console.error('[AUTOMATCH] 생성 종료 처리 실패: 알 수 없는 매칭 유형', matchType);
                return false;
            }
            if (!run.running || run.queueing || run.queueItems.size > 0) return false;
            run.running = false;
            const label = run.cancelled > 0 ? '생성 종료' : '생성 완료';
            atSetFillProgress(matchType, `${label} · 성공 ${run.completed}, 실패 ${run.failed}, 취소 ${run.cancelled}`);
            const toastType = run.cancelled > 0 ? 'warning' : (run.completed > 0 ? 'success' : 'error');
            showToast(`오토매치 ${atFillMatchTypeLabel(matchType)} 기본 이미지 · 성공 ${run.completed}, 실패 ${run.failed}, 취소 ${run.cancelled}`, toastType);
            return true;
        }

        function atSnapshotFillSlot() {
            return {
                ...atFillSlot,
                ref_images: (atFillSlot.ref_images || []).map(image => ({ ...image })),
                style_ref_images: (atFillSlot.style_ref_images || []).map(image => ({ ...image })),
                snapref_images: (atFillSlot.snapref_images || []).slice(0, 1).map(image => ({ ...image })),
                lora_list: (atFillSlot.lora_list || []).map(item => ({ ...item })),
                style_lora_list: (atFillSlot.style_lora_list || []).map(item => ({ ...item })),
                face_lora_list: (atFillSlot.face_lora_list || []).map(item => ({ ...item })),
            };
        }

        async function atFillEmptySlots(matchType) {
            const run = atFillRuns[matchType];
            if (!run) {
                console.error('[AUTOMATCH] 기본 이미지 생성 시작 실패: 알 수 없는 매칭 유형', matchType);
                showToast('알 수 없는 오토매치 생성 유형입니다', 'error');
                return;
            }
            if (run.running) {
                console.warn(`[AUTOMATCH] ${matchType} 기본 이미지 생성 건너뜀: 이미 실행 중`);
                return;
            }
            atFillPreviewMatchType = matchType;
            const targets = atCollectEmptyTopMatches(matchType);
            if (!atFillSlot.character || !atFillSlot.appearance || !atFillSlot.outfit) {
                showToast('캐릭터, 외모, 복장을 모두 선택하세요', 'warning');
                return;
            }
            if (!targets.length) {
                showToast(`선택한 TOP 범위에 ${atFillMatchTypeLabel(matchType)} 빈 슬롯이 없습니다`, 'info');
                return;
            }

            const fillSlotSnapshot = atSnapshotFillSlot();
            run.running = true;
            run.queueing = true;
            run.pendingExpressions = new Set();
            run.queueItems = new Map();
            run.completed = 0;
            run.failed = 0;
            run.cancelled = 0;
            run.total = targets.length;
            targets.forEach(expression => atFillReservedExpressions.add(expression));
            atSetFillProgress(matchType, `${targets.length}개 기본 이미지를 큐에 추가하는 중…`);

            for (const expression of targets) {
                const slot = {
                    ...fillSlotSnapshot,
                    expression,
                    asset_workflow_type: normalizeAssetWorkflowType(currentConfig?.asset_workflow_type),
                };
                try {
                    const promptData = await buildAssetPromptData(slot);
                    if (!promptData) throw new Error('프롬프트 생성 결과가 비어있습니다');
                    const payload = {
                        character: slot.character,
                        appearance: slot.appearance,
                        outfit: slot.outfit,
                        expression,
                        storage_group: 'automatch_defaults',
                        asset_workflow_type: normalizeAssetWorkflowType(currentConfig?.asset_workflow_type),
                        face_id_enabled: slot.ref_enabled,
                        face_id_strength: slot.ref_strength,
                        reference_images: (slot.ref_images || []).map(image => ({ filename: image.name, local_path: image.local_path })),
                        style_ref_enabled: slot.style_ref_enabled,
                        style_ref_strength: slot.style_ref_strength,
                        style_ref_images: (slot.style_ref_images || []).map(image => ({ filename: image.name, local_path: image.local_path })),
                        snapref_enabled: getAssetWorkflowCapabilities(slot.asset_workflow_type).anima && !!slot.snapref_enabled,
                        snapref_images: slot.snapref_enabled ? (slot.snapref_images || []).slice(0, 1).map(image => ({ filename: image.name, local_path: image.local_path })) : [],
                        snapref_dir: slot.snapref_dir || '',
                        snapref_strength: slot.snapref_strength ?? 0,
                        snapref_mode: slot.snapref_mode || 'char',
                        snapref_megapixels: slot.snapref_megapixels ?? 1,
                        positive_prompt: promptData.positive,
                        negative_prompt: promptData.negative,
                    };
                    const response = await fetchJSON('/api/queue/add', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            type: 'asset_generation',
                            label: `오토매치 ${atFillMatchTypeLabel(matchType)} 기본 이미지 ${slot.character}/${expression}`,
                            params: { body: payload },
                        }),
                    });
                    if (!response?.success) throw new Error(response?.error || '큐 추가 실패');
                    if (!response.item_id) throw new Error('큐 작업 ID가 비어있습니다');
                    run.pendingExpressions.add(expression);
                    run.queueItems.set(response.item_id, expression);
                } catch (e) {
                    run.failed++;
                    atFillReservedExpressions.delete(expression);
                    console.error(`[AUTOMATCH] ${matchType} 기본 이미지 큐 추가 실패: expression=${expression}`, e);
                }
            }
            run.queueing = false;

            if (!run.pendingExpressions.size) {
                atSetFillProgress(matchType, `큐 추가 실패 · ${run.failed}건`);
                atFinalizeFillRun(matchType);
                return;
            }
            atSetFillProgress(matchType, `큐 대기 중 · 완료 0 / ${run.total}, 큐 추가 실패 ${run.failed}`);
            showToast(`${atFillMatchTypeLabel(matchType)} ${run.pendingExpressions.size}개 기본 이미지 생성 작업을 큐에 추가했습니다`, 'success');
        }

        async function atHandleDefaultGenerationEvent(data) {
            const result = data?.result || data || {};
            if (result.storage_group !== 'automatch_defaults') return;
            const expression = result.expression || '';
            const itemId = data?.item_id || '';
            let run = itemId
                ? Object.values(atFillRuns).find(candidate => candidate.queueItems.has(itemId))
                : null;
            if (!run && expression) {
                run = Object.values(atFillRuns).find(candidate => candidate.pendingExpressions.has(expression)) || null;
            }
            if (!run || !expression || !run.pendingExpressions.has(expression)) return;

            run.pendingExpressions.delete(expression);
            if (itemId) {
                run.queueItems.delete(itemId);
            } else {
                const fallbackEntry = Array.from(run.queueItems.entries()).find(([, value]) => value === expression);
                if (fallbackEntry) run.queueItems.delete(fallbackEntry[0]);
            }
            const succeeded = result.success !== false && data?.status !== 'error';
            if (succeeded) {
                run.completed++;
                try {
                    await atLoadCompareImages({ silent: true });
                } finally {
                    atFillReservedExpressions.delete(expression);
                }
            } else {
                run.failed++;
                atFillReservedExpressions.delete(expression);
            }
            const done = run.completed + run.failed + run.cancelled;
            atSetFillProgress(run.matchType, `생성 진행 · 완료 ${run.completed}, 실패 ${run.failed}, 취소 ${run.cancelled} (${done}/${run.total})`);
            atFinalizeFillRun(run.matchType);
        }

        function atReconcileDefaultGenerationQueue(items) {
            if (!Array.isArray(items)) {
                console.error('[AUTOMATCH] 큐 상태 보정 실패: 큐 항목이 배열이 아님', items);
                return;
            }
            const itemMap = new Map(items.filter(Boolean).map(item => [item.id, item]));
            const completedExpressions = [];
            Object.values(atFillRuns).forEach(run => {
                if (!run.running || run.queueItems.size === 0) return;
                let changed = false;
                for (const [itemId, expression] of Array.from(run.queueItems.entries())) {
                    const item = itemMap.get(itemId);
                    if (!item || !['completed', 'failed', 'cancelled'].includes(item.status)) continue;
                    run.queueItems.delete(itemId);
                    run.pendingExpressions.delete(expression);
                    if (item.status === 'cancelled') {
                        run.cancelled++;
                        atFillReservedExpressions.delete(expression);
                    } else if (item.status === 'failed' || item.result?.success === false) {
                        run.failed++;
                        atFillReservedExpressions.delete(expression);
                    } else {
                        run.completed++;
                        completedExpressions.push(expression);
                    }
                    changed = true;
                }
                if (!changed) return;
                const done = run.completed + run.failed + run.cancelled;
                atSetFillProgress(run.matchType, `생성 진행 · 완료 ${run.completed}, 실패 ${run.failed}, 취소 ${run.cancelled} (${done}/${run.total})`);
                atFinalizeFillRun(run.matchType);
            });
            if (completedExpressions.length) {
                atLoadCompareImages({ silent: true }).catch(e => {
                    console.error('[AUTOMATCH] 큐 완료 보정 후 비교 이미지 갱신 실패:', e);
                }).finally(() => {
                    completedExpressions.forEach(expression => atFillReservedExpressions.delete(expression));
                    atUpdateFillAvailability();
                });
            }
        }

        function atClearAll() {
            atState.images.forEach(item => { if (item.url) URL.revokeObjectURL(item.url); });
            atState.images = [];
            atState.matches = [];
            atState.imageMatches = [];
            atState.embeddingMatches = [];
            atResetMatchPages();
            atState.compareImages = {};
            atState.compareImageMeta = {};
            atState.chains = [];
            sessionStorage.removeItem('atState');
            atRenderImages();
            atEmotionUpdatePreview();
            const canvas = document.getElementById('at-canvas');
            if (canvas) canvas.innerHTML = '<div class="at-empty-state">이미지를 분석하면<br>매칭 결과가 여기에 표시됩니다</div>';
            atUpdateFillAvailability();
            document.getElementById('at-analyze-btn').disabled = true;
            document.getElementById('at-clear-btn').disabled = true;
            document.getElementById('at-progress-bar').style.display = 'none';
            atSwitchView('upload');
        }

        function atRenderSourceCards() {
            const canvas = document.getElementById('at-canvas');
            if (!canvas) return;
            if (atState.imageMatches.length > 0) {
                atRenderMatches();
                return;
            }
            const done = atState.images.filter(i => i.status === 'done');
            if (done.length === 0) {
                canvas.innerHTML = '<div class="at-empty-state">이미지를 분석하면<br>매칭 결과가 여기에 표시됩니다</div>';
                return;
            }
            canvas.innerHTML = '';
            done.forEach(item => {
                const card = document.createElement('div');
                card.className = 'at-card at-card-source';
                const tags = item.tags ? item.tags : [];
                card.innerHTML = `
                    <div class="at-card-img">
                        <img src="${item.url}" onclick="openLightbox(this.src)">
                    </div>
                    <div class="at-card-body">
                        <div class="at-card-name">${escapeHtml(item.file.name || '이미지')}</div>
                        <div class="at-card-tags">${tags.map(t => `<span class="at-tag-chip">${escapeHtml(t)}</span>`).join('')}</div>
                    </div>
                `;
                canvas.appendChild(card);
            });
        }

        function atRenderImages() {
            const container = document.getElementById('at-images');
            container.innerHTML = '';
            if (atState.images.length === 0) {
                container.innerHTML = `
                    <div style="text-align:center; padding:48px 20px; border:2px dashed var(--border); border-radius:10px; color:var(--text2); background:var(--surface2);">
                        <div style="font-size:2.4rem; margin-bottom:10px; opacity:0.6;">🖼️</div>
                        <div style="font-size:0.95rem; margin-bottom:6px; color:var(--text);">이미지가 없습니다.</div>
                        <div style="font-size:0.82rem;">위 <b style="color:var(--accent);">📷 이미지 업로드</b> 버튼을 눌러 이미지 업로드를 진행해주세요.</div>
                    </div>`;
                return;
            }
            atState.images.forEach((item, i) => {
                const card = document.createElement('div');
                card.className = 'at-image-card';
                let badge = '';
                if (item.status === 'done') badge = '<div class="at-analysis-badge">✅ 분석완료</div>';
                else if (item.status === 'analyzing') badge = '<div class="at-analysis-badge" style="color:#ffd700;">⏳ 분석중</div>';
                else if (item.status === 'pending') badge = '<div class="at-analysis-badge" style="color:#888;">⏸ 대기중</div>';
                else if (item.status === 'error') badge = '<div class="at-analysis-badge" style="color:#f44;">❌ 오류</div>';
                const emotion = atExtractEmotion(item.file ? item.file.name : '');
                const emotionLabel = emotion
                    ? `<div style="position:absolute; left:4px; bottom:4px; right:4px; background:rgba(0,0,0,0.65); color:#fff; font-size:0.72rem; padding:2px 6px; border-radius:4px; line-height:1.2;">감정: ${escapeHtml(emotion)}</div>`
                    : '';
                card.style.position = 'relative';
                card.innerHTML = `<img src="${item.url}"><button class="at-remove-btn" onclick="atRemoveImage(${i})">✕</button>${badge}${emotionLabel}`;
                container.appendChild(card);
            });
        }

        // ── 감정 추출(업로드 태그 정제) 클라이언트 구현 ──────────────
        // 서버 clean_name_by_steps/_parse_take/_apply_take 의 JS 미러.
        // 이미지 파일명에서 확장자를 뺀 뒤 활성 태그 프로필 규칙을 적용해 감정만 추출한다.
        function atParseTake(takeValue) {
            if (typeof takeValue === 'number') return takeValue;
            if (typeof takeValue !== 'string') return takeValue;
            if (takeValue.endsWith(':')) {
                const n = parseInt(takeValue.slice(0, -1), 10);
                return isNaN(n) ? takeValue : [n, null];
            }
            if (takeValue.startsWith(':')) {
                const n = parseInt(takeValue.slice(1), 10);
                return isNaN(n) ? takeValue : [null, n];
            }
            if (takeValue.includes(':')) {
                const p = takeValue.split(':', 2);
                const a = p[0] ? parseInt(p[0], 10) : NaN;
                const b = p[1] ? parseInt(p[1], 10) : NaN;
                return [isNaN(a) ? null : a, isNaN(b) ? null : b];
            }
            return takeValue;
        }

        function atApplyTake(parts, takeValue, joinSep) {
            if (typeof takeValue === 'number') {
                // JS는 parts[-1] 처럼 음수 인덱스를 지원하지 않으므로 변환.
                const n = takeValue;
                if (-parts.length <= n && n < parts.length) {
                    return parts[n < 0 ? parts.length + n : n];
                }
                return n < 0 ? parts[parts.length - 1] : parts[0];
            }
            if (Array.isArray(takeValue)) {
                let start = takeValue[0], end = takeValue[1];
                if (start != null && start < 0) start = parts.length + start;
                if (end != null && end < 0) end = parts.length + end;
                // JS slice는 end=null을 0으로 취급하므로 null은 undefined(끝까지)로 변환.
                // 파이썬 parts[1:None] == parts[1:] 동작과 일치시킴.
                const s = (start == null) ? undefined : start;
                const e = (end == null) ? undefined : end;
                return parts.slice(s, e).join(joinSep);
            }
            return parts[parts.length - 1];
        }

        function atCleanNameBySteps(name, steps) {
            if (!name) return '';
            let result = name;
            for (const step of (steps || [])) {
                const action = step.action || '';
                try {
                    if (action === 'split_by') {
                        const sep = step.separator || '_';
                        const parts = result.split(sep);
                        if (!parts.length) continue;
                        result = atApplyTake(parts, atParseTake(step.take), sep);
                    } else if (action === 'strip_suffix') {
                        const p = step.pattern || '';
                        if (p) result = result.replace(new RegExp(p, 'g'), '');
                    } else if (action === 'strip_prefix') {
                        const p = step.pattern || '';
                        if (p) result = result.replace(new RegExp('^' + p, 'g'), '');
                    } else if (action === 'replace') {
                        const from = step.from || '';
                        const to = step.to != null ? step.to : ' ';
                        if (from) result = result.split(from).join(to);
                    } else if (action === 'strip') {
                        result = result.trim();
                    } else if (action === 'lower') {
                        result = result.toLowerCase();
                    }
                } catch (e) {
                    console.error('[atCleanNameBySteps] 단계 적용 오류:', step, e);
                }
            }
            return (result || '').trim();
        }

        function atExtractEmotion(filename) {
            if (!filename) return '';
            const dot = filename.lastIndexOf('.');
            const baseName = dot > 0 ? filename.substring(0, dot) : filename;
            const cleaned = atCleanNameBySteps(baseName, atEmbedActiveSteps.tag);
            // 규칙 결과가 빈 값이면 baseName으로 폴백 → "(없음)" 방지
            return cleaned || baseName;
        }

        // ── 이미지 업로드 & 감정 추출 모달 (batch-add 스타일) ─────────
        const AT_EMOTION_DEFAULT_RULES = [{ action: 'split_by', separator: '_', take: -1 }];

        function atOpenUploadModal() {
            const modal = document.getElementById('at-upload-modal');
            if (!modal) return;
            modal.style.display = 'flex';
            // 태그 정제 규칙(활성 태그 프로필 steps) 로드 후 규칙 편집기/미리보기 렌더
            (async () => {
                if (!atEmbedProfiles || Object.keys(atEmbedProfiles).length === 0) {
                    await atLoadProfiles();
                }
                if (!atEmbedActiveSteps.tag || atEmbedActiveSteps.tag.length === 0) {
                    atEmbedActiveSteps.tag = JSON.parse(JSON.stringify(AT_EMOTION_DEFAULT_RULES));
                }
                atEmotionRenderRules();
                atEmotionUpdatePreview();
            })();
        }

        function atCloseUploadModal() {
            const modal = document.getElementById('at-upload-modal');
            if (modal) modal.style.display = 'none';
        }

        function atEmotionRenderRules() {
            const container = document.getElementById('at-emotion-rules');
            if (!container) return;
            container.innerHTML = '';
            const rules = atEmbedActiveSteps.tag || [];
            const maxRows = Math.max(rules.length, 1);
            for (let i = 0; i < maxRows; i++) {
                const step = rules[i] || {};
                const row = document.createElement('div');
                row.style.cssText = 'display:flex; gap:4px; margin-bottom:4px; align-items:center; flex-wrap:wrap;';
                let paramsHtml = '';
                if (step.action === 'split_by') {
                    paramsHtml = `<input type="text" value="${escHtml(step.separator || '_')}" placeholder="구분자" oninput="atEmbedActiveSteps.tag[${i}].separator=this.value; atEmotionUpdatePreview(); atRenderImages();" style="width:50px; padding:2px 4px; font-size:0.75rem; border:1px solid var(--border); border-radius:3px; background:var(--surface2); color:var(--text);">
                        <input type="text" value="${escHtml(String(step.take ?? -1))}" placeholder="인덱스(-1/0/1:)" oninput="atEmbedActiveSteps.tag[${i}].take=this.value.trim().match(/^-?\d+$/) ? parseInt(this.value.trim()) : this.value.trim(); atEmotionUpdatePreview(); atRenderImages();" style="width:60px; padding:2px 4px; font-size:0.75rem; border:1px solid var(--border); border-radius:3px; background:var(--surface2); color:var(--text);">`;
                } else if (step.action === 'strip_suffix' || step.action === 'strip_prefix') {
                    paramsHtml = `<input type="text" value="${escHtml(step.pattern || '')}" placeholder="패턴(정규식)" oninput="atEmbedActiveSteps.tag[${i}].pattern=this.value; atEmotionUpdatePreview(); atRenderImages();" style="width:140px; padding:2px 4px; font-size:0.75rem; border:1px solid var(--border); border-radius:3px; background:var(--surface2); color:var(--text);">`;
                } else if (step.action === 'replace') {
                    paramsHtml = `<input type="text" value="${escHtml(step.from || '')}" placeholder="찾을값" oninput="atEmbedActiveSteps.tag[${i}].from=this.value; atEmotionUpdatePreview(); atRenderImages();" style="width:70px; padding:2px 4px; font-size:0.75rem; border:1px solid var(--border); border-radius:3px; background:var(--surface2); color:var(--text);">
                        <input type="text" value="${escHtml(step.to != null ? step.to : ' ')}" placeholder="바꿀값" oninput="atEmbedActiveSteps.tag[${i}].to=this.value; atEmotionUpdatePreview(); atRenderImages();" style="width:70px; padding:2px 4px; font-size:0.75rem; border:1px solid var(--border); border-radius:3px; background:var(--surface2); color:var(--text);">`;
                }
                row.innerHTML = `
                    <select onchange="atEmbedActiveSteps.tag[${i}]={action:this.value}; atEmotionRenderRules(); atEmotionUpdatePreview(); atRenderImages();" style="padding:2px 4px; font-size:0.75rem; border:1px solid var(--border); border-radius:3px; background:var(--surface2); color:var(--text);">
                        <option value="split_by" ${step.action==='split_by'?'selected':''}>구분자로 분리</option>
                        <option value="strip_suffix" ${step.action==='strip_suffix'?'selected':''}>접미사 제거</option>
                        <option value="strip_prefix" ${step.action==='strip_prefix'?'selected':''}>접두사 제거</option>
                        <option value="replace" ${step.action==='replace'?'selected':''}>치환</option>
                        <option value="strip" ${step.action==='strip'?'selected':''}>공백 제거</option>
                        <option value="lower" ${step.action==='lower'?'selected':''}>소문자화</option>
                    </select>
                    ${paramsHtml}
                    <button onclick="atEmotionRemoveRule(${i})" style="background:var(--error); color:#fff; border:none; padding:2px 6px; border-radius:3px; cursor:pointer; font-size:0.7rem;">✕</button>
                `;
                container.appendChild(row);
            }
        }

        function atEmotionAddRule() {
            if (!atEmbedActiveSteps.tag) atEmbedActiveSteps.tag = [];
            atEmbedActiveSteps.tag.push({ action: 'replace', from: '_', to: ' ' });
            atEmotionRenderRules();
            atEmotionUpdatePreview();
            atRenderImages();
        }

        function atEmotionRemoveRule(i) {
            if (!atEmbedActiveSteps.tag) return;
            atEmbedActiveSteps.tag.splice(i, 1);
            atEmotionRenderRules();
            atEmotionUpdatePreview();
            atRenderImages();
        }

        function atEmotionUpdatePreview() {
            const preview = document.getElementById('at-emotion-preview');
            if (!preview) return;
            if (!atState.images.length) {
                preview.innerHTML = '<span style="color:var(--text2);">파일을 선택하면 추출된 감정이 여기에 표시됩니다.</span>';
                return;
            }
            preview.innerHTML = atState.images.map(item => {
                const fname = item.file ? item.file.name : '';
                const emotion = atExtractEmotion(fname);
                return `<div style="display:flex; justify-content:space-between; gap:8px; padding:2px 0;">
                    <span style="color:var(--text2); word-break:break-all;">${escapeHtml(fname)}</span>
                    <span style="color:var(--accent); font-weight:600; word-break:break-all; white-space:nowrap;">→ ${escapeHtml(emotion)}</span>
                </div>`;
            }).join('');
        }

        async function atEmotionApply() {
            const steps = JSON.parse(JSON.stringify(atEmbedActiveSteps.tag || []));
            try {
                const resp = await fetch('/api/asset_tool/embedding_tag_rule_apply', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ steps })
                });
                const result = await resp.json();
                if (result.success) {
                    showToast('감정 추출 규칙이 적용되었습니다', 'success');
                    await atLoadProfiles();
                } else {
                    showToast('적용 실패: ' + (result.error || ''), 'error');
                }
            } catch (e) {
                showToast('적용 오류: ' + e.message, 'error');
            }
        }


        // 서버에서 저장된 프로필 매핑 불러오기
        async function atLoadProfileMapFromServer() {
            try {
                const resp = await fetch('/api/asset_tool/embedding_profile_map');
                const result = await resp.json();
                if (result.success && result.preset_profile_map) {
                    const map = result.preset_profile_map || {};
                    if (Object.keys(map).length > 0) {
                        atPresetProfileMap = JSON.parse(JSON.stringify(map));
                        console.log('[atLoadProfileMapFromServer] 서버 매핑 로드:', Object.keys(map).length, '개');
                        return true;
                    }
                }
                // 매핑은 없어도 정제 규칙(clean_profiles)이 존재하면 임베딩 매칭 가능
                if (result.success && result.has_clean_profiles) {
                    console.log('[atLoadProfileMapFromServer] 매핑 없음, 정제 규칙 존재 → 매칭 진행 허용');
                    return true;
                }
                console.log('[atLoadProfileMapFromServer] 서버에 저장된 매핑/정제규칙 없음');
                return false;
            } catch (e) {
                console.error('[atLoadProfileMapFromServer] 오류:', e);
                return false;
            }
        }

        // 준비 상태 체크리스트 업데이트
        async function atCheckReadyStates() {
            const embedIcon = document.getElementById('at-check-embedding-icon');
            const embedText = document.getElementById('at-check-embedding-text');
            const embedBox = document.getElementById('at-check-embedding');
            if (!embedIcon) return;

            // 임베딩 캐시 상태 확인
            let embedReady = false;
            try {
                const resp = await fetch('/api/asset_tool/embedding_cache_status');
                const result = await resp.json();
                console.log('[atCheckReadyStates] 임베딩 캐시 응답:', result);
                if (result.success && result.valid && (result.cached_embeddings || 0) > 0) {
                    embedReady = true;
                }
            } catch (e) {
                console.error('[atCheckReadyStates] 임베딩 캐시 조회 오류:', e);
            }
            if (embedReady) {
                embedIcon.textContent = '✅';
                embedText.textContent = '임베딩 캐시 준비됨';
                embedBox.style.borderColor = 'var(--success, #4caf50)';
                embedBox.style.color = 'var(--success, #4caf50)';
            } else {
                embedIcon.textContent = '❌';
                embedText.textContent = '임베딩 캐시 없음';
                embedBox.style.borderColor = 'var(--error, #f44336)';
                embedBox.style.color = 'var(--error, #f44336)';
            }
        }

        // 오토매치 상태 플래그
        let atTagPreviewDone = false;   // 업로드 태그 미리보기 완료 여부

        // 오토매치 분석 중단 컨트롤러
        let atAbortController = null;

        async function atAnalyzeAll() {
            const category = document.getElementById('at-category').value;
            const doAnalyze = document.getElementById('at-do-analyze').checked;
            const doMatch = document.getElementById('at-do-match').checked;
            if (!doAnalyze && !doMatch) { showToast('태그 분석 또는 임베딩 매칭 중 하나 이상 선택하세요', 'error'); return; }
            if (doMatch) {
                if (!atPresetProfileMap || Object.keys(atPresetProfileMap).length === 0) {
                    const loaded = await atLoadProfileMapFromServer();
                    if (!loaded) {
                        showToast('정제 결과가 없습니다. 먼저 임베딩 설정에서 미리보기를 확인하세요.', 'error');
                        return;
                    }
                }
            }

            // 태그 분석 모드일 때, 기존 done 상태도 pending으로 초기화하여 재분행 상황을 보여줌
            if (doAnalyze) {
                let resetCount = 0;
                atState.images.forEach(i => {
                    if (i.status === 'done') {
                        i.status = 'pending';
                        i.tags = [];
                        resetCount++;
                    }
                });
                if (resetCount > 0) {
                    console.log('[atAnalyzeAll] 기존 분석완료 이미지', resetCount, '개를 대기 상태로 초기화');
                }
                atRenderImages();
            }
            const pending = atState.images.filter(i => i.status === 'pending' || i.status === 'error');

            document.getElementById('at-analyze-btn').disabled = true;
            document.getElementById('at-stop-btn').style.display = '';
            document.getElementById('at-progress-bar').style.display = 'block';
            document.getElementById('at-progress-inner').style.width = '0%';

            // 전체 단계: 태그 분석(이미지별) + 배치 매칭(이미지별)
            atState.queueItemIds = [];
            atState.analyzeCompleted = 0;

            // 1. 태그 분석 (큐 사용, 이미지당 개별 큐 아이템)
            if (doAnalyze && pending.length > 0) {
                atAbortController = new AbortController();
                atState.analyzeTotal = pending.length;

                for (const item of pending) {
                    item.status = 'analyzing';
                }
                atRenderImages();

                let addedCount = 0;
                for (const item of pending) {
                    try {
                        const b64 = await fileToBase64(item.file);
                        const resp = await fetchJSON('/api/queue/add', {
                            method: 'POST',
                            headers: {'Content-Type': 'application/json'},
                            body: JSON.stringify({
                                type: 'tag_analysis',
                                label: `태그 분석 (${item.file.name})`,
                                params: { source: 'auto_match', images: [{data: b64, filename: item.file.name}], category: category }
                            })
                        });
                        if (resp.item_id) {
                            atState.queueItemIds.push(resp.item_id);
                            addedCount++;
                        }
                    } catch (e) {
                        console.error('[AT] 큐 추가 오류:', item.file.name, e);
                        item.error = '큐 추가 실패';
                        item.status = 'error';
                    }
                }

                if (addedCount > 0) {
                    showToast(`큐에 ${addedCount}장 추가됨`, 'info');
                } else {
                    showToast('큐 추가 실패', 'error');
                    document.getElementById('at-analyze-btn').disabled = false;
                    document.getElementById('at-stop-btn').style.display = 'none';
                    document.getElementById('at-progress-bar').style.display = 'none';
                    return;
                }
                return; // 큐 완료 이벤트로 후속 처리
            }

            // 2. 배치 매칭 (큐 사용)
            if (doMatch) {
                await atProceedToMatching();
                return; // 큐 완료 이벤트가 UI를 처리함
            }

            document.getElementById('at-analyze-btn').disabled = false;
            document.getElementById('at-stop-btn').style.display = 'none';
            document.getElementById('at-progress-bar').style.display = 'none';
        }

        // 큐 기반 태그 분석 완료 후 매칭 단계 진행
        async function atProceedToMatching() {
            const category = document.getElementById('at-category').value;
            const doMatch = document.getElementById('at-do-match').checked;

            if (!doMatch) {
                document.getElementById('at-analyze-btn').disabled = false;
                document.getElementById('at-stop-btn').style.display = 'none';
                const progressInner = document.getElementById('at-progress-inner');
                if (progressInner) progressInner.style.width = '100%';
                setTimeout(() => { document.getElementById('at-progress-bar').style.display = 'none'; }, 500);
                showToast('태그 분석 완료', 'success');
                return;
            }

            // 매칭 결과 초기화 (새 세션 시작)
            atState.embeddingMatches = [];
            atState.imageMatches = [];
            atResetMatchPages();
            atState.chains = [];

            const uploadedFiles = atState.images.filter(i => i.file);
            const doneImages = atState.images.filter(i => i.status === 'done' && i.tags && i.tags.length > 0);

            // 임베딩 항목 (파일명 기반)
            const embItems = uploadedFiles.map(img => {
                const fileName = img.file.name || '';
                const baseName = fileName.substring(0, fileName.lastIndexOf('.')) || fileName;
                return { image_name: fileName, tags: [baseName] };
            });

            // 태그 항목 (분석된 태그 기반)
            const tagItems = doneImages.map(img => ({
                image_name: img.file.name || '',
                tags: [...new Set(img.tags.map(t => t.trim()))]
            }));

            // 중복 제거하여 병합
            const allItemsMap = {};
            for (const item of [...embItems, ...tagItems]) {
                const key = item.image_name;
                if (!allItemsMap[key]) {
                    allItemsMap[key] = { image_name: key, tags: [] };
                }
                const existingTags = new Set(allItemsMap[key].tags);
                for (const t of item.tags) {
                    if (!existingTags.has(t)) allItemsMap[key].tags.push(t);
                }
            }
            const allItems = Object.values(allItemsMap);

            if (allItems.length === 0) {
                showToast('매칭할 항목이 없습니다', 'error');
                document.getElementById('at-analyze-btn').disabled = false;
                document.getElementById('at-stop-btn').style.display = 'none';
                document.getElementById('at-progress-bar').style.display = 'none';
                return;
            }

            // 이미지당 개별 큐 아이템으로 분해
            atState.queueItemIds = [];
            atState.analyzeTotal = allItems.length;
            atState.analyzeCompleted = 0;

            const progressInner = document.getElementById('at-progress-inner');
            if (progressInner) progressInner.style.width = '0%';

            let addedCount = 0;
            for (const matchItem of allItems) {
                try {
                    const resp = await fetchJSON('/api/queue/add', {
                        method: 'POST',
                        headers: {'Content-Type': 'application/json'},
                        body: JSON.stringify({
                            type: 'auto_match_batch',
                            label: `배치 매칭 (${matchItem.image_name})`,
                            params: {
                                items: [matchItem],
                                category: category,
                                top_n: AT_MATCH_RESULT_LIMIT,
                                embedding_threshold: 0,
                            }
                        })
                    });
                    if (resp.item_id) {
                        atState.queueItemIds.push(resp.item_id);
                        addedCount++;
                    }
                } catch (e) {
                    console.error('[AT] 배치 매칭 큐 추가 오류:', matchItem.image_name, e);
                }
            }

            if (addedCount > 0) {
                showToast(`배치 매칭 ${addedCount}건 큐에 추가됨`, 'info');
            } else {
                showToast('배치 매칭 큐 추가 실패', 'error');
                document.getElementById('at-analyze-btn').disabled = false;
                document.getElementById('at-stop-btn').style.display = 'none';
                document.getElementById('at-progress-bar').style.display = 'none';
            }
        }

        async function atStopAnalysis() {
            // 대기 중인 큐 아이템 모두 취소
            if (atState.queueItemIds.length > 0) {
                for (const itemId of atState.queueItemIds) {
                    try {
                        await fetchJSON('/api/queue/cancel', {
                            method: 'POST',
                            headers: {'Content-Type': 'application/json'},
                            body: JSON.stringify({ id: itemId })
                        });
                    } catch (e) { console.error('[AT] 큐 취소 오류:', itemId, e); }
                }
                atState.queueItemIds = [];
            }
            if (atAbortController) {
                atAbortController.abort();
            }
            atState.images.forEach(i => { if (i.status === 'analyzing') i.status = 'pending'; });
            atRenderImages();
            document.getElementById('at-analyze-btn').disabled = false;
            document.getElementById('at-stop-btn').style.display = 'none';
            document.getElementById('at-progress-bar').style.display = 'none';
            showToast('분석이 중지되었습니다', 'warning');
        }

        function atShowAnalysisResults() {
            const section = document.getElementById('at-analysis-section');
            const container = document.getElementById('at-analysis-results');
            const done = atState.images.filter(i => i.status === 'done');
            if (done.length === 0) { section.style.display = 'none'; return; }

            section.style.display = 'block';
            container.innerHTML = '';
            done.forEach((item, i) => {
                const div = document.createElement('div');
                div.style.cssText = 'margin-bottom:12px; padding:8px 10px; background:var(--surface); border-radius:6px;';
                const name = item.file.name || `이미지 ${i + 1}`;
                const tagsHtml = (item.tags || []).map(t => `<span class="at-tag-chip">${escapeHtml(t)}</span>`).join('');
                div.innerHTML = `<div style="font-weight:600; font-size:0.85rem; margin-bottom:4px;">${escapeHtml(name)}</div><div class="at-tags-preview">${tagsHtml}</div>`;
                container.appendChild(div);
            });
        }

        function handleAutoMatchBatchProgress(data) {
            const phase = data.phase || '';

            if (phase === 'started') {
                return;
            }

            if (phase === 'completed') {
                // 개별 이미지 매칭 결과 누적
                const uploadedFiles = atState.images.filter(i => i.file);
                const doneImages = atState.images.filter(i => i.status === 'done' && i.tags && i.tags.length > 0);

                if (data.results) {
                    for (const r of data.results) {
                        if (r.embedding_matches && r.embedding_matches.length > 0) {
                            const img = uploadedFiles.find(i => (i.file.name || '') === r.image_name);
                            atState.embeddingMatches.push({
                                imageName: r.image_name || '이미지',
                                imageUrl: img ? img.url || '' : '',
                                matches: r.embedding_matches.map(m => ({ ...m, selected: false }))
                            });
                        }
                        if (r.matches && r.matches.length > 0) {
                            const img = doneImages.find(i => (i.file.name || '') === r.image_name);
                            const uniqueTags = img ? [...new Set(img.tags.map(t => t.trim()))] : [];
                            atState.imageMatches.push({
                                imageName: r.image_name || '이미지',
                                imageUrl: img ? img.url : '',
                                tags: uniqueTags,
                                matches: r.matches.map(m => ({ ...m, selected: false }))
                            });
                        }
                        if (r.chains && r.chains.length > 0) {
                            atState.chains.push(...r.chains);
                        }
                    }
                }

                atState.analyzeCompleted++;
                const progressInner = document.getElementById('at-progress-inner');
                if (progressInner && atState.analyzeTotal > 0) {
                    progressInner.style.width = Math.round((atState.analyzeCompleted / atState.analyzeTotal) * 100) + '%';
                }

                // 전체 매칭 완료 확인
                if (atState.analyzeCompleted >= atState.analyzeTotal) {
                    atState.queueItemIds = [];
                    document.getElementById('at-analyze-btn').disabled = false;
                    document.getElementById('at-stop-btn').style.display = 'none';
                    if (progressInner) progressInner.style.width = '100%';
                    setTimeout(() => { document.getElementById('at-progress-bar').style.display = 'none'; }, 500);

                    if (atState.embeddingMatches.length > 0 || atState.imageMatches.length > 0) {
                        atSwitchView('result');
                        atRenderMatches();
                        showToast('배치 매칭 완료', 'success');
                    } else {
                        showToast('매칭 결과가 없습니다', 'warning');
                    }
                }
            }
        }

        async function atMatchPresets(fileNames) {
            const category = document.getElementById('at-category').value;
            const doneImages = atState.images.filter(i => i.status === 'done' && i.tags && i.tags.length > 0);

            let tagNames = fileNames;
            if (!tagNames || tagNames.length === 0) {
                if (doneImages.length === 0) { showToast('매칭할 태그가 없습니다', 'error'); return; }
                tagNames = doneImages.map(i => {
                    const name = i.file.name || '';
                    return name.substring(0, name.lastIndexOf('.')) || name;
                });
            }

            try {
            atState.imageMatches = [];
            atState.matches = [];
            atState.embeddingMatches = [];
            atResetMatchPages();

            // 배치: 임베딩 매칭 + 태그 매칭을 1회 호출로 처리
            const allImages = atState.images.filter(i => i.file);
            const items = allImages.map(img => {
                const fileName = img.file.name || '';
                const baseName = fileName.substring(0, fileName.lastIndexOf('.')) || fileName;
                const tags = (img.status === 'done' && img.tags && img.tags.length > 0)
                    ? [...new Set(img.tags.map(t => t.trim()))]
                    : [baseName];
                return { image_name: fileName, tags: tags };
            });

            const batchResp = await fetch('/api/asset_tool/match_batch', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ items: items, category: category, top_n: AT_MATCH_RESULT_LIMIT, embedding_threshold: 0 })
            });
            const batchResult = await batchResp.json();

            if (batchResult.success && batchResult.results) {
                for (const r of batchResult.results) {
                    const img = allImages.find(i => (i.file.name || '') === r.image_name);
                    // 임베딩 매칭
                    if (r.embedding_matches && r.embedding_matches.length > 0) {
                        atState.embeddingMatches.push({
                            imageName: r.image_name || '이미지',
                            imageUrl: img ? img.url || '' : '',
                            matches: r.embedding_matches.map(m => ({ ...m, selected: false }))
                        });
                    }
                    // 태그 매칭 (Jaccard)
                    if (r.matches && r.matches.length > 0) {
                        const uniqueTags = (img && img.tags) ? [...new Set(img.tags.map(t => t.trim()))] : [];
                        atState.imageMatches.push({
                            imageName: r.image_name || '이미지',
                            imageUrl: img ? img.url : '',
                            tags: uniqueTags,
                            matches: r.matches.map(m => ({ ...m, selected: false }))
                        });
                    }
                }
            }

                atState.chains = [];
                atRenderMatches();
            } catch (e) {
                showToast('매칭 오류: ' + e.message, 'error');
            }
        }

        function _atSaveState() {
            console.log("[AT_SAVE_STATE] called, emb=" + atState.embeddingMatches.length + ", img=" + atState.imageMatches.length);
            try {
                sessionStorage.setItem('atState', JSON.stringify({
                    embeddingMatches: atState.embeddingMatches,
                    imageMatches: atState.imageMatches,
                    chains: atState.chains,
                    fillSlot: {
                        ...atFillSlot,
                        ref_images: (atFillSlot.ref_images || []).map(({ name, local_path, orig_filename }) => ({ name, local_path, orig_filename })),
                        style_ref_images: (atFillSlot.style_ref_images || []).map(({ name, local_path, orig_filename }) => ({ name, local_path, orig_filename })),
                    },
                }));
            } catch (e) {}
        }

        function _atLoadState() {
            console.log("[AT_LOAD_STATE] called");
            try {
                const saved = sessionStorage.getItem('atState');
                if (saved) {
                    const data = JSON.parse(saved);
                    atState.embeddingMatches = data.embeddingMatches || [];
                    atState.imageMatches = data.imageMatches || [];
                    atState.chains = data.chains || [];
                    if (data.fillSlot && typeof data.fillSlot === 'object') Object.assign(atFillSlot, data.fillSlot);
                    // Blob URL은 세션이 끊기면 무효화되므로 imageUrl 비워둠
                    atState.embeddingMatches.forEach(g => { g.imageUrl = ''; });
                    atState.imageMatches.forEach(g => { g.imageUrl = ''; });
                    // 다음 프레임에 렌더링
                    requestAnimationFrame(() => {
                        atRenderMatches();
                    });
                }
            } catch (e) {}
        }

        function atBuildCompareVisual(name) {
            const url = atState.compareImages[name] || '';
            const meta = atState.compareImageMeta[name] || {};
            const source = meta.source || '';
            const label = source === 'direct'
                ? '선택 복장'
                : (source === 'existing_asset' ? '기존 에셋' : (source === 'generated_default' ? '기본 이미지' : ''));
            return {
                url,
                source,
                badge: label ? `<span class="at-source-badge ${source}">${label}</span>` : '',
                image: url
                    ? `<img src="${url}" loading="lazy" style="width:100%;height:100%;object-fit:cover;display:block;" onclick="openLightbox(this.src)">`
                    : '<div class="at-card-empty-visual"><span>이미지 없음<br>우측 패널에서 생성할 수 있습니다</span></div>',
            };
        }

        function atResetMatchPages() {
            atMatchPages.embedding = {};
            atMatchPages.tag = {};
        }

        function atCreateMatchPager(type, imageName, title, color, totalItems) {
            if (!atMatchPages[type]) {
                console.error(`[AUTOMATCH] 알 수 없는 매칭 페이지 유형: ${type}`);
                return { element: document.createElement('div'), start: 0, end: AT_MATCH_PAGE_SIZE };
            }
            const totalPages = Math.max(1, Math.ceil(totalItems / AT_MATCH_PAGE_SIZE));
            const storedPage = Number.parseInt(atMatchPages[type][imageName] || 0, 10);
            const page = Math.max(0, Math.min(totalPages - 1, Number.isFinite(storedPage) ? storedPage : 0));
            atMatchPages[type][imageName] = page;

            const row = document.createElement('div');
            row.className = 'at-match-title-row';
            const previous = document.createElement('button');
            previous.type = 'button';
            previous.className = 'at-page-btn';
            previous.textContent = '‹';
            previous.title = `${title} 이전 페이지`;
            previous.setAttribute('aria-label', `${title} 이전 페이지`);
            previous.disabled = page === 0;
            previous.onclick = () => atChangeMatchPage(type, imageName, page - 1, totalPages);

            const heading = document.createElement('div');
            heading.className = 'at-match-title';
            heading.style.color = color;
            heading.textContent = `${title} · ${totalItems}개`;

            const pageLabel = document.createElement('span');
            pageLabel.className = 'at-page-label';
            pageLabel.textContent = `${page + 1}/${totalPages}`;

            const next = document.createElement('button');
            next.type = 'button';
            next.className = 'at-page-btn';
            next.textContent = '›';
            next.title = `${title} 다음 페이지`;
            next.setAttribute('aria-label', `${title} 다음 페이지`);
            next.disabled = page >= totalPages - 1;
            next.onclick = () => atChangeMatchPage(type, imageName, page + 1, totalPages);

            row.append(previous, heading, pageLabel, next);
            const start = page * AT_MATCH_PAGE_SIZE;
            return { element: row, start, end: Math.min(start + AT_MATCH_PAGE_SIZE, totalItems) };
        }

        function atChangeMatchPage(type, imageName, nextPage, totalPages) {
            if (!atMatchPages[type]) {
                console.error(`[AUTOMATCH] 페이지 변경 실패: 알 수 없는 유형 ${type}`);
                return;
            }
            atMatchPages[type][imageName] = Math.max(0, Math.min(totalPages - 1, nextPage));
            atRenderMatches();
        }

        function atRenderMatches() {
            console.log("[AT_RENDER_MATCHES] called, emb=" + atState.embeddingMatches.length + ", img=" + atState.imageMatches.length);
            const canvas = document.getElementById('at-canvas');
            const emptyMsg = document.getElementById('at-match-empty');
            if (!canvas) return;
            canvas.innerHTML = '';
            const summaryMeta = document.getElementById('at-result-summary-meta');
            const imageCount = document.getElementById('at-result-image-count');

            if (atState.embeddingMatches.length === 0 && atState.imageMatches.length === 0) {
                canvas.innerHTML = '<div class="at-empty-state">이미지를 분석하면<br>매칭 결과가 여기에 표시됩니다</div>';
                if (summaryMeta) summaryMeta.textContent = '분석 결과가 아직 없습니다';
                if (imageCount) imageCount.textContent = '0개 이미지';
                atUpdateFillAvailability();
                return;
            }

            const enc = encodeURIComponent;

            // 모든 이미지 이름 수집
            const allImageNames = [];
            atState.embeddingMatches.forEach(g => { if (!allImageNames.includes(g.imageName)) allImageNames.push(g.imageName); });
            atState.imageMatches.forEach(g => { if (!allImageNames.includes(g.imageName)) allImageNames.push(g.imageName); });
            const directCount = Object.values(atState.compareImageMeta).filter(item => item.source === 'direct').length;
            const existingCount = Object.values(atState.compareImageMeta).filter(item => item.source === 'existing_asset').length;
            const defaultCount = Object.values(atState.compareImageMeta).filter(item => item.source === 'generated_default').length;
            if (summaryMeta) summaryMeta.textContent = `선택 복장 ${directCount}개 · 기존 에셋 ${existingCount}개 · 기본 이미지 ${defaultCount}개 · 나머지는 빈 슬롯`;
            if (imageCount) imageCount.textContent = `${allImageNames.length}개 이미지`;

            allImageNames.forEach((imgName, imgIdx) => {
                const embGroup = atState.embeddingMatches.find(g => g.imageName === imgName);
                const tagGroup = atState.imageMatches.find(g => g.imageName === imgName);
                const imageUrl = (embGroup && embGroup.imageUrl) ? embGroup.imageUrl : (tagGroup ? tagGroup.imageUrl : '');

                // 이미지 구분선
                if (imgIdx > 0) {
                    const sep = document.createElement('div');
                    sep.className = 'at-card-separator';
                    sep.innerHTML = `<div class="at-card-separator-line"></div><div class="at-card-separator-label">${escapeHtml(imgName)}</div><div class="at-card-separator-line"></div>`;
                    canvas.appendChild(sep);
                }

                const wrapper = document.createElement('div');
                wrapper.className = 'at-result-item' + (imageUrl ? '' : ' no-source');

                // 왼쪽: 업로드 이미지 + 선택된 매칭 비교 이미지
                if (imageUrl) {
                    const srcCard = document.createElement('div');
                    srcCard.className = 'at-card at-card-source at-result-source';
                    const selEmb = embGroup ? embGroup.matches.find(m => m.selected) : null;
                    const selTag = tagGroup ? tagGroup.matches.find(m => m.selected) : null;
                    const selName = selEmb ? selEmb.name : (selTag ? selTag.name : '');
                    const selectedVisual = selName ? atBuildCompareVisual(selName) : null;
                    const compareHtml = selName
                        ? `<div style="margin-top:8px;"><div style="font-size:0.75rem;color:var(--text2);margin-bottom:4px;">선택: ${escapeHtml(selName)}</div><div class="at-card-img" style="aspect-ratio:3/4;border-radius:8px;">${selectedVisual.image}${selectedVisual.badge}</div></div>`
                        : '';
                    srcCard.innerHTML = `
                        <div class="at-card-img"><img src="${imageUrl}" loading="lazy" onclick="openLightbox(this.src)"></div>
                        <div class="at-card-body"><div class="at-card-name">${escapeHtml(imgName)}</div></div>
                        ${compareHtml}
                    `;
                    wrapper.appendChild(srcCard);
                }

                // 오른쪽: 매칭 결과 (카드 그리드, 행 내부 스크롤 없음)
                const rightCol = document.createElement('div');
                rightCol.className = 'at-match-column';

                // 임베딩 매칭 결과
                if (embGroup && embGroup.matches.length > 0) {
                    const egi = atState.embeddingMatches.indexOf(embGroup);
                    const embPager = atCreateMatchPager('embedding', imgName, '🧠 임베딩 매칭', 'var(--accent)', embGroup.matches.length);
                    rightCol.appendChild(embPager.element);

                    const embRow = document.createElement('div');
                    embRow.className = 'at-match-grid';
                    embGroup.matches.slice(embPager.start, embPager.end).forEach((m, pageIndex) => {
                        const i = embPager.start + pageIndex;
                        const card = document.createElement('div');
                        const visual = atBuildCompareVisual(m.name);
                        card.className = 'at-card' + (m.selected ? ' selected' : '') + (!visual.url ? ' is-empty' : '');
                        const simPct = m.similarity ? Math.round(m.similarity * 100) : 0;
                        const cleanName = m.clean_name ? `<div style="font-size:0.7rem; color:var(--text2);">(${escapeHtml(m.clean_name)})</div>` : '';
                        const matchedTag = m.matched_tag ? `<div style="font-size:0.7rem; color:var(--text2);">← ${escapeHtml(m.matched_tag)}</div>` : '';
                        card.innerHTML = `
                            <div class="at-card-img">
                                <input type="checkbox" class="at-card-check" ${m.selected ? 'checked' : ''} onchange="atSelectSingleMatch('embedding', ${egi}, ${i}, ${imgIdx}, this.checked); ">
                                <div class="at-card-pct">${simPct}%</div>
                                ${visual.image}${visual.badge}
                            </div>
                            <div class="at-card-body">
                                <div class="at-card-name">${escapeHtml(m.name)}</div>
                                ${cleanName}
                                ${matchedTag}
                                <div class="at-card-detail">유사도 ${simPct}%</div>
                            </div>
                        `;
                        embRow.appendChild(card);
                    });
                    rightCol.appendChild(embRow);
                }

                // 태그 매칭 결과
                if (tagGroup && tagGroup.matches.length > 0) {
                    const gi = atState.imageMatches.indexOf(tagGroup);
                    const tagPager = atCreateMatchPager('tag', imgName, '🏷️ 태그 매칭', '#4caf50', tagGroup.matches.length);
                    rightCol.appendChild(tagPager.element);

                    const tagsLine = document.createElement('div');
                    tagsLine.style.cssText = 'display:flex; flex-wrap:wrap; gap:3px; margin-bottom:8px;';
                    tagsLine.innerHTML = tagGroup.tags.map(t => `<span class="at-tag-chip">${escapeHtml(t)}</span>`).join('');
                    rightCol.appendChild(tagsLine);

                    const tagRow = document.createElement('div');
                    tagRow.className = 'at-match-grid';
                    tagGroup.matches.slice(tagPager.start, tagPager.end).forEach((m, pageIndex) => {
                        const i = tagPager.start + pageIndex;
                        const card = document.createElement('div');
                        const visual = atBuildCompareVisual(m.name);
                        card.className = 'at-card' + (m.selected ? ' selected' : '') + (!visual.url ? ' is-empty' : '');
                        const isManual = m.manual === true;
                        const matchPct = isManual ? '수동' : (m.jaccard > 0 ? Math.round(m.jaccard * 100) : 0);
                        const matchedStr = (m.matched_tags || []).map(t => `<span class="at-tag-chip" style="border-color:#4caf50;background:rgba(76,175,80,0.1);">${escapeHtml(t)}</span>`).join('');
                        const unmatchedStr = (m.unmatched_preset || []).slice(0, 5).map(t => `<span class="at-tag-chip" style="border-color:#999;background:rgba(158,158,158,0.1);">${escapeHtml(t)}</span>`).join('');
                        card.innerHTML = `
                            <div class="at-card-img">
                                <input type="checkbox" class="at-card-check" ${m.selected ? 'checked' : ''} onchange="atSelectSingleMatch('tag', ${gi}, ${i}, ${imgIdx}, this.checked); ">
                                <div class="at-card-pct">${isManual ? matchPct : matchPct + '%'}</div>
                                ${visual.image}${visual.badge}
                            </div>
                            <div class="at-card-body">
                                <div class="at-card-name">${escapeHtml(m.name)}</div>
                                <div class="at-card-detail">${isManual ? '수동 추가' : ('일치 ' + m.match_ratio)}</div>
                                <div class="at-card-tags">${matchedStr}${unmatchedStr}</div>
                            </div>
                        `;
                        tagRow.appendChild(card);
                    });
                    rightCol.appendChild(tagRow);
                }

                // --- manual preset add UI
                const manualWrap = document.createElement('div');
                manualWrap.style.cssText = 'margin-top:12px;';
                const manualBtn = document.createElement('button');
                manualBtn.className = 'at-btn';
                manualBtn.style.cssText = 'font-size:0.78rem; padding:4px 10px; background:var(--surface2);';
                manualBtn.textContent = '\u2795 프리셋 직접 추가';
                const manualSearchWrap = document.createElement('div');
                manualSearchWrap.style.cssText = 'display:none; margin-top:4px;';
                const manualSearchInput = document.createElement('input');
                manualSearchInput.type = 'text';
                manualSearchInput.placeholder = '프리셋 검색...';
                manualSearchInput.style.cssText = 'width:100%; padding:6px 8px; border:1px solid var(--border); border-radius:4px; background:var(--surface2); color:var(--text); font-size:0.78rem; box-sizing:border-box;';
                const manualSearchList = document.createElement('div');
                manualSearchList.style.cssText = 'max-height:160px; overflow-y:auto; margin-top:4px; border:1px solid var(--border); border-radius:4px; background:var(--surface);';
                manualSearchList.innerHTML = atBuildPresetSearchList('');
                manualSearchInput.oninput = (e) => {
                    manualSearchList.innerHTML = atBuildPresetSearchList(e.target.value);
                };
                manualSearchList.onclick = (e) => {
                    const item = e.target.closest('[data-preset]');
                    if (item) {
                        atAddManualMatch(imgName, item.dataset.preset);
                        manualSearchWrap.style.display = 'none';
                        manualSearchInput.value = '';
                        manualSearchList.innerHTML = atBuildPresetSearchList('');
                    }
                };
                manualSearchWrap.appendChild(manualSearchInput);
                manualSearchWrap.appendChild(manualSearchList);
                manualBtn.onclick = () => {
                    manualSearchWrap.style.display = manualSearchWrap.style.display === 'none' ? 'block' : 'none';
                    if (manualSearchWrap.style.display !== 'none') manualSearchInput.focus();
                };
                manualWrap.appendChild(manualBtn);
                manualWrap.appendChild(manualSearchWrap);
                rightCol.appendChild(manualWrap);

                wrapper.appendChild(rightCol);
                canvas.appendChild(wrapper);
            });
            atUpdateFillAvailability();
            _atSaveState();
        }

        function atSelectSingleMatch(type, groupIdx, matchIdx, imgIdx, checked) {
            const allImageNames = [];
            atState.embeddingMatches.forEach(g => { if (!allImageNames.includes(g.imageName)) allImageNames.push(g.imageName); });
            atState.imageMatches.forEach(g => { if (!allImageNames.includes(g.imageName)) allImageNames.push(g.imageName); });

            const currentImgName = allImageNames[imgIdx];
            if (!currentImgName) return;

            atState.embeddingMatches.forEach((g) => {
                if (g.imageName !== currentImgName) return;
                g.matches.forEach((m) => { m.selected = false; });
            });
            atState.imageMatches.forEach((g) => {
                if (g.imageName !== currentImgName) return;
                g.matches.forEach((m) => { m.selected = false; });
            });

            if (checked) {
                if (type === 'embedding') {
                    atState.embeddingMatches[groupIdx].matches[matchIdx].selected = true;
                } else {
                    atState.imageMatches[groupIdx].matches[matchIdx].selected = true;
                }
            }

            atRenderMatches();
        }
        function atBuildPresetSearchList(query) {
            const category = document.getElementById('at-category').value;
            let presets = {};
            if (category === 'expressions') presets = (assetTags && assetTags.expressions) || {};
            else if (category === 'composition') presets = (assetTags && assetTags.composition_presets) || {};
            else if (category === 'quality') presets = (assetTags && assetTags.quality_presets) || {};
            else if (category === 'appearances') presets = (assetTags && assetTags.appearances) || {};
            else if (category === 'outfits') presets = (assetTags && assetTags.outfits) || {};
            else if (category === 'negative') presets = (assetTags && assetTags.negative_presets) || {};
            const q = (query || '').toLowerCase().trim();
            const names = Object.keys(presets).sort().filter(name => !q || name.toLowerCase().includes(q));
            if (names.length === 0) {
                return '<div style="padding:8px; font-size:0.75rem; color:var(--text2); text-align:center;">결과 없음</div>';
            }
            return names.map(name => '<div data-preset="' + escapeHtml(name) + '" style="padding:6px 8px; font-size:0.78rem; cursor:pointer; border-bottom:1px solid var(--border); transition:background 0.15s;" onmouseenter="this.style.background=\'var(--surface2)\'" onmouseleave="this.style.background=\'transparent\'">' + escapeHtml(name) + '</div>').join('');
        }

        function atAddManualMatch(imgName, presetName) {
            let group = atState.imageMatches.find(g => g.imageName === imgName);
            if (!group) {
                const img = atState.images.find(i => (i.file && i.file.name || '') === imgName);
                group = {
                    imageName: imgName,
                    imageUrl: img ? img.url : '',
                    tags: [],
                    matches: []
                };
                atState.imageMatches.push(group);
            }
            if (group.matches.some(m => m.name === presetName)) {
                showToast('이미 추가된 프리셋입니다', 'warning');
                return;
            }
            // 기존 선택 해제
            group.matches.forEach(m => { m.selected = false; });
            group.matches.unshift({
                name: presetName,
                jaccard: 0,
                match_ratio: '수동',
                matched_tags: [],
                unmatched_preset: [],
                selected: true,
                manual: true
            });
            atRenderMatches();
            showToast(`"${presetName}" 추가됨`, 'success');
        }

        function atSendToBatch() {
            const category = document.getElementById('at-category').value;
            const newChains = [];

            atState.imageMatches.forEach(imgGroup => {
                imgGroup.matches.filter(m => m.selected).forEach(m => {
                    const chain = {
                        character: '',
                        appearance: '',
                        outfit: '',
                        expression: '',
                        composition_preset: '',
                        quality_preset: '',
                        negative_preset: '',
                        character_negative_preset: '',
                        ref_enabled: false,
                        ref_strength: 0.55,
                        ref_image: '',
                        ref_local_path: '',
                        style_ref_enabled: false,
                        style_ref_strength: 0.55,
                        style_ref_image: '',
                        pose_enabled: false,
                        pose_id: '',
                        hrf_enabled: false,
                        fd_enabled: false,
                        hd_enabled: false,
                        ed_enabled: false,
                    };
                    if (category === 'expressions') chain.expression = m.name;
                    else if (category === 'composition') chain.composition_preset = m.name;
                    else if (category === 'quality') chain.quality_preset = m.name;
                    else if (category === 'character') {
                        chain.expression = (m.character_data || {}).expression || '';
                        chain.appearance = (m.character_data || {}).appearance || '';
                        chain.outfit = (m.character_data || {}).outfit || '';
                    }
                    else if (category === 'appearances') chain.appearance = m.name;
                    else if (category === 'outfits') chain.outfit = m.name;
                    newChains.push(chain);
                });
            });

            atState.embeddingMatches.forEach(embGroup => {
                embGroup.matches.filter(m => m.selected).forEach(m => {
                const chain = {
                    character: '',
                    appearance: '',
                    outfit: '',
                    expression: '',
                    composition_preset: '',
                    quality_preset: '',
                    negative_preset: '',
                    character_negative_preset: '',
                    ref_enabled: false,
                    ref_strength: 0.55,
                    ref_image: '',
                    ref_local_path: '',
                    style_ref_enabled: false,
                    style_ref_strength: 0.55,
                    style_ref_image: '',
                    pose_enabled: false,
                    pose_id: '',
                    hrf_enabled: false,
                    fd_enabled: false,
                    hd_enabled: false,
                    ed_enabled: false,
                    artist_preset: '',
                    natural_language_preset: '',
                };
                if (category === 'expressions') chain.expression = m.name;
                else if (category === 'composition') chain.composition_preset = m.name;
                else if (category === 'quality') chain.quality_preset = m.name;
                else if (category === 'appearances') chain.appearance = m.name;
                else if (category === 'outfits') chain.outfit = m.name;
                newChains.push(chain);
            });
            });

            if (newChains.length === 0) { showToast('선택된 매칭이 없습니다', 'error'); return; }

            // 에셋 일괄 생성 탭에 체인 추가
            if (typeof addBatchChainSlot === 'function') {
                newChains.forEach(chain => {
                    addBatchChainSlot(chain);
                });
            }

            // 에셋 일괄 생성 탭으로 전환
            if (typeof switchTab === 'function') {
                switchTab('batch');
            }
            showToast(`${newChains.length}개 체인이 에셋 일괄 생성에 추가되었습니다`, 'success');
        }

        // ─── 오토매치 내보내기 (이름 치환 / 체인) ─────────────────────────

        function _atGetAllImageNames() {
            const names = [];
            atState.embeddingMatches.forEach(g => { if (!names.includes(g.imageName)) names.push(g.imageName); });
            atState.imageMatches.forEach(g => { if (!names.includes(g.imageName)) names.push(g.imageName); });
            return names;
        }

        function _atGetSelectedForImage(imgName) {
            const selEmb = atState.embeddingMatches.find(g => g.imageName === imgName);
            const selTag = atState.imageMatches.find(g => g.imageName === imgName);
            const embMatch = selEmb ? selEmb.matches.find(m => m.selected) : null;
            const tagMatch = selTag ? selTag.matches.find(m => m.selected) : null;
            return embMatch || tagMatch || null;
        }

        function _atValidateSelection() {
            const allNames = _atGetAllImageNames();
            if (allNames.length === 0) {
                showToast('매칭 결과가 없습니다. 먼저 분석을 진행해주세요.', 'warning');
                return false;
            }
            for (const imgName of allNames) {
                if (!_atGetSelectedForImage(imgName)) {
                    showToast('모든 이미지에 대해 매칭을 선택해주세요', 'warning');
                    return false;
                }
            }
            return true;
        }

                function atExportNameMapping() {
            if (!_atValidateSelection()) return;

            const charName = document.getElementById('at-compare-char').value || '';
            const category = document.getElementById("at-category").value || "expressions";
            const allNames = _atGetAllImageNames();
            const outfitMapping = {};
            const expressionMapping = {};

            allNames.forEach(imgName => {
                const match = _atGetSelectedForImage(imgName);
                if (match) {
                    // Python _safe_dirname()과 동일하게 폴더명과 매칭되도록 변환
                    const safeName = match.name.replace(/[^\p{L}\p{N} _\-\.]/gu, '').trim();
                    // 업로드 화면의 감정 미리보기와 같은 규칙을 단일 기준으로 사용한다.
                    const cleanedValue = atExtractEmotion(imgName);
                    if (category === "outfits") {
                        outfitMapping[safeName] = cleanedValue;
                    } else {
                        expressionMapping[safeName] = cleanedValue;
                    }
                }
            });

            const data = {
                export_name: charName,
                outfit_mapping: outfitMapping,
                expression_mapping: expressionMapping,
                export_format: 'webp',
                export_quality: 90,
                naming_order: ['character', 'outfit', 'expression'],
                naming_enabled: { character: true, outfit: true, expression: true }
            };
            const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `name_mapping_${Date.now()}.json`;
            a.click();
            URL.revokeObjectURL(url);
            showToast('이름 치환 규칙을 다운로드합니다', 'success');
        }        async function atExportChain() {
            if (!_atValidateSelection()) return;

            const charName = document.getElementById('at-compare-char').value || '';
            const allNames = _atGetAllImageNames();
            const chains = [];

            let epSettings = {};
            if (charName) {
                try {
                    const resp = await fetch(`/api/asset_mode/ep_settings/${encodeURIComponent(charName)}`);
                    epSettings = await resp.json();
                } catch (e) {
                    console.warn('[체인내보내기] ep_settings 로드 실패:', e);
                }
            }

            allNames.forEach(imgName => {
                const match = _atGetSelectedForImage(imgName);
                if (!match) return;

                const perExpr = epSettings.per_expression || {};
                const exprSettings = perExpr[match.name] || {};

                const chain = {
                    character: exprSettings.character || epSettings.character || '',
                    appearance: exprSettings.appearance || epSettings.appearance || '',
                    outfit: exprSettings.outfit || epSettings.outfit || '',
                    expression: match.name,
                    composition_preset: exprSettings.composition_preset || epSettings.composition_preset || '',
                    quality_preset: exprSettings.quality_preset || epSettings.quality_preset || '',
                    negative_preset: exprSettings.negative_preset || epSettings.negative_preset || '',
                    character_negative_preset: exprSettings.character_negative_preset || epSettings.character_negative_preset || '',
                    ref_enabled: exprSettings.ref_enabled !== undefined ? exprSettings.ref_enabled : (epSettings.ref_enabled || false),
                    ref_strength: exprSettings.ref_strength || epSettings.ref_strength || 0.55,
                    ref_image: '',
                    ref_local_path: '',
                    style_ref_enabled: exprSettings.style_ref_enabled !== undefined ? exprSettings.style_ref_enabled : (epSettings.style_ref_enabled || false),
                    style_ref_strength: exprSettings.style_ref_strength || epSettings.style_ref_strength || 0.55,
                    style_ref_image: '',
                    pose_enabled: false,
                    pose_id: '',
                    hrf_enabled: exprSettings.hrf_enabled !== undefined ? exprSettings.hrf_enabled : (epSettings.hrf_enabled || false),
                    fd_enabled: exprSettings.fd_enabled !== undefined ? exprSettings.fd_enabled : (epSettings.fd_enabled || false),
                    hd_enabled: exprSettings.hd_enabled !== undefined ? exprSettings.hd_enabled : (epSettings.hd_enabled || false),
                    ed_enabled: exprSettings.ed_enabled !== undefined ? exprSettings.ed_enabled : (epSettings.ed_enabled || false),
                };
                chains.push(chain);
            });

            const payload = {
                version: 1,
                repeat: 1,
                chains,
            };

            const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `chain_export_${Date.now()}.json`;
            a.click();
            URL.revokeObjectURL(url);
            showToast('체인 파일을 다운로드합니다', 'success');
        }

        // ─── 임베딩 설정 UI ─────────────────────────────────────────
        const AT_CLEAN_ACTIONS = [
            { value: 'split_by', label: '구분자로 분리', params: ['separator', 'take'] },
            { value: 'strip_suffix', label: '접미사 제거', params: ['pattern'] },
            { value: 'strip_prefix', label: '접두사 제거', params: ['pattern'] },
            { value: 'replace', label: '치환', params: ['from', 'to'] },
            { value: 'strip', label: '공백 제거', params: [] },
            { value: 'lower', label: '소문자화', params: [] },
        ];
        let atEmbedProfiles = {};
        let atEmbedCurrentSource = 'preset';
        let atEmbedActiveSteps = { preset: [], tag: [] };

        // 태그 필터링 액션
        const TAG_FILTER_ACTIONS = [
            { value: 'remove_match', label: '패턴 일치 제거', params: ['pattern'] },
            { value: 'split_by', label: '구분자로 분리', params: ['separator', 'take'] },
            { value: 'replace', label: '치환', params: ['from', 'to'] },
            { value: 'strip_prefix', label: '접두사 제거', params: ['pattern'] },
            { value: 'strip_suffix', label: '접미사 제거', params: ['pattern'] },
            { value: 'strip', label: '공백 제거', params: [] },
            { value: 'lower', label: '소문자화', params: [] },
        ];
        let tagFilterProfiles = {};
        let tagFilterActiveProfile = '';
        let tagFilterSteps = [];
        let tagFilterSelectedItems = [];

        function atGetCurrentProfileType(source) {
            return source || 'preset';
        }

        function atGetCurrentProfileName(source) {
            const selId = (source || 'preset') === 'tag' ? 'at-embed-profile-select-tag' : 'at-embed-profile-select-preset';
            const sel = document.getElementById(selId);
            return sel ? sel.value : '';
        }

        function atInitEmbedView() {
            atLoadProfiles();
            atLoadCacheStatus();
        }

        async function atLoadProfiles() {
            try {
                const resp = await fetch('/api/asset_tool/embedding_profiles');
                const result = await resp.json();
                if (!result.success) { showToast('프로필 로드 실패', 'error'); return; }
                atEmbedProfiles = result.profiles || {};
                // 두 영역 모두 렌더링
                atRenderProfileSelect('at-embed-profile-select-preset', result.active_preset_profile);
                atRenderProfileSelect('at-embed-profile-select-tag', result.active_tag_profile);
                // 프리셋 steps
                const presetName = result.active_preset_profile;
                const presetSteps = atEmbedProfiles[presetName] || [];
                atEmbedActiveSteps.preset = JSON.parse(JSON.stringify(presetSteps));
                atRenderCleanSteps(atEmbedActiveSteps.preset, 'preset');
                // 태그 steps (모달 평면 규칙 리스트에서 편집) — 오버라이드(인메모리 적용) 우선
                const tagSteps = Array.isArray(result.active_tag_steps) ? result.active_tag_steps : (atEmbedProfiles[result.active_tag_profile] || []);
                atEmbedActiveSteps.tag = JSON.parse(JSON.stringify(tagSteps));
                atRenderCleanSteps(atEmbedActiveSteps.tag, 'tag');
                // 모달이 열려 있으면 규칙 편집기/미리보기 갱신, 업로드 카드 감정 라벨도 갱신
                atEmotionRenderRules();
                atEmotionUpdatePreview();
                atRenderImages();
            } catch (e) {
                showToast('프로필 로드 오류: ' + e.message, 'error');
            }
        }

        function atRenderProfileSelect(selectId, activeName) {
            const sel = document.getElementById(selectId);
            if (!sel) return;
            sel.innerHTML = '';
            const names = Object.keys(atEmbedProfiles);
            names.forEach(name => {
                const opt = document.createElement('option');
                opt.value = name;
                opt.textContent = name;
                if (name === activeName) opt.selected = true;
                sel.appendChild(opt);
            });
        }

        function atOnProfileSelect(source) {
            const name = atGetCurrentProfileName(source);
            const steps = atEmbedProfiles[name] || [];
            atEmbedActiveSteps[source] = JSON.parse(JSON.stringify(steps));
            atRenderCleanSteps(atEmbedActiveSteps[source], source);
        }

        function atRenderCleanSteps(steps, source) {
            const container = document.getElementById(`at-embed-steps-container-${source}`);
            if (!container) return; // 태그 정제는 모달의 평면 규칙 리스트(atEmotionRenderRules)로 이관
            container.innerHTML = '';
            const maxSteps = Math.max(steps.length, 1);
            for (let i = 0; i < maxSteps; i++) {
                const step = steps[i] || {};
                const stepDiv = document.createElement('div');
                stepDiv.style.cssText = 'display:flex; gap:8px; align-items:center; margin-bottom:8px; flex-wrap:wrap;';
                const stepNum = document.createElement('span');
                stepNum.textContent = `${i + 1}단계:`;
                stepNum.style.cssText = 'font-weight:600; font-size:0.82rem; min-width:42px;';
                stepDiv.appendChild(stepNum);

                const actionSelect = document.createElement('select');
                actionSelect.style.cssText = 'padding:4px 8px; border-radius:5px; border:1px solid var(--border); background:var(--surface); color:var(--text); font-size:0.82rem; min-width:140px;';
                actionSelect.innerHTML = '<option value="">(없음)</option>' + AT_CLEAN_ACTIONS.map(a => `<option value="${a.value}" ${step.action === a.value ? 'selected' : ''}>${a.label}</option>`).join('');
                actionSelect.onchange = () => { atOnStepChange(i, source); };
                stepDiv.appendChild(actionSelect);

                if (step.action === 'split_by') {
                    const sepInput = document.createElement('input');
                    sepInput.type = 'text'; sepInput.value = step.separator || '_';
                    sepInput.placeholder = '구분자';
                    sepInput.style.cssText = 'width:50px; padding:4px 6px; border-radius:5px; border:1px solid var(--border); background:var(--surface); color:var(--text); font-size:0.82rem; text-align:center;';
                    sepInput.id = `at-step-${source}-${i}-separator`;
                    stepDiv.appendChild(sepInput);
                    const takeInput = document.createElement('input');
                    takeInput.type = 'text'; takeInput.value = step.take !== undefined ? String(step.take) : '-1';
                    takeInput.placeholder = '위치';
                    takeInput.style.cssText = 'width:80px; padding:4px 6px; border-radius:5px; border:1px solid var(--border); background:var(--surface); color:var(--text); font-size:0.82rem;';
                    takeInput.id = `at-step-${source}-${i}-take`;
                    stepDiv.appendChild(takeInput);
                } else if (step.action === 'strip_suffix' || step.action === 'strip_prefix') {
                    const patInput = document.createElement('input');
                    patInput.type = 'text'; patInput.value = step.pattern || '';
                    patInput.placeholder = '정규식 패턴';
                    patInput.style.cssText = 'width:200px; padding:4px 6px; border-radius:5px; border:1px solid var(--border); background:var(--surface); color:var(--text); font-size:0.82rem;';
                    patInput.id = `at-step-${source}-${i}-pattern`;
                    stepDiv.appendChild(patInput);
                } else if (step.action === 'replace') {
                    const fromInput = document.createElement('input');
                    fromInput.type = 'text'; fromInput.value = step.from || '';
                    fromInput.placeholder = '찾을 문자';
                    fromInput.style.cssText = 'width:60px; padding:4px 6px; border-radius:5px; border:1px solid var(--border); background:var(--surface); color:var(--text); font-size:0.82rem; text-align:center;';
                    fromInput.id = `at-step-${source}-${i}-from`;
                    stepDiv.appendChild(fromInput);
                    const arrow = document.createElement('span');
                    arrow.textContent = '→';
                    arrow.style.cssText = 'font-size:0.82rem;';
                    stepDiv.appendChild(arrow);
                    const toInput = document.createElement('input');
                    toInput.type = 'text'; toInput.value = step.to !== undefined ? step.to : ' ';
                    toInput.placeholder = '바꿀 문자';
                    toInput.style.cssText = 'width:60px; padding:4px 6px; border-radius:5px; border:1px solid var(--border); background:var(--surface); color:var(--text); font-size:0.82rem; text-align:center;';
                    toInput.id = `at-step-${source}-${i}-to`;
                    stepDiv.appendChild(toInput);
                }

                const removeBtn = document.createElement('button');
                removeBtn.textContent = '✕';
                removeBtn.style.cssText = 'border:none; background:transparent; color:var(--error); cursor:pointer; font-size:0.9rem; padding:2px 6px;';
                removeBtn.onclick = () => { atRemoveStep(i, source); };
                stepDiv.appendChild(removeBtn);

                container.appendChild(stepDiv);
            }
            // 태그 규칙 변경 시 모달/업로드 화면의 감정 라벨을 실시간 갱신
            if (source === 'tag') {
                atEmotionUpdatePreview();
                atRenderImages();
            }
        }

        function atOnStepChange(stepIndex, source) {
            atReadStepsFromUI(source);
            atRenderCleanSteps(atEmbedActiveSteps[source], source);
            const container = document.getElementById(`at-embed-steps-container-${source}`);
            const rows = container.querySelectorAll(':scope > div');
            if (rows[stepIndex]) {
                const sel = rows[stepIndex].querySelector('select');
                if (sel) sel.focus();
            }
        }

        function atReadStepsFromUI(source) {
            const steps = [];
            const container = document.getElementById(`at-embed-steps-container-${source}`);
            if (!container) return steps; // 태그 정제는 모달 평면 규칙 리스트 사용
            const rows = container.querySelectorAll(':scope > div');
            rows.forEach((row, i) => {
                const actionSelect = row.querySelector('select');
                if (!actionSelect || !actionSelect.value) return;
                const step = { action: actionSelect.value };
                if (step.action === 'split_by') {
                    const sepEl = document.getElementById(`at-step-${source}-${i}-separator`);
                    const takeEl = document.getElementById(`at-step-${source}-${i}-take`);
                    step.separator = sepEl ? sepEl.value : '_';
                    const takeVal = takeEl ? takeEl.value.trim() : '-1';
                    step.take = takeVal.match(/^-?\d+$/) ? parseInt(takeVal) : takeVal;
                } else if (step.action === 'strip_suffix' || step.action === 'strip_prefix') {
                    const patEl = document.getElementById(`at-step-${source}-${i}-pattern`);
                    step.pattern = patEl ? patEl.value : '';
                } else if (step.action === 'replace') {
                    const fromEl = document.getElementById(`at-step-${source}-${i}-from`);
                    const toEl = document.getElementById(`at-step-${source}-${i}-to`);
                    step.from = fromEl ? fromEl.value : '';
                    step.to = toEl ? toEl.value : ' ';
                }
                steps.push(step);
            });
            atEmbedActiveSteps[source] = steps;
            return steps;
        }

        function atAddStep(source) {
            atReadStepsFromUI(source);
            atEmbedActiveSteps[source].push({ action: 'replace', from: '_', to: ' ' });
            atRenderCleanSteps(atEmbedActiveSteps[source], source);
        }

        function atRemoveStep(index, source) {
            atReadStepsFromUI(source);
            atEmbedActiveSteps[source].splice(index, 1);
            atRenderCleanSteps(atEmbedActiveSteps[source], source);
        }

        async function atSaveCurrentProfile(source) {
            const steps = atReadStepsFromUI(source);
            const name = atGetCurrentProfileName(source);
            if (!name) { showToast('프로필을 먼저 선택하거나 새로 만드세요', 'warning'); return; }
            const profileType = atGetCurrentProfileType(source);
            try {
                const resp = await fetch('/api/asset_tool/embedding_profile_save', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ name, steps, profile_type: profileType })
                });
                const result = await resp.json();
                if (result.success) {
                    showToast(`프로필 '${name}' 저장됨`, 'success');
                    await atLoadProfiles();
                    atLoadCacheStatus();
                    atPreviewClean(source);
                    // 같은 프로필을 쓰는 다른 쪽도 동기화
                    const otherSource = source === 'preset' ? 'tag' : 'preset';
                    const otherName = atGetCurrentProfileName(otherSource);
                    if (otherName === name) {
                        atEmbedActiveSteps[otherSource] = JSON.parse(JSON.stringify(steps));
                        atRenderCleanSteps(atEmbedActiveSteps[otherSource], otherSource);
                    }
                } else {
                    showToast('저장 실패: ' + (result.error || ''), 'error');
                }
            } catch (e) {
                showToast('저장 오류: ' + e.message, 'error');
            }
        }

        async function atNewProfile(source) {
            const name = prompt('새 프로필 이름을 입력하세요:');
            if (!name || !name.trim()) return;
            const trimmedName = name.trim();
            atReadStepsFromUI(source);
            atEmbedProfiles[trimmedName] = JSON.parse(JSON.stringify(atEmbedActiveSteps[source]));
            try {
                const profileType = atGetCurrentProfileType(source);
                const resp = await fetch('/api/asset_tool/embedding_profile_save', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ name: trimmedName, steps: atEmbedProfiles[trimmedName], profile_type: profileType })
                });
                const result = await resp.json();
                if (!result.success) {
                    showToast('프로필 저장 실패: ' + (result.error || ''), 'error');
                    return;
                }
                showToast(`프로필 '${trimmedName}' 생성됨`, 'success');
                await atLoadProfiles();
                const selId = source === 'tag' ? 'at-embed-profile-select-tag' : 'at-embed-profile-select-preset';
                const sel = document.getElementById(selId);
                if (sel) sel.value = trimmedName;
                atRenderCleanSteps(atEmbedProfiles[trimmedName] || [], source);
            } catch (e) {
                showToast('프로필 생성 오류: ' + e.message, 'error');
            }
        }

        async function atDeleteProfile(source) {
            const name = atGetCurrentProfileName(source);
            if (!name) return;
            if (!confirm(`프로필 '${name}'을 삭제하시겠습니까?`)) return;
            try {
                const resp = await fetch('/api/asset_tool/embedding_profile_delete', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ name })
                });
                const result = await resp.json();
                if (result.success) {
                    showToast(`프로필 '${name}' 삭제됨`, 'success');
                    await atLoadProfiles();
                } else {
                    showToast('삭제 실패: ' + (result.error || ''), 'error');
                }
            } catch (e) {
                showToast('삭제 오류: ' + e.message, 'error');
            }
        }

        async function atApplyProfile() {
            const name = atGetCurrentProfileName();
            const profileType = atGetCurrentProfileType();
            if (!name) return;
            try {
                const resp = await fetch('/api/asset_tool/embedding_profile_apply', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ name, profile_type: profileType })
                });
                const result = await resp.json();
                if (result.success) {
                    showToast(`프로필 '${name}' 적용됨`, 'success');
                    atLoadCacheStatus();
                } else {
                    showToast('적용 실패: ' + (result.error || ''), 'error');
                }
            } catch (e) {
                showToast('적용 오류: ' + e.message, 'error');
            }
        }

        function atResetCurrentProfile(source) {
            const defaults = {
                preset: [
                    { action: 'split_by', separator: '/', take: -1 },
                    { action: 'strip_suffix', pattern: '_v\\d+$' },
                    { action: 'replace', from: '_', to: ' ' }
                ],
                tag: [
                    { action: 'strip_suffix', pattern: '\\.(webp|png|jpg|jpeg|gif|bmp)$' },
                    { action: 'split_by', separator: '_', take: '1:' },
                    { action: 'replace', from: '_', to: ' ' }
                ]
            };
            const steps = (source === 'tag' ? defaults.tag : defaults.preset);
            atEmbedActiveSteps[source] = JSON.parse(JSON.stringify(steps));
            atRenderCleanSteps(atEmbedActiveSteps[source], source);
            showToast('기본값으로 초기화되었습니다', 'info');
        }

        let atPresetProfileMap = {};

        async function atPreviewClean(source) {
            if (!source) source = 'preset';
            atEmbedCurrentSource = source;
            const previewDiv = document.getElementById('at-embed-preview');
            document.getElementById('at-preview-preset-btn').classList.toggle('at-btn-primary', source === 'preset');
            // 태그 미리보기는 업로드 모달(atEmotionUpdatePreview)로 이관되어 이 버튼은 없을 수 있음
            const tagBtn = document.getElementById('at-preview-tag-btn');
            if (tagBtn) tagBtn.classList.toggle('at-btn-primary', source === 'tag');
            previewDiv.innerHTML = '<div style="color:var(--text2); font-size:0.85rem;">로딩 중...</div>';
            try {
                let resp;
                if (source === 'tag') {
                    const tagNames = atState.images.map(img => img.file ? img.file.name : '').filter(n => n);
                    if (tagNames.length === 0) {
                        previewDiv.innerHTML = '<div style="color:var(--text2); font-size:0.85rem;">업로드된 이미지가 없습니다. 먼저 이미지를 업로드하세요.</div>';
                        return;
                    }
                    resp = await fetch('/api/asset_tool/embedding_preview', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ category: 'expressions', source: 'tag', names: tagNames })
                    });
                } else {
                    resp = await fetch('/api/asset_tool/embedding_preview?category=expressions&source=preset');
                }
                const result = await resp.json();
                if (!result.success) {
                    previewDiv.innerHTML = `<div style="color:var(--error); font-size:0.85rem;">오류: ${escapeHtml(result.error || '')}</div>`;
                    return;
                }
                const preview = result.preview || [];
                const profiles = result.profiles || {};
                const profileMap = result.preset_profile_map || {};
                atPresetProfileMap = JSON.parse(JSON.stringify(profileMap));
                atEmbedProfiles = profiles;
                window._atTagPreview = preview;

                if (result.active_preset_profile !== undefined) {
                    atRenderProfileSelect(result.active_preset_profile);
                }

                if (preview.length === 0) {
                    const emptyMsg = source === 'tag'
                        ? '업로드된 이미지 파일명에 정제할 이름이 없습니다.'
                        : '해당 카테고리에 프리셋이 없습니다.';
                    previewDiv.innerHTML = `<div style="color:var(--text2); font-size:0.85rem;">${emptyMsg}</div>`;
                    return;
                }
                const profileNames = Object.keys(profiles);
                let html = '<table style="width:100%; border-collapse:collapse; font-size:0.82rem;">';
                html += '<thead><tr style="border-bottom:2px solid var(--border);">';
                html += '<th style="text-align:left; padding:6px 8px; color:var(--text2); width:40%;">원본</th>';
                html += '<th style="text-align:left; padding:4px 6px; color:var(--text2); width:30%;">적용 프로필</th>';
                html += '<th style="text-align:left; padding:6px 8px; color:var(--text2); width:30%;">정제 후</th>';
                html += '</tr></thead><tbody>';
                preview.forEach(item => {
                    const changed = item.original !== item.cleaned;
                    const selectedProfile = profileMap[item.original] || '';
                    html += `<tr style="border-bottom:1px solid var(--border);">`;
                    html += `<td style="padding:5px 8px; ${changed ? '' : 'color:var(--text2);'}">${escapeHtml(item.original)}</td>`;
                    html += `<td style="padding:4px 6px;">`;
                    html += `<select data-preset-name="${escapeHtml(item.original)}" style="font-size:0.78rem; padding:2px 4px; border-radius:4px; border:1px solid var(--border); background:var(--surface2); color:var(--text); width:100%;" onchange="atOnProfileMapChange(this.dataset.presetName, this.value)">`;
                    html += `<option value="">현재 프로필</option>`;
                    profileNames.forEach(pn => {
                        const sel = pn === selectedProfile ? 'selected' : '';
                        html += `<option value="${escapeHtml(pn)}" ${sel}>${escapeHtml(pn)}</option>`;
                    });
                    html += `</select></td>`;
                    html += `<td style="padding:5px 8px; color:var(--accent);">${escapeHtml(item.cleaned || '(빈 값)')}</td>`;
                    html += '</tr>';
                });
                html += '</tbody></table>';
                const cacheInfo = result.cache_info || {};
                const cacheStatus = cacheInfo.valid ? `✅ 유효 (${cacheInfo.cached_embeddings || 0}개 캐시됨)` : '❌ 설정 변경으로 무효화됨';
                html += `<div style="margin-top:8px; display:flex; align-items:center; gap:8px;">`;
                html += `<span style="font-size:0.78rem; color:var(--text2);">캐시 상태: ${cacheStatus}</span>`;
                html += `</div>`;
                const saveBtn = document.getElementById('at-save-profile-map-btn');
                if (saveBtn) saveBtn.style.display = source === 'preset' ? '' : 'none';
                previewDiv.innerHTML = html;
                if (source === 'tag') atTagPreviewDone = true;
            } catch (e) {
                previewDiv.innerHTML = `<div style="color:var(--error); font-size:0.85rem;">로드 오류: ${escapeHtml(e.message)}</div>`;
                if (source === 'tag') atTagPreviewDone = false;
            }
            atCheckReadyStates();
        }

        function atOnProfileMapChange(presetName, profileName) {
            if (profileName) {
                atPresetProfileMap[presetName] = profileName;
            } else {
                delete atPresetProfileMap[presetName];
            }
            atRefreshPreviewCleanedNames();
        }

        async function atRefreshPreviewCleanedNames() {
            const previewDiv = document.getElementById('at-embed-preview');
            const table = previewDiv.querySelector('table');
            if (!table) return;
            try {
                const source = atEmbedCurrentSource || 'preset';
                let resp;
                if (source === 'tag') {
                    const tagNames = atState.images.map(img => img.file ? img.file.name : '').filter(n => n);
                    if (tagNames.length === 0) return;
                    resp = await fetch('/api/asset_tool/embedding_preview', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ category: 'expressions', source: 'tag', names: tagNames })
                    });
                } else {
                    resp = await fetch('/api/asset_tool/embedding_preview?category=expressions&source=preset');
                }
                const result = await resp.json();
                if (!result.success) return;
                const preview = result.preview || [];
                const profileMap = atPresetProfileMap;
                const rows = table.querySelectorAll('tbody tr');
                preview.forEach((item, i) => {
                    if (rows[i]) {
                        const cleanedTd = rows[i].querySelector('td:nth-child(3)');
                        if (cleanedTd) {
                            const changed = item.original !== item.cleaned;
                            const isMapped = profileMap[item.original];
                            cleanedTd.textContent = item.cleaned || '(빈 값)';
                            const origTd = rows[i].querySelector('td:nth-child(1)');
                            if (origTd) origTd.style.color = changed ? '' : 'var(--text2)';
                            if (cleanedTd) cleanedTd.style.color = isMapped ? '#ff9800' : 'var(--accent)';
                        }
                    }
                });
            } catch (e) { /* ignore */ }
        }

        async function atSaveProfileMap() {
            try {
                const resp = await fetch('/api/asset_tool/embedding_profile_map', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ preset_profile_map: atPresetProfileMap })
                });
                const result = await resp.json();
                if (result.success) {
                    showToast(`프리셋 프로필 할당 저장됨 (${result.count}개)`, 'success');
                } else {
                    showToast('저장 실패: ' + (result.error || ''), 'error');
                }
            } catch (e) {
                showToast('저장 오류: ' + e.message, 'error');
            }
            atCheckReadyStates();
        }

        async function atLoadCacheStatus() {
            const statusDiv = document.getElementById('at-embed-cache-status');
            try {
                const resp = await fetch('/api/asset_tool/embedding_cache_status');
                const result = await resp.json();
                if (result.success) {
                    if (result.valid) {
                        statusDiv.innerHTML = `✅ 캐시 유효 (<strong>${result.cached_embeddings}</strong>개 임베딩 저장됨)`;
                        statusDiv.style.color = 'var(--accent)';
                    } else {
                        statusDiv.innerHTML = '❌ 캐시 무효 (설정 변경됨, 재빌드 필요)';
                        statusDiv.style.color = 'var(--error)';
                    }
                } else {
                    statusDiv.innerHTML = '상태 확인 불가';
                    statusDiv.style.color = 'var(--text2)';
                }
            } catch (e) {
                statusDiv.innerHTML = '상태 확인 오류';
                statusDiv.style.color = 'var(--text2)';
            }
        }

        let atEmbedBuildRunning = false;
        async function atStartEmbeddingBuild(skipCached = false) {
            if (atEmbedBuildRunning) { showToast('이미 임베딩 빌드가 진행 중입니다', 'warning'); return; }
            atEmbedBuildRunning = true;
            const btn = document.getElementById('at-embed-build-btn');
            const incBtn = document.getElementById('at-embed-incremental-btn');
            const progressDiv = document.getElementById('at-embed-progress');
            const progressBar = document.getElementById('at-embed-progress-bar');
            const progressText = document.getElementById('at-embed-progress-text');
            btn.disabled = true;
            incBtn.disabled = true;
            const activeBtn = skipCached ? incBtn : btn;
            activeBtn.textContent = '⏳ 임베딩 중...';
            progressDiv.style.display = 'block';
            progressBar.style.width = '0%';
            progressText.textContent = '임베딩 시작 중...';
            try {
                const resp = await fetch('/api/asset_tool/embedding_start', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ skip_cached: skipCached }),
                });
                const result = await resp.json();
                if (result.success) {
                    progressBar.style.width = '100%';
                    progressBar.textContent = '';
                    const skipped = result.skipped || 0;
                    const msg = skipCached && skipped > 0
                        ? `완료! 신규 ${result.embedded_count - skipped}개 + 캐시 ${skipped}개 / 전체 ${result.total_names}개`
                        : `완료! ${result.embedded_count}/${result.total_names}개 임베딩 저장됨`;
                    progressText.textContent = msg;
                    showToast(skipCached ? `캐시없는것만 임베딩 완료 (캐시 ${skipped}개 스킵)` : `${result.embedded_count}개 임베딩 빌드 완료`, 'success');
                    atLoadCacheStatus();
                    atPreviewClean();
                } else {
                    progressText.textContent = '오류: ' + (result.error || '알 수 없는 오류');
                    showToast('임베딩 빌드 실패: ' + (result.error || ''), 'error');
                }
            } catch (e) {
                progressText.textContent = '오류: ' + e.message;
                showToast('임베딩 빌드 오류: ' + e.message, 'error');
            }
            btn.disabled = false;
            incBtn.disabled = false;
            btn.textContent = '▶ 전체 임베딩';
            incBtn.textContent = '⚡ 캐시없는것만 임베딩';
            atEmbedBuildRunning = false;
            atCheckReadyStates();
        }

        // ─── LoRA 매니징 ─────────────────────────────────────
        let loraCurrentCharacter = '';
        let loraCurrentEntry = '';
        let loraPickerTarget = 'training'; // 'training' or 'test'
        let loraPickerState = { level: 'characters', pickerCharacter: '', outfit: '', expression: '', selected: new Set(), scroll: {} };

        function _loraHideAll() {
            document.getElementById('lora-loading').style.display = 'none';
            document.getElementById('lora-entries-section').style.display = 'none';
            document.getElementById('lora-trained-section').style.display = 'none';
            document.getElementById('lora-representative').style.display = 'none';
            document.getElementById('lora-section-divider').style.display = 'none';
            document.getElementById('lora-training-section').style.display = 'none';
            document.getElementById('lora-test-section').style.display = 'none';
            document.getElementById('lora-entry-info').style.display = 'none';
            document.getElementById('lora-training-add-section').style.display = 'none';
            document.getElementById('lora-test-add-section').style.display = 'none';
            document.getElementById('asset-lora-refine-batch-section').style.display = 'none';
            document.getElementById('asset-lora-test-setup-section').style.display = 'none';
            document.getElementById('lora-training-config-section').style.display = 'none';
            document.getElementById('lora-training-export-section').style.display = 'none';
            document.getElementById('lora-delete-btn').style.display = 'none';
            document.getElementById('lora-duplicate-btn').style.display = 'none';
            document.getElementById('lora-project-add-btn').style.display = 'none';
        }

        async function initLoraTab() {
            closeTrainedSessionModal();
            loraCurrentEntry = '';
            loraCurrentCharacter = '';
            _loraHideAll();
            document.getElementById('lora-breadcrumb').innerHTML = '<span>로라매니징</span>';
            await loadLoraCharacterGrid();
        }

        // ─── Level 1: 전체 캐릭터 그리드 ─────────────────────────
        async function loadLoraCharacterGrid() {
            const loadingEl = document.getElementById('lora-loading');
            loadingEl.style.display = 'flex';
            try {
                const resp = await fetchJSON('/api/lora/characters');
                const section = document.getElementById('lora-entries-section');
                const grid = document.getElementById('lora-entry-grid');
                const emptyEl = document.getElementById('lora-entry-empty');

                section.style.display = '';
                if (!resp.success || !resp.characters || resp.characters.length === 0) {
                    grid.style.display = 'none';
                    emptyEl.style.display = '';
                    emptyEl.querySelector('p').textContent = '캐릭터가 없습니다. 에셋에서 캐릭터를 추가하세요.';
                    return;
                }
                emptyEl.style.display = 'none';
                grid.style.display = '';
                grid.innerHTML = resp.characters.map(name => `
                    <div class="asset-folder-card" onclick="enterLoraCharacter('${escapeHtml(name)}')">
                        <div class="folder-icon">📁</div>
                        <div class="folder-name">${escapeHtml(name)}</div>
                    </div>
                `).join('');
                loadingEl.style.display = 'none';
            } catch (e) {
                console.error('[LORA] 캐릭터 그리드 로드 실패:', e);
                loadingEl.style.display = 'none';
            }
        }

        // ─── Level 2: 캐릭터의 LoRA 항목 그리드 ─────────────────────────
        async function enterLoraCharacter(character) {
            loraCurrentCharacter = character;
            closeTrainedSessionModal();
            loraCurrentEntry = '';
            _loraHideAll();
            document.getElementById('lora-project-add-btn').style.display = '';
            const loadingEl = document.getElementById('lora-loading');
            loadingEl.style.display = 'flex';

            // breadcrumb
            document.getElementById('lora-breadcrumb').innerHTML =
                `<span style="cursor:pointer;" onclick="initLoraTab()">로라매니징</span> / <span>${escapeHtml(character)}</span>`;

            try {
                const enc = encodeURIComponent;
                const resp = await fetchJSON(`/api/lora/manage/list?character=${enc(character)}`);
                const section = document.getElementById('lora-entries-section');
                const grid = document.getElementById('lora-entry-grid');
                const emptyEl = document.getElementById('lora-entry-empty');

                section.style.display = '';
                if (!resp.success) { showToast(resp.error || '항목 로드 실패', 'error'); return; }
                const entries = resp.loras || [];
                if (entries.length === 0) {
                    grid.style.display = 'none';
                    emptyEl.style.display = '';
                    emptyEl.querySelector('p').textContent = 'LoRA 항목이 없습니다. 사이드바에서 추가하세요.';
                    return;
                }
                emptyEl.style.display = 'none';
                grid.style.display = '';
                grid.innerHTML = entries.map(e => {
                    const enc2 = encodeURIComponent;
                    let thumbSrc = '';
                    if (e.representative) {
                        try {
                            const rep = JSON.parse(e.representative);
                            thumbSrc = rep.preview || '';
                        } catch (_) {
                            thumbSrc = `/api/lora/entry_image/${enc2(character)}/${enc2(e.name)}/${enc2(e.representative)}`;
                        }
                    }
                    return `
                    <div class="asset-gallery-card" onclick="enterLoraEntry('${escapeHtml(e.name)}')">
                        ${thumbSrc
                            ? `<img class="gallery-thumb" src="${thumbSrc}" loading="lazy">`
                            : `<div class="gallery-thumb-placeholder" style="display:flex;align-items:center;justify-content:center;font-size:2.5rem;opacity:0.4;">📁</div>`
                        }
                        <div style="padding:10px;">
                            <div style="font-weight:600; font-size:0.9rem;">${escapeHtml(e.name)}</div>
                            ${e.trigger ? `<div style="font-size:0.75rem; color:var(--text-secondary); margin-top:2px;">${escapeHtml(e.trigger)}</div>` : ''}
                        </div>
                    </div>`;
                }).join('');
                loadingEl.style.display = 'none';
            } catch (e) {
                console.error('[LORA_MANAGE] 항목 그리드 로드 실패:', e);
                loadingEl.style.display = 'none';
            }
        }

        // ─── Level 3: LoRA 항목 상세 ─────────────────────────────────
        async function enterLoraEntry(name) {
            closeTrainedSessionModal();
            loraCurrentEntry = name;

            // breadcrumb
            document.getElementById('lora-breadcrumb').innerHTML =
                `<span style="cursor:pointer;" onclick="initLoraTab()">로라매니징</span> / <span style="cursor:pointer;" onclick="enterLoraCharacter('${escapeHtml(loraCurrentCharacter)}')">${escapeHtml(loraCurrentCharacter)}</span> / <span>${escapeHtml(name)}</span>`;

            _loraHideAll();
            const loadingEl = document.getElementById('lora-loading');
            loadingEl.style.display = 'flex';

            // 사이드바: 삭제/학습 표시
            document.getElementById('lora-delete-btn').style.display = '';
            document.getElementById('lora-duplicate-btn').style.display = '';
            document.getElementById('lora-training-add-section').style.display = '';
            document.getElementById('lora-test-add-section').style.display = '';
            document.getElementById('asset-lora-refine-batch-section').style.display = '';
            document.getElementById('asset-lora-test-setup-section').style.display = '';
            document.getElementById('lora-training-config-section').style.display = '';
            document.getElementById('lora-training-export-section').style.display = '';

            // 항목 정보 로드
            const enc = encodeURIComponent;
            try {
                const resp = await fetchJSON(`/api/lora/manage/list?character=${enc(loraCurrentCharacter)}`);
                if (resp.success) {
                    const entry = (resp.loras || []).find(l => l.name === name);
                    if (entry) {
                        document.getElementById('lora-entry-info-title').textContent = name;
                        document.getElementById('lora-entry-trigger').value = entry.trigger || '';
                        document.getElementById('lora-entry-description').value = entry.description || '';
                        document.getElementById('lora-entry-info').style.display = '';
                        loraEntryRepresentative = entry.representative || '';
                    }
                }
            } catch (e) { console.error('[LORA_MANAGE] 항목 정보 로드 실패:', e); }

            await Promise.all([loadLoraTrainingImages(), loadLoraTestImages(), loadLoraTrainingConfig(), loadTrainedLoraSessions()]);
            loadingEl.style.display = 'none';
        }

        // ─── 학습된 LoRA (lora_load_path) ─────────────────────────
        let loraCurrentTrainedSession = '';
        let loraCurrentTrainedStep = '';
        let loraEntryRepresentative = '';
        let _loraTrainedSessionRequestId = 0;
        let _loraTrainedStepRequestId = 0;

        // ─── 학습 세션 STEP 보기 모달 (세션 카드 클릭 → 모달화, 본문 노드 이동) ───
        // 이동한 노드들의 원래 위치를 기억해 닫을 때 복원한다.
        let _loraTrainedSessionMoved = []; // [{node, parent, next}]
        const _loraTrainedSessionBodyIds = ['lora-loss-chart-container', 'lora-trained-steps', 'lora-trained-previews', 'lora-trained-empty'];

        function _loraTrainedMoveTo(host, id) {
            const el = document.getElementById(id);
            if (!el) { console.warn('[LORA_SESSION_MODAL] 이동할 요소를 찾을 수 없음:', id); return; }
            _loraTrainedSessionMoved.push({ node: el, parent: el.parentElement, next: el.nextSibling });
            host.appendChild(el);
        }

        function _renderLoraTrainedSessionBreadcrumb(session, stepName = '') {
            const breadcrumb = document.getElementById('lora-trained-session-breadcrumb');
            if (!breadcrumb) {
                console.error('[LORA_SESSION_MODAL] 모달 breadcrumb 요소 없음');
                return;
            }
            const sessionSegment = stepName
                ? `<span style="cursor:pointer;" onclick="enterTrainedSession('${escapeHtml(session)}')">${escapeHtml(session)}</span> / <span>${escapeHtml(stepName)}</span>`
                : `<span>${escapeHtml(session)}</span>`;
            breadcrumb.innerHTML =
                `<span style="cursor:pointer;" onclick="initLoraTab()">로라매니징</span> / ` +
                `<span style="cursor:pointer;" onclick="enterLoraCharacter('${escapeHtml(loraCurrentCharacter)}')">${escapeHtml(loraCurrentCharacter)}</span> / ` +
                `<span style="cursor:pointer;" onclick="enterLoraEntry('${escapeHtml(loraCurrentEntry)}')">${escapeHtml(loraCurrentEntry)}</span> / ` +
                sessionSegment;
        }

        function _setLoraTrainedSessionBusy(isBusy) {
            const body = document.getElementById('lora-trained-session-body');
            if (!body) {
                console.error('[LORA_SESSION_MODAL] busy 상태를 적용할 본문 요소 없음:', isBusy);
                return;
            }
            if (isBusy) body.setAttribute('aria-busy', 'true');
            else body.removeAttribute('aria-busy');
        }

        function _resetLoraTrainedSessionContent() {
            if (window._loraLossChart) {
                window._loraLossChart.destroy();
                window._loraLossChart = null;
            }

            for (const id of _loraTrainedSessionBodyIds) {
                const el = document.getElementById(id);
                if (!el) {
                    console.error('[LORA_SESSION_MODAL] 초기화할 요소 없음:', id);
                    continue;
                }
                el.style.display = 'none';
            }

            const stepsEl = document.getElementById('lora-trained-steps');
            const previewsEl = document.getElementById('lora-trained-previews');
            const emptyEl = document.getElementById('lora-trained-empty');
            const lossCanvas = document.getElementById('lora-loss-chart');
            const lossNoData = document.getElementById('lora-loss-nodata');
            const tomlBtn = document.getElementById('lora-toml-preview-btn');
            if (stepsEl) stepsEl.innerHTML = '';
            else console.error('[LORA_SESSION_MODAL] STEP 목록 요소 없음');
            if (previewsEl) previewsEl.innerHTML = '';
            else console.error('[LORA_SESSION_MODAL] 프리뷰 목록 요소 없음');
            if (emptyEl) emptyEl.textContent = '학습된 LoRA가 없습니다.';
            else console.error('[LORA_SESSION_MODAL] 빈 상태 요소 없음');
            if (lossCanvas) lossCanvas.style.display = 'none';
            else console.error('[LORA_SESSION_MODAL] Loss canvas 요소 없음');
            if (lossNoData) lossNoData.style.display = 'none';
            else console.error('[LORA_SESSION_MODAL] Loss 빈 상태 요소 없음');
            if (tomlBtn) tomlBtn.style.display = 'none';
            else console.error('[LORA_SESSION_MODAL] TOML 버튼 요소 없음');
        }

        function _isLoraTrainedSessionRequestCurrent(requestId, session) {
            const modal = document.getElementById('lora-trained-session-modal');
            return requestId === _loraTrainedSessionRequestId
                && loraCurrentTrainedSession === session
                && !!modal
                && modal.classList.contains('visible');
        }

        function _isLoraTrainedStepRequestCurrent(requestId, session, stepName) {
            return requestId === _loraTrainedStepRequestId
                && loraCurrentTrainedSession === session
                && loraCurrentTrainedStep === stepName
                && _isLoraTrainedSessionRequestCurrent(_loraTrainedSessionRequestId, session);
        }

        // 세션 STEP 보기 모달을 연다. 페이지 breadcrumb는 고정하고 본문 노드만 모달로 이동한다.
        // 이미 열려 있으면(재진입) 노드 이동은 생략 — breadcrumb와 데이터만 다시 갱신한다.
        function openTrainedSessionModal(session) {
            const modal = document.getElementById('lora-trained-session-modal');
            if (!modal) { console.error('[LORA_SESSION_MODAL] 모달 요소 없음'); return false; }

            if (_loraTrainedSessionMoved.length === 0) {
                const bodyHost = document.getElementById('lora-trained-session-body');
                if (!bodyHost) { console.error('[LORA_SESSION_MODAL] 본문 호스트 없음'); return false; }
                for (const id of _loraTrainedSessionBodyIds) _loraTrainedMoveTo(bodyHost, id);
            }

            _resetLoraTrainedSessionContent();
            const sessionsEl = document.getElementById('lora-trained-sessions');
            const repEl = document.getElementById('lora-representative');
            if (sessionsEl) sessionsEl.style.display = 'none';
            else console.error('[LORA_SESSION_MODAL] 숨길 세션 폴더 목록 요소 없음');
            if (repEl) repEl.style.display = 'none';
            else console.error('[LORA_SESSION_MODAL] 숨길 대표 LoRA 요소 없음');
            _renderLoraTrainedSessionBreadcrumb(session);
            _setLoraTrainedSessionBusy(true);
            modal.classList.add('visible');
            return true;
        }

        function closeTrainedSessionModal() {
            _loraTrainedSessionRequestId += 1;
            _loraTrainedStepRequestId += 1;
            const modal = document.getElementById('lora-trained-session-modal');
            if (_loraTrainedSessionMoved.length === 0) {
                if (modal) modal.classList.remove('visible');
                return;
            }
            _setLoraTrainedSessionBusy(false);
            _resetLoraTrainedSessionContent();
            // 노드들을 원래 부모/순서로 복원
            for (const { node, parent, next } of _loraTrainedSessionMoved) {
                if (!parent) continue;
                try {
                    if (next && next.parentNode === parent) parent.insertBefore(node, next);
                    else parent.appendChild(node);
                } catch (e) {
                    console.error('[LORA_SESSION_MODAL] 노드 복원 실패:', node && node.id, e);
                    try { parent.appendChild(node); } catch (_) {}
                }
                node.style.display = 'none';
            }
            _loraTrainedSessionMoved = [];
            if (modal) modal.classList.remove('visible');

            // 상태 정리 — 세션 목록(엔트리 상세)으로 복귀
            loraCurrentTrainedSession = '';
            loraCurrentTrainedStep = '';
            // breadcrumb 를 엔트리 단계로 복원
            document.getElementById('lora-breadcrumb').innerHTML =
                `<span style="cursor:pointer;" onclick="initLoraTab()">로라매니징</span> / ` +
                `<span style="cursor:pointer;" onclick="enterLoraCharacter('${escapeHtml(loraCurrentCharacter)}')">${escapeHtml(loraCurrentCharacter)}</span> / ` +
                `<span>${escapeHtml(loraCurrentEntry)}</span>`;
            // 세션 목록 + (있던) 대표 표시 복원
            const sessionsEl = document.getElementById('lora-trained-sessions');
            if (sessionsEl) sessionsEl.style.display = '';
            const repEl = document.getElementById('lora-representative');
            if (repEl && repEl.innerHTML.trim()) repEl.style.display = '';
        }

        // ✕ 버튼용: 모달을 닫고 세션 목록 카드를 새로고침한다.
        // 모달 안에서 세션 대표 설정/step 삭제 등 변경된 내용을 카드에 반영하기 위함.
        async function closeTrainedSessionModalAndRefresh() {
            const entry = loraCurrentEntry;
            closeTrainedSessionModal();
            if (entry) {
                try { await loadTrainedLoraSessions(); }
                catch (e) { console.error('[LORA_SESSION_MODAL] 세션 목록 새로고침 실패:', e); }
            }
        }

        async function loadTrainedLoraSessions() {
            const section = document.getElementById('lora-trained-section');
            const sessionsEl = document.getElementById('lora-trained-sessions');
            const stepsEl = document.getElementById('lora-trained-steps');
            const previewsEl = document.getElementById('lora-trained-previews');
            const emptyEl = document.getElementById('lora-trained-empty');

            section.style.display = '';
            document.getElementById('lora-section-divider').style.display = '';

            sessionsEl.style.display = 'none';
            stepsEl.style.display = 'none';
            previewsEl.style.display = 'none';
            emptyEl.style.display = 'none';

            // 엔트리 레벨에서는 Loss 차트 숨김
            if (window._loraLossChart) { window._loraLossChart.destroy(); window._loraLossChart = null; }
            document.getElementById('lora-loss-chart-container').style.display = 'none';
            document.getElementById('lora-loss-nodata').style.display = 'none';

            loraCurrentTrainedSession = '';

            try {
                const enc = encodeURIComponent;
                const resp = await fetchJSON(`/api/lora/trained/sessions?character=${enc(loraCurrentCharacter)}&entry=${enc(loraCurrentEntry)}`);
                if (!resp.success) {
                    if (resp.error) showToast(resp.error, 'error');
                    emptyEl.style.display = '';
                    return;
                }
                const sessions = resp.sessions || [];
                if (sessions.length === 0) {
                    emptyEl.style.display = '';
                    return;
                }
                sessionsEl.style.display = '';
                // 대표 LoRA 이미지 표시
                const repEl = document.getElementById('lora-representative');
                if (loraEntryRepresentative) {
                    try {
                        const rep = JSON.parse(loraEntryRepresentative);
                        const repImg = rep.preview || '';
                        const repFile = rep.safetensors || '';
                        if (repImg) {
                            repEl.style.display = '';
                            repEl.innerHTML = `
                                <div style="display:flex; align-items:center; gap:12px; padding:12px; background:var(--surface); border:2px solid var(--accent); border-radius:10px;">
                                    <img src="${repImg}" style="width:80px; height:80px; object-fit:cover; border-radius:8px;">
                                    <div>
                                        <div style="font-size:0.75rem; font-weight:700; color:var(--accent); margin-bottom:4px;">현재 엔트리 대표</div>
                                        <div style="font-size:0.8rem; color:var(--text-secondary); word-break:break-all;">${escapeHtml(repFile.split(/[\\/]/).pop() || '')}</div>
                                    </div>
                                </div>`;
                        } else {
                            repEl.style.display = 'none';
                        }
                    } catch (_) { repEl.style.display = 'none'; }
                } else {
                    repEl.style.display = 'none';
                }
                // 대표 이미지가 속한 세션 찾기
                let repPreviewUrl = '';
                let repSessionName = '';
                if (loraEntryRepresentative) {
                    try {
                        const rep = JSON.parse(loraEntryRepresentative);
                        repPreviewUrl = rep.preview || '';
                    } catch (_) {}
                }
                // preview URL에서 세션명 추출: /api/lora/trained/preview/char/entry/SESSION/file
                if (repPreviewUrl) {
                    const parts = repPreviewUrl.split('/');
                    const si = parts.indexOf('preview');
                    if (si >= 0 && parts.length > si + 3) repSessionName = decodeURIComponent(parts[si + 3]);
                }
                sessionsEl.innerHTML = `<div style="display:grid; grid-template-columns:repeat(auto-fill, minmax(320px, 1fr)); gap:12px;">` +
                    sessions.map(s => {
                        const isRep = s.name === repSessionName;
                        const sessionPreview = s.preview_url || '';
                        const hasSessionRep = !!sessionPreview;
                        return `
                        <div onclick="enterTrainedSession('${escapeHtml(s.name)}')"
                             style="background:var(--surface); border:1px solid ${isRep ? 'var(--accent)' : 'var(--border)'}; border-radius:10px; padding:16px; cursor:pointer; transition:border-color 0.2s; position:relative;"
                             onmouseover="this.style.borderColor='var(--accent)'" onmouseout="this.style.borderColor='${isRep ? 'var(--accent)' : 'var(--border)'}'">
                            <button onclick="event.stopPropagation(); deleteTrainedSession('${escapeHtml(s.name)}')"
                                    style="position:absolute; top:8px; right:8px; background:rgba(220,53,69,0.85); color:#fff; border:none; border-radius:6px; padding:4px 10px; font-size:0.75rem; cursor:pointer; opacity:0; transition:opacity 0.2s;"
                                    onmouseover="this.style.opacity='1'" onmouseout="this.style.opacity='0'"
                                    class="trained-delete-btn">폴더 삭제</button>
                            ${sessionPreview ? `<img src="${sessionPreview}" style="width:100%; border-radius:8px; margin-bottom:10px; display:block;">` : ''}
                            ${hasSessionRep ? '<div style="position:absolute; top:8px; left:8px; z-index:50; background:rgba(255,193,7,0.95); color:#000; font-size:0.7rem; font-weight:700; padding:3px 8px; border-radius:4px;">세션 대표</div>' : ''}
                            <div style="font-weight:600; font-size:0.95rem;">${escapeHtml(s.name)}</div>
                            <div style="font-size:0.8rem; color:var(--text-secondary); margin-top:6px;">
                                ${s.step_count}개 파일${s.has_final ? ' (최종 포함)' : ''}
                                ${!hasSessionRep ? ' <span style="color:var(--warning);">(세션 대표 미설정)</span>' : ''}
                            </div>
                            ${hasSessionRep ? `
                            <button onclick="event.stopPropagation(); setEntryRepFromSession('${escapeHtml(s.name)}')"
                                    style="margin-top:8px; background:${isRep ? 'var(--accent)' : 'var(--surface2)'}; color:${isRep ? '#fff' : 'var(--text)'}; border:1px solid ${isRep ? 'var(--accent)' : 'var(--border)'}; border-radius:6px; padding:4px 10px; font-size:0.75rem; cursor:pointer; width:100%; transition:background 0.2s;"
                                    ${isRep ? 'disabled' : ''}>
                                ${isRep ? '현재 엔트리 대표' : '엔트리 대표로 설정'}
                            </button>` : ''}
                            <button onclick="event.stopPropagation(); removeNonSessionRepAssets('${escapeHtml(s.name)}', ${s.step_count})"
                                    style="margin-top:4px; background:var(--surface2); color:var(--text); border:1px solid var(--border); border-radius:6px; padding:4px 10px; font-size:0.75rem; cursor:pointer; width:100%;"
                                    title="이 세션의 대표 step만 남기고 나머지를 삭제합니다">
                                세션 대표 외 제거
                            </button>
                        </div>`;
                    }).join('') + '</div>';
            } catch (e) {
                console.error('[LORA_TRAINED] 세션 로드 실패:', e);
                emptyEl.style.display = '';
            }
        }

        async function enterTrainedSession(session) {
            const requestId = ++_loraTrainedSessionRequestId;
            _loraTrainedStepRequestId += 1;
            loraCurrentTrainedSession = session;

            // 페이지 로딩 표시는 사용하지 않는다. 모달 본문을 비운 뒤 데이터가 완성되면 한 번에 표시한다.
            if (!openTrainedSessionModal(session)) {
                console.error('[LORA_TRAINED] 세션 모달 열기 실패:', {
                    character: loraCurrentCharacter,
                    entry: loraCurrentEntry,
                    session,
                });
                return;
            }

            const stepsEl = document.getElementById('lora-trained-steps');
            const emptyEl = document.getElementById('lora-trained-empty');
            const lossChartEl = document.getElementById('lora-loss-chart-container');
            if (!stepsEl || !emptyEl || !lossChartEl) {
                console.error('[LORA_TRAINED] 세션 렌더링 요소 누락:', {
                    steps: !!stepsEl,
                    empty: !!emptyEl,
                    lossChart: !!lossChartEl,
                    session,
                });
                _setLoraTrainedSessionBusy(false);
                return;
            }

            try {
                const enc = encodeURIComponent;
                const resp = await fetchJSON(`/api/lora/trained/steps?character=${enc(loraCurrentCharacter)}&entry=${enc(loraCurrentEntry)}&session=${enc(session)}`);
                if (!_isLoraTrainedSessionRequestCurrent(requestId, session)) {
                    console.info('[LORA_TRAINED] 만료된 세션 STEP 응답 무시:', {
                        requestId,
                        currentRequestId: _loraTrainedSessionRequestId,
                        session,
                        currentSession: loraCurrentTrainedSession,
                    });
                    return;
                }
                if (!resp.success) {
                    console.error('[LORA_TRAINED] 세션 STEP API 실패:', {
                        character: loraCurrentCharacter,
                        entry: loraCurrentEntry,
                        session,
                        response: resp,
                    });
                    showToast(resp.error || 'step 로드 실패', 'error');
                    emptyEl.textContent = resp.error || 'step 로드에 실패했습니다.';
                    emptyEl.style.display = '';
                    return;
                }
                const steps = resp.steps || [];
                if (steps.length === 0) {
                    console.warn('[LORA_TRAINED] 세션 STEP 파일 없음:', {
                        character: loraCurrentCharacter,
                        entry: loraCurrentEntry,
                        session,
                    });
                    emptyEl.style.display = '';
                    emptyEl.textContent = 'step 파일이 없습니다.';
                    return;
                }

                // 대표 safetensors 파일명 추출
                let repSafetensors = '';
                if (loraEntryRepresentative) {
                    try { repSafetensors = JSON.parse(loraEntryRepresentative).safetensors || ''; }
                    catch (e) {
                        console.error('[LORA_TRAINED] 엔트리 대표 정보 파싱 실패:', {
                            session,
                            representative: loraEntryRepresentative,
                            error: e,
                        });
                    }
                }

                // 세션 대표 정보까지 로드된 뒤에만 STEP/Loss를 표시한다.
                let sessionRepSafetensors = '';
                try {
                    const sessResp = await fetchJSON(`/api/lora/trained/sessions?character=${enc(loraCurrentCharacter)}&entry=${enc(loraCurrentEntry)}`);
                    if (!_isLoraTrainedSessionRequestCurrent(requestId, session)) {
                        console.info('[LORA_TRAINED] 만료된 세션 대표 응답 무시:', {
                            requestId,
                            currentRequestId: _loraTrainedSessionRequestId,
                            session,
                            currentSession: loraCurrentTrainedSession,
                        });
                        return;
                    }
                    if (sessResp.success) {
                        const sess = (sessResp.sessions || []).find(x => x.name === session);
                        if (sess && sess.representative) {
                            try {
                                sessionRepSafetensors = JSON.parse(sess.representative).safetensors || '';
                            } catch (e) {
                                console.error('[LORA_TRAINED] 세션 대표 정보 파싱 실패:', {
                                    session,
                                    representative: sess.representative,
                                    error: e,
                                });
                            }
                        }
                    } else {
                        console.error('[LORA_TRAINED] 세션 대표 API 실패:', {
                            character: loraCurrentCharacter,
                            entry: loraCurrentEntry,
                            session,
                            response: sessResp,
                        });
                    }
                } catch (e) {
                    console.error('[LORA_TRAINED] 세션 대표 조회 실패:', {
                        character: loraCurrentCharacter,
                        entry: loraCurrentEntry,
                        session,
                        error: e,
                    });
                }

                if (!_isLoraTrainedSessionRequestCurrent(requestId, session)) {
                    console.info('[LORA_TRAINED] 렌더링 전 만료된 세션 요청 무시:', {
                        requestId,
                        currentRequestId: _loraTrainedSessionRequestId,
                        session,
                        currentSession: loraCurrentTrainedSession,
                    });
                    return;
                }

                // Loss 차트 렌더링 (avr_loss가 있는 경우)
                const lossSteps = steps.filter(s => s.avr_loss != null);
                const lossCanvas = document.getElementById('lora-loss-chart');
                const lossNoData = document.getElementById('lora-loss-nodata');
                if (!lossCanvas || !lossNoData) {
                    console.error('[LORA_TRAINED] Loss 렌더링 요소 누락:', {
                        canvas: !!lossCanvas,
                        noData: !!lossNoData,
                        session,
                    });
                    throw new Error('Loss 렌더링 요소가 없습니다.');
                }
                if (lossSteps.length >= 2) {
                    const labels = lossSteps.map(s => {
                        const m = s.name.match(/step(\d+)/);
                        return m ? parseInt(m[1], 10) : s.name;
                    });
                    const losses = lossSteps.map(s => s.avr_loss);
                    const ctx = lossCanvas.getContext('2d');
                    lossCanvas.style.display = '';
                    lossNoData.style.display = 'none';
                    window._loraLossChart = new Chart(ctx, {
                        type: 'line',
                        data: {
                            labels: labels,
                            datasets: [{
                                label: 'avr_loss',
                                data: losses,
                                borderColor: 'rgba(0,120,215,0.9)',
                                backgroundColor: 'rgba(0,120,215,0.15)',
                                fill: true,
                                tension: 0.3,
                                pointRadius: 3,
                                pointHoverRadius: 5,
                            }]
                        },
                        options: {
                            responsive: true,
                            maintainAspectRatio: false,
                            plugins: {
                                legend: { display: false },
                                tooltip: {
                                    callbacks: {
                                        title: (items) => 'step ' + items[0].label,
                                        label: (item) => 'loss: ' + item.formattedValue,
                                    }
                                }
                            },
                            scales: {
                                x: {
                                    title: { display: true, text: 'step', color: 'var(--text-secondary)' },
                                    ticks: { color: 'var(--text-secondary)' },
                                    grid: { color: 'rgba(128,128,128,0.15)' }
                                },
                                y: {
                                    title: { display: true, text: 'loss', color: 'var(--text-secondary)' },
                                    ticks: { color: 'var(--text-secondary)' },
                                    grid: { color: 'rgba(128,128,128,0.15)' }
                                }
                            }
                        }
                    });
                    lossChartEl.style.display = '';
                } else {
                    lossCanvas.style.display = 'none';
                    lossNoData.style.display = '';
                    lossChartEl.style.display = '';
                }
                // TOML 미리보기 버튼: step이 있으면 표시
                const tomlBtn = document.getElementById('lora-toml-preview-btn');
                if (tomlBtn) tomlBtn.style.display = '';
                else console.error('[LORA_TRAINED] TOML 버튼 요소 없음:', { session });
                stepsEl.innerHTML = `<div style="margin-bottom:10px; font-size:0.82rem; color:var(--text-secondary);">step 파일을 클릭하면 프리뷰 이미지를 볼 수 있습니다.</div>` +
                    `<div style="display:grid; grid-template-columns:repeat(auto-fill, minmax(340px, 1fr)); gap:12px;">` +
                    steps.map(s => {
                        const previewUrl = s.previews.length > 0
                            ? `/api/lora/trained/preview/${enc(loraCurrentCharacter)}/${enc(loraCurrentEntry)}/${enc(session)}/${enc(s.previews[0])}`
                            : '';
                        const isRep = s.safetensors === repSafetensors;
                        const isSessionRep = s.safetensors === sessionRepSafetensors;
                        let badges = '';
                        if (isRep) badges += '<div style="position:absolute; top:8px; left:8px; z-index:50; background:rgba(0,120,215,0.95); color:#fff; font-size:0.7rem; font-weight:700; padding:3px 8px; border-radius:4px;">엔트리 대표</div>';
                        if (isSessionRep) badges += `<div style="position:absolute; top:8px; left:${isRep ? '110px' : '8px'}; z-index:50; background:rgba(255,193,7,0.95); color:#000; font-size:0.7rem; font-weight:700; padding:3px 8px; border-radius:4px;">세션 대표</div>`;
                        return `
                        <div data-step-name="${escapeHtml(s.name)}" style="background:var(--surface); border:1px solid ${isRep ? 'var(--accent)' : (isSessionRep ? 'rgba(255,193,7,0.6)' : 'var(--border)')}; border-radius:10px; padding:12px; transition:border-color 0.2s; position:relative;"
                             onmouseover="this.style.borderColor='var(--accent)'" onmouseout="this.style.borderColor='${isRep ? 'var(--accent)' : (isSessionRep ? 'rgba(255,193,7,0.6)' : 'var(--border)')}'">
                            ${badges}
                            <div onclick="enterTrainedStep('${escapeHtml(s.name)}')" style="cursor:pointer;">
                                ${previewUrl ? `<img src="${previewUrl}" style="width:100%; border-radius:8px; margin-bottom:10px;">` : ''}
                                <div style="font-weight:600; font-size:0.9rem;">${escapeHtml(s.name)}</div>
                                <div style="font-size:0.78rem; color:var(--text-secondary); margin-top:4px;">
                                    프리뷰 ${s.previews.length}장${s.avr_loss != null ? ` · loss ${Number(s.avr_loss).toFixed(5)}` : ''}
                                </div>
                            </div>
                            <button onclick="event.stopPropagation(); deleteTrainedStep('${escapeHtml(s.name)}')"
                                    style="position:absolute; top:8px; right:8px; background:rgba(220,53,69,0.85); color:#fff; border:none; border-radius:6px; padding:4px 10px; font-size:0.75rem; cursor:pointer; opacity:0; transition:opacity 0.2s;"
                                    onmouseover="this.style.opacity='1'" onmouseout="this.style.opacity='0'"
                                    class="trained-delete-btn">삭제</button>
                        </div>`;
                    }).join('') + '</div>';
                stepsEl.style.display = '';
            } catch (e) {
                console.error('[LORA_TRAINED] step 로드 실패:', e);
                if (_isLoraTrainedSessionRequestCurrent(requestId, session)) {
                    _resetLoraTrainedSessionContent();
                    showToast('step 로드 실패', 'error');
                    emptyEl.textContent = 'step 로드에 실패했습니다.';
                    emptyEl.style.display = '';
                }
            } finally {
                if (_isLoraTrainedSessionRequestCurrent(requestId, session)) {
                    _setLoraTrainedSessionBusy(false);
                }
            }
        }

        async function setTrainedRepresentative(safetensorsPath, previewUrl) {
            if (!confirm('이 이미지와 LoRA를 대표로 설정하시겠습니까?')) return;
            try {
                const repValue = JSON.stringify({ safetensors: safetensorsPath, preview: previewUrl });
                const resp = await fetchJSON('/api/lora/manage/update', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        name: loraCurrentEntry,
                        character: loraCurrentCharacter,
                        representative: repValue,
                    }),
                });
                if (resp.success) {
                    loraEntryRepresentative = repValue;
                    showToast('대표 LoRA로 설정되었습니다', 'success');
                    await enterTrainedSession(loraCurrentTrainedSession);
                    if (loraCurrentTrainedStep) enterTrainedStep(loraCurrentTrainedStep);
                } else {
                    showToast(resp.error || '설정 실패', 'error');
                }
            } catch (e) {
                console.error('[LORA_TRAINED] 대표 설정 실패:', e);
                showToast('대표 설정 실패', 'error');
            }
        }

        async function setSessionRepresentative(sessionName, safetensorsPath, previewUrl) {
            if (!confirm('이 이미지와 LoRA를 이 세션의 대표로 설정하시겠습니까?')) return;
            try {
                const repValue = JSON.stringify({ safetensors: safetensorsPath, preview: previewUrl });
                const resp = await fetchJSON('/api/lora/manage/update', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        name: loraCurrentEntry,
                        character: loraCurrentCharacter,
                        session_name: sessionName,
                        session_representative: repValue,
                    }),
                });
                if (resp.success) {
                    // 현재 세션이 엔트리 대표로 설정되어 있으면 엔트리 대표도 함께 업데이트
                    let isEntryRepSession = false;
                    try {
                        const rep = JSON.parse(loraEntryRepresentative);
                        const parts = (rep.preview || '').split('/');
                        const si = parts.indexOf('preview');
                        if (si >= 0 && parts.length > si + 3) {
                            isEntryRepSession = decodeURIComponent(parts[si + 3]) === sessionName;
                        }
                    } catch (_) {}
                    if (isEntryRepSession) {
                        const entryResp = await fetchJSON('/api/lora/manage/update', {
                            method: 'POST',
                            headers: {'Content-Type': 'application/json'},
                            body: JSON.stringify({
                                name: loraCurrentEntry,
                                character: loraCurrentCharacter,
                                representative: repValue,
                            }),
                        });
                        if (entryResp.success) loraEntryRepresentative = repValue;
                    }
                    showToast('세션 대표 LoRA로 설정되었습니다', 'success');
                    await enterTrainedSession(loraCurrentTrainedSession);
                    if (loraCurrentTrainedStep) enterTrainedStep(loraCurrentTrainedStep);
                } else {
                    showToast(resp.error || '설정 실패', 'error');
                }
            } catch (e) {
                console.error('[LORA_TRAINED] 세션 대표 설정 실패:', e);
                showToast('세션 대표 설정 실패', 'error');
            }
        }

        async function setEntryRepFromSession(sessionName) {
            try {
                // 세션 대표 데이터를 엔트리 대표로 복사
                const enc = encodeURIComponent;
                const resp = await fetchJSON(`/api/lora/trained/sessions?character=${enc(loraCurrentCharacter)}&entry=${enc(loraCurrentEntry)}`);
                if (!resp.success) { showToast('세션 정보 조회 실패', 'error'); return; }
                const session = (resp.sessions || []).find(s => s.name === sessionName);
                if (!session || !session.representative) { showToast('세션 대표가 설정되지 않았습니다', 'error'); return; }

                const updateResp = await fetchJSON('/api/lora/manage/update', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        name: loraCurrentEntry,
                        character: loraCurrentCharacter,
                        representative: session.representative,
                    }),
                });
                if (updateResp.success) {
                    loraEntryRepresentative = session.representative;
                    showToast('엔트리 대표로 설정되었습니다', 'success');
                    loadTrainedLoraSessions();
                } else {
                    showToast(updateResp.error || '설정 실패', 'error');
                }
            } catch (e) {
                console.error('[LORA_TRAINED] 엔트리 대표 설정 실패:', e);
                showToast('엔트리 대표 설정 실패', 'error');
            }
        }

        async function deleteTrainedStep(stepName) {
            if (!confirm(`"${stepName}"을(를) 삭제하시겠습니까?\n관련 safetensors, json, toml, 프리뷰 이미지가 모두 삭제됩니다.`)) return;
            const enc = encodeURIComponent;
            try {
                const resp = await fetchJSON('/api/lora/trained/delete', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        character: loraCurrentCharacter,
                        entry: loraCurrentEntry,
                        session: loraCurrentTrainedSession,
                        step: stepName,
                    }),
                });
                if (resp.success) {
                    showToast('삭제 완료', 'success');
                    enterTrainedSession(loraCurrentTrainedSession);
                } else {
                    showToast(resp.error || '삭제 실패', 'error');
                }
            } catch (e) {
                console.error('[LORA_TRAINED] 삭제 실패:', e);
                showToast('삭제 실패', 'error');
            }
        }

        async function deleteTrainedSession(sessionName) {
            if (!confirm(`세션 "${sessionName}" 폴더를 전체 삭제하시겠습니까?\n폴더 내 모든 파일이 삭제되며 복구할 수 없습니다.`)) return;
            try {
                const resp = await fetchJSON('/api/lora/trained/delete-session', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        character: loraCurrentCharacter,
                        entry: loraCurrentEntry,
                        session: sessionName,
                    }),
                });
                if (resp.success) {
                    showToast(`세션 삭제 완료 (${resp.file_count}개 파일)`, 'success');
                    loadTrainedLoraSessions();
                } else {
                    showToast(resp.error || '세션 삭제 실패', 'error');
                }
            } catch (e) {
                console.error('[LORA_TRAINED] 세션 삭제 실패:', e);
                showToast('세션 삭제 실패', 'error');
            }
        }

        async function removeNonSessionRepAssets(sessionName, stepCount) {
            const msg = stepCount && stepCount > 0
                ? `세션 "${sessionName}"에서 대표 step만 남기고 나머지 ${stepCount - 1}개 step을 삭제합니다.\n세션 대표가 없으면 모든 step이 삭제됩니다.\n복구할 수 없습니다. 계속하시겠습니까?`
                : `세션 "${sessionName}"의 대표 외 step을 삭제합니다.\n복구할 수 없습니다. 계속하시겠습니까?`;
            if (!confirm(msg)) return;
            try {
                const resp = await fetchJSON('/api/lora/trained/delete-non-rep', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        character: loraCurrentCharacter,
                        entry: loraCurrentEntry,
                        session: sessionName,
                    }),
                });
                if (resp.success) {
                    const kept = resp.kept ? `\n남긴 대표: ${resp.kept}` : (resp.had_rep ? '\n(대표 파일을 찾지 못해 남긴 파일 없음)' : '\n(세션 대표 미지정 - 전체 삭제)');
                    const errNote = resp.errors && resp.errors.length ? `\n일부 오류: ${resp.errors.length}건` : '';
                    showToast(`세션 대표 외 제거 완료 (${resp.deleted_count}개 step 삭제)${errNote}`, errNote ? 'warning' : 'success');
                    console.log(`[LORA_TRAINED] 세션 대표 외 제거: ${sessionName}${kept}${errNote}`, resp.errors);
                    loadTrainedLoraSessions();
                } else {
                    showToast(resp.error || '세션 대표 외 제거 실패', 'error');
                }
            } catch (e) {
                console.error('[LORA_TRAINED] 세션 대표 외 제거 실패:', e);
                showToast('세션 대표 외 제거 실패: ' + (e && e.message ? e.message : e), 'error');
            }
        }

        async function enterTrainedStep(stepName) {
            const session = loraCurrentTrainedSession;
            if (!session) {
                console.error('[LORA_TRAINED] STEP 진입 실패: 현재 세션이 비어 있음', {
                    character: loraCurrentCharacter,
                    entry: loraCurrentEntry,
                    stepName,
                });
                return;
            }
            const requestId = ++_loraTrainedStepRequestId;
            loraCurrentTrainedStep = stepName;
            if (!_isLoraTrainedStepRequestCurrent(requestId, session, stepName)) {
                console.error('[LORA_TRAINED] STEP 진입 실패: 세션 모달이 활성 상태가 아님', {
                    session,
                    stepName,
                    requestId,
                    sessionRequestId: _loraTrainedSessionRequestId,
                });
                return;
            }
            _renderLoraTrainedSessionBreadcrumb(session, stepName);
            _setLoraTrainedSessionBusy(true);

            const stepsEl = document.getElementById('lora-trained-steps');
            const previewsEl = document.getElementById('lora-trained-previews');
            if (!stepsEl || !previewsEl) {
                console.error('[LORA_TRAINED] STEP 프리뷰 렌더링 요소 누락:', {
                    steps: !!stepsEl,
                    previews: !!previewsEl,
                    session,
                    stepName,
                });
                _setLoraTrainedSessionBusy(false);
                return;
            }
            stepsEl.style.display = 'none';
            previewsEl.style.display = 'none';
            previewsEl.innerHTML = '';

            const enc = encodeURIComponent;
            try {
                const resp = await fetchJSON(`/api/lora/trained/steps?character=${enc(loraCurrentCharacter)}&entry=${enc(loraCurrentEntry)}&session=${enc(session)}`);
                if (!_isLoraTrainedStepRequestCurrent(requestId, session, stepName)) {
                    console.info('[LORA_TRAINED] 만료된 STEP 프리뷰 응답 무시:', {
                        requestId,
                        currentRequestId: _loraTrainedStepRequestId,
                        session,
                        stepName,
                        currentStep: loraCurrentTrainedStep,
                    });
                    return;
                }
                if (!resp.success) {
                    console.error('[LORA_TRAINED] STEP 프리뷰 API 실패:', {
                        character: loraCurrentCharacter,
                        entry: loraCurrentEntry,
                        session,
                        stepName,
                        response: resp,
                    });
                    previewsEl.style.display = '';
                    previewsEl.innerHTML = `<div style="text-align:center; padding:32px; color:var(--text-secondary);">${escapeHtml(resp.error || '프리뷰 로드에 실패했습니다.')}</div>`;
                    return;
                }
                const step = (resp.steps || []).find(s => s.name === stepName);
                if (!step || !step.previews || step.previews.length === 0) {
                    console.warn('[LORA_TRAINED] STEP 프리뷰 이미지 없음:', {
                        character: loraCurrentCharacter,
                        entry: loraCurrentEntry,
                        session,
                        stepName,
                        stepFound: !!step,
                    });
                    previewsEl.style.display = '';
                    previewsEl.innerHTML = '<div style="text-align:center; padding:32px; color:var(--text-secondary);">프리뷰 이미지가 없습니다.</div>';
                    return;
                }
                const safetensorsPath = step.safetensors;
                // 대표 상태 확인
                let isEntryRep = false, isSessionRep = false, sessionRepPreviewUrl = '';
                try {
                    const rep = loraEntryRepresentative ? JSON.parse(loraEntryRepresentative) : null;
                    if (rep && rep.safetensors === safetensorsPath) isEntryRep = true;
                } catch (e) {
                    console.error('[LORA_TRAINED] STEP 엔트리 대표 정보 파싱 실패:', {
                        session,
                        stepName,
                        representative: loraEntryRepresentative,
                        error: e,
                    });
                }
                try {
                    const sessResp = await fetchJSON(`/api/lora/trained/sessions?character=${enc(loraCurrentCharacter)}&entry=${enc(loraCurrentEntry)}`);
                    if (!_isLoraTrainedStepRequestCurrent(requestId, session, stepName)) {
                        console.info('[LORA_TRAINED] 만료된 STEP 대표 응답 무시:', {
                            requestId,
                            currentRequestId: _loraTrainedStepRequestId,
                            session,
                            stepName,
                            currentStep: loraCurrentTrainedStep,
                        });
                        return;
                    }
                    if (sessResp.success) {
                        const sess = (sessResp.sessions || []).find(x => x.name === session);
                        if (sess && sess.representative) {
                            try {
                                const sr = JSON.parse(sess.representative);
                                if (sr.safetensors === safetensorsPath) {
                                    isSessionRep = true;
                                    sessionRepPreviewUrl = sr.preview || '';
                                }
                            } catch (e) {
                                console.error('[LORA_TRAINED] STEP 세션 대표 정보 파싱 실패:', {
                                    session,
                                    stepName,
                                    representative: sess.representative,
                                    error: e,
                                });
                            }
                        }
                    } else {
                        console.error('[LORA_TRAINED] STEP 세션 대표 API 실패:', {
                            character: loraCurrentCharacter,
                            entry: loraCurrentEntry,
                            session,
                            stepName,
                            response: sessResp,
                        });
                    }
                } catch (e) {
                    console.error('[LORA_TRAINED] STEP 세션 대표 조회 실패:', {
                        character: loraCurrentCharacter,
                        entry: loraCurrentEntry,
                        session,
                        stepName,
                        error: e,
                    });
                }
                if (!_isLoraTrainedStepRequestCurrent(requestId, session, stepName)) {
                    console.info('[LORA_TRAINED] 렌더링 전 만료된 STEP 요청 무시:', {
                        requestId,
                        currentRequestId: _loraTrainedStepRequestId,
                        session,
                        stepName,
                        currentStep: loraCurrentTrainedStep,
                    });
                    return;
                }
                let badgeHtml = '';
                if (isEntryRep) badgeHtml += '<span style="background:rgba(0,120,215,0.95); color:#fff; font-size:0.7rem; font-weight:700; padding:2px 8px; border-radius:4px;">엔트리 대표</span>';
                if (isSessionRep) badgeHtml += '<span style="background:rgba(255,193,7,0.95); color:#000; font-size:0.7rem; font-weight:700; padding:2px 8px; border-radius:4px;">세션 대표</span>';
                previewsEl.innerHTML = `<div style="display:flex; align-items:center; gap:8px; margin-bottom:10px;">
                        <span style="font-size:0.82rem; color:var(--text-secondary);">${escapeHtml(step.safetensors)}</span>
                        ${badgeHtml}
                    </div>` +
                    `<div style="display:grid; grid-template-columns:repeat(auto-fill, minmax(400px, 1fr)); gap:12px;">` +
                    step.previews.map(p => {
                        const url = `/api/lora/trained/preview/${enc(loraCurrentCharacter)}/${enc(loraCurrentEntry)}/${enc(session)}/${enc(p)}`;
                        const isRepImage = isSessionRep && sessionRepPreviewUrl === url;
                        return `<div style="position:relative;">
                            <img src="${url}" style="width:100%; border-radius:10px; cursor:pointer; display:block;" onclick="openLightbox('${url}')">
                            ${isRepImage ? '<div style="position:absolute; top:10px; left:10px; z-index:50; background:rgba(255,193,7,0.95); color:#000; font-size:0.75rem; font-weight:700; padding:4px 10px; border-radius:6px;">현재 세션 대표 이미지</div>' : ''}
                            <div style="position:absolute; bottom:10px; right:10px; display:flex; gap:6px;">
                            <button onclick="setSessionRepresentative('${escapeHtml(session)}', '${escapeHtml(safetensorsPath)}', '${escapeHtml(url)}')"
                                    style="background:rgba(0,0,0,0.7); color:#fff; border:1px solid rgba(255,255,255,0.3); border-radius:8px; padding:6px 12px; font-size:0.78rem; cursor:pointer; backdrop-filter:blur(4px); transition:background 0.2s;"
                                    onmouseover="this.style.background='rgba(0,160,80,0.85)'" onmouseout="this.style.background='rgba(0,0,0,0.7)'">
                                세션 대표로 설정
                            </button>
                            </div>
                        </div>`;
                    }).join('') + '</div>';
                previewsEl.style.display = '';
            } catch (e) {
                console.error('[LORA_TRAINED] 프리뷰 로드 실패:', e);
                if (_isLoraTrainedStepRequestCurrent(requestId, session, stepName)) {
                    previewsEl.style.display = '';
                    previewsEl.innerHTML = '<div style="text-align:center; padding:32px; color:var(--text-secondary);">프리뷰 로드에 실패했습니다.</div>';
                }
            } finally {
                if (_isLoraTrainedStepRequestCurrent(requestId, session, stepName)) {
                    _setLoraTrainedSessionBusy(false);
                }
            }
        }

        function validateLoraProjectName(name) {
            return ComfyBotBatch.getStorageNameError(String(name || '').trim(), 'LoRA 프로젝트명');
        }

        function setLoraProjectNameFieldError(inputId, errorId, message) {
            const input = document.getElementById(inputId);
            const errorEl = document.getElementById(errorId);
            if (input) input.style.borderColor = message ? 'var(--error)' : 'var(--border)';
            if (errorEl) {
                errorEl.textContent = message || '';
                errorEl.style.display = message ? 'block' : 'none';
            }
        }

        function validateLoraProjectNameField(inputId, errorId) {
            const input = document.getElementById(inputId);
            if (!input) {
                console.error('[LORA_NAME] 프로젝트명 입력 필드를 찾을 수 없음:', inputId);
                return false;
            }
            const message = input.value ? validateLoraProjectName(input.value) : '';
            setLoraProjectNameFieldError(inputId, errorId, message);
            return !message;
        }

        function setLoraEntryAddError(message) {
            const errorEl = document.getElementById('lora-entry-add-error');
            errorEl.textContent = message || '';
            errorEl.style.display = message ? 'block' : 'none';
        }

        function validateLoraEntryAddName() {
            const input = document.getElementById('lora-entry-add-name');
            const message = input.value ? validateLoraProjectName(input.value) : '';
            setLoraEntryAddError(message);
            input.style.borderColor = message ? 'var(--error)' : 'var(--border)';
            return !message;
        }

        async function addLoraEntry() {
            if (!loraCurrentCharacter) { showToast('먼저 캐릭터를 선택하세요', 'error'); return; }
            document.getElementById('lora-entry-add-character').textContent = loraCurrentCharacter;
            document.getElementById('lora-entry-add-name').value = '';
            document.getElementById('lora-entry-add-trigger').value = '';
            document.getElementById('lora-entry-add-description').value = '';
            document.getElementById('lora-entry-add-name').style.borderColor = 'var(--border)';
            setLoraEntryAddError('');
            document.getElementById('lora-entry-add-modal').style.display = 'flex';
            setTimeout(() => document.getElementById('lora-entry-add-name').focus(), 0);
        }

        function closeLoraEntryAddModal() {
            document.getElementById('lora-entry-add-modal').style.display = 'none';
        }

        async function confirmLoraEntryAdd() {
            if (!loraCurrentCharacter) {
                console.error('[LORA_MANAGE] 프로젝트 추가 실패: 선택된 캐릭터 없음');
                setLoraEntryAddError('먼저 캐릭터를 선택하세요');
                return;
            }
            const nameInput = document.getElementById('lora-entry-add-name');
            const triggerInput = document.getElementById('lora-entry-add-trigger');
            const name = nameInput.value.trim();
            const trigger = triggerInput.value.trim();
            const description = document.getElementById('lora-entry-add-description').value.trim();
            const nameError = validateLoraProjectName(name);
            if (nameError) {
                setLoraEntryAddError(nameError);
                nameInput.style.borderColor = 'var(--error)';
                nameInput.focus();
                return;
            }
            if (!trigger) {
                setLoraEntryAddError('트리거 키워드는 필수입니다');
                triggerInput.focus();
                return;
            }
            setLoraEntryAddError('');
            const confirmButton = document.getElementById('lora-entry-add-confirm');
            confirmButton.disabled = true;
            try {
                const resp = await fetchJSON('/api/lora/manage/add', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ name, character: loraCurrentCharacter, trigger, description })
                });
                if (resp.success) {
                    showToast('LoRA 항목 추가 완료', 'success');
                    closeLoraEntryAddModal();
                    await enterLoraCharacter(loraCurrentCharacter);
                } else {
                    const message = resp.error || '추가 실패';
                    console.error('[LORA_MANAGE] 프로젝트 추가 거부:', message);
                    setLoraEntryAddError(message);
                }
            } catch (e) {
                console.error('[LORA_MANAGE] 추가 실패:', e);
                setLoraEntryAddError(`추가 실패: ${e.message || e}`);
            } finally {
                confirmButton.disabled = false;
            }
        }

        async function removeLoraEntry() {
            if (!loraCurrentEntry) { showToast('삭제할 LoRA 항목을 선택하세요', 'error'); return; }
            if (!confirm(`프로젝트 "${loraCurrentEntry}"를 삭제하시겠습니까?\n\n프로젝트의 이미지와 학습된 LoRA 파일(대표 및 모든 학습 결과)이 함께 삭제됩니다.\n삭제한 파일은 복구할 수 없습니다.`)) return;
            try {
                const resp = await fetchJSON('/api/lora/manage/delete', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ name: loraCurrentEntry, character: loraCurrentCharacter })                });
                if (resp.success) {
                    if (resp.modal_sync_warning) {
                        showToast(`로컬 프로젝트와 LoRA는 삭제됐지만 원격 LoRA 삭제 예약에 실패했습니다: ${resp.modal_sync_warning}`, 'error');
                    } else showToast('프로젝트 및 LoRA 삭제 완료', 'success');
                    await enterLoraCharacter(loraCurrentCharacter);
                } else {
                    showToast(resp.error || '삭제 실패', 'error');
                }
            } catch (e) { console.error('[LORA_MANAGE] 삭제 실패:', e); showToast(`삭제 실패: ${e.message || e}`, 'error'); }
        }

        // ─── LoRA 항목 복제 ─────────────────────────────────
        async function openLoraDuplicateModal() {
            if (!loraCurrentEntry) { showToast('LoRA 항목을 선택하세요', 'error'); return; }

            // 원본 정보 표시
            document.getElementById('dup-source-info').textContent =
                `${loraCurrentCharacter} / ${loraCurrentEntry}`;

            // 대상 항목명 초기화
            document.getElementById('dup-target-entry').value = '';
            setLoraProjectNameFieldError('dup-target-entry', 'dup-target-entry-error', '');
            document.getElementById('dup-description').value = '';
            document.getElementById('dup-training-config').value = '';

            try {
                // 캐릭터 목록 로드
                const charResp = await fetchJSON('/api/lora/characters');
                const sel = document.getElementById('dup-target-character');
                sel.innerHTML = '';
                if (charResp.success && charResp.characters) {
                    charResp.characters.forEach(c => {
                        const opt = document.createElement('option');
                        opt.value = c; opt.textContent = c;
                        if (c === loraCurrentCharacter) opt.selected = true;
                        sel.appendChild(opt);
                    });
                }

                // 현재 엔트리 데이터로 pre-fill
                const enc = encodeURIComponent;
                const entryResp = await fetchJSON(`/api/lora/manage/list?character=${enc(loraCurrentCharacter)}`);
                if (entryResp.success) {
                    const entry = (entryResp.loras || []).find(l => l.name === loraCurrentEntry);
                    if (entry) {
                        document.getElementById('dup-trigger').value = entry.trigger || '';
                        document.getElementById('dup-description').value = entry.description || '';
                        if (entry.training_config && Object.keys(entry.training_config).length > 0) {
                            document.getElementById('dup-training-config').value =
                                JSON.stringify(entry.training_config, null, 2);
                        }
                    }
                }
            } catch (e) {
                console.error('[LORA_MANAGE] 복제 모달 로드 실패:', e);
            }

            // 대상 캐릭터/항목명 변경 시 lora_save_path 실시간 갱신
            const updateDupSavePath = () => {
                const tc = document.getElementById('dup-training-config');
                const tcRaw = tc.value.trim();
                if (!tcRaw) return;
                try {
                    const cfg = JSON.parse(tcRaw);
                    cfg.lora_save_path = 'SOYA_ASSET_LORA/' + document.getElementById('dup-target-character').value + '/Lora/' + (document.getElementById('dup-target-entry').value.trim() || '?');
                    tc.value = JSON.stringify(cfg, null, 2);
                } catch {}
            };
            document.getElementById('dup-target-character').onchange = updateDupSavePath;
            document.getElementById('dup-target-entry').oninput = () => {
                updateDupSavePath();
                validateLoraProjectNameField('dup-target-entry', 'dup-target-entry-error');
            };

            document.getElementById('lora-duplicate-modal').style.display = 'flex';
        }

        function closeLoraDuplicateModal() {
            document.getElementById('lora-duplicate-modal').style.display = 'none';
        }

        // --- TOML 미리보기 모달 ---
        async function openLoraTomlModal() {
            if (!loraCurrentTrainedSession) { showToast('세션을 먼저 선택하세요', 'error'); return; }
            const enc = encodeURIComponent;
            // 현재 표시된 step 목록에서 첫 번째 step 사용
            const stepsContainer = document.getElementById('lora-trained-steps');
            const firstStepEl = stepsContainer ? stepsContainer.querySelector('[data-step-name]') : null;
            if (!firstStepEl) { showToast('step이 없습니다', 'error'); return; }
            const stepName = firstStepEl.getAttribute('data-step-name');
            const modal = document.getElementById('lora-toml-modal');
            const titleEl = document.getElementById('lora-toml-modal-title');
            const contentEl = document.getElementById('lora-toml-modal-content');
            titleEl.textContent = 'TOML 학습 설정 — ' + stepName + '.toml';
            contentEl.textContent = '불러오는 중...';
            modal.style.display = 'flex';
            try {
                const resp = await fetchJSON(`/api/lora/trained/toml?character=${enc(loraCurrentCharacter)}&entry=${enc(loraCurrentEntry)}&session=${enc(loraCurrentTrainedSession)}&step=${enc(stepName)}`);
                if (resp.success) {
                    contentEl.textContent = resp.content;
                } else {
                    contentEl.textContent = resp.error || 'TOML 파일을 불러올 수 없습니다';
                }
            } catch (e) {
                contentEl.textContent = 'TOML 로드 실패: ' + e;
            }
        }
        function closeLoraTomlModal() {
            document.getElementById('lora-toml-modal').style.display = 'none';
        }

        async function confirmLoraDuplicate() {
            const targetEntryInput = document.getElementById('dup-target-entry');
            const targetEntry = targetEntryInput.value.trim();
            const targetCharacter = document.getElementById('dup-target-character').value;
            const trigger = document.getElementById('dup-trigger').value.trim();
            const description = document.getElementById('dup-description').value.trim();

            if (!targetEntry) {
                setLoraProjectNameFieldError('dup-target-entry', 'dup-target-entry-error', 'LoRA 프로젝트명을 입력하세요');
                targetEntryInput.focus();
                return;
            }
            const nameError = validateLoraProjectName(targetEntry);
            if (nameError) {
                setLoraProjectNameFieldError('dup-target-entry', 'dup-target-entry-error', nameError);
                targetEntryInput.focus();
                return;
            }
            setLoraProjectNameFieldError('dup-target-entry', 'dup-target-entry-error', '');
            if (!trigger) { showToast('트리거 키워드를 입력하세요', 'error'); return; }

            let trainingConfig = null;
            const tcRaw = document.getElementById('dup-training-config').value.trim();
            if (tcRaw) {
                try { trainingConfig = JSON.parse(tcRaw); }
                catch (e) { showToast('학습 설정 JSON 형식 오류', 'error'); return; }
            }

            // lora_save_path를 대상 캐릭터/항목명에 맞게 재생성
            if (trainingConfig) {
                trainingConfig.lora_save_path = 'SOYA_ASSET_LORA/' + targetCharacter + '/Lora/' + targetEntry;
            }

            try {
                const resp = await fetchJSON('/api/lora/manage/duplicate', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        source_character: loraCurrentCharacter,
                        source_entry: loraCurrentEntry,
                        target_character: targetCharacter,
                        target_entry: targetEntry,
                        trigger, description,
                        training_config: trainingConfig
                    })
                });
                if (resp.success) {
                    showToast(`복제 완료 (학습 ${resp.copied_training || 0}장, 테스트 ${resp.copied_test || 0}장)`, 'success');
                    closeLoraDuplicateModal();
                    // 타겟 캐릭터가 현재 캐릭터와 같으면 목록 새로고침
                    if (targetCharacter === loraCurrentCharacter) {
                        await enterLoraCharacter(loraCurrentCharacter);
                    }
                } else {
                    const message = resp.error || '복제 실패';
                    console.error('[LORA_MANAGE] 프로젝트 복제 거부:', message);
                    setLoraProjectNameFieldError('dup-target-entry', 'dup-target-entry-error', message);
                }
            } catch (e) {
                console.error('[LORA_MANAGE] 복제 실패:', e);
                setLoraProjectNameFieldError('dup-target-entry', 'dup-target-entry-error', '복제 요청에 실패했습니다');
            }
        }

        async function saveLoraEntryInfo() {
            if (!loraCurrentEntry) { showToast('LoRA 항목을 선택하세요', 'error'); return; }
            const trigger = document.getElementById('lora-entry-trigger').value.trim();
            if (!trigger) { showToast('트리거 키워드는 필수입니다', 'error'); return; }
            const description = document.getElementById('lora-entry-description').value.trim();
            try {
                const resp = await fetchJSON('/api/lora/manage/update', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ name: loraCurrentEntry, character: loraCurrentCharacter, trigger, description })
                });
                if (resp.success) { showToast('저장 완료', 'success'); }
                else { showToast(resp.error || '저장 실패', 'error'); }
            } catch (e) { console.error('[LORA_MANAGE] 저장 실패:', e); showToast('저장 실패', 'error'); }
        }

        async function startLoraTraining() {
            if (!loraCurrentCharacter || !loraCurrentEntry) { showToast('LoRA 항목을 선택하세요', 'error'); return; }
            try {
                // 학습 전 설정 자동 저장
                await saveLoraTrainingConfig();
                const resp = await fetchJSON('/api/lora/training/start', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ character: loraCurrentCharacter, entry: loraCurrentEntry })
                });
                if (resp.success) {
                    showToast(`큐에 추가됨: ${resp.label}`, 'success');
                } else {
                    showToast(resp.error || '큐 추가 실패', 'error');
                }
            } catch (e) { console.error('[LORA] 큐 추가 실패:', e); showToast('큐 추가 실패', 'error'); }
        }

        function showLoraTrainingProgress() {
            const el = document.getElementById('lora-training-progress');
            if (el) el.style.display = 'block';
            const btn = document.getElementById('lora-training-start-btn');
            if (btn) { btn.disabled = true; btn.style.opacity = '0.5'; btn.style.cursor = 'not-allowed'; }
            const stopBtn = document.getElementById('lora-training-stop-btn');
            if (stopBtn) stopBtn.style.display = 'inline-block';
            updateLoraTrainingUI('preparing', { message: '학습 준비 중...' });
        }

        function stopLoraTraining() {
            // 진행률 UI 숨기고 학습 시작 버튼 복원
            const progEl = document.getElementById('lora-training-progress');
            if (progEl) progEl.style.display = 'none';
            const btn = document.getElementById('lora-training-start-btn');
            if (btn) { btn.disabled = false; btn.style.opacity = '1'; btn.style.cursor = 'pointer'; }
            const stopBtn = document.getElementById('lora-training-stop-btn');
            if (stopBtn) stopBtn.style.display = 'none';
            showToast('학습 중지됨 (버튼 복원)', 'info');
        }

        function updateLoraTrainingUI(phase, data) {
            const phaseEl = document.getElementById('lora-progress-phase');
            const pctEl = document.getElementById('lora-progress-pct');
            const barEl = document.getElementById('lora-progress-bar');
            const stepEl = document.getElementById('lora-progress-step');
            const timeEl = document.getElementById('lora-progress-time');

            if (phase === 'preparing' || phase === 'modal_running' || phase === 'modal_syncing' || phase === 'vast_running') {
                if (phaseEl) phaseEl.textContent = '준비 중';
                if (pctEl) pctEl.textContent = '';
                if (barEl) barEl.style.width = '0%';
                if (stepEl) stepEl.textContent = data.message || '';
                if (timeEl) timeEl.textContent = '';
            } else if (phase === 'modal_downloading' || phase === 'modal_download_complete' || phase === 'vast_downloading') {
                const pct = Math.round(Number(data.percentage || 0));
                if (phaseEl) phaseEl.textContent = phase === 'modal_download_complete' ? 'LoRA 다운로드 완료' : 'LoRA 다운로드 중';
                if (pctEl) pctEl.textContent = pct + '%';
                if (barEl) { barEl.style.width = pct + '%'; barEl.style.background = '#06b6d4'; }
                if (stepEl) stepEl.textContent = data.name || data.message || '';
                if (timeEl) {
                    const done = Number(data.downloaded_bytes || 0);
                    const total = Number(data.total_bytes || 0);
                    timeEl.textContent = total > 0 ? `${comfyInstallerFormatBytes(done)} / ${comfyInstallerFormatBytes(total)}` : '';
                }
            } else if (phase === 'training') {
                const step = data.step || 0;
                const total = data.total || 1;
                const pct = Math.round(step / total * 100);
                if (phaseEl) phaseEl.textContent = '학습 진행 중';
                if (pctEl) pctEl.textContent = pct + '%';
                if (barEl) { barEl.style.width = pct + '%'; barEl.style.background = 'var(--accent)'; }
                if (stepEl) stepEl.textContent = `스텝 ${step}/${total}`;
                const remainMin = data.remaining_min || 0;
                const elapsedSec = data.elapsed_sec || 0;
                const elapsedMin = (elapsedSec / 60).toFixed(1);
                if (timeEl) timeEl.textContent = `경과 ${elapsedMin}분 / 남은 ${remainMin.toFixed(1)}분`;
            } else if (phase === 'training_complete') {
                if (phaseEl) phaseEl.textContent = '학습 완료';
                if (pctEl) pctEl.textContent = '100%';
                if (barEl) { barEl.style.width = '100%'; barEl.style.background = '#4caf50'; }
                if (stepEl) stepEl.textContent = data.message || '학습 완료!';
                if (timeEl) timeEl.textContent = '';
            } else if (phase === 'preview' || phase === 'preview_start') {
                const current = data.current || 0;
                const total = data.total || 1;
                const pct = total > 0 ? Math.round(current / total * 100) : 0;
                if (phaseEl) phaseEl.textContent = '프리뷰 이미지 생성';
                if (pctEl) pctEl.textContent = pct + '%';
                if (barEl) { barEl.style.width = pct + '%'; barEl.style.background = '#2196f3'; }
                if (stepEl) stepEl.textContent = `프리뷰 ${current}/${total}`;
                const remainMin = data.remaining_min || 0;
                if (timeEl) timeEl.textContent = remainMin > 0 ? `남은 약 ${remainMin.toFixed(1)}분` : '';
            } else if (phase === 'all_complete') {
                if (phaseEl) { phaseEl.textContent = '전체 완료!'; phaseEl.style.color = '#4caf50'; }
                if (pctEl) pctEl.textContent = '';
                if (barEl) { barEl.style.width = '100%'; barEl.style.background = '#4caf50'; }
                if (stepEl) stepEl.textContent = data.message || '모든 작업 완료';
                if (timeEl) timeEl.textContent = '';
                // 학습 시작 버튼 복원
                const btn = document.getElementById('lora-training-start-btn');
                if (btn) { btn.disabled = false; btn.style.opacity = '1'; btn.style.cursor = 'pointer'; }
                const stopBtn2 = document.getElementById('lora-training-stop-btn');
                if (stopBtn2) stopBtn2.style.display = 'none';
                showToast('LoRA 학습 및 다운로드가 완료되었습니다!', 'success');
                // 학습 완료 시 세션 카드 목록을 새로고침해 새 세션이 바로 보이게 한다.
                // (엔트리 상세 화면을 보고 있을 때만)
                const trainedSec = document.getElementById('lora-trained-section');
                if (trainedSec && trainedSec.style.display !== 'none' && loraCurrentEntry) {
                    try { loadTrainedLoraSessions(); }
                    catch (e) { console.error('[LORA_TRAINING] 완료 후 세션 목록 새로고침 실패:', e); }
                }
            } else if (phase === 'error') {
                if (phaseEl) { phaseEl.textContent = '에러 발생'; phaseEl.style.color = 'var(--error)'; }
                if (pctEl) pctEl.textContent = '';
                if (barEl) { barEl.style.background = 'var(--error)'; }
                if (stepEl) stepEl.textContent = data.message || '알 수 없는 에러';
                if (timeEl) timeEl.textContent = '';
                const btn = document.getElementById('lora-training-start-btn');
                if (btn) { btn.disabled = false; btn.style.opacity = '1'; btn.style.cursor = 'pointer'; }
                const stopBtn3 = document.getElementById('lora-training-stop-btn');
                if (stopBtn3) stopBtn3.style.display = 'none';
                showToast('학습 중 에러: ' + (data.message || ''), 'error');
            }
        }

        async function exportLoraTrainingImages() {
            if (!loraCurrentCharacter || !loraCurrentEntry) { showToast('LoRA 항목을 선택하세요', 'error'); return; }
            try {
                const resp = await fetchJSON('/api/lora/training_images/export', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ character: loraCurrentCharacter, entry: loraCurrentEntry })
                });
                if (resp.success) {
                    const errs = resp.errors || [];
                    const msg = errs.length > 0
                        ? `${resp.count}개 전송 완료 (${errs.length}개 실패)`
                        : `${resp.count}개 전송 완료`;
                    showToast(msg, errs.length > 0 ? 'warning' : 'success');
                } else {
                    showToast(resp.error || '전송 실패', 'error');
                }
            } catch (e) { console.error('[LORA] 이미지 전송 실패:', e); showToast('전송 실패', 'error'); }
        }

        async function loadLoraFiles() {
            if (!loraCurrentCharacter) return;
            const grid = document.getElementById('lora-file-grid');
            const section = document.getElementById('lora-files-section');
            const enc = encodeURIComponent;
            try {
                let url = `/api/lora/list?character=${enc(loraCurrentCharacter)}`;
                if (loraCurrentEntry) url += `&entry=${enc(loraCurrentEntry)}`;
                const resp = await fetchJSON(url);
                if (!resp.success) { showToast(resp.error || '파일 목록 로드 실패', 'error'); return; }
                const files = resp.files || [];
                section.style.display = '';
                if (files.length === 0) {
                    grid.style.display = 'none';
                    return;
                }
                grid.style.display = '';
                grid.innerHTML = files.map(f => `
                    <div class="lora-file-card">
                        <div class="lora-file-name">${escapeHtml(f.filename)}</div>
                        <div class="lora-file-info">${formatFileSize(f.size)} · ${formatDate(f.modified)}</div>
                        <div class="lora-file-actions">
                            <button style="background:var(--error); color:#fff;" onclick="deleteLoraFile('${escapeHtml(f.filename)}')">삭제</button>
                        </div>
                    </div>
                `).join('');
            } catch (e) {
                console.error('[LORA] 파일 목록 로드 실패:', e);
            }
        }

        async function uploadLoraFile(input) {
            if (!loraCurrentCharacter) { showToast('먼저 캐릭터를 선택하세요', 'error'); input.value = ''; return; }
            const file = input.files[0];
            if (!file) return;
            const formData = new FormData();
            formData.append('file', file);
            const enc = encodeURIComponent;
            try {
                let url = `/api/lora/upload?character=${enc(loraCurrentCharacter)}`;
                if (loraCurrentEntry) url += `&entry=${enc(loraCurrentEntry)}`;
                const resp = await fetch(url, { method: 'POST', body: formData });
                const result = await resp.json();
                if (result.success) { showToast('업로드 완료', 'success'); await loadLoraFiles(); }
                else { showToast(result.error || '업로드 실패', 'error'); }
            } catch (e) { console.error('[LORA] 업로드 실패:', e); showToast('업로드 실패', 'error'); }
            input.value = '';
        }

        async function deleteLoraFile(filename) {
            if (!confirm(`"${filename}" 삭제하시겠습니까?`)) return;
            try {
                const resp = await fetchJSON('/api/lora/delete', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ character: loraCurrentCharacter, filename, entry: loraCurrentEntry })
                });
                if (resp.success) { showToast('삭제 완료', 'success'); await loadLoraFiles(); }
                else { showToast(resp.error || '삭제 실패', 'error'); }
            } catch (e) { console.error('[LORA] 삭제 실패:', e); showToast('삭제 실패', 'error'); }
        }

        // ─── 학습용 이미지 ─────────────────────────────────────
        async function loadLoraTrainingImages() {
            if (!loraCurrentCharacter || !loraCurrentEntry) return;
            const grid = document.getElementById('lora-training-grid');
            const section = document.getElementById('lora-training-section');
            const emptyEl = document.getElementById('lora-training-empty');
            const enc = encodeURIComponent;
            try {
                const resp = await fetchJSON(`/api/lora/training_images?character=${enc(loraCurrentCharacter)}&entry=${enc(loraCurrentEntry)}`);
                if (!resp.success) { showToast(resp.error || '학습 이미지 로드 실패', 'error'); return; }
                const images = resp.images || [];
                section.style.display = '';
                // N_IMG 자동 업데이트
                document.getElementById('lora-cfg-nimg').textContent = images.length;
                updateSaveAfterDropdown();
                if (images.length === 0) {
                    grid.style.display = 'none';
                    emptyEl.style.display = '';
                    return;
                }
                emptyEl.style.display = 'none';
                grid.style.display = '';
                grid.innerHTML = images.map(img => `
                    <div class="asset-image-card" style="cursor:default;">
                        <div style="position:relative; overflow:hidden; border-radius:8px;">
                            <img src="/api/lora/training_image/${enc(loraCurrentCharacter)}/${enc(loraCurrentEntry)}/${enc(img.filename)}" style="width:100%; display:block; cursor:zoom-in;" onclick="event.stopPropagation(); openLightbox(this.src)">
                            ${img.is_representative ? '<div style="position:absolute; top:4px; left:4px; z-index:70; background:rgba(255,193,7,0.95); color:#000; font-size:0.7rem; font-weight:700; padding:3px 8px; border-radius:4px;">대표</div>' : ''}
                            ${img.width && img.height ? '<div style="position:absolute; top:4px; right:4px; z-index:70; background:rgba(0,0,0,0.7); color:#fff; font-size:0.65rem; padding:2px 6px; border-radius:4px;">' + img.width + 'x' + img.height + '</div>' : ''}
                        </div>
                        <div style="padding:8px;">
                            <div style="font-size:0.75rem; color:var(--text-secondary); margin-bottom:4px;">${escapeHtml(img.filename)}</div>
                            <div style="font-size:0.7rem; color:var(--text-secondary); margin-bottom:6px; max-height:40px; overflow:hidden;">${escapeHtml(img.positive || '(프롬프트 없음)')}</div>
                            <div style="display:flex; gap:4px; flex-wrap:wrap;">
                                <button onclick="showLoraTrainingPrompt('${escapeHtml(img.filename)}')" style="flex:1; padding:3px 6px; background:var(--surface2); color:var(--text); border:1px solid var(--border); border-radius:4px; cursor:pointer; font-size:0.7rem;">프롬프트</button>
                                <button onclick="deleteLoraTrainingImage('${escapeHtml(img.filename)}')" style="flex:1; padding:3px 6px; background:var(--error); color:#fff; border:none; border-radius:4px; cursor:pointer; font-size:0.7rem;">삭제</button>
                            </div>
                        </div>
                    </div>
                `).join('');
            } catch (e) {
                console.error('[LORA] 학습 이미지 로드 실패:', e);
            }
        }

        // ─── 학습 설정 ─────────────────────────────────────

        // SAVE_AFTER 드롭박스 실시간 갱신
        function updateSaveAfterDropdown() {
            const nImg = parseInt(document.getElementById('lora-cfg-nimg').textContent) || 0;
            const stepPerImage = parseInt(document.getElementById('lora-cfg-step').value) || 50;
            const savePerStep = parseInt(document.getElementById('lora-cfg-save-step').value) || 50;
            const select = document.getElementById('lora-cfg-save-after');
            const currentValue = parseInt(select.value) || 0;
            const maxSteps = nImg * stepPerImage;

            let options = [{value: 0, label: '전체 기록 (0)'}];
            if (savePerStep > 0) {
                for (let step = savePerStep; step <= maxSteps; step += savePerStep) {
                    options.push({value: step, label: step + ' 이후'});
                }
            }

            select.innerHTML = '';
            options.forEach(opt => {
                const el = document.createElement('option');
                el.value = opt.value;
                el.textContent = opt.label;
                select.appendChild(el);
            });

            // 기존 선택값 유지, 없으면 0으로 리셋
            if (options.some(opt => opt.value === currentValue)) {
                select.value = currentValue;
            } else {
                select.value = 0;
            }
        }

        async function loadLoraTrainingConfig() {
            if (!loraCurrentCharacter || !loraCurrentEntry) return;
            const enc = encodeURIComponent;
            try {
                const resp = await fetchJSON(`/api/lora/manage/list?character=${enc(loraCurrentCharacter)}`);
                if (resp.success) {
                    const entry = (resp.loras || []).find(l => l.name === loraCurrentEntry);
                    const cfg = (entry && entry.training_config) || {};
                    document.getElementById('lora-cfg-profile').value = cfg.profile || '';
                    document.getElementById('lora-cfg-step').value = cfg.step_per_image || 50;
                    document.getElementById('lora-cfg-ilrate').value = cfg.il_rate || 0.0005;
                    document.getElementById('lora-cfg-save-step').value = cfg.save_per_step || 50;
                    document.getElementById('lora-cfg-folder').textContent = cfg.multi_img_folder_name || 'soya_lora';
                    document.getElementById('lora-cfg-genw').value = cfg.gen_w || 1024;
                    document.getElementById('lora-cfg-genh').value = cfg.gen_h || 1024;
                    // 업스케일링 토글
                    const upscaleCb = document.getElementById('lora-cfg-upscale');
                    upscaleCb.checked = !!cfg.upscale;
                    const upscaleStatus = document.getElementById('lora-cfg-upscale-status');
                    upscaleStatus.textContent = cfg.upscale ? 'ON' : 'OFF';
                    upscaleStatus.className = 'toggle-status ' + (cfg.upscale ? 'on' : 'off');
                    document.getElementById('lora-cfg-resolution').value = cfg.resolution || 1024;
                    document.getElementById('lora-cfg-dim').value = cfg.dim || 32;
                    document.getElementById('lora-cfg-alpha').value = cfg.alpha || 16;
                    // SAVE_AFTER 드롭박스 갱신 후 복원
                    updateSaveAfterDropdown();
                    if (cfg.save_after !== undefined) {
                        const saveAfterSelect = document.getElementById('lora-cfg-save-after');
                        if (saveAfterSelect.querySelector(`option[value="${cfg.save_after}"]`)) {
                            saveAfterSelect.value = cfg.save_after;
                        }
                    }
                    // lora_save_path 자동 생성 (models/loras 기준 상대 경로)
                    document.getElementById('lora-cfg-save-path').textContent = 'SOYA_ASSET_LORA/' + loraCurrentCharacter + '/Lora/' + loraCurrentEntry;
                }
            } catch (e) { console.error('[LORA] 학습 설정 로드 실패:', e); }
        }

        async function saveLoraTrainingConfig() {
            if (!loraCurrentEntry) { showToast('LoRA 항목을 선택하세요', 'error'); return; }
            const training_config = {
                profile: document.getElementById('lora-cfg-profile').value.trim(),
                step_per_image: parseInt(document.getElementById('lora-cfg-step').value) || 50,
                il_rate: parseFloat(document.getElementById('lora-cfg-ilrate').value) || 0.0005,
                save_per_step: parseInt(document.getElementById('lora-cfg-save-step').value) || 50,
                save_after: parseInt(document.getElementById('lora-cfg-save-after').value) || 0,
                multi_img_folder_name: document.getElementById('lora-cfg-folder').textContent.trim(),
                gen_w: parseInt(document.getElementById('lora-cfg-genw').value) || 1024,
                gen_h: parseInt(document.getElementById('lora-cfg-genh').value) || 1024,
                upscale: document.getElementById('lora-cfg-upscale').checked,
                resolution: parseInt(document.getElementById('lora-cfg-resolution').value) || 1024,
                dim: parseInt(document.getElementById('lora-cfg-dim').value) || 32,
                alpha: parseInt(document.getElementById('lora-cfg-alpha').value) || 16,
                lora_save_path: document.getElementById('lora-cfg-save-path').textContent.trim() || ('SOYA_ASSET_LORA/' + loraCurrentCharacter + '/Lora/' + loraCurrentEntry),
            };
            try {
                const resp = await fetchJSON('/api/lora/manage/update', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ name: loraCurrentEntry, character: loraCurrentCharacter, training_config })
                });
                if (resp.success) { showToast('학습 설정 저장 완료', 'success'); }
                else { showToast(resp.error || '저장 실패', 'error'); }
            } catch (e) { console.error('[LORA] 학습 설정 저장 실패:', e); showToast('저장 실패', 'error'); }
        }

        // 학습 이미지 캐시 (미리보기용)
        let loraTrainingImageCache = [];
        let loraTestImageCache = [];

        // loadLoraTrainingImages에서 캐시 업데이트 (기존 함수에 캐시 저장 추가는 별도)
        async function _fetchLoraTrainingImageCache() {
            if (!loraCurrentCharacter || !loraCurrentEntry) { loraTrainingImageCache = []; return; }
            const enc = encodeURIComponent;
            try {
                const resp = await fetchJSON(`/api/lora/training_images?character=${enc(loraCurrentCharacter)}&entry=${enc(loraCurrentEntry)}`);
                loraTrainingImageCache = resp.success ? (resp.images || []) : [];
            } catch (e) { loraTrainingImageCache = []; }
        }

        async function _fetchLoraTestImageCache() {
            if (!loraCurrentCharacter || !loraCurrentEntry) { loraTestImageCache = []; return; }
            const enc = encodeURIComponent;
            try {
                const resp = await fetchJSON(`/api/lora/test_images?character=${enc(loraCurrentCharacter)}&entry=${enc(loraCurrentEntry)}`);
                loraTestImageCache = resp.success ? (resp.images || []) : [];
            } catch (e) { loraTestImageCache = []; }
        }

        async function previewLoraPromptsRaw() {
            await Promise.all([_fetchLoraTrainingImageCache(), _fetchLoraTestImageCache()]);
            const images = loraTrainingImageCache;
            const testImages = loraTestImageCache;
            if (images.length === 0) { showToast('학습 이미지가 없습니다', 'error'); return; }

            const profile = document.getElementById('lora-cfg-profile').value.trim();
            const nImg = images.length;
            const stepPerImage = parseInt(document.getElementById('lora-cfg-step').value) || 50;
            const ilRate = parseFloat(document.getElementById('lora-cfg-ilrate').value) || 0.0005;
            const savePerStep = parseInt(document.getElementById('lora-cfg-save-step').value) || 50;
            const folderName = document.getElementById('lora-cfg-folder').textContent.trim();
            const genW = parseInt(document.getElementById('lora-cfg-genw').value) || 1024;
            const genH = parseInt(document.getElementById('lora-cfg-genh').value) || 1024;
            const loraSavePath = document.getElementById('lora-cfg-save-path').textContent.trim() || (loraCurrentCharacter + '/Lora/' + loraCurrentEntry);
            const upscale = document.getElementById('lora-cfg-upscale').checked;
            const resolution = parseInt(document.getElementById('lora-cfg-resolution').value) || 1024;
            const saveAfter = parseInt(document.getElementById('lora-cfg-save-after').value) || 0;
            const dim = parseInt(document.getElementById('lora-cfg-dim').value) || 32;
            const alpha = parseInt(document.getElementById('lora-cfg-alpha').value) || 16;

            // 긍정: [1]트리거 프롬프트\n...\n[PROFILE]\n...\n[TEST_POSITIVE]\n...\n[TEST_NEGATIVE]\n...\n[END]
            const trigger = document.getElementById('lora-entry-trigger').value.trim();
            let positiveRaw = '';
            let negativeRaw = '';
            images.forEach((img, i) => {
                const triggerPrefix = trigger ? trigger + ', ' : '';
                positiveRaw += `[${i + 1}]${triggerPrefix}${img.positive || '(프롬프트 없음)'}\n`;
                negativeRaw += `[${i + 1}]${img.negative || ''}\n`;
            });

            // 설정 블록 (긍정만)
            let configBlock = `[PROFILE]\n${profile || '(미입력)'}\n[N_IMG]\n${nImg}\n[STEP_PER_IMAGE]\n${stepPerImage}\n[IL_RATE]\n${ilRate}\n[SAVE_PER_STEP]\n${savePerStep}\n[MULTI_IMG_FOLDER_NAME]\n${folderName || '(미입력)'}\n[LORA_SAVE_PATH]\n${loraSavePath}\n[GEN_W]\n${genW}\n[GEN_H]\n${genH}\n[UPSCALE]\n${upscale}\n[RESOLUTION]\n${resolution}\n[SAVE_AFTER]\n${saveAfter}`;

            // TEST_POSITIVE + TEST_NEGATIVE (항상 포함)
            let testBlock = '\n[TEST_POSITIVE]\n';
            testImages.forEach((img, i) => {
                const triggerPrefix = trigger ? trigger + ', ' : '';
                testBlock += `[${i + 1}]${triggerPrefix}${img.positive || '(프롬프트 없음)'}\n`;
            });
            testBlock += '[TEST_NEGATIVE]\n';
            testImages.forEach((img, i) => {
                testBlock += `[${i + 1}]${img.negative || ''}\n`;
            });

            positiveRaw += configBlock + testBlock + `\n[DIM]\n${dim}\n[ALPHA]\n${alpha}\n[END]`;
            // 부정: 이미지별 태그만, [END] 없음

            let overlay = document.getElementById('lora-raw-overlay');
            if (overlay) overlay.remove();
            overlay = document.createElement('div');
            overlay.id = 'lora-raw-overlay';
            overlay.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.5); z-index:270; display:flex; align-items:center; justify-content:center;';
            overlay.onclick = (e) => { if (e.target === overlay) overlay.remove(); };
            overlay.innerHTML = `<div style="background:var(--surface); border-radius:12px; padding:20px; max-width:700px; width:90%; max-height:85vh; display:flex; flex-direction:column; overflow:hidden;">
                <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px;">
                    <h3 style="margin:0;">프롬프트 Raw (${images.length}장 학습${testImages.length > 0 ? ', ' + testImages.length + '장 테스트' : ''})</h3>
                    <button onclick="document.getElementById('lora-raw-overlay').remove()" style="background:none; border:none; font-size:1.4rem; cursor:pointer; color:var(--text);">&times;</button>
                </div>
                <div style="flex:1; overflow-y:auto; display:flex; flex-direction:column; gap:12px;">
                    <div>
                        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:4px;">
                            <span style="font-weight:600; font-size:0.9rem;">긍정 프롬프트 Raw</span>
                            <button onclick="navigator.clipboard.writeText(document.getElementById('lora-raw-positive').textContent); showToast('복사 완료','success')" style="padding:2px 8px; font-size:0.75rem; background:var(--surface2); border:1px solid var(--border); border-radius:4px; cursor:pointer;">복사</button>
                        </div>
                        <pre id="lora-raw-positive" style="background:var(--surface2); padding:10px; border-radius:8px; font-size:0.8rem; white-space:pre-wrap; word-break:break-all; margin:0; max-height:300px; overflow-y:auto;">${escapeHtml(positiveRaw.trim())}</pre>
                    </div>
                    <div>
                        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:4px;">
                            <span style="font-weight:600; font-size:0.9rem;">부정 프롬프트 Raw</span>
                            <button onclick="navigator.clipboard.writeText(document.getElementById('lora-raw-negative').textContent); showToast('복사 완료','success')" style="padding:2px 8px; font-size:0.75rem; background:var(--surface2); border:1px solid var(--border); border-radius:4px; cursor:pointer;">복사</button>
                        </div>
                        <pre id="lora-raw-negative" style="background:var(--surface2); padding:10px; border-radius:8px; font-size:0.8rem; white-space:pre-wrap; word-break:break-all; margin:0; max-height:300px; overflow-y:auto;">${escapeHtml(negativeRaw.trim())}</pre>
                    </div>
                </div>
            </div>`;
            document.body.appendChild(overlay);
        }

        async function deleteLoraTrainingImage(filename) {
            if (!confirm(`"${filename}" 삭제하시겠습니까?`)) return;
            try {
                const resp = await fetchJSON('/api/lora/training_images/delete', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ character: loraCurrentCharacter, entry: loraCurrentEntry, filename })
                });
                if (resp.success) { showToast('삭제 완료', 'success'); await loadLoraTrainingImages(); }
                else { showToast(resp.error || '삭제 실패', 'error'); }
            } catch (e) { console.error('[LORA] 학습 이미지 삭제 실패:', e); showToast('삭제 실패', 'error'); }
        }

        // ─── 테스트 이미지 ─────────────────────────────────────
        async function loadLoraTestImages() {
            if (!loraCurrentCharacter || !loraCurrentEntry) return;
            const grid = document.getElementById('lora-test-grid');
            const section = document.getElementById('lora-test-section');
            const emptyEl = document.getElementById('lora-test-empty');
            const enc = encodeURIComponent;
            try {
                const resp = await fetchJSON(`/api/lora/test_images?character=${enc(loraCurrentCharacter)}&entry=${enc(loraCurrentEntry)}`);
                if (!resp.success) { showToast(resp.error || '테스트 이미지 로드 실패', 'error'); return; }
                const images = resp.images || [];
                section.style.display = '';
                if (images.length === 0) {
                    grid.style.display = 'none';
                    emptyEl.style.display = '';
                    return;
                }
                emptyEl.style.display = 'none';
                grid.style.display = '';
                grid.innerHTML = images.map(img => `
                    <div class="asset-image-card" style="cursor:default;">
                        <div style="position:relative; overflow:hidden; border-radius:8px;">
                            <img src="/api/lora/test_image/${enc(loraCurrentCharacter)}/${enc(loraCurrentEntry)}/${enc(img.filename)}" style="width:100%; display:block; cursor:zoom-in;" onclick="event.stopPropagation(); openLightbox(this.src)">
                            ${img.is_representative ? '<div style="position:absolute; top:4px; left:4px; z-index:70; background:rgba(255,193,7,0.95); color:#000; font-size:0.7rem; font-weight:700; padding:3px 8px; border-radius:4px;">대표</div>' : ''}
                        </div>
                        <div style="padding:8px;">
                            <div style="font-size:0.75rem; color:var(--text-secondary); margin-bottom:4px;">${escapeHtml(img.filename)}</div>
                            <div style="font-size:0.7rem; color:var(--text-secondary); margin-bottom:6px; max-height:40px; overflow:hidden;">${escapeHtml(img.positive || '(프롬프트 없음)')}</div>
                            <div style="display:flex; gap:4px; flex-wrap:wrap;">
                                <button onclick="showLoraTestPrompt('${escapeHtml(img.filename)}')" style="flex:1; padding:3px 6px; background:var(--surface2); color:var(--text); border:1px solid var(--border); border-radius:4px; cursor:pointer; font-size:0.7rem;">프롬프트</button>
                                <button onclick="deleteLoraTestImage('${escapeHtml(img.filename)}')" style="flex:1; padding:3px 6px; background:var(--error); color:#fff; border:none; border-radius:4px; cursor:pointer; font-size:0.7rem;">삭제</button>
                            </div>
                        </div>
                    </div>
                `).join('');
            } catch (e) {
                console.error('[LORA] 테스트 이미지 로드 실패:', e);
            }
        }

