        function showLoraTestPrompt(filename) {
            const enc = encodeURIComponent;
            fetchJSON(`/api/lora/test_images?character=${enc(loraCurrentCharacter)}&entry=${enc(loraCurrentEntry)}`).then(resp => {
                if (!resp.success) return;
                const img = resp.images.find(i => i.filename === filename);
                if (!img) return;
                const modal = document.getElementById('lora-image-picker-modal');
                document.getElementById('lora-picker-title').textContent = '프롬프트 편집 (테스트)';
                document.getElementById('lora-picker-footer').style.display = 'flex';
                document.getElementById('lora-picker-footer').innerHTML = `
                    <div style="display:flex; gap:6px; align-items:center; flex:1; flex-wrap:wrap;">
                        <button id="lora-test-llm-btn" type="button" style="padding:6px 12px;background:var(--accent);color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:0.8rem;font-weight:600;">🤖 LLM 정제</button>
                        <button type="button" onclick="_openBotTestSetupPromptModal(true)" style="padding:6px 12px;background:var(--surface2);color:var(--text);border:1px solid var(--border);border-radius:6px;cursor:pointer;font-size:0.8rem;">⚙️ LLM 프롬프트</button>
                        <span id="lora-test-refine-status" style="font-size:0.72rem;color:var(--text2);"></span>
                    </div>
                    <button onclick="closeLoraImagePicker()" style="padding:8px 16px; background:var(--surface2); color:var(--text); border:1px solid var(--border); border-radius:6px; cursor:pointer;">닫기</button>
                    <button onclick="saveLoraTestPrompt('${escapeHtml(filename)}')" style="padding:8px 16px; background:var(--accent); color:#fff; border:none; border-radius:6px; cursor:pointer; font-weight:600;">저장</button>
                `;
                // 🤖 LLM 정제 버튼: card_positive(학습 첫 이미지 positive) + 현재 테스트 프롬프트 조합 정제.
                // 정제 입력(test_positive)은 미리보기/전송 공통 단일 소스(_refineInputPositive)에서 가져온다.
                const _assetTestLlmBtn = document.getElementById('lora-test-llm-btn');
                if (_assetTestLlmBtn) {
                    _assetTestLlmBtn.onclick = async () => {
                        const test_positive = _refineInputPositive();
                        if (!test_positive) { showToast('정제할 테스트 프롬프트가 비어 있습니다', 'error'); return; }
                        let card_positive = '';
                        let card_filename = '';
                        try {
                            const enc = encodeURIComponent;
                            const r = await fetchJSON(`/api/lora/training_images?character=${enc(loraCurrentCharacter)}&entry=${enc(loraCurrentEntry)}`);
                            if (r && r.success && r.images && r.images.length) {
                                card_positive = (r.images[0].positive || '').trim();
                                card_filename = r.images[0].filename || '';
                            }
                        } catch (e) {
                            showToast(`카드 프롬프트 로드 실패: ${e.message}`, 'error');
                            return;
                        }
                        if (!card_positive) { showToast('카드(학습 첫 이미지) 프롬프트가 없습니다. 먼저 학습 이미지를 정제/수정하세요.', 'error'); return; }
                        _runLoraTestSetupRefine({
                            source_type: 'asset_test_setup',
                            character: loraCurrentCharacter, entry: loraCurrentEntry,
                            card_filename, card_positive, test_filename: filename, test_positive,
                            btn: _assetTestLlmBtn, statusEl: document.getElementById('lora-test-refine-status'),
                        });
                    };
                }
                const origPos = img.original_positive || img.positive || '';
                const origNeg = img.original_negative || img.negative || '';
                const curPos = img.positive || '';
                const curNeg = img.negative || '';
                const curPosTags = _tagSet(curPos);
                const origPosTags = _tagSet(origPos);
                const curNegTags = _tagSet(curNeg);
                const origNegTags = _tagSet(origNeg);
                const _roStyle = 'width:100%; padding:8px; border:1px solid var(--border); border-radius:6px; background:var(--surface2); color:var(--text-secondary); font-size:0.85rem; line-height:1.5; white-space:pre-wrap; word-wrap:break-word; overflow-y:auto; cursor:default;';
                const _editStyle = 'width:100%; padding:8px; border:1px solid var(--border); border-radius:6px; background:var(--surface); color:var(--text); font-size:0.85rem; line-height:1.5; white-space:pre-wrap; word-wrap:break-word; overflow-y:auto; outline:none; min-height:80px;';
                document.getElementById('lora-picker-body').innerHTML = `
                    <div style="display:flex; gap:16px; margin-bottom:12px;">
                        <img src="/api/lora/test_image/${enc(loraCurrentCharacter)}/${enc(loraCurrentEntry)}/${enc(filename)}" onclick="openLightbox(this.src)" style="width:120px; height:120px; object-fit:cover; border-radius:8px; display:block; flex-shrink:0; cursor:zoom-in;">
                        <div style="display:flex; align-items:center; font-size:0.85rem; color:var(--text-secondary);">${escapeHtml(filename)}</div>
                    </div>
                    <details style="margin-bottom:8px; border:1px solid var(--border); border-radius:6px; padding:6px 10px; background:var(--surface2);">
                        <summary style="cursor:pointer; font-size:0.85rem; font-weight:600; color:var(--error);">블록 태그 규칙</summary>
                        <div id="lora-block-rules-panel" style="margin-top:6px;"></div>
                    </details>
                    <div style="display:flex; gap:16px;">
                        <div style="flex:1; display:flex; flex-direction:column; gap:8px;">
                            <div style="font-size:0.85rem; font-weight:700; color:var(--text-secondary); text-align:center; margin-bottom:4px; display:flex; align-items:center; justify-content:center; gap:6px;"><span>원본</span><div class="mode-segment" id="orig-chip-toggle" style="display:inline-flex; align-items:center; border:1px solid var(--border); border-radius:6px; overflow:hidden;"><button class="mode-seg-btn active" data-mode="text" onclick="setOrigChipMode(false)" style="padding:2px 8px; font-size:0.7rem; font-weight:600; border:none; cursor:pointer; transition:background 0.2s, color 0.2s; background:var(--accent); color:#fff;">텍스트</button><button class="mode-seg-btn" data-mode="chips" onclick="setOrigChipMode(true)" style="padding:2px 8px; font-size:0.7rem; font-weight:600; border:none; cursor:pointer; transition:background 0.2s, color 0.2s; background:var(--surface2); color:var(--text2);">태그</button></div></div>
                            <div>
                                <label style="font-size:0.8rem; font-weight:600; display:block; margin-bottom:4px;">긍정 프롬프트</label>
                                <div id="lora-prompt-positive-orig" style="${_roStyle} max-height:200px;">${_renderPromptDiffSpans(origPos, curPosTags, 'rgba(220,50,50,0.12)')}</div>
                                <div id="lora-prompt-positive-orig-chips" class="lora-prompt-chips-container" style="display:none; max-height:200px; background:var(--surface2);"></div>
                            </div>
                            <div>
                                <label style="font-size:0.8rem; font-weight:600; display:block; margin-bottom:4px;">부정 프롬프트</label>
                                <div id="lora-prompt-negative-orig" style="${_roStyle} max-height:120px;">${_renderPromptDiffSpans(origNeg, curNegTags, 'rgba(220,50,50,0.12)')}</div>
                                <div id="lora-prompt-negative-orig-chips" class="lora-prompt-chips-container" style="display:none; max-height:120px; background:var(--surface2);"></div>
                            </div>
                        </div>
                        <div style="flex:1; display:flex; flex-direction:column; gap:8px;">
                            <div style="font-size:0.85rem; font-weight:700; color:var(--accent); margin-bottom:4px; display:flex; align-items:center; justify-content:space-between;"><span>수정</span><div style="display:flex; align-items:center; gap:12px;"><label title="태그 설명 툴팁" style="display:flex; align-items:center; gap:4px; font-size:0.7rem; font-weight:400; color:var(--text-secondary); cursor:pointer;">설명<input type="checkbox" onchange="toggleChipDesc(this.checked)" style="display:none;"><span style="position:relative; width:28px; height:16px; background:var(--border); border-radius:8px; transition:background 0.2s;"><span style="position:absolute; top:2px; left:2px; width:12px; height:12px; background:#fff; border-radius:50%; transition:left 0.2s;"></span></span></label><div class="mode-segment" id="lora-prompt-mode-toggle" style="display:inline-flex; align-items:center; border:1px solid var(--border); border-radius:6px; overflow:hidden;"><button class="mode-seg-btn active" data-mode="text" onclick="setLoraPromptEditMode('text')" style="padding:2px 8px; font-size:0.7rem; font-weight:600; border:none; cursor:pointer; transition:background 0.2s, color 0.2s; background:var(--accent); color:#fff;">텍스트</button><button class="mode-seg-btn" data-mode="chips" onclick="setLoraPromptEditMode('chips')" style="padding:2px 8px; font-size:0.7rem; font-weight:600; border:none; cursor:pointer; transition:background 0.2s, color 0.2s; background:var(--surface2); color:var(--text2);">태그</button></div></div></div>
                            <div>
                                <label style="font-size:0.8rem; font-weight:600; display:block; margin-bottom:4px;">긍정 프롬프트</label>
                                <div><div contenteditable="true" id="lora-prompt-positive" onpaste="event.preventDefault(); document.execCommand('insertText', false, event.clipboardData.getData('text/plain'));" style="${_editStyle} max-height:200px;">${_renderPromptDiffSpans(curPos, origPosTags, 'rgba(50,180,50,0.12)')}</div><div id="lora-prompt-positive-chips" class="lora-prompt-chips-container" style="display:none; max-height:200px;"></div></div>
                            </div>
                            <div>
                                <label style="font-size:0.8rem; font-weight:600; display:block; margin-bottom:4px;">부정 프롬프트</label>
                                <div><div contenteditable="true" id="lora-prompt-negative" onpaste="event.preventDefault(); document.execCommand('insertText', false, event.clipboardData.getData('text/plain'));" style="${_editStyle} max-height:120px;">${_renderPromptDiffSpans(curNeg, origNegTags, 'rgba(50,180,50,0.12)')}</div><div id="lora-prompt-negative-chips" class="lora-prompt-chips-container" style="display:none; max-height:120px;"></div></div>
                            </div>
                        </div>
                    </div>
                `;
                modal.style.display = 'flex';
                _loraPromptState = { origPos, origNeg, origPosTags, origNegTags };
                _origChipMode = false;
                loraPromptEditMode = 'text';
                setupPromptLiveDiff();
                _loadLoraBlockRules().then(() => _renderBlockRulesPanel());
            });
        }

        async function saveLoraTestPrompt(filename) {
            const positive = _readLoraPromptContent('positive');
            const negative = _readLoraPromptContent('negative');
            try {
                const resp = await fetchJSON('/api/lora/test_images/prompt', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ character: loraCurrentCharacter, entry: loraCurrentEntry, filename, positive, negative })
                });
                if (resp.success) { showToast('프롬프트 저장 완료', 'success'); closeLoraImagePicker(); await loadLoraTestImages(); }
                else { showToast(resp.error || '저장 실패', 'error'); }
            } catch (e) { console.error('[LORA] 테스트 프롬프트 저장 실패:', e); showToast('저장 실패', 'error'); }
        }

        // ─── LoRA 프롬프트 편집 모드 토글 ───
        let _loraPromptState = { mode: 'text', origPos: '', origNeg: '', origPosTags: new Set(), origNegTags: new Set() };
        let _loraPickerGender = ''; // 미리보기용: 현재 열린 프롬프트 편집 모달 캐릭터의 실제 gender_tag
        let _loraPickerCtx = { bot: '', char: '' }; // 미리보기용: 현재 열린 모달의 (봇, 캐릭터) — 서버 gender_tag 조회용
        let loraPromptEditMode = 'text';
        let _loraBlockRules = []; // 전역 블록 태그 규칙

        function _matchBlockRule(tag, rules) {
            if (!rules || !rules.length) return false;
            const t = tag.trim().toLowerCase();
            for (const rule of rules) {
                const r = rule.trim().toLowerCase();
                if (r.startsWith('* ')) {
                    if (t.endsWith(r.substring(2))) return true;
                } else if (r.endsWith(' *')) {
                    if (t.startsWith(r.slice(0, -2))) return true;
                } else {
                    if (t === r) return true;
                }
            }
            return false;
        }

        async function _loadLoraBlockRules() {
            try {
                const resp = await fetchJSON('/api/lora/block_tag_rules');
                if (resp.success) _loraBlockRules = resp.rules || [];
                else _loraBlockRules = [];
            } catch (e) {
                console.error('[LORA] 블록 규칙 로드 실패:', e);
                _loraBlockRules = [];
            }
        }

        async function _saveLoraBlockRules(rules) {
            try {
                const resp = await fetchJSON('/api/lora/block_tag_rules', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ rules })
                });
                if (resp.success) { _loraBlockRules = resp.rules; return true; }
                else { showToast(resp.error || '블록 규칙 저장 실패', 'error'); return false; }
            } catch (e) {
                console.error('[LORA] 블록 규칙 저장 실패:', e);
                showToast('블록 규칙 저장 실패', 'error');
                return false;
            }
        }

        function _renderBlockRulesPanel() {
            const panel = document.getElementById('lora-block-rules-panel');
            if (!panel) return;
            let html = '<div style="display:flex; flex-wrap:wrap; gap:4px; margin-bottom:8px;">';
            if (_loraBlockRules.length === 0) {
                html += '<span style="font-size:0.8rem; color:var(--text-secondary);">규칙 없음</span>';
            } else {
                _loraBlockRules.forEach((rule, i) => {
                    html += `<span style="display:inline-flex; align-items:center; gap:2px; background:rgba(220,50,50,0.12); border:1px solid rgba(220,50,50,0.3); border-radius:4px; padding:2px 6px; font-size:0.75rem; color:var(--error);">${escapeHtml(rule)}<span style="cursor:pointer; font-weight:bold; margin-left:2px;" onclick="_removeBlockRule(${i})">&times;</span></span>`;
                });
            }
            html += '</div>';
            html += '<div style="display:flex; gap:4px; margin-bottom:8px;">';
            html += '<input id="lora-block-rule-input" type="text" placeholder="예: * hair, * eyes" style="flex:1; padding:4px 8px; border:1px solid var(--border); border-radius:4px; background:var(--surface); color:var(--text); font-size:0.8rem;">';
            html += '<button onclick="_addBlockRule()" style="padding:4px 10px; background:var(--accent); color:#fff; border:none; border-radius:4px; font-size:0.8rem; cursor:pointer; font-weight:600;">추가</button>';
            html += '</div>';
            html += '<div style="display:flex; gap:4px;">';
            html += '<button onclick="_removeAllBlockedChips(\'positive\')" style="padding:4px 10px; background:rgba(220,50,50,0.15); color:var(--error); border:1px solid rgba(220,50,50,0.3); border-radius:4px; font-size:0.75rem; cursor:pointer;">긍정 매칭 전체 삭제</button>';
            html += '<button onclick="_removeAllBlockedChips(\'negative\')" style="padding:4px 10px; background:rgba(220,50,50,0.15); color:var(--error); border:1px solid rgba(220,50,50,0.3); border-radius:4px; font-size:0.75rem; cursor:pointer;">부정 매칭 전체 삭제</button>';
            html += '</div>';
            panel.innerHTML = html;
        }

        async function _addBlockRule() {
            const input = document.getElementById('lora-block-rule-input');
            if (!input || !input.value.trim()) return;
            const rule = input.value.trim();
            if (_loraBlockRules.includes(rule)) { showToast('이미 존재하는 규칙입니다', 'error'); return; }
            const newRules = [..._loraBlockRules, rule];
            if (await _saveLoraBlockRules(newRules)) {
                _renderBlockRulesPanel();
                _refreshLoraPromptWithBlockRules();
                input.value = '';
            }
        }

        async function _removeBlockRule(index) {
            const newRules = _loraBlockRules.filter((_, i) => i !== index);
            if (await _saveLoraBlockRules(newRules)) {
                _renderBlockRulesPanel();
                _refreshLoraPromptWithBlockRules();
            }
        }

        function _removeAllBlockedChips(field) {
            if (loraPromptEditMode !== 'chips') {
                // 텍스트 모드면 칩 모드로 전환 후 삭제
                toggleLoraPromptEditMode();
            }
            const container = document.getElementById('lora-prompt-' + field + '-chips');
            if (!container) return;
            const chips = container.querySelectorAll('.lora-prompt-chip.blocked');
            if (chips.length === 0) { showToast('매칭되는 태그가 없습니다', 'info'); return; }
            chips.forEach(c => c.remove());
            _updateLoraPromptDiff();
            showToast(`${chips.length}개 태그 삭제됨`, 'success');
        }

        function _refreshLoraPromptWithBlockRules() {
            const posText = _readLoraPromptContent('positive');
            const negText = _readLoraPromptContent('negative');
            _writeLoraPromptContent('positive', posText);
            _writeLoraPromptContent('negative', negText);
            _updateLoraPromptDiff();
        }

        function toggleLoraPromptEditMode() {
            setLoraPromptEditMode(loraPromptEditMode === 'text' ? 'chips' : 'text');
        }

        function setLoraPromptEditMode(mode) {
            const posText = _readLoraPromptContent('positive');
            const negText = _readLoraPromptContent('negative');
            loraPromptEditMode = mode;
            _writeLoraPromptContent('positive', posText);
            _writeLoraPromptContent('negative', negText);
            _updateLoraModeToggleBtn();
            _updateLoraPromptDiff();
        }

        function _readLoraPromptContent(field) {
            if (loraPromptEditMode === 'text') {
                const el = document.getElementById('lora-prompt-' + field);
                return el ? el.textContent : '';
            } else {
                const container = document.getElementById('lora-prompt-' + field + '-chips');
                if (!container) return '';
                return Array.from(container.querySelectorAll('.lora-prompt-chip'))
                    .map(c => c.dataset.tag).filter(t => t).join(', ');
            }
        }

        function _writeLoraPromptContent(field, text) {
            const textEl = document.getElementById('lora-prompt-' + field);
            const chipsEl = document.getElementById('lora-prompt-' + field + '-chips');
            if (loraPromptEditMode === 'text') {
                if (textEl) {
                    const origKey = field === 'positive' ? 'origPosTags' : 'origNegTags';
                    textEl.innerHTML = _renderPromptDiffSpans(text, _loraPromptState[origKey], 'rgba(50,180,50,0.12)');
                    textEl.style.display = '';
                }
                if (chipsEl) chipsEl.style.display = 'none';
            } else {
                if (textEl) textEl.style.display = 'none';
                if (chipsEl) {
                    const origKey = field === 'positive' ? 'origPosTags' : 'origNegTags';
                    chipsEl.innerHTML = _renderLoraPromptChips(text, _loraPromptState[origKey]);
                    chipsEl.style.display = '';
                }
            }
        }

        const _chipDescCache = {};
        let _chipDescEnabled = false;
        let _chipDescTimer = null;
        let _chipDescTooltip = null;

        function toggleChipDesc(checked) {
            _chipDescEnabled = checked;
            document.querySelectorAll('input[type="checkbox"][onchange*="toggleChipDesc"]').forEach(cb => {
                cb.checked = checked;
                const track = cb.nextElementSibling;
                const knob = track.querySelector('span');
                track.style.background = checked ? 'var(--accent)' : 'var(--border)';
                knob.style.left = checked ? '14px' : '2px';
            });
            if (!checked) _hideChipDesc();
            else { _hideChipDesc(); }  // 켤 때도 기존 툴팁 전부 제거
        }

        function _renderLoraPromptChips(text, origTagsSet) {
            if (!text) return '';
            const tags = text.split(',').map(t => t.trim()).filter(t => t);
            return tags.map(tag => {
                const isAdded = !origTagsSet.has(tag);
                const isBlocked = _matchBlockRule(tag, _loraBlockRules);
                let cls = 'lora-prompt-chip';
                if (isAdded) cls += ' added';
                if (isBlocked) cls += ' blocked';
                return '<span class="' + cls + '" data-tag="' + escapeHtml(tag) + '" onmouseenter="_showChipDesc(this)" onmouseleave="_hideChipDesc()">' + escapeHtml(tag) + '<span class="remove-chip" onclick="_removeLoraPromptChip(this)">&times;</span></span>';
            }).join('');
        }

        async function _showChipDesc(chipEl) {
            _hideChipDesc();
            if (!_chipDescEnabled) return;
            const tag = chipEl.dataset.tag;
            if (!tag) return;
            const key = tag.toLowerCase().replace(/_/g, ' ');
            _chipDescTimer = setTimeout(async () => {
                let desc = _chipDescCache[key];
                if (desc === undefined) {
                    try {
                        const query = tag.replace(/ /g, '_');
                        const resp = await fetch(`/api/autocomplete?query=${encodeURIComponent(query)}&limit=5`);
                        const results = await resp.json();
                        if (!results.length) { _chipDescCache[key] = null; return; }
                        const match = results.find(r => r.name === key) || results[0];
                        desc = match.description || null;
                        _chipDescCache[key] = desc;
                    } catch (e) { _chipDescCache[key] = null; return; }
                }
                if (!desc) return;
                const tip = document.createElement('div');
                tip.className = 'lora-chip-desc';
                tip.textContent = desc;
                document.body.appendChild(tip);
                const rect = chipEl.getBoundingClientRect();
                tip.style.left = rect.left + 'px';
                tip.style.top = (rect.bottom + 4) + 'px';
                _chipDescTooltip = tip;
            }, 200);
        }

        function _hideChipDesc() {
            clearTimeout(_chipDescTimer);
            document.querySelectorAll('.lora-chip-desc').forEach(el => el.remove());
            _chipDescTooltip = null;
        }

        function _removeLoraPromptChip(removeBtn) {
            removeBtn.parentElement.remove();
            _updateLoraPromptDiff();
        }

        function _updateLoraPromptDiff() {
            const posText = _readLoraPromptContent('positive');
            const negText = _readLoraPromptContent('negative');
            const origPosEl = document.getElementById('lora-prompt-positive-orig');
            const origNegEl = document.getElementById('lora-prompt-negative-orig');
            if (origPosEl) origPosEl.innerHTML = _renderPromptDiffSpans(_loraPromptState.origPos, _tagSet(posText), 'rgba(220,50,50,0.12)');
            if (origNegEl) origNegEl.innerHTML = _renderPromptDiffSpans(_loraPromptState.origNeg, _tagSet(negText), 'rgba(220,50,50,0.12)');
            if (_origChipMode) _refreshOrigChips();
        }

        function _updateLoraModeToggleBtn() {
            const seg = document.getElementById('lora-prompt-mode-toggle');
            if (!seg) return;
            seg.querySelectorAll('.mode-seg-btn').forEach(btn => {
                const isActive = btn.dataset.mode === loraPromptEditMode;
                btn.style.background = isActive ? 'var(--accent)' : 'var(--surface2)';
                btn.style.color = isActive ? '#fff' : 'var(--text2)';
                btn.classList.toggle('active', isActive);
            });
        }

        function _renderPromptDiffSpans(text, otherTagsSet, highlightColor) {
            if (!text) return '';
            const parts = text.split(',');
            return parts.map((part) => {
                const trimmed = part.trim();
                const isDiff = trimmed && !otherTagsSet.has(trimmed);
                const isBlocked = trimmed && _matchBlockRule(trimmed, _loraBlockRules);
                let bg = '';
                if (isBlocked) bg = 'rgba(220,50,50,0.2)';
                else if (isDiff) bg = highlightColor;
                const extraStyle = isBlocked ? '; color:var(--error); font-weight:600' : '';
                return `<span style="background:${bg}; border-radius:3px${extraStyle}">${escapeHtml(part)}</span>`;
            }).join(',');
        }

        function _tagSet(text) {
            return new Set(text.split(',').map(t => t.trim()).filter(t => t));
        }

        let _origChipMode = false;

        function _renderLoraOrigChips(text, otherTagsSet, field) {
            if (!text) return '';
            const tags = text.split(',').map(t => t.trim()).filter(t => t);
            const editTags = _tagSet(_readLoraPromptContent(field));
            return tags.map(tag => {
                const isDiff = !otherTagsSet.has(tag);
                const isBlocked = _matchBlockRule(tag, _loraBlockRules);
                const alreadyInEdit = editTags.has(tag);
                let cls = 'lora-orig-chip';
                if (isBlocked) cls += ' blocked-tag';
                else if (isDiff) cls += ' diff-tag';
                if (alreadyInEdit) cls += ' already-in-edit';
                return '<span class="' + cls + '" data-tag="' + escapeHtml(tag) + '" onmouseenter="_showOrigChipDesc(this)" onmouseleave="_hideOrigChipDesc()">' + escapeHtml(tag) + '<button class="send-to-edit" onclick="_sendTagToEdit(\'' + field + '\', \'' + escapeHtml(tag).replace(/'/g, "\\'") + '\')" title="수정으로 보내기">&#10132;</button></span>';
            }).join('');
        }

        async function _showOrigChipDesc(chipEl) {
            _hideOrigChipDesc();
            if (!_chipDescEnabled) return;
            const tag = chipEl.dataset.tag;
            if (!tag) return;
            const key = tag.toLowerCase().replace(/_/g, ' ');
            _chipDescTimer = setTimeout(async () => {
                let desc = _chipDescCache[key];
                if (desc === undefined) {
                    try {
                        const query = tag.replace(/ /g, '_');
                        const resp = await fetch(`/api/autocomplete?query=${encodeURIComponent(query)}&limit=5`);
                        const results = await resp.json();
                        if (!results.length) { _chipDescCache[key] = null; return; }
                        const match = results.find(r => r.name === key) || results[0];
                        desc = match.description || null;
                        _chipDescCache[key] = desc;
                    } catch (e) { _chipDescCache[key] = null; return; }
                }
                if (!desc) return;
                const tip = document.createElement('div');
                tip.className = 'lora-chip-desc';
                tip.textContent = desc;
                document.body.appendChild(tip);
                const rect = chipEl.getBoundingClientRect();
                tip.style.left = rect.left + 'px';
                tip.style.top = (rect.bottom + 4) + 'px';
                _chipDescTooltip = tip;
            }, 200);
        }

        function _hideOrigChipDesc() {
            clearTimeout(_chipDescTimer);
            document.querySelectorAll('.lora-chip-desc').forEach(el => el.remove());
            _chipDescTooltip = null;
        }

        function _sendTagToEdit(field, tag) {
            const currentText = _readLoraPromptContent(field);
            const currentTags = currentText.split(',').map(t => t.trim()).filter(t => t);
            if (currentTags.includes(tag)) return;
            currentTags.push(tag);
            const newText = currentTags.join(', ');
            _writeLoraPromptContent(field, newText);
            _refreshOrigChips();
            _updateLoraPromptDiff();
        }

        function _refreshOrigChips() {
            const posText = _readLoraPromptContent('positive');
            const negText = _readLoraPromptContent('negative');
            const origPosChipsEl = document.getElementById('lora-prompt-positive-orig-chips');
            const origNegChipsEl = document.getElementById('lora-prompt-negative-orig-chips');
            if (origPosChipsEl) origPosChipsEl.innerHTML = _renderLoraOrigChips(_loraPromptState.origPos, _tagSet(posText), 'positive');
            if (origNegChipsEl) origNegChipsEl.innerHTML = _renderLoraOrigChips(_loraPromptState.origNeg, _tagSet(negText), 'negative');
        }

        function toggleOrigChipMode() {
            setOrigChipMode(!_origChipMode);
        }

        function setOrigChipMode(chipMode) {
            _origChipMode = chipMode;
            ['positive', 'negative'].forEach(field => {
                const textEl = document.getElementById('lora-prompt-' + field + '-orig');
                const chipsEl = document.getElementById('lora-prompt-' + field + '-orig-chips');
                if (textEl) textEl.style.display = _origChipMode ? 'none' : '';
                if (chipsEl) chipsEl.style.display = _origChipMode ? '' : 'none';
            });
            const seg = document.getElementById('orig-chip-toggle');
            if (seg) {
                seg.querySelectorAll('.mode-seg-btn').forEach(btn => {
                    const isActive = btn.dataset.mode === (_origChipMode ? 'chips' : 'text');
                    btn.style.background = isActive ? 'var(--accent)' : 'var(--surface2)';
                    btn.style.color = isActive ? '#fff' : 'var(--text2)';
                    btn.classList.toggle('active', isActive);
                });
            }
            if (_origChipMode) _refreshOrigChips();
        }

        // ─── 프롬프트 텍스트 모드 자동완성 ───
        const _pac = { dropdown: null, activeIdx: -1, items: [], visible: false, timer: null, targetEl: null };

        function _initPromptAutocomplete() {
            if (!_pac.dropdown) {
                _pac.dropdown = document.createElement('div');
                _pac.dropdown.className = 'prompt-autocomplete-dropdown';
                _pac.dropdown.style.display = 'none';
                document.body.appendChild(_pac.dropdown);
            }
        }

        function _getCursorTextOffset(el) {
            const sel = window.getSelection();
            if (!sel.rangeCount) return -1;
            const range = sel.getRangeAt(0);
            const preRange = document.createRange();
            preRange.selectNodeContents(el);
            preRange.setEnd(range.startContainer, range.startOffset);
            return preRange.toString().length;
        }

        function _getCurrentTagWord(el) {
            const cursorPos = _getCursorTextOffset(el);
            if (cursorPos < 0) return null;
            const text = el.textContent;
            let start = text.lastIndexOf(',', cursorPos - 1);
            start = start === -1 ? 0 : start + 1;
            while (start < cursorPos && text[start] === ' ') start++;
            const word = text.substring(start, cursorPos);
            return { start, end: cursorPos, word: word.trim(), text };
        }

        function _showPromptAutocomplete(el, items) {
            _initPromptAutocomplete();
            if (!items.length) { _hidePromptAutocomplete(); return; }
            _pac.items = items;
            _pac.activeIdx = -1;
            _pac.targetEl = el;

            const sel = window.getSelection();
            if (!sel.rangeCount) { _hidePromptAutocomplete(); return; }
            const range = sel.getRangeAt(0);
            const rect = range.getBoundingClientRect();

            _pac.dropdown.innerHTML = items.map((item, i) =>
                '<div class="prompt-autocomplete-item" data-idx="' + i + '" onmousedown="_pacSelect(' + i + '); event.preventDefault();">' +
                    '<span class="tag-name">' + escapeHtml(item.name) + '</span>' +
                    (item.description ? '<span class="tag-desc">' + escapeHtml(item.description) + '</span>' : '') +
                '</div>'
            ).join('');

            let left = rect.left;
            let top = rect.bottom + 4;
            if (left + 300 > window.innerWidth) left = window.innerWidth - 310;
            if (top + 220 > window.innerHeight) top = rect.top - 224;
            _pac.dropdown.style.left = Math.max(4, left) + 'px';
            _pac.dropdown.style.top = top + 'px';
            _pac.dropdown.style.display = 'block';
            _pac.visible = true;
        }

        function _hidePromptAutocomplete() {
            if (_pac.dropdown) _pac.dropdown.style.display = 'none';
            _pac.visible = false;
            _pac.activeIdx = -1;
            _pac.items = [];
        }

        function _pacSelect(idx) {
            const item = _pac.items[idx];
            if (!item || !_pac.targetEl) return;
            const el = _pac.targetEl;
            const wordInfo = _getCurrentTagWord(el);
            if (!wordInfo) { _hidePromptAutocomplete(); return; }

            const text = wordInfo.text;
            const before = text.substring(0, wordInfo.start);
            const after = text.substring(wordInfo.end);
            const afterTrimmed = after.trimStart();
            const suffix = afterTrimmed.length === 0 ? ', ' : '';
            const newText = before + item.name + suffix + after;

            el.textContent = newText;
            _updateLoraPromptDiff();
            _hidePromptAutocomplete();

            el.focus();
            const newPos = before.length + item.name.length + suffix.length;
            const textNode = el.firstChild;
            if (textNode && textNode.nodeType === 3 && newPos <= textNode.length) {
                const newRange = document.createRange();
                newRange.setStart(textNode, newPos);
                newRange.collapse(true);
                const sel = window.getSelection();
                sel.removeAllRanges();
                sel.addRange(newRange);
            }
        }

        function _pacNavigate(direction) {
            if (!_pac.visible || !_pac.items.length) return;
            _pac.activeIdx += direction;
            if (_pac.activeIdx < 0) _pac.activeIdx = _pac.items.length - 1;
            if (_pac.activeIdx >= _pac.items.length) _pac.activeIdx = 0;
            const items = _pac.dropdown.querySelectorAll('.prompt-autocomplete-item');
            items.forEach((el, i) => el.classList.toggle('active', i === _pac.activeIdx));
            if (items[_pac.activeIdx]) items[_pac.activeIdx].scrollIntoView({ block: 'nearest' });
        }

        function _onPromptAutocompleteInput(el) {
            if (loraPromptEditMode !== 'text') { _hidePromptAutocomplete(); return; }
            clearTimeout(_pac.timer);
            const wordInfo = _getCurrentTagWord(el);
            if (!wordInfo || wordInfo.word.length < 2) { _hidePromptAutocomplete(); return; }
            _pac.targetEl = el;
            _pac.timer = setTimeout(async () => {
                try {
                    const query = wordInfo.word.replace(/ /g, '_');
                    const resp = await fetch('/api/autocomplete?query=' + encodeURIComponent(query) + '&limit=10');
                    const results = await resp.json();
                    _showPromptAutocomplete(el, results);
                } catch (e) { _hidePromptAutocomplete(); }
            }, 200);
        }

        function _onPromptAutocompleteKeydown(e) {
            if (!_pac.visible) return false;
            if (e.key === 'ArrowDown') { e.preventDefault(); _pacNavigate(1); return true; }
            if (e.key === 'ArrowUp') { e.preventDefault(); _pacNavigate(-1); return true; }
            if (e.key === 'Enter' || e.key === 'Tab') {
                if (_pac.activeIdx >= 0) { e.preventDefault(); _pacSelect(_pac.activeIdx); return true; }
                _hidePromptAutocomplete();
            }
            if (e.key === 'Escape') { e.preventDefault(); _hidePromptAutocomplete(); return true; }
            return false;
        }

        function setupPromptLiveDiff() {
            const editPosEl = document.getElementById('lora-prompt-positive');
            const editNegEl = document.getElementById('lora-prompt-negative');
            if (!editPosEl || !editNegEl) return;

            editPosEl.oninput = editNegEl.oninput = function() {
                if (loraPromptEditMode === 'text') {
                    _updateLoraPromptDiff();
                    _onPromptAutocompleteInput(this);
                }
            };
            editPosEl.onfocus = function() {
                if (loraPromptEditMode === 'text') {
                    const text = this.textContent;
                    this.textContent = text;
                }
            };
            editNegEl.onfocus = function() {
                if (loraPromptEditMode === 'text') {
                    const text = this.textContent;
                    this.textContent = text;
                }
            };
            editPosEl.onblur = function() {
                if (loraPromptEditMode === 'text') {
                    this.innerHTML = _renderPromptDiffSpans(this.textContent, _loraPromptState.origPosTags, 'rgba(50,180,50,0.12)');
                }
                setTimeout(_hidePromptAutocomplete, 150);
            };
            editNegEl.onblur = function() {
                if (loraPromptEditMode === 'text') {
                    this.innerHTML = _renderPromptDiffSpans(this.textContent, _loraPromptState.origNegTags, 'rgba(50,180,50,0.12)');
                }
                setTimeout(_hidePromptAutocomplete, 150);
            };
            editPosEl.onkeydown = editNegEl.onkeydown = function(e) {
                _onPromptAutocompleteKeydown(e);
            };
            _syncChipDescToggles();
        }

        function showLoraTrainingPrompt(filename) {
            const grid = document.getElementById('lora-training-grid');
            const card = grid.querySelector(`[onclick*="${filename}"]`);
            // 프롬프트 편집 모달 열기
            const enc = encodeURIComponent;
            fetchJSON(`/api/lora/training_images?character=${enc(loraCurrentCharacter)}&entry=${enc(loraCurrentEntry)}`).then(resp => {
                if (!resp.success) return;
                const img = resp.images.find(i => i.filename === filename);
                if (!img) return;
                const modal = document.getElementById('lora-image-picker-modal');
                document.getElementById('lora-picker-title').textContent = '프롬프트 편집';
                document.getElementById('lora-picker-footer').style.display = 'flex';
                document.getElementById('lora-picker-footer').innerHTML = `
                    <div style="display:flex; gap:6px; align-items:center; flex:1; flex-wrap:wrap;">
                        <button id="lora-training-llm-btn" type="button" style="padding:6px 12px;background:var(--accent);color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:0.8rem;font-weight:600;">🤖 LLM 정제</button>
                        <button type="button" onclick="_openAutoLoraPromptModal(true)" style="padding:6px 12px;background:var(--surface2);color:var(--text);border:1px solid var(--border);border-radius:6px;cursor:pointer;font-size:0.8rem;">⚙️ LLM 프롬프트</button>
                        <span id="lora-training-refine-status" style="font-size:0.72rem;color:var(--text2);"></span>
                    </div>
                    <button onclick="closeLoraImagePicker()" style="padding:8px 16px; background:var(--surface2); color:var(--text); border:1px solid var(--border); border-radius:6px; cursor:pointer;">닫기</button>
                    <button onclick="saveLoraTrainingPrompt('${escapeHtml(filename)}')" style="padding:8px 16px; background:var(--accent); color:#fff; border:none; border-radius:6px; cursor:pointer; font-weight:600;">저장</button>
                `;
                // LLM 정제 버튼 바인딩 (설정 값은 클릭 시점에 읽음)
                _loraPickerCtx = { bot: (typeof botCurrentBot !== 'undefined' && botCurrentBot) || '', char: loraCurrentCharacter };
                _loraPickerGender = _resolveRealGenderTag(_loraPickerCtx.bot, loraCurrentCharacter);
                const _llmBtn = document.getElementById('lora-training-llm-btn');
                if (_llmBtn) {
                    const _ctx = { character: loraCurrentCharacter, entry: loraCurrentEntry, filename };
                    _llmBtn.onclick = () => {
                        // 정제 입력({etc})은 미리보기와 동일한 단일 소스에서 가져온다 (분리 금지).
                        const positive = _refineInputPositive();
                        _runLoraPromptRefine({
                            source_type: 'training',
                            character: _ctx.character,
                            entry: _ctx.entry,
                            filename: _ctx.filename,
                            positive,
                            is_asset: true,
                            btn: _llmBtn,
                            statusEl: document.getElementById('lora-training-refine-status'),
                        });
                    };
                }
                const origPos = img.original_positive || img.positive || '';
                const origNeg = img.original_negative || img.negative || '';
                const curPos = img.positive || '';
                const curNeg = img.negative || '';
                const curPosTags = _tagSet(curPos);
                const origPosTags = _tagSet(origPos);
                const curNegTags = _tagSet(curNeg);
                const origNegTags = _tagSet(origNeg);
                const _roStyle = 'width:100%; padding:8px; border:1px solid var(--border); border-radius:6px; background:var(--surface2); color:var(--text-secondary); font-size:0.85rem; line-height:1.5; white-space:pre-wrap; word-wrap:break-word; overflow-y:auto; cursor:default;';
                const _editStyle = 'width:100%; padding:8px; border:1px solid var(--border); border-radius:6px; background:var(--surface); color:var(--text); font-size:0.85rem; line-height:1.5; white-space:pre-wrap; word-wrap:break-word; overflow-y:auto; outline:none; min-height:80px;';
                document.getElementById('lora-picker-body').innerHTML = `
                    <div style="display:flex; gap:16px; margin-bottom:12px;">
                        <img src="/api/lora/training_image/${enc(loraCurrentCharacter)}/${enc(loraCurrentEntry)}/${enc(filename)}" onclick="openLightbox(this.src)" style="width:120px; height:120px; object-fit:cover; border-radius:8px; display:block; flex-shrink:0; cursor:zoom-in;">
                        <div style="display:flex; align-items:center; font-size:0.85rem; color:var(--text-secondary);">${escapeHtml(filename)}</div>
                    </div>
                    <details style="margin-bottom:8px; border:1px solid var(--border); border-radius:6px; padding:6px 10px; background:var(--surface2);">
                        <summary style="cursor:pointer; font-size:0.85rem; font-weight:600; color:var(--error);">블록 태그 규칙</summary>
                        <div id="lora-block-rules-panel" style="margin-top:6px;"></div>
                    </details>
                    <div style="display:flex; gap:16px;">
                        <div style="flex:1; display:flex; flex-direction:column; gap:8px;">
                            <div style="font-size:0.85rem; font-weight:700; color:var(--text-secondary); text-align:center; margin-bottom:4px; display:flex; align-items:center; justify-content:center; gap:6px;"><span>원본</span><div class="mode-segment" id="orig-chip-toggle" style="display:inline-flex; align-items:center; border:1px solid var(--border); border-radius:6px; overflow:hidden;"><button class="mode-seg-btn active" data-mode="text" onclick="setOrigChipMode(false)" style="padding:2px 8px; font-size:0.7rem; font-weight:600; border:none; cursor:pointer; transition:background 0.2s, color 0.2s; background:var(--accent); color:#fff;">텍스트</button><button class="mode-seg-btn" data-mode="chips" onclick="setOrigChipMode(true)" style="padding:2px 8px; font-size:0.7rem; font-weight:600; border:none; cursor:pointer; transition:background 0.2s, color 0.2s; background:var(--surface2); color:var(--text2);">태그</button></div></div>
                            <div>
                                <label style="font-size:0.8rem; font-weight:600; display:block; margin-bottom:4px;">긍정 프롬프트</label>
                                <div id="lora-prompt-positive-orig" style="${_roStyle} max-height:200px;">${_renderPromptDiffSpans(origPos, curPosTags, 'rgba(220,50,50,0.12)')}</div>
                                <div id="lora-prompt-positive-orig-chips" class="lora-prompt-chips-container" style="display:none; max-height:200px; background:var(--surface2);"></div>
                            </div>
                            <div>
                                <label style="font-size:0.8rem; font-weight:600; display:block; margin-bottom:4px;">부정 프롬프트</label>
                                <div id="lora-prompt-negative-orig" style="${_roStyle} max-height:120px;">${_renderPromptDiffSpans(origNeg, curNegTags, 'rgba(220,50,50,0.12)')}</div>
                                <div id="lora-prompt-negative-orig-chips" class="lora-prompt-chips-container" style="display:none; max-height:120px; background:var(--surface2);"></div>
                            </div>
                        </div>
                        <div style="flex:1; display:flex; flex-direction:column; gap:8px;">
                            <div style="font-size:0.85rem; font-weight:700; color:var(--accent); margin-bottom:4px; display:flex; align-items:center; justify-content:space-between;"><span>수정</span><div style="display:flex; align-items:center; gap:12px;"><label title="태그 설명 툴팁" style="display:flex; align-items:center; gap:4px; font-size:0.7rem; font-weight:400; color:var(--text-secondary); cursor:pointer;">설명<input type="checkbox" onchange="toggleChipDesc(this.checked)" style="display:none;"><span style="position:relative; width:28px; height:16px; background:var(--border); border-radius:8px; transition:background 0.2s;"><span style="position:absolute; top:2px; left:2px; width:12px; height:12px; background:#fff; border-radius:50%; transition:left 0.2s;"></span></span></label><div class="mode-segment" id="lora-prompt-mode-toggle" style="display:inline-flex; align-items:center; border:1px solid var(--border); border-radius:6px; overflow:hidden;"><button class="mode-seg-btn active" data-mode="text" onclick="setLoraPromptEditMode('text')" style="padding:2px 8px; font-size:0.7rem; font-weight:600; border:none; cursor:pointer; transition:background 0.2s, color 0.2s; background:var(--accent); color:#fff;">텍스트</button><button class="mode-seg-btn" data-mode="chips" onclick="setLoraPromptEditMode('chips')" style="padding:2px 8px; font-size:0.7rem; font-weight:600; border:none; cursor:pointer; transition:background 0.2s, color 0.2s; background:var(--surface2); color:var(--text2);">태그</button></div></div></div>
                            <div>
                                <label style="font-size:0.8rem; font-weight:600; display:block; margin-bottom:4px;">긍정 프롬프트</label>
                                <div><div contenteditable="true" id="lora-prompt-positive" onpaste="event.preventDefault(); document.execCommand('insertText', false, event.clipboardData.getData('text/plain'));" style="${_editStyle} max-height:200px;">${_renderPromptDiffSpans(curPos, origPosTags, 'rgba(50,180,50,0.12)')}</div><div id="lora-prompt-positive-chips" class="lora-prompt-chips-container" style="display:none; max-height:200px;"></div></div>
                            </div>
                            <div>
                                <label style="font-size:0.8rem; font-weight:600; display:block; margin-bottom:4px;">부정 프롬프트</label>
                                <div><div contenteditable="true" id="lora-prompt-negative" onpaste="event.preventDefault(); document.execCommand('insertText', false, event.clipboardData.getData('text/plain'));" style="${_editStyle} max-height:120px;">${_renderPromptDiffSpans(curNeg, origNegTags, 'rgba(50,180,50,0.12)')}</div><div id="lora-prompt-negative-chips" class="lora-prompt-chips-container" style="display:none; max-height:120px;"></div></div>
                            </div>
                        </div>
                    </div>
                `;
                modal.style.display = 'flex';
                _loraPromptState = { origPos, origNeg, origPosTags, origNegTags };
                _origChipMode = false;
                loraPromptEditMode = 'text';
                setupPromptLiveDiff();
                _loadLoraBlockRules().then(() => _renderBlockRulesPanel());
            });
        }

        async function saveLoraTrainingPrompt(filename) {
            const positive = _readLoraPromptContent('positive');
            const negative = _readLoraPromptContent('negative');
            try {
                const resp = await fetchJSON('/api/lora/training_images/prompt', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ character: loraCurrentCharacter, entry: loraCurrentEntry, filename, positive, negative })
                });
                if (resp.success) { showToast('프롬프트 저장 완료', 'success'); closeLoraImagePicker(); await loadLoraTrainingImages(); }
                else { showToast(resp.error || '저장 실패', 'error'); }
            } catch (e) { console.error('[LORA] 프롬프트 저장 실패:', e); showToast('저장 실패', 'error'); }
        }

        // ─── LoRA 이미지 피커 ─────────────────────────────────
        function openLoraImagePicker(target = 'training') {
            if (!loraCurrentCharacter) { showToast('먼저 캐릭터를 선택하세요', 'error'); return; }
            loraPickerTarget = target;
            loraPickerState = { level: 'characters', pickerCharacter: loraCurrentCharacter, outfit: '', expression: '', selected: new Set(), scroll: {} };
            document.getElementById('lora-picker-title').textContent = target === 'test' ? '테스트 이미지 선택' : '학습용 이미지 선택';
            document.getElementById('lora-picker-footer').style.display = 'flex';
            document.getElementById('lora-picker-footer').innerHTML = `
                <span id="lora-picker-count" style="font-size:0.85rem; color:var(--text-secondary);"></span>
                <button onclick="loraPickerConfirm()" style="padding:8px 20px; background:var(--accent); color:#fff; border:none; border-radius:6px; cursor:pointer; font-weight:600;">선택 완료</button>
            `;
            const modal = document.getElementById('lora-image-picker-modal');
            modal.style.display = 'flex';
            loadLoraPickerCharacters();
        }

        function _loraPickerSearchHtml(id, placeholder) {
            return '<div style="margin-bottom:10px;">'
                + '<input type="text" id="' + id + '" placeholder="' + placeholder + '" autocomplete="off" '
                + 'style="width:100%; padding:7px 10px; border:1px solid var(--border); border-radius:6px; '
                + 'background:var(--surface2); color:var(--text); font-size:0.85rem; box-sizing:border-box;">'
                + '<div id="' + id + '-empty" style="display:none; text-align:center; padding:20px; '
                + 'color:var(--text-secondary); font-size:0.85rem;">검색 결과가 없습니다.</div>'
                + '</div>';
        }

        function _loraPickerSaveScroll() {
            const body = document.getElementById('lora-picker-body');
            if (!body || !loraPickerState) {
                console.error('[LORA] 피커 스크롤 저장 대상 없음:', {
                    bodyFound: !!body,
                    stateFound: !!loraPickerState
                });
                return;
            }
            if (!loraPickerState.scroll) loraPickerState.scroll = {};
            let key = loraPickerState.level;
            if (key === 'images') {
                key = 'images:' + loraPickerState.outfit + '|||' + loraPickerState.expression;
            }
            loraPickerState.scroll[key] = body.scrollTop;
        }

        function _loraPickerRestoreScroll(key) {
            const body = document.getElementById('lora-picker-body');
            if (!body || !loraPickerState) {
                console.error('[LORA] 피커 스크롤 복원 대상 없음:', key, {
                    bodyFound: !!body,
                    stateFound: !!loraPickerState
                });
                return;
            }
            const targetY = (loraPickerState.scroll || {})[key] || 0;
            if (!targetY) return;

            const images = Array.from(body.querySelectorAll('img'));
            const previousOverflowAnchor = body.style.overflowAnchor;
            let tries = 0;
            let stable = 0;
            let cancelled = false;

            const assertPosition = function() {
                if (!cancelled && Math.abs(body.scrollTop - targetY) > 2) body.scrollTop = targetY;
            };
            const stop = function() {
                if (cancelled) return;
                cancelled = true;
                body.removeEventListener('wheel', stop);
                body.removeEventListener('touchstart', stop);
                images.forEach(function(image) { image.removeEventListener('load', assertPosition); });
                body.style.overflowAnchor = previousOverflowAnchor;
            };

            body.style.overflowAnchor = 'none';
            body.addEventListener('wheel', stop, { passive: true });
            body.addEventListener('touchstart', stop, { passive: true });
            images.forEach(function(image) {
                if (!image.complete) image.addEventListener('load', assertPosition);
            });

            const tick = function() {
                if (cancelled) return;
                if (Math.abs(body.scrollTop - targetY) <= 2) {
                    if (++stable >= 3) {
                        stop();
                        return;
                    }
                } else {
                    stable = 0;
                    body.scrollTop = targetY;
                }
                if (++tries < 60) setTimeout(tick, 50);
                else stop();
            };
            requestAnimationFrame(tick);
        }

        function _loraPickerNorm(value) {
            return String(value == null ? '' : value)
                .toLowerCase()
                .replace(/[\s\-_/\\.,()\[\]|]+/g, '');
        }

        function _loraPickerBindSearch(inputId, itemSelector, textOf) {
            const input = document.getElementById(inputId);
            if (!input) {
                console.error('[LORA] 피커 검색 입력칸 없음:', inputId);
                return;
            }
            const emptyElement = document.getElementById(inputId + '-empty');
            const apply = function() {
                const raw = input.value.trim();
                const tokens = raw ? raw.split(/\s+/).map(_loraPickerNorm).filter(Boolean) : [];
                let shown = 0;
                document.querySelectorAll(itemSelector).forEach(function(element) {
                    const haystack = _loraPickerNorm(textOf(element));
                    const matches = tokens.length === 0 || tokens.every(function(token) {
                        return haystack.includes(token);
                    });
                    element.style.display = matches ? '' : 'none';
                    if (matches) shown++;
                });
                if (emptyElement) {
                    emptyElement.style.display = tokens.length && shown === 0 ? 'block' : 'none';
                }
            };
            input.addEventListener('input', apply);
            input.addEventListener('compositionupdate', apply);
            input.addEventListener('compositionend', apply);
            try {
                input.focus({ preventScroll: true });
            } catch (error) {
                console.warn('[LORA] preventScroll 포커스 미지원, 기본 포커스 사용:', error);
                input.focus();
            }
        }

        function closeLoraImagePicker() {
            document.getElementById('lora-image-picker-modal').style.display = 'none';
            _loraPickerGender = '';
            _loraPickerCtx = { bot: '', char: '' };
            _hideChipDesc();
        }

        function _syncChipDescToggles() {
            document.querySelectorAll('input[type="checkbox"][onchange*="toggleChipDesc"]').forEach(cb => {
                cb.checked = _chipDescEnabled;
                const track = cb.nextElementSibling;
                const knob = track.querySelector('span');
                track.style.background = _chipDescEnabled ? 'var(--accent)' : 'var(--border)';
                knob.style.left = _chipDescEnabled ? '14px' : '2px';
            });
        }

        function loadLoraPickerCharacters() {
            const state = loraPickerState;
            const body = document.getElementById('lora-picker-body');
            state.level = 'characters';
            body.innerHTML = '<div style="text-align:center; padding:32px;"><div class="spinner" style="width:32px;height:32px;border-width:3px;margin:0 auto;"></div></div>';
            fetchJSON('/api/lora/characters').then(function(resp) {
                if (loraPickerState !== state || state.level !== 'characters') {
                    console.warn('[LORA] 만료된 캐릭터 목록 응답 폐기');
                    return;
                }
                if (!resp || !resp.success || !resp.characters || resp.characters.length === 0) {
                    body.innerHTML = '<div style="text-align:center; padding:32px; color:var(--text-secondary);">캐릭터가 없습니다.</div>';
                    return;
                }
                const countInfo = state.selected.size > 0 ? ' (현재 ' + state.selected.size + '장 선택됨)' : '';
                let html = '<div style="margin-bottom:8px; font-size:0.85rem; color:var(--text-secondary);">에셋을 탐색할 캐릭터를 선택하세요' + countInfo + '</div>';
                html += _loraPickerSearchHtml('lora-picker-char-search', '캐릭터 검색...');
                html += '<div id="lora-picker-char-grid" style="display:grid; grid-template-columns:repeat(auto-fill, minmax(120px, 1fr)); gap:10px;">';
                resp.characters.forEach(function(name) {
                    const border = name === state.pickerCharacter ? 'border-color:var(--accent);' : '';
                    html += '<div class="asset-folder-card" data-name="' + escapeHtml(name) + '" onclick="enterLoraPickerCharacter(\'' + escapeHtml(name) + '\')" style="' + border + '">';
                    html += '<div class="folder-icon">📁</div>';
                    html += '<div class="folder-name">' + escapeHtml(name) + '</div>';
                    html += '</div>';
                });
                html += '</div>';
                body.innerHTML = html;
                _loraPickerBindSearch(
                    'lora-picker-char-search',
                    '#lora-picker-char-grid .asset-folder-card',
                    function(element) { return element.getAttribute('data-name') || ''; }
                );
                loraPickerUpdateCount();
                _loraPickerRestoreScroll('characters');
            }).catch(function(e) {
                console.error('[LORA] 캐릭터 목록 로드 실패:', e);
                if (loraPickerState !== state || state.level !== 'characters') {
                    console.warn('[LORA] 만료된 캐릭터 실패 응답 화면 반영 생략');
                    return;
                }
                body.innerHTML = '<div style="text-align:center; padding:32px; color:var(--error);">로드 실패</div>';
            });
        }

        function enterLoraPickerCharacter(character) {
            _loraPickerSaveScroll();
            loraPickerState.pickerCharacter = character;
            loadLoraPickerGallery();
        }

        function loadLoraPickerGallery() {
            const state = loraPickerState;
            const body = document.getElementById('lora-picker-body');
            const enc = encodeURIComponent;
            const pickerChar = state.pickerCharacter;
            state.level = 'gallery';
            body.innerHTML = '<div style="text-align:center; padding:32px;"><div class="spinner" style="width:32px;height:32px;border-width:3px;margin:0 auto;"></div></div>';

            fetchJSON('/api/asset_mode/characters/' + enc(pickerChar) + '/gallery').then(function(resp) {
                if (loraPickerState !== state || state.level !== 'gallery' || state.pickerCharacter !== pickerChar) {
                    console.warn('[LORA] 만료된 갤러리 응답 폐기:', pickerChar);
                    return;
                }
                if (!resp || !resp.gallery || resp.gallery.length === 0) {
                    body.innerHTML = '<div style="margin-bottom:12px;"><button id="lora-picker-back-chars" style="padding:4px 12px; background:var(--surface2); color:var(--text); border:1px solid var(--border); border-radius:4px; cursor:pointer; font-size:0.8rem;">&larr; 캐릭터 선택</button></div><div style="text-align:center; padding:32px; color:var(--text-secondary);">표시할 이미지가 없습니다.</div>';
                    document.getElementById('lora-picker-back-chars').addEventListener('click', function() {
                        _loraPickerSaveScroll();
                        loadLoraPickerCharacters();
                    });
                    return;
                }

                let html = '<div style="margin-bottom:12px; display:flex; align-items:center; gap:8px;">';
                html += '<button id="lora-picker-back-chars" style="padding:4px 12px; background:var(--surface2); color:var(--text); border:1px solid var(--border); border-radius:4px; cursor:pointer; font-size:0.8rem;">&larr; 캐릭터 선택</button>';
                html += '<span style="font-size:0.85rem; color:var(--text-secondary);">' + escapeHtml(pickerChar) + '</span>';
                html += '<button id="lora-picker-toggle-all" style="padding:4px 12px; background:var(--surface2); color:var(--text); border:1px solid var(--border); border-radius:4px; cursor:pointer; font-size:0.8rem; margin-left:auto;">전체 선택/해제</button>';
                html += '</div>';
                html += _loraPickerSearchHtml('lora-picker-gallery-search', '의상 / 표정 검색...');
                html += '<div class="asset-gallery-grid" id="lora-picker-gallery-grid">';
                resp.gallery.forEach(function(item) {
                    html += '<div class="asset-gallery-item" data-outfit="' + escapeHtml(item.outfit) + '" data-expression="' + escapeHtml(item.expression) + '" style="cursor:pointer;">';
                    if (item.representative) {
                        html += '<img src="/api/asset_mode/characters/' + enc(pickerChar) + '/outfits/' + enc(item.outfit) + '/expressions/' + enc(item.expression) + '/images/' + enc(item.representative) + '" style="width:100%; display:block; border-radius:6px;">';
                    } else {
                        html += '<div style="width:100%; padding:32px; background:var(--surface2); border-radius:6px; display:flex; align-items:center; justify-content:center; color:var(--text-secondary); font-size:0.8rem;">No img</div>';
                    }
                    var label = escapeHtml(item.outfit) + ' / ' + escapeHtml(item.expression);
                    if (item.image_count > 1) label += ' (' + item.image_count + '장)';
                    html += '<div style="font-size:0.75rem; margin-top:4px; text-align:center;">' + label + '</div>';
                    html += '</div>';
                });
                html += '</div>';
                body.innerHTML = html;

                // 이벤트 리스너 부착
                const backBtn = document.getElementById('lora-picker-back-chars');
                if (backBtn) {
                    backBtn.addEventListener('click', function() {
                        _loraPickerSaveScroll();
                        loadLoraPickerCharacters();
                    });
                }
                document.getElementById('lora-picker-toggle-all').addEventListener('click', loraPickerToggleSelectAll);
                document.querySelectorAll('#lora-picker-gallery-grid .asset-gallery-item').forEach(function(el) {
                    el.addEventListener('click', function() {
                        _loraPickerSaveScroll();
                        loadLoraPickerImages(this.getAttribute('data-outfit'), this.getAttribute('data-expression'));
                    });
                });
                _loraPickerBindSearch(
                    'lora-picker-gallery-search',
                    '#lora-picker-gallery-grid .asset-gallery-item',
                    function(element) {
                        return (element.getAttribute('data-outfit') || '') + ' '
                            + (element.getAttribute('data-expression') || '');
                    }
                );

                loraPickerUpdateCount();
                _loraPickerRestoreScroll('gallery');
            }).catch(function(e) {
                console.error('[LORA] 갤러리 로드 실패:', e);
                if (loraPickerState !== state || state.level !== 'gallery') {
                    console.warn('[LORA] 만료된 갤러리 실패 응답 화면 반영 생략:', pickerChar);
                    return;
                }
                body.innerHTML = '<div style="text-align:center; padding:32px; color:var(--error);">로드 실패</div>';
            });
        }

        function loadLoraPickerImages(outfit, expression) {
            const state = loraPickerState;
            const body = document.getElementById('lora-picker-body');
            const enc = encodeURIComponent;
            const pickerChar = state.pickerCharacter;
            state.outfit = outfit;
            state.expression = expression;
            state.level = 'images';

            let headerHtml = '<div style="margin-bottom:12px; display:flex; align-items:center; gap:8px;">';
            headerHtml += '<button id="lora-picker-back-gallery" style="padding:4px 12px; background:var(--surface2); color:var(--text); border:1px solid var(--border); border-radius:4px; cursor:pointer; font-size:0.8rem;">&larr; 갤러리</button>';
            headerHtml += '<span style="font-size:0.85rem; color:var(--text-secondary);">' + escapeHtml(pickerChar) + ' / ' + escapeHtml(outfit) + ' / ' + escapeHtml(expression) + '</span>';
            headerHtml += '<button id="lora-picker-img-toggle-all" style="padding:4px 12px; background:var(--surface2); color:var(--text); border:1px solid var(--border); border-radius:4px; cursor:pointer; font-size:0.8rem; margin-left:auto;">전체 선택/해제</button>';
            headerHtml += '</div>';
            headerHtml += _loraPickerSearchHtml('lora-picker-img-search', '파일명 검색...');
            headerHtml += '<div id="lora-picker-images-grid" style="display:grid; grid-template-columns:repeat(3, 1fr); gap:8px;">';
            headerHtml += '<div class="spinner" style="width:32px;height:32px;border-width:3px;margin:16px auto;"></div>';
            headerHtml += '</div>';
            body.innerHTML = headerHtml;

            document.getElementById('lora-picker-back-gallery').addEventListener('click', function() {
                _loraPickerSaveScroll();
                loadLoraPickerGallery();
            });
            document.getElementById('lora-picker-img-toggle-all').addEventListener('click', loraPickerToggleSelectAll);

            fetchJSON('/api/asset_mode/characters/' + enc(pickerChar) + '/outfits/' + enc(outfit) + '/expressions/' + enc(expression) + '/images').then(function(resp) {
                if (
                    loraPickerState !== state
                    || state.level !== 'images'
                    || state.pickerCharacter !== pickerChar
                    || state.outfit !== outfit
                    || state.expression !== expression
                ) {
                    console.warn('[LORA] 만료된 이미지 목록 응답 폐기:', pickerChar, outfit, expression);
                    return;
                }
                if (!resp || !resp.images || resp.images.length === 0) {
                    document.getElementById('lora-picker-images-grid').innerHTML = '<div style="text-align:center; padding:16px; color:var(--text-secondary); grid-column:1/-1;">이미지가 없습니다.</div>';
                    return;
                }

                const grid = document.getElementById('lora-picker-images-grid');
                let html = '';
                resp.images.forEach(function(img) {
                    const key = pickerChar + '|||' + outfit + '|||' + expression + '|||' + img.filename;
                    const checked = state.selected.has(key);
                    const imgUrl = '/api/asset_mode/characters/' + enc(pickerChar) + '/outfits/' + enc(outfit) + '/expressions/' + enc(expression) + '/images/' + enc(img.filename);
                    const borderColor = checked ? 'var(--accent)' : 'transparent';
                    const bgColor = checked ? 'var(--accent)' : 'rgba(0,0,0,0.3)';
                    const checkMark = checked ? '&#10003;' : '';
                    html += '<div data-key="' + escapeHtml(key) + '" data-filename="' + escapeHtml(img.filename) + '" style="position:relative; cursor:pointer; border-radius:6px; overflow:hidden; border:2px solid ' + borderColor + '; transition:border-color 0.15s;">';
                    html += '<img src="' + imgUrl + '" style="width:100%; display:block;">';
                    html += '<div style="position:absolute; top:4px; right:4px; width:20px; height:20px; border-radius:50%; background:' + bgColor + '; display:flex; align-items:center; justify-content:center; color:#fff; font-size:0.7rem;">' + checkMark + '</div>';
                    if (img.is_representative) {
                        html += '<div style="position:absolute; top:4px; left:4px; z-index:70; background:rgba(255,193,7,0.95); color:#000; font-size:0.65rem; font-weight:700; padding:2px 6px; border-radius:4px;">대표</div>';
                    }
                    html += '</div>';
                });
                grid.innerHTML = html;
                // 이미지 클릭 이벤트
                grid.querySelectorAll('[data-key]').forEach(function(el) {
                    el.addEventListener('click', function() {
                        loraPickerToggle(this, this.getAttribute('data-key'));
                    });
                });
                _loraPickerBindSearch(
                    'lora-picker-img-search',
                    '#lora-picker-images-grid [data-filename]',
                    function(element) { return element.getAttribute('data-filename') || ''; }
                );
                _loraPickerRestoreScroll('images:' + outfit + '|||' + expression);
            }).catch(function(e) {
                console.error('[LORA] 이미지 로드 실패:', e);
                if (
                    loraPickerState !== state
                    || state.level !== 'images'
                    || state.outfit !== outfit
                    || state.expression !== expression
                ) {
                    console.warn('[LORA] 만료된 이미지 실패 응답 화면 반영 생략:', pickerChar, outfit, expression);
                    return;
                }
                const grid = document.getElementById('lora-picker-images-grid');
                if (grid) {
                    grid.innerHTML = '<div style="text-align:center; padding:16px; color:var(--error); grid-column:1/-1;">로드 실패</div>';
                }
            });
        }

        function loraPickerToggle(el, key) {
            if (loraPickerState.selected.has(key)) {
                loraPickerState.selected.delete(key);
                el.style.borderColor = 'transparent';
                el.querySelector('div').style.background = 'rgba(0,0,0,0.3)';
                el.querySelector('div').textContent = '';
            } else {
                loraPickerState.selected.add(key);
                el.style.borderColor = 'var(--accent)';
                el.querySelector('div').style.background = 'var(--accent)';
                el.querySelector('div').textContent = '✓';
            }
            loraPickerUpdateCount();
        }

        async function _loraPickerLoadGalleryKeys(groups, pickerCharacter, maxConcurrency = 4) {
            const specs = groups.map(function(element) {
                return {
                    outfit: element.getAttribute('data-outfit') || '',
                    expression: element.getAttribute('data-expression') || ''
                };
            });
            const keys = new Set();
            const failures = [];
            let nextIndex = 0;

            const worker = async function() {
                while (nextIndex < specs.length) {
                    const spec = specs[nextIndex++];
                    if (!spec.outfit || !spec.expression) {
                        const error = new Error('의상 또는 표정 식별자가 비어 있습니다.');
                        console.error('[LORA] 전체 선택 그룹 식별 실패:', spec, error);
                        failures.push({ ...spec, error: error.message });
                        continue;
                    }
                    const url = '/api/asset_mode/characters/' + encodeURIComponent(pickerCharacter)
                        + '/outfits/' + encodeURIComponent(spec.outfit)
                        + '/expressions/' + encodeURIComponent(spec.expression) + '/images';
                    try {
                        const response = await fetchJSON(url);
                        if (!response || !Array.isArray(response.images)) {
                            throw new Error('이미지 목록 응답 형식이 올바르지 않습니다.');
                        }
                        response.images.forEach(function(image) {
                            if (!image || !image.filename) {
                                console.error('[LORA] 전체 선택 이미지 파일명 누락:', spec, image);
                                failures.push({ ...spec, error: '이미지 파일명 누락' });
                                return;
                            }
                            keys.add(
                                pickerCharacter + '|||' + spec.outfit + '|||'
                                + spec.expression + '|||' + image.filename
                            );
                        });
                    } catch (error) {
                        console.error('[LORA] 전체 선택 이미지 목록 로드 실패:', spec, url, error);
                        failures.push({
                            ...spec,
                            error: error && error.message ? error.message : String(error)
                        });
                    }
                }
            };

            const workerCount = Math.min(Math.max(1, maxConcurrency), specs.length);
            await Promise.all(Array.from({ length: workerCount }, worker));
            return { keys: Array.from(keys), failures };
        }

        async function loraPickerToggleSelectAll() {
            if (!loraPickerState) {
                console.error('[LORA] 전체 선택 실패: 피커 상태가 없습니다.');
                return;
            }

            if (loraPickerState.level === 'images') {
                const items = Array.from(
                    document.querySelectorAll('#lora-picker-images-grid [data-key]')
                ).filter(function(element) {
                    return element.style.display !== 'none';
                });
                if (!items.length) {
                    console.error('[LORA] 전체 선택 실패: 현재 보이는 이미지가 없습니다.');
                    showToast('선택할 이미지가 없습니다', 'error');
                    return;
                }
                const allSelected = items.every(function(element) {
                    return loraPickerState.selected.has(element.getAttribute('data-key'));
                });
                items.forEach(function(element) {
                    const key = element.getAttribute('data-key');
                    if (loraPickerState.selected.has(key) === allSelected) {
                        loraPickerToggle(element, key);
                    }
                });
                showToast(
                    (allSelected ? '전체 해제' : '전체 선택') + ' (' + items.length + '장)',
                    'success'
                );
                return;
            }

            if (loraPickerState.level !== 'gallery') {
                console.error('[LORA] 전체 선택 실패: 지원하지 않는 피커 단계:', loraPickerState.level);
                return;
            }

            const groups = Array.from(
                document.querySelectorAll('#lora-picker-gallery-grid .asset-gallery-item')
            ).filter(function(element) {
                return element.style.display !== 'none';
            });
            if (!groups.length) {
                console.error('[LORA] 전체 선택 실패: 현재 보이는 갤러리 항목이 없습니다.');
                showToast('선택할 항목이 없습니다', 'error');
                return;
            }

            const button = document.getElementById('lora-picker-toggle-all');
            if (!button) {
                console.error('[LORA] 전체 선택 실패: 실행 버튼을 찾을 수 없습니다.');
                showToast('전체 선택 버튼을 찾을 수 없습니다', 'error');
                return;
            }
            const originalText = button.textContent;
            const requestState = loraPickerState;
            const pickerCharacter = requestState.pickerCharacter;
            const modal = document.getElementById('lora-image-picker-modal');
            button.disabled = true;
            button.textContent = '불러오는 중...';

            try {
                const result = await _loraPickerLoadGalleryKeys(groups, pickerCharacter, 4);
                if (
                    loraPickerState !== requestState
                    || requestState.level !== 'gallery'
                    || (modal && modal.style.display === 'none')
                ) {
                    console.warn('[LORA] 전체 선택 결과 폐기: 처리 중 피커 상태가 변경되었습니다.', {
                        pickerCharacter,
                        currentLevel: loraPickerState && loraPickerState.level
                    });
                    return;
                }
                if (result.failures.length > 0) {
                    console.error('[LORA] 전체 선택 중 일부 그룹 로드 실패, 선택 변경 취소:', result.failures);
                    showToast(
                        '전체 선택 실패: ' + result.failures.length
                            + '개 항목을 불러오지 못해 선택을 변경하지 않았습니다',
                        'error'
                    );
                    return;
                }
                if (!result.keys.length) {
                    console.error('[LORA] 전체 선택 실패: 불러온 이미지 키가 없습니다.', {
                        pickerCharacter,
                        groupCount: groups.length
                    });
                    showToast('불러온 이미지가 없습니다', 'error');
                    return;
                }

                const allSelected = result.keys.every(function(key) {
                    return requestState.selected.has(key);
                });
                result.keys.forEach(function(key) {
                    if (allSelected) requestState.selected.delete(key);
                    else requestState.selected.add(key);
                });
                loraPickerUpdateCount();
                showToast(
                    (allSelected ? '전체 해제' : '전체 선택') + ' (' + result.keys.length + '장)',
                    'success'
                );
            } catch (error) {
                console.error('[LORA] 전체 선택 처리 중 예외:', {
                    pickerCharacter,
                    groupCount: groups.length
                }, error);
                showToast('전체 선택 처리에 실패했습니다', 'error');
            } finally {
                button.disabled = false;
                button.textContent = originalText;
            }
        }

        function loraPickerUpdateCount() {
            const el = document.getElementById('lora-picker-count');
            if (el) el.textContent = `${loraPickerState.selected.size}장 선택됨`;
        }

        async function loraPickerConfirm() {
            if (loraPickerState.selected.size === 0) {
                showToast('이미지를 선택하세요', 'error');
                return;
            }
            const sources = [];
            for (const key of loraPickerState.selected) {
                const [sourceChar, outfit, expression, filename] = key.split('|||');
                sources.push({ character: sourceChar, outfit, expression, filename });
            }

            // 봇 LoRA 테스트 이미지 모드
            if (loraPickerTarget === 'bot_test') {
                try {
                    const resp = await fetchJSON('/api/bot_lora/test_images/add', {
                        method: 'POST', headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ bot: botLoraCurrentBot, project: botLoraCurrentProject, sources })
                    });
                    if (resp.success) {
                        const msg = `${resp.added.length}장 추가됨${resp.skipped.length > 0 ? ` (${resp.skipped.length}장 스킵)` : ''}`;
                        showToast(msg, 'success');
                        closeLoraImagePicker();
                        await loadBotLoraProject();
                    } else {
                        showToast(resp.error || '추가 실패', 'error');
                    }
                } catch (e) {
                    console.error('[BOT_LORA] 이미지 추가 실패:', e);
                    showToast('추가 실패', 'error');
                }
                return;
            }

            // 봇 LoRA 캐릭터별 테스트 이미지 모드
            if (loraPickerTarget === 'bot_char_test') {
                try {
                    const resp = await fetchJSON('/api/bot_lora/char_test_images/add', {
                        method: 'POST', headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ bot: botLoraCurrentBot, project: botLoraCurrentProject, character: botLoraCharTestTarget, visual_card_id: botLoraCharTestTargetCard, sources })
                    });
                    if (resp.success) {
                        const msg = `${resp.added.length}장 추가됨${resp.skipped.length > 0 ? ` (${resp.skipped.length}장 스킵)` : ''}`;
                        showToast(msg, 'success');
                        closeLoraImagePicker();
                        await loadBotLoraProject();
                    } else {
                        showToast(resp.error || '추가 실패', 'error');
                    }
                } catch (e) {
                    console.error('[BOT_LORA] 캐릭터 테스트 이미지 추가 실패:', e);
                    showToast('추가 실패', 'error');
                }
                return;
            }

            // 그림체(스타일) LoRA 테스트 이미지 모드
            if (loraPickerTarget === 'style_test') {
                try {
                    const images = sources.map(s => ({
                        type: 'asset', character: s.character, outfit: s.outfit, expression: s.expression, filename: s.filename
                    }));
                    const resp = await fetchJSON('/api/style_lora/test_images/add', {
                        method: 'POST', headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ project: _styleLora.currentProject, images })
                    });
                    if (resp.success) {
                        const ok = (resp.results || []).filter(r => r.success).length;
                        const fail = (resp.results || []).length - ok;
                        showToast(`${ok}장 추가 완료${fail ? ` (${fail}장 실패)` : ''}`, fail ? 'error' : 'success');
                        closeLoraImagePicker();
                        await loadStyleTestImages();
                        renderStyleTestImageGrid();
                    } else {
                        showToast(resp.error || '추가 실패', 'error');
                    }
                } catch (e) {
                    console.error('[STYLE_LORA] 테스트 이미지 추가 실패:', e);
                    showToast(`추가 실패: ${e.message || e}`, 'error');
                }
                return;
            }

            // 인스턴스 로라 생성 모드
            if (loraPickerTarget === 'instance_create') {
                for (const src of sources) {
                    // 에셋 이미지 경로 구성
                    const srcType = _instanceCreatePickerSource;
                    _instanceCreateFiles.push({
                        type: srcType,
                        source: { ...src, type: srcType },
                        previewUrl: null,
                    });
                }
                showToast(`${sources.length}장 선택됨`, 'success');
                closeLoraImagePicker();
                // 에셋 이미지 미리보기 로드
                for (const f of _instanceCreateFiles) {
                    if (!f.previewUrl && f.source) {
                        const s = f.source;
                        try {
                            const imgUrl = `/api/asset_mode/characters/${encodeURIComponent(s.character)}/outfits/${encodeURIComponent(s.outfit)}/expressions/${encodeURIComponent(s.expression)}/images/${encodeURIComponent(s.filename)}`;
                            f.previewUrl = imgUrl;
                        } catch (e) {}
                    }
                }
                renderInstanceCreatePreview();
                return;
            }

            const apiUrl = loraPickerTarget === 'test' ? '/api/lora/test_images/add' : '/api/lora/training_images/add';
            try {
                const resp = await fetchJSON(apiUrl, {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ character: loraCurrentCharacter, entry: loraCurrentEntry, sources })
                });
                if (resp.success) {
                    const msg = `${resp.added.length}장 추가됨${resp.skipped.length > 0 ? ` (${resp.skipped.length}장 스킵)` : ''}`;
                    showToast(msg, 'success');
                    closeLoraImagePicker();
                    if (loraPickerTarget === 'test') {
                        await loadLoraTestImages();
                    } else {
                        await loadLoraTrainingImages();
                    }
                } else {
                    showToast(resp.error || '추가 실패', 'error');
                }
            } catch (e) {
                console.error('[LORA] 이미지 추가 실패:', e);
                showToast('추가 실패', 'error');
            }
        }

        function formatFileSize(bytes) {
            if (bytes < 1024) return bytes + ' B';
            if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
            return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
        }

        // 드래그앤드롭 초기화
        document.addEventListener('DOMContentLoaded', () => {
            const dropzone = document.getElementById('at-dropzone');
            if (dropzone) {
                dropzone.addEventListener('dragover', (e) => { e.preventDefault(); dropzone.classList.add('dragover'); });
                dropzone.addEventListener('dragleave', () => { dropzone.classList.remove('dragover'); });
                dropzone.addEventListener('drop', (e) => {
                    e.preventDefault();
                    dropzone.classList.remove('dragover');
                    if (e.dataTransfer.files.length) atOnFilesSelected(e.dataTransfer.files);
                });
            }
            if (typeof restoreBotCurrentBotLightweight === 'function') {
                restoreBotCurrentBotLightweight();
            }
        });

        // ─── 캐릭터 메이커 ─────────────────────────────────────
        const CM_FIELDS = ['appearance', 'outfit', 'expression', 'composition'];
        // 잠금(LLM 수정 보호) 대상: 태그 필드 4종 + 자연어. 백엔드 LOCKABLE_FIELDS와 대응.
        const CM_LOCKABLE = [...CM_FIELDS, 'natural_language'];
        const CM_FIELD_LABELS = {
            appearance: '외모',
            outfit: '복장',
            expression: '표정',
            composition: '구도/기타',
        };
        // 생성 설정 프리셋 중 자유 편집으로 꺼낼 수 있는 항목.
        // 이 목록은 LLM 수정 계약(CM_FIELDS/CM_LOCKABLE)에 절대 포함하지 않는다.
        const CM_EDITABLE_PRESETS = {
            quality_preset: { label: 'ILXL 품질', selectId: 'cm-setting-quality', toggleId: 'cm-pull-quality', category: 'quality_presets', rawSlotKey: 'raw_quality_tags' },
            artist_preset: { label: 'ILXL 아티스트', selectId: 'cm-setting-artist', toggleId: 'cm-pull-artist', category: 'artist_presets', rawSlotKey: 'raw_artist_tags' },
            negative_preset: { label: 'ILXL 부정', selectId: 'cm-setting-negative', toggleId: 'cm-pull-negative', category: 'negative_presets', rawSlotKey: 'raw_negative_tags' },
            anima_quality_preset: { label: 'ANIMA 품질', selectId: 'cm-setting-anima-quality', toggleId: 'cm-pull-anima-quality', category: 'quality_presets', rawSlotKey: 'raw_anima_quality_tags' },
            anima_artist_preset: { label: 'ANIMA 아티스트', selectId: 'cm-setting-anima-artist', toggleId: 'cm-pull-anima-artist', category: 'artist_presets', rawSlotKey: 'raw_anima_artist_tags' },
            anima_negative_preset: { label: 'ANIMA 부정', selectId: 'cm-setting-anima-negative', toggleId: 'cm-pull-anima-negative', category: 'negative_presets', rawSlotKey: 'raw_anima_negative_tags' },
            character_negative_preset: { label: '캐릭터 부정', selectId: 'cm-setting-char-negative', toggleId: 'cm-pull-char-negative', category: 'character_negative_presets', rawSlotKey: 'raw_character_negative_tags' },
        };
        const CM_EDITABLE_PRESET_FIELDS = Object.keys(CM_EDITABLE_PRESETS);
        // 캐릭터 메이커는 단일 영속 세션 하나만 사용한다. 서버가 디스크에서 로드/보존하므로
        // 브라우저에 세션 식별자를 따로 저장하지 않는다.
        const CM_SINGLE_SESSION_ID = 'default';
        // 시드 모드('random'|'fixed')는 프론트엔드 전용 상태. 시드 값 자체는 항상 구체적
        // 숫자로 송출하므로(-1 사용 안 함) 'random'이면 생성 직전에 새 시드를 굴린다.
        const CM_SEED_MODE_STORAGE_KEY = 'characterMakerSeedMode';
        let cmSeedMode = 'random';
        let cmSession = null;
        let cmCapabilities = null;
        let cmInitialized = false;
        let cmBusy = false;
        let cmSyncTimer = null;
        let cmSyncVersion = 0;
        let cmLastDiff = null;
        let cmRagVerified = false;

        async function cmRequest(url, options = {}) {
            const response = await fetch(url, options);
            let data = {};
            try {
                data = await response.json();
            } catch (error) {
                console.error('[CHARACTER_MAKER] API 응답 JSON 해석 실패:', url, response.status, error);
            }
            if (!response.ok || data.error || data.success === false) {
                const error = new Error(data.error || `HTTP ${response.status}`);
                error.status = response.status;
                error.data = data;
                throw error;
            }
            return data;
        }

        function cmCurrentPayload() {
            return {
                world_context: cmSession?.world_context || '',
                natural_language: cmSession?.natural_language || '',
                fields: Object.fromEntries(CM_FIELDS.map(field => [
                    field,
                    [...(cmSession?.fields?.[field] || [])],
                ])),
                locks: Object.fromEntries(CM_LOCKABLE.map(field => [
                    field,
                    !!cmSession?.locks?.[field],
                ])),
                editable_preset_tags: Object.fromEntries(CM_EDITABLE_PRESET_FIELDS.map(field => [
                    field,
                    [...(cmSession?.editable_preset_tags?.[field] || [])],
                ])),
                editable_preset_enabled: Object.fromEntries(CM_EDITABLE_PRESET_FIELDS.map(field => [
                    field,
                    !!cmSession?.editable_preset_enabled?.[field],
                ])),
                settings: cmCollectSettings(),
            };
        }

        function cmCurrentGenerationState() {
            if (!cmSession) return null;
            cmEnsureEditablePresetState();
            return {
                settings: cmCollectSettings(),
                editable_preset_tags: Object.fromEntries(
                    CM_EDITABLE_PRESET_FIELDS.map(field => [
                        field,
                        [...(cmSession.editable_preset_tags[field] || [])],
                    ])
                ),
                editable_preset_enabled: Object.fromEntries(
                    CM_EDITABLE_PRESET_FIELDS.map(field => [
                        field,
                        !!cmSession.editable_preset_enabled[field],
                    ])
                ),
            };
        }

        async function cmCreateSession(generationState = null) {
            // POST = 캐릭터 작업만 비우고 생성 설정 전체를 서버에서 보존한다.
            // 현재 브라우저에 아직 디바운스 중인 변경도 함께 보내 서버 상태보다 우선한다.
            const options = { method: 'POST' };
            if (generationState) {
                options.headers = { 'Content-Type': 'application/json' };
                options.body = JSON.stringify(generationState);
            }
            const data = await cmRequest('/api/character_maker/session', options);
            cmSession = data.session;
            cmLastDiff = null;
            return cmSession;
        }

        async function cmLoadOrCreateSession() {
            // 단일 영속 세션: 항상 동일한 id로 조회. 서버가 디스크에서 복원해 반환한다.
            const data = await cmRequest(`/api/character_maker/session/${encodeURIComponent(CM_SINGLE_SESSION_ID)}`);
            cmSession = data.session;
            cmLastDiff = null;
            return cmSession;
        }

        async function initCharacterMaker() {
            cmBindReferenceDrop();
            cmInitSplitHandle();
            if (!assetTags) {
                try {
                    await loadAssetData();
                } catch (error) {
                    console.error('[CHARACTER_MAKER] 프리셋 데이터 로드 실패:', error);
                    showToast('캐릭터 메이커 프리셋을 불러오지 못했습니다.', 'error');
                    return;
                }
            }

            try {
                const capabilityData = await cmRequest('/api/character_maker/capabilities');
                cmCapabilities = capabilityData;
            } catch (error) {
                console.error('[CHARACTER_MAKER] 기능 상태 조회 실패:', error);
                cmCapabilities = {
                    vision: { ready: false, service: '' },
                    rag: { enabled: false, url: '' },
                };
            }
            // 단일 영속 세션: 서버 재시작에도 같은 세션이 살아있으므로 boot_id 불일치로
            // 폐기하지 않는다. 페이지 로드마다 서버에서 최신 상태를 가져온다.
            if (!cmSession) {
                cmSetBusy(true, '작업공간을 불러오는 중...');
                try {
                    await cmLoadOrCreateSession();
                } catch (error) {
                    console.error('[CHARACTER_MAKER] 세션 준비 실패:', error);
                    showToast('캐릭터 메이커 세션 준비 실패: ' + error.message, 'error');
                    cmSetBusy(false);
                    return;
                }
                cmSetBusy(false);
            }

            cmPopulatePresetOptions();
            cmApplySettingsToUI();
            const savedEditorMode = sessionStorage.getItem('characterMakerEditorMode') || 'chip';
            cmSetEditorMode(savedEditorMode, false);
            cmRender();
            cmInitialized = true;
            requestAnimationFrame(cmAlignSettingsWall);
        }

        function cmInitSplitHandle() {
            const canvas = document.getElementById('cm-canvas');
            const handle = document.getElementById('cm-split-handle');
            if (!canvas || !handle || handle.dataset.bound === '1') return;
            handle.dataset.bound = '1';

            const applyRatio = ratio => {
                const clamped = Math.min(0.88, Math.max(0.12, ratio));
                canvas.style.setProperty('--cm-split', clamped.toFixed(4));
                return clamped;
            };
            // 저장된 비율 복원.
            try {
                const saved = parseFloat(localStorage.getItem('cm-split-ratio'));
                if (Number.isFinite(saved)) applyRatio(saved);
            } catch (error) {
                console.error('[CHARACTER_MAKER] 분할 비율 복원 실패:', error);
            }

            let dragging = false;
            const onMove = event => {
                if (!dragging) return;
                const rect = canvas.getBoundingClientRect();
                if (!rect.width) return;
                const ratio = (event.clientX - rect.left) / rect.width;
                applyRatio(ratio);
            };
            const onUp = event => {
                if (!dragging) return;
                dragging = false;
                handle.classList.remove('dragging');
                try {
                    handle.releasePointerCapture(event.pointerId);
                } catch (error) { /* 무시 */ }
                const ratio = parseFloat(canvas.style.getPropertyValue('--cm-split'));
                if (Number.isFinite(ratio)) {
                    try { localStorage.setItem('cm-split-ratio', String(ratio)); }
                    catch (error) { console.error('[CHARACTER_MAKER] 분할 비율 저장 실패:', error); }
                }
                window.removeEventListener('pointermove', onMove);
                window.removeEventListener('pointerup', onUp);
            };
            handle.addEventListener('pointerdown', event => {
                event.preventDefault();
                dragging = true;
                handle.classList.add('dragging');
                try { handle.setPointerCapture(event.pointerId); }
                catch (error) { /* 무시 */ }
                window.addEventListener('pointermove', onMove);
                window.addEventListener('pointerup', onUp);
            });
        }

        function cmBindReferenceDrop() {
            const drop = document.getElementById('cm-reference-drop');
            if (!drop || drop.dataset.bound === '1') return;
            drop.dataset.bound = '1';
            drop.addEventListener('dragover', event => {
                event.preventDefault();
                drop.classList.add('dragover');
            });
            drop.addEventListener('dragleave', () => drop.classList.remove('dragover'));
            drop.addEventListener('drop', event => {
                event.preventDefault();
                drop.classList.remove('dragover');
                if (event.dataTransfer?.files?.length) cmUploadReferences(event.dataTransfer.files);
            });
        }

        function cmCleanTags(value) {
            const source = Array.isArray(value)
                ? value
                : splitTagsPreservingParens(String(value || '').replace(/\r?\n/g, ','));
            const result = [];
            const seen = new Set();
            for (const item of source) {
                const tag = String(item || '').trim();
                const key = tag.toLocaleLowerCase();
                if (!tag || seen.has(key)) continue;
                seen.add(key);
                result.push(tag);
            }
            return result.slice(0, 160);
        }

        function cmFillPresetSelect(id, values, placeholder) {
            const select = document.getElementById(id);
            if (!select) return;
            const previous = select.value;
            select.innerHTML = '';
            const empty = document.createElement('option');
            empty.value = '';
            empty.textContent = placeholder;
            select.appendChild(empty);
            Object.keys(values || {}).sort((a, b) => a.localeCompare(b, 'ko')).forEach(name => {
                const option = document.createElement('option');
                option.value = name;
                option.textContent = name;
                select.appendChild(option);
            });
            if ([...select.options].some(option => option.value === previous)) select.value = previous;
        }

        function cmPopulatePresetOptions() {
            cmFillPresetSelect('cm-setting-quality', assetTags?.quality_presets, '사용 안 함');
            cmFillPresetSelect('cm-setting-artist', assetTags?.artist_presets, '사용 안 함');
            cmFillPresetSelect('cm-setting-anima-quality', assetTags?.quality_presets, '사용 안 함');
            cmFillPresetSelect('cm-setting-anima-artist', assetTags?.artist_presets, '사용 안 함');
            cmFillPresetSelect('cm-setting-negative', assetTags?.negative_presets, '사용 안 함');
            cmFillPresetSelect('cm-setting-anima-negative', assetTags?.negative_presets, '사용 안 함');
            cmFillPresetSelect('cm-setting-char-negative', assetTags?.character_negative_presets, '사용 안 함');
            cmFillPresetSelect('cm-confirm-appearance-existing', assetTags?.appearances, '기존 외모 선택');
            cmFillPresetSelect('cm-confirm-outfit-existing', assetTags?.outfits, '기존 복장 선택');
            cmFillPresetSelect('cm-confirm-expression-existing', assetTags?.expressions, '표정 선택');
            cmFillPresetSelect('cm-confirm-existing-character', assetTags?.characters, '기존 캐릭터 선택');
            cmRenderFieldPresetSelects();
        }

        // 필드별 프리셋 키 매핑: 캐릭터 메이커 4개 필드 → assetTags의 전역 프리셋 사전
        const CM_FIELD_PRESET_KEYS = {
            appearance: 'appearances',
            outfit: 'outfits',
            expression: 'expressions',
            composition: 'composition_presets',
        };
        // 커스텀 셀렉트(검색 내장) 식별자/onChange 래퍼 매핑.
        // 에셋 생성 쪽 buildAssetCustomSelect + bindAssetCustomSelects 메커니즘을 그대로 재사용한다.
        const CM_FIELD_PRESET_SELECT_IDS = {
            appearance: 'cm-preset-appearance',
            outfit: 'cm-preset-outfit',
            expression: 'cm-preset-expression',
            composition: 'cm-preset-composition',
        };
        const CM_FIELD_PRESET_LOAD_FNS = {
            appearance: 'cmLoadAppearancePreset',
            outfit: 'cmLoadOutfitPreset',
            expression: 'cmLoadExpressionPreset',
            composition: 'cmLoadCompositionPreset',
        };

        function cmRenderFieldPresetSelects() {
            if (!assetTags) return;
            for (const field of CM_FIELDS) {
                const card = document.querySelector(`.cm-field-card[data-field="${field}"]`);
                const wrap = card?.querySelector('[data-preset-select]');
                if (!wrap) continue;
                const presets = assetTags[CM_FIELD_PRESET_KEYS[field]] || {};
                // buildAssetCustomSelect 가 키를 sort() 하므로 ko-locale 정렬이 필요하면
                // 미리 정렬된 객체를 넘긴다. 에셋 쪽과 동일한 디자인/검색 동작을 공유.
                const sorted = {};
                Object.keys(presets)
                    .sort((a, b) => a.localeCompare(b, 'ko'))
                    .forEach(k => { sorted[k] = presets[k]; });
                wrap.innerHTML = buildAssetCustomSelect(
                    sorted, '', '프리셋에서 불러오기',
                    CM_FIELD_PRESET_SELECT_IDS[field],
                    CM_FIELD_PRESET_LOAD_FNS[field],
                );
            }
            // 자연어 카드: 자연어 프리셋(문자열)을 검색 셀렉트로. 다른 필드와 동일 UI.
            const nlWrap = document.querySelector(
                '.cm-field-card[data-field="natural_language"] [data-preset-select]'
            );
            if (nlWrap) {
                const nlPresets = assetTags.natural_language_presets || {};
                const nlSorted = {};
                Object.keys(nlPresets)
                    .sort((a, b) => a.localeCompare(b, 'ko'))
                    .forEach(k => { nlSorted[k] = nlPresets[k]; });
                nlWrap.innerHTML = buildAssetCustomSelect(
                    nlSorted, '', '자연어 프리셋에서 불러오기',
                    'cm-preset-natural-language', 'cmLoadNaturalLanguagePreset',
                );
            }
            // 새로 주입된 .custom-select 들에 열기/닫기·검색·옵션 선택 바인딩.
            // bindAssetCustomSelects 는 data-bound 로 중복 바인딩을 막으므로 안전.
            bindAssetCustomSelects();
        }

        function cmLoadFieldPreset(field) {
            if (!cmSession || !CM_FIELDS.includes(field)) return;
            const selectId = CM_FIELD_PRESET_SELECT_IDS[field];
            const name = (getAssetSelectValue(selectId) || '').trim();
            if (!name) return;
            const presets = assetTags?.[CM_FIELD_PRESET_KEYS[field]] || {};
            const tags = presets[name];
            if (!Array.isArray(tags)) {
                console.error(
                    '[CHARACTER_MAKER] 필드 프리셋을 찾을 수 없습니다:',
                    field, name,
                );
                showToast(`${CM_FIELD_LABELS[field]} 프리셋 '${name}'을(를) 찾을 수 없습니다.`, 'error');
                setAssetSelectValue(selectId, '');
                return;
            }
            const cleaned = cmCleanTags(tags);
            // 교체: 기존 필드 태그를 프리셋 태그로 덮어쓴 뒤 임시 세션에 동기화.
            cmSession.fields[field] = cleaned;
            cmRenderField(field);
            cmQueueSync();
            // 불러오기는 상태가 아니라 동작이므로 항상 안내 옵션으로 되돌린다.
            setAssetSelectValue(selectId, '');
            if (!cleaned.length) {
                showToast(`${CM_FIELD_LABELS[field]} 프리셋 '${name}'에 태그가 없습니다.`, 'info');
            } else {
                showToast(`${CM_FIELD_LABELS[field]} 프리셋 '${name}' 불러옴 · ${cleaned.length} tags`, 'success');
            }
        }

        // bindAssetCustomSelects 가 window[fn]() 무인자 호출을 하므로 필드별 래퍼를 둔다.
        function cmLoadAppearancePreset() { return cmLoadFieldPreset('appearance'); }
        function cmLoadOutfitPreset() { return cmLoadFieldPreset('outfit'); }
        function cmLoadExpressionPreset() { return cmLoadFieldPreset('expression'); }
        function cmLoadCompositionPreset() { return cmLoadFieldPreset('composition'); }

        function cmEnsureEditablePresetState() {
            if (!cmSession) return;
            if (!cmSession.editable_preset_tags || typeof cmSession.editable_preset_tags !== 'object') {
                cmSession.editable_preset_tags = {};
            }
            if (!cmSession.editable_preset_enabled || typeof cmSession.editable_preset_enabled !== 'object') {
                cmSession.editable_preset_enabled = {};
            }
            CM_EDITABLE_PRESET_FIELDS.forEach(field => {
                if (!Array.isArray(cmSession.editable_preset_tags[field])) {
                    cmSession.editable_preset_tags[field] = [];
                }
                cmSession.editable_preset_enabled[field] = !!cmSession.editable_preset_enabled[field];
            });
        }

        function cmToggleEditablePreset(field, enabled) {
            const config = CM_EDITABLE_PRESETS[field];
            if (!cmSession || !config) {
                console.error('[CHARACTER_MAKER] 생성 프리셋 자유 편집 토글 실패:', field, enabled);
                return;
            }
            cmEnsureEditablePresetState();
            const toggle = document.getElementById(config.toggleId);
            if (enabled) {
                const presetName = (document.getElementById(config.selectId)?.value || '').trim();
                if (!presetName) {
                    console.error('[CHARACTER_MAKER] 생성 프리셋 자유 편집 실패: 선택 프리셋 없음', field);
                    if (toggle) toggle.checked = false;
                    showToast(`${config.label} 프리셋을 먼저 선택하세요.`, 'error');
                    return;
                }
                const rawTags = assetTags?.[config.category]?.[presetName];
                if (!Array.isArray(rawTags)) {
                    console.error('[CHARACTER_MAKER] 생성 프리셋 자유 편집 실패: 태그 배열 없음', {
                        field,
                        presetName,
                        category: config.category,
                        value: rawTags,
                    });
                    if (toggle) toggle.checked = false;
                    showToast(`${config.label} 프리셋 '${presetName}'의 태그를 찾을 수 없습니다.`, 'error');
                    return;
                }
                cmSession.editable_preset_tags[field] = cmCleanTags(rawTags);
                cmSession.editable_preset_enabled[field] = true;
                showToast(`${config.label} '${presetName}'을 자유 편집 영역으로 옮겼습니다.`, 'success');
            } else {
                cmSession.editable_preset_enabled[field] = false;
                cmSession.editable_preset_tags[field] = [];
                showToast(`${config.label}을 생성 설정 프리셋으로 되돌렸습니다.`, 'info');
            }
            cmRenderEditablePresetControls();
            cmRenderEditablePresetCards();
            cmQueueSync();
        }

        function cmRenderEditablePresetControls() {
            if (!cmSession) return;
            cmEnsureEditablePresetState();
            CM_EDITABLE_PRESET_FIELDS.forEach(field => {
                const config = CM_EDITABLE_PRESETS[field];
                const enabled = !!cmSession.editable_preset_enabled[field];
                const toggle = document.getElementById(config.toggleId);
                const select = document.getElementById(config.selectId);
                const group = document.querySelector(`[data-cm-editable-preset="${field}"]`);
                const unavailable = !!group?.classList.contains('is-unavailable');
                if (toggle) {
                    toggle.checked = enabled;
                    toggle.disabled = unavailable;
                }
                if (select) select.disabled = unavailable || enabled;
                group?.classList.toggle('cm-preset-is-editing', enabled);
            });
        }

        function cmRenderEditablePresetCards() {
            const container = document.getElementById('cm-editable-preset-list');
            if (!container || !cmSession) return;
            cmEnsureEditablePresetState();
            const enabledFields = CM_EDITABLE_PRESET_FIELDS.filter(
                field => cmSession.editable_preset_enabled[field]
            );
            container.innerHTML = enabledFields.map(field => {
                const config = CM_EDITABLE_PRESETS[field];
                return `
                    <section class="cm-field-card cm-editable-preset-card" data-editable-preset-field="${field}">
                        <div class="cm-field-head">
                            <span class="cm-field-dot"></span>
                            <span class="cm-field-name">${escapeHtml(config.label)}</span>
                            <span class="cm-field-count" data-count>0 tags</span>
                            <span class="cm-user-only-badge">LLM 제외 · 사용자 전용</span>
                            <button type="button" class="cm-lock-btn cm-preset-return-btn" onclick="cmToggleEditablePreset('${field}', false)">잠금 영역으로</button>
                        </div>
                        <div class="cm-field-body">
                            <div class="cm-chip-editor">
                                <div class="cm-chip-list" data-chips></div>
                                <div class="cm-tag-add">
                                    <input data-add-input placeholder="태그 추가 · 쉼표 구분" onkeydown="cmEditablePresetTagKeydown(event, '${field}')">
                                    <button class="cm-btn" type="button" onclick="cmAddEditablePresetTags('${field}')">＋</button>
                                </div>
                            </div>
                            <div class="cm-text-wrap">
                                <textarea class="cm-tag-textarea cm-text-editor" data-text placeholder="comma, separated, tags" oninput="cmEditablePresetTextInput('${field}', this.value)"></textarea>
                            </div>
                        </div>
                    </section>`;
            }).join('');
            enabledFields.forEach(field => cmRenderEditablePresetField(field));
        }

        function cmRenderEditablePresetField(field, preserveActiveText = false) {
            if (!cmSession || !CM_EDITABLE_PRESETS[field]) return;
            const card = document.querySelector(`[data-editable-preset-field="${field}"]`);
            if (!card) return;
            const tags = cmSession.editable_preset_tags?.[field] || [];
            const chipList = card.querySelector('[data-chips]');
            if (chipList) {
                chipList.innerHTML = tags.length
                    ? tags.map((tag, index) => `
                        <span class="cm-tag-chip">
                            <span>${escapeHtml(tag)}</span>
                            <button type="button" onclick="cmRemoveEditablePresetTag('${field}', ${index})" aria-label="태그 삭제">×</button>
                        </span>`).join('')
                    : '<span class="cm-hint">태그가 비어 있습니다. 직접 추가할 수 있습니다.</span>';
                // showName + 공용 툴팁: 네이티브 title(브라우저 기본 호버) 대신
                // 태그명 헤더와 설명을 함께 띄운다.
                chipList.querySelectorAll('.cm-tag-chip').forEach((chip, index) => {
                    _attachTagChipTooltip(chip, tags[index], '', null, { showName: true });
                });
                // 첫 호버에서도 즉시 뜨도록 설명을 미리 캐시에 채운다.
                _prefetchTagDescriptions(tags);
            }
            const textarea = card.querySelector('[data-text]');
            if (textarea && (!preserveActiveText || document.activeElement !== textarea)) {
                textarea.value = tags.join(', ');
            }
            const count = card.querySelector('[data-count]');
            if (count) count.textContent = `${tags.length} tags`;
        }

        function cmEditablePresetTextInput(field, value) {
            if (!cmSession || !CM_EDITABLE_PRESETS[field]) return;
            cmSession.editable_preset_tags[field] = cmCleanTags(value);
            cmRenderEditablePresetField(field, true);
            cmQueueSync();
        }

        function cmEditablePresetTagKeydown(event, field) {
            if (event.key !== 'Enter') return;
            event.preventDefault();
            cmAddEditablePresetTags(field);
        }

        function cmAddEditablePresetTags(field) {
            if (!cmSession || !CM_EDITABLE_PRESETS[field]) return;
            const card = document.querySelector(`[data-editable-preset-field="${field}"]`);
            const input = card?.querySelector('[data-add-input]');
            const added = cmCleanTags(input?.value || '');
            if (!added.length) {
                console.error('[CHARACTER_MAKER] 생성 프리셋 태그 추가 스킵: 입력 비어 있음', field);
                return;
            }
            cmSession.editable_preset_tags[field] = cmCleanTags([
                ...(cmSession.editable_preset_tags[field] || []),
                ...added,
            ]);
            if (input) input.value = '';
            cmRenderEditablePresetField(field);
            cmQueueSync();
        }

        function cmRemoveEditablePresetTag(field, index) {
            if (!cmSession || !CM_EDITABLE_PRESETS[field]) return;
            const tags = [...(cmSession.editable_preset_tags[field] || [])];
            if (index < 0 || index >= tags.length) {
                console.error('[CHARACTER_MAKER] 생성 프리셋 태그 삭제 인덱스 오류:', field, index);
                return;
            }
            tags.splice(index, 1);
            cmSession.editable_preset_tags[field] = tags;
            _hideTagChipTooltip();
            cmRenderEditablePresetField(field);
            cmQueueSync();
        }

        function cmCollectSettings() {
            const fallback = cmSession?.settings || {};
            const stringValue = (id, key) => {
                const element = document.getElementById(id);
                return element ? element.value : (fallback[key] || '');
            };
            const numberValue = (id, key, defaultValue) => {
                const element = document.getElementById(id);
                const value = Number(element ? element.value : fallback[key]);
                return Number.isFinite(value) ? value : defaultValue;
            };
            const floatValue = (id, key, defaultValue) => {
                const element = document.getElementById(id);
                const value = Number(element ? element.value : fallback[key]);
                return Number.isFinite(value) ? value : defaultValue;
            };
            const boolValue = (id, key) => {
                const element = document.getElementById(id);
                return element ? !!element.checked : !!fallback[key];
            };
            const textValue = (id, key) => {
                const element = document.getElementById(id);
                const value = element ? element.value : fallback[key];
                return typeof value === 'string' ? value : String(value ?? '');
            };
            const optionalNumber = (id, key) => {
                const element = document.getElementById(id);
                const raw = element ? element.value : fallback[key];
                if (raw === '' || raw === null || raw === undefined) return '';
                const value = Number(raw);
                return Number.isFinite(value) ? String(value) : '';
            };
            return {
                generation_workflow: stringValue('cm-setting-generation-workflow', 'generation_workflow') === 'illustration'
                    ? 'illustration'
                    : 'asset',
                asset_workflow_type: stringValue('cm-setting-workflow', 'asset_workflow_type') || 'ilxl',
                quality_preset: stringValue('cm-setting-quality', 'quality_preset'),
                artist_preset: stringValue('cm-setting-artist', 'artist_preset'),
                negative_preset: stringValue('cm-setting-negative', 'negative_preset'),
                character_negative_preset: stringValue('cm-setting-char-negative', 'character_negative_preset'),
                anima_quality_preset: stringValue('cm-setting-anima-quality', 'anima_quality_preset'),
                anima_artist_preset: stringValue('cm-setting-anima-artist', 'anima_artist_preset'),
                anima_negative_preset: stringValue('cm-setting-anima-negative', 'anima_negative_preset'),
                img_w: Math.round(numberValue('cm-setting-width', 'img_w', 700)),
                img_h: Math.round(numberValue('cm-setting-height', 'img_h', 1024)),
                seed: Math.round(numberValue('cm-setting-seed', 'seed', -1)),
                rag_enabled: boolValue('cm-setting-rag', 'rag_enabled'),
                lora_enabled: boolValue('cm-setting-lora-enabled', 'lora_enabled'),
                lora_list: Array.isArray(fallback.lora_list)
                    ? fallback.lora_list.map(item => ({...item}))
                    : [],
                style_lora_enabled: boolValue('cm-setting-style-lora-enabled', 'style_lora_enabled'),
                style_lora_list: Array.isArray(fallback.style_lora_list)
                    ? fallback.style_lora_list.map(item => ({...item}))
                    : [],
                snapref_enabled: boolValue('cm-snapref-toggle', 'snapref_enabled'),
                snapref_images: Array.isArray(fallback.snapref_images)
                    ? fallback.snapref_images.slice(0, 1).map(item => ({...item}))
                    : [],
                snapref_dir: fallback.snapref_dir || '',
                snapref_mode: stringValue('cm-snapref-mode', 'snapref_mode') || 'char',
                snapref_strength: floatValue('cm-snapref-strength', 'snapref_strength', 0),
                snapref_megapixels: floatValue('cm-snapref-megapixels', 'snapref_megapixels', 1),
                face_lora_enabled: boolValue('cm-setting-face-lora-enabled', 'face_lora_enabled'),
                face_lora_list: Array.isArray(fallback.face_lora_list)
                    ? fallback.face_lora_list.map(item => ({...item}))
                    : [],
                face_lora_upscale_size: optionalNumber('cm-setting-face-upscale', 'face_lora_upscale_size'),
                face_tags: textValue('cm-setting-face-tags', 'face_tags'),
                eye_tags: textValue('cm-setting-eye-tags', 'eye_tags'),
                hrf_sdxl: boolValue('cm-setting-hrf-sdxl', 'hrf_sdxl'),
                hrf_anima: boolValue('cm-setting-hrf-anima', 'hrf_anima'),
                hrf_size: floatValue('cm-setting-hrf-size', 'hrf_size', 2.0),
                hrf_restore_size: boolValue('cm-setting-hrf-restore', 'hrf_restore_size'),
                hrf_control_net: boolValue('cm-setting-hrf-control', 'hrf_control_net'),
                sdxl_fd_enabled: boolValue('cm-setting-sdxl-fd', 'sdxl_fd_enabled'),
                sdxl_hd_enabled: boolValue('cm-setting-sdxl-hd', 'sdxl_hd_enabled'),
                sdxl_ed_enabled: boolValue('cm-setting-sdxl-ed', 'sdxl_ed_enabled'),
                anima_fd_enabled: boolValue('cm-setting-anima-fd', 'anima_fd_enabled'),
                anima_hd_enabled: boolValue('cm-setting-anima-hd', 'anima_hd_enabled'),
                anima_ed_enabled: boolValue('cm-setting-anima-ed', 'anima_ed_enabled'),
                face_crop_top: floatValue('cm-setting-face-crop-top', 'face_crop_top', 2.5),
                face_crop_bottom: floatValue('cm-setting-face-crop-bottom', 'face_crop_bottom', 1.0),
            };
        }

        // 전역 에셋 워크플로우 타입(설정→삽화)이 바뀌면 CM에 즉시 반영한다.
        // CM 세션의 asset_workflow_type은 전역 config를 따르므로(서버 public_session이
        // live 값으로 덮어쓴다), 저장 직후 cmSession에도 밀어넣고 재렌더.
        function cmSyncWorkflowFromConfig() {
            if (!cmSession?.settings) return;
            const next = normalizeAssetWorkflowType(currentConfig?.asset_workflow_type);
            cmSession.settings.asset_workflow_type = next;
            cmApplySettingsToUI();
        }

        function cmApplySettingsToUI() {
            if (!cmSession?.settings) return;
            const settings = cmSession.settings;
            const values = {
                'cm-setting-generation-workflow': settings.generation_workflow === 'illustration' ? 'illustration' : 'asset',
                'cm-setting-workflow': settings.asset_workflow_type || 'ilxl',
                'cm-setting-illustration-workflow': normalizeIllustrationWorkflowType(currentConfig?.illustration_workflow_type),
                'cm-setting-quality': settings.quality_preset || '',
                'cm-setting-artist': settings.artist_preset || '',
                'cm-setting-negative': settings.negative_preset || '',
                'cm-setting-char-negative': settings.character_negative_preset || '',
                'cm-setting-anima-quality': settings.anima_quality_preset || '',
                'cm-setting-anima-artist': settings.anima_artist_preset || '',
                'cm-setting-anima-negative': settings.anima_negative_preset || '',
                'cm-setting-width': settings.img_w ?? 700,
                'cm-setting-height': settings.img_h ?? 1024,
                'cm-setting-seed': settings.seed ?? -1,
                'cm-setting-hrf-size': settings.hrf_size ?? 2,
                'cm-setting-face-crop-top': settings.face_crop_top ?? 2.5,
                'cm-setting-face-crop-bottom': settings.face_crop_bottom ?? 1,
                'cm-setting-face-upscale': settings.face_lora_upscale_size ?? '',
                'cm-setting-face-tags': settings.face_tags || '',
                'cm-setting-eye-tags': settings.eye_tags || '',
                'cm-snapref-mode': settings.snapref_mode || 'char',
                'cm-snapref-strength': settings.snapref_strength ?? 0,
                'cm-snapref-megapixels': settings.snapref_megapixels ?? 1,
            };
            Object.entries(values).forEach(([id, value]) => {
                const element = document.getElementById(id);
                if (!element) return;
                if (element.options) {
                    if ([...element.options].some(option => option.value === String(value))) {
                        element.value = value;
                    }
                } else {
                    element.value = value;
                }
            });
            const hrfSizeValue = document.getElementById('cm-setting-hrf-size-value');
            if (hrfSizeValue) {
                hrfSizeValue.textContent = Number(settings.hrf_size ?? 2).toFixed(2);
            }
            const checkboxes = {
                'cm-setting-rag': settings.rag_enabled,
                'cm-setting-lora-enabled': settings.lora_enabled,
                'cm-setting-style-lora-enabled': settings.style_lora_enabled,
                'cm-snapref-toggle': settings.snapref_enabled,
                'cm-setting-face-lora-enabled': settings.face_lora_enabled,
                'cm-setting-hrf-sdxl': settings.hrf_sdxl,
                'cm-setting-hrf-anima': settings.hrf_anima,
                'cm-setting-hrf-restore': settings.hrf_restore_size !== false,
                'cm-setting-hrf-control': settings.hrf_control_net,
                'cm-setting-sdxl-fd': settings.sdxl_fd_enabled,
                'cm-setting-sdxl-hd': settings.sdxl_hd_enabled,
                'cm-setting-sdxl-ed': settings.sdxl_ed_enabled,
                'cm-setting-anima-fd': settings.anima_fd_enabled,
                'cm-setting-anima-hd': settings.anima_hd_enabled,
                'cm-setting-anima-ed': settings.anima_ed_enabled,
            };
            Object.entries(checkboxes).forEach(([id, value]) => {
                const element = document.getElementById(id);
                if (element) element.checked = !!value;
            });
            cmRenderSeedControl();
            cmRenderAllLoraSettings();
            document.getElementById('cm-snapref-section').style.display = settings.snapref_enabled ? 'block' : 'none';
            const snaprefStatus = document.getElementById('cm-snapref-status');
            snaprefStatus.textContent = settings.snapref_enabled ? 'ON' : 'OFF';
            snaprefStatus.className = 'toggle-status ' + (settings.snapref_enabled ? 'on' : 'off');
            document.getElementById('cm-snapref-strength-value').textContent = Number(settings.snapref_strength ?? 0).toFixed(1);
            renderAssetRefPreview('cm-snapref', false);
            cmApplySettingsAvailability();
            cmRenderEditablePresetControls();
        }

        function cmSettingChanged() {
            if (!cmSession) return;
            cmSession.settings = cmCollectSettings();
            cmRagVerified = false;
            cmRenderAllLoraSettings();
            cmApplySettingsAvailability();
            cmRenderStatus();
            cmQueueSync();
        }

        // ─── 시드 제어(자유편집 영역 시드 카드) ───
        // 시드는 항상 0~2^32-1 구체적 숫자. -1(서버측 랜덤 치환)은 사용하지 않는다.
        // 'random' 모드: 생성 직전(cmPrepareSeedForGenerate)에 새 시드를 굴려 송출.
        // 'fixed' 모드: 현재 시드를 그대로 재사용. 좋은 그림이 나오면 📌 고정.
        function cmLoadSeedMode() {
            try {
                const value = localStorage.getItem(CM_SEED_MODE_STORAGE_KEY);
                if (value === 'random' || value === 'fixed') return value;
            } catch (error) {
                console.error('[CHARACTER_MAKER] 시드 모드 로드 실패:', error);
            }
            return 'random';
        }
        function cmSaveSeedMode(mode) {
            try {
                localStorage.setItem(CM_SEED_MODE_STORAGE_KEY, mode);
            } catch (error) {
                console.error('[CHARACTER_MAKER] 시드 모드 저장 실패:', error);
            }
        }
        function cmIsValidSeed(n) {
            return Number.isInteger(n) && n >= 0 && n <= 4294967295;
        }
        function cmRollSeed() {
            // 0 ~ 2^32-1. Math.random()*2^32 의 floor 는 [0, 2^32-1].
            return Math.floor(Math.random() * 4294967296);
        }
        function cmRenderSeedModeButtons() {
            const randomBtn = document.getElementById('cm-seed-mode-random');
            const fixedBtn = document.getElementById('cm-seed-mode-fixed');
            if (randomBtn) randomBtn.classList.toggle('active', cmSeedMode === 'random');
            if (fixedBtn) fixedBtn.classList.toggle('active', cmSeedMode === 'fixed');
        }
        function cmSetSeedMode(mode) {
            if (mode !== 'random' && mode !== 'fixed') return;
            cmSeedMode = mode;
            cmSaveSeedMode(mode);
            cmRenderSeedModeButtons();
        }
        // 시드 입력칸을 사용자가 직접 수정 → 유효한 구체적 시드로 보정하고 'fixed' 로 전환.
        function cmSeedInputChanged(raw) {
            let n = Math.floor(Number(raw));
            if (!Number.isFinite(n) || n < 0) {
                n = cmRollSeed();
            } else if (n > 4294967295) {
                n = 4294967295;
            }
            const el = document.getElementById('cm-setting-seed');
            if (el) el.value = n;
            if (cmSession?.settings) cmSession.settings.seed = n;
            cmSetSeedMode('fixed');
            cmSettingChanged();
        }
        // cm-setting-seed 요소가 항상 유효한 구체적 시드를 갖도록 보정하고 모드 버튼을 렌더.
        // -1(구/서버 기본값) 이거나 범위 밖이면 새 시드를 굴린다.
        function cmRenderSeedControl() {
            cmSeedMode = cmLoadSeedMode();
            const el = document.getElementById('cm-setting-seed');
            if (el) {
                let n = Math.floor(Number(el.value));
                if (!cmIsValidSeed(n)) {
                    n = cmRollSeed();
                    el.value = n;
                    if (cmSession?.settings) cmSession.settings.seed = n;
                }
            }
            cmRenderSeedModeButtons();
        }
        // 생성 직전 호출: 'random' 모드면 새 시드를 굴려 입력칸/세션에 반영.
        // 'fixed' 라도 현재 값이 유효하지 않으면(빈 칸/범위 밖) 새 시드로 보정.
        // cmBuildPromptData·cmCollectSettings 가 이 값을 읽어 [SEED] 토큰과 설정에 넣는다.
        function cmPrepareSeedForGenerate() {
            const el = document.getElementById('cm-setting-seed');
            let n = el ? Math.floor(Number(el.value)) : NaN;
            if (cmSeedMode === 'random' || !cmIsValidSeed(n)) {
                n = cmRollSeed();
                if (el) el.value = n;
                if (cmSession?.settings) cmSession.settings.seed = n;
            }
        }

        // CM LoRA는 일반/스타일/페이스 3종류. 각 종류별로 설정 키·패널·피커 오버레이가 다르다.
        const CM_LORA_KINDS = {
            regular: { listKey: 'lora_list', enabledKey: 'lora_enabled', toggleId: 'cm-setting-lora-enabled', panelId: 'cm-setting-lora-panel', listId: 'cm-setting-lora-list', overlay: 'cm-lora-picker-overlay', showStyleTab: false, title: '캐릭터 메이커 LoRA 선택' },
            style: { listKey: 'style_lora_list', enabledKey: 'style_lora_enabled', toggleId: 'cm-setting-style-lora-enabled', panelId: 'cm-setting-style-lora-panel', listId: 'cm-setting-style-lora-list', overlay: 'cm-style-lora-picker-overlay', showStyleTab: true, title: '캐릭터 메이커 Style LoRA 선택' },
            face: { listKey: 'face_lora_list', enabledKey: 'face_lora_enabled', toggleId: 'cm-setting-face-lora-enabled', panelId: 'cm-setting-face-lora-panel', listId: 'cm-setting-face-lora-list', overlay: 'cm-face-lora-picker-overlay', showStyleTab: false, title: '캐릭터 메이커 Face LoRA 선택' },
        };

        function cmRenderLoraSettings(kind = 'regular') {
            const cfg = CM_LORA_KINDS[kind];
            if (!cfg) return;
            const panel = document.getElementById(cfg.panelId);
            const list = document.getElementById(cfg.listId);
            const enabled = !!document.getElementById(cfg.toggleId)?.checked;
            panel?.classList.toggle('visible', enabled);
            if (!list || !cmSession?.settings) return;
            const items = Array.isArray(cmSession.settings[cfg.listKey])
                ? cmSession.settings[cfg.listKey]
                : [];
            if (!items.length) {
                list.innerHTML =
                    '<div class="cm-maker-lora-empty">선택된 LoRA가 없습니다.</div>';
                return;
            }
            const capabilities = cmGetGenerationCapabilities();
            list.innerHTML = items.map((item, index) => {
                const base = String(item.BASE || 'anima').toLowerCase() === 'ilxl'
                    ? 'sdxl'
                    : String(item.BASE || 'anima').toLowerCase();
                const compatible = base === 'sdxl'
                    ? capabilities.ilxl
                    : capabilities.anima;
                const sourceLabel = item.source === 'bot'
                    ? '봇'
                    : (item.source === 'instance'
                        ? '인스턴스'
                        : (item.source === 'style' ? '스타일' : '에셋'));
                const strength = Number.isFinite(Number(item.strength))
                    ? Number(item.strength)
                    : 0.5;
                return `
                    <div class="cm-maker-lora-item">
                        <div style="min-width:0;">
                            <div class="cm-maker-lora-name">${escapeHtml(item.name || item.lora_path || 'LoRA')}</div>
                            <div class="cm-maker-lora-meta">
                                ${sourceLabel} · ${base === 'sdxl' ? 'ILXL' : 'ANIMA'}
                                ${compatible ? '' : ' · 현재 워크플로우에서 미사용'}
                            </div>
                            <input class="cm-maker-lora-trigger" type="text"
                                   value="${escapeHtml(item.trigger || '')}"
                                   placeholder="트리거 워드"
                                   onchange="cmUpdateLoraSetting('${kind}', ${index}, 'trigger', this.value)">
                        </div>
                        <label class="cm-maker-lora-strength">
                            <span class="cm-maker-lora-strength-row">
                                <span>강도</span>
                                <input type="number" class="cm-maker-lora-strength-num"
                                       min="0" max="1" step="0.01"
                                       value="${strength.toFixed(2)}"
                                       oninput="cmLoraStrengthDrag('${kind}', ${index}, this)"
                                       onchange="cmLoraStrengthCommit('${kind}', ${index}, this)">
                            </span>
                            <input type="range" min="0" max="1" step="0.01"
                                   value="${strength}"
                                   oninput="cmLoraStrengthDrag('${kind}', ${index}, this)"
                                   onchange="cmLoraStrengthCommit('${kind}', ${index}, this)">
                        </label>
                        <button type="button" class="cm-maker-lora-remove"
                                onclick="cmRemoveLoraSetting('${kind}', ${index})"
                                title="LoRA 제거">×</button>
                    </div>`;
            }).join('');
        }

        function cmRenderAllLoraSettings() {
            Object.keys(CM_LORA_KINDS).forEach(kind => cmRenderLoraSettings(kind));
        }

        function cmLoraToggleChanged(kind = 'regular') {
            if (!cmSession) return;
            const cfg = CM_LORA_KINDS[kind];
            if (!cfg) return;
            cmSession.settings[cfg.enabledKey] =
                !!document.getElementById(cfg.toggleId)?.checked;
            cmRenderLoraSettings(kind);
            cmQueueSync();
        }

        function cmUpdateLoraSetting(kind, index, key, value) {
            const cfg = CM_LORA_KINDS[kind];
            const list = cfg && cmSession?.settings?.[cfg.listKey];
            if (!Array.isArray(list) || !list[index]) {
                console.error('[CHARACTER_MAKER_LORA] 변경할 LoRA를 찾지 못했습니다:', kind, index);
                return;
            }
            list[index][key] = value;
            cmQueueSync();
        }

        // 슬라이더 드래그 / 숫자 타이핑 중: 표시만 양방향 동기화 (저장은 onchange에서)
        function cmLoraStrengthDrag(kind, index, el) {
            const wrap = el.closest('.cm-maker-lora-strength');
            if (!wrap) return;
            const range = wrap.querySelector('input[type="range"]');
            const num = wrap.querySelector('.cm-maker-lora-strength-num');
            const v = Number(el.value);
            if (el.type === 'range') {
                if (num) num.value = v.toFixed(2);
            } else if (Number.isFinite(v)) {
                if (range) range.value = Math.min(1, Math.max(0, v));
            }
        }

        // 값 확정(포커스 아웃/엔터): 0~1 클램프 + 데이터 저장 + 양쪽 동기화
        function cmLoraStrengthCommit(kind, index, el) {
            const cfg = CM_LORA_KINDS[kind];
            const list = cfg && cmSession?.settings?.[cfg.listKey];
            if (!Array.isArray(list) || !list[index]) {
                console.error('[CHARACTER_MAKER_LORA] 강도를 저장할 LoRA를 찾지 못했습니다:', kind, index);
                return;
            }
            let v = Number(el.value);
            if (!Number.isFinite(v)) v = 0.5;
            v = Math.min(1, Math.max(0, v));
            list[index].strength = v;
            const wrap = el.closest('.cm-maker-lora-strength');
            if (wrap) {
                const range = wrap.querySelector('input[type="range"]');
                const num = wrap.querySelector('.cm-maker-lora-strength-num');
                if (range) range.value = v;
                if (num) num.value = v.toFixed(2);
            }
            cmQueueSync();
        }

        function cmRemoveLoraSetting(kind, index) {
            const cfg = CM_LORA_KINDS[kind];
            const list = cfg && cmSession?.settings?.[cfg.listKey];
            if (!Array.isArray(list) || index < 0 || index >= list.length) {
                console.error('[CHARACTER_MAKER_LORA] 제거할 LoRA를 찾지 못했습니다:', kind, index);
                return;
            }
            list.splice(index, 1);
            cmRenderLoraSettings(kind);
            cmQueueSync();
        }

        async function cmOpenLoraPicker(kind = 'regular') {
            if (!cmSession) return;
            const cfg = CM_LORA_KINDS[kind];
            if (!cfg) return;
            if (!Array.isArray(cmSession.settings[cfg.listKey])) {
                cmSession.settings[cfg.listKey] = [];
            }
            if (cmSession.settings[cfg.listKey].length >= 12) {
                showToast('캐릭터 메이커 LoRA는 종류별로 최대 12개까지 사용할 수 있습니다.', 'error');
                return;
            }
            _loraPickerCfg = {
                list: cmSession.settings[cfg.listKey],
                render: () => {
                    if (cmSession.settings[cfg.listKey].length > 12) {
                        cmSession.settings[cfg.listKey].splice(12);
                        showToast(
                            '캐릭터 메이커 LoRA는 최대 12개까지만 유지했습니다.',
                            'error',
                        );
                    }
                    cmSession.settings[cfg.enabledKey] = true;
                    const toggle = document.getElementById(cfg.toggleId);
                    if (toggle) toggle.checked = true;
                    cmRenderLoraSettings(kind);
                    cmQueueSync();
                },
                overlayId: cfg.overlay,
                showStyleTab: cfg.showStyleTab,
            };
            await _openLoraPickerModal(cfg.title, cfg.overlay);
        }

        function cmToggleSettingsWall(force) {
            const wall = document.getElementById('cm-settings-wall');
            if (!wall) return;
            const willCollapse = typeof force === 'boolean'
                ? force
                : !wall.classList.contains('collapsed');
            wall.classList.toggle('collapsed', willCollapse);
            wall.setAttribute('aria-expanded', String(!willCollapse));
            const handle = document.getElementById('cm-settings-handle');
            if (handle) {
                handle.setAttribute('aria-expanded', String(!willCollapse));
                handle.title = willCollapse ? '생성 설정 펼치기' : '생성 설정 접기';
            }
            if (!willCollapse) {
                cmApplySettingsAvailability();
                cmRenderPromptLockSummary();
            }
            cmAlignSettingsWall();
        }

        // 생성 설정 드로어(손잡이)의 세로 시작선을 에디터 열 상단(=툴바 하단)에 맞춘다.
        // CSS의 top:290px(헤더230+툴바60 가정)은 고정값이라 실제 헤더 높이·DPI·창 크기가
        // 다르면 툴바와 손잡이 사이에 '자유 편집 영역' 타이틀 높이만큼 빈 공간이 생긴다.
        // 에디터 열의 실제 viewport top을 읽어 wall의 top/max-height를 동기화한다.
        let cmSettingsWallResizeBound = false;
        function cmAlignSettingsWall() {
            const wall = document.getElementById('cm-settings-wall');
            const editorWall = document.getElementById('cm-editor-wall');
            const tab = document.getElementById('tab-character-maker-content');
            if (!wall || !editorWall || !tab || !tab.classList.contains('active')) return;
            const top = Math.round(editorWall.getBoundingClientRect().top);
            if (!Number.isFinite(top) || top <= 0) return;
            wall.style.top = top + 'px';
            wall.style.maxHeight = `calc(100vh - ${top}px)`;
            if (!cmSettingsWallResizeBound) {
                cmSettingsWallResizeBound = true;
                window.addEventListener('resize', cmAlignSettingsWall);
            }
        }

        function cmGetGenerationCapabilities() {
            const generationWorkflow = document.getElementById('cm-setting-generation-workflow')?.value === 'illustration'
                ? 'illustration'
                : 'asset';
            if (generationWorkflow === 'illustration') {
                const type = normalizeIllustrationWorkflowType(
                    currentConfig?.illustration_workflow_type,
                );
                const illustration = getIllustrationCapabilities(type);
                return {
                    generationWorkflow,
                    type,
                    ilxl: !!illustration.sdxl,
                    anima: !!illustration.anima,
                    dual: !!illustration.sdxl && !!illustration.anima,
                    pose: false,
                    ipadapter: false,
                    localAdvanced: !!illustration.localAdvanced,
                    lora: !!illustration.localAdvanced,
                };
            }
            return {
                ...getAssetWorkflowCapabilities(
                    document.getElementById('cm-setting-workflow')?.value,
                ),
                generationWorkflow,
                localAdvanced: true,
                lora: true,
            };
        }

        // 선택한 생성 워크플로우와 모델 계열에 따라 쓸 수 없는 항목을 회색 잠금.
        // CM 미지원(.cm-unsupported) 항목은 마크업 disabled를 유지하고 건드리지 않는다.
        function cmApplySettingsAvailability() {
            const wall = document.getElementById('cm-settings-wall');
            if (!wall) return;
            const capabilities = cmGetGenerationCapabilities();
            const illustrationMode = capabilities.generationWorkflow === 'illustration';
            const generationBadge = document.getElementById('cm-generation-workflow-badge');
            if (generationBadge) {
                const modelLabel = capabilities.dual ? 'ILXL+ANIMA'
                    : capabilities.anima ? 'ANIMA'
                    : 'ILXL';
                generationBadge.textContent = `${illustrationMode ? '삽화' : '에셋'} · ${modelLabel}`;
            }
            const assetRow = document.getElementById('cm-asset-workflow-row');
            const illustrationRow = document.getElementById('cm-illustration-workflow-row');
            if (assetRow) assetRow.style.display = illustrationMode ? 'none' : '';
            if (illustrationRow) illustrationRow.style.display = illustrationMode ? '' : 'none';
            const illustrationSelect = document.getElementById('cm-setting-illustration-workflow');
            if (illustrationSelect) {
                illustrationSelect.value = normalizeIllustrationWorkflowType(
                    currentConfig?.illustration_workflow_type,
                );
            }
            const legend = document.getElementById('cm-workflow-legend');
            if (legend) {
                legend.innerHTML = illustrationMode
                    ? '<strong>삽화용 봇 설정:</strong> 현재 설정의 삽화 프로필을 사용하며, 챈섭에서 지원하지 않는 로컬 고급 옵션은 잠깁니다.'
                    : '<strong>에셋 모드:</strong> 현재 설정의 에셋 프로필을 사용하며, 모델 계열에 맞지 않는 옵션은 잠깁니다.';
            }
            wall.querySelectorAll('[data-cm-local-advanced]').forEach(container => {
                const available = !illustrationMode || capabilities.localAdvanced;
                container.classList.toggle('is-unavailable', !available);
                container.querySelectorAll('input, select, button').forEach(control => {
                    control.disabled = !available;
                });
            });
            wall.querySelectorAll('[data-cm-lora-controls]').forEach(container => {
                const available = !illustrationMode || capabilities.lora;
                container.classList.toggle('is-unavailable', !available);
                container.querySelectorAll('input, select, button').forEach(control => {
                    control.disabled = !available;
                });
            });
            // 상위 그룹 상태를 먼저 적용한 뒤 모델별 상태를 적용해야, 예를 들어
            // ANIMA-only에서 상위 그룹 활성화가 ILXL 하위 컨트롤을 다시 켜지 않는다.
            wall.querySelectorAll('[data-at-availability]').forEach(container => {
                const availability = container.dataset.atAvailability;
                const modelAvailable = availability === 'anima' ? capabilities.anima
                    : (availability === 'sdxl-only' || availability === 'ilxl') ? capabilities.ilxl
                    : availability === 'pose' ? capabilities.pose
                    : availability === 'ipadapter' ? capabilities.ipadapter
                    : true;
                const advancedAvailable = !container.closest('[data-cm-local-advanced]')
                    || !illustrationMode
                    || capabilities.localAdvanced;
                const loraAvailable = !container.closest('[data-cm-lora-controls]')
                    || !illustrationMode
                    || capabilities.lora;
                const available = modelAvailable && advancedAvailable && loraAvailable
                    && (!container.hasAttribute('data-cm-snapref') || !illustrationMode);
                container.classList.toggle('is-unavailable', !available);
                if (container.classList.contains('cm-unsupported')) return; // 미지원은 항상 잠금
                container.querySelectorAll('input, select, button').forEach(control => {
                    control.disabled = !available;
                });
            });
            const generateButton = document.getElementById('cm-generate-btn');
            if (generateButton && !cmBusy) {
                generateButton.textContent = illustrationMode
                    ? '사용자 삽화 생성'
                    : '사용자 이미지 생성';
            }
        }

        // 프롬프트 구성(외모·복장·표정·구도) 잠금 행을 자유 편집 영역의 현재 태그 수와 동기화.
        function cmRenderPromptLockSummary() {
            if (!cmSession?.fields) return;
            ['appearance', 'outfit', 'expression', 'composition'].forEach(field => {
                const node = document.querySelector(`[data-cm-lock-summary="${field}"]`);
                if (!node) return;
                const tags = Array.isArray(cmSession.fields[field]) ? cmSession.fields[field] : [];
                node.textContent = tags.length
                    ? `${tags.length}개 태그 · 자유 편집 영역 연동`
                    : '자유 편집 영역에서 수정';
            });
        }

        function cmSetEditorMode(mode, persist = true) {
            const normalized = mode === 'text' ? 'text' : 'chip';
            const wall = document.getElementById('cm-editor-wall');
            wall?.classList.toggle('text-mode', normalized === 'text');
            document.getElementById('cm-mode-chip')?.classList.toggle('active', normalized === 'chip');
            document.getElementById('cm-mode-text')?.classList.toggle('active', normalized === 'text');
            // 모드 전환 시 열려 있던 자동완성 드롭다운을 닫아 이전 모드의 잔상이 남지 않게 한다.
            wall?.querySelectorAll('.tag-autocomplete-dropdown').forEach(d => d.classList.remove('visible'));
            if (persist) sessionStorage.setItem('characterMakerEditorMode', normalized);
        }

        function cmRenderField(field, preserveActiveText = false) {
            if (!cmSession) return;
            const card = document.querySelector(`.cm-field-card[data-field="${field}"]`);
            if (!card) return;
            const tags = cmSession.fields?.[field] || [];
            const chipList = card.querySelector('[data-chips]');
            if (chipList) {
                chipList.innerHTML = tags.map((tag, index) => `
                    <span class="cm-tag-chip">
                        <span>${escapeHtml(tag)}</span>
                        <button type="button" onclick="cmRemoveTag('${field}', ${index})" aria-label="태그 삭제">×</button>
                    </span>`).join('');
                if (!tags.length) {
                    chipList.innerHTML = '<span class="cm-hint">아직 태그가 없습니다.</span>';
                }
                // 칩 hover 설명 툴팁 (에셋 생성과 동일: _lookupTagDescription → #ac-tooltip).
                // innerHTML로 생성한 칩은 이벤트가 없으므로 렌더 직후 바인딩한다.
                // showName: 잘린 칩의 전체 태그명도 툴팁에서 확인 가능.
                // 네이티브 title 대신 공용 툴팁만 쓴다(브라우저 기본 호버 방지).
                chipList.querySelectorAll('.cm-tag-chip').forEach((chip, index) => {
                    _attachTagChipTooltip(chip, tags[index], '', null, { showName: true });
                });
                // 첫 호버에서도 즉시 뜨도록 설명을 미리 캐시에 채운다.
                _prefetchTagDescriptions(tags);
            }
            const textarea = card.querySelector('[data-text]');
            if (textarea && (!preserveActiveText || document.activeElement !== textarea)) {
                textarea.value = tags.join(', ');
            }
            const count = card.querySelector('[data-count]');
            if (count) count.textContent = `${tags.length} tags`;
            const locked = !!cmSession.locks?.[field];
            const lockButton = card.querySelector('[data-lock]');
            if (lockButton) {
                lockButton.classList.toggle('locked', locked);
                lockButton.textContent = locked ? 'LLM 잠금' : 'LLM 열림';
                lockButton.title = locked ? 'LLM 수정에서 이 영역을 유지합니다' : 'LLM이 이 영역을 수정할 수 있습니다';
            }
        }

        function cmRenderNaturalLanguage(preserveActiveText = false) {
            if (!cmSession) return;
            const card = document.querySelector('.cm-field-card[data-field="natural_language"]');
            if (!card) return;
            const text = cmSession.natural_language || '';
            const textarea = card.querySelector('[data-natural-text]');
            if (textarea && (!preserveActiveText || document.activeElement !== textarea)) {
                textarea.value = text;
            }
            const count = card.querySelector('[data-natural-count]');
            if (count) count.textContent = `${text.length}자`;
            const locked = !!cmSession.locks?.natural_language;
            const lockButton = card.querySelector('[data-lock]');
            if (lockButton) {
                lockButton.classList.toggle('locked', locked);
                lockButton.textContent = locked ? 'LLM 잠금' : 'LLM 열림';
                lockButton.title = locked ? 'LLM 수정에서 이 영역을 유지합니다' : 'LLM이 이 영역을 수정할 수 있습니다';
            }
        }

        function cmNaturalLanguageInput(value) {
            if (!cmSession) return;
            cmSession.natural_language = String(value || '').slice(0, 2000);
            cmRenderNaturalLanguage(true);
            cmQueueSync();
        }

        function cmLoadNaturalLanguagePreset() {
            if (!cmSession) return;
            const name = (getAssetSelectValue('cm-preset-natural-language') || '').trim();
            if (!name) return;
            const presets = assetTags?.natural_language_presets || {};
            const text = presets[name];
            if (typeof text !== 'string') {
                console.error('[CHARACTER_MAKER] 자연어 프리셋을 찾을 수 없습니다:', name);
                showToast(`자연어 프리셋 '${name}'을(를) 찾을 수 없습니다.`, 'error');
                setAssetSelectValue('cm-preset-natural-language', '');
                return;
            }
            cmSession.natural_language = text.slice(0, 2000);
            cmRenderNaturalLanguage();
            cmQueueSync();
            // 불러오기는 상태가 아니라 동작이므로 항상 안내 옵션으로 되돌린다.
            setAssetSelectValue('cm-preset-natural-language', '');
            showToast(`자연어 프리셋 '${name}' 불러옴 · ${cmSession.natural_language.length}자`, 'success');
        }

        function cmRenderChat() {
            const log = document.getElementById('cm-chat-log');
            if (!log || !cmSession) return;
            const chat = cmSession.chat || [];
            const scope = document.getElementById('cm-chat-scope');
            const activeBranchId = cmSession.active_chat_branch_id || '';
            const pendingCount = activeBranchId
                ? chat.filter(message => message.branch_id === activeBranchId && !message.accepted).length
                : 0;
            if (scope) {
                if (pendingCount) {
                    scope.textContent = `활성 분기 · 미승인 ${pendingCount}개`;
                } else if (cmSession.user_chat_checkpoint_id) {
                    scope.textContent = '사용자 체크포인트 · 새 분기 준비';
                } else {
                    scope.textContent = '새 분기 준비 · 잠금 필드는 유지';
                }
            }
            if (!chat.length) {
                log.innerHTML = '<div class="cm-chat-empty">원하는 특징을 말하면 네 영역의 태그 초안을 만듭니다.<br>이미지를 만든 뒤에는 보이는 문제를 그대로 피드백하세요.</div>';
                return;
            }
            log.innerHTML = chat.map(message => {
                const base = message.base === 'user'
                    ? 'user'
                    : (message.base === 'llm' ? 'llm' : 'unknown');
                const baseLabel = base === 'user'
                    ? '사용자 기준'
                    : (base === 'llm' ? 'LLM 기준' : '기준 미상');
                const baseClass = base === 'user'
                    ? 'user-base'
                    : (base === 'llm' ? 'llm-base' : 'unknown');
                const superseded = !!message.branch_id
                    && !message.accepted
                    && message.branch_id !== activeBranchId;
                const stateBadge = message.accepted
                    ? '<span class="cm-message-context-badge accepted">accept됨</span>'
                    : (superseded
                        ? '<span class="cm-message-context-badge superseded">폐기됨</span>'
                        : '');
                return `
                    <div class="cm-message ${message.role === 'user' ? 'user' : 'assistant'}${superseded ? ' superseded' : ''}">
                        <div class="cm-message-context">
                            <span class="cm-message-context-badge ${baseClass}">${baseLabel}</span>
                            ${stateBadge}
                        </div>
                        <div class="cm-message-content">${escapeHtml(message.content || '')}</div>
                    </div>`;
            }).join('');
            log.scrollTop = log.scrollHeight;
        }

        function cmRenderReferences() {
            const grid = document.getElementById('cm-reference-grid');
            const count = document.getElementById('cm-reference-count');
            if (!grid || !cmSession) return;
            const references = cmSession.references || [];
            if (count) count.textContent = `${references.length} / 8`;
            grid.innerHTML = references.map(reference => `
                <div class="cm-reference-item" title="${escapeHtml(reference.name || '')}">
                    <img src="${reference.url}?v=${encodeURIComponent(cmSession.updated_at || '')}" alt="">
                    <button class="cm-reference-remove" type="button"
                            onclick="event.stopPropagation(); cmRemoveReference('${reference.id}')">×</button>
                </div>
            `).join('');
        }

        function cmRenderStage() {
            const revisionsEl = document.getElementById('cm-revisions');
            const userPane = document.getElementById('cm-pane-user');
            const llmPane = document.getElementById('cm-pane-llm');
            const userImage = document.getElementById('cm-user-image');
            const llmImage = document.getElementById('cm-llm-image');
            const meta = document.getElementById('cm-stage-meta');
            if (!revisionsEl || !userPane || !llmPane || !userImage || !llmImage || !cmSession) return;
            // 캔버스 종횡비를 선택된 생성 비율(세로형 2장 나란히 기준)로 맞춘다.
            // 화면이 가로로 넓어져도 패인이 가로로만 늘어나 이미지가 작아 보이는 현상 방지.
            const cmCanvas = document.getElementById('cm-canvas');
            if (cmCanvas) {
                const { img_w: cmW = 700, img_h: cmH = 1024 } = cmCollectSettings();
                const cmRatio = (cmW > 0 && cmH > 0) ? (2 * cmW / cmH) : 1.37;
                cmCanvas.style.setProperty('--cm-canvas-ratio', String(cmRatio));
            }
            const revisions = cmSession.revisions || [];
            const activeId = cmSession.active_revision_id;
            const llmActiveId = cmSession.llm_active_revision_id;
            const active = revisions.find(item => item.id === activeId);
            const llmActive = revisions.find(item => item.id === llmActiveId);

            const renderPane = (paneEl, imgEl, revision) => {
                if (revision) {
                    const nextSrc = `${revision.url}?v=${encodeURIComponent(revision.created_at || '')}`;
                    if (imgEl.getAttribute('src') !== nextSrc) imgEl.src = nextSrc;
                    imgEl.onerror = () => {
                        console.error('[CHARACTER_MAKER] 리비전 이미지 표시 실패:', revision.id);
                    };
                    paneEl.classList.add('has-image');
                } else {
                    imgEl.removeAttribute('src');
                    paneEl.classList.remove('has-image');
                }
            };
            renderPane(userPane, userImage, active);
            renderPane(llmPane, llmImage, llmActive);

            // 히스토리 스트립: 출처(user/llm) 배지 + 활성 표시. 클릭 시 출처에 맞춰 좌/우 슬롯 로드.
            revisionsEl.innerHTML = revisions.map((revision, index) => {
                const source = revision.source === 'llm' ? 'llm' : 'user';
                const isActive = revision.id === activeId;
                const isLlmActive = revision.id === llmActiveId;
                const classes = [
                    'cm-revision',
                    isActive ? 'active' : '',
                    isLlmActive ? 'llm-active' : '',
                ].filter(Boolean).join(' ');
                const badge = source === 'llm' ? 'LLM' : 'USER';
                return `
                <div class="${classes}"
                     role="button" tabindex="0"
                     title="${source === 'llm' ? 'LLM' : '사용자'} 리비전 R${index + 1}"
                     onclick="cmSelectRevision('${revision.id}','${source}')"
                     onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();cmSelectRevision('${revision.id}','${source}');}">
                    <img src="${revision.url}?v=${encodeURIComponent(revision.created_at || '')}" alt="리비전 ${index + 1}">
                    <span class="cm-revision-badge ${source}">${badge}</span>
                    <span class="cm-revision-label">R${index + 1}</span>
                </div>`;
            }).join('');

            if (meta) {
                if (active || llmActive) {
                    const u = active ? `사용자 R${revisions.indexOf(active) + 1}(${active.fields?.appearance?.length || 0}/${active.fields?.outfit?.length || 0}/${active.fields?.expression?.length || 0}/${active.fields?.composition?.length || 0})` : '사용자 없음';
                    const l = llmActive ? `LLM R${revisions.indexOf(llmActive) + 1}(${llmActive.fields?.appearance?.length || 0}/${llmActive.fields?.outfit?.length || 0}/${llmActive.fields?.expression?.length || 0}/${llmActive.fields?.composition?.length || 0})` : 'LLM 없음';
                    meta.textContent = `${l} · ${u}`;
                } else {
                    meta.textContent = '활성 리비전 없음';
                }
            }
        }

        async function cmSendUserImageToInstanceLora() {
            const button = document.getElementById('cm-send-instance-lora-btn');
            const revisions = cmSession?.revisions || [];
            const revision = revisions.find(item => item.id === cmSession?.active_revision_id);
            if (!revision?.url) {
                console.error('[CHARACTER_MAKER] 인스턴스 로라 전달 실패: 활성 사용자 이미지가 없습니다.', {
                    active_revision_id: cmSession?.active_revision_id || '',
                });
                showToast('인스턴스 로라로 보낼 사용자 이미지가 없습니다.', 'error');
                return;
            }

            const originalText = button?.textContent?.trim() || '인스턴스 로라로 보내기';
            if (button) {
                button.disabled = true;
                button.textContent = '이미지 준비 중...';
            }
            try {
                const response = await fetch(revision.url, { cache: 'no-store' });
                if (!response.ok) {
                    throw new Error(`이미지 조회 HTTP ${response.status}`);
                }
                const blob = await response.blob();
                if (!blob.size) {
                    throw new Error('이미지 응답이 비어 있습니다.');
                }
                const responseContentType = (blob.type || response.headers.get('Content-Type') || 'image/png')
                    .split(';')[0]
                    .trim()
                    .toLowerCase();
                const contentType = responseContentType.startsWith('image/') ? responseContentType : 'image/png';
                const extensionByType = {
                    'image/jpeg': 'jpg',
                    'image/png': 'png',
                    'image/webp': 'webp',
                    'image/gif': 'gif',
                    'image/bmp': 'bmp',
                };
                const extension = extensionByType[contentType] || 'png';
                const safeRevisionId = String(revision.id || 'revision').replace(/[^a-zA-Z0-9_-]/g, '_');
                const uploadFile = new File(
                    [blob],
                    `character-maker-${safeRevisionId}.${extension}`,
                    { type: contentType || 'image/png', lastModified: Date.now() },
                );
                await showInstanceLoraCreateModal(uploadFile);
            } catch (error) {
                console.error('[CHARACTER_MAKER] 인스턴스 로라 전달 실패:', {
                    revision_id: revision.id || '',
                    image_url: revision.url,
                    error,
                });
                showToast('인스턴스 로라 이미지 준비 실패: ' + (error.message || error), 'error');
            } finally {
                if (button) {
                    button.disabled = false;
                    button.textContent = originalText;
                }
            }
        }

        function cmRenderLlmTags() {
            const container = document.getElementById('cm-llm-tags');
            if (!container || !cmSession) return;
            const llmFields = cmSession.llm_fields || {};
            const chips = [];
            for (const field of CM_FIELDS) {
                for (const tag of (llmFields[field] || [])) {
                    chips.push(`<span class="cm-llm-tag-chip">${escapeHtml(CM_FIELD_LABELS[field])}: ${escapeHtml(tag)}</span>`);
                }
            }
            const naturalLanguage = (cmSession.llm_natural_language || '').trim();
            const titleHtml = '<span class="cm-llm-tags-title">LLM 태그</span>';
            // 태그 칩 블록(wrap 줄바꿈) + 자연어 블록(아래)을 세로로 쌓는다.
            // 둘 다 비어있으면 안내 문구만.
            const parts = [];
            if (chips.length) {
                parts.push(`<div class="cm-llm-tags-row">${titleHtml}${chips.join('')}</div>`);
            }
            if (naturalLanguage) {
                parts.push(
                    '<div class="cm-llm-natural">'
                    + '<span class="cm-llm-natural-title">자연어</span>'
                    + `<span class="cm-llm-natural-text">${escapeHtml(naturalLanguage)}</span>`
                    + '</div>'
                );
            }
            container.innerHTML = parts.length
                ? parts.join('')
                : `<div class="cm-llm-tags-row">${titleHtml}<span class="cm-llm-tags-empty">아직 LLM이 수정한 태그가 없습니다.</span></div>`;
        }

        // 하위 호환: 기존 호출 지점(cmRenderRevisions 이름)이 있을 수 있어 분할 렌더로 위임.
        function cmRenderRevisions() { cmRenderStage(); }

        function cmRenderStatus() {
            if (!cmSession) return;
            const sessionStatus = document.getElementById('cm-session-status');
            if (sessionStatus) {
                sessionStatus.textContent = cmSession.finalized
                    ? '캐릭터 메이커 · 확정 완료'
                    : '캐릭터 메이커 작업공간';
                sessionStatus.className = 'cm-status-pill ready';
            }
            const revisionStatus = document.getElementById('cm-revision-status');
            if (revisionStatus) {
                revisionStatus.textContent = `리비전 ${(cmSession.revisions || []).length}`;
                revisionStatus.className = `cm-status-pill ${(cmSession.revisions || []).length ? 'ready' : ''}`;
            }
            const visionStatus = document.getElementById('cm-vision-status');
            const visionReady = !!cmCapabilities?.vision?.ready;
            if (visionStatus) {
                const service = cmCapabilities?.vision?.service || '미설정';
                visionStatus.textContent = visionReady ? `Vision · ${service}` : `Vision 필요 · ${service}`;
                visionStatus.className = `cm-status-pill ${visionReady ? 'ready' : 'error'}`;
            }
            const ragStatus = document.getElementById('cm-rag-status');
            const ragEnabled = !!cmSession.settings?.rag_enabled;
            if (ragStatus) {
                ragStatus.textContent = ragEnabled
                    ? (cmRagVerified ? 'Danbooru RAG · 연결됨' : 'Danbooru RAG · ON / 미확인')
                    : 'Danbooru RAG · OFF';
                ragStatus.className = `cm-status-pill ${ragEnabled ? (cmRagVerified ? 'ready' : 'warn') : ''}`;
            }
            const saveStatus = document.getElementById('cm-save-status');
            if (saveStatus) {
                if (cmSession.finalized) {
                    saveStatus.textContent = `등록 완료 · ${cmSession.finalized.character_name}`;
                    saveStatus.className = 'cm-status-pill ready';
                } else {
                    saveStatus.textContent = '확정 전 · 자동 저장됨';
                    saveStatus.className = 'cm-status-pill warn';
                }
            }
            const world = document.getElementById('cm-world-context');
            const worldCount = document.getElementById('cm-world-count');
            if (worldCount) worldCount.textContent = `${(world?.value || '').length.toLocaleString()} / 20,000`;
        }

        function cmRenderDiff(diff = cmLastDiff) {
            const strip = document.getElementById('cm-diff-strip');
            if (!strip) return;
            const chips = [];
            for (const field of CM_FIELDS) {
                const entry = diff?.[field] || {};
                for (const tag of entry.added || []) {
                    chips.push(`<span class="cm-diff-chip add">+ ${escapeHtml(CM_FIELD_LABELS[field])} · ${escapeHtml(tag)}</span>`);
                }
                for (const tag of entry.removed || []) {
                    chips.push(`<span class="cm-diff-chip remove">− ${escapeHtml(CM_FIELD_LABELS[field])} · ${escapeHtml(tag)}</span>`);
                }
            }
            strip.innerHTML = chips.length
                ? chips.join('')
                : '<span class="cm-diff-empty">이번 수정에서 태그 변화가 없습니다.</span>';
        }

        function cmRender() {
            if (!cmSession) return;
            const world = document.getElementById('cm-world-context');
            if (world && document.activeElement !== world) world.value = cmSession.world_context || '';
            CM_FIELDS.forEach(field => cmRenderField(field));
            cmRenderEditablePresetControls();
            cmRenderEditablePresetCards();
            cmRenderNaturalLanguage();
            cmRenderChat();
            cmRenderReferences();
            cmRenderStage();
            cmRenderLlmTags();
            cmRenderStatus();
            cmRenderDiff();
            cmRenderPromptLockSummary();
        }

        function cmQueueSync(delay = 450) {
            if (!cmSession) return;
            clearTimeout(cmSyncTimer);
            const version = ++cmSyncVersion;
            const saveStatus = document.getElementById('cm-save-status');
            if (saveStatus && !cmSession.finalized) {
                saveStatus.textContent = '임시값 동기화 대기';
                saveStatus.className = 'cm-status-pill warn';
            }
            cmSyncTimer = setTimeout(() => cmSyncSession(version), delay);
        }

        async function cmSyncSession(version = ++cmSyncVersion) {
            clearTimeout(cmSyncTimer);
            cmSyncTimer = null;
            if (!cmSession) return;
            const sessionId = cmSession.id;
            try {
                await cmRequest(`/api/character_maker/session/${encodeURIComponent(sessionId)}`, {
                    method: 'PATCH',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(cmCurrentPayload()),
                    keepalive: true,
                });
                if (version === cmSyncVersion && cmSession?.id === sessionId) cmRenderStatus();
            } catch (error) {
                console.error('[CHARACTER_MAKER] 임시값 동기화 실패:', sessionId, error);
                const saveStatus = document.getElementById('cm-save-status');
                if (saveStatus) {
                    saveStatus.textContent = '임시값 동기화 실패';
                    saveStatus.className = 'cm-status-pill error';
                }
            }
        }

        function cmOnWorldInput() {
            if (!cmSession) return;
            const world = document.getElementById('cm-world-context');
            cmSession.world_context = (world?.value || '').slice(0, 20000);
            const count = document.getElementById('cm-world-count');
            if (count) count.textContent = `${cmSession.world_context.length.toLocaleString()} / 20,000`;
            cmQueueSync();
        }

        function cmTextFieldInput(field, value) {
            if (!cmSession || !CM_FIELDS.includes(field)) return;
            cmSession.fields[field] = cmCleanTags(value);
            cmRenderField(field, true);
            cmQueueSync();
        }

        function cmTagInputKeydown(event, field) {
            if (event.key === 'Enter') {
                // 자동완성 드롭다운이 열려 있고 포커스된 항목이 있으면 태그 추가를 건너뛰고
                // 자동완성 선택(TagAutocomplete의 keydown 리스너)에 맡긴다.
                const card = document.querySelector(`.cm-field-card[data-field="${field}"]`);
                const dropdown = card?.querySelector('.cm-tag-add > .tag-autocomplete-dropdown');
                if (dropdown?.classList.contains('visible') && dropdown.querySelector('.ac-item.focused')) {
                    return;
                }
                event.preventDefault();
                cmAddTags(field);
            }
        }

        function cmAddTags(field) {
            if (!cmSession || !CM_FIELDS.includes(field)) return;
            const card = document.querySelector(`.cm-field-card[data-field="${field}"]`);
            const input = card?.querySelector('[data-add-input]');
            const added = cmCleanTags(input?.value || '');
            if (!added.length) return;
            cmSession.fields[field] = cmCleanTags([...(cmSession.fields[field] || []), ...added]);
            if (input) input.value = '';
            cmRenderField(field);
            cmQueueSync();
        }

        function cmRemoveTag(field, index) {
            if (!cmSession || !CM_FIELDS.includes(field)) return;
            const tags = [...(cmSession.fields[field] || [])];
            if (index < 0 || index >= tags.length) {
                console.error('[CHARACTER_MAKER] 삭제할 태그 인덱스가 유효하지 않습니다:', field, index);
                return;
            }
            tags.splice(index, 1);
            cmSession.fields[field] = tags;
            // 칩이 innerHTML 재생성으로 통째로 교체되면 mouseleave가 발생하지 않아
            // 떠 있던 설명 호버가 남으므로 명시적으로 숨긴다.
            _hideTagChipTooltip();
            cmRenderField(field);
            cmQueueSync();
        }

        function cmToggleLock(field) {
            if (!cmSession || !CM_LOCKABLE.includes(field)) return;
            cmSession.locks[field] = !cmSession.locks[field];
            if (field === 'natural_language') {
                cmRenderNaturalLanguage();
            } else {
                cmRenderField(field);
            }
            cmQueueSync();
        }

        function cmFeedbackKeydown(event) {
            if (event.key === 'Enter' && (event.ctrlKey || event.metaKey)) {
                event.preventDefault();
                cmRevise('user');
            }
        }

        function cmSetBusy(active, message = '처리 중...') {
            cmBusy = !!active;
            document.getElementById('cm-busy-overlay')?.classList.toggle('visible', cmBusy);
            const busyText = document.getElementById('cm-busy-text');
            if (busyText) busyText.textContent = message;
            ['cm-revise-user-btn', 'cm-revise-llm-btn', 'cm-generate-btn', 'cm-accept-btn', 'cm-confirm-open-btn'].forEach(id => {
                const button = document.getElementById(id);
                if (button) button.disabled = cmBusy;
            });
        }

        async function cmRevise(base) {
            if (cmBusy || !cmSession) return;
            if (base !== 'user' && base !== 'llm') {
                console.error('[CHARACTER_MAKER] cmRevise base 오류:', base);
                return;
            }
            const input = document.getElementById('cm-feedback-input');
            const message = input?.value.trim() || '';
            if (!message) {
                showToast('LLM에게 전달할 요청이나 피드백을 입력하세요.', 'error');
                return;
            }
            const baseRevisionId = base === 'llm'
                ? cmSession.llm_active_revision_id
                : cmSession.active_revision_id;
            const hasBaseImage = !!baseRevisionId;
            const needsVision = hasBaseImage || !!(cmSession.references || []).length;
            const routeCapability = hasBaseImage
                ? cmCapabilities?.routes?.feedback
                : cmCapabilities?.routes?.draft;
            const routeVisionReady = routeCapability
                ? !!routeCapability.vision_ready
                : !!cmCapabilities?.vision?.ready;
            if (needsVision && !routeVisionReady) {
                showToast('현재 입력에는 비전 지원 LLM 경로가 필요합니다. 외부 LLM 분기를 확인하세요.', 'error');
                return;
            }
            const baseLabel = base === 'llm' ? 'LLM 기준' : '사용자 기준';
            cmSetBusy(true, hasBaseImage
                ? `${baseLabel} · 현재 이미지와 피드백을 함께 분석하는 중...`
                : `${baseLabel} · 세계관에서 캐릭터 태그를 설계하는 중...`);
            const sessionId = cmSession.id;
            try {
                // 1) LLM 수정(base 에서 출발 → 결과는 llm_fields 에 저장)
                const revisePayload = { ...cmCurrentPayload(), base, message };
                // base=="llm" 은 사용자 fields 를 서버에 보내지 않는다(사용자 영역 보존).
                if (base === 'llm') delete revisePayload.fields;
                const data = await cmRequest(`/api/character_maker/session/${encodeURIComponent(sessionId)}/revise`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(revisePayload),
                });
                cmSession = data.session;
                cmLastDiff = data.diff || null;
                if (data.rag?.enabled) cmRagVerified = true;
                cmApplySettingsToUI();
                cmRender();
                if (input) input.value = '';

                // LLM 결과(llm_fields)에 외모/복장이 없으면 그릴 수 없다.
                const llmFields = cmSession.llm_fields || {};
                if (!(llmFields.appearance || []).length || !(llmFields.outfit || []).length) {
                    const ragNote = data.rag?.enabled ? ' · RAG 후보 검증 포함' : '';
                    showToast(`LLM이 태그를 수정했지만 외모/복장이 부족해 그리지 못했습니다${ragNote}.`, 'error');
                    return;
                }

                // 2) 즉시 다시 그리기(우측 LLM 이미지)
                const generationWorkflow = cmCollectSettings().generation_workflow;
                cmSetBusy(
                    true,
                    `${baseLabel} · ${generationWorkflow === 'illustration' ? '삽화' : '에셋'} 워크플로우에서 LLM 결과를 그리는 중...`,
                );
                cmPrepareSeedForGenerate();
                const promptData = await cmBuildPromptData('llm');
                const genPayload = {
                    world_context: cmSession.world_context || '',
                    locks: Object.fromEntries(CM_FIELDS.map(field => [field, !!cmSession.locks?.[field]])),
                    settings: cmCollectSettings(),
                    source: 'llm',
                    positive_prompt: promptData.positive,
                    negative_prompt: promptData.negative || '',
                    note: `LLM(${baseLabel}) · 외모 ${(llmFields.appearance || []).length} · 복장 ${(llmFields.outfit || []).length} · 표정 ${(llmFields.expression || []).length} · 구도 ${(llmFields.composition || []).length}`,
                };
                const genData = await cmRequest(`/api/character_maker/session/${encodeURIComponent(sessionId)}/generate`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(genPayload),
                });
                cmSession = genData.session;
                cmRender();
                const ragNote = data.rag?.enabled ? ' · RAG 후보 검증 포함' : '';
                showToast(
                    `${baseLabel} LLM 수정 후 ${generationWorkflow === 'illustration' ? '삽화' : '에셋'}으로 그렸습니다${ragNote}.`,
                    'success',
                );
            } catch (error) {
                console.error('[CHARACTER_MAKER] LLM 수정 실패:', error);
                if (cmSession?.settings?.rag_enabled) {
                    cmRagVerified = false;
                    cmRenderStatus();
                }
                showToast('LLM 수정 실패: ' + error.message, 'error');
            } finally {
                cmSetBusy(false);
            }
        }

        async function cmAccept() {
            if (cmBusy || !cmSession) return;
            if (!cmSession.llm_active_revision_id) {
                showToast('accept 할 LLM 결과가 없습니다. 먼저 LLM 수정으로 이미지를 그려주세요.', 'error');
                return;
            }
            cmSetBusy(true, 'LLM 결과를 사용자 영역으로 복사하는 중...');
            try {
                const data = await cmRequest(`/api/character_maker/session/${encodeURIComponent(cmSession.id)}/accept`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                });
                cmSession = data.session;
                cmApplySettingsToUI();
                cmRender();
                showToast('LLM 결과와 현재 대화 분기를 사용자 체크포인트에 병합했습니다.', 'success');
            } catch (error) {
                console.error('[CHARACTER_MAKER] accept 실패:', error);
                showToast('accept 실패: ' + error.message, 'error');
            } finally {
                cmSetBusy(false);
            }
        }

        function cmBuildGenerationSlot(fields = cmSession?.fields, naturalLanguage = '') {
            const settings = cmCollectSettings();
            const src = fields || (cmSession?.fields);
            const slot = {
                asset_workflow_type: settings.asset_workflow_type,
                raw_appearance_tags: [...(src.appearance || [])],
                raw_outfit_tags: [...(src.outfit || [])],
                raw_expression_tags: [...(src.expression || [])],
                raw_composition_tags: [...(src.composition || [])],
                quality_preset: settings.quality_preset,
                artist_preset: settings.artist_preset,
                negative_preset: settings.negative_preset,
                character_negative_preset: settings.character_negative_preset,
                anima_quality_preset: settings.anima_quality_preset,
                anima_artist_preset: settings.anima_artist_preset,
                anima_negative_preset: settings.anima_negative_preset,
                natural_language: naturalLanguage || '',
                lora_list: (settings.lora_list || []).map(item => ({...item})),
                lora_enabled: !!settings.lora_enabled,
                style_lora_list: (settings.style_lora_list || []).map(item => ({...item})),
                style_lora_enabled: !!settings.style_lora_enabled,
                snapref_enabled: !!settings.snapref_enabled,
                snapref_images: (settings.snapref_images || []).map(item => ({...item})),
                snapref_dir: settings.snapref_dir || '',
                snapref_mode: settings.snapref_mode || 'char',
                snapref_strength: settings.snapref_strength ?? 0,
                snapref_megapixels: settings.snapref_megapixels ?? 1,
                face_lora_list: (settings.face_lora_list || []).map(item => ({...item})),
                face_lora_enabled: !!settings.face_lora_enabled,
                face_lora_upscale_size: settings.face_lora_upscale_size ?? '',
                face_tags: settings.face_tags || '',
                eye_tags: settings.eye_tags || '',
                ref_enabled: false,
                ref_strength: 0.55,
                style_ref_enabled: false,
                style_ref_strength: 0.55,
                pose_enabled: false,
                hrf_sdxl: !!settings.hrf_sdxl,
                hrf_anima: !!settings.hrf_anima,
                hrf_size: settings.hrf_size ?? 2,
                hrf_restore_size: settings.hrf_restore_size !== false,
                hrf_control_net: !!settings.hrf_control_net,
                sdxl_fd_enabled: !!settings.sdxl_fd_enabled,
                sdxl_hd_enabled: !!settings.sdxl_hd_enabled,
                sdxl_ed_enabled: !!settings.sdxl_ed_enabled,
                anima_fd_enabled: !!settings.anima_fd_enabled,
                anima_hd_enabled: !!settings.anima_hd_enabled,
                anima_ed_enabled: !!settings.anima_ed_enabled,
                face_crop_top: settings.face_crop_top ?? 2.5,
                face_crop_bottom: settings.face_crop_bottom ?? 1,
                img_w: settings.img_w,
                img_h: settings.img_h,
                seed: settings.seed,
            };
            cmEnsureEditablePresetState();
            CM_EDITABLE_PRESET_FIELDS.forEach(field => {
                if (!cmSession?.editable_preset_enabled?.[field]) return;
                const config = CM_EDITABLE_PRESETS[field];
                slot[config.rawSlotKey] = [
                    ...(cmSession.editable_preset_tags?.[field] || []),
                ];
            });
            return slot;
        }

        async function cmBuildPromptData(source = 'user') {
            const generationWorkflow = cmCollectSettings().generation_workflow;
            if (generationWorkflow === 'illustration') {
                const data = await cmRequest(
                    `/api/character_maker/session/${encodeURIComponent(cmSession.id)}/illustration-prompt`,
                    {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ ...cmCurrentPayload(), source }),
                    },
                );
                const promptData = data.prompt;
                if (!promptData?.positive) {
                    console.error('[CHARACTER_MAKER] 삽화 프롬프트 생성 결과가 비어 있습니다:', data);
                    throw new Error('삽화 생성 프롬프트를 만들지 못했습니다.');
                }
                return promptData;
            }
            if (!assetTags) {
                console.error('[CHARACTER_MAKER] 프롬프트 생성 실패: assetTags가 비어 있습니다.');
                throw new Error('에셋 프리셋 데이터가 준비되지 않았습니다.');
            }
            const fields = source === 'llm'
                ? (cmSession?.llm_fields || cmSession?.fields)
                : (cmSession?.fields);
            const naturalLanguage = source === 'llm'
                ? (cmSession?.llm_natural_language ?? cmSession?.natural_language ?? '')
                : (cmSession?.natural_language ?? '');
            const promptData = await buildAssetPromptData(
                cmBuildGenerationSlot(fields, naturalLanguage)
            );
            if (!promptData?.positive) {
                console.error('[CHARACTER_MAKER] 프롬프트 생성 결과가 비어 있습니다:', promptData);
                throw new Error('생성 프롬프트를 만들지 못했습니다.');
            }
            return promptData;
        }

        async function cmGenerate() {
            if (cmBusy || !cmSession) return;
            if (!(cmSession.fields.appearance || []).length || !(cmSession.fields.outfit || []).length) {
                showToast('이미지 생성 전에 외모와 복장 태그를 각각 하나 이상 준비하세요.', 'error');
                return;
            }
            const generationWorkflow = cmCollectSettings().generation_workflow;
            cmSetBusy(
                true,
                generationWorkflow === 'illustration'
                    ? '삽화 워크플로우에서 새 리비전을 생성하는 중...'
                    : '에셋 워크플로우에서 새 리비전을 생성하는 중...',
            );
            try {
                cmPrepareSeedForGenerate();
                const promptData = await cmBuildPromptData('user');
                const payload = {
                    ...cmCurrentPayload(),
                    source: 'user',
                    positive_prompt: promptData.positive,
                    negative_prompt: promptData.negative || '',
                    note: `외모 ${cmSession.fields.appearance.length} · 복장 ${cmSession.fields.outfit.length} · 표정 ${cmSession.fields.expression.length} · 구도 ${cmSession.fields.composition.length}`,
                };
                const data = await cmRequest(`/api/character_maker/session/${encodeURIComponent(cmSession.id)}/generate`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload),
                });
                cmSession = data.session;
                cmRender();
                showToast(
                    `새 ${generationWorkflow === 'illustration' ? '삽화' : '에셋'} 리비전 R${cmSession.revisions.length}을 생성했습니다.`,
                    'success',
                );
            } catch (error) {
                console.error('[CHARACTER_MAKER] 이미지 생성 실패:', error);
                showToast('이미지 생성 실패: ' + error.message, 'error');
            } finally {
                cmSetBusy(false);
            }
        }

        async function cmPreviewPrompt() {
            if (!cmSession) return;
            try {
                const promptData = await cmBuildPromptData();
                document.getElementById('cm-prompt-preview-modal')?.remove();
                const modal = document.createElement('div');
                modal.id = 'cm-prompt-preview-modal';
                modal.className = 'cm-modal visible';
                modal.innerHTML = `
                    <div class="cm-modal-shell" style="width:min(860px,95vw);">
                        <div class="cm-modal-head">
                            <div class="cm-modal-title">생성 프롬프트 미리보기</div>
                            <button class="cm-modal-close" type="button" aria-label="닫기">✕</button>
                        </div>
                        <div class="cm-modal-body">
                            <div class="cm-hint" style="margin-bottom:5px;">Positive</div>
                            <pre data-positive style="max-height:38vh;overflow:auto;padding:10px;border:1px solid var(--border);border-radius:8px;background:var(--surface2);white-space:pre-wrap;word-break:break-word;font-size:.7rem;"></pre>
                            <div class="cm-hint" style="margin:12px 0 5px;">Negative</div>
                            <pre data-negative style="max-height:20vh;overflow:auto;padding:10px;border:1px solid var(--border);border-radius:8px;background:var(--surface2);white-space:pre-wrap;word-break:break-word;font-size:.7rem;"></pre>
                        </div>
                    </div>`;
                modal.querySelector('[data-positive]').textContent = promptData.positive;
                modal.querySelector('[data-negative]').textContent = promptData.negative || '(비어 있음)';
                modal.querySelector('.cm-modal-close').onclick = () => modal.remove();
                modal.onclick = event => { if (event.target === modal) modal.remove(); };
                document.body.appendChild(modal);
            } catch (error) {
                console.error('[CHARACTER_MAKER] 프롬프트 미리보기 실패:', error);
                showToast('프롬프트 미리보기 실패: ' + error.message, 'error');
            }
        }

        async function cmUploadReferences(fileList) {
            if (cmBusy || !cmSession) return;
            const files = [...(fileList || [])].filter(file => file.type?.startsWith('image/'));
            if (!files.length) {
                console.error('[CHARACTER_MAKER] 참고 이미지 업로드 스킵: 이미지 파일 없음');
                showToast('업로드할 이미지 파일을 선택하세요.', 'error');
                return;
            }
            const remaining = Math.max(0, 8 - (cmSession.references || []).length);
            if (!remaining) {
                showToast('참고 이미지는 최대 8장까지 올릴 수 있습니다.', 'error');
                return;
            }
            const selected = files.slice(0, remaining);
            const form = new FormData();
            selected.forEach(file => form.append('files', file, file.name));
            cmSetBusy(true, `참고 이미지 ${selected.length}장을 준비하는 중...`);
            try {
                const data = await cmRequest(`/api/character_maker/session/${encodeURIComponent(cmSession.id)}/reference`, {
                    method: 'POST',
                    body: form,
                });
                cmSession = data.session;
                cmRenderReferences();
                cmRenderStatus();
                const input = document.getElementById('cm-reference-input');
                if (input) input.value = '';
                showToast(`참고 이미지 ${data.uploaded || selected.length}장을 추가했습니다.`, 'success');
            } catch (error) {
                console.error('[CHARACTER_MAKER] 참고 이미지 업로드 실패:', error);
                showToast('참고 이미지 업로드 실패: ' + error.message, 'error');
            } finally {
                cmSetBusy(false);
            }
        }

        async function cmRemoveReference(referenceId) {
            if (cmBusy || !cmSession) return;
            try {
                const data = await cmRequest(`/api/character_maker/session/${encodeURIComponent(cmSession.id)}/reference/${encodeURIComponent(referenceId)}`, {
                    method: 'DELETE',
                });
                cmSession = data.session;
                cmRenderReferences();
                cmRenderStatus();
            } catch (error) {
                console.error('[CHARACTER_MAKER] 참고 이미지 삭제 실패:', referenceId, error);
                showToast('참고 이미지 삭제 실패: ' + error.message, 'error');
            }
        }

        async function cmSelectRevision(revisionId, source) {
            if (cmBusy || !cmSession) return;
            const key = source === 'llm' ? 'llm_active_revision_id' : 'active_revision_id';
            if (cmSession[key] === revisionId) return;
            try {
                const data = await cmRequest(`/api/character_maker/session/${encodeURIComponent(cmSession.id)}`, {
                    method: 'PATCH',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ [key]: revisionId }),
                });
                cmSession = data.session;
                cmRenderStage();
                cmRenderStatus();
            } catch (error) {
                console.error('[CHARACTER_MAKER] 리비전 선택 실패:', revisionId, source, error);
                showToast('리비전 선택 실패: ' + error.message, 'error');
            }
        }

        function cmGetActiveUserRevision() {
            if (!cmSession?.active_revision_id) return null;
            return (cmSession.revisions || []).find(
                revision => revision.id === cmSession.active_revision_id,
            ) || null;
        }

        function cmRenderConfirmEditablePresets(activeRevision) {
            const section = document.getElementById('cm-confirm-editable-presets');
            const list = document.getElementById('cm-confirm-editable-preset-list');
            if (!section || !list) return;
            const enabled = activeRevision?.editable_preset_enabled || {};
            const tagsByField = activeRevision?.editable_preset_tags || {};
            const fields = CM_EDITABLE_PRESET_FIELDS.filter(field => !!enabled[field]);
            section.style.display = fields.length ? '' : 'none';
            list.innerHTML = fields.map(field => {
                const config = CM_EDITABLE_PRESETS[field];
                const count = Array.isArray(tagsByField[field]) ? tagsByField[field].length : 0;
                return `
                    <div class="cm-confirm-preset-row" data-confirm-editable-preset="${field}">
                        <div class="cm-confirm-preset-title">${escapeHtml(config.label)} <span>${count} tags · LLM 제외 편집본</span></div>
                        <label class="cm-confirm-representative">
                            <input type="checkbox" data-save-editable-preset onchange="cmUpdateConfirmEditablePresetMode('${field}')">
                            <span>선택 이미지에 사용한 편집본을 새 프리셋으로 저장</span>
                        </label>
                        <div class="cm-confirm-field" style="margin-top:7px;">
                            <label>새 ${escapeHtml(config.label)} 프리셋 이름</label>
                            <input data-editable-preset-name disabled placeholder="예: 캐릭터용 ${escapeHtml(config.label)}" oninput="cmUpdateConfirmSummary()">
                        </div>
                    </div>`;
            }).join('');
        }

        function cmUpdateConfirmEditablePresetMode(field) {
            const row = document.querySelector(`[data-confirm-editable-preset="${field}"]`);
            if (!row) {
                console.error('[CHARACTER_MAKER] 확정 생성 프리셋 행을 찾을 수 없습니다:', field);
                return;
            }
            const save = !!row.querySelector('[data-save-editable-preset]')?.checked;
            const nameInput = row.querySelector('[data-editable-preset-name]');
            if (nameInput) nameInput.disabled = !save;
            cmUpdateConfirmSummary();
        }

        function cmCollectEditablePresetRegistrations(activeRevision = cmGetActiveUserRevision()) {
            const enabled = activeRevision?.editable_preset_enabled || {};
            return Object.fromEntries(
                CM_EDITABLE_PRESET_FIELDS
                    .filter(field => !!enabled[field])
                    .map(field => {
                        const row = document.querySelector(`[data-confirm-editable-preset="${field}"]`);
                        const save = !!row?.querySelector('[data-save-editable-preset]')?.checked;
                        const name = row?.querySelector('[data-editable-preset-name]')?.value?.trim() || '';
                        return [field, { mode: save ? 'new' : 'none', name: save ? name : '' }];
                    })
            );
        }

        function cmOpenConfirm() {
            if (!cmSession) return;
            const activeRevision = cmGetActiveUserRevision();
            if (!activeRevision) {
                console.error('[CHARACTER_MAKER] 확정창 열기 실패: 현재 사용자 이미지가 없습니다.', {
                    active_revision_id: cmSession.active_revision_id || '',
                });
                showToast('확정 전에 사용자 이미지를 생성하거나 사용자 영역에 적용하세요.', 'error');
                return;
            }
            cmPopulatePresetOptions();
            const revisionInput = document.getElementById('cm-confirm-revision');
            if (revisionInput) {
                const revisionIndex = (cmSession.revisions || []).findIndex(
                    revision => revision.id === activeRevision.id,
                );
                const sourceLabel = activeRevision.source === 'llm' ? 'LLM 적용본' : 'USER 생성본';
                revisionInput.value = `사용자 R${revisionIndex + 1} · ${sourceLabel}`;
                revisionInput.dataset.revisionId = activeRevision.id;
            }
            const previewImage = document.getElementById('cm-confirm-preview-image');
            if (previewImage) {
                previewImage.src = `${activeRevision.url}?v=${encodeURIComponent(activeRevision.created_at || '')}`;
                previewImage.onclick = () => openLightbox(previewImage.src);
                previewImage.onerror = () => {
                    console.error('[CHARACTER_MAKER] 확정 이미지 미리보기 실패:', {
                        revision_id: activeRevision.id,
                        url: activeRevision.url,
                    });
                };
            }
            const presetSources = {
                appearance: assetTags?.appearances || {},
                outfit: assetTags?.outfits || {},
                expression: assetTags?.expressions || {},
            };
            Object.entries(presetSources).forEach(([kind, values]) => {
                const modeSelect = document.getElementById(`cm-confirm-${kind}-mode`);
                const existingOption = modeSelect?.querySelector('option[value="existing"]');
                const hasExisting = Object.keys(values).length > 0;
                if (existingOption) existingOption.disabled = !hasExisting;
                if (modeSelect?.value === 'existing' && !hasExisting) {
                    modeSelect.value = 'new';
                }
            });
            const expressionMode = document.getElementById('cm-confirm-expression-mode');
            if (expressionMode) {
                expressionMode.value = Object.keys(assetTags?.expressions || {}).length
                    ? 'existing'
                    : 'new';
            }
            document.getElementById('cm-confirm-composition-mode').value = 'none';
            const representativeCheckbox = document.getElementById('cm-confirm-set-representative');
            if (representativeCheckbox) representativeCheckbox.checked = false;
            const naturalLanguageCheckbox = document.getElementById('cm-confirm-save-natural-language');
            if (naturalLanguageCheckbox) naturalLanguageCheckbox.checked = false;
            const naturalLanguageName = document.getElementById('cm-confirm-natural-language-name');
            if (naturalLanguageName) naturalLanguageName.value = '';
            const naturalLanguagePreview = document.getElementById('cm-confirm-natural-language-preview');
            if (naturalLanguagePreview) {
                const naturalLanguage = String(activeRevision.natural_language || '').trim();
                naturalLanguagePreview.textContent = naturalLanguage
                    ? `${naturalLanguage.length}자 · ${naturalLanguage}`
                    : '선택 이미지에는 저장할 자연어가 없습니다.';
            }
            cmRenderConfirmEditablePresets(activeRevision);
            const targetSelect = document.getElementById('cm-confirm-registration-mode');
            const existingTarget = targetSelect?.querySelector('option[value="existing"]');
            const hasExistingCharacters = Object.keys(assetTags?.characters || {}).length > 0;
            if (existingTarget) existingTarget.disabled = !hasExistingCharacters;
            if (targetSelect?.value === 'existing' && !hasExistingCharacters) {
                targetSelect.value = 'new';
            }
            cmUpdateConfirmRegistrationMode();
            cmUpdateConfirmMode();
            cmUpdateConfirmSummary();
            document.getElementById('cm-confirm-modal')?.classList.add('visible');
        }

        function cmCloseConfirm() {
            document.getElementById('cm-confirm-modal')?.classList.remove('visible');
        }

        function cmUpdateConfirmRegistrationMode() {
            const registrationMode = document.getElementById('cm-confirm-registration-mode')?.value || 'new';
            const existing = registrationMode === 'existing';
            const newField = document.getElementById('cm-confirm-new-character-field');
            const existingField = document.getElementById('cm-confirm-existing-character-field');
            if (newField) newField.style.display = existing ? 'none' : '';
            if (existingField) existingField.style.display = existing ? '' : 'none';
            cmUpdateConfirmMode();
        }

        function cmGetConfirmCharacterName() {
            const registrationMode = document.getElementById('cm-confirm-registration-mode')?.value || 'new';
            return registrationMode === 'existing'
                ? (document.getElementById('cm-confirm-existing-character')?.value || '')
                : (document.getElementById('cm-confirm-character')?.value.trim() || '');
        }

        function cmGetConfirmPresetSelection(kind) {
            const mode = document.getElementById(`cm-confirm-${kind}-mode`)?.value || 'new';
            const valueElement = document.getElementById(
                mode === 'existing'
                    ? `cm-confirm-${kind}-existing`
                    : `cm-confirm-${kind}-new`,
            );
            return {
                mode,
                name: valueElement?.value?.trim() || '',
            };
        }

        function cmUseCharacterDefaultsForExistingPresets(force = false) {
            const registrationMode = document.getElementById('cm-confirm-registration-mode')?.value || 'new';
            if (registrationMode !== 'existing') return;
            const characterName = document.getElementById('cm-confirm-existing-character')?.value || '';
            const character = assetTags?.characters?.[characterName];
            if (!character || typeof character !== 'object') return;
            ['appearance', 'outfit', 'expression'].forEach(kind => {
                const mode = document.getElementById(`cm-confirm-${kind}-mode`)?.value;
                const select = document.getElementById(`cm-confirm-${kind}-existing`);
                const defaultName = character[kind];
                if (
                    mode === 'existing'
                    && select
                    && (force || !select.value)
                    && [...select.options].some(option => option.value === defaultName)
                ) {
                    select.value = defaultName;
                }
            });
        }

        function cmConfirmExistingCharacterChanged() {
            cmUseCharacterDefaultsForExistingPresets(true);
            cmUpdateConfirmSummary();
        }

        function cmUpdateConfirmMode() {
            ['appearance', 'outfit', 'expression'].forEach(kind => {
                const mode = document.getElementById(`cm-confirm-${kind}-mode`)?.value || 'new';
                const existingField = document.getElementById(`cm-confirm-${kind}-existing-field`);
                const newField = document.getElementById(`cm-confirm-${kind}-new-field`);
                if (existingField) existingField.style.display = mode === 'existing' ? '' : 'none';
                if (newField) newField.style.display = mode === 'new' ? '' : 'none';
            });
            cmUseCharacterDefaultsForExistingPresets();

            const compositionMode = document.getElementById('cm-confirm-composition-mode')?.value || 'none';
            const composition = document.getElementById('cm-confirm-composition');
            if (composition) composition.disabled = compositionMode !== 'new';
            const saveNaturalLanguage = document.getElementById('cm-confirm-save-natural-language')?.checked || false;
            const naturalLanguageName = document.getElementById('cm-confirm-natural-language-name');
            if (naturalLanguageName) naturalLanguageName.disabled = !saveNaturalLanguage;
            cmUpdateConfirmSummary();
        }

        function cmUpdateConfirmSummary() {
            const summary = document.getElementById('cm-confirm-summary');
            if (!summary || !cmSession) return;
            const registrationMode = document.getElementById('cm-confirm-registration-mode')?.value || 'new';
            const activeRevision = cmGetActiveUserRevision();
            const revisionFields = activeRevision?.fields || {};
            const characterName = cmGetConfirmCharacterName();
            const appearance = cmGetConfirmPresetSelection('appearance');
            const outfit = cmGetConfirmPresetSelection('outfit');
            const expression = cmGetConfirmPresetSelection('expression');
            const compositionMode = document.getElementById('cm-confirm-composition-mode')?.value || 'none';
            const setRepresentative = document.getElementById('cm-confirm-set-representative')?.checked || false;
            const saveNaturalLanguage = document.getElementById('cm-confirm-save-natural-language')?.checked || false;
            const naturalLanguageName = document.getElementById('cm-confirm-natural-language-name')?.value.trim() || '';
            const revisionNaturalLanguage = String(activeRevision?.natural_language || '').trim();
            const displayPart = value => escapeHtml(value || '(선택 필요)');
            const editablePresetRegistrations = cmCollectEditablePresetRegistrations(activeRevision);
            const editablePresetFields = CM_EDITABLE_PRESET_FIELDS.filter(
                field => !!activeRevision?.editable_preset_enabled?.[field]
            );
            const editablePresetSummary = editablePresetFields.length
                ? editablePresetFields.map(field => {
                    const registration = editablePresetRegistrations[field] || { mode: 'none', name: '' };
                    const tagCount = activeRevision?.editable_preset_tags?.[field]?.length || 0;
                    return registration.mode === 'new'
                        ? `${CM_EDITABLE_PRESETS[field].label} '${displayPart(registration.name)}'(${tagCount})`
                        : `${CM_EDITABLE_PRESETS[field].label} 저장 안 함(${tagCount})`;
                }).join(' · ')
                : '없음';
            const selectionLabel = (selection, fieldName) => selection.mode === 'existing'
                ? `기존 '${displayPart(selection.name)}'`
                : `새로 등록 '${displayPart(selection.name)}' · ${(revisionFields[fieldName] || []).length} tags`;
            const path = document.getElementById('cm-confirm-path');
            if (path) {
                path.innerHTML = `
                    <span class="cm-confirm-path-label">실제 카드 저장 폴더</span>
                    <code>asset / ${displayPart(characterName)} / ${displayPart(outfit.name)} / ${displayPart(expression.name)}</code>
                `;
            }
            summary.innerHTML = `
                <b>등록 대상</b> · ${registrationMode === 'existing'
                    ? `기존 캐릭터 ${displayPart(characterName)} · 현재 기본값 유지`
                    : `새 캐릭터 ${displayPart(characterName)}`}<br>
                <b>외모</b> · ${selectionLabel(appearance, 'appearance')}<br>
                <b>복장</b> · ${selectionLabel(outfit, 'outfit')}<br>
                <b>표정</b> · ${selectionLabel(expression, 'expression')}<br>
                <b>대표 이미지</b> · ${setRepresentative
                    ? '이 카드로 교체'
                    : '기존 대표 유지 · 대표가 없으면 자동 지정'}<br>
                <b>구도</b> · ${compositionMode === 'none'
                    ? '등록 안 함'
                    : `새로 등록 · ${(revisionFields.composition || []).length} tags`}<br>
                <b>자연어</b> · ${saveNaturalLanguage
                    ? `새로 등록 '${displayPart(naturalLanguageName)}' · ${revisionNaturalLanguage.length}자`
                    : '프리셋 등록 안 함 · 카드 기록에는 보존'}<br>
                <b>생성 프리셋 편집본</b> · ${editablePresetSummary}<br>
                새 프리셋이나 캐릭터 정보를 저장할 때는 먼저 <code>backups/</code>에 태그 데이터를 백업합니다.
            `;
        }

        async function cmConfirmCharacter() {
            if (cmBusy || !cmSession) return;
            const activeRevision = cmGetActiveUserRevision();
            if (!activeRevision) {
                console.error('[CHARACTER_MAKER] 확정 실패: 현재 사용자 이미지가 없습니다.', {
                    active_revision_id: cmSession.active_revision_id || '',
                });
                showToast('등록할 현재 사용자 이미지가 없습니다.', 'error');
                return;
            }
            const registrationMode = document.getElementById('cm-confirm-registration-mode')?.value || 'new';
            const appearance = cmGetConfirmPresetSelection('appearance');
            const outfit = cmGetConfirmPresetSelection('outfit');
            const expression = cmGetConfirmPresetSelection('expression');
            const compositionMode = document.getElementById('cm-confirm-composition-mode')?.value || 'none';
            const saveNaturalLanguage = document.getElementById('cm-confirm-save-natural-language')?.checked || false;
            const characterName = cmGetConfirmCharacterName();
            const editablePresetRegistrations = cmCollectEditablePresetRegistrations(activeRevision);
            const payload = {
                registration_mode: registrationMode,
                character_name: characterName,
                appearance_mode: appearance.mode,
                appearance_name: appearance.name,
                outfit_mode: outfit.mode,
                outfit_name: outfit.name,
                expression_mode: expression.mode,
                expression_name: expression.name,
                composition_mode: compositionMode,
                composition_name: compositionMode === 'new'
                    ? (document.getElementById('cm-confirm-composition')?.value.trim() || '')
                    : '',
                natural_language_mode: saveNaturalLanguage ? 'new' : 'none',
                natural_language_name: saveNaturalLanguage
                    ? (document.getElementById('cm-confirm-natural-language-name')?.value.trim() || '')
                    : '',
                editable_preset_registrations: editablePresetRegistrations,
                set_representative: document.getElementById('cm-confirm-set-representative')?.checked || false,
                revision_id: activeRevision.id,
            };
            if (!payload.character_name || !payload.appearance_name || !payload.outfit_name) {
                console.error('[CHARACTER_MAKER] 확정 입력 누락:', payload);
                showToast(
                    registrationMode === 'existing'
                        ? '기존 캐릭터와 외모·복장을 모두 선택하세요.'
                        : '새 캐릭터 이름과 외모·복장을 모두 입력하거나 선택하세요.',
                    'error',
                );
                return;
            }
            if (!payload.expression_name) {
                console.error('[CHARACTER_MAKER] 확정 표정 누락:', payload);
                showToast('등록하거나 사용할 표정 프리셋을 선택하세요.', 'error');
                return;
            }
            const revisionFields = activeRevision.fields || {};
            for (const [selection, fieldName, label] of [
                [appearance, 'appearance', '외모'],
                [outfit, 'outfit', '복장'],
                [expression, 'expression', '표정'],
            ]) {
                if (selection.mode === 'new' && !(revisionFields[fieldName] || []).length) {
                    console.error(`[CHARACTER_MAKER] 새 ${label} 프리셋 태그 누락:`, {
                        revision_id: activeRevision.id,
                        field: fieldName,
                    });
                    showToast(`새 ${label} 프리셋으로 등록할 이미지 생성 당시 태그가 없습니다.`, 'error');
                    return;
                }
            }
            if (compositionMode === 'new' && !payload.composition_name) {
                console.error('[CHARACTER_MAKER] 새 구도 이름 누락:', payload);
                showToast('새 구도 프리셋 이름을 입력하세요.', 'error');
                return;
            }
            if (
                compositionMode === 'new'
                && !(revisionFields.composition || []).length
            ) {
                console.error('[CHARACTER_MAKER] 새 구도 프리셋 태그 누락:', {
                    revision_id: activeRevision.id,
                });
                showToast('새 구도로 등록할 이미지 생성 당시 태그가 없습니다.', 'error');
                return;
            }
            if (saveNaturalLanguage && !payload.natural_language_name) {
                console.error('[CHARACTER_MAKER] 새 자연어 프리셋 이름 누락:', payload);
                showToast('새 자연어 프리셋 이름을 입력하세요.', 'error');
                return;
            }
            if (saveNaturalLanguage && !String(activeRevision.natural_language || '').trim()) {
                console.error('[CHARACTER_MAKER] 새 자연어 프리셋 원문 누락:', {
                    revision_id: activeRevision.id,
                });
                showToast('선택 이미지 생성 당시 저장된 자연어가 없습니다.', 'error');
                return;
            }
            for (const [field, registration] of Object.entries(editablePresetRegistrations)) {
                if (registration.mode !== 'new') continue;
                const config = CM_EDITABLE_PRESETS[field];
                if (!registration.name) {
                    console.error('[CHARACTER_MAKER] 새 생성 프리셋 이름 누락:', field, registration);
                    showToast(`새 ${config?.label || field} 프리셋 이름을 입력하세요.`, 'error');
                    return;
                }
                if (!(activeRevision.editable_preset_tags?.[field] || []).length) {
                    console.error('[CHARACTER_MAKER] 새 생성 프리셋 태그 누락:', {
                        revision_id: activeRevision.id,
                        field,
                    });
                    showToast(`새 ${config?.label || field} 프리셋으로 저장할 태그가 없습니다.`, 'error');
                    return;
                }
            }

            cmSetBusy(
                true,
                registrationMode === 'existing'
                    ? '기존 캐릭터 폴더에 이미지 카드와 프롬프트를 추가하는 중...'
                    : '새 캐릭터 폴더와 이미지 카드를 등록하는 중...',
            );
            const submit = document.getElementById('cm-confirm-submit');
            if (submit) submit.disabled = true;
            try {
                const data = await cmRequest(`/api/character_maker/session/${encodeURIComponent(cmSession.id)}/confirm`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload),
                });
                cmSession = data.session;
                cmCloseConfirm();
                cmRender();
                try {
                    await loadAssetData();
                } catch (reloadError) {
                    console.error('[CHARACTER_MAKER] 확정 후 에셋 프리셋 다시 읽기 실패:', reloadError);
                }
                const newPresetLabels = [
                    data.finalized.appearance_mode === 'new' ? '외모' : '',
                    data.finalized.outfit_mode === 'new' ? '복장' : '',
                    payload.expression_mode === 'new' ? '표정' : '',
                    payload.composition_mode === 'new' ? '구도' : '',
                    data.finalized.natural_language_mode === 'new' ? '자연어' : '',
                ].filter(Boolean);
                Object.keys(data.finalized.editable_preset_registrations || {}).forEach(field => {
                    newPresetLabels.push(CM_EDITABLE_PRESETS[field]?.label || field);
                });
                const representativeLabel = data.finalized.representative_updated
                    ? '대표 이미지도 반영했습니다.'
                    : '기존 대표 이미지는 유지했습니다.';
                showToast(
                    data.finalized.registration_mode === 'existing'
                        ? `기존 캐릭터 '${data.finalized.character_name}'에 이미지 카드를 추가했습니다. ${newPresetLabels.length ? `새 프리셋: ${newPresetLabels.join('·')}. ` : ''}${representativeLabel}`
                        : `캐릭터 '${data.finalized.character_name}'과 이미지 카드를 등록했습니다. ${representativeLabel}`,
                    'success',
                    7000,
                );
            } catch (error) {
                console.error('[CHARACTER_MAKER] 캐릭터 확정 실패:', payload, error);
                showToast('캐릭터 확정 실패: ' + error.message, 'error', 7000);
            } finally {
                if (submit) submit.disabled = false;
                cmSetBusy(false);
            }
        }

        async function cmResetSession() {
            if (cmBusy) return;
            if (cmSession && !window.confirm('현재 캐릭터 작업을 지우고 새 캐릭터를 시작할까요?')) return;
            const generationState = cmCurrentGenerationState();
            // 이전 캐릭터의 디바운스 PATCH가 새 세션을 다시 덮지 않도록 대기 작업을 폐기한다.
            clearTimeout(cmSyncTimer);
            cmSyncTimer = null;
            cmSyncVersion++;
            cmSetBusy(true, '새 캐릭터 작업공간을 만드는 중...');
            try {
                cmSession = null;
                cmLastDiff = null;
                cmRagVerified = false;
                // POST create = 생성 설정은 보존하고 캐릭터 작업만 리셋.
                await cmCreateSession(generationState);
                cmPopulatePresetOptions();
                cmApplySettingsToUI();
                cmRender();
                showToast('새 캐릭터 작업공간을 만들었습니다.', 'success');
            } catch (error) {
                console.error('[CHARACTER_MAKER] 새 세션 생성 실패:', error);
                showToast('새 캐릭터 시작 실패: ' + error.message, 'error');
            } finally {
                cmSetBusy(false);
            }
        }

