        // ─── 공용 최상단 진행도 바 ───
        function showTopProgress() {
            document.getElementById('top-progress-bar').style.display = 'block';
            document.getElementById('top-progress-inner').style.width = '0%';
            document.getElementById('top-progress-label').textContent = '';
        }
        function updateTopProgress(value, max) {
            const bar = document.getElementById('top-progress-bar');
            if (!bar) return;
            bar.style.display = 'block';
            const pct = max > 0 ? Math.round(value / max * 100) : 0;
            document.getElementById('top-progress-inner').style.width = pct + '%';
            document.getElementById('top-progress-label').textContent = pct + '%';
        }
        function hideTopProgress() {
            document.getElementById('top-progress-bar').style.display = 'none';
            document.getElementById('top-progress-label').textContent = '';
        }
        // 갤러리 네비게이션: 0=캐릭터 목록, 1=캐릭터 갤러리(복장x표정), 2=이미지 상세
