        const INDEPENDENT_SCROLL_CONTAINER_SELECTOR = [
            '#tab-bot-content.active > .independent-scroll-container',
            '#tab-illustration-prompt-content.active > .independent-scroll-container',
            '#tab-comfy-emotion-content.active > .independent-scroll-container',
            '#tab-asset-content.active > .independent-scroll-container',
            '#tab-asset-upload-content.active > .independent-scroll-container',
            '#tab-lora-content.active > #lora-asset-mode > .independent-scroll-container',
            '#tab-lora-content.active > #lora-bot-mode > .independent-scroll-container',
            '#tab-lora-content.active > #lora-instance-mode > .independent-scroll-container',
            '#tab-lora-content.active > #lora-style-mode > .independent-scroll-container',
        ].join(', ');
        let independentScrollResizeFrame = 0;

        function syncIndependentScrollHeight() {
            const containers = document.querySelectorAll(INDEPENDENT_SCROLL_CONTAINER_SELECTOR);
            containers.forEach((container) => {
                // 비활성(display:none) 모드 건너뛰기 — offsetParent가 null이면 화면에 보이지 않는 상태
                if (container.offsetParent === null) return;

                const containerTop = Math.max(0, container.getBoundingClientRect().top);
                const mainElement = container.closest('main');
                const mainBottomPadding = mainElement
                    ? (Number.parseFloat(window.getComputedStyle(mainElement).paddingBottom) || 0)
                    : 0;
                const availableHeight = Math.max(
                    160,
                    Math.floor(window.innerHeight - containerTop - mainBottomPadding),
                );
                container.style.setProperty('--independent-scroll-height', `${availableHeight}px`);
            });
        }

        function scheduleIndependentScrollHeightSync() {
            if (independentScrollResizeFrame) return;
            independentScrollResizeFrame = window.requestAnimationFrame(() => {
                independentScrollResizeFrame = 0;
                syncIndependentScrollHeight();
            });
        }

        // ─── 헤더 시스템 모니터 (RAM/VRAM/CPU/GPU) ───────────────────
        // 서버의 system_stats WS 이벤트로 갱신. GPU 개수만큼 동적으로 GPU{i}/VRAM{i} 줄 생성.
        const _SYSMON_ELS = { strip: null, cpu: null, ram: null, gpuRows: null };

        function _ensureSysmonEls() {
            if (_SYSMON_ELS.strip) return;
            _SYSMON_ELS.strip = document.getElementById('sysmon-strip');
            _SYSMON_ELS.cpu = document.getElementById('sysmon-cpu');
            _SYSMON_ELS.ram = document.getElementById('sysmon-ram');
            _SYSMON_ELS.gpuRows = document.getElementById('sysmon-gpu-rows');
        }

        function _fmtSysmonNum(value, digits) {
            const n = Number(value);
            return Number.isFinite(n) ? n.toFixed(digits) : '—';
        }

        // GPU 한 대당 GPU/VRAM 2줄. gpus 배열 길이에 맞춰 줄을 추가/제거/갱신한다.
        function _renderSysmonGpuRows(gpus) {
            const container = _SYSMON_ELS.gpuRows;
            if (!container) return;
            const want = gpus.length;
            const multi = want > 1;

            while (container.children.length < want * 2) {
                const gpuRow = document.createElement('span');
                gpuRow.className = 'sysmon-row sysmon-gpu-row';
                const gpuLbl = document.createElement('span');
                gpuLbl.className = 'sysmon-label';
                const gpuVal = document.createElement('span');
                gpuVal.className = 'sysmon-value';
                gpuRow.appendChild(gpuLbl);
                gpuRow.appendChild(gpuVal);
                container.appendChild(gpuRow);

                const vramRow = document.createElement('span');
                vramRow.className = 'sysmon-row sysmon-gpu-row';
                const vramLbl = document.createElement('span');
                vramLbl.className = 'sysmon-label';
                const vramVal = document.createElement('span');
                vramVal.className = 'sysmon-value';
                vramRow.appendChild(vramLbl);
                vramRow.appendChild(vramVal);
                container.appendChild(vramRow);
            }
            while (container.children.length > want * 2) {
                container.removeChild(container.lastChild);
            }
            gpus.forEach((gpu, i) => {
                const gpuRow = container.children[i * 2];
                const vramRow = container.children[i * 2 + 1];
                if (gpuRow) {
                    gpuRow.querySelector('.sysmon-label').textContent = multi ? `GPU${i}` : 'GPU';
                    gpuRow.querySelector('.sysmon-value').textContent = `${_fmtSysmonNum(gpu.percent, 0)}%`;
                    gpuRow.title = gpu.name ? String(gpu.name) : '';
                }
                if (vramRow) {
                    vramRow.querySelector('.sysmon-label').textContent = multi ? `VRAM${i}` : 'VRAM';
                    const vramVal = vramRow.querySelector('.sysmon-value');
                    if (gpu.vram_total_gb) {
                        vramVal.textContent = `${_fmtSysmonNum(gpu.vram_used_gb, 1)} / ${_fmtSysmonNum(gpu.vram_total_gb, 0)} GB`;
                        // 여유 1GB 미만 → OOM 임박 경고(빨강). 1GB 이상 회복 시 원래 색으로 복귀.
                        vramVal.classList.toggle('sysmon-crit', (gpu.vram_total_gb - gpu.vram_used_gb) < 1);
                    } else {
                        vramVal.textContent = '—';
                        vramVal.classList.remove('sysmon-crit');
                    }
                }
            });
            container.style.display = want > 0 ? '' : 'none';
        }

        function updateSysmon(data) {
            if (!data || typeof data !== 'object') return;
            try {
                _ensureSysmonEls();
                if (!_SYSMON_ELS.strip) return;

                if (_SYSMON_ELS.cpu) {
                    _SYSMON_ELS.cpu.textContent = data.cpu_available
                        ? `${_fmtSysmonNum(data.cpu_percent, 0)}%`
                        : '—';
                }
                if (_SYSMON_ELS.ram) {
                    if (data.ram_total_gb) {
                        _SYSMON_ELS.ram.textContent = `${_fmtSysmonNum(data.ram_used_gb, 1)} / ${_fmtSysmonNum(data.ram_total_gb, 0)} GB`;
                        // 여유 1GB 미만 → OOM 임박 경고(빨강). 1GB 이상 회복 시 원래 색으로 복귀.
                        _SYSMON_ELS.ram.classList.toggle('sysmon-crit', (data.ram_total_gb - data.ram_used_gb) < 1);
                    } else {
                        _SYSMON_ELS.ram.textContent = '—';
                        _SYSMON_ELS.ram.classList.remove('sysmon-crit');
                    }
                }

                const gpus = Array.isArray(data.gpus)
                    ? data.gpus.filter((g) => g && typeof g === 'object')
                    : [];
                _renderSysmonGpuRows(data.gpu_available ? gpus : []);

                const names = gpus.map((g) => g.name).filter(Boolean).join(', ');
                _SYSMON_ELS.strip.title = names
                    ? `시스템 리소스 (참고용) — ${names}`
                    : '시스템 리소스 (참고용)';
            } catch (e) {
                console.error('[SYSMON] 시스템 통계 갱신 실패:', e);
            }
        }

        const WORKSPACE_CHROME_SESSION_KEY = 'workspaceChromeCollapsed';
        const HEADER_CONTROLS_TOGGLE_LOCK_MS = 260;
        let headerControlsToggleLocked = false;

        function toggleHeaderControlsDock(event) {
            if (event) event.stopPropagation();

            if (headerControlsToggleLocked) return;

            const dock = document.getElementById('header-controls-dock');
            const handle = document.getElementById('header-controls-handle');
            if (!dock || !handle) {
                console.error('[HEADER_CONTROLS] 상단 도구 메뉴 또는 화살표 손잡이를 찾지 못했습니다.', {
                    dockFound: Boolean(dock),
                    handleFound: Boolean(handle),
                });
                return;
            }

            const willPin = !dock.classList.contains('is-pinned');
            dock.classList.toggle('is-pinned', willPin);

            const actionLabel = willPin ? '상단 도구 메뉴 닫기' : '상단 도구 메뉴 열기';
            handle.setAttribute('aria-expanded', String(willPin));
            handle.setAttribute('aria-label', actionLabel);
            handle.title = actionLabel;

            headerControlsToggleLocked = true;
            window.setTimeout(() => {
                headerControlsToggleLocked = false;
            }, HEADER_CONTROLS_TOGGLE_LOCK_MS);
        }

        function setWorkspaceChromeCollapsed(collapsed, persist = true) {
            const isCollapsed = Boolean(collapsed);
            document.body.classList.toggle('workspace-chrome-collapsed', isCollapsed);

            const toggleButton = document.getElementById('workspace-chrome-toggle');
            if (toggleButton) {
                const actionLabel = isCollapsed ? '탭 펼치기' : '탭 접기';
                toggleButton.setAttribute('aria-expanded', String(!isCollapsed));
                toggleButton.setAttribute('aria-label', actionLabel);
                toggleButton.title = actionLabel;
            } else {
                console.error('[WORKSPACE_CHROME] 상단 메뉴 토글 버튼을 찾지 못했습니다.');
            }

            if (persist) {
                try {
                    sessionStorage.setItem(WORKSPACE_CHROME_SESSION_KEY, isCollapsed ? '1' : '0');
                } catch (error) {
                    console.error('[WORKSPACE_CHROME] 접힘 상태 저장 실패:', error);
                }
            }

            scheduleIndependentScrollHeightSync();
        }

        function toggleWorkspaceChrome() {
            setWorkspaceChromeCollapsed(!document.body.classList.contains('workspace-chrome-collapsed'));
        }

        function restoreWorkspaceChromeState() {
            let isCollapsed = false;
            try {
                isCollapsed = sessionStorage.getItem(WORKSPACE_CHROME_SESSION_KEY) === '1';
            } catch (error) {
                console.error('[WORKSPACE_CHROME] 접힘 상태 복원 실패:', error);
            }
            setWorkspaceChromeCollapsed(isCollapsed, false);
        }

        window.addEventListener('resize', scheduleIndependentScrollHeightSync);
