            const main = document.getElementById('bot-main');
            const sidebar = document.getElementById('bot-sidebar');
            if (!main) console.error('[BOT] 캐릭터 목록 스크롤 저장 실패: bot-main 요소가 없습니다.');
            if (!sidebar) console.error('[BOT] 캐릭터 목록 스크롤 저장 실패: bot-sidebar 요소가 없습니다.');
            _botCharacterListScroll = {
                main: main ? main.scrollTop : 0,
                sidebar: sidebar ? sidebar.scrollTop : 0,
            };

            botCurrentChar = charName;
            _botFaceCropFolderOpen = false;
            updateBotBreadcrumb();

            // 사이드바를 캐릭터 상세 액션으로 교체
            const botSection = document.getElementById('bot-char-section');
            const charDetailSidebar = document.getElementById('bot-char-detail-sidebar');

            // 기존 사이드바 섹션 숨기기
