                sdxl_quality_preset: document.getElementById('illust-sdxl-quality-preset').value,
                anima_negative_preset: document.getElementById('illust-anima-negative-preset').value,
                sdxl_negative_preset: document.getElementById('illust-sdxl-negative-preset').value,
                hrf_activate: document.getElementById('illust-hrf-toggle').checked,
                hrf_size: parseFloat(document.getElementById('illust-hrf-size').value) || 1.5,
                hrf_restore_size: document.getElementById('illust-hrf-restore-size').checked,
                anima_hrf_activate: document.getElementById('illust-anima-hrf-toggle').checked,
                img_w: parseInt(document.getElementById('illust-img-w').value) || 756,
                img_h: parseInt(document.getElementById('illust-img-h').value) || 756,
                face_id_activate: document.getElementById('illust-face-id-toggle').checked,
                snapref_enabled: document.getElementById('illust-snapref-toggle').checked,
                snapref_strength: Number(document.getElementById('illust-snapref-strength').value ?? 0),
                snapref_mode: document.getElementById('illust-snapref-mode').value ?? 'char',
