                anima_hd_activate: document.getElementById('illust-anima-hd-toggle').checked,
                anima_ed_activate: document.getElementById('illust-anima-ed-toggle').checked,
                fd_activate: document.getElementById('illust-fd-toggle').checked,
                hd_activate: document.getElementById('illust-hd-toggle').checked,
                ed_activate: document.getElementById('illust-ed-toggle').checked,
                seed: parseInt(document.getElementById('illust-seed-input').value) || -1,
                face_lora_upscale_size: document.getElementById('illust-face-lora-upscale').value || '',
