        function updateIllustToggles() {
            const snaprefOn = document.getElementById('illust-snapref-toggle').checked;
            document.getElementById('illust-snapref-options').style.display = snaprefOn ? 'block' : 'none';
            document.getElementById('illust-snapref-status').textContent = snaprefOn ? 'ON' : 'OFF';
            document.getElementById('illust-snapref-status').className = snaprefOn ? 'toggle-status on' : 'toggle-status off';

            const hrfOn = document.getElementById('illust-hrf-toggle').checked;
            document.getElementById('illust-hrf-status').textContent = hrfOn ? 'ON' : 'OFF';
            document.getElementById('illust-hrf-status').className = hrfOn ? 'toggle-status on' : 'toggle-status off';

            const animaHrfOn = document.getElementById('illust-anima-hrf-toggle').checked;
            document.getElementById('illust-anima-hrf-status').textContent = animaHrfOn ? 'ON' : 'OFF';
            document.getElementById('illust-anima-hrf-status').className = animaHrfOn ? 'toggle-status on' : 'toggle-status off';

            const faceIdOn = document.getElementById('illust-face-id-toggle').checked;
            document.getElementById('illust-face-id-options').style.display = faceIdOn ? 'block' : 'none';
            document.getElementById('illust-face-id-status').textContent = faceIdOn ? 'ON' : 'OFF';
            document.getElementById('illust-face-id-status').className = faceIdOn ? 'toggle-status on' : 'toggle-status off';
        }

        function toggleIllustDetailerChip(checkboxId, chipEl) {
            const cb = document.getElementById(checkboxId);
            if (!cb) return;
            cb.checked = !cb.checked;
            syncIllustDetailerChip(cb, chipEl.id || chipEl);
            saveIllustSettings();
        }

        function syncIllustDetailerChip(checkbox, chipId) {
            const chip = typeof chipId === 'string' ? document.getElementById(chipId) : chipId;
            if (!chip) return;
            if (checkbox.checked) {
                chip.classList.add('active');
            } else {
                chip.classList.remove('active');
            }
        }

        // ─── POSITIVE 화이트리스트/블랙리스트 규칙 ────────────────────
        let _positiveWhitelist = [];
        let _positiveBlacklist = [];
        let _recommendedPositiveWhitelist = [];
        let _recommendedPositiveBlacklist = [];

        function _updatePositiveRulesCount() {
            const el = document.getElementById('positive-rules-count');
            if (!el) return;
            const wl = _positiveWhitelist.length;
            const bl = _positiveBlacklist.length;
            if (wl === 0 && bl === 0) {
                el.textContent = '규칙 없음 (모든 태그 포함)';
            } else {
                el.textContent = `화이트리스트 ${wl}개 / 블랙리스트 ${bl}개`;
            }
        }

        async function loadPositiveRules() {
            try {
                const res = await fetchJSON('/api/bot_mode/positive_rules');
                if (res && !res.error) {
                    _positiveWhitelist = res.positive_whitelist || [];
                    _positiveBlacklist = res.positive_blacklist || [];
                    _recommendedPositiveWhitelist = res.recommended_positive_whitelist || [];
                    _recommendedPositiveBlacklist = res.recommended_positive_blacklist || [];
                } else {
                    _positiveWhitelist = [];
                    _positiveBlacklist = [];
                    _recommendedPositiveWhitelist = [];
                    _recommendedPositiveBlacklist = [];
                }
            } catch (e) {
                console.error('[POSITIVE_RULES] 로드 실패:', e);
                _positiveWhitelist = [];
                _positiveBlacklist = [];
                _recommendedPositiveWhitelist = [];
                _recommendedPositiveBlacklist = [];
            }
            _updatePositiveRulesCount();
        }

        async function openPositiveRulesModal() {
            const existing = document.getElementById('positive-rules-modal');
            if (existing) { existing.remove(); return; }

            await loadPositiveRules();

            const modal = document.createElement('div');
            modal.id = 'positive-rules-modal';
            modal.style.cssText = 'position:fixed; top:50%; left:50%; transform:translate(-50%,-50%); z-index:270; background:var(--surface); border:1px solid var(--border); border-radius:10px; padding:20px; min-width:480px; max-width:600px; max-height:80vh; box-shadow:0 8px 32px rgba(0,0,0,0.4); display:flex; flex-direction:column;';
            modal.innerHTML = `
                <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:14px;">
                    <div style="font-weight:700; font-size:1rem;">POSITIVE 태그 규칙</div>
                    <button onclick="document.getElementById('positive-rules-modal').remove()"
                        style="background:none; border:none; color:var(--text2); font-size:1.2rem; cursor:pointer;">✕</button>
                </div>
                <div style="font-size:0.75rem; color:var(--text2); margin-bottom:12px; padding:6px 8px; background:rgba(0,105,92,0.08); border-radius:4px;">
                    CHAR 섹션에서 캐릭터별로 POSITIVE 태그를 추출할 때 필터링 규칙을 설정합니다.<br>
                    화이트리스트가 있으면 매칭된 태그만 포함, 블랙리스트 + FACE/EYE_TAGS는 자동 제외됩니다.<br>
                    <code style="font-size:0.7rem;">* expressions</code> (접미사), <code style="font-size:0.7rem;">smile *</code> (접두사), <code style="font-size:0.7rem;">smile</code> (정확매칭)
                </div>
                <div style="display:flex; justify-content:flex-end; margin-bottom:12px;">
                    <button onclick="applyRecommendedPositiveRules()"
                        style="background:#00695C; color:#fff; border:none; padding:6px 12px; border-radius:6px; cursor:pointer; font-size:0.8rem; font-weight:600;">추천 태그로 덮어쓰기</button>
                </div>
                <div style="margin-bottom:12px;">
                    <div style="font-size:0.8rem; font-weight:600; color:rgba(76,175,80,0.9); margin-bottom:6px;">화이트리스트 (매칭된 태그만 POSITIVE에 포함)</div>
                    <div id="pr-whitelist-chips" style="display:flex; flex-wrap:wrap; gap:4px; min-height:24px; margin-bottom:6px;"></div>
                    <div style="display:flex; gap:6px;">
                        <input id="pr-whitelist-input" type="text" placeholder="예: * expressions, smile" style="flex:1; padding:6px 10px; border:1px solid var(--border); border-radius:4px; background:var(--surface2); color:var(--text); font-size:0.85rem;">
                        <button onclick="addPositiveRule('whitelist')" style="padding:6px 14px; background:rgba(76,175,80,0.85); color:#fff; border:none; border-radius:4px; font-size:0.85rem; cursor:pointer; font-weight:600;">추가</button>
                    </div>
                </div>
                <div style="margin-bottom:12px;">
                    <div style="font-size:0.8rem; font-weight:600; color:rgba(220,50,50,0.85); margin-bottom:6px;">블랙리스트 (화이트리스트 통과 후 제외)</div>
                    <div style="font-size:0.7rem; color:var(--text2); margin-bottom:4px;">FACE_TAGS, EYE_TAGS는 자동으로 제외됩니다</div>
                    <div id="pr-blacklist-chips" style="display:flex; flex-wrap:wrap; gap:4px; min-height:24px; margin-bottom:6px;"></div>
                    <div style="display:flex; gap:6px;">
                        <input id="pr-blacklist-input" type="text" placeholder="예: open mouth, tears" style="flex:1; padding:6px 10px; border:1px solid var(--border); border-radius:4px; background:var(--surface2); color:var(--text); font-size:0.85rem;">
                        <button onclick="addPositiveRule('blacklist')" style="padding:6px 14px; background:rgba(220,50,50,0.85); color:#fff; border:none; border-radius:4px; font-size:0.85rem; cursor:pointer; font-weight:600;">추가</button>
                    </div>
                </div>
                <div style="display:flex; gap:8px; margin-top:auto; justify-content:flex-end;">
                    <button onclick="document.getElementById('positive-rules-modal').remove()"
                        style="background:var(--surface2); color:var(--text); border:1px solid var(--border); padding:6px 16px; border-radius:6px; cursor:pointer; font-size:0.85rem;">닫기</button>
                    <button onclick="savePositiveRulesFromModal()"
                        style="background:var(--accent); color:#fff; border:none; padding:6px 16px; border-radius:6px; cursor:pointer; font-size:0.85rem;">저장</button>
                </div>
            `;
            document.body.appendChild(modal);
            _renderPositiveChips('whitelist');
            _renderPositiveChips('blacklist');

            // Enter 키 입력
            const wlInput = document.getElementById('pr-whitelist-input');
            const blInput = document.getElementById('pr-blacklist-input');
            if (wlInput) wlInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); addPositiveRule('whitelist'); } });
            if (blInput) blInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); addPositiveRule('blacklist'); } });
        }

        function applyRecommendedPositiveRules() {
            if (_recommendedPositiveWhitelist.length === 0 && _recommendedPositiveBlacklist.length === 0) {
                console.error('[POSITIVE_RULES] 서버에서 추천 태그를 받지 못했습니다.');
                showToast('추천 태그를 불러오지 못했습니다', 'error');
                return;
            }
            if (!window.confirm('현재 편집 중인 POSITIVE 규칙을 추천 태그로 덮어쓸까요?\n저장 버튼을 눌러야 실제로 반영됩니다.')) {
                return;
            }
            _positiveWhitelist = [..._recommendedPositiveWhitelist];
            _positiveBlacklist = [..._recommendedPositiveBlacklist];
            _renderPositiveChips('whitelist');
            _renderPositiveChips('blacklist');
            showToast('추천 태그를 적용했습니다. 저장 버튼을 눌러 반영하세요.', 'success');
        }

        function _renderPositiveChips(type) {
            const container = document.getElementById(`pr-${type}-chips`);
            if (!container) return;
            const rules = type === 'whitelist' ? _positiveWhitelist : _positiveBlacklist;
            const bg = type === 'whitelist' ? 'rgba(76,175,80,0.12)' : 'rgba(220,50,50,0.10)';
            const border = type === 'whitelist' ? 'rgba(76,175,80,0.35)' : 'rgba(220,50,50,0.25)';
            const text = type === 'whitelist' ? 'rgba(76,175,80,0.95)' : 'rgba(220,50,50,0.9)';

            if (rules.length === 0) {
                container.innerHTML = `<span style="font-size:0.75rem; color:var(--text2);">${type === 'whitelist' ? '없음 (모든 태그 포함)' : '없음'}</span>`;
                return;
            }
            container.innerHTML = rules.map((rule, i) =>
                `<span style="display:inline-flex; align-items:center; gap:3px; background:${bg}; border:1px solid ${border}; border-radius:4px; padding:3px 8px; font-size:0.8rem; color:${text};">${escHtml(rule)}<span style="cursor:pointer; font-weight:bold; margin-left:2px; opacity:0.7;" onclick="removePositiveRule('${type}', ${i})">&times;</span></span>`
            ).join('');
        }

        async function addPositiveRule(type) {
            const input = document.getElementById(`pr-${type}-input`);
            if (!input || !input.value.trim()) return;
            const rule = input.value.trim();
            const rules = type === 'whitelist' ? _positiveWhitelist : _positiveBlacklist;
            if (rules.includes(rule)) {
                showToast('이미 존재하는 규칙입니다', 'error');
                return;
            }
            if (type === 'whitelist') {
                _positiveWhitelist = [..._positiveWhitelist, rule];
            } else {
                _positiveBlacklist = [..._positiveBlacklist, rule];
            }
            _renderPositiveChips(type);
            input.value = '';
            input.focus();
        }

        function removePositiveRule(type, index) {
            if (type === 'whitelist') {
                _positiveWhitelist = _positiveWhitelist.filter((_, i) => i !== index);
            } else {
                _positiveBlacklist = _positiveBlacklist.filter((_, i) => i !== index);
            }
            _renderPositiveChips(type);
        }

        async function savePositiveRulesFromModal() {
            try {
                const res = await fetchJSON('/api/bot_mode/positive_rules', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        positive_whitelist: _positiveWhitelist,
                        positive_blacklist: _positiveBlacklist,
                    }),
                });
                if (res && res.success) {
                    _positiveWhitelist = res.positive_whitelist || [];
                    _positiveBlacklist = res.positive_blacklist || [];
                    _updatePositiveRulesCount();
                    showToast('POSITIVE 태그 규칙 저장 완료', 'success');
                    document.getElementById('positive-rules-modal').remove();
                } else {
                    showToast(res.error || '저장 실패', 'error');
                }
            } catch (e) {
                console.error('[POSITIVE_RULES] 저장 실패:', e);
                showToast('POSITIVE 태그 규칙 저장 실패', 'error');
            }
        }

        let _illustPresetsCache = null;

        async function loadIllustArtistPresets() {
            try {
                const tagsData = await fetchJSON('/api/asset_mode/tags');
                if (!tagsData) return;
                _illustPresetsCache = tagsData;

                // 아티스트 프리셋
                const artistPresets = tagsData.artist_presets || {};
                const artistNames = Object.keys(artistPresets);
                fillPresetSelect('illust-anima-artist-preset', artistNames, '아티스트');
                fillPresetSelect('illust-sdxl-artist-preset', artistNames, '아티스트');

                // 품질 프리셋
                const qualityPresets = tagsData.quality_presets || {};
                const qualityNames = Object.keys(qualityPresets);
                fillPresetSelect('illust-anima-quality-preset', qualityNames, '품질');
                fillPresetSelect('illust-sdxl-quality-preset', qualityNames, '품질');

                // 부정 프리셋
                const negativePresets = tagsData.negative_presets || {};
                const negativeNames = Object.keys(negativePresets);
                fillPresetSelect('illust-anima-negative-preset', negativeNames, '부정');
                fillPresetSelect('illust-sdxl-negative-preset', negativeNames, '부정');

                // 설정 로드 (선택값 복원)
                await loadIllustSettings();

                // 태그 박스 렌더
                renderIllustPresetTags('illust-sdxl-artist-preset','illust-sdxl-artist-tags','artist_presets');
                renderIllustPresetTags('illust-sdxl-quality-preset','illust-sdxl-quality-tags','quality_presets');
                renderIllustPresetTags('illust-anima-artist-preset','illust-anima-artist-tags','artist_presets');
                renderIllustPresetTags('illust-anima-quality-preset','illust-anima-quality-tags','quality_presets');
                renderIllustPresetTags('illust-sdxl-negative-preset','illust-sdxl-negative-tags','negative_presets');
                renderIllustPresetTags('illust-anima-negative-preset','illust-anima-negative-tags','negative_presets');
            } catch (e) {
                console.error('[ILLUST] 프리셋 로드 실패:', e);
            }
        }

        function renderIllustPresetTags(selectId, containerId, presetType) {
            const select = document.getElementById(selectId);
            const container = document.getElementById(containerId);
            if (!select || !container) return;
            container.innerHTML = '';
            const name = select.value;
            if (!name || !_illustPresetsCache) return;
            const presets = _illustPresetsCache[presetType] || {};
            const tags = presets[name];
            if (!tags || !tags.length) return;
            tags.forEach(tag => {
                const span = document.createElement('span');
                span.textContent = tag;
                span.style.cssText = 'display:inline-block; padding:2px 6px; border-radius:3px; font-size:0.7rem; background:var(--surface2); border:1px solid var(--border); color:var(--text);';
                _attachTagChipTooltip(span, tag);
                container.appendChild(span);
            });
        }

        // ─── 삽화 통합 태그 편집 모달 ─────────────────────────
        const ILLUST_TAG_EDITOR_SECTIONS = [
            { id: 'sdxl-artist',  label: 'ILXL 아티스트', selectId: 'illust-sdxl-artist-preset',  presetType: 'artist_presets' },
            { id: 'sdxl-quality', label: 'ILXL 품질',     selectId: 'illust-sdxl-quality-preset', presetType: 'quality_presets' },
            { id: 'anima-artist', label: 'ANIMA 아티스트', selectId: 'illust-anima-artist-preset', presetType: 'artist_presets' },
            { id: 'anima-quality',label: 'ANIMA 품질',    selectId: 'illust-anima-quality-preset',presetType: 'quality_presets' },
            { id: 'sdxl-negative',label: 'ILXL 부정',     selectId: 'illust-sdxl-negative-preset',presetType: 'negative_presets' },
            { id: 'anima-negative',label:'ANIMA 부정',     selectId: 'illust-anima-negative-preset',presetType:'negative_presets' },
        ];

        function openIllustTagEditorModal() {
            let modal = document.getElementById('illust-tag-editor-modal');
            if (modal) { modal.classList.toggle('visible'); _refreshIllustTagEditor(); return; }

            let sectionsHtml = '';
            const colors = ['#9C27B0','#4CAF50','#E91E63','#FF9800','#F44336','#795548'];
            ILLUST_TAG_EDITOR_SECTIONS.forEach((sec, i) => {
                sectionsHtml += `
                    <div style="background:rgba(${i%2===0?'156,39,176':'33,150,243'},0.06); border-radius:8px; padding:10px; margin-bottom:8px; border-left:3px solid ${colors[i]};">
                        <div style="font-size:0.8rem; font-weight:700; color:${colors[i]}; margin-bottom:6px;">
                            <span>${sec.label}</span>
                        </div>
                        <div style="display:flex; gap:4px; align-items:center; margin-bottom:6px;">
                            <select id="illust-te-select-${sec.id}" onchange="illustTeSelectPreset('${sec.id}')" style="flex:1; padding:3px 6px; border-radius:4px; border:1px solid var(--border); background:var(--surface2); color:var(--text); font-size:0.75rem;">
                                <option value="">-- 없음 --</option>
                            </select>
                            <button onclick="illustTeAddPreset('${sec.id}')" style="background:var(--accent); color:#fff; border:none; padding:2px 8px; border-radius:4px; cursor:pointer; font-size:0.7rem;">추가</button>
                            <button onclick="illustTeDuplicatePreset('${sec.id}')" style="background:var(--surface2); color:var(--text); border:1px solid var(--border); padding:2px 8px; border-radius:4px; cursor:pointer; font-size:0.7rem;">복제</button>
                            <button onclick="illustTeDeletePreset('${sec.id}')" style="background:var(--error); color:#fff; border:none; padding:2px 8px; border-radius:4px; cursor:pointer; font-size:0.7rem;">삭제</button>
                        </div>
                        <div id="illust-te-tags-${sec.id}" style="min-height:24px;"></div>
                        <div class="inline-add" style="margin-top:4px; position:relative;">
                            <input type="text" id="illust-te-input-${sec.id}" placeholder="태그 추가 (쉼표 구분, 괄호 묶음 유지)"
                                onkeydown="illustTeInputKeydown(event, '${sec.id}')">
                            <div class="tag-autocomplete-dropdown" id="ac-illust-te-${sec.id}"></div>
                            <button onclick="illustTeAddTag('${sec.id}')">+</button>
                        </div>
                    </div>`;
            });

            modal = document.createElement('div');
            modal.id = 'illust-tag-editor-modal';
            modal.className = 'modal';
            modal.innerHTML = `
                <div class="modal-content" style="max-width:700px;">
                    <div class="modal-header">
                        <h2>태그 편집</h2>
                        <button class="modal-close" onclick="document.getElementById('illust-tag-editor-modal').classList.remove('visible')">&times;</button>
                    </div>
                    <div class="modal-body" style="max-height:70vh; overflow-y:auto;">
                        <div style="font-size:0.75rem; color:var(--text2); margin-bottom:8px;">
                            현재 선택된 프리셋의 태그를 직접 편집합니다. 변경은 즉시 저장됩니다.
                        </div>
                        ${sectionsHtml}
                    </div>
                    <div class="modal-footer" style="display:flex; justify-content:flex-end;">
                        <button onclick="document.getElementById('illust-tag-editor-modal').classList.remove('visible')" style="background:var(--surface2); color:var(--text); border:1px solid var(--border); padding:6px 16px; border-radius:4px; cursor:pointer;">닫기</button>
                    </div>
                </div>`;
            document.body.appendChild(modal);
            // 각 섹션 입력필드에 자동완성 + 뜻(tooltip) 연결 (asset 모드 패턴과 동일)
            ILLUST_TAG_EDITOR_SECTIONS.forEach(sec => {
                TagAutocomplete.attach(`illust-te-input-${sec.id}`, `ac-illust-te-${sec.id}`, 'input');
            });
            modal.classList.add('visible');
            _refreshIllustTagEditor();
        }

        async function _refreshIllustTagEditor(prefetchedTagsData = null) {
            try {
                const tagsData = prefetchedTagsData || await fetchJSON('/api/asset_mode/tags');
                if (!tagsData) return;
                _illustPresetsCache = tagsData;
                ILLUST_TAG_EDITOR_SECTIONS.forEach(sec => {
                    const sidebarSelect = document.getElementById(sec.selectId);
                    const modalSelect = document.getElementById(`illust-te-select-${sec.id}`);
                    const tagsEl = document.getElementById(`illust-te-tags-${sec.id}`);
                    if (!tagsEl) return;
                    // 모달 드롭다운 채우기
                    if (modalSelect) {
                        const prevVal = modalSelect.value;
                        const presets = tagsData[sec.presetType] || {};
                        const names = Object.keys(presets);
                        modalSelect.innerHTML = '<option value="">-- 없음 --</option>';
                        names.forEach(n => { const o = document.createElement('option'); o.value = n; o.textContent = n; modalSelect.appendChild(o); });
                        // 사이드바 선택값과 동기화
                        const syncVal = sidebarSelect?.value || prevVal;
                        modalSelect.value = syncVal;
                    }
                    const name = modalSelect?.value || sidebarSelect?.value;
                    if (!name) { tagsEl.innerHTML = '<span style="font-size:0.7rem;color:var(--text-muted);">프리셋을 먼저 선택하세요</span>'; return; }
                    const presets = tagsData[sec.presetType] || {};
                    const tags = presets[name] || [];
                    _renderIllustTeChips(tagsEl, tags, sec.presetType, name);
                });
            } catch (e) { console.error('[ILLUST-TE] 새로고침 실패:', e); }
        }

        function _renderIllustTeChips(container, tags, presetType, presetName) {
            container.innerHTML = '';
            if (!tags.length) {
                container.innerHTML = '<span style="font-size:0.7rem;color:var(--text-muted);">태그 없음</span>';
                return;
            }
            const secId = ILLUST_TAG_EDITOR_SECTIONS.find(s => s.presetType === presetType && document.getElementById(s.selectId)?.value === presetName)?.id;
            const block = document.createElement('div');
            block.style.cssText = 'display:flex; flex-wrap:wrap; gap:4px; padding:8px; background:var(--surface); border:1px solid var(--border); border-radius:6px; min-height:28px;';
            tags.forEach((tag, idx) => {
                if (!tag) return;
                const chip = document.createElement('span');
                chip.className = 'tag-chip';
                chip.draggable = true;
                chip.dataset.idx = idx;
                chip.style.cssText = 'display:inline-flex; align-items:center; gap:4px; background:var(--surface2); border:1px solid var(--border); border-radius:4px; padding:2px 8px; font-size:0.75rem; color:var(--text); cursor:grab;';
                const label = document.createElement('span');
                label.textContent = tag;
                chip.appendChild(label);
                const x = document.createElement('span');
                x.style.cssText = 'cursor:pointer; color:var(--text-muted); margin-left:4px; font-size:0.85rem;';
                x.textContent = '×';
                x.addEventListener('click', () => illustTeRemoveTag(secId, idx));
                chip.appendChild(x);
                _attachTagChipTooltip(chip, tag);
                block.appendChild(chip);
            });
            container.appendChild(block);
            if (secId) _attachIllustTeDrag(block, tags, secId);
        }

        function _attachIllustTeDrag(container, tags, secId) {
            let dragIdx = null;
            container.querySelectorAll('.tag-chip[draggable]').forEach(chip => {
                chip.addEventListener('dragstart', (e) => {
                    dragIdx = parseInt(chip.dataset.idx);
                    chip.style.opacity = '0.4';
                    e.dataTransfer.effectAllowed = 'move';
                });
                chip.addEventListener('dragend', () => {
                    chip.style.opacity = '';
                    container.querySelectorAll('.tag-chip').forEach(c => c.style.outline = '');
                });
                chip.addEventListener('dragover', (e) => {
                    e.preventDefault();
                    e.dataTransfer.dropEffect = 'move';
                    chip.style.outline = '2px solid var(--accent)';
                });
                chip.addEventListener('dragleave', () => { chip.style.outline = ''; });
                chip.addEventListener('drop', async (e) => {
                    e.preventDefault();
                    chip.style.outline = '';
                    const dropIdx = parseInt(chip.dataset.idx);
                    if (dragIdx === null || dragIdx === dropIdx) return;
                    const order = tags.map((_, i) => i);
                    const [moved] = order.splice(dragIdx, 1);
                    order.splice(dropIdx, 0, moved);
                    const sec = ILLUST_TAG_EDITOR_SECTIONS.find(s => s.id === secId);
                    if (!sec) return;
                    try {
                        const resp = await fetch('/api/asset_mode/tags', {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({ action: 'reorder_preset_tags', preset_type: sec.presetType, preset_name: document.getElementById(sec.selectId)?.value, order })
                        });
                        const result = await resp.json();
                        if (result.success) await _refreshIllustTagEditor();
                        else showToast(result.error || '순서 변경 실패', 'error');
                    } catch (err) { showToast('요청 실패: ' + err.message, 'error'); }
                });
            });
        }

        // ─── 모달 프리셋 CRUD ─────────────────────────────────
        async function illustTeSelectPreset(secId) {
            const sec = ILLUST_TAG_EDITOR_SECTIONS.find(s => s.id === secId);
            if (!sec) return;
            const modalSelect = document.getElementById(`illust-te-select-${secId}`);
            const sidebarSelect = document.getElementById(sec.selectId);
            const val = modalSelect?.value || '';
            // 사이드바 동기화
            if (sidebarSelect) { sidebarSelect.value = val; saveIllustSettings(); renderIllustPresetTags(sec.selectId, sec.selectId.replace('-preset','-tags'), sec.presetType); }
            await _refreshIllustTagEditor();
        }

        async function illustTeAddPreset(secId) {
            const sec = ILLUST_TAG_EDITOR_SECTIONS.find(s => s.id === secId);
            if (!sec) return;
            const name = prompt('새 프리셋명');
            if (!name?.trim()) return;
            try {
                const resp = await fetch('/api/asset_mode/tags', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ action: `save_${sec.presetType.replace('_presets','')}_preset`, name: name.trim(), tags: [] })
                });
                const result = await resp.json();
                if (result.success) {
                    await loadIllustArtistPresets();
                    const modalSelect = document.getElementById(`illust-te-select-${secId}`);
                    const sidebarSelect = document.getElementById(sec.selectId);
                    if (sidebarSelect) sidebarSelect.value = name.trim();
                    if (modalSelect) modalSelect.value = name.trim();
                    saveIllustSettings();
                    await _refreshIllustTagEditor();
                } else { showToast(result.error || '추가 실패', 'error'); }
            } catch (e) { showToast('요청 실패: ' + e.message, 'error'); }
        }

        async function illustTeDuplicatePreset(secId) {
            const sec = ILLUST_TAG_EDITOR_SECTIONS.find(s => s.id === secId);
            if (!sec) return;
            const modalSelect = document.getElementById(`illust-te-select-${secId}`);
            const src = modalSelect?.value;
            if (!src) { showToast('복제할 프리셋을 선택하세요', 'error'); return; }
            const newName = prompt('새 프리셋명', src + ' 복사본');
            if (!newName?.trim()) return;
            try {
                const resp = await fetch('/api/asset_mode/tags', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ action: `duplicate_${sec.presetType.replace('_presets','')}_preset`, source: src, name: newName.trim() })
                });
                const result = await resp.json();
                if (result.success) {
                    await loadIllustArtistPresets();
                    const modalSelect2 = document.getElementById(`illust-te-select-${secId}`);
                    if (modalSelect2) modalSelect2.value = newName.trim();
                    await _refreshIllustTagEditor();
                } else { showToast(result.error || '복제 실패', 'error'); }
            } catch (e) { showToast('요청 실패: ' + e.message, 'error'); }
        }

        async function illustTeDeletePreset(secId) {
            const sec = ILLUST_TAG_EDITOR_SECTIONS.find(s => s.id === secId);
            if (!sec) return;
            const modalSelect = document.getElementById(`illust-te-select-${secId}`);
            const name = modalSelect?.value;
            if (!name) { showToast('삭제할 프리셋을 선택하세요', 'error'); return; }
            if (!confirm(`프리셋 "${name}" 삭제?`)) return;
            try {
                const resp = await fetch('/api/asset_mode/tags', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ action: `delete_${sec.presetType.replace('_presets','')}_preset`, name })
                });
                const result = await resp.json();
                if (result.success) {
                    await loadIllustArtistPresets();
                    await _refreshIllustTagEditor();
                } else { showToast(result.error || '삭제 실패', 'error'); }
            } catch (e) { showToast('요청 실패: ' + e.message, 'error'); }
        }

        function _illustTePresetName(secId) {
            const sec = ILLUST_TAG_EDITOR_SECTIONS.find(s => s.id === secId);
            if (!sec) return null;
            return document.getElementById(`illust-te-select-${secId}`)?.value || document.getElementById(sec.selectId)?.value || null;
        }

        // 입력필드 Enter 처리: 자동완성 드롭다운이 떠 있고 포커스된 항목이 있으면
        // 선택(TagAutocomplete가 value 채움)에 맡기고, 그 외에는 태그를 바로 추가한다.
        function illustTeInputKeydown(e, secId) {
            if (e.key !== 'Enter') return;
            const dd = document.getElementById(`ac-illust-te-${secId}`);
            if (dd && dd.classList.contains('visible') && dd.querySelector('.ac-item.focused')) return;
            e.preventDefault();
            illustTeAddTag(secId);
        }

        async function illustTeAddTag(secId) {
            const sec = ILLUST_TAG_EDITOR_SECTIONS.find(s => s.id === secId);
            if (!sec) return;
            const input = document.getElementById(`illust-te-input-${secId}`);
            if (!input?.value?.trim()) return;
            const presetName = _illustTePresetName(secId);
            if (!presetName) { showToast('프리셋을 먼저 선택하세요', 'error'); return; }
            const existingTags = _illustPresetsCache?.[sec.presetType]?.[presetName]
                || assetTags?.[sec.presetType]?.[presetName]
                || [];
            await addAssetTagInput({
                inputId: `illust-te-input-${secId}`,
                action: 'add_preset_tag',
                baseParams: { preset_type: sec.presetType, preset_name: presetName },
                existingTags,
                afterReload: async () => {
                    await _refreshIllustTagEditor(assetTags);
                    const sidebarContainerId = sec.selectId.replace('-preset', '-tags');
                    renderIllustPresetTags(sec.selectId, sidebarContainerId, sec.presetType);
                }
            });
        }

        async function illustTeRemoveTag(secId, idx) {
            const sec = ILLUST_TAG_EDITOR_SECTIONS.find(s => s.id === secId);
            if (!sec) return;
            const presetName = _illustTePresetName(secId);
            if (!presetName) return;
            try {
                const resp = await fetch('/api/asset_mode/tags', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ action: 'remove_preset_tag', preset_type: sec.presetType, preset_name: presetName, index: idx })
                });
                const result = await resp.json();
                if (result.success) {
                    await _refreshIllustTagEditor();
                    const sidebarContainerId = sec.selectId.replace('-preset', '-tags');
                    renderIllustPresetTags(sec.selectId, sidebarContainerId, sec.presetType);
                } else {
                    showToast(result.error || '삭제 실패', 'error');
                }
            } catch (err) { showToast('요청 실패: ' + err.message, 'error'); }
        }

        function fillPresetSelect(elementId, names, label) {
            const select = document.getElementById(elementId);
            if (!select) return;
            const currentValue = select.value;
            select.innerHTML = '<option value="">-- 없음 --</option>';
            for (const name of names) {
                const opt = document.createElement('option');
                opt.value = name;
                opt.textContent = name;
                select.appendChild(opt);
            }
            select.value = currentValue || '';
        }

