        async function switchIllustModalTab(tab) {
            const logs = document.getElementById('illust-tab-logs');
            const history = document.getElementById('illust-tab-history');
            const llm = document.getElementById('illust-tab-llm');
            const toggles = document.getElementById('illust-tab-toggles');
            const extra = document.getElementById('illust-tab-extra');
            const flow = document.getElementById('illust-tab-flow');
            const logsBody = document.getElementById('illust-tab-content-logs');
            const historyBody = document.getElementById('illust-tab-content-history');
            const llmBody = document.getElementById('illust-tab-content-llm');
            const togglesBody = document.getElementById('illust-tab-content-toggles');
            const extraBody = document.getElementById('illust-tab-content-extra');
            const flowBody = document.getElementById('illust-tab-content-flow');
            const logsFooter = document.getElementById('illust-log-footer-logs');
            const historyFooter = document.getElementById('illust-log-footer-history');
            const llmFooter = document.getElementById('illust-log-footer-llm');
            const togglesFooter = document.getElementById('illust-log-footer-toggles');
            const flowFooter = document.getElementById('illust-log-footer-flow');
            const requiredElements = [logs, history, llm, toggles, extra, flow, logsBody, historyBody, llmBody, togglesBody, extraBody, flowBody, logsFooter, historyFooter, llmFooter, togglesFooter, flowFooter];
            if (requiredElements.some(element => !element)) {
                console.error('[ILLUST_CONTEXT] 삽화 프롬프트 생성 탭 전환에 필요한 요소가 없습니다:', tab);
                return;
            }
            for (const [name, button] of [['logs', logs], ['history', history], ['llm', llm], ['toggles', toggles], ['extra', extra], ['flow', flow]]) {
                const active = name === tab;
                button.classList.toggle('is-active', active);
                button.setAttribute('aria-selected', String(active));
            }
            logsBody.style.display = tab === 'logs' ? '' : 'none';
            historyBody.style.display = tab === 'history' ? '' : 'none';
            llmBody.style.display = tab === 'llm' ? '' : 'none';
            togglesBody.hidden = tab !== 'toggles';
            extraBody.hidden = tab !== 'extra';
            flowBody.hidden = tab !== 'flow';
            logsFooter.style.display = tab === 'logs' ? 'flex' : 'none';
            historyFooter.style.display = tab === 'history' ? 'flex' : 'none';
            llmFooter.style.display = tab === 'llm' ? 'flex' : 'none';
            togglesFooter.hidden = tab !== 'toggles';
            flowFooter.hidden = tab !== 'flow';
            if (tab !== 'flow') pauseIllustrationPreview();
            if (tab === 'logs') await refreshIllustLogs();
            if (tab === 'history') await loadIllustrationChatHistories();
            if (tab === 'llm') await refreshIllustrationPromptInspector();
            if (tab === 'extra') await exportLbExtraTxt();
            if (tab === 'toggles' || tab === 'flow') {
                if (!togglesBody.childElementCount) await loadIllustrationContextToggles();
                else if (tab === 'flow') await renderIllustrationNodePreview();
            }
        }

        function switchIllustCallTab(tab) {
            const root = document.getElementById('illust-tab-content-llm');
            if (!root) {
                console.error('[ILLUST_CONTEXT] LLM 프롬프트 탭을 찾을 수 없습니다:', tab);
                return;
            }
            root.querySelectorAll('[data-illust-call-tab]').forEach(button => {
                const active = button.dataset.illustCallTab === tab;
                button.classList.toggle('is-active', active);
                button.setAttribute('aria-selected', String(active));
            });
            root.querySelectorAll('[data-illust-call-panel]').forEach(panel => {
                panel.hidden = panel.dataset.illustCallPanel !== tab;
            });
        }

        async function loadLighbdPrompts() {
            const statusEl = document.getElementById('lighbd-prompt-status');
            const fields = {
                genre: 'genre',
                call1_enhance: 'call1_enhance',
                time_place: 'time_place',
                manga_select: 'manga_select', manga_plan: 'manga_plan', manga_detail: 'manga_detail',
                character_resolve: 'character_resolve',
                profile_resolve: 'profile_resolve',
                call2_jailbreak: 'call2_jailbreak', call2_job: 'call2_job', call2_prefill: 'call2_prefill',
                call2_common: 'call2_common', call2_explicit: 'call2_explicit', call2_select: 'call2_select', call2_plan: 'call2_plan', call2_detail: 'call2_detail',
                call2_keyvis: 'call2_keyvis', call2_preset: 'preset',
                call3_speak: 'call3_speak', call3_manga: 'call3_manga', call3_manga_nsfw: 'call3_manga_nsfw',
                call3_subtitle: 'call3_subtitle', multi_char_mask: 'multi_char_mask',
                visual_correction: 'visual_correction', visual_selection: 'visual_selection',
            };
            statusEl.textContent = '불러오는 중...';
            try {
                const res = await fetch('/api/illustration_context/prompts');
                if (!res.ok) throw new Error('HTTP ' + res.status);
                const data = await res.json();
                for (const [k, id] of Object.entries(fields)) {
                    const el = document.getElementById('lighbd-prompt-' + id);
                    if (el) el.value = data[k] || '';
                }
                statusEl.textContent = '지침을 불러왔습니다. 편집한 지침은 저장 후 새 호출부터 적용됩니다.';
            } catch (e) {
                console.error('[ILLUST_CONTEXT] LLM 프롬프트 로드 실패:', e);
                statusEl.innerHTML = `<span style="color:#ff6b6b;">로드 실패: ${escapeHtml(e.message || String(e))}</span>`;
            }
        }

        async function saveLighbdPrompts() {
            const statusEl = document.getElementById('lighbd-prompt-status');
            const fields = {
                genre: 'genre',
                call1_enhance: 'call1_enhance',
                time_place: 'time_place',
                manga_select: 'manga_select', manga_plan: 'manga_plan', manga_detail: 'manga_detail',
                character_resolve: 'character_resolve',
                profile_resolve: 'profile_resolve',
                call2_jailbreak: 'call2_jailbreak', call2_job: 'call2_job', call2_prefill: 'call2_prefill',
                call2_common: 'call2_common', call2_explicit: 'call2_explicit', call2_select: 'call2_select', call2_plan: 'call2_plan', call2_detail: 'call2_detail',
                call2_keyvis: 'call2_keyvis', call2_preset: 'preset',
                call3_speak: 'call3_speak', call3_manga: 'call3_manga', call3_manga_nsfw: 'call3_manga_nsfw',
                call3_subtitle: 'call3_subtitle', multi_char_mask: 'multi_char_mask',
                visual_correction: 'visual_correction', visual_selection: 'visual_selection',
            };
            const body = {};
            for (const [k, id] of Object.entries(fields)) {
                const el = document.getElementById('lighbd-prompt-' + id);
                if (el) body[k] = el.value;
            }
            statusEl.textContent = '저장 중...';
            try {
                const res = await fetch('/api/illustration_context/prompts', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify(body),
                });
                if (!res.ok) {
                    const errBody = await res.json().catch(() => ({}));
                    throw new Error(errBody.error || ('HTTP ' + res.status));
                }
                const data = await res.json();
                statusEl.textContent = `지침 ${Array.isArray(data.saved) ? data.saved.length : 0}개 저장 완료 · 새 호출부터 적용됩니다.`;
                await refreshIllustrationPromptInspector();
                showToast('삽화 노드별 LLM 프롬프트 저장 완료', 'success');
            } catch (e) {
                console.error('[ILLUST_CONTEXT] LLM 프롬프트 저장 실패:', e);
                statusEl.innerHTML = `<span style="color:#ff6b6b;">저장 실패: ${escapeHtml(e.message || String(e))}</span>`;
                showToast('lighbd 프롬프트 저장 실패: ' + (e.message || String(e)), 'error');
            }
        }

        let _illustrationHistorySearchTimer = null;
        let _illustrationHistorySettingsLoaded = false;
        let _illustrationHistorySettings = {};

        function _formatIllustrationHistoryTime(value) {
            const numeric = Number(value || 0);
            if (!numeric) return '-';
            try {
                return new Date(numeric * 1000).toLocaleString();
            } catch (e) {
                console.error('[ILLUST_HISTORY] 날짜 표시 실패:', value, e);
                return '-';
            }
        }

