        function _illustrationHistoryJson(value) {
            try {
                return JSON.stringify(value ?? {}, null, 2);
            } catch (e) {
                console.error('[ILLUST_HISTORY] 상세 JSON 표시 실패:', e, value);
                return String(value ?? '');
            }
        }

        function _setIllustrationHistoryDetailText(id, value, jsonValue = false) {
            const element = document.getElementById(id);
            if (!element) {
                console.error('[ILLUST_HISTORY] 상세 표시 요소가 없습니다:', id);
                return;
            }
            const rendered = jsonValue ? _illustrationHistoryJson(value) : String(value ?? '');
            element.textContent = rendered || '(없음)';
        }

        function _renderIllustrationChatHistoryDetail(record, profileOptions = {}) {
            const meta = document.getElementById('illust-history-detail-meta');
            const messagesRoot = document.getElementById('illust-history-detail-messages');
            const content = document.getElementById('illust-history-detail-content');
            const status = document.getElementById('illust-history-detail-status');
            if (!meta || !messagesRoot || !content || !status) {
                console.error('[ILLUST_HISTORY] 상세 모달 내용 요소가 준비되지 않았습니다.');
                return;
            }
            const source = record?.source || {};
            const activeTurn = record?.active_turn || {};
            const pipelineResult = record?.last_pipeline || {};
            const metadata = [
                ['히스토리 ID', record?.history_id || '-'],
                ['봇', source.bot_name || '미지정'],
                ['저장 크기', `${Number(record?.stored_chars || 0).toLocaleString()}자`],
                ['메시지', `${Array.isArray(record?.messages) ? record.messages.length : 0}개`],
                ['리비전', Number(record?.revision || 0)],
                ['최근 갱신', _formatIllustrationHistoryTime(record?.updated_at)],
                ['최근 동작', activeTurn.operation || '-'],
                ['리롤', `${Number(activeTurn.reroll_index || 0)}회`],
                ['파이프라인', pipelineResult.status || '-'],
            ];
            meta.replaceChildren();
            for (const [label, value] of metadata) {
                const card = document.createElement('div');
                const labelNode = document.createElement('span');
                const valueNode = document.createElement('strong');
                labelNode.textContent = label;
                valueNode.textContent = String(value);
                card.append(labelNode, valueNode);
                meta.appendChild(card);
            }

            messagesRoot.replaceChildren();
            const messages = Array.isArray(record?.messages) ? record.messages : [];
            if (!messages.length) {
                const empty = document.createElement('div');
                empty.className = 'illust-history-detail-note';
                empty.style.margin = '0 10px 10px';
                empty.textContent = '저장된 원문 메시지가 없습니다.';
                messagesRoot.appendChild(empty);
            }
            messages.forEach((message, index) => {
                const article = document.createElement('article');
                const role = String(message?.role || 'user').toLowerCase();
                article.className = 'illust-history-message' + (role === 'char' ? ' is-char' : '');
                const head = document.createElement('div');
                head.className = 'illust-history-message-head';
                const trimmed = Number(message?.trimmed_prefix_chars || 0);
                head.textContent = `${index + 1}. ${role === 'char' ? 'CHAR' : 'USER'}`
                    + (trimmed ? ` · 앞 ${trimmed.toLocaleString()}자 잘림` : '')
                    + (message?.id ? ` · ${message.id}` : '');
                const body = document.createElement('pre');
                body.textContent = String(message?.content || '');
                article.append(head, body);
                messagesRoot.appendChild(article);
            });

            const participants = {...(record?.characters || {}), ...(activeTurn.state_before || {})};
            for (const [id, states] of [
                ['illust-history-detail-characters', record?.characters || {}],
                ['illust-history-detail-state-before', activeTurn.state_before || {}],
            ]) {
                const root = document.getElementById(id);
                root.replaceChildren();
                // Keep all metadata and untouched checkpoints exactly as loaded.
                root.dataset.states = JSON.stringify(states);
                if (!Object.keys(states).length) {
                    const empty = document.createElement('div');
                    empty.className = 'illust-history-detail-note';
                    empty.textContent = '저장된 프로필·복장·머리 상태가 없습니다. 생성 시 대화와 캐릭터 설정에서 판단합니다.';
                    root.appendChild(empty);
                }
                for (const [key, participant] of Object.entries(participants)) {
                    const tracked = states[key] || {};
                    const card = document.createElement('fieldset');
                    card.className = 'illust-history-state-character';
                    card.dataset.character = key;
                    const title = document.createElement('legend');
                    title.textContent = tracked.canonical_name || participant?.canonical_name || key;
                    card.dataset.canonicalName = title.textContent;
                    card.appendChild(title);
                    const registeredName = Object.keys(profileOptions).find(name => name.toLowerCase() === title.textContent.toLowerCase());
                    const choices = profileOptions[registeredName] || [];
                    if (choices.length || tracked.active_visual_profile_id) {
                        const profileFields = document.createElement('div');
                        profileFields.className = 'illust-history-state-fields';
                        for (const [field, label] of [['active_visual_profile_id', '적용 프로필 카드'], ['active_visual_profile_state', '프로필 상태·판단 근거 (선택)']]) {
                            const labelNode = document.createElement('label');
                            labelNode.textContent = label;
                            const isProfile = field === 'active_visual_profile_id';
                            const input = document.createElement(isProfile ? 'select' : 'textarea');
                            input.dataset.profileField = field;
                            input.dataset.initialValue = String(tracked[field] || '');
                            if (isProfile) {
                                const options = [{id: '', label: '대화와 설정으로 판단'}, ...choices];
                                if (tracked[field] && !choices.some(option => option.id === tracked[field])) {
                                    options.push({id: tracked[field], label: '저장된 카드 · 현재 등록 목록에 없음'});
                                }
                                for (const option of options) {
                                    const node = document.createElement('option');
                                    node.value = option.id;
                                    node.textContent = option.id
                                        ? option.id + (option.label && option.label !== option.id ? ` · ${option.label}` : '')
                                        : option.label;
                                    input.appendChild(node);
                                }
                            }
                            input.value = input.dataset.initialValue;
                            input.rows = 3;
                            input.spellcheck = false;
                            input.setAttribute('aria-label', `${title.textContent} · ${label}`);
                            labelNode.appendChild(input);
                            if (isProfile) {
                                const picker = document.createElement('div');
                                picker.className = 'illust-history-profile-picker';
                                const thumbnail = document.createElement('button');
                                thumbnail.type = 'button';
                                thumbnail.className = 'illust-history-profile-thumb';
                                input.onchange = () => {
                                    const selected = choices.find(option => option.id === input.value);
                                    const filename = String(selected?.rep_image || '').trim();
                                    const empty = document.createElement('span');
                                    empty.textContent = input.value ? '대표 이미지 없음' : '카드 선택';
                                    thumbnail.replaceChildren(empty);
                                    thumbnail.disabled = true;
                                    thumbnail.onclick = null;
                                    thumbnail.title = empty.textContent;
                                    if (!filename || !source.bot_name) return;
                                    const image = document.createElement('img');
                                    const src = `/api/bot_mode/image/${encodeURIComponent(source.bot_name)}/${encodeURIComponent(registeredName)}/${encodeURIComponent(filename)}`;
                                    image.alt = `${title.textContent} · ${selected.label || selected.id} 대표 이미지`;
                                    image.loading = 'lazy';
                                    image.onerror = () => {
                                        if (thumbnail.firstChild !== image) return;
                                        console.error('[ILLUST_HISTORY] 프로필 대표 이미지 로드 실패:', {bot: source.bot_name, character: registeredName, profile: selected.id, filename});
                                        empty.textContent = '이미지 로드 실패';
                                        thumbnail.replaceChildren(empty);
                                        thumbnail.disabled = true;
                                        thumbnail.onclick = null;
                                        thumbnail.title = empty.textContent;
                                    };
                                    thumbnail.replaceChildren(image);
                                    thumbnail.disabled = false;
                                    thumbnail.title = `${image.alt} 확대`;
                                    thumbnail.onclick = () => openLightbox(src);
                                    image.src = src;
                                };
                                input.onchange();
                                picker.append(thumbnail, labelNode);
                                profileFields.appendChild(picker);
                            } else {
                                profileFields.appendChild(labelNode);
                            }
                        }
                        card.appendChild(profileFields);
                    }
                    const chain = Array.isArray(tracked?.call1_status_history) && tracked.call1_status_history.length
                        ? tracked.call1_status_history
                        : typeof tracked?.call1_status === 'string' ? [tracked.call1_status] : [];
                    const fields = document.createElement('div');
                    fields.className = 'illust-history-state-fields';
                    card.appendChild(fields);
                    if (!chain.length) {
                        fields.textContent = '저장된 복장·머리 상태가 없습니다.';
                    }
                    const past = document.createElement('details');
                    past.className = 'illust-history-state-past';
                    const summary = document.createElement('summary');
                    summary.textContent = `이전 변경 기록 ${Math.max(0, chain.length - 1)}개 · 읽기 전용`;
                    past.appendChild(summary);
                    chain.forEach((raw, index) => {
                        let parsed;
                        try {
                            parsed = JSON.parse(raw);
                        } catch (error) {
                            console.warn('[ILLUST_HISTORY] 복장·머리 필드로 읽을 수 없어 원문 표시:', {id, key, index, raw, error});
                        }
                        const tags = parsed && typeof parsed === 'object' && !Array.isArray(parsed)
                            && ['outfit', 'hair'].some(field => typeof parsed[field] === 'string')
                            && ['outfit', 'hair'].every(field => parsed[field] === undefined || typeof parsed[field] === 'string');
                        const values = tags
                            ? [['outfit', '복장', parsed.outfit ?? ''], ['hair', '머리', parsed.hair ?? '']]
                            : [['raw', '저장된 상태 원문', typeof raw === 'string' ? raw : _illustrationHistoryJson(raw)]];
                        const latest = index === chain.length - 1;
                        const entry = document.createElement('dl');
                        if (!latest) {
                            const heading = document.createElement('dt');
                            heading.textContent = `이전 상태 ${index + 1}`;
                            entry.append(heading, document.createElement('dd'));
                        }
                        for (const [field, label, text] of values) {
                            if (latest) {
                                const labelNode = document.createElement('label');
                                labelNode.textContent = label;
                                const input = document.createElement('textarea');
                                input.dataset.field = field;
                                input.defaultValue = text;
                                input.rows = field === 'outfit' ? 4 : 3;
                                input.spellcheck = false;
                                input.setAttribute('aria-label', `${title.textContent} · ${label}`);
                                labelNode.appendChild(input);
                                fields.appendChild(labelNode);
                            } else {
                                const term = document.createElement('dt');
                                const description = document.createElement('dd');
                                term.textContent = label;
                                description.textContent = text || '(비어 있음)';
                                entry.append(term, description);
                            }
                        }
                        if (!latest) past.appendChild(entry);
                    });
                    if (chain.length > 1) card.appendChild(past);
                    const profileHistory = Array.isArray(tracked?.visual_base_timeline) ? tracked.visual_base_timeline : [];
                    if (profileHistory.length) {
                        const details = document.createElement('details');
                        details.className = 'illust-history-state-past';
                        const summary = document.createElement('summary');
                        summary.textContent = `프로필 변경 기록 ${profileHistory.length}개 · 읽기 전용`;
                        details.appendChild(summary);
                        for (const event of profileHistory) {
                            const entry = document.createElement('dl');
                            for (const [label, text] of [
                                ['시점', [event.message_id, event.anchor_segment || event.segment_id].filter(Boolean).join(' · ')],
                                ['적용 카드 ID', event.target_visual_profile_id || event.visual_profile_name],
                                ['판단 근거', event.visual_change || (typeof event.initial_state === 'string' ? event.initial_state : '')
                                    || (Array.isArray(event.evidence) ? event.evidence.join('\n') : event.evidence)],
                            ]) {
                                const term = document.createElement('dt'), description = document.createElement('dd');
                                term.textContent = label;
                                description.textContent = text || '(정보 없음)';
                                entry.append(term, description);
                            }
                            details.appendChild(entry);
                        }
                        card.appendChild(details);
                    }
                    root.appendChild(card);
                }
            }
            _setIllustrationHistoryDetailText('illust-history-detail-active-turn', activeTurn, true);
            _setIllustrationHistoryDetailText('illust-history-detail-call1', pipelineResult.call1_result || {}, true);
            _setIllustrationHistoryDetailText('illust-history-detail-time-place', pipelineResult.time_place_result || {}, true);
            _setIllustrationHistoryDetailText('illust-history-detail-profile', pipelineResult.profile_result || {}, true);
            const profileTable = document.getElementById('illust-history-detail-profile-table');
            profileTable.replaceChildren();
            if (pipelineResult.profile_result?.state_table && typeof window !== 'undefined' && window.appendIllustrationTrackedStateTable) {
                window.appendIllustrationTrackedStateTable({profile_state_table: pipelineResult.profile_result.state_table}, profileTable);
            }
            _setIllustrationHistoryDetailText('illust-history-detail-call2', pipelineResult.call2_out || '');
            _setIllustrationHistoryDetailText('illust-history-detail-call3-final', pipelineResult.call3_out || '');
            _setIllustrationHistoryDetailText('illust-history-detail-wardrobe', {
                wardrobe_events: pipelineResult.wardrobe_events || [],
                last_visual_by_character: pipelineResult.last_visual_by_character || {},
            }, true);
            _setIllustrationHistoryDetailText('illust-history-detail-rerolls', record?.reroll_archive || [], true);
            _setIllustrationHistoryDetailText(
                'illust-history-detail-call3-note',
                pipelineResult.call3_out
                    ? (pipelineResult.call3_correction_used
                        ? 'POST PROCESS: 최초 생성 1회 + 슬롯 완전성 교정 1회'
                        : 'POST PROCESS: 최초 생성 1회 · 교정 호출 없음')
                    : 'POST PROCESS 출력 없음',
            );
            _setIllustrationHistoryDetailText('illust-history-detail-subtitle', record?.title || '');
            status.style.display = 'none';
            content.style.display = '';
        }

        async function openIllustrationChatHistory(historyId, saveState = false) {
            if (!historyId) {
                console.error('[ILLUST_HISTORY] 열람할 historyId가 비어 있습니다.');
                return;
            }
            const modal = _ensureIllustrationChatHistoryDetailModal();
            const status = document.getElementById('illust-history-detail-status');
            const content = document.getElementById('illust-history-detail-content');
            const saveButton = document.getElementById('illust-history-state-save');
            modal.dataset.historyId = historyId;
            modal.classList.add('visible');
            if (!saveState) {
                modal.querySelectorAll('details').forEach(section => { section.open = false; });
                const body = modal.querySelector('.modal-body');
                if (body) body.scrollTop = 0;
            }
            if (status) {
                status.style.display = '';
                status.textContent = saveState ? '캐릭터 상태를 저장하는 중...' : '히스토리 상세 내용을 불러오는 중...';
            }
            if (content && !saveState) content.style.display = 'none';
            if (saveButton) saveButton.disabled = true;
            try {
                let options;
                if (saveState) {
                    const body = {};
                    for (const [id, field] of [
                        ['illust-history-detail-characters', 'characters'],
                        ['illust-history-detail-state-before', 'state_before'],
                    ]) {
                        const root = document.getElementById(id);
                        const states = JSON.parse(root.dataset.states);
                        for (const card of root.querySelectorAll('[data-character]')) {
                            const profileInputs = [...card.querySelectorAll('[data-profile-field]')];
                            const changedInputs = profileInputs.filter(input => input.value !== input.dataset.initialValue);
                            const inputs = [...card.querySelectorAll('textarea[data-field]')];
                            if (!changedInputs.length && !inputs.some(input => input.value !== input.defaultValue)) continue;
                            const tracked = states[card.dataset.character] ||= {canonical_name: card.dataset.canonicalName};
                            const changedProfile = changedInputs.find(input => input.dataset.profileField === 'active_visual_profile_id');
                            if (changedProfile) tracked.active_visual_profile_state = '';
                            for (const input of changedInputs) {
                                tracked[input.dataset.profileField] = input.value;
                            }
                            if (!inputs.some(input => input.value !== input.defaultValue)) continue;
                            const chain = tracked.call1_status_history;
                            const hasHistory = Array.isArray(chain) && chain.length > 0;
                            const previous = hasHistory ? chain[chain.length - 1] : tracked.call1_status;
                            const rawInput = inputs.find(input => input.dataset.field === 'raw');
                            let updated;
                            if (rawInput) {
                                updated = rawInput.value;
                            } else {
                                const tags = JSON.parse(previous);
                                for (const input of inputs) {
                                    if (input.value !== input.defaultValue) tags[input.dataset.field] = input.value;
                                }
                                updated = JSON.stringify(tags);
                            }
                            if (hasHistory) chain[chain.length - 1] = updated;
                            tracked.call1_status = updated;
                        }
                        body[field] = states;
                    }
                    options = {
                        method: 'POST', headers: {'Content-Type': 'application/json'},
                        body: JSON.stringify(body),
                    };
                }
                const response = await fetch('/api/illustration_context/chat-histories/' + encodeURIComponent(historyId), options);
                const data = await response.json();
                if (!response.ok) throw new Error(data.error || ('HTTP ' + response.status));
                if (modal.dataset.historyId !== historyId) return;
                _renderIllustrationChatHistoryDetail(data.history || {}, data.profile_options || {});
                if (saveState) {
                    showToast('캐릭터 프로필·복장·헤어 상태를 저장했습니다.', 'success');
                    await loadIllustrationChatHistories();
                }
            } catch (e) {
                console.error('[ILLUST_HISTORY] 상세 조회/상태 저장 실패:', {historyId, saveState, error: e});
                if (modal.dataset.historyId === historyId) {
                    if (status) status.textContent = (saveState ? '상태 저장 실패: ' : '상세 로드 실패: ') + (e.message || e);
                    if (saveState) showToast('상태 저장 실패: ' + (e.message || e), 'error');
                }
            } finally {
                if (saveButton && modal.dataset.historyId === historyId) saveButton.disabled = false;
            }
        }

        function renderIllustrationChatHistories(records) {
            const list = document.getElementById('illust-history-list');
            if (!list) {
                console.error('[ILLUST_HISTORY] 목록 표시 요소가 없습니다.');
                return;
            }
            if (!Array.isArray(records) || records.length === 0) {
                list.innerHTML = '<div class="illust-history-empty">저장된 채팅 히스토리가 없습니다.</div>';
                return;
            }
            list.innerHTML = records.map(item => {
                const title = item.title || '(제목 없는 히스토리)';
                const operationLabels = {
                    new: '신규', append: '연속 갱신', reroll: '리롤 교체', duplicate: '중복 재실행',
                };
                const operation = operationLabels[item.last_operation] || item.last_operation || '-';
                return `
                    <article class="illust-history-card">
                        <div style="min-width:0;">
                            <div class="illust-history-title" title="${escapeHtml(title)}">${escapeHtml(title)}</div>
                            <div class="illust-history-meta">
                                ${escapeHtml(item.bot_name || '봇 미지정')} · ${Number(item.stored_chars || 0).toLocaleString()}자 · 메시지 ${Number(item.message_count || 0)}개 · 캐릭터 ${Number(item.character_count || 0)}명<br>
                                ${escapeHtml(operation)} · 리롤 ${Number(item.reroll_index || 0)}회 · ${escapeHtml(item.pipeline_status || '-')} · ${escapeHtml(_formatIllustrationHistoryTime(item.updated_at))}<br>
                                <code>${escapeHtml(item.history_id || '')}</code>
                            </div>
                        </div>
                        <div style="display:flex; gap:6px; align-items:center;">
                            <button class="illust-settings-action is-secondary" type="button" onclick="openIllustrationChatHistory('${escapeHtml(item.history_id || '')}')">보기</button>
                            <button class="illust-settings-action" type="button" style="color:var(--danger, #e45858);" onclick="deleteIllustrationChatHistory('${escapeHtml(item.history_id || '')}')">삭제</button>
                        </div>
                    </article>`;
            }).join('');
        }

        function _applyIllustrationHistorySettings(settings) {
            _illustrationHistorySettings = {...settings};
            const map = {
                'illust-history-storage-max': 'storage_max_chars',
                'illust-history-call1': 'call1_history_chars',
                'illust-history-call3': 'call3_fallback_history_chars',
            };
            for (const [id, key] of Object.entries(map)) {
                const input = document.getElementById(id);
                if (!input) {
                    console.error('[ILLUST_HISTORY] 설정 입력 요소가 없습니다:', id);
                    continue;
                }
                input.value = Number(settings?.[key] ?? 0);
            }
            _illustrationHistorySettingsLoaded = true;
        }

        async function loadIllustrationChatHistories() {
            const status = document.getElementById('illust-history-status');
            const search = document.getElementById('illust-history-search');
            if (!status || !search) {
                console.error('[ILLUST_HISTORY] 검색 UI가 준비되지 않았습니다.');
                return;
            }
            status.textContent = '히스토리 검색 중...';
            status.classList.remove('is-error');
            try {
                const response = await fetch('/api/illustration_context/chat-histories?limit=200&query=' + encodeURIComponent(search.value || ''));
                const data = await response.json();
                if (!response.ok) throw new Error(data.error || ('HTTP ' + response.status));
                renderIllustrationChatHistories(data.histories || []);
                if (!_illustrationHistorySettingsLoaded) _applyIllustrationHistorySettings(data.settings || {});
                status.textContent = `${Number(data.count || 0)}개 히스토리 표시`;
            } catch (e) {
                console.error('[ILLUST_HISTORY] 목록 로드 실패:', e);
                status.textContent = '로드 실패: ' + (e.message || e);
                status.classList.add('is-error');
            }
        }

        function scheduleIllustrationHistorySearch() {
            if (_illustrationHistorySearchTimer) clearTimeout(_illustrationHistorySearchTimer);
            _illustrationHistorySearchTimer = setTimeout(() => {
                _illustrationHistorySearchTimer = null;
                loadIllustrationChatHistories();
            }, 300);
        }

        async function deleteIllustrationChatHistory(historyId) {
            if (!historyId) {
                console.error('[ILLUST_HISTORY] 삭제할 historyId가 비어 있습니다.');
                return;
            }
            if (!confirm('이 채팅 히스토리를 삭제할까요? 삭제본은 trash 폴더로 이동됩니다.')) return;
            try {
                const response = await fetch('/api/illustration_context/chat-histories/' + encodeURIComponent(historyId), {method: 'DELETE'});
                const data = await response.json();
                if (!response.ok) throw new Error(data.error || ('HTTP ' + response.status));
                const detailModal = document.getElementById('illust-history-detail-modal');
                if (detailModal?.dataset.historyId === historyId) {
                    closeIllustrationChatHistoryDetail();
                }
                showToast('채팅 히스토리를 휴지통으로 이동했습니다.', 'success');
                await loadIllustrationChatHistories();
            } catch (e) {
                console.error('[ILLUST_HISTORY] 삭제 실패:', e);
                showToast('채팅 히스토리 삭제 실패: ' + (e.message || e), 'error');
            }
        }

        async function saveIllustrationHistorySettings() {
            const storage = Number(document.getElementById('illust-history-storage-max')?.value || 0);
            const call1 = Number(document.getElementById('illust-history-call1')?.value || 0);
            const call3 = Number(document.getElementById('illust-history-call3')?.value || 0);
            if (!Number.isFinite(storage) || storage < 1000 || [call1, call3].some(value => !Number.isFinite(value) || value < 0)) {
                showToast('히스토리 글자수 설정을 확인해주세요.', 'error');
                return;
            }
            if ([call1, call3].some(value => value > storage)) {
                showToast('CALL별 히스토리 글자수는 저장 최대 글자수를 넘을 수 없습니다.', 'error');
                return;
            }
            const button = document.getElementById('illust-history-save');
            if (button) button.disabled = true;
            try {
                const response = await fetch('/api/illustration_context/chat-histories/settings', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({settings: {
                        ..._illustrationHistorySettings,
                        storage_max_chars: storage,
                        call1_history_chars: call1,
                        call3_fallback_history_chars: call3,
                    }}),
                });
                const data = await response.json();
                if (!response.ok) throw new Error(data.error || ('HTTP ' + response.status));
                _applyIllustrationHistorySettings(data.settings || {});
                showToast('채팅 히스토리 글자수 설정을 저장했습니다.', 'success');
                await loadIllustrationChatHistories();
            } catch (e) {
                console.error('[ILLUST_HISTORY] 설정 저장 실패:', e);
                showToast('히스토리 설정 저장 실패: ' + (e.message || e), 'error');
            } finally {
                if (button) button.disabled = false;
            }
        }

