        function renderAssetImportLV0() {
            window._botAssetNavLevel = 0;
            window._botAssetSelectedChar = '';
            window._botAssetSelectedOutfit = '';
            updateAssetImportBreadcrumb();

            const body = document.getElementById('bot-asset-import-body');
            const chars = (window._botAssetData || {}).characters || [];
            body.innerHTML = '';
            const grid = document.createElement('div');
            grid.style.cssText = 'display:grid; grid-template-columns:repeat(auto-fill, minmax(140px, 1fr)); gap:10px;';
            for (const c of chars) {
                const card = document.createElement('div');
                card.className = 'asset-folder-card';
                card.innerHTML = `<div class="folder-icon">👤</div><div class="folder-name">${escHtml(c)}</div>`;
                card.style.cursor = 'pointer';
                card.onclick = () => renderAssetImportLV1(c);
                grid.appendChild(card);
            }
            body.appendChild(grid);
        }

        async function renderAssetImportLV1(charName) {
            window._botAssetNavLevel = 1;
            window._botAssetSelectedChar = charName;
            window._botAssetSelectedOutfit = '';
            updateAssetImportBreadcrumb();

            const body = document.getElementById('bot-asset-import-body');
            body.innerHTML = '<div style="color:var(--text2); text-align:center; padding:20px;">불러오는 중...</div>';

            try {
                const resp = await fetch(`/api/bot_mode/asset_character_images?character=${encodeURIComponent(charName)}`);
                const data = await resp.json();
                window._botAssetCharData = data;
                body.innerHTML = '';

                const grid = document.createElement('div');
                grid.style.cssText = 'display:grid; grid-template-columns:repeat(auto-fill, minmax(140px, 1fr)); gap:10px;';

                if (data.outfits && data.outfits.length > 0) {
                    for (const outfit of data.outfits) {
                        const exprCount = (outfit.expressions || []).length;
                        const card = document.createElement('div');
                        card.className = 'asset-folder-card';
                        card.innerHTML = `<div class="folder-icon">👔</div><div class="folder-name">${escHtml(outfit.name)}</div><div style="font-size:0.75rem; color:var(--text2); margin-top:4px;">표정 ${exprCount}개</div>`;
                        card.style.cursor = 'pointer';
                        card.onclick = () => renderAssetImportLV2(charName, outfit.name);
                        grid.appendChild(card);
                    }
                }
                if (data.direct_images && data.direct_images.length > 0) {
                    const card = document.createElement('div');
                    card.className = 'asset-folder-card';
                    const count = data.direct_images.length;
                    card.innerHTML = `<div class="folder-icon">🖼️</div><div class="folder-name">직접 이미지</div><div style="font-size:0.75rem; color:var(--text2); margin-top:4px;">${count}장</div>`;
                    card.style.cursor = 'pointer';
                    card.onclick = () => renderAssetImportDirectImages(charName);
                    grid.appendChild(card);
                }
                if (grid.children.length === 0) {
                    body.innerHTML = '<div style="color:var(--text2); text-align:center; padding:20px;">의상/표정이 없습니다.</div>';
                    return;
                }
                body.appendChild(grid);
            } catch (e) {
                console.error('[BOT] 에셋 캐릭터 데이터 로드 실패:', e);
                body.innerHTML = '<div style="color:var(--error);">로드 실패</div>';
            }
        }

        function renderAssetImportLV2(charName, outfitName) {
            window._botAssetNavLevel = 2;
            window._botAssetSelectedOutfit = outfitName;
            updateAssetImportBreadcrumb();

            const body = document.getElementById('bot-asset-import-body');
            body.innerHTML = '';

            const data = window._botAssetCharData || {};
            const outfit = (data.outfits || []).find(o => o.name === outfitName);
            if (!outfit || !outfit.expressions || outfit.expressions.length === 0) {
                body.innerHTML = '<div style="color:var(--text2); text-align:center; padding:20px;">표정이 없습니다.</div>';
                return;
            }

            const grid = document.createElement('div');
            grid.style.cssText = 'display:grid; grid-template-columns:repeat(auto-fill, minmax(140px, 1fr)); gap:10px;';

            for (const expr of outfit.expressions) {
                const repImg = (expr.images || [])[0];
                const count = (expr.images || []).length;
                const card = document.createElement('div');
                card.className = 'asset-folder-card';
                if (repImg && repImg.url) {
                    card.innerHTML = `<img src="${repImg.url}" loading="lazy" style="width:100%; aspect-ratio:1; object-fit:cover; border-radius:6px;" onerror="this.parentElement.querySelector('.folder-icon').style.display='block'; this.style.display='none';">
                        <div style="display:none;" class="folder-icon">😀</div>
                        <div class="folder-name">${escHtml(expr.name)}</div>
                        <div style="font-size:0.75rem; color:var(--text2); margin-top:4px;">${count}장</div>`;
                } else {
                    card.innerHTML = `<div class="folder-icon">😀</div><div class="folder-name">${escHtml(expr.name)}</div><div style="font-size:0.75rem; color:var(--text2); margin-top:4px;">${count}장</div>`;
                }
                card.style.cursor = 'pointer';
                card.onclick = () => renderAssetImportExpressionImages(charName, outfitName, expr.name);
                grid.appendChild(card);
            }
            body.appendChild(grid);
        }

        function renderAssetImportExpressionImages(charName, outfitName, exprName) {
            window._botAssetNavLevel = 3;
            window._botAssetSelectedExpr = exprName;
            updateAssetImportBreadcrumb();

            const body = document.getElementById('bot-asset-import-body');
            body.innerHTML = '';

            const data = window._botAssetCharData || {};
            const outfit = (data.outfits || []).find(o => o.name === outfitName);
            const expr = (outfit?.expressions || []).find(e => e.name === exprName);
            if (!expr || !expr.images || expr.images.length === 0) {
                body.innerHTML = '<div style="color:var(--text2); text-align:center; padding:20px;">이미지가 없습니다.</div>';
                return;
            }

            const grid = document.createElement('div');
            grid.style.cssText = 'display:grid; grid-template-columns:repeat(auto-fill, minmax(120px, 1fr)); gap:8px;';

            for (const img of expr.images) {
                const card = document.createElement('div');
                card.style.cssText = 'position:relative; border-radius:6px; overflow:hidden; cursor:pointer; border:2px solid transparent; transition:border-color 0.2s;';
                card.innerHTML = `<img src="${img.url}" loading="lazy" style="width:100%; aspect-ratio:700/1024; object-fit:contain; background:var(--surface2); display:block;">
                    <div style="position:absolute; bottom:0; left:0; right:0; background:rgba(0,0,0,0.7); color:#fff; font-size:0.6rem; padding:2px 4px;">${escHtml(img.filename)}</div>`;
                card.onclick = () => {
                    if (window._botAssetSelected.has(img.path)) {
                        window._botAssetSelected.delete(img.path);
                        card.style.borderColor = 'transparent';
                    } else {
                        window._botAssetSelected.add(img.path);
                        card.style.borderColor = 'var(--accent)';
                    }
                    document.getElementById('bot-asset-import-confirm').textContent = `가져오기 (${window._botAssetSelected.size})`;
                };
                grid.appendChild(card);
            }
            body.appendChild(grid);
        }

        function renderAssetImportDirectImages(charName) {
            window._botAssetNavLevel = 2;
            window._botAssetSelectedOutfit = '(직접 이미지)';
            updateAssetImportBreadcrumb();

            const body = document.getElementById('bot-asset-import-body');
            body.innerHTML = '';

            const data = window._botAssetCharData || {};
            const images = data.direct_images || [];
            if (images.length === 0) {
                body.innerHTML = '<div style="color:var(--text2); text-align:center; padding:20px;">이미지가 없습니다.</div>';
                return;
            }

            body.innerHTML = '<div style="color:var(--text2); font-size:0.8rem; margin-bottom:8px;">경고: 직접 이미지는 미리보기를 지원하지 않습니다.</div>';
            const list = document.createElement('div');
            list.style.cssText = 'display:flex; flex-direction:column; gap:4px;';
            for (const img of images) {
                const row = document.createElement('div');
                row.style.cssText = 'padding:6px 10px; border:1px solid var(--border); border-radius:6px; cursor:pointer; font-size:0.8rem; transition:border-color 0.2s;' + (window._botAssetSelected.has(img.path) ? 'border-color:var(--accent);' : '');
                row.textContent = img.filename;
                row.onclick = () => {
                    if (window._botAssetSelected.has(img.path)) {
                        window._botAssetSelected.delete(img.path);
                        row.style.borderColor = 'var(--border)';
                    } else {
                        window._botAssetSelected.add(img.path);
                        row.style.borderColor = 'var(--accent)';
                    }
                    document.getElementById('bot-asset-import-confirm').textContent = `가져오기 (${window._botAssetSelected.size})`;
                };
                list.appendChild(row);
            }
            body.appendChild(list);
        }

        function updateAssetImportBreadcrumb() {
            const bc = document.getElementById('bot-asset-import-breadcrumb');
            if (!bc) return;
            let html = '<span style="cursor:pointer; color:var(--accent);" onclick="renderAssetImportLV0()">에셋</span>';
            if (window._botAssetNavLevel >= 1 && window._botAssetSelectedChar) {
                html += ` <span style="color:var(--text2);">›</span> `;
                html += `<span style="cursor:pointer; color:var(--accent);" onclick="renderAssetImportLV1('${escAttr(window._botAssetSelectedChar)}')">${escHtml(window._botAssetSelectedChar)}</span>`;
            }
            if (window._botAssetNavLevel >= 2 && window._botAssetSelectedOutfit) {
                html += ` <span style="color:var(--text2);">›</span> `;
                if (window._botAssetSelectedOutfit === '(직접 이미지)') {
                    html += `<span>직접 이미지</span>`;
                } else {
                    html += `<span style="cursor:pointer; color:var(--accent);" onclick="renderAssetImportLV2('${escAttr(window._botAssetSelectedChar)}','${escAttr(window._botAssetSelectedOutfit)}')">${escHtml(window._botAssetSelectedOutfit)}</span>`;
                }
            }
            if (window._botAssetNavLevel >= 3 && window._botAssetSelectedExpr) {
                html += ` <span style="color:var(--text2);">›</span> `;
                html += `<span>${escHtml(window._botAssetSelectedExpr)}</span>`;
            }
            bc.innerHTML = html;
        }

        async function confirmBotAssetImport() {
            const paths = Array.from(window._botAssetSelected || []);
            if (paths.length === 0) { alert('이미지를 선택하세요.'); return; }
            try {
                const resp = await fetch('/api/bot_mode/import_asset', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({bot: botCurrentBot, character: window._botAssetImportCharName, asset_paths: paths})
                });
                const data = await resp.json();
                if (data.error) { alert(data.error); return; }
                document.getElementById('bot-asset-import-modal').style.display = 'none';
                await loadBotCharDetailImages(window._botAssetImportCharName);
                showToast(`${data.count}개 이미지 가져옴`);
            } catch (e) {
                console.error('[BOT] 에셋 가져오기 실패:', e);
                alert('가져오기 실패');
            }
        }

        // ─── 유틸 ──────────────────────────────

        // ─── 유틸 ──────────────────────────────
        function escHtml(s) { const d = document.createElement('div'); d.textContent = s || ''; return d.innerHTML; }
        function escAttr(s) { return (s || '').replace(/"/g, '&quot;').replace(/'/g, '&#39;'); }

        // ─── 봇 사이드바 리사이즈 ──────────────────────
        (function() {
            const handle = document.getElementById('bot-sidebar-resize-handle');
            const sidebar = document.getElementById('bot-sidebar');
            if (!handle || !sidebar) return;
            let startX, startW;
            handle.addEventListener('mousedown', e => {
                e.preventDefault();
                startX = e.clientX;
                startW = sidebar.offsetWidth;
                document.addEventListener('mousemove', onMove);
                document.addEventListener('mouseup', onUp);
                handle.classList.add('active');
            });
            function onMove(e) {
                const w = Math.max(280, Math.min(800, startW + (startX - e.clientX)));
                sidebar.style.width = w + 'px';
            }
            function onUp() {
                document.removeEventListener('mousemove', onMove);
                document.removeEventListener('mouseup', onUp);
                handle.classList.remove('active');
            }
        })();

        async function loadAssetData() {
            const isFirstLoad = !assetTags;
            if (isFirstLoad) showAssetView('loading');
            try {
                const resp = await fetch('/api/asset_mode/tags');
                assetTags = await resp.json();
                if (typeof botRenderNegativePresetSelect === 'function') botRenderNegativePresetSelect();
                try {
                    const gResp = await fetch('/api/asset_mode/characters');
                    const gData = await gResp.json();
                    assetRepresentatives = gData.representatives || {};
                } catch (e) {
                    assetRepresentatives = {};
                }

                if (isFirstLoad) {
                    assetTags.quality = [];
                    assetTags.composition = [];
                    assetTags.negative = [];
                    assetTags.character_negative = [];
                    assetTags.anima_quality = [];
                    assetTags.anima_negative = [];
                }

                renderAssetUI();
                auRenderNegativePresetSelect();
                if (isFirstLoad) {
                    const h = { 'Content-Type': 'application/json' };
                    fetch('/api/asset_mode/tags', { method: 'POST', headers: h, body: JSON.stringify({ action: 'load_quality_preset', name: '' }) });
                    fetch('/api/asset_mode/tags', { method: 'POST', headers: h, body: JSON.stringify({ action: 'load_composition_preset', name: '' }) });
                    fetch('/api/asset_mode/tags', { method: 'POST', headers: h, body: JSON.stringify({ action: 'load_character_negative_preset', name: '' }) });
                    fetch('/api/asset_mode/tags', { method: 'POST', headers: h, body: JSON.stringify({ action: 'load_negative_preset', name: '' }) });
                    fetch('/api/asset_mode/tags', { method: 'POST', headers: h, body: JSON.stringify({ action: 'load_anima_quality_preset', name: '' }) });
                    fetch('/api/asset_mode/tags', { method: 'POST', headers: h, body: JSON.stringify({ action: 'load_anima_negative_preset', name: '' }) });
                }
            } catch (e) {
                console.error('[ASSET] 태그 로드 실패:', e);
            }
        }

        function renderAssetUI() {
            if (!assetTags) return;
            const sidebar = document.getElementById('asset-sidebar');
            const savedScroll = sidebar ? sidebar.scrollTop : 0;
            const charSelect = document.getElementById('asset-character-select');
            const currentChar = charSelect.value;
            charSelect.innerHTML = '<option value="">-- 캐릭터 선택 --</option>';
            for (const name of Object.keys(assetTags.characters || {}).sort()) {
                const opt = document.createElement('option');
                opt.value = name;
                opt.textContent = name;
                if (name === currentChar) opt.selected = true;
                charSelect.appendChild(opt);
            }

            // 전역 외모/복장/표정 custom-select 렌더
            const prevApp = getAssetSelectValue('asset-appearance-select');
            const prevOutfit = getAssetSelectValue('asset-outfit-select');
            const prevExpr = getAssetSelectValue('asset-expression-select');

            const appContainer = document.getElementById('asset-appearance-select-container');
            appContainer.innerHTML = buildAssetCustomSelect(assetTags.appearances || {}, prevApp, '-- 외모 선택 --', 'asset-appearance-select', 'onAssetAppearanceChange');

            const outfitContainer = document.getElementById('asset-outfit-select-container');
            outfitContainer.innerHTML = buildAssetCustomSelect(assetTags.outfits || {}, prevOutfit, '-- 복장 선택 --', 'asset-outfit-select', 'onAssetOutfitChange');

            const exprContainer = document.getElementById('asset-expression-select-container');
            exprContainer.innerHTML = buildAssetCustomSelect(assetTags.expressions || {}, prevExpr, '-- 표정 선택 --', 'asset-expression-select', 'onAssetExpressionChange');

            bindAssetCustomSelects();

            // 품질/구도/캐릭터 부정/부정 태그
            renderTagChips('asset-quality-tags', assetTags.quality || [], 'removeAssetQualityTag');
            renderTagChips('asset-composition-tags', assetTags.composition || [], 'removeAssetCompositionTag');
            renderTagChips('asset-character-negative-tags', assetTags.character_negative || [], 'removeAssetCharacterNegativeTag');
            renderTagChips('asset-negative-tags', assetTags.negative || [], 'removeAssetNegativeTag');

            // 모든 프리셋 custom-select 렌더
            const customSelectPresets = [
                ['quality_presets', 'asset-quality-preset-select', '-- 프리셋 --', 'loadQualityPreset'],
                ['composition_presets', 'asset-composition-preset-select', '-- 프리셋 --', 'loadCompositionPreset'],
                ['character_negative_presets', 'asset-character-negative-preset-select', '-- 프리셋 --', 'loadCharacterNegativePreset'],
                ['negative_presets', 'asset-negative-preset-select', '-- 프리셋 --', 'loadNegativePreset'],
                ['artist_presets', 'asset-artist-preset-select', '-- 프리셋 --', 'loadArtistPreset'],
                ['natural_language_presets', 'asset-natural-language-preset-select', '-- 프리셋 --', 'loadNaturalLanguagePreset'],
            ];
            customSelectPresets.forEach(([key, selectId, placeholder, onChangeFn]) => {
                const prev = getAssetSelectValue(selectId);
                const container = document.getElementById(selectId + '-container');
                if (!container) return;
                container.innerHTML = buildAssetCustomSelect(assetTags[key] || {}, prev, placeholder, selectId, onChangeFn);
            });
            bindAssetCustomSelects();


            onAssetCharacterChange(true);

            // 보존된 선택값이 유효하면 태그도 다시 렌더
            if (prevApp && assetTags.appearances?.[prevApp]) onAssetAppearanceChange();
            if (prevOutfit && assetTags.outfits?.[prevOutfit]) onAssetOutfitChange(true);
            if (prevExpr && assetTags.expressions?.[prevExpr]) onAssetExpressionChange(true);

            if (!prevApp || !assetTags.appearances?.[prevApp]) document.getElementById('asset-appearance-tags').innerHTML = '';
            if (!prevOutfit || !assetTags.outfits?.[prevOutfit]) document.getElementById('asset-outfit-tags').innerHTML = '';
            if (!prevExpr || !assetTags.expressions?.[prevExpr]) document.getElementById('asset-expression-tags').innerHTML = '';

            // 아티스트/자연어 프리셋 선택값이 있으면 태그도 다시 렌더
            const prevArtist = getAssetSelectValue('asset-artist-preset-select');
            if (prevArtist && assetTags.artist_presets?.[prevArtist]) loadArtistPreset();
            const prevNL = getAssetSelectValue('asset-natural-language-preset-select');
            if (prevNL && assetTags.natural_language_presets?.[prevNL] !== undefined) loadNaturalLanguagePreset();

            // ANIMA 아티스트 프리셋 custom-select 렌더
            const prevAnimaArtist = getAssetSelectValue('anima-artist-preset-select');
            const animaArtistContainer = document.getElementById('anima-artist-preset-select-container');
            if (animaArtistContainer) {
                animaArtistContainer.innerHTML = buildAssetCustomSelect(assetTags.artist_presets || {}, prevAnimaArtist, '-- ANIMA 아티스트 프리셋 --', 'anima-artist-preset-select', 'loadAnimaArtistPreset');
                bindAssetCustomSelects();
            }
            if (prevAnimaArtist && assetTags.artist_presets?.[prevAnimaArtist]) loadAnimaArtistPreset();

            // ANIMA 품질 프리셋 custom-select
            const prevAnimaQuality = getAssetSelectValue('anima-quality-preset-select');
            const animaQualityContainer = document.getElementById('anima-quality-preset-select-container');
            if (animaQualityContainer) {
                animaQualityContainer.innerHTML = buildAssetCustomSelect(assetTags.quality_presets || {}, prevAnimaQuality, '-- ANIMA 품질 프리셋 --', 'anima-quality-preset-select', 'loadAnimaQualityPreset');
                bindAssetCustomSelects();
            }
            if (prevAnimaQuality && assetTags.quality_presets?.[prevAnimaQuality]) loadAnimaQualityPreset();
            renderTagChips('anima-quality-tags', assetTags.anima_quality || [], 'removeAnimaQualityTag');

            // ANIMA 부정 프리셋 custom-select
            const prevAnimaNeg = getAssetSelectValue('anima-negative-preset-select');
            const animaNegContainer = document.getElementById('anima-negative-preset-select-container');
            if (animaNegContainer) {
                animaNegContainer.innerHTML = buildAssetCustomSelect(assetTags.negative_presets || {}, prevAnimaNeg, '-- ANIMA 부정 프리셋 --', 'anima-negative-preset-select', 'loadAnimaNegativePreset');
                bindAssetCustomSelects();
            }
            if (prevAnimaNeg && assetTags.negative_presets?.[prevAnimaNeg]) loadAnimaNegativePreset();
            renderTagChips('anima-negative-tags', assetTags.anima_negative || [], 'removeAnimaNegativeTag');

            // ANIMA UI 가시성 업데이트
            updateAnimaUIVisibility();

            // 메인 영역 갤러리 네비게이션 새로고침
            renderAssetMainArea();

            // 사이드바 스크롤 위치 복원
            if (sidebar) {
                sidebar.scrollTop = savedScroll;
            }
        }

        // 태그칩 호버 설명 캐시: tag명 → description (또는 null)
        const _tagDescCache = new Map();

        async function _lookupTagDescription(tagName) {
            const key = tagName.trim().toLowerCase().replace(/_/g, ' ').replace(/\s+/g, ' ');
            if (!key) return null;
            if (_tagDescCache.has(key)) return _tagDescCache.get(key);
            let desc = null;
            try {
                const resp = await fetch(`/api/autocomplete?query=${encodeURIComponent(key)}&limit=15`);
                if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
                const tags = await resp.json();
                if (Array.isArray(tags)) {
                    const exact = tags.find(t => (t.name || '').trim().toLowerCase().replace(/\s+/g, ' ') === key);
                    desc = (exact && exact.description && exact.description.trim()) ? exact.description.trim() : null;
                }
            } catch (e) {
                console.error('[TAG_DESC] 태그 설명 조회 실패:', { tagName, error: e });
            }
            _tagDescCache.set(key, desc);
            return desc;
        }

        // 칩 렌더 직후 태그 설명을 백그라운드로 미리 조회해 캐시를 채운다.
        // 첫 호버에서도 툴팁이 즉시 뜨도록 하기 위한 것으로,
        // _lookupTagDescription 이 캐시(null 포함)로 중복 조회를 막으므로
        // 렌더링마다 호출해도 네트워크 요청은 태그별 최초 1회만 발생한다.
        // 요청 폭주를 막으려 순차 체인으로 조회한다(캐시 히트는 즉시 스킵).
        function _prefetchTagDescriptions(tags) {
            const list = (Array.isArray(tags) ? tags : [tags]).filter(Boolean);
            if (!list.length) return;
            list.reduce((chain, tag) => chain.then(() => _lookupTagDescription(tag)), Promise.resolve());
        }

        // ──────────────────────────────────────────────────────────────────
        // 태그칩 설명 호버 툴팁(#ac-tooltip) 숨김 — 공용 헬퍼
        // ──────────────────────────────────────────────────────────────────
        // [버그 패턴] _attachTagChipTooltip 은 mouseenter 로 툴팁을 띄우고
        //   mouseleave 로 숨긴다. 그런데 칩이 innerHTML 재생성/parent.remove() 등으로
        //   DOM 에서 통째로 사라지면 브라우저가 mouseleave 를 발생시키지 않는다.
        //   결과적으로 "칩 위에 호버 → 그 칩 삭제" 시 설명 호버가 화면에 남는 버그 발생.
        //
        // [언제 호출하나] 칩을 파괴/재생성(re-render) 하는 삭제·초기화 경로에서
        //   다시 그리기 직전에 한 번 호출하면 잔류 툴팁이 즉시 사라진다.
        //   예) cmRemoveTag(), renderTagChips() 의 removeFn 경로 등.
        //
        // [재사용 안내] 같은 증상(태그/칩 제거 후 설명 호버가 안 사라짐)을
        //   다른 기능(에셋 모드·LB추가·포커스편집 등 _attachTagChipTooltip 사용처)에서
        //   발견하면, 해당 칩의 제거/재렌더 직전에 이 함수를 호출하면 된다.
        //   툴팁 요소는 페이지 전체에 1개(#ac-tooltip)이므로 부작용 없이 재사용 가능.
        function _hideTagChipTooltip() {
            const tooltip = document.getElementById('ac-tooltip');
            if (tooltip) tooltip.style.display = 'none';
        }

        function _attachTagChipTooltip(chip, tagName, preloadedDesc, gateFn, opts = {}) {
            if (!chip || !tagName) return;
            // 주의: mouseenter/mouseleave 기반이다. 칩이 DOM 에서 제거될 때는
            //   mouseleave 가 발생하지 않아 툴팁이 남을 수 있다.
            //   따라서 칩을 파괴/재생성하는 경로(삭제·재렌더)에서는
            //   반드시 _hideTagChipTooltip() 을 직접 호출해야 한다. (위 헬퍼 주석 참고)
            // 반응성: 브라우저 네이티브 title 툴팁(약 0.5~1초 지연)과 달리
            //   표시 지연을 짧게(기본 90ms) 잡아 즉각 뜨는 느낌을 유지하되,
            //   칩들을 빠르게 스칠 때마다 툴팁이 깜빡이는 건 방지한다.
            const showDelay = Number.isFinite(opts.delayMs) ? opts.delayMs : 90;
            let showTimer = null;
            chip.addEventListener('mouseenter', () => {
                // gateFn(예: "설명" 토글)이 닫혀 있으면 툴팁을 띄우지 않는다
                if (gateFn && !gateFn()) return;
                clearTimeout(showTimer);
                showTimer = setTimeout(async () => {
                    showTimer = null;
                    const tooltip = document.getElementById('ac-tooltip');
                    if (!tooltip) return;
                    // API(최신 형식, 소속 경로 포함)를 우선 조회하고, 실패 시 preloadedDesc로 폴백.
                    // 원본/편집본 칩 모두 동일한 설명 형식이 표시되도록 함.
                    const preloaded = (typeof preloadedDesc === 'string') ? preloadedDesc.trim() : '';
                    const desc = (await _lookupTagDescription(tagName)) || preloaded;
                    // 마우스가 이미 칩을 벗어났거나 칩이 재렌더로 사라졌을 수 있음 — 확인
                    if ((gateFn && !gateFn()) || !chip.isConnected || !chip.matches(':hover')) return;
                    if (!desc && !opts.showName) return;
                    // 툴팁 내용 구성: showName 이면 태그명 헤더 + 설명, 아니면 기존처럼 설명만.
                    // 칩 텍스트가 잘려 있을 때도 전체 태그명·뜻을 확인할 수 있게 한다.
                    tooltip.replaceChildren();
                    if (opts.showName) {
                        const nameEl = document.createElement('div');
                        nameEl.className = 'ac-tip-name';
                        nameEl.textContent = tagName;
                        tooltip.appendChild(nameEl);
                    }
                    if (desc) {
                        const descEl = document.createElement('div');
                        descEl.className = 'ac-tip-desc';
                        descEl.textContent = desc;
                        tooltip.appendChild(descEl);
                    }
                    tooltip.style.display = 'block';
                    // 위치: 칩 기준 아래쪽 우선, 화면 밖으로 나가면 좌우/위아래로 보정.
                    // (우측 편집 영역 칩이 화면 오른쪽 끝에 붙어 있어도 툴팁이 잘리지 않게.)
                    const rect = chip.getBoundingClientRect();
                    const tipWidth = tooltip.offsetWidth;
                    const tipHeight = tooltip.offsetHeight;
                    let left = Math.min(Math.max(8, rect.left), Math.max(8, window.innerWidth - tipWidth - 8));
                    let top = rect.bottom + 6;
                    if (top + tipHeight > window.innerHeight - 8) {
                        top = Math.max(8, rect.top - tipHeight - 6);
                    }
                    tooltip.style.left = left + 'px';
                    tooltip.style.top = top + 'px';
                }, showDelay);
            });
            chip.addEventListener('mouseleave', () => {
                clearTimeout(showTimer);
                showTimer = null;
                _hideTagChipTooltip();
            });
        }

        function renderTagChips(containerId, tags, removeFnName) {
            // 칩이 innerHTML 재생성으로 통째로 교체되면 mouseleave가 발생하지 않아
            // 호버 중이던 설명 툴팁(#ac-tooltip)이 화면에 남는다. 재렌더 직전에 숨긴다.
            _hideTagChipTooltip();
            const container = document.getElementById(containerId);
            container.innerHTML = '';
            tags.forEach((tag, idx) => {
                if (!tag) return;
                const chip = document.createElement('span');
                chip.className = 'tag-chip';
                chip.draggable = true;
                chip.dataset.idx = idx;
                chip.innerHTML = `${escapeHtml(tag)} <span class="remove-tag" onclick="${removeFnName}(${idx})">&times;</span>`;
                _attachTagChipTooltip(chip, tag);
                container.appendChild(chip);
            });
            attachDragReorder(container, tags, containerId, removeFnName);
        }

        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        function parseAssetTagInput(text, existingTags = []) {
            const seen = new Set(
                (Array.isArray(existingTags) ? existingTags : [])
                    .map(tag => String(tag || '').trim())
                    .filter(Boolean)
            );
            const parsed = splitTagsPreservingParens(
                String(text || '').replace(/\r?\n/g, ',')
            );
            return parsed.filter(tag => {
                const normalized = String(tag || '').trim();
                if (!normalized || seen.has(normalized)) return false;
                seen.add(normalized);
                return true;
            });
        }

        async function addAssetTagInput({
            inputId,
            action,
            baseParams = {},
            existingTags = [],
            afterReload = null,
        }) {
            const input = document.getElementById(inputId);
            if (!input) {
                console.error(`[ASSET] 태그 추가 실패: 입력 필드 없음 (${inputId})`);
                return false;
            }
            const rawValue = input.value;
            if (!rawValue.trim()) return false;

            const values = parseAssetTagInput(rawValue, existingTags);
            input.value = '';
            if (!values.length) {
                console.error(`[ASSET] 태그 추가 건너뜀: 새 태그 없음 (${inputId})`);
                showToast('추가할 새 태그가 없습니다', 'error');
                return false;
            }

            let addedCount = 0;
            let firstError = '';
            for (const value of values) {
                try {
                    const resp = await fetch('/api/asset_mode/tags', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ action, ...baseParams, value })
                    });
                    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
                    const result = await resp.json();
                    if (result.success) {
                        addedCount++;
                    } else {
                        const reason = result.error || '알 수 없는 오류';
                        console.error(`[ASSET] 태그 추가 실패: action=${action}, value=${value}, error=${reason}`);
                        if (!firstError) firstError = reason;
                    }
                } catch (e) {
                    console.error(`[ASSET] 태그 추가 요청 예외: action=${action}, value=${value}`, e);
                    if (!firstError) firstError = e.message;
                }
            }

            if (addedCount > 0) {
                try {
                    const dataResp = await fetch('/api/asset_mode/tags');
                    if (!dataResp.ok) throw new Error(`HTTP ${dataResp.status}`);
                    assetTags = await dataResp.json();
                    if (typeof botRenderNegativePresetSelect === 'function') botRenderNegativePresetSelect();
                    if (afterReload) await afterReload();
                } catch (e) {
                    console.error(`[ASSET] 태그 추가 후 데이터 갱신 실패: action=${action}`, e);
                    showToast('태그는 추가됐지만 화면 갱신에 실패했습니다', 'error');
                    return false;
                }
            }
            if (firstError) showToast(firstError, 'error');
            return addedCount > 0;
        }

        async function assetTagAction(action, params = {}) {
            try {
                const resp = await fetch('/api/asset_mode/tags', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ action, ...params })
                });
                const result = await resp.json();
                if (resp.ok && result.success) {
                    await loadAssetData();
                } else {
                    console.error('[ASSET] 태그 저장 실패:', action, params, resp.status, result);
                    showToast(result.error || '오류', 'error');
                }
                return result;
            } catch (e) {
                console.error('[ASSET] 태그 저장 요청 실패:', action, params, e);
                showToast('요청 실패: ' + e.message, 'error');
                return { success: false, error: e.message };
            }
        }

        async function addAssetCharacter() {
            const name = prompt('새 캐릭터명을 입력하세요');
            if (!name || !name.trim()) return;
            await assetTagAction('add_character', { name: name.trim() });
            // 새 캐릭터 선택 + 모든 셀렉트 초기화
            document.getElementById('asset-character-select').value = name.trim();
            setAssetSelectValue('asset-appearance-select', '');
            setAssetSelectValue('asset-outfit-select', '');
            setAssetSelectValue('asset-expression-select', '');
            onAssetAppearanceChange();
            onAssetOutfitChange();
            onAssetExpressionChange();
            updateGenerateBtn();
        }

        function removeAssetCharacter() {
            const name = document.getElementById('asset-character-select').value;
            if (!name) return;
            if (!confirm(`캐릭터 "${name}" 삭제?`)) return;
            assetTagAction('remove_character', { name });
        }

        async function duplicateAssetCharacter() {
            const source = document.getElementById('asset-character-select').value;
            if (!source) return;
            const newName = prompt(`복제할 새 캐릭터명을 입력하세요\n(원본: ${source})`);
            if (!newName || !newName.trim()) return;
            await assetTagAction('duplicate_character', { source, name: newName.trim() });
            document.getElementById('asset-character-select').value = newName.trim();
            onAssetCharacterChange();
        }

        function onAssetCharacterChange(preserveSelections = false) {
            const charName = document.getElementById('asset-character-select').value;

            // 외모/복장/표정 섹션은 항상 표시 (전역)
            if (!charName || !assetTags || !assetTags.characters[charName]) {
                updateAssetBreadcrumb();
                updateGenerateBtn();
                return;
            }

            updateAssetBreadcrumb();
            updateGenerateBtn();
            // 사이드바에서 캐릭터 변경 시 갤러리 레벨1로 이동 (초기 로드 제외)
            if (!preserveSelections && charName) {
                navigateToCharacterGallery(charName);
            }
        }

        // ─── 에셋 사이드바 custom-select 헬퍼 ───
        function buildAssetCustomSelect(dataObj, selectedValue, placeholder, selectId, onChangeFnName) {
            const sortedKeys = Object.keys(dataObj || {}).sort();
            const displayText = selectedValue || placeholder;
            let html = `<div class="custom-select" data-select-id="${selectId}" data-onchange="${onChangeFnName}">`;
            html += `<div class="custom-select-value">${escapeHtml(displayText)}</div>`;
            html += `<div class="custom-select-options">`;
            html += `<input class="custom-select-search" placeholder="검색..." autocomplete="off" />`;
            html += `<div class="custom-select-option-list">`;
            html += `<div class="custom-select-option placeholder-opt${!selectedValue ? ' selected' : ''}" data-value="">${escapeHtml(placeholder)}</div>`;
            for (const name of sortedKeys) {
                const sel = name === selectedValue ? ' selected' : '';
                html += `<div class="custom-select-option${sel}" data-value="${escapeHtml(name)}">${escapeHtml(name)}</div>`;
            }
            html += `</div></div></div>`;
            return html;
        }

        function getAssetSelectValue(selectId) {
            const cs = document.querySelector(`.custom-select[data-select-id="${selectId}"]`);
            if (cs) {
                const selected = cs.querySelector('.custom-select-option.selected');
                return selected ? selected.dataset.value : '';
            }
            const nativeSelect = document.getElementById(selectId);
            return nativeSelect && typeof nativeSelect.value === 'string' ? nativeSelect.value : '';
        }

        function setAssetSelectValue(selectId, value) {
            const cs = document.querySelector(`.custom-select[data-select-id="${selectId}"]`);
            const normalizedValue = value == null ? '' : String(value);
            if (!cs) {
                const nativeSelect = document.getElementById(selectId);
                if (!nativeSelect || typeof nativeSelect.value !== 'string') {
                    console.error(`[ASSET] 설정 선택값 복원 실패: 컨트롤 없음 (${selectId})`);
                    return false;
                }
                const options = Array.from(nativeSelect.options || []);
                if (options.length && !options.some(opt => opt.value === normalizedValue)) {
                    console.error(`[ASSET] 설정 선택값 복원 실패: 옵션 없음 (${selectId}=${normalizedValue})`);
                    return false;
                }
                nativeSelect.value = normalizedValue;
                return true;
            }
            const valueEl = cs.querySelector('.custom-select-value');
            const optionList = cs.querySelector('.custom-select-option-list');
            if (!valueEl || !optionList) {
                console.error(`[ASSET] 설정 선택값 복원 실패: 커스텀 셀렉트 구조 오류 (${selectId})`);
                return false;
            }
            const options = Array.from(optionList.querySelectorAll('.custom-select-option'));
            const target = options.find(opt => opt.dataset.value === normalizedValue);
            if (!target) {
                console.error(`[ASSET] 설정 선택값 복원 실패: 옵션 없음 (${selectId}=${normalizedValue})`);
                return false;
            }
            options.forEach(opt => opt.classList.remove('selected'));
            target.classList.add('selected');
            valueEl.textContent = target.textContent;
            return true;
        }

        function bindAssetCustomSelects() {
            document.querySelectorAll('.custom-select[data-select-id]').forEach(cs => {
                const selectId = cs.dataset.selectId;
                const onChangeFn = cs.dataset.onchange;
                const valueEl = cs.querySelector('.custom-select-value');
                const searchInput = cs.querySelector('.custom-select-search');
                const optionList = cs.querySelector('.custom-select-option-list');

                // 이미 바인딩된 경우 스킵
                if (cs.dataset.bound) return;
                cs.dataset.bound = 'true';

                // 열기/닫기 토글
                cs.addEventListener('click', (e) => {
                    if (e.target.closest('.custom-select-option')) return;
                    if (e.target.closest('.custom-select-search')) return;
                    const wasOpen = cs.classList.contains('open');
                    document.querySelectorAll('.custom-select.open').forEach(o => o.classList.remove('open'));
                    if (!wasOpen) {
                        cs.classList.add('open');
                        searchInput.value = '';
                        filterCustomOptions(optionList, '');
                        requestAnimationFrame(() => searchInput.focus());
                    }
                });

                // 검색 필터링
                searchInput.addEventListener('input', (e) => {
                    e.stopPropagation();
                    filterCustomOptions(optionList, searchInput.value);
                });
                searchInput.addEventListener('click', (e) => e.stopPropagation());

                // 옵션 선택
                optionList.addEventListener('click', (e) => {
                    const opt = e.target.closest('.custom-select-option');
                    if (!opt) return;
                    e.stopPropagation();
                    const val = opt.dataset.value;
                    valueEl.textContent = opt.textContent;
                    optionList.querySelectorAll('.custom-select-option').forEach(o => o.classList.remove('selected'));
                    opt.classList.add('selected');
                    cs.classList.remove('open');

                    // onChange 콜백 실행
                    if (onChangeFn && typeof window[onChangeFn] === 'function') {
                        window[onChangeFn]();
                    }
                });
            });
        }

