        function colorBlockHeaders(text) {
            // [BLOCK_NAME] 타이틀에 색상 적용
            return escapeHtml(text).replace(/\[([A-Z_]+)\]/g, (match, name) => {
                const color = BLOCK_COLORS[name] || '#aaa';
                return `<span style="color:${color};font-weight:bold;">[${name}]</span>`;
            });
        }

        function renderColoredPrompt(categoryData) {
            // categoryData: [{key, tags: [string]}, ...]
            const parts = [];
            for (const cat of categoryData) {
                const meta = PROMPT_CATEGORIES.find(c => c.key === cat.key);
                if (!meta) continue;
                const validTags = cat.tags.filter(t => t && t.trim()).map(t => escapeHtml(t.trim()));
                if (validTags.length === 0) continue;
                parts.push(`<span class="${meta.cls}" title="${meta.label}">${validTags.join(', ')}</span>`);
            }
            return parts.join(', ');
        }

        // ─── 단일 에셋 UI 상태를 공통 프롬프트 슬롯으로 변환 ──────────
        async function buildAssetPromptFromUI() {
            if (!assetTags) return null;
            const capabilities = getAssetWorkflowCapabilities();
            const hasAnima = capabilities.anima;
            const app = getAssetSelectValue('asset-appearance-select');
            const outfit = getAssetSelectValue('asset-outfit-select');
            const expr = getAssetSelectValue('asset-expression-select');
            const artistName = getAssetSelectValue('asset-artist-preset-select') || '';
            const animaArtistName = getAssetSelectValue('anima-artist-preset-select') || '';
            const slot = {
                asset_workflow_type: capabilities.type,
                raw_quality_tags: [...(assetTags.quality || [])],
                raw_composition_tags: [...(assetTags.composition || [])],
                raw_artist_tags: artistName
                    ? [...(assetTags.artist_presets?.[artistName] || [])]
                    : [],
                raw_anima_artist_tags: animaArtistName
                    ? [...(assetTags.artist_presets?.[animaArtistName] || [])]
                    : [],
                raw_appearance_tags: app ? [...(assetTags.appearances?.[app] || [])] : [],
                raw_expression_tags: expr ? [...(assetTags.expressions?.[expr] || [])] : [],
                raw_outfit_tags: outfit ? [...(assetTags.outfits?.[outfit] || [])] : [],
                raw_character_negative_tags: [...(assetTags.character_negative || [])],
                raw_negative_tags: [...(assetTags.negative || [])],
                raw_anima_quality_tags: [...(assetTags.anima_quality || [])],
                raw_anima_negative_tags: [...(assetTags.anima_negative || [])],
                natural_language: document.getElementById('asset-natural-language-text')?.value?.trim() || '',
                lora_enabled: document.getElementById('asset-lora-toggle')?.checked || false,
                lora_list: assetLoraList,
                style_lora_enabled: document.getElementById('asset-style-lora-toggle')?.checked || false,
                style_lora_list: styleLoraList,
                face_lora_enabled: hasAnima && (document.getElementById('asset-face-lora-toggle')?.checked || false),
                face_lora_list: faceLoraList,
                face_lora_upscale_size: document.getElementById('asset-face-lora-upscale')?.value || '',
                face_tags: document.getElementById('asset-face-tags')?.value.trim() || '',
                eye_tags: document.getElementById('asset-eye-tags')?.value.trim() || '',
                ref_enabled: capabilities.ipadapter && (document.getElementById('asset-ref-toggle')?.checked || false),
                ref_strength: parseFloat(document.getElementById('asset-ref-strength')?.value) || 0.55,
                ref_dir: document.getElementById('asset-ref-folder-hash-text')?.textContent || '',
                snapref_enabled: hasAnima && (document.getElementById('asset-snapref-toggle')?.checked || false),
                snapref_strength: Number(document.getElementById('asset-snapref-strength')?.value ?? 0),
                snapref_mode: document.getElementById('asset-snapref-mode')?.value || 'char',
                snapref_megapixels: Number(document.getElementById('asset-snapref-megapixels')?.value ?? 1),
                snapref_dir: assetSnapRefDir,
                style_ref_enabled: capabilities.ipadapter && (document.getElementById('asset-style-ref-toggle')?.checked || false),
                style_ref_strength: parseFloat(document.getElementById('asset-style-ref-strength')?.value) || 0.55,
                style_ref_dir: document.getElementById('asset-style-ref-folder-hash-text')?.textContent || '',
                pose_enabled: capabilities.pose && (document.getElementById('asset-pose-toggle')?.checked || false),
                pose_id: assetSelectedPoseId || '',
                hrf_sdxl: capabilities.ilxl && (document.getElementById('asset-hrf-sdxl')?.checked || false),
                hrf_anima: hasAnima && (document.getElementById('asset-hrf-anima')?.checked || false),
                hrf_size: parseFloat(document.getElementById('asset-hrf-size')?.value) || 2.0,
                hrf_restore_size: document.getElementById('asset-hrf-restore-size')?.checked || false,
                hrf_control_net: document.getElementById('asset-hrf-control-net')?.checked || false,
                img_w: parseInt(document.getElementById('asset-img-w')?.value) || 700,
                img_h: parseInt(document.getElementById('asset-img-h')?.value) || 1024,
                sdxl_fd_enabled: capabilities.ilxl && (document.getElementById('asset-sdxl-fd')?.checked || false),
                sdxl_hd_enabled: capabilities.ilxl && (document.getElementById('asset-sdxl-hd')?.checked || false),
                sdxl_ed_enabled: capabilities.ilxl && (document.getElementById('asset-sdxl-ed')?.checked || false),
                anima_fd_enabled: hasAnima && (document.getElementById('asset-anima-fd')?.checked || false),
                anima_hd_enabled: hasAnima && (document.getElementById('asset-anima-hd')?.checked || false),
                anima_ed_enabled: hasAnima && (document.getElementById('asset-anima-ed')?.checked || false),
                face_crop_top: parseFloat(document.getElementById('asset-face-crop-top')?.value) || 2.5,
                face_crop_bottom: parseFloat(document.getElementById('asset-face-crop-bottom')?.value) || 1,
                seed: parseInt(document.getElementById('asset-seed-input')?.value) || -1,
            };
            const promptData = await buildAssetPromptData(slot);
            if (!promptData) {
                console.error('[ASSET] 공통 프롬프트 빌더가 빈 결과를 반환했습니다:', slot);
                return null;
            }
            return {
                ...promptData,
                positiveColored: colorBlockHeaders(promptData.positive),
                negativeColored: colorBlockHeaders(promptData.negative),
                positiveLength: promptData.positive.length,
            };
        }

        // ─── 설정 저장/불러오기 ────────────────────────────────
        function saveAssetSettings() {
            const capabilities = getAssetWorkflowCapabilities();
            const isAnima = capabilities.anima;
            const settings = {
                cache_version: 2,
                character: getAssetSelectValue('asset-character-select'),
                appearance: getAssetSelectValue('asset-appearance-select'),
                outfit: getAssetSelectValue('asset-outfit-select'),
                expression: getAssetSelectValue('asset-expression-select'),
                artist_preset: getAssetSelectValue('asset-artist-preset-select'),
                quality_preset: getAssetSelectValue('asset-quality-preset-select'),
                composition_preset: getAssetSelectValue('asset-composition-preset-select'),
                character_negative_preset: getAssetSelectValue('asset-character-negative-preset-select'),
                negative_preset: getAssetSelectValue('asset-negative-preset-select'),
                natural_language_preset: getAssetSelectValue('asset-natural-language-preset-select'),
                natural_language_text: document.getElementById('asset-natural-language-text')?.value || '',
                ref_enabled: document.getElementById('asset-ref-toggle')?.checked || false,
                ref_strength: parseFloat(document.getElementById('asset-ref-strength')?.value) || 0.55,
                ref_dir: document.getElementById('asset-ref-folder-hash-text')?.textContent || '',
                snapref_enabled: document.getElementById('asset-snapref-toggle')?.checked || false,
                snapref_strength: Number(document.getElementById('asset-snapref-strength')?.value ?? 0),
                snapref_mode: document.getElementById('asset-snapref-mode')?.value || 'char',
                snapref_megapixels: Number(document.getElementById('asset-snapref-megapixels')?.value ?? 1),
                snapref_images: assetSnapRefImages.map(image => ({...image})),
                snapref_dir: assetSnapRefDir,
                style_ref_enabled: document.getElementById('asset-style-ref-toggle')?.checked || false,
                style_ref_strength: parseFloat(document.getElementById('asset-style-ref-strength')?.value) || 0.55,
                style_ref_dir: document.getElementById('asset-style-ref-folder-hash-text')?.textContent || '',
                lora_enabled: document.getElementById('asset-lora-toggle')?.checked || false,
                lora_list: assetLoraList.map(l => ({...l})),
                style_lora_enabled: document.getElementById('asset-style-lora-toggle')?.checked || false,
                style_lora_list: styleLoraList.map(l => ({...l})),
                pose_enabled: document.getElementById('asset-pose-toggle')?.checked || false,
                pose_id: assetSelectedPoseId || '',
                img_w: parseInt(document.getElementById('asset-img-w')?.value) || 700,
                img_h: parseInt(document.getElementById('asset-img-h')?.value) || 1024,
                hrf_sdxl: capabilities.ilxl && (document.getElementById('asset-hrf-sdxl')?.checked || false),
                hrf_anima: capabilities.anima && (document.getElementById('asset-hrf-anima')?.checked || false),
                hrf_size: parseFloat(document.getElementById('asset-hrf-size')?.value) || 2.0,
                hrf_restore_size: document.getElementById('asset-hrf-restore-size')?.checked || false,
                hrf_control_net: document.getElementById('asset-hrf-control-net')?.checked || false,
                sdxl_fd: capabilities.ilxl && (document.getElementById('asset-sdxl-fd')?.checked || false),
                sdxl_hd: capabilities.ilxl && (document.getElementById('asset-sdxl-hd')?.checked || false),
                sdxl_ed: capabilities.ilxl && (document.getElementById('asset-sdxl-ed')?.checked || false),
                anima_fd: capabilities.anima && (document.getElementById('asset-anima-fd')?.checked || false),
                anima_hd: capabilities.anima && (document.getElementById('asset-anima-hd')?.checked || false),
                anima_ed: capabilities.anima && (document.getElementById('asset-anima-ed')?.checked || false),
            };
            if (isAnima) {
                settings.anima_artist_preset = getAssetSelectValue('anima-artist-preset-select');
                settings.anima_quality_preset = getAssetSelectValue('anima-quality-preset-select');
                settings.anima_negative_preset = getAssetSelectValue('anima-negative-preset-select');
                settings.face_lora_enabled = document.getElementById('asset-face-lora-toggle')?.checked || false;
                settings.face_lora_list = faceLoraList.map(l => ({...l}));
                settings.face_crop_top = parseFloat(document.getElementById('asset-face-crop-top')?.value) || 2.5;
                settings.face_crop_bottom = parseFloat(document.getElementById('asset-face-crop-bottom')?.value) || 1;
                settings.face_tags = document.getElementById('asset-face-tags')?.value || '';
                settings.eye_tags = document.getElementById('asset-eye-tags')?.value || '';
                settings.face_lora_upscale_size = document.getElementById('asset-face-lora-upscale')?.value || '';
                settings.seed = parseInt(document.getElementById('asset-seed-input')?.value) || -1;
            }
            try {
                localStorage.setItem('assetModeSettings', JSON.stringify(settings));
                showToast('설정이 캐시에 저장되었습니다');
            } catch (e) {
                console.error('[ASSET] 설정 캐시 저장 실패:', e);
                showToast('설정 저장 실패', 'error');
            }
        }

        async function loadAssetSettings() {
            let raw;
            try {
                raw = localStorage.getItem('assetModeSettings');
            } catch (e) {
                console.error('[ASSET] 설정 불러오기 실패: 캐시 접근 오류', e);
                showToast('설정 불러오기 실패', 'error');
                return;
            }
            if (!raw) {
                console.error('[ASSET] 설정 불러오기 실패: 저장된 캐시 없음');
                showToast('저장된 설정이 없습니다', 'error');
                return;
            }
            let s;
            try {
                s = JSON.parse(raw);
            } catch(e) {
                console.error('[ASSET] 설정 불러오기 실패: 캐시 JSON 파싱 오류', e);
                showToast('설정 불러오기 실패', 'error');
                return;
            }
            if (!s || typeof s !== 'object' || Array.isArray(s)) {
                console.error('[ASSET] 설정 불러오기 실패: 캐시 형식 오류', s);
                showToast('설정 불러오기 실패', 'error');
                return;
            }

            try {
                const requiredCustomSelect = document.querySelector(
                    '.custom-select[data-select-id="asset-appearance-select"]'
                );
                if (!assetTags || !requiredCustomSelect) await loadAssetData();
                if (!assetTags) throw new Error('에셋 태그 데이터가 준비되지 않았습니다');

                const isAnima = getAssetWorkflowCapabilities().anima;
                const restoreFailures = [];
                const restoreSelect = (selectId, value, label) => {
                    const restored = setAssetSelectValue(selectId, value);
                    if (!restored) restoreFailures.push(label);
                    return restored;
                };

                // v1 캐시는 일반 select를 커스텀 select 헬퍼로 읽어 캐릭터가 항상 비어 있었다.
                // 해당 캐시는 현재 캐릭터를 유지하고, v2부터 빈 선택도 저장값 그대로 복원한다.
                if (s.cache_version >= 2 || s.character) {
                    restoreSelect('asset-character-select', s.character, '캐릭터');
                } else {
                    console.warn('[ASSET] 이전 캐시에 캐릭터 값이 없어 현재 선택을 유지합니다.');
                }
                onAssetCharacterChange(true);

                restoreSelect('asset-appearance-select', s.appearance, '외모');
                onAssetAppearanceChange();
                restoreSelect('asset-outfit-select', s.outfit, '복장');
                onAssetOutfitChange();
                restoreSelect('asset-expression-select', s.expression, '표정');
                onAssetExpressionChange();
                restoreSelect('asset-artist-preset-select', s.artist_preset, '아티스트 프리셋');
                loadArtistPreset();
                restoreSelect('asset-quality-preset-select', s.quality_preset, '품질 프리셋');
                if (await loadQualityPreset() === false) restoreFailures.push('품질 태그');
                restoreSelect('asset-composition-preset-select', s.composition_preset, '구도 프리셋');
                if (await loadCompositionPreset() === false) restoreFailures.push('구도 태그');
                restoreSelect('asset-character-negative-preset-select', s.character_negative_preset, '캐릭터 부정 프리셋');
                if (await loadCharacterNegativePreset() === false) restoreFailures.push('캐릭터 부정 태그');
                restoreSelect('asset-negative-preset-select', s.negative_preset, '부정 프리셋');
                if (await loadNegativePreset() === false) restoreFailures.push('부정 태그');
                restoreSelect('asset-natural-language-preset-select', s.natural_language_preset, '자연어 프리셋');
                loadNaturalLanguagePreset();
                const nlText = document.getElementById('asset-natural-language-text');
                if (nlText) nlText.value = s.natural_language_text || '';

                const refToggle = document.getElementById('asset-ref-toggle');
                if (refToggle) { refToggle.checked = s.ref_enabled || false; refToggle.dispatchEvent(new Event('change')); }
                const refStrength = document.getElementById('asset-ref-strength');
                if (refStrength) { refStrength.value = s.ref_strength || 0.55; refStrength.dispatchEvent(new Event('input')); }
                assetSnapRefImages = (s.snapref_images || []).slice(0, 1).map(image => ({...image}));
                assetSnapRefDir = s.snapref_dir || '';
                const snaprefToggle = document.getElementById('asset-snapref-toggle');
                if (snaprefToggle) { snaprefToggle.checked = s.snapref_enabled || false; onAssetRefToggle('snapref'); }
                document.getElementById('asset-snapref-mode').value = s.snapref_mode || 'char';
                document.getElementById('asset-snapref-strength').value = s.snapref_strength ?? 0;
                document.getElementById('asset-snapref-strength-val').textContent = s.snapref_strength ?? 0;
                document.getElementById('asset-snapref-megapixels').value = s.snapref_megapixels ?? 1;
                document.getElementById('asset-snapref-megapixels-val').textContent = s.snapref_megapixels ?? 1;
                renderAssetRefPreview('snapref');
                const styleToggle = document.getElementById('asset-style-ref-toggle');
                if (styleToggle) { styleToggle.checked = s.style_ref_enabled || false; styleToggle.dispatchEvent(new Event('change')); }
                const styleStrength = document.getElementById('asset-style-ref-strength');
                if (styleStrength) { styleStrength.value = s.style_ref_strength || 0.55; styleStrength.dispatchEvent(new Event('input')); }

                const loraToggle = document.getElementById('asset-lora-toggle');
                if (loraToggle) { loraToggle.checked = s.lora_enabled || false; loraToggle.dispatchEvent(new Event('change')); }
                assetLoraList = (s.lora_list || []).map(l => ({...l}));
                renderAssetLoraList();

                const styleLoraToggle = document.getElementById('asset-style-lora-toggle');
                if (styleLoraToggle) { styleLoraToggle.checked = s.style_lora_enabled || false; styleLoraToggle.dispatchEvent(new Event('change')); }
                styleLoraList = (s.style_lora_list || []).map(l => ({...l}));
                renderAssetStyleLoraList();

                const poseToggle = document.getElementById('asset-pose-toggle');
                if (poseToggle) { poseToggle.checked = s.pose_enabled || false; poseToggle.dispatchEvent(new Event('change')); }
                assetSelectedPoseId = s.pose_id || '';

                const imgW = document.getElementById('asset-img-w');
                if (imgW) imgW.value = s.img_w || 700;
                const imgH = document.getElementById('asset-img-h');
                if (imgH) imgH.value = s.img_h || 1024;

                const hrfSdxl = document.getElementById('asset-hrf-sdxl');
                if (hrfSdxl) hrfSdxl.checked = s.hrf_sdxl || false;
                const hrfAnima = document.getElementById('asset-hrf-anima');
                if (hrfAnima) hrfAnima.checked = s.hrf_anima || false;
                const hrfSize = document.getElementById('asset-hrf-size');
                if (hrfSize) { hrfSize.value = s.hrf_size || 2.0; hrfSize.dispatchEvent(new Event('input')); }
                const hrfRestore = document.getElementById('asset-hrf-restore-size');
                if (hrfRestore) hrfRestore.checked = s.hrf_restore_size !== false;
                const hrfControlNet = document.getElementById('asset-hrf-control-net');
                if (hrfControlNet) hrfControlNet.checked = s.hrf_control_net || false;
                const sdxlFd = document.getElementById('asset-sdxl-fd');
                if (sdxlFd) sdxlFd.checked = s.sdxl_fd || false;
                const sdxlHd = document.getElementById('asset-sdxl-hd');
                if (sdxlHd) sdxlHd.checked = s.sdxl_hd || false;
                const sdxlEd = document.getElementById('asset-sdxl-ed');
                if (sdxlEd) sdxlEd.checked = s.sdxl_ed || false;
                const animaFd = document.getElementById('asset-anima-fd');
                if (animaFd) animaFd.checked = s.anima_fd || false;
                const animaHd = document.getElementById('asset-anima-hd');
                if (animaHd) animaHd.checked = s.anima_hd || false;
                const animaEd = document.getElementById('asset-anima-ed');
                if (animaEd) animaEd.checked = s.anima_ed || false;

                if (isAnima) {
                    restoreSelect('anima-artist-preset-select', s.anima_artist_preset, 'ANIMA 아티스트 프리셋');
                    loadAnimaArtistPreset();
                    restoreSelect('anima-quality-preset-select', s.anima_quality_preset, 'ANIMA 품질 프리셋');
                    if (await loadAnimaQualityPreset() === false) restoreFailures.push('ANIMA 품질 태그');
                    restoreSelect('anima-negative-preset-select', s.anima_negative_preset, 'ANIMA 부정 프리셋');
                    if (await loadAnimaNegativePreset() === false) restoreFailures.push('ANIMA 부정 태그');
                    const faceLoraToggle = document.getElementById('asset-face-lora-toggle');
                    if (faceLoraToggle) { faceLoraToggle.checked = s.face_lora_enabled || false; faceLoraToggle.dispatchEvent(new Event('change')); }
                    faceLoraList = (s.face_lora_list || []).map(l => ({...l}));
                    renderAssetFaceLoraList();
                    const faceCropTop = document.getElementById('asset-face-crop-top');
                    if (faceCropTop) faceCropTop.value = s.face_crop_top ?? 2.5;
                    const faceCropBottom = document.getElementById('asset-face-crop-bottom');
                    if (faceCropBottom) faceCropBottom.value = s.face_crop_bottom ?? 1;
                    const faceTags = document.getElementById('asset-face-tags');
                    if (faceTags) faceTags.value = s.face_tags || '';
                    if (typeof initFaceTagsFromArray === 'function') initFaceTagsFromArray(s.face_tags || '');
                    const eyeTags = document.getElementById('asset-eye-tags');
                    if (eyeTags) eyeTags.value = s.eye_tags || '';
                    const faceLoraUpscale = document.getElementById('asset-face-lora-upscale');
                    if (faceLoraUpscale) faceLoraUpscale.value = s.face_lora_upscale_size || '';
                    const seedInput = document.getElementById('asset-seed-input');
                    if (seedInput) seedInput.value = s.seed ?? -1;
                }
                updateGenerateBtn();

                if (restoreFailures.length) {
                    const uniqueFailures = [...new Set(restoreFailures)];
                    console.error('[ASSET] 설정 일부 복원 실패:', uniqueFailures);
                    showToast(`일부 설정을 불러오지 못했습니다: ${uniqueFailures.join(', ')}`, 'error');
                    return;
                }
                showToast('설정을 불러왔습니다');
            } catch (e) {
                console.error('[ASSET] 설정 불러오기 실패:', e);
                showToast('설정 불러오기 실패: ' + e.message, 'error');
            }
        }

        // ─── 프롬프트 미리보기 ───────────────────────────────
        async function previewAssetPrompt() {
            const data = await buildAssetPromptFromUI();
            if (!data) return;

            const overlay = document.createElement('div');
            overlay.id = 'prompt-preview-overlay';
            overlay.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.6); z-index:270; display:flex; align-items:center; justify-content:center;';
            overlay.innerHTML = `
                <div style="background:var(--surface); border-radius:12px; padding:20px; max-width:600px; width:90%; max-height:80vh; overflow-y:auto;">
                    <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px;">
                        <h3 style="margin:0;">프롬프트 미리보기</h3>
                        <button onclick="document.getElementById('prompt-preview-overlay').remove()" style="background:none; border:none; color:var(--text); font-size:1.2rem; cursor:pointer;">x</button>
                    </div>
                    <div style="margin-bottom:12px;">
                        <div style="font-size:0.8rem; font-weight:600; color:var(--success); margin-bottom:4px;">긍정 프롬프트</div>
                        <div style="background:var(--surface2); padding:10px; border-radius:6px; font-size:0.75rem; white-space:pre-wrap; word-break:break-all; max-height:300px; overflow-y:auto; margin:0; font-family:'Consolas',monospace;">${data.positiveColored}${colorBlockHeaders(data.positive.substring(data.positiveLength))}</div>
                    </div>
                    <div>
                        <div style="font-size:0.8rem; font-weight:600; color:var(--error); margin-bottom:4px;">부정 프롬프트</div>
                        <div style="background:var(--surface2); padding:10px; border-radius:6px; font-size:0.75rem; white-space:pre-wrap; word-break:break-all; max-height:150px; overflow-y:auto; margin:0; font-family:'Consolas',monospace;">${data.negativeColored ? data.negativeColored : escapeHtml(data.negative || '(없음)')}</div>
                    </div>
                </div>`;
            document.body.appendChild(overlay);
        }

        // ─── 구도/기타 태그 ─────────────────────────────────
        async function addAssetCompositionTag() {
            await addAssetTagInput({
                inputId: 'asset-new-composition-tag',
                action: 'add_composition_tag',
                existingTags: assetTags?.composition || [],
                afterReload: () => {
                    renderTagChips('asset-composition-tags', assetTags.composition || [], 'removeAssetCompositionTag');
                    syncCompositionPreset();
                }
            });
        }

        async function removeAssetCompositionTag(idx) {
            await modifyTagLightweight('remove_composition_tag', { index: idx }, 'asset-composition-tags', 'removeAssetCompositionTag', 'composition', syncCompositionPreset);
        }

        // ─── 구도 프리셋 ────────────────────────────────────
        function addCompositionPreset() {
            if (!assetTags) return;
            const name = prompt('새 프리셋명');
            if (!name || !name.trim()) return;
            assetTagAction('save_composition_preset', { name: name.trim(), tags: [] });
        }

        function duplicateCompositionPreset() {
            const src = getAssetSelectValue('asset-composition-preset-select');
            if (!src) { showToast('복제할 프리셋을 선택하세요', 'error'); return; }
            const newName = prompt('새 프리셋명', src + ' 복사본');
            if (!newName || !newName.trim()) return;
            assetTagAction('duplicate_composition_preset', { source: src, name: newName.trim() });
        }

        function syncCompositionPreset() {
            const sel = getAssetSelectValue('asset-composition-preset-select');
            if (!sel || !assetTags) return;
            fetch('/api/asset_mode/tags', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: 'save_composition_preset', name: sel, tags: assetTags.composition || [] })
            }).catch(() => {});
        }

        function loadCompositionPreset() {
            const name = getAssetSelectValue('asset-composition-preset-select');
            return modifyTagLightweight('load_composition_preset', { name }, 'asset-composition-tags', 'removeAssetCompositionTag', 'composition');
        }

        function deleteCompositionPreset() {
            const name = getAssetSelectValue('asset-composition-preset-select');
            if (!name) return;
            if (!confirm(`프리셋 "${name}" 삭제?`)) return;
            assetTagAction('delete_composition_preset', { name });
        }

        // ─── 아티스트 프리셋 ────────────────────────────────────
        function loadArtistPreset() {
            const name = getAssetSelectValue('asset-artist-preset-select');
            const tagsDiv = document.getElementById('asset-artist-tags');
            tagsDiv.innerHTML = '';
            if (!name || !assetTags) return;
            const tags = assetTags.artist_presets?.[name] || [];
            renderTagChipsWithFn(tagsDiv, tags, (idx) => {
                removeArtistTag(name, idx);
            });
        }

        async function removeArtistTag(presetName, idx) {
            if (!assetTags?.artist_presets?.[presetName]) return;
            const newTags = [...assetTags.artist_presets[presetName]];
            newTags.splice(idx, 1);
            try {
                const resp = await fetch('/api/asset_mode/tags', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'save_artist_preset', name: presetName, tags: newTags }) });
                const result = await resp.json();
                if (result.success) {
                    const dataResp = await fetch('/api/asset_mode/tags');
                    assetTags = await dataResp.json();
                    if (typeof botRenderNegativePresetSelect === 'function') botRenderNegativePresetSelect();
                    const tagsDiv = document.getElementById('asset-artist-tags');
                    const tags = assetTags.artist_presets?.[presetName] || [];
                    renderTagChipsWithFn(tagsDiv, tags, (i) => { removeArtistTag(presetName, i); });
                } else { showToast(result.error || '오류', 'error'); }
            } catch (e) { showToast('요청 실패: ' + e.message, 'error'); }
        }

        async function addAssetArtistTag() {
            const input = document.getElementById('asset-new-artist-tag');
            if (!input.value.trim()) return;
            const presetName = getAssetSelectValue('asset-artist-preset-select');
            if (!presetName) { showToast('아티스트 프리셋을 먼저 선택하세요', 'error'); return; }
            const currentTags = assetTags.artist_presets?.[presetName] || [];
            const newTags = parseAssetTagInput(input.value, currentTags);
            input.value = '';
            if (!newTags.length) {
                console.error(`[ASSET] 아티스트 태그 추가 건너뜀: 새 태그 없음 (${presetName})`);
                showToast('추가할 새 태그가 없습니다', 'error');
                return;
            }
            try {
                const resp = await fetch('/api/asset_mode/tags', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'save_artist_preset', name: presetName, tags: [...currentTags, ...newTags] }) });
                const result = await resp.json();
                if (result.success) {
                    const dataResp = await fetch('/api/asset_mode/tags');
                    assetTags = await dataResp.json();
                    if (typeof botRenderNegativePresetSelect === 'function') botRenderNegativePresetSelect();
                    const tagsDiv = document.getElementById('asset-artist-tags');
                    const tags = assetTags.artist_presets?.[presetName] || [];
                    renderTagChipsWithFn(tagsDiv, tags, (idx) => { removeArtistTag(presetName, idx); });
                } else { showToast(result.error || '오류', 'error'); }
            } catch (e) { showToast('요청 실패: ' + e.message, 'error'); }
        }

