        function setWorkflowModeAvailability(container, available) {
            if (!container) return;
            container.classList.toggle('is-unavailable', !available);
            container.setAttribute('aria-disabled', available ? 'false' : 'true');
            if (available) container.removeAttribute('inert');
            else container.setAttribute('inert', '');
            container.querySelectorAll('input, select, textarea, button').forEach(control => {
                if (!available) {
                    if (!control.hasAttribute('data-workflow-was-disabled')) {
                        control.dataset.workflowWasDisabled = control.disabled ? 'true' : 'false';
                    }
                    control.disabled = true;
                } else if (control.hasAttribute('data-workflow-was-disabled')) {
                    control.disabled = control.dataset.workflowWasDisabled === 'true';
                    delete control.dataset.workflowWasDisabled;
                }
            });
        }

        function applyWorkflowModeAvailability(root, capabilities = getAssetWorkflowCapabilities()) {
            if (!root) return;
            root.querySelectorAll('[data-workflow-availability]').forEach(container => {
                const availability = container.dataset.workflowAvailability;
                const available = availability === 'anima' ? capabilities.anima
                    : availability === 'regular' || availability === 'ilxl' ? capabilities.ilxl
                    : availability === 'pose' ? capabilities.pose
                    : availability === 'ipadapter' ? capabilities.ipadapter
                    : availability === 'face-lora' ? capabilities.faceLora
                    : true;
                setWorkflowModeAvailability(container, available);
            });
        }

        // ─── ANIMA UI 활성화/비활성화 및 포즈 제어 ─────────────────
        function updateAnimaUIVisibility() {
            const capabilities = getAssetWorkflowCapabilities();
            applyWorkflowModeAvailability(document, capabilities);
            // ANIMA 모드에서 기존 섹션 라벨 변경
            const qualitySection = document.getElementById('asset-quality-tags')?.closest('div[style*="rgba(76,175,80"]');
            if (qualitySection) {
                const title = qualitySection.querySelector('.section-title');
                if (title) title.textContent = 'ILXL 품질 태그';
            }
            const negSection = document.getElementById('asset-negative-tags')?.closest('div[style*="rgba(244,67,54"]');
            if (negSection) {
                const title = negSection.querySelector('.section-title');
                if (title) title.textContent = 'ILXL 부정 태그';
            }
            updatePoseForWorkflowType();
            // EP HRF 모드 드롭다운 표시 동기화
            const epHrfMode = document.getElementById('ep-hrf-mode');
            if (epHrfMode) {
                const epHrfOn = document.getElementById('ep-hrf-toggle')?.checked;
                epHrfMode.style.display = (capabilities.dual && epHrfOn) ? 'inline-block' : 'none';
            }
            if (typeof atApplyFillWorkflowAvailability === 'function') atApplyFillWorkflowAvailability();
            if (typeof atUpdateFillHiresAvailability === 'function') atUpdateFillHiresAvailability();
        }

        function updatePoseForWorkflowType() {
            const capabilities = getAssetWorkflowCapabilities();
            const poseContainer = document.getElementById('asset-pose-container');
            const poseToggle = document.getElementById('asset-pose-toggle');
            setWorkflowModeAvailability(poseContainer, capabilities.pose);
            if (!capabilities.pose && poseToggle) poseToggle.checked = false;
            if (poseToggle) document.getElementById('asset-pose-section').style.display = poseToggle.checked ? 'block' : 'none';
        }

