        // 품질/구도/부정 태그: renderAssetUI() 없이 태그 컨테이너만 업데이트 (스크롤 유지)
        async function modifyTagLightweight(action, params, containerId, removeFnName, tagKey, syncFn) {
            try {
                const resp = await fetch('/api/asset_mode/tags', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ action, ...params })
                });
                const result = await resp.json();
                if (result.success) {
                    const dataResp = await fetch('/api/asset_mode/tags');
                    assetTags = await dataResp.json();
                    if (typeof botRenderNegativePresetSelect === 'function') botRenderNegativePresetSelect();
                    renderTagChips(containerId, assetTags[tagKey] || [], removeFnName);
                    if (syncFn) syncFn();
                    return true;
                } else {
                    console.error(`[ASSET] 태그 프리셋 적용 실패: action=${action}, error=${result.error || '알 수 없는 오류'}`);
                    showToast(result.error || '오류', 'error');
                    return false;
                }
            } catch (e) {
                console.error(`[ASSET] 태그 프리셋 적용 예외: action=${action}`, e);
                showToast('요청 실패: ' + e.message, 'error');
                return false;
            }
        }

