                    statusEl.textContent = `큐에 추가됨 (${data.total}장) - 대기 중...`;
                    _startTagBatch(data.batch_id, `에셋 일괄 태깅 (${data.total}장)`, data.total, 'asset_batch', {
                        finalizeFn: () => { if (typeof auSetAnalyzingState === 'function') auSetAnalyzingState(false); },
                    });
