        function auRenderNegativePresetSelect() {
            const container = document.getElementById('au-negative-preset-select');
            if (!container || !assetTags) return;
            container.innerHTML = buildCustomSelectHTML(
                assetTags.negative_presets || {},
                '',
                '-- 부정 프리셋 선택 --',
                'au-negative-preset'
            );
            // 커스텀 드롭다운 이벤트 바인딩
            const cs = container.querySelector('.custom-select[data-field="au-negative-preset"]');
            if (!cs) return;
            const valueEl = cs.querySelector('.custom-select-value');
            const searchInput = cs.querySelector('.custom-select-search');
            const optionList = cs.querySelector('.custom-select-option-list');

            cs.addEventListener('click', (e) => {
                if (e.target.closest('.custom-select-option')) return;
                const wasOpen = cs.classList.contains('open');
                document.querySelectorAll('.custom-select.open').forEach(o => o.classList.remove('open'));
                if (!wasOpen) {
                    cs.classList.add('open');
                    searchInput.value = '';
                    filterCustomOptions(optionList, '');
                    requestAnimationFrame(() => searchInput.focus());
                }
            });

            searchInput.addEventListener('input', (e) => {
                e.stopPropagation();
                filterCustomOptions(optionList, searchInput.value);
            });
            searchInput.addEventListener('click', (e) => e.stopPropagation());

            optionList.querySelectorAll('.custom-select-option').forEach(opt => {
                opt.addEventListener('click', (e) => {
                    e.stopPropagation();
                    valueEl.textContent = opt.textContent;
                    optionList.querySelectorAll('.custom-select-option').forEach(o => o.classList.remove('selected'));
                    opt.classList.add('selected');
                    cs.classList.remove('open');
                });
            });
        }

        async function auRequestNegativePromptApply(payload, label) {
            const request = (async () => {
                let response;
                try {
                    response = await fetch('/api/asset_mode/batch_set_negative', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify(payload),
                    });
                } catch (error) {
                    console.error(`[AU] ${label} 부정 프롬프트 요청 실패:`, { payload, error });
                    throw new Error('부정 프롬프트 적용 요청에 실패했습니다');
                }

                let data;
                try {
                    data = await response.json();
                } catch (error) {
                    console.error(
                        `[AU] ${label} 부정 프롬프트 응답 파싱 실패:`,
                        { payload, status: response.status, error },
                    );
                    throw new Error('부정 프롬프트 적용 응답을 해석하지 못했습니다');
                }
                if (!data || typeof data !== 'object') {
                    console.error(
                        `[AU] ${label} 부정 프롬프트 응답 형식 오류:`,
                        { payload, status: response.status, data },
                    );
                    throw new Error('부정 프롬프트 적용 응답 형식이 올바르지 않습니다');
                }
                if (!response.ok || !data.success) {
                    console.error(
                        `[AU] ${label} 부정 프롬프트 적용 실패:`,
                        { payload, status: response.status, data },
                    );
                    throw new Error(data.error || `부정 프롬프트 적용 실패 (HTTP ${response.status})`);
                }
                return data;
            })();
            auPendingNegativePromptApplyRequests.add(request);
            try {
                return await request;
            } finally {
                auPendingNegativePromptApplyRequests.delete(request);
            }
        }

        async function auWaitForPendingNegativePromptApplies() {
            const pending = [...auPendingNegativePromptApplyRequests];
            if (pending.length === 0) return;
            const results = await Promise.allSettled(pending);
            const failure = results.find(result => result.status === 'rejected');
            if (failure) {
                console.error(
                    '[EDIT_TOOL] 대기 중인 부정 프롬프트 적용 실패:',
                    failure.reason,
                );
                throw new Error('부정 프롬프트 적용이 실패해 EDIT를 열지 못했습니다');
            }
        }

        async function auBatchSetNegative() {
            if (auNavLevel < 1 || !auNavCharacter) {
                showToast('캐릭터를 먼저 선택하세요', 'error');
                return;
            }
            const container = document.getElementById('au-negative-preset-select');
            const selEl = container ? container.querySelector('.custom-select-value') : null;
            const presetName = selEl ? selEl.textContent : '';
            if (!presetName || presetName.startsWith('--')) {
                showToast('부정 프리셋을 먼저 선택하세요', 'error');
                return;
            }
            const presetTags = assetTags.negative_presets?.[presetName];
            if (!presetTags || !Array.isArray(presetTags) || presetTags.length === 0) {
                showToast('선택한 프리셋에 태그가 없습니다', 'error');
                return;
            }
            const negativeTags = presetTags.join(', ');
            const targetCharacter = auNavCharacter;
            if (!confirm(`대표이미지에 부정 프롬프트를 일괄 적용하시겠습니까?\n기존 부정 프롬프트가 덮어씌워집니다.`)) return;

            const btn = document.getElementById('au-batch-negative-btn');
            btn.disabled = true;
            btn.textContent = '적용 중...';
            try {
                const data = await auRequestNegativePromptApply(
                    { character: targetCharacter, negative_tags: negativeTags },
                    '대표 이미지',
                );
                const total = data.total || 0;
                const ok = data.success_count || 0;
                const fail = data.fail_count || 0;
                showToast(
                    `${ok}장에 부정 프롬프트 적용 완료` + (fail > 0 ? `, ${fail}건 실패` : ''),
                    fail > 0 ? 'warning' : 'success'
                );
                await auRefreshPromptViews(targetCharacter);
            } catch (e) {
                console.error('[AU] 대표 이미지 부정 프롬프트 적용 오류:', e);
                showToast('부정 프롬프트 적용 오류: ' + e.message, 'error');
            } finally {
                btn.disabled = false;
                btn.textContent = '대표 이미지 일괄 부정 프롬프트 적용';
            }
        }

        async function auBatchSetNegativeSelected() {
            if (auNavLevel !== 2 || !auNavCharacter) {
                showToast('LV2(이미지 목록)에서만 사용 가능합니다', 'error');
                return;
            }
            if (auSelectedImages.size === 0) { showToast('이미지를 먼저 선택하세요', 'error'); return; }
            const container = document.getElementById('au-negative-preset-select');
            const selEl = container ? container.querySelector('.custom-select-value') : null;
            const presetName = selEl ? selEl.textContent : '';
            if (!presetName || presetName.startsWith('--')) {
                showToast('부정 프리셋을 먼저 선택하세요', 'error');
                return;
            }
            const presetTags = assetTags.negative_presets?.[presetName];
            if (!presetTags || !Array.isArray(presetTags) || presetTags.length === 0) {
                showToast('선택한 프리셋에 태그가 없습니다', 'error');
                return;
            }
            const negativeTags = presetTags.join(', ');
            const targetCharacter = auNavCharacter;
            const targetOutfit = auNavOutfit;
            const targetExpression = auNavExpression;
            // URL → {outfit, expression, filename} 추출 (auAnalyzeSelectedImages 와 동일 패턴)
            const images = [...auSelectedImages].map(url => {
                const parts = url.split('/images/');
                const filename = parts.length > 1 ? decodeURIComponent(parts[parts.length - 1]) : '';
                return { outfit: targetOutfit, expression: targetExpression, filename };
            }).filter(img => img.filename);
            if (images.length === 0) { showToast('유효한 이미지가 없습니다', 'error'); return; }
            if (!confirm(`선택한 ${images.length}장 이미지에 부정 프롬프트를 적용하시겠습니까?\n기존 부정 프롬프트가 덮어씌워집니다.`)) return;

            const btn = document.getElementById('au-batch-negative-selected-btn');
            btn.disabled = true;
            const origText = btn.textContent;
            btn.textContent = '적용 중...';
            try {
                const data = await auRequestNegativePromptApply(
                    {
                        character: targetCharacter,
                        negative_tags: negativeTags,
                        images,
                    },
                    '선택 이미지',
                );
                const ok = data.success_count || 0;
                const fail = data.fail_count || 0;
                showToast(
                    `선택 ${ok}장에 부정 프롬프트 적용 완료` + (fail > 0 ? `, ${fail}건 실패` : ''),
                    fail > 0 ? 'warning' : 'success'
                );
                await auRefreshPromptViews(
                    targetCharacter,
                    targetOutfit,
                    targetExpression,
                );
            } catch (e) {
                console.error('[AU] 선택 이미지 부정 프롬프트 적용 오류:', e);
                showToast('부정 프롬프트 적용 오류: ' + e.message, 'error');
            } finally {
                btn.disabled = auSelectedImages.size === 0;
                btn.textContent = origText;
            }
        }

        async function auRefreshPromptViews(character, outfit = '', expression = '') {
            const refreshes = [];
            if (
                auNavLevel === 2
                && auNavCharacter === character
                && (!outfit || auNavOutfit === outfit)
                && (!expression || auNavExpression === expression)
            ) {
                auSelectedImages.clear();
                auUpdateAnalyzeBtn();
                auUpdateUploadBtn();
                refreshes.push(
                    auRenderImages(auNavCharacter, auNavOutfit, auNavExpression),
                );
            }
            if (
                typeof assetNavLevel !== 'undefined'
                && assetNavLevel === 2
                && assetNavCharacter === character
                && (!outfit || assetNavOutfit === outfit)
                && (!expression || assetNavExpression === expression)
            ) {
                refreshes.push(loadAssetImages());
            }
            if (refreshes.length === 0) return;
            await Promise.all(refreshes);
        }

