        function auUpdateUploadBtn() {
            // 버튼은 항상 활성화 - 모달에서 레벨 체크
        }

        // ─── 업로드 모달 ─────────────────────────────────────────
        let auModalFiles = [];
        let auModalFileSettings = []; // [{ outfit: '', expression: '' }, ...]
        let auModalOutfitRules = [];
        let auModalExprRules = [];

        // 정제 규칙 액션 (오토매치와 동일)
        const AU_CLEAN_ACTIONS = [
            { value: 'split_by', label: '구분자로 분리', params: ['separator', 'take'] },
            { value: 'strip_suffix', label: '접미사 제거', params: ['pattern'] },
            { value: 'strip_prefix', label: '접두사 제거', params: ['pattern'] },
            { value: 'replace', label: '치환', params: ['from', 'to'] },
            { value: 'strip', label: '공백 제거', params: [] },
            { value: 'lower', label: '소문자화', params: [] },
        ];

        const AU_DEFAULT_RULES = {
            outfit: [
                { action: 'strip_suffix', pattern: '\\.(webp|png|jpg|jpeg|gif|bmp)$' },
            ],
            expr: [
                { action: 'strip_suffix', pattern: '\\.(webp|png|jpg|jpeg|gif|bmp)$' },
            ],
        };

        function auApplyCleanSteps(filename, steps) {
            let result = filename;
            for (const step of steps) {
                if (!step.action) continue;
                try {
                    switch (step.action) {
                        case 'split_by': {
                            const sep = step.separator || '_';
                            const parts = result.split(sep).filter(p => p !== '');
                            const take = step.take;
                            if (typeof take === 'number') {
                                result = take < 0 ? (parts[parts.length + take] || '') : (parts[take] || '');
                            } else if (typeof take === 'string' && take.includes(':')) {
                                const [startStr, endStr] = take.split(':').map(s => s.trim());
                                const s = startStr ? parseInt(startStr) - 1 : 0;
                                const e = endStr ? parseInt(endStr) : parts.length;
                                result = parts.slice(Math.max(0, s), Math.min(parts.length, e)).join(sep);
                            } else {
                                result = parts[0] || '';
                            }
                            break;
                        }
                        case 'strip_suffix': {
                            const re = new RegExp(step.pattern + '$');
                            result = result.replace(re, '');
                            break;
                        }
                        case 'strip_prefix': {
                            const re = new RegExp('^' + step.pattern);
                            result = result.replace(re, '');
                            break;
                        }
                        case 'replace': {
                            result = result.replaceAll(step.from || '', step.to !== undefined ? step.to : ' ');
                            break;
                        }
                        case 'strip': {
                            result = result.trim();
                            break;
                        }
                        case 'lower': {
                            result = result.toLowerCase();
                            break;
                        }
                    }
                } catch (e) {
                    console.warn('[AU] 정제 규칙 적용 오류:', step.action, e);
                }
            }
            return result.trim();
        }

        function auRenderRuleSteps(steps, field) {
            const container = document.getElementById(`au-modal-${field}-rules-container`);
            if (!container) return;
            container.innerHTML = '';
            for (let i = 0; i < Math.max(steps.length, 1); i++) {
                const step = steps[i] || {};
                const row = document.createElement('div');
                row.style.cssText = 'display:flex; gap:6px; align-items:center; margin-bottom:6px; flex-wrap:wrap;';

                const num = document.createElement('span');
                num.textContent = `${i + 1}.`;
                num.style.cssText = 'font-weight:600; font-size:0.78rem; min-width:20px;';
                row.appendChild(num);

                const actionSel = document.createElement('select');
                actionSel.style.cssText = 'padding:3px 6px; border-radius:5px; border:1px solid var(--border); background:var(--surface); color:var(--text); font-size:0.78rem; min-width:120px;';
                actionSel.innerHTML = '<option value="">(없음)</option>' + AU_CLEAN_ACTIONS.map(a =>
                    `<option value="${a.value}" ${step.action === a.value ? 'selected' : ''}>${a.label}</option>`
                ).join('');
                actionSel.onchange = () => { auOnRuleStepChange(i, field); };
                row.appendChild(actionSel);

                if (step.action === 'split_by') {
                    const sepIn = document.createElement('input');
                    sepIn.type = 'text'; sepIn.value = step.separator || '_'; sepIn.placeholder = '구분자';
                    sepIn.style.cssText = 'width:45px; padding:3px 5px; border-radius:5px; border:1px solid var(--border); background:var(--surface); color:var(--text); font-size:0.78rem; text-align:center;';
                    sepIn.id = `au-rule-${field}-${i}-separator`;
                    row.appendChild(sepIn);
                    const takeIn = document.createElement('input');
                    takeIn.type = 'text'; takeIn.value = step.take !== undefined ? String(step.take) : '-1'; takeIn.placeholder = '위치';
                    takeIn.style.cssText = 'width:60px; padding:3px 5px; border-radius:5px; border:1px solid var(--border); background:var(--surface); color:var(--text); font-size:0.78rem;';
                    takeIn.id = `au-rule-${field}-${i}-take`;
                    row.appendChild(takeIn);
                } else if (step.action === 'strip_suffix' || step.action === 'strip_prefix') {
                    const patIn = document.createElement('input');
                    patIn.type = 'text'; patIn.value = step.pattern || ''; patIn.placeholder = '정규식 패턴';
                    patIn.style.cssText = 'width:150px; padding:3px 5px; border-radius:5px; border:1px solid var(--border); background:var(--surface); color:var(--text); font-size:0.78rem;';
                    patIn.id = `au-rule-${field}-${i}-pattern`;
                    row.appendChild(patIn);
                } else if (step.action === 'replace') {
                    const fromIn = document.createElement('input');
                    fromIn.type = 'text'; fromIn.value = step.from || ''; fromIn.placeholder = '찾을 문자';
                    fromIn.style.cssText = 'width:55px; padding:3px 5px; border-radius:5px; border:1px solid var(--border); background:var(--surface); color:var(--text); font-size:0.78rem; text-align:center;';
                    fromIn.id = `au-rule-${field}-${i}-from`;
                    row.appendChild(fromIn);
                    const arrow = document.createElement('span');
                    arrow.textContent = '→'; arrow.style.cssText = 'font-size:0.78rem;';
                    row.appendChild(arrow);
                    const toIn = document.createElement('input');
                    toIn.type = 'text'; toIn.value = step.to !== undefined ? step.to : ' '; toIn.placeholder = '바꿀 문자';
                    toIn.style.cssText = 'width:55px; padding:3px 5px; border-radius:5px; border:1px solid var(--border); background:var(--surface); color:var(--text); font-size:0.78rem; text-align:center;';
                    toIn.id = `au-rule-${field}-${i}-to`;
                    row.appendChild(toIn);
                }

                const rmBtn = document.createElement('button');
                rmBtn.textContent = '✕';
                rmBtn.style.cssText = 'border:none; background:transparent; color:var(--error); cursor:pointer; font-size:0.85rem; padding:2px 4px;';
                rmBtn.onclick = () => { auRemoveRuleStep(i, field); };
                row.appendChild(rmBtn);

                container.appendChild(row);
            }
        }

        function auReadRuleStepsFromUI(field) {
            const steps = [];
            const container = document.getElementById(`au-modal-${field}-rules-container`);
            if (!container) return steps;
            const rows = container.querySelectorAll(':scope > div');
            rows.forEach((row, i) => {
                const actionSel = row.querySelector('select');
                if (!actionSel || !actionSel.value) return;
                const step = { action: actionSel.value };
                if (step.action === 'split_by') {
                    const sepEl = document.getElementById(`au-rule-${field}-${i}-separator`);
                    const takeEl = document.getElementById(`au-rule-${field}-${i}-take`);
                    step.separator = sepEl ? sepEl.value : '_';
                    const takeVal = takeEl ? takeEl.value.trim() : '-1';
                    step.take = takeVal.match(/^-?\d+$/) ? parseInt(takeVal) : takeVal;
                } else if (step.action === 'strip_suffix' || step.action === 'strip_prefix') {
                    const patEl = document.getElementById(`au-rule-${field}-${i}-pattern`);
                    step.pattern = patEl ? patEl.value : '';
                } else if (step.action === 'replace') {
                    const fromEl = document.getElementById(`au-rule-${field}-${i}-from`);
                    const toEl = document.getElementById(`au-rule-${field}-${i}-to`);
                    step.from = fromEl ? fromEl.value : '';
                    step.to = toEl ? toEl.value : ' ';
                }
                steps.push(step);
            });
            return steps;
        }

        function auOnRuleStepChange(stepIndex, field) {
            const steps = auReadRuleStepsFromUI(field);
            if (field === 'outfit') auModalOutfitRules = steps;
            else auModalExprRules = steps;
            auRenderRuleSteps(steps, field);
            auApplyGlobalSettings();
            const container = document.getElementById(`au-modal-${field}-rules-container`);
            const rows = container.querySelectorAll(':scope > div');
            if (rows[stepIndex]) {
                const sel = rows[stepIndex].querySelector('select');
                if (sel) sel.focus();
            }
        }

        function auAddRuleStep(field) {
            const steps = auReadRuleStepsFromUI(field);
            steps.push({ action: 'replace', from: '_', to: ' ' });
            if (field === 'outfit') auModalOutfitRules = steps;
            else auModalExprRules = steps;
            auRenderRuleSteps(steps, field);
        }

        function auRemoveRuleStep(index, field) {
            const steps = auReadRuleStepsFromUI(field);
            steps.splice(index, 1);
            if (field === 'outfit') auModalOutfitRules = steps;
            else auModalExprRules = steps;
            auRenderRuleSteps(steps, field);
            auApplyGlobalSettings();
        }

        function auResetRules(field) {
            const defaults = JSON.parse(JSON.stringify(AU_DEFAULT_RULES[field] || []));
            if (field === 'outfit') auModalOutfitRules = defaults;
            else auModalExprRules = defaults;
            auRenderRuleSteps(defaults, field);
            auApplyGlobalSettings();
        }

        function auToggleMode(field) {
            const mode = document.getElementById(`au-modal-${field}-mode`).value;
            const directEl = document.getElementById(`au-modal-${field}-direct`);
            const ruleEl = document.getElementById(`au-modal-${field}-rule`);
            directEl.style.display = mode === 'direct' ? 'block' : 'none';
            ruleEl.style.display = mode === 'rule' ? 'block' : 'none';
            auApplyGlobalSettings();
        }

        function auApplyGlobalSettings() {
            if (auModalFiles.length === 0) return;
            const outfitMode = document.getElementById('au-modal-outfit-mode').value;
            const exprMode = document.getElementById('au-modal-expr-mode').value;

            const outfitSteps = auReadRuleStepsFromUI('outfit');
            auModalOutfitRules = outfitSteps;
            const exprSteps = auReadRuleStepsFromUI('expr');
            auModalExprRules = exprSteps;

            const directOutfit = document.getElementById('au-modal-outfit-direct-input').value;
            const directExpr = document.getElementById('au-modal-expr-direct-input').value;

            for (let i = 0; i < auModalFiles.length; i++) {
                const fname = auModalFiles[i].name;
                if (outfitMode === 'rule') {
                    auModalFileSettings[i].outfit = auApplyCleanSteps(fname, outfitSteps);
                } else {
                    auModalFileSettings[i].outfit = directOutfit;
                }
                if (exprMode === 'rule') {
                    auModalFileSettings[i].expression = auApplyCleanSteps(fname, exprSteps);
                } else {
                    auModalFileSettings[i].expression = directExpr;
                }
            }
            auRenderModalFileList();
        }

        function auOpenUploadModal() {
            if (auNavLevel < 1 || !auNavCharacter) {
                showToast('캐릭터 폴더로 먼저 들어가세요', 'warning');
                return;
            }

            const modal = document.getElementById('au-upload-modal');
            modal.classList.add('visible');

            // 캐릭터명 표시
            document.getElementById('au-modal-character').textContent = auNavCharacter;

            // 글로벌 설정 초기화
            auModalFiles = [];
            auModalFileSettings = [];
            auModalOutfitRules = JSON.parse(JSON.stringify(AU_DEFAULT_RULES.outfit));
            auModalExprRules = JSON.parse(JSON.stringify(AU_DEFAULT_RULES.expr));

            document.getElementById('au-modal-outfit-mode').value = 'rule';
            document.getElementById('au-modal-expr-mode').value = 'rule';
            document.getElementById('au-modal-outfit-direct').style.display = 'none';
            document.getElementById('au-modal-outfit-rule').style.display = 'block';
            document.getElementById('au-modal-expr-direct').style.display = 'none';
            document.getElementById('au-modal-expr-rule').style.display = 'block';
            document.getElementById('au-modal-outfit-direct-input').value = '';
            document.getElementById('au-modal-expr-direct-input').value = '';

            auRenderRuleSteps(auModalOutfitRules, 'outfit');
            auRenderRuleSteps(auModalExprRules, 'expr');

            auRenderModalFileList();
            document.getElementById('au-modal-upload-status').style.display = 'none';

            // 드롭존 이벤트 (중복 방지)
            const dropzone = document.getElementById('au-modal-dropzone');
            const fileInput = document.getElementById('au-modal-file-input');
            dropzone.onclick = () => fileInput.click();
            dropzone.ondragover = (e) => { e.preventDefault(); dropzone.style.borderColor = 'var(--accent)'; dropzone.style.background = 'rgba(255,152,0,0.08)'; };
            dropzone.ondragleave = () => { dropzone.style.borderColor = ''; dropzone.style.background = ''; };
            dropzone.ondrop = (e) => {
                e.preventDefault();
                dropzone.style.borderColor = '';
                dropzone.style.background = '';
                if (e.dataTransfer.files.length) auAddModalFiles(e.dataTransfer.files);
            };
            fileInput.onchange = () => { if (fileInput.files.length) auAddModalFiles(fileInput.files); fileInput.value = ''; };
        }

        function auCloseUploadModal() {
            document.getElementById('au-upload-modal').classList.remove('visible');
            auModalFiles = [];
            auModalFileSettings = [];
            document.getElementById('au-modal-file-input').value = '';
        }

        function auAddModalFiles(fileList) {
            for (const f of fileList) {
                if (!f.type.startsWith('image/')) continue;
                auModalFiles.push(f);
                auModalFileSettings.push({ outfit: '', expression: '' });
            }
            auApplyGlobalSettings();
        }

        function auRemoveModalFile(index) {
            auModalFiles.splice(index, 1);
            auModalFileSettings.splice(index, 1);
            auRenderModalFileList();
        }

        function auOnFileSettingChange(index, field, value) {
            auModalFileSettings[index][field] = value;
            auUpdateUploadBtnState();
        }

        function auUpdateUploadBtnState() {
            const btn = document.getElementById('au-modal-upload-btn');
            if (auModalFiles.length === 0) { btn.disabled = true; return; }
            const allValid = auModalFileSettings.every(s => s.outfit && s.expression);
            btn.disabled = !allValid;
        }

        function auRenderModalFileList() {
            const listEl = document.getElementById('au-modal-file-list');
            const inputStyle = 'padding:3px 6px; border-radius:5px; border:1px solid var(--border); background:var(--surface); color:var(--text); font-size:0.78rem; width:120px; box-sizing:border-box;';

            if (auModalFiles.length === 0) {
                listEl.innerHTML = '';
                auUpdateUploadBtnState();
                return;
            }

            listEl.innerHTML = `<div style="display:grid; grid-template-columns:1fr 130px 130px 30px; gap:6px; align-items:center; padding:4px 0; font-size:0.75rem; color:var(--text2); border-bottom:2px solid var(--border); font-weight:600;">
                <span>파일명</span><span>복장</span><span>표정</span><span></span>
            </div>` + auModalFiles.map((f, i) => {
                const s = auModalFileSettings[i] || { outfit: '', expression: '' };
                return `<div style="display:grid; grid-template-columns:1fr 130px 130px 30px; gap:6px; align-items:center; padding:3px 0; font-size:0.78rem; border-bottom:1px solid var(--border);">
                    <span style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" title="${escapeHtml(f.name)}">${escapeHtml(f.name)} <span style="color:var(--text-secondary);">(${(f.size/1024).toFixed(0)}KB)</span></span>
                    <input type="text" value="${escapeHtml(s.outfit)}" onchange="auOnFileSettingChange(${i},'outfit',this.value)" style="${inputStyle}">
                    <input type="text" value="${escapeHtml(s.expression)}" onchange="auOnFileSettingChange(${i},'expression',this.value)" style="${inputStyle}">
                    <button onclick="auRemoveModalFile(${i})" style="background:none; border:none; color:var(--error); cursor:pointer; font-size:0.9rem; padding:0 4px;">✕</button>
                </div>`;
            }).join('');

            auUpdateUploadBtnState();
        }

        async function auDoUpload() {
            if (auModalFiles.length === 0) return;
            // 모든 파일에 outfit/expression이 있는지 확인
            const missing = auModalFileSettings.some(s => !s.outfit || !s.expression);
            if (missing) {
                showToast('모든 파일의 복장/표정을 입력해주세요', 'warning');
                return;
            }

            const statusEl = document.getElementById('au-modal-upload-status');
            const btn = document.getElementById('au-modal-upload-btn');
            statusEl.style.display = 'block';
            btn.disabled = true;

            let done = 0, failCount = 0;
            for (let idx = 0; idx < auModalFiles.length; idx++) {
                const file = auModalFiles[idx];
                const { outfit, expression } = auModalFileSettings[idx];
                statusEl.textContent = `업로드 중... (${done + 1}/${auModalFiles.length})`;
                try {
                    const formData = new FormData();
                    formData.append('image', file);
                    formData.append('character', auNavCharacter);
                    formData.append('outfit', outfit);
                    formData.append('expression', expression);
                    const resp = await fetch('/api/asset_mode/upload_image', { method: 'POST', body: formData });
                    const result = await resp.json();
                    if (!result.success) {
                        console.warn('[AU] 업로드 실패:', file.name, result.error);
                        failCount++;
                    }
                } catch (e) {
                    console.error('[AU] 업로드 오류:', e);
                    failCount++;
                }
                done++;
            }

            showToast(`${done - failCount}장 업로드 완료`, failCount > 0 ? 'warning' : 'success');
            auCloseUploadModal();

            // 현재 뷰 갱신
            const enc = encodeURIComponent;
            if (auNavLevel === 2 && auNavOutfit && auNavExpression) {
                await auRenderImages(enc(auNavCharacter), enc(auNavOutfit), enc(auNavExpression));
            } else if (auNavLevel === 1) {
                await auRenderGallery(auNavCharacter);
            }
        }

        // ─── 에셋 업로드 탭 끝 ─────────────────────────────────────

        function renderAssetMainArea() {
            if (assetNavLevel === 0) renderCharacterFolders();
            else if (assetNavLevel === 1) renderCharacterGallery(assetNavCharacter);
            else if (assetNavLevel === 2) loadAssetImages();
        }

        function showAssetView(view) {
            // view: 'empty' | 'folder' | 'gallery' | 'grid' | 'loading'
            document.getElementById('asset-loading').style.display = view === 'loading' ? 'flex' : 'none';
            document.getElementById('asset-empty-state').style.display = view === 'empty' ? 'block' : 'none';
            document.getElementById('asset-folder-grid').style.display = view === 'folder' ? 'grid' : 'none';
            document.getElementById('asset-gallery-grid').style.display = view === 'gallery' ? 'grid' : 'none';
            document.getElementById('asset-image-grid').style.display = view === 'grid' ? 'grid' : 'none';
        }

        function renderCharacterFolders(updateBreadcrumb = true) {
            const main = document.getElementById('asset-main');
            const savedScroll = assetNavLevel === 0 && main ? main.scrollTop : 0;
            assetNavLevel = 0;
            assetNavCharacter = '';
            assetNavOutfit = '';
            assetNavExpression = '';
            if (updateBreadcrumb) updateAssetBreadcrumb();

            const chars = Object.keys(assetTags?.characters || {});
            if (chars.length === 0) {
                showAssetView('empty');
                const empty = document.getElementById('asset-empty-state');
                empty.querySelector('h3').textContent = '에셋 생성 모드';
                empty.querySelector('p').textContent = '사이드바에서 캐릭터를 추가한 후 이미지를 생성하세요.';
                return;
            }

            const grid = document.getElementById('asset-folder-grid');
            grid.innerHTML = '';

            const query = assetCharacterSearchQuery.trim().toLocaleLowerCase();
            const filtered = chars.filter(name => {
                const group = assetTags.characters[name].group || '';
                const matchesGroup = !assetCharacterGroupFilter
                    || (assetCharacterGroupFilter === 'ungrouped' && !group)
                    || assetCharacterGroupFilter === `group:${group}`;
                return matchesGroup && (!query || name.toLocaleLowerCase().includes(query));
            });
            filtered.forEach(name => {
                grid.appendChild(createFolderCard(name));
            });
            if (!filtered.length) {
                const empty = document.createElement('div');
                empty.className = 'character-search-empty asset-gallery-search-empty';
                empty.style.display = 'block';
                empty.textContent = '검색 결과가 없습니다.';
                grid.appendChild(empty);
            }

            showAssetView('folder');
            if (main) main.scrollTop = savedScroll;
        }

        function createFolderCard(name) {
            const card = document.createElement('div');
            card.className = 'asset-folder-card';

            const icon = document.createElement('div');
            icon.className = 'folder-icon';
            icon.textContent = '📁';

            const nameEl = document.createElement('div');
            nameEl.className = 'folder-name';
            nameEl.textContent = name;

            card.appendChild(icon);
            card.appendChild(nameEl);

            const groupLabel = document.createElement('label');
            groupLabel.className = 'asset-folder-group';
            groupLabel.textContent = '그룹';
            groupLabel.onclick = event => event.stopPropagation();
            const groupSelect = document.createElement('select');
            groupSelect.setAttribute('aria-label', `${name} 그룹`);
            groupSelect.add(new Option('미지정', ''));
            const groups = [...new Set(Object.values(assetTags.characters)
                .map(character => character.group || '').filter(Boolean))]
                .sort((left, right) => left.localeCompare(right));
            groups.forEach(group => groupSelect.add(new Option(group, `group:${group}`)));
            groupSelect.add(new Option('＋ 그룹 추가', 'add'));
            const currentGroup = assetTags.characters[name].group || '';
            groupSelect.value = currentGroup ? `group:${currentGroup}` : '';
            groupSelect.onchange = async () => {
                if (groupSelect.value === 'add') {
                    const savedGroup = assetTags.characters[name]?.group || '';
                    groupSelect.value = savedGroup ? `group:${savedGroup}` : '';
                    openBotNameModal({
                        title: '그룹 추가',
                        placeholder: '그룹명',
                        nameLabel: '그룹명',
                        confirmText: '추가',
                        hint: '',
                        validateName: value => value.trim() ? '' : '그룹명을 입력하세요.',
                        onConfirm: async group => {
                            groupSelect.disabled = true;
                            try {
                                await assetTagAction('update_character', { name, group: group.trim() });
                            } finally {
                                groupSelect.disabled = false;
                            }
                        },
                    });
                    return;
                }
                const group = groupSelect.value ? groupSelect.value.slice(6) : '';
                if (group === (assetTags.characters[name].group || '')) return;
                groupSelect.disabled = true;
                try {
                    await assetTagAction('update_character', { name, group });
                } finally {
                    const savedGroup = assetTags.characters[name]?.group || '';
                    groupSelect.value = savedGroup ? `group:${savedGroup}` : '';
                    groupSelect.disabled = false;
                }
            };
            groupLabel.appendChild(groupSelect);
            card.appendChild(groupLabel);

            card.onclick = () => {
                navigateToCharacterGallery(name);
            };

            return card;
        }

        async function navigateToCharacterGallery(charName) {
            assetNavLevel = 1;
            assetNavCharacter = charName;
            assetNavOutfit = '';
            assetNavExpression = '';
            // 사이드바 셀렉트 동기화
            document.getElementById('asset-character-select').value = charName;
            onAssetCharacterChange(true);
            updateAssetBreadcrumb();
            await renderCharacterGallery(charName);
        }

        async function renderCharacterGallery(charName) {
            if (assetNavLevel !== 1 || assetNavCharacter !== charName) {
                console.log('[ASSET] 이동한 갤러리의 갱신을 건너뜁니다:', charName);
                return;
            }
            const requestId = renderCharacterGallery.requestId = (renderCharacterGallery.requestId || 0) + 1;
            const main = document.getElementById('asset-main');
            const grid = document.getElementById('asset-gallery-grid');
            const sameView = grid.dataset.character === charName && grid.style.display === 'grid';
            // Keep the current scroll range available while a refresh is pending.
            if (!sameView) showAssetView('loading');
            try {
                const enc = encodeURIComponent;
                const resp = await fetch(`/api/asset_mode/characters/${enc(charName)}/gallery`);
                const data = await resp.json();
                if (requestId !== renderCharacterGallery.requestId || assetNavLevel !== 1 || assetNavCharacter !== charName) {
                    console.log('[ASSET] 이전 갤러리 요청 응답을 건너뜁니다:', charName, requestId);
                    return;
                }
                const items = data.gallery || [];
                const outfitGroups = data.outfit_groups || {};

                if (items.length === 0) {
                    showAssetView('empty');
                    const empty = document.getElementById('asset-empty-state');
                    empty.querySelector('h3').textContent = escapeHtml(charName);
                    empty.querySelector('p').textContent = '복장과 표정을 추가한 후 이미지를 생성하세요.';
                    return;
                }

                const savedScroll = sameView && main ? main.scrollTop : 0;
                grid.innerHTML = '';

                // 아이템 키 맵
                const itemMap = {};
                items.forEach(it => { itemMap[`${it.outfit}::${it.expression}`] = it; });

                // 그룹에 속한 아이템 집합
                const groupedKeys = new Set();
                for (const members of Object.values(outfitGroups)) {
                    members.forEach(m => groupedKeys.add(`${m.outfit}::${m.expression}`));
                }

                // 그룹 카드 생성 헬퍼
                function createGalleryCard(item, inGroup) {
                    const card = document.createElement('div');
                    card.className = 'asset-gallery-card';
                    card.draggable = true;
                    card.dataset.outfit = item.outfit;
                    card.dataset.expression = item.expression;
                    card.dataset.hasRepresentative = item.representative ? 'true' : 'false';
                    card.dataset.modifiedAt = String(Number(item.modified_at) || 0);

                    // 드래그 시작
                    card.addEventListener('dragstart', e => {
                        e.dataTransfer.setData('text/plain', `${item.outfit}::${item.expression}`);
                        e.dataTransfer.effectAllowed = 'move';
                        card.classList.add('gallery-dragging');
                    });
                    card.addEventListener('dragend', () => {
                        card.classList.remove('gallery-dragging');
                        document.querySelectorAll('.gallery-drag-over, .gallery-group-drag-over').forEach(el =>
                            el.classList.remove('gallery-drag-over', 'gallery-group-drag-over'));
                    });

                    // 다른 카드 위에 드롭 → 그룹 생성
                    card.addEventListener('dragover', e => {
                        e.preventDefault();
                        e.dataTransfer.dropEffect = 'move';
                        card.classList.add('gallery-drag-over');
                    });
                    card.addEventListener('dragleave', () => {
                        card.classList.remove('gallery-drag-over');
                    });
                    card.addEventListener('drop', e => {
                        e.preventDefault();
                        card.classList.remove('gallery-drag-over');
                        const srcKey = e.dataTransfer.getData('text/plain');
                        const tgtKey = `${item.outfit}::${item.expression}`;
                        if (!srcKey || srcKey === tgtKey) return;
                        const [srcOutfit, srcExpr] = srcKey.split('::');
                        assetTagAction('set_outfit_group', {
                            character: charName,
                            src_outfit: srcOutfit, src_expression: srcExpr,
                            tgt_outfit: item.outfit, tgt_expression: item.expression
                        }).then(() => renderCharacterGallery(charName));
                    });

                    const enc = encodeURIComponent;
                    let thumbHtml;
                    let thumbUrl = '';
                    let posterUrl = '';
                    if (item.representative) {
                        thumbUrl = `/api/asset_mode/characters/${enc(charName)}/outfits/${enc(item.outfit)}/expressions/${enc(item.expression)}/images/${enc(item.representative)}`;
                        posterUrl = item.representative_is_animated
                            ? `${thumbUrl}/poster`
                            : thumbUrl;
                        const animationAttrs = item.representative_is_animated
                            ? `data-poster-src="${posterUrl}" data-anim-src="${thumbUrl}" onmouseenter="this.src=this.dataset.animSrc" onmouseleave="this.src=this.dataset.posterSrc"`
                            : '';
                        thumbHtml = `
                            ${item.representative_is_animated ? '<span class="source-badge source-anim" title="영상 · 마우스를 올려 재생">A</span>' : ''}
                            <img class="gallery-thumb${item.representative_is_animated ? ' is-anim' : ''}" src="${posterUrl}" loading="lazy" ${animationAttrs}>`;
                    } else {
                        thumbHtml = `<div class="gallery-thumb-placeholder">이미지 없음</div>`;
                    }

                    let removeGroupBtn = '';
                    if (inGroup) {
                        removeGroupBtn = `<button class="gallery-group-remove-btn">×</button>`;
                    }

                    card.innerHTML = `
                        <button class="gallery-delete-btn" onclick="event.stopPropagation(); deleteAssetCombination('${enc(charName)}','${enc(item.outfit)}','${enc(item.expression)}',${item.image_count})">삭제</button>
                        ${removeGroupBtn}
                        ${thumbHtml}
                        <div class="gallery-title">${escapeHtml(item.outfit)} - ${escapeHtml(item.expression)}</div>
                        ${item.image_count > 0 ? `<div class="gallery-count">${item.image_count}장</div>` : ''}
                    `;

                    // 그룹 제거 버튼 이벤트
                    if (inGroup) {
                        const rmBtn = card.querySelector('.gallery-group-remove-btn');
                        if (rmBtn) {
                            rmBtn.addEventListener('click', e => {
                                e.stopPropagation();
                                assetTagAction('ungroup_outfit', {
                                    character: charName,
                                    outfit: item.outfit,
                                    expression: item.expression
                                }).then(() => renderCharacterGallery(charName));
                            });
                        }
                    }

                    card.onclick = (e) => {
                        navigateToImages(charName, item.outfit, item.expression);
                    };

                    return card;
                }

                // 그룹별 연한 랜덤 배경색
                const groupColors = {};
                function getGroupColor(gid) {
                    if (!groupColors[gid]) {
                        const h = Math.floor(Math.random() * 360);
                        groupColors[gid] = `hsla(${h}, 60%, 85%, 0.4)`;
                    }
                    return groupColors[gid];
                }

                // 그룹 렌더링
                for (const [gid, members] of Object.entries(outfitGroups)) {
                    const validMembers = members.filter(m => itemMap[`${m.outfit}::${m.expression}`]);
                    if (validMembers.length === 0) continue;

                    const container = document.createElement('div');
                    container.className = 'gallery-group-container';
                    container.style.backgroundColor = getGroupColor(gid);

                    validMembers.forEach(m => {
                        const it = itemMap[`${m.outfit}::${m.expression}`];
                        container.appendChild(createGalleryCard(it, true));
                    });

                    // 그룹 컨테이너도 드롭 영역
                    container.addEventListener('dragover', e => {
                        e.preventDefault();
                        e.dataTransfer.dropEffect = 'move';
                        container.classList.add('gallery-group-drag-over');
                    });
                    container.addEventListener('dragleave', e => {
                        if (!container.contains(e.relatedTarget)) {
                            container.classList.remove('gallery-group-drag-over');
                        }
                    });
                    container.addEventListener('drop', e => {
                        e.preventDefault();
                        container.classList.remove('gallery-group-drag-over');
                        const srcKey = e.dataTransfer.getData('text/plain');
                        if (!srcKey) return;
                        const tgt = validMembers[0];
                        const tgtKey = `${tgt.outfit}::${tgt.expression}`;
                        if (srcKey === tgtKey) return;
                        const [srcOutfit, srcExpr] = srcKey.split('::');
                        assetTagAction('set_outfit_group', {
                            character: charName,
                            src_outfit: srcOutfit, src_expression: srcExpr,
                            tgt_outfit: tgt.outfit, tgt_expression: tgt.expression
                        }).then(() => renderCharacterGallery(charName));
                    });

                    grid.appendChild(container);
                }

                // 그룹 없는 개별 카드
                items.forEach(it => {
                    const key = `${it.outfit}::${it.expression}`;
                    if (groupedKeys.has(key)) return;
                    grid.appendChild(createGalleryCard(it, false));
                });

                grid.dataset.character = charName;
                showAssetView('gallery');
                applyAssetGalleryControls('asset');
                if (main) main.scrollTop = savedScroll;
                else console.error('[ASSET] LV1 스크롤 복원 실패: asset-main 요소가 없습니다.');
            } catch (e) {
                console.error('[ASSET] 갤러리 로드 실패:', e);
            }
        }

        let _assetScrollCache = {};

        function navigateToImages(charName, outfit, expression) {
            const main = document.getElementById('asset-main');
            if (main) {
                _assetScrollCache[1] = main.scrollTop;
            } else {
                console.error('[ASSET] LV1 스크롤 저장 실패: asset-main 요소가 없습니다.');
                _assetScrollCache[1] = 0;
            }
            const sidebar = document.getElementById('asset-sidebar');
            if (sidebar) _assetScrollCache['sidebar_1'] = sidebar.scrollTop;
            assetNavLevel = 2;
            assetNavCharacter = charName;
            assetNavOutfit = outfit;
            assetNavExpression = expression;
            // 사이드바 동기화
            document.getElementById('asset-character-select').value = charName;
            onAssetCharacterChange(true);
            syncAssetSelectFromDirname('asset-outfit-select', outfit);
            onAssetOutfitChange(true);
            syncAssetSelectFromDirname('asset-expression-select', expression);
            onAssetExpressionChange(true);
            updateAssetBreadcrumb();
            updateGenerateBtn();
            loadAssetImages();
        }

        function syncAssetSelectFromDirname(selectId, dirname) {
            // Python _safe_dirname()과 동일: \p{L}(유니코드 글자) + \p{N}(유니코드 숫자) + 공백/_/-/. 유지
            const re = /[^\p{L}\p{N} _\-\.]/gu;
            const normalizedDirname = dirname == null ? '' : String(dirname);
            const cs = document.querySelector(`.custom-select[data-select-id="${selectId}"]`);
            if (!cs) {
                console.error(`[ASSET] Lv2 선택 동기화 실패: 컨트롤 없음 (${selectId}, dirname=${normalizedDirname})`);
                return false;
            }

            const optionList = cs.querySelector('.custom-select-option-list');
            if (!optionList) {
                console.error(`[ASSET] Lv2 선택 동기화 실패: 옵션 목록 없음 (${selectId}, dirname=${normalizedDirname})`);
                return false;
            }

            if (!normalizedDirname) {
                const previous = getAssetSelectValue(selectId);
                setAssetSelectValue(selectId, '');
                console.error(`[ASSET] Lv2 선택 동기화 실패: 폴더명 비어 있음 (${selectId}, previous=${previous})`);
                return false;
            }

            const options = Array.from(optionList.querySelectorAll('.custom-select-option'));
            let target = options.find(opt => opt.dataset.value === normalizedDirname);

            if (!target) {
                const matches = options.filter(opt => {
                    const value = opt.dataset.value;
                    return value && value.replace(re, '').trim() === normalizedDirname;
                });
                if (matches.length === 1) {
                    target = matches[0];
                } else if (matches.length > 1) {
                    const previous = getAssetSelectValue(selectId);
                    setAssetSelectValue(selectId, '');
                    console.error(
                        `[ASSET] Lv2 선택 동기화 실패: 정리된 폴더명 중복 ` +
                        `(${selectId}, dirname=${normalizedDirname}, previous=${previous}, ` +
                        `candidates=${matches.map(opt => opt.dataset.value).join(' | ')})`
                    );
                    return false;
                }
            }

            if (!target) {
                const previous = getAssetSelectValue(selectId);
                setAssetSelectValue(selectId, '');
                console.error(
                    `[ASSET] Lv2 선택 동기화 실패: 일치 옵션 없음 ` +
                    `(${selectId}, dirname=${normalizedDirname}, previous=${previous})`
                );
                return false;
            }

            if (!setAssetSelectValue(selectId, target.dataset.value)) {
                console.error(
                    `[ASSET] Lv2 선택 동기화 실패: 선택값 적용 실패 ` +
                    `(${selectId}, dirname=${normalizedDirname}, value=${target.dataset.value})`
                );
                return false;
            }
            return true;
        }

        async function navigateAssetBreadcrumb(level) {
            if (level === 0) renderCharacterFolders();
            else if (level === 1) {
                const charName = assetNavCharacter;
                const savedScroll = assetNavLevel === 2 ? _assetScrollCache[1] : undefined;
                assetNavLevel = 1;
                assetNavOutfit = '';
                assetNavExpression = '';
                // 2차→1차 복귀 시 사이드바 스크롤을 즉시(동기적으로) 복원
                const sidebar = document.getElementById('asset-sidebar');
                if (sidebar && _assetScrollCache['sidebar_1'] !== undefined) {
                    sidebar.scrollTop = _assetScrollCache['sidebar_1'];
                    delete _assetScrollCache['sidebar_1'];
                }
                updateAssetBreadcrumb();
                const grid = document.getElementById('asset-gallery-grid');
                if (savedScroll !== undefined && grid.dataset.character === charName) {
                    showAssetView('gallery');
                    const main = document.getElementById('asset-main');
                    if (main) main.scrollTop = savedScroll;
                    else console.error('[ASSET] LV1 복귀 스크롤 복원 실패: asset-main 요소가 없습니다.');
                }
                await renderCharacterGallery(charName);
            }
        }

        function updateAssetBreadcrumb() {
            const bc = document.getElementById('asset-breadcrumb');
            let html = '<span class="bc-link" onclick="navigateAssetBreadcrumb(0)">에셋</span>';

            if (assetNavLevel >= 1 && assetNavCharacter) {
                if (assetNavLevel === 1) {
                    html += `<span class="bc-sep">/</span><span class="bc-active">${escapeHtml(assetNavCharacter)}</span>`;
                } else {
                    html += `<span class="bc-sep">/</span><span class="bc-link" onclick="navigateAssetBreadcrumb(1)">${escapeHtml(assetNavCharacter)}</span>`;
                }
            }
            if (assetNavLevel >= 2 && assetNavOutfit && assetNavExpression) {
                html += `<span class="bc-sep">/</span><span class="bc-active">${escapeHtml(assetNavOutfit)}-${escapeHtml(assetNavExpression)}</span>`;
            }
            if (assetNavLevel === 1 && assetNavCharacter) {
                html += buildAssetGalleryControls('asset');
            }
            bc.innerHTML = html;
            if (assetNavLevel === 0) {
                const groups = [...new Set(Object.values(assetTags?.characters || {})
                    .map(character => character.group || '').filter(Boolean))]
                    .sort((left, right) => left.localeCompare(right));
                const controls = document.createElement('div');
                controls.className = 'asset-gallery-controls';
                const select = document.createElement('select');
                select.id = 'asset-character-group-filter';
                select.className = 'asset-gallery-sort';
                select.setAttribute('aria-label', '캐릭터 그룹 필터');
                select.add(new Option('전체 그룹', ''));
                select.add(new Option('미지정', 'ungrouped'));
                groups.forEach(group => {
                    select.add(new Option(group, `group:${group}`));
                });
                if (assetCharacterGroupFilter.startsWith('group:')
                    && !groups.includes(assetCharacterGroupFilter.slice(6))) {
                    assetCharacterGroupFilter = '';
                }
                select.value = assetCharacterGroupFilter;
                select.onchange = () => {
                    assetCharacterGroupFilter = select.value;
                    renderCharacterFolders(false);
                };
                const search = document.createElement('input');
                search.id = 'asset-character-search';
                search.className = 'breadcrumb-character-search';
                search.type = 'search';
                search.autocomplete = 'off';
                search.placeholder = '캐릭터 검색';
                search.setAttribute('aria-label', '에셋 캐릭터 검색');
                search.value = assetCharacterSearchQuery;
                search.oninput = () => {
                    assetCharacterSearchQuery = search.value;
                    renderCharacterFolders(false);
                };
                controls.append(select, search);
                bc.appendChild(controls);
            }
            if (assetNavLevel === 1 && assetNavCharacter) {
                restoreAssetGallerySearchValue('asset');
            }
        }

        function updateGenerateBtn() {
            const char = document.getElementById('asset-character-select').value;
            const app = getAssetSelectValue('asset-appearance-select');
            const outfit = getAssetSelectValue('asset-outfit-select');
            const expr = getAssetSelectValue('asset-expression-select');
            const btn = document.getElementById('asset-generate-btn');
            const missing = !char || !app || !outfit || !expr;
            btn.classList.toggle('is-disabled', missing);
            btn.dataset.missing = [!char && '캐릭터', !app && '외형', !outfit && '의상', !expr && '표정'].filter(Boolean).join(', ');
        }

        // ─── 에셋 생성 큐 관리 ────────────────────────────────────
        function addQueueItem(label, requestBody) {
            const id = ++assetQueueCounter;
            assetQueue.push({
                id: id,
                label: label,
                requestBody: requestBody,
                status: 'pending',
                progress: 0,
                progressMax: 100,
                startTime: null,
                endTime: null,
                errorMsg: '',
                autoHideAt: null,
            });
            renderAssetQueueUI();
            return assetQueue[assetQueue.length - 1];
        }

        const removingQueueItems = new Set();
        function removeQueueItem(id) {
            if (removingQueueItems.has(id)) return;
            cancelAutoHide(id);
            const el = document.querySelector('[data-queue-item-id="' + id + '"]');
            if (el) {
                removingQueueItems.add(id);
                // FLIP: 기존 위치 기록
                const positions = {};
                el.parentNode.querySelectorAll('.asset-queue-item').forEach(item => {
                    const itemId = item.dataset.queueItemId;
                    if (itemId) positions[itemId] = item.getBoundingClientRect().top;
                });
                // 종료 애니메이션: 오른쪽으로 슬라이드 + 페이드아웃
                el.style.transition = 'transform 0.3s ease, opacity 0.3s ease';
                el.style.transform = 'translateX(80px)';
                el.style.opacity = '0';
                setTimeout(() => {
                    removingQueueItems.delete(id);
                    assetQueue = assetQueue.filter(q => q.id !== id);
                    renderAssetQueueUI();
                    // FLIP: 아래 항목들이 부드럽게 올라오도록 애니메이션
                    document.querySelectorAll('.asset-queue-item').forEach(item => {
                        const itemId = item.dataset.queueItemId;
                        if (positions[itemId] !== undefined) {
                            const delta = positions[itemId] - item.getBoundingClientRect().top;
                            if (Math.abs(delta) > 1) {
                                item.style.transition = 'none';
                                item.style.transform = 'translateY(' + delta + 'px)';
                                item.offsetHeight;
                                item.style.transition = 'transform 0.3s ease, background 0.15s';
                                item.style.transform = '';
                            }
                        }
                    });
                    if (assetQueue.length === 0) {
                        document.getElementById('asset-queue-container').style.display = 'none';
                        hideTopProgress();
                        stopCountdownInterval();
                    }
                }, 300);
            } else {
                assetQueue = assetQueue.filter(q => q.id !== id);
                renderAssetQueueUI();
                if (assetQueue.length === 0) {
                    document.getElementById('asset-queue-container').style.display = 'none';
                    hideTopProgress();
                    stopCountdownInterval();
                }
            }
        }

        const autoHideTimers = {};
        let countdownInterval = null;

        // 큐 항목 제거 애니메이션 (슬라이드 아웃 + FLIP 슬라이드 업)
        function animateQueueRemovals(items) {
            return new Promise(resolve => {
                if (items.length === 0) { resolve(); return; }
                for (const item of items) removingQueueItems.add(item.id);
                const positions = {};
                const panelBody = document.getElementById('asset-queue-panel-body');
                panelBody.querySelectorAll('.asset-queue-item').forEach(el => {
                    const itemId = el.dataset.queueItemId;
                    if (itemId) positions[itemId] = el.getBoundingClientRect().top;
                });
                for (const item of items) {
                    cancelAutoHide(item.id);
                    const el = document.querySelector('[data-queue-item-id="' + item.id + '"]');
                    if (el) {
                        el.style.transition = 'transform 0.3s ease, opacity 0.3s ease';
                        el.style.transform = 'translateX(80px)';
                        el.style.opacity = '0';
                    }
                }
                setTimeout(() => {
                    for (const item of items) {
                        removingQueueItems.delete(item.id);
                        const idx = assetQueue.indexOf(item);
                        if (idx >= 0) assetQueue.splice(idx, 1);
                    }
                    renderAssetQueueUI();
                    document.querySelectorAll('.asset-queue-item').forEach(el => {
                        const itemId = el.dataset.queueItemId;
                        if (positions[itemId] !== undefined) {
                            const delta = positions[itemId] - el.getBoundingClientRect().top;
                            if (Math.abs(delta) > 1) {
                                el.style.transition = 'none';
                                el.style.transform = 'translateY(' + delta + 'px)';
                                el.offsetHeight;
                                el.style.transition = 'transform 0.3s ease, background 0.15s';
                                el.style.transform = '';
                            }
                        }
                    });
                    if (assetQueue.length === 0) {
                        document.getElementById('asset-queue-container').style.display = 'none';
                        hideTopProgress();
                        stopCountdownInterval();
                    }
                    resolve();
                }, 300);
            });
        }
        function scheduleAutoHide(id, delayMs) {
            if (autoHideTimers[id]) clearTimeout(autoHideTimers[id]);
            const item = assetQueue.find(q => q.id === id);
            if (item) item.autoHideAt = Date.now() + delayMs;
            autoHideTimers[id] = setTimeout(() => {
                delete autoHideTimers[id];
                if (item) item.autoHideAt = null;
                removeQueueItem(id);
            }, delayMs);
            startCountdownInterval();
        }
        function cancelAutoHide(id) {
            if (autoHideTimers[id]) {
                clearTimeout(autoHideTimers[id]);
                delete autoHideTimers[id];
            }
            const item = assetQueue.find(q => q.id === id);
            if (item) item.autoHideAt = null;
        }
        function startCountdownInterval() {
            if (countdownInterval) return;
            countdownInterval = setInterval(updateCountdowns, 1000);
        }
        function stopCountdownInterval() {
            if (countdownInterval) {
                clearInterval(countdownInterval);
                countdownInterval = null;
            }
        }
        function updateCountdowns() {
            const hasAnyCountdown = assetQueue.some(q => q.autoHideAt !== null);
            if (!hasAnyCountdown) {
                stopCountdownInterval();
                return;
            }
            assetQueue.forEach(item => {
                if (item.autoHideAt !== null) {
                    const remaining = Math.max(0, Math.ceil((item.autoHideAt - Date.now()) / 1000));
                    const el = document.querySelector('[data-queue-item-id="' + item.id + '"] .item-countdown');
                    if (el) el.textContent = remaining + 's';
                }
            });
        }

        function renderAssetQueueUI() {
            const wait = 200 - (Date.now() - (renderAssetQueueUI.lastRender || 0));
            if (wait > 0) {
                if (!renderAssetQueueUI.timer) renderAssetQueueUI.timer = setTimeout(() => {
                    renderAssetQueueUI.timer = null;
                    renderAssetQueueUI();
                }, wait);
                return;
            }
            if (renderAssetQueueUI.timer) clearTimeout(renderAssetQueueUI.timer);
            renderAssetQueueUI.timer = null;
            renderAssetQueueUI.lastRender = Date.now();
            const container = document.getElementById('asset-queue-container');
            if (!container) { console.error('[QUEUE] renderAssetQueueUI: asset-queue-container 요소 없음'); return; }
            const processing = assetQueue.find(q => q.status === 'processing');
            const pending = assetQueue.filter(q => q.status === 'pending' || q.status === 'waiting');
            const history = _queueHistoryItems(assetQueue);
            const failedCount = history.filter(item => item.status === 'failed').length;
            const hasActive = processing || pending.length > 0;
            const wallTab = document.getElementById('asset-queue-wall-tab');
            const wallTabCount = document.getElementById('queue-wall-tab-count');
            if (!wallTab || !wallTabCount) {
                console.error('[QUEUE] renderAssetQueueUI: 좌측 벽 큐 탭 요소 누락', {
                    wallTab: !!wallTab, wallTabCount: !!wallTabCount,
                });
            } else {
                const activeCount = pending.length + (processing ? 1 : 0);
                wallTabCount.textContent = failedCount ? `!${failedCount}` : hasActive ? String(activeCount) : '✓';
                const wallTabLabel = hasActive
                    ? `작업 큐 펼치기, 처리 또는 대기 ${activeCount}개`
                    : failedCount ? `작업 큐 펼치기, 실패 ${failedCount}개` : '작업 큐 펼치기, 모든 작업 완료';
                wallTab.setAttribute('aria-label', wallTabLabel);
                wallTab.title = wallTabLabel;
            }

            container.style.display = assetQueue.length > 0 ? 'flex' : 'none';
            setAssetQueuePanelExpanded(assetQueueExpanded);

            // ─── 타입별 아이콘/색상 ───
            function getTypeStyle(type) {
                switch (type) {
                    case 'illustration': return { icon: '🖼', color: '#e74c3c' };
                    case 'asset_generation': return { icon: '🎨', color: '#3498db' };
                    case 'asset_lora_training': return { icon: '🔶', color: '#e67e22' };
                    case 'bot_lora_training': return { icon: '🟣', color: '#9b59b6' };
                    case 'instance_lora_training': return { icon: '🔵', color: '#1abc9c' };
                    case 'modal_lora_download': return { icon: '⇩', color: '#06b6d4' };
                    case 'vast_lora_download': return { icon: '⇩', color: '#22c55e' };
                    case 'instance_lora_analysis': return { icon: '🔍', color: '#2ecc71' };
                    case 'tag_analysis': return { icon: '🏷', color: '#f39c12' };
                    case 'auto_match_batch': return { icon: '🔗', color: '#16a085' };
                    case 'data_patch_utility': return { icon: '🖼', color: '#1565C0' };
                    default: return { icon: '○', color: 'var(--text2)' };
                }
            }

            // ─── 슬림 바 ───
            const barLabel = document.getElementById('queue-bar-label');
            const barProgressText = document.getElementById('queue-bar-progress-text');
            const barProgressBar = document.getElementById('queue-bar-progress-bar');
            const barWaiting = document.getElementById('queue-bar-waiting');
            const barSpinner = document.getElementById('queue-bar-spinner');
            const barStopBtn = document.getElementById('queue-bar-stop-btn');
            const bar = document.getElementById('asset-queue-bar');
            if (!bar || !barLabel || !barProgressText || !barProgressBar || !barWaiting || !barSpinner || !barStopBtn) {
                console.error('[QUEUE] renderAssetQueueUI: 큐 바 하위 요소 누락', { bar: !!bar, barLabel: !!barLabel, barProgressText: !!barProgressText, barProgressBar: !!barProgressBar, barWaiting: !!barWaiting, barSpinner: !!barSpinner, barStopBtn: !!barStopBtn });
                return;
            }

            if (processing) {
                // 배치 항목이면 배치 단위 진행률 표시(장당 라벨 대신 배치 라벨 + X/Y).
                if (processing.batch_id) {
                    const grp = assetQueue.filter(q => q.batch_id === processing.batch_id);
                    const total = processing.batch_total || grp.length;
                    const pend = grp.filter(q => q.status === 'pending').length;
                    const done = Math.max(0, total - pend - grp.filter(q => q.status === 'processing').length);
                    barLabel.textContent = processing.batch_label || processing.label;
                    barLabel.title = processing.batch_label || processing.label || '';
                    const pct = total > 0 ? Math.round((done / total) * 100) : Math.round(processing.progress || 0);
                    barProgressText.textContent = done + '/' + total;
                    barProgressBar.style.width = pct + '%';
                } else {
                    barLabel.textContent = processing.label;
                    barLabel.title = processing.label || '';
                    const pct = Math.round(processing.progress || 0);
                    barProgressText.textContent = pct + '%';
                    barProgressBar.style.width = pct + '%';
                }
                barSpinner.style.display = 'block';
                barStopBtn.style.display = 'inline-block';
            } else if (pending.length > 0) {
                barLabel.textContent = '다음: ' + (pending[0].batch_label || pending[0].label);
                barLabel.title = pending[0].batch_label || pending[0].label || '';
                barProgressText.textContent = '준비중...';
                barProgressBar.style.width = '0%';
                barSpinner.style.display = 'block';
                barStopBtn.style.display = 'inline-block';
            }

            if (pending.length > 0) {
                barWaiting.style.display = 'inline-block';
                // 배치 단위 대기 표시: 1000장이 "1000 대기"로 도배되지 않게 배치 수+장 수.
                const _batchIds = new Set();
                let _standalone = 0;
                pending.forEach(q => q.batch_id ? _batchIds.add(q.batch_id) : _standalone++);
                barWaiting.textContent = (_batchIds.size > 0)
                    ? `${_batchIds.size}배치 / ${pending.length}장 대기`
                    : (pending.length + ' 대기');
            } else {
                barWaiting.style.display = 'none';
            }

            if (!hasActive) {
                barSpinner.style.display = 'none';
                barStopBtn.style.display = 'none';
                bar.classList.add('all-done');
                if (assetQueue.length > 0) {
                    const cancelledCount = assetQueue.filter(q => q.status === 'cancelled').length;
                    barLabel.textContent = failedCount ? `실패 ${failedCount}개 · 최근 작업 확인` : cancelledCount === assetQueue.length ? '취소됨' : '완료';
                    barLabel.title = '';
                    barProgressText.textContent = '';
                    barProgressBar.style.width = '100%';
                }
            } else {
                bar.classList.remove('all-done');
            }

            // ─── 패널 ───
            if (!assetQueueExpanded) return;
            const panelBody = document.getElementById('asset-queue-panel-body');
            if (!panelBody) { console.error('[QUEUE] renderAssetQueueUI: asset-queue-panel-body 요소 없음'); return; }
            panelBody.innerHTML = '';
            if (history.length) {
                const heading = document.createElement('div');
                heading.className = 'queue-history-heading';
                heading.textContent = '최근 작업 · 최대 10개';
                panelBody.appendChild(heading);
            }
            // 배치 그룹핑: 동일 batch_id 항목을 1줄 요약(대량 항목 DOM 폭주 방지).
            const rendered = new Set();
            [...history, ...assetQueue.filter(item => !_queueItemFinished(item))].forEach(item => {
                if (rendered.has(item.id)) return;
                if (item.batch_id && !_queueItemFinished(item)) {
                    const grp = assetQueue.filter(i => i.batch_id === item.batch_id && !_queueItemFinished(i));
                    grp.forEach(g => rendered.add(g.id));
                    const total = item.batch_total || grp.length;
                    const pend = grp.filter(i => i.status === 'pending').length;
                    const proc = grp.filter(i => i.status === 'processing').length;
                    const done = Math.max(0, total - pend - proc);
                    const ts = getTypeStyle(item.type);
                    const row = document.createElement('div');
                    row.className = 'asset-queue-item item-batch' + (proc ? ' processing' : '');
                    row.dataset.queueItemId = item.id;
                    const icon = proc ? '<span class="queue-spinner" style="width:14px;height:14px;border-width:2px;"></span>' : ts.icon;
                    const statusText = proc ? (done + '/' + total) : (pend > 0 ? (done + '/' + total + ' 대기') : '완료');
                    const pct = total > 0 ? Math.round((done / total) * 100) : 0;
                    const actionBtn = pend > 0
                        ? '<button class="item-dismiss-btn" onclick="event.stopPropagation(); cancelQueueBatchBackend(\'' + item.batch_id + '\');">✕</button>'
                        : '';
                    const labelColor = proc ? ts.color : '';
                    row.innerHTML =
                        '<div class="item-icon">' + icon + '</div>' +
                        '<div class="item-label" style="' + (labelColor ? 'color:' + labelColor : '') + '">' + escapeHtml(item.batch_label || item.label || '배치') + '</div>' +
                        (proc ? '<div class="item-progress-bar"><div class="item-progress-bar-inner" style="width:' + pct + '%"></div></div>' : '') +
                        '<div class="item-status">' + statusText + '</div>' +
                        actionBtn;
                    const _batchLblEl = row.querySelector('.item-label');
                    if (_batchLblEl) _batchLblEl.title = item.batch_label || item.label || '';
                    panelBody.appendChild(row);
                } else {
                    const ts = getTypeStyle(item.type);
                    const row = document.createElement('div');
                    row.className = 'asset-queue-item item-' + item.status;
                    row.dataset.queueItemId = item.id;
                    let icon = '';
                    let statusText = '';
                    switch (item.status) {
                        case 'waiting':
                            statusText = '슬롯 대기';
                        case 'pending':
                            icon = ts.icon; break;
                        case 'processing':
                            icon = '<span class="queue-spinner" style="width:14px;height:14px;border-width:2px;"></span>';
                            statusText = Math.round(item.progress || 0) + '%';
                            break;
                        case 'completed':
                            icon = '✔'; break;
                        case 'failed':
                            icon = '✘'; statusText = '실패'; break;
                        case 'cancelled':
                            icon = '■'; statusText = '취소'; break;
                    }
                    if (!statusText && item.status === 'pending') statusText = '대기';
                    if (!statusText && item.status === 'completed') statusText = '완료';

                    // 학습 진행률 상세 (phase별 표시)
                    let phaseHint = '';
                    if (item.status === 'processing' && item.progress_detail) {
                        const d = item.progress_detail;
                        if (d.phase === 'generating' || d.phase === 'preview') {
                            const cur = d.current || d.value || 0;
                            const tot = d.total || d.max || 0;
                            statusText = '프리뷰';
                            phaseHint = '<span style="font-size:0.65rem;color:var(--text3);margin-left:2px;">' + cur + '/' + tot + '</span>';
                        } else if (d.phase === 'training') {
                            if (d.step !== undefined && d.total) {
                                statusText = '학습';
                                phaseHint = '<span style="font-size:0.65rem;color:var(--text3);margin-left:2px;">' + d.step + '/' + d.total + '</span>';
                            } else if (d.step !== undefined) {
                                statusText = '학습 step ' + d.step;
                            }
                        } else if (d.phase === 'modal_downloading' || d.phase === 'modal_download_queued' || d.phase === 'vast_downloading') {
                            statusText = d.phase === 'modal_download_queued' ? '다운로드 대기' : '다운로드';
                            const done = Number(d.downloaded_bytes || 0);
                            const total = Number(d.total_bytes || 0);
                            if (total > 0) {
                                phaseHint = '<span style="font-size:0.65rem;color:var(--text3);margin-left:2px;">' +
                                    comfyInstallerFormatBytes(done) + '/' + comfyInstallerFormatBytes(total) + '</span>';
                            }
                        } else if (d.phase === 'visual_profile_guide') {
                            const completed = Math.max(0, Number(d.completed || 0));
                            const tot = Math.max(0, Number(d.total || 0));
                            const isAppearanceStage = String(d.stage || '').startsWith('appearance_');
                            const profileCurrent = Math.max(0, Number(d.profile_current || 0));
                            const profileTotal = Math.max(0, Number(d.profile_total || 0));
                            statusText = isAppearanceStage
                                ? `외형 ${profileCurrent}/${profileTotal}`
                                : (tot > 0 ? `캐릭터 ${completed}/${tot}` : Math.round(item.progress || 0) + '%');
                            const character = String(d.character || '').trim();
                            if (character) {
                                phaseHint = '<span style="font-size:0.65rem;color:var(--text3);margin-left:2px;">' +
                                    escapeHtml(character) + '</span>';
                            }
                        } else if (d.step && d.total) {
                            statusText = d.step + '/' + d.total;
                        }
                    }

                    let actionBtn = '';
                    if (item.status === 'pending') {
                        actionBtn = '<button class="item-dismiss-btn" onclick="event.stopPropagation(); cancelQueueItem(\'' + item.id + '\');">✕</button>';
                    } else if (item.status === 'processing') {
                        actionBtn = '<button class="item-dismiss-btn" style="background:rgba(230,126,34,0.2);color:#e67e22;" onclick="event.stopPropagation(); skipCurrentItem(\'' + item.id + '\');">건너뛰기</button>';
                    } else {
                        actionBtn = '<button class="item-dismiss-btn" onclick="event.stopPropagation(); removeQueueItemBackend(\'' + item.id + '\');">✕</button>';
                    }

                    const labelColor = item.status === 'processing' ? ts.color : '';
                    row.innerHTML =
                        '<div class="item-icon">' + icon + '</div>' +
                        '<div class="item-label" style="' + (labelColor ? 'color:' + labelColor : '') + '">' + escapeHtml(item.label) + '</div>' +
                        (item.status === 'processing' ? '<div class="item-progress-bar"><div class="item-progress-bar-inner" style="width:' + Math.round(item.progress || 0) + '%"></div></div>' : '') +
                        '<div class="item-status">' + statusText + phaseHint + '</div>' +
                        actionBtn;
                    if (item.status === 'failed') {
                        row.appendChild(_renderQueueError(item));
                    }
                    const _itemLblEl = row.querySelector('.item-label');
                    if (_itemLblEl) _itemLblEl.title = item.label || '';
                    panelBody.appendChild(row);
                }
            });

            // 패널 헤더
            const panelSpinner = document.getElementById('queue-panel-spinner');
            const panelTitle = document.getElementById('queue-panel-title-text');
            if (hasActive) {
                panelSpinner.style.display = 'block';
                panelTitle.textContent = '처리 중 (' + (pending.length + (processing ? 1 : 0)) + '개)';
            } else {
                panelSpinner.style.display = 'none';
                panelTitle.textContent = failedCount ? `실패 ${failedCount}개` : '완료됨';
            }
        }

        async function removeQueueItemBackend(id) {
            try {
                await fetchJSON('/api/queue/remove', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id: id }),
                });
            } catch (e) { console.error('[QUEUE] 항목 제거 실패:', e); }
        }

        async function cancelQueueBatchBackend(batchId) {
            if (!batchId) return;
            if (!confirm('이 배치의 남은 대기 항목을 모두 취소할까요? (처리 중인 1건은 완료됩니다)')) return;
            try {
                const resp = await fetchJSON('/api/queue/cancel_batch', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ batch_id: batchId }),
                });
                if (resp && resp.success) showToast(`배치 취소: ${resp.cancelled || 0}건`, 'success');
                else showToast((resp && resp.error) || '배치 취소 실패', 'error');
            } catch (e) { showToast(`배치 취소 실패: ${e.message || e}`, 'error'); }
        }

        function setAssetQueuePanelExpanded(expanded) {
            assetQueueExpanded = Boolean(expanded);
            const container = document.getElementById('asset-queue-container');
            const panel = document.getElementById('asset-queue-panel');
            const bar = document.getElementById('asset-queue-bar');
            const icon = document.getElementById('queue-bar-expand-icon');
            const collapseBtn = document.getElementById('queue-panel-collapse-btn');
            const wallTab = document.getElementById('asset-queue-wall-tab');
            if (!container || !panel || !bar || !icon || !collapseBtn || !wallTab) {
                console.error('[QUEUE] setAssetQueuePanelExpanded: 큐 접기 UI 요소 누락', {
                    container: !!container, panel: !!panel, bar: !!bar, icon: !!icon,
                    collapseBtn: !!collapseBtn, wallTab: !!wallTab,
                });
                return;
            }
            if (assetQueueExpanded) {
                container.classList.remove('collapsed');
                panel.classList.remove('hidden');
                panel.classList.add('visible');
                bar.classList.add('expanded');
                panel.setAttribute('aria-hidden', 'false');
                panel.inert = false;
                bar.setAttribute('aria-expanded', 'true');
                bar.setAttribute('aria-hidden', 'false');
                bar.inert = false;
                bar.tabIndex = 0;
                wallTab.setAttribute('aria-expanded', 'true');
                wallTab.setAttribute('aria-hidden', 'true');
                wallTab.tabIndex = -1;
                bar.title = '작업 큐 접기';
                icon.textContent = '⌄';
            } else {
                container.classList.add('collapsed');
                panel.classList.remove('visible');
                panel.classList.add('hidden');
                bar.classList.remove('expanded');
                panel.setAttribute('aria-hidden', 'true');
                panel.inert = true;
                bar.setAttribute('aria-expanded', 'false');
                bar.setAttribute('aria-hidden', 'true');
                bar.inert = true;
                bar.tabIndex = -1;
                wallTab.setAttribute('aria-expanded', 'false');
                wallTab.setAttribute('aria-hidden', 'false');
                wallTab.tabIndex = 0;
                icon.textContent = '⌃';
            }
        }

        function collapseAssetQueuePanel() {
            const wallTab = document.getElementById('asset-queue-wall-tab');
            if (!wallTab) {
                console.error('[QUEUE] collapseAssetQueuePanel: asset-queue-wall-tab 요소 없음');
                return;
            }
            setAssetQueuePanelExpanded(false);
            wallTab.focus();
        }

        function expandAssetQueuePanel() {
            const collapseBtn = document.getElementById('queue-panel-collapse-btn');
            if (!collapseBtn) {
                console.error('[QUEUE] expandAssetQueuePanel: queue-panel-collapse-btn 요소 없음');
                return;
            }
            setAssetQueuePanelExpanded(true);
            renderAssetQueueUI();
            collapseBtn.focus();
        }

        function toggleAssetQueuePanel() {
            setAssetQueuePanelExpanded(!assetQueueExpanded);
            if (assetQueueExpanded) renderAssetQueueUI();
        }

        // ─── 에셋 생성 (큐 기반) ─────────────────────────────────
        async function generateAssetImage() {
            const char = document.getElementById('asset-character-select').value;
            const outfit = getAssetSelectValue('asset-outfit-select');
            const expr = getAssetSelectValue('asset-expression-select');
            const app = getAssetSelectValue('asset-appearance-select');

            if (!char || !outfit || !expr || !app) {
                const missing = [!char && '캐릭터', !app && '외형', !outfit && '의상', !expr && '표정'].filter(Boolean).join(', ');
                showToast(missing + '을(를) 선택해야 이미지를 생성할 수 있습니다', 'warning', 3000);
                return;
            }

            const totalCount = Math.max(1, parseInt(document.getElementById('asset-generate-count').value) || 1);

            // 프롬프트 미리보기 빌더로 프롬프트 생성 (단일 소스)
            const promptData = await buildAssetPromptFromUI();
            if (!promptData) {
                showToast('프롬프트 빌드 실패', 'error');
                return;
            }

            const capabilities = getAssetWorkflowCapabilities();
            const refEnabled = capabilities.ipadapter && document.getElementById('asset-ref-toggle').checked;
            const styleRefEnabled = capabilities.ipadapter && document.getElementById('asset-style-ref-toggle').checked;
            const snaprefEnabled = capabilities.anima && document.getElementById('asset-snapref-toggle').checked;

            const requestBody = {
                character: char,
                outfit: outfit,
                expression: expr,
                appearance: app,
                asset_workflow_type: capabilities.type,
                face_id_enabled: refEnabled,
                reference_images: refEnabled ? assetRefImages.map(img => ({filename: img.name, local_path: img.local_path})) : [],
                snapref_enabled: snaprefEnabled,
                snapref_strength: Number(document.getElementById('asset-snapref-strength')?.value ?? 0),
                snapref_mode: document.getElementById('asset-snapref-mode')?.value || 'char',
                snapref_megapixels: Number(document.getElementById('asset-snapref-megapixels')?.value ?? 1),
                snapref_images: snaprefEnabled ? assetSnapRefImages.map(img => ({filename: img.name, local_path: img.local_path})) : [],
                style_ref_enabled: styleRefEnabled,
                style_ref_images: styleRefEnabled ? assetStyleRefImages.map(img => ({filename: img.name, local_path: img.local_path})) : [],
                positive_prompt: promptData.positive,
                negative_prompt: promptData.negative,
            };

            // 인스턴스 LoRA 사용 횟수 증가
            const instanceLoraIds = [...new Set(assetLoraList.filter(l => l.source === 'instance' && l.lora_id).map(l => l.lora_id))];
            for (const lid of instanceLoraIds) {
                try { await fetchJSON('/api/instance_lora/increment_usage', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ id: lid }) }); } catch (e) { console.warn('[INSTANCE_LORA] 호출횟수 증가 실패:', lid, e); }
            }

            // 큐 항목 생성 (백엔드 통합 큐에 추가)
            for (let i = 0; i < totalCount; i++) {
                const label = totalCount > 1 ? char + '/' + outfit + '/' + expr + ' (' + (i + 1) + '/' + totalCount + ')' : char + '/' + outfit + '/' + expr;
                try {
                    await fetchJSON('/api/queue/add', {
                        method: 'POST', headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ type: 'asset_generation', label: label, params: { body: requestBody } }),
                    });
                } catch (e) {
                    console.error('[QUEUE] 에셋 생성 큐 추가 실패:', e);
                    showToast('큐 추가 실패: ' + e.message, 'error');
                }
            }
        }

        async function processAssetQueue() {
            // 통합 큐에서 처리하므로 프론트엔드 루프 불필요
        }

        async function stopAssetQueue() {
            if (!confirm('대기 중인 모든 작업을 취소하시겠습니까?')) return;
            try {
                await fetchJSON('/api/queue/cancel_all', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                });
            } catch (e) { console.error('[QUEUE] 전체 취소 실패:', e); }
        }

        async function cancelQueueItem(id) {
            try {
                await fetchJSON('/api/queue/cancel', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id: id }),
                });
            } catch (e) { console.error('[QUEUE] 취소 실패:', e); }
        }

        function skipCurrentItem(id) {
            cancelQueueItem(id);
        }

        // 하위 호환성
        function stopAssetGeneration() { stopAssetQueue(); }

        async function loadAssetImages() {
            const requestId = loadAssetImages.requestId = (loadAssetImages.requestId || 0) + 1;
            const main = document.getElementById('asset-main');
            if (!main) {
                console.error('[ASSET] LV2 스크롤 저장 실패: asset-main 요소가 없습니다.');
            }
            // 네비게이션 상태 우선, 없으면 사이드바에서 가져옴
            const char = assetNavCharacter || document.getElementById('asset-character-select').value;
            const outfit = assetNavOutfit || getAssetSelectValue('asset-outfit-select');
            const expr = assetNavExpression || getAssetSelectValue('asset-expression-select');
            const empty = document.getElementById('asset-empty-state');

            if (!char || !outfit || !expr) {
                showAssetView('empty');
                empty.querySelector('h3').textContent = '에셋 생성 모드';
                empty.querySelector('p').textContent = '사이드바에서 캐릭터, 복장, 표정을 선택한 후 이미지를 생성하세요.';
                return;
            }

            try {
                const enc = encodeURIComponent;
                const url = `/api/asset_mode/characters/${enc(char)}/outfits/${enc(outfit)}/expressions/${enc(expr)}/images`;
                const grid = document.getElementById('asset-image-grid');
                const sameView = grid.dataset.url === url && grid.style.display === 'grid';
                if (!sameView) showAssetView('loading');
                const resp = await fetch(url);
                const data = await resp.json();
                if (requestId !== loadAssetImages.requestId || assetNavLevel !== 2
                    || char !== (assetNavCharacter || document.getElementById('asset-character-select').value)
                    || outfit !== (assetNavOutfit || getAssetSelectValue('asset-outfit-select'))
                    || expr !== (assetNavExpression || getAssetSelectValue('asset-expression-select'))) {
                    console.log('[ASSET] 이전 이미지 요청 응답을 건너뜁니다:', url, requestId);
                    return;
                }
                const images = data.images || [];

                if (images.length === 0) {
                    showAssetView('empty');
                    empty.querySelector('h3').textContent = `${char} / ${outfit} / ${expr}`;
                    empty.querySelector('p').textContent = '아직 생성된 이미지가 없습니다. "이미지 생성" 버튼을 눌러보세요.';
                    return;
                }

                const savedScroll = sameView && main ? main.scrollTop : 0;
                grid.innerHTML = '';

                images.forEach(img => {
                    const imgUrl = `/api/asset_mode/characters/${enc(char)}/outfits/${enc(outfit)}/expressions/${enc(expr)}/images/${enc(img.filename)}`;
                    const posterUrl = img.is_animated ? `${imgUrl}/poster` : imgUrl;
                    const animationAttrs = img.is_animated
                        ? `data-poster-src="${posterUrl}" data-anim-src="${imgUrl}" onmouseenter="this.src=this.dataset.animSrc" onmouseleave="this.src=this.dataset.posterSrc"`
                        : '';
                    const card = document.createElement('div');
                    card.className = 'asset-image-card';
                    const hasPrompt = img.positive || img.negative || img.edit_prompt || img.is_video_animation;
                    const promptDetails = img.is_video_animation === true
                        ? renderVideoPromptDetails(img, img.positive)
                        : `
                            ${img.positive ? `<b>긍정:</b> ${escapeHtml(img.positive).replace(/\n/g, '<br>')}` : ''}
                            ${img.negative ? `<br><b>부정:</b> ${escapeHtml(img.negative).replace(/\n/g, '<br>')}` : ''}
                            ${img.edit_prompt ? `<br><b>Edit:</b> ${escapeHtml(img.edit_prompt).replace(/\n/g, '<br>')}` : ''}
                            ${img.edit_prompt_original && img.edit_prompt_original !== img.edit_prompt ? `<br><b>Edit 원문:</b> ${escapeHtml(img.edit_prompt_original).replace(/\n/g, '<br>')}` : ''}
                            ${img.edit_negative_prompt ? `<br><b>Edit 부정:</b> ${escapeHtml(img.edit_negative_prompt).replace(/\n/g, '<br>')}` : ''}
                            ${img.edit_source_filename ? `<br><b>Edit 원본:</b> ${escapeHtml(img.edit_source_filename)}` : ''}
                        `;
                    card.innerHTML = `
                        ${img.is_representative ? '<div class="rep-badge">대표</div>' : ''}
                        <div class="asset-img-frame">
                            ${img.is_animated ? '<span class="source-badge source-anim" title="영상 · 마우스를 올려 재생">A</span>' : ''}
                            <img src="${posterUrl}" data-full-src="${imgUrl}" ${animationAttrs} onclick="openLightbox(this.dataset.fullSrc)" loading="lazy">
                            ${img.is_edited ? '<div class="edit-badge">EDIT됨</div>' : ''}
                        </div>
                        <div class="card-actions">
                            <span class="filename">${escapeHtml(img.filename)}</span>
                            <button onclick="setAssetRepresentative('${enc(char)}','${enc(outfit)}','${enc(expr)}','${enc(img.filename)}')">
                                ${img.is_representative ? '대표해제' : '대표설정'}
                            </button>
                            <button onclick="deleteAssetImage('${enc(char)}','${enc(outfit)}','${enc(expr)}','${enc(img.filename)}')" style="color:var(--error);">삭제</button>
                            <button onclick="sendAssetToPoseEditor('${imgUrl}','${enc(img.filename)}')">포즈 편집</button>
                            <button type="button" class="qwen-edit-btn" ${img.is_animated ? 'disabled title="영상 에셋에는 EDIT 툴을 사용할 수 없습니다"' : ''}>EDIT 툴 호출</button>
                            <button type="button" class="asset-video-btn">영상화</button>
                            <button type="button" class="asset-video-postprocess-btn" ${img.is_animated ? 'title="이 animated 에셋을 새 파일로 후처리합니다"' : 'disabled title="영상 후처리는 animated AVIF/WebP 에셋에서만 사용할 수 있습니다"'}>영상 후처리</button>
                            <button type="button" class="asset-llm-flow-btn" ${img.is_animated ? 'title="이 애니메이션 에셋을 만든 영상화 LLM 흐름을 보여줍니다"' : 'disabled title="LLM 흐름은 애니메이션 에셋에서만 확인할 수 있습니다"'}>🧩 LLM 흐름</button>
                        </div>
                        ${hasPrompt ? `
                        <div class="prompt-info">
                            <div class="prompt-label" onclick="this.parentElement.classList.toggle('expanded')">프롬프트 ▾</div>
                            <div class="prompt-text">
                                ${promptDetails}
                            </div>
                        </div>` : ''}`;
                    const qwenButton = card.querySelector('.qwen-edit-btn');
                    if (qwenButton && !img.is_animated) {
                        qwenButton.addEventListener('click', (event) => {
                            event.stopPropagation();
                            auOpenQwenEdit({
                                character: char,
                                outfit,
                                expression: expr,
                                filename: img.filename,
                                imageUrl: imgUrl,
                                positive: img.positive || '',
                                negative: img.edit_negative_prompt || img.negative || '',
                            });
                        });
                    } else if (!qwenButton) {
                        console.error('[QWEN_EDIT] 에셋 생성 LV2 카드 버튼 생성 실패:', img.filename);
                    }
                    const videoButton = card.querySelector('.asset-video-btn');
                    if (videoButton) {
                        videoButton.addEventListener('click', (event) => {
                            event.stopPropagation();
                            openAssetVideoWorkspace({
                                character: char,
                                outfit,
                                expression: expr,
                                filename: img.filename,
                            });
                        });
                    } else {
                        console.error('[ASSET_VIDEO_UI] 에셋 생성 LV2 카드 버튼 생성 실패:', img.filename);
                    }
                    const videoPostprocessButton = card.querySelector('.asset-video-postprocess-btn');
                    if (videoPostprocessButton && img.is_animated) {
                        videoPostprocessButton.addEventListener('click', (event) => {
                            event.stopPropagation();
                            openAssetVideoReprocess({
                                character: char,
                                outfit,
                                expression: expr,
                                filename: img.filename,
                            }, img, posterUrl, imgUrl);
                        });
                    } else if (!videoPostprocessButton) {
                        console.error('[ASSET_VIDEO_REPROCESS_UI] 에셋 생성 LV2 카드 버튼 생성 실패:', img.filename);
                    }
                    const llmFlowButton = card.querySelector('.asset-llm-flow-btn');
                    if (llmFlowButton && img.is_animated) {
                        llmFlowButton.addEventListener('click', (event) => {
                            event.stopPropagation();
                            openAssetLlmFlowModal({
                                character: char,
                                outfit,
                                expression: expr,
                                filename: img.filename,
                            });
                        });
                    } else if (!llmFlowButton) {
                        console.error('[ASSET_LLM_FLOW] 에셋 생성 LV2 카드 버튼 생성 실패:', img.filename);
                    }
                    grid.appendChild(card);
                });

                grid.dataset.url = url;
                showAssetView('grid');
                if (main) main.scrollTop = savedScroll;
            } catch (e) {
                console.error('[ASSET] 이미지 로드 실패:', e);
            }
        }

        async function setAssetRepresentative(char, outfit, expr, filename) {
            try {
                const resp = await fetch('/api/asset_mode/set_representative', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        character: decodeURIComponent(char),
                        outfit: decodeURIComponent(outfit),
                        expression: decodeURIComponent(expr),
                        filename: decodeURIComponent(filename),
                    })
                });
                const result = await resp.json();
                if (result.success) {
                    showToast('대표 이미지 설정 완료', 'success');
                    renderAssetMainArea();
                } else {
                    showToast(result.error || '설정 실패', 'error');
                }
            } catch (e) {
                showToast('요청 실패', 'error');
            }
        }

        async function deleteAssetCombination(char, outfit, expr, imageCount) {
            const msg = imageCount > 0
                ? `"${decodeURIComponent(outfit)} - ${decodeURIComponent(expr)}" 조합과\n내부 이미지 ${imageCount}장을 모두 삭제할까요?\n이 작업은 되돌릴 수 없습니다.`
                : `"${decodeURIComponent(outfit)} - ${decodeURIComponent(expr)}" 조합을 삭제할까요?`;
            if (!confirm(msg)) return;
            try {
                const resp = await fetch('/api/asset_mode/delete_combination', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        character: decodeURIComponent(char),
                        outfit: decodeURIComponent(outfit),
                        expression: decodeURIComponent(expr),
                    })
                });
                const result = await resp.json();
                if (result.success) {
                    showToast('조합 삭제 완료', 'success');
                    renderCharacterGallery(decodeURIComponent(char));
                } else {
                    showToast(result.error || '삭제 실패', 'error');
                }
            } catch (e) {
                showToast('요청 실패', 'error');
            }
        }

        async function deleteAssetImage(char, outfit, expr, filename) {
            if (!confirm('이 이미지를 삭제할까요?')) return;
            try {
                const resp = await fetch('/api/asset_mode/delete_image', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        character: decodeURIComponent(char),
                        outfit: decodeURIComponent(outfit),
                        expression: decodeURIComponent(expr),
                        filename: decodeURIComponent(filename),
                    })
                });
                const result = await resp.json();
                if (result.success) {
                    showToast('이미지 삭제 완료', 'success');
                    renderAssetMainArea();
                } else {
                    showToast(result.error || '삭제 실패', 'error');
                }
            } catch (e) {
                showToast('요청 실패', 'error');
            }
        }

        // 에셋 모드 WebSocket 이벤트 핸들링 (기존 ws 핸들러에 추가)
        async function handleAssetVideoCreated(data) {
            if (!data || !data.character || !data.outfit || !data.expression) {
                console.error('[ASSET_VIDEO_UI] 완료 이벤트 필수값 누락:', data);
                return;
            }
            showToast(`영상 에셋 추가 완료: ${data.filename || ''}`, 'success');
            const assetTabActive = document.getElementById('tab-asset-content')?.classList.contains('active');
            const uploadTabActive = document.getElementById('tab-asset-upload-content')?.classList.contains('active');
            try {
                if (assetTabActive && assetNavCharacter === data.character) {
                    if (
                        assetNavLevel === 2
                        && assetNavOutfit === data.outfit
                        && assetNavExpression === data.expression
                    ) {
                        await loadAssetImages();
                    } else if (assetNavLevel === 1) {
                        await renderCharacterGallery(assetNavCharacter);
                    }
                }
                if (uploadTabActive && auNavCharacter === data.character) {
                    if (
                        auNavLevel === 2
                        && auNavOutfit === data.outfit
                        && auNavExpression === data.expression
                    ) {
                        await auRenderImages(auNavCharacter, auNavOutfit, auNavExpression);
                    } else if (auNavLevel === 1) {
                        await auRenderGallery(auNavCharacter);
                    }
                }
            } catch (error) {
                console.error('[ASSET_VIDEO_UI] 영상 완료 후 목록 갱신 실패:', error, data);
            }
        }

        function handleAssetWsEvent(type, data) {
            if (type === 'asset_generation_progress') {
                // 큐에서 현재 에셋 생성 항목 찾아서 진행률 업데이트
                const current = assetQueue.find(q => q.status === 'processing' && q.type === 'asset_generation');
                if (current) {
                    current.progress = data.max > 0 ? (data.value / data.max * 100) : 0;
                    current.progress_detail = data;
                }
                updateTopProgress(data.value || 0, data.max || 0);
                renderAssetQueueUI();
            } else if (type === 'asset_generation_completed') {
                if (typeof atHandleDefaultGenerationEvent === 'function') {
                    atHandleDefaultGenerationEvent(data).catch(e => {
                        console.error('[AUTOMATCH] 기본 이미지 완료 이벤트 처리 실패:', e);
                    });
                }
                if (data.status === 'success') {
                    renderAssetMainArea();
                } else if (data.status === 'error') {
                    const errMsg = (data.result && data.result.error) || data.error || '에셋 생성 실패';
                    console.error('[ASSET] 생성 실패:', errMsg);
                    showToast(errMsg, 'error');
                }
                hideTopProgress();
            }
        }

        // ─── 통합 큐 모달 ──────────────────────────────────────
        let queueModalOpen = false;
        let queueModalData = []; // 큐 모달 전용 상태
        let queueIllustWaiting = false; // 삽화 대기 중 여부
        let queueIllustWaitStartedAt = null; // epoch(ms)
        let queueIllustWaitSeconds = 10; // 총 대기 시간(초)
        let _queueIllustWaitTimer = null; // 카운트다운 렌더 타이머
        let queuePaused = false; // 큐 일시정지 중 여부 (새 작업 꺼내기만 멈춤, 적재는 계속)

        function toggleQueueModal() {
            if (queueModalOpen) closeQueueModal();
            else openQueueModal();
        }
        async function openQueueModal() {
            queueModalOpen = true;
            document.getElementById('queue-modal').classList.add('visible');
            // 서버에서 최신 큐 상태를 가져와 모달 데이터 동기화
            try {
                const data = await fetchJSON('/api/queue/status');
                if (data && data.items) {
                    const prevStatus = {};
                    queueModalData.forEach(i => prevStatus[i.id] = i.status);
                    queueModalData = data.items.map(item => ({
                        id: item.id,
                        type: item.type || '',
                        label: item.label || '',
                        status: item.status,
                        error: item.error || '',
                        created_at: item.created_at,
                        completed_at: item.completed_at,
                        progress: item.progress || 0,
                        progress_detail: item.progress_detail || {},
                        subtasks: Array.isArray(item.subtasks) ? item.subtasks : [],
                        execution_area: item.execution_area || 'gpu',
                        provider: item.provider || '',
                        batch_id: item.batch_id || null,
                        batch_label: item.batch_label || null,
                        batch_index: item.batch_index || null,
                        batch_total: item.batch_total || null,
                    }));
                    queueModalData.forEach(_expandActiveQueueSubtasks);
                    updateQueueBadge();
                    queueIllustWaiting = !!data.illust_waiting;
                    queueIllustWaitStartedAt = data.illust_wait_started_at ? data.illust_wait_started_at * 1000 : null;
                    queueIllustWaitSeconds = data.illust_wait_seconds || 10;
                    _updateIllustWaitTimer();
                    queuePaused = !!data.paused;
                    _updateQueuePauseUI();
                }
            } catch (e) { console.error('[QUEUE] 모달 열 때 상태 로드 실패:', e); }
            renderQueueModal();
        }
        function closeQueueModal() {
            queueModalOpen = false;
            const modal = document.getElementById('queue-modal');
            if (modal) modal.classList.remove('visible');
            else console.error('[QUEUE] closeQueueModal: queue-modal 요소 없음');
        }

        function updateQueueBadge() {
            // 배치(동일 batch_id)는 1작업으로 취급 — 1000장 일괄 태깅이 배지를 1000으로 도배하지 않도록.
            // '활성' = 아직 끝나지 않은 작업(pending + waiting + processing). waiting은 LLM 슬롯
            // 게이트 대기 중이지만 완료되지 않은 작업이므로 미처리 작업 수에 포함한다.
            const active = queueModalData.filter(
                i => i.status === 'pending' || i.status === 'waiting' || i.status === 'processing'
            );
            const batchIds = new Set();
            let standalone = 0;
            active.forEach(i => { if (i.batch_id) batchIds.add(i.batch_id); else standalone++; });
            const jobs = standalone + batchIds.size;
            const totalImages = active.length;
            const badge = document.getElementById('queue-badge');
            if (!badge) { console.error('[QUEUE] updateQueueBadge: queue-badge 요소 없음'); return; }
            if (jobs > 0) {
                badge.textContent = (batchIds.size > 0 && totalImages > jobs) ? `${jobs}(${totalImages})` : String(jobs);
                badge.style.display = 'flex';
            } else {
                badge.style.display = 'none';
            }
        }

        const _queueTypeLabels = {
            illustration: '삽화', asset_generation: '에셋',
            qwen_edit: 'EDIT 툴',
            illustration_llm_build: '삽화 LLM',
            illustration_easy_edit: '삽화 편집',
            illustration_image_analysis: '이미지 분석',
            illustration_auto_feedback_llm: '삽화 오토피드백 LLM',
            llm_test: 'LLM 테스트',
            visual_profile_guide: '프로필 선택 기준',
            asset_lora_training: '에셋로라', bot_lora_training: '봇로라',
            instance_lora_face_extract: '얼굴추출',
            instance_lora_training: '인스턴스로라',
            instance_lora_analysis: '인스턴스분석',
            instance_lora_prompt_refine: '프롬프트 정제',
            lora_prompt_review: '프롬프트 2차 검수',
            bot_lora_feedback: 'LoRA 오토피드백 학습',
            bot_llm_face_tag_analysis: 'LLM 얼굴분석',
            bot_lb_extra_refine: 'lb.extra 프로필 정제',
            qwen_edit_translate: 'EDIT 번역',
            video_instruction_draft: 'H3 AI 초안',
            video_instruction_refine: 'H3 V1 일반 다듬기',
            video_instruction_direct: 'H3 V2 시네마틱 다듬기',
            video_prompt_build: 'H3 프롬프트',
            video_i2v: 'H3 I2V',
            video_first_last: 'H3 FLF2V',
            video_postprocess: '영상 후처리',
            character_maker: '캐릭터 메이커',
            preset_import_classify: '프리셋 가져오기 분류',
            tag_analysis: '태그분석',
            auto_match_batch: '배치매칭',
            regenerate: '재생성',
            restore_manual: '수동 생성',
            data_patch_utility: '데이터 패치',
            modal_lora_download: 'Modal 다운로드',
            vast_lora_download: 'Vast 다운로드',
        };

        const _queueAreaDefinitions = [
            {key: 'llm', icon: '🧠', title: 'LLM 처리', note: 'CALL 및 프롬프트 분석'},
            {key: 'hybrid', icon: '⚡', title: '동적 배분', note: '먼저 빈 로컬 GPU/Modal/Vast/챈섭이 실행'},
            {key: 'gpu', icon: '🖥️', title: 'GPU', note: '로컬 ComfyUI 작업'},
            {
                key: 'cloud', icon: '☁️', title: '클라우드 GPU', note: '원격 ComfyUI 작업',
                itemAreas: ['modal', 'vast'],
                legend: [
                    {key: 'modal', label: 'Modal'},
                    {key: 'vast', label: 'Vast'},
                ],
            },
            {key: 'background', icon: '⚙️', title: '백그라운드 처리', note: 'Modal 다운로드 · 영상 업스케일/AVIF 변환'},
            {key: 'external', icon: '☁️', title: '외부 서비스', note: '챈섭 API 작업'},
        ];

        function _queueDefinitionIncludesArea(definition, area) {
            const itemAreas = Array.isArray(definition && definition.itemAreas)
                ? definition.itemAreas
                : [definition && definition.key];
            return itemAreas.includes(area);
        }

        function _queueItemArea(item) {
            const area = String((item && item.execution_area) || 'gpu').toLowerCase();
            // 둘 이상의 Comfy 실행 레인에 병렬 배분된 작업은 실제 워커가 claim하기 전까지
            // 특정 GPU 소속이 아니므로 동적 배분 레인에 표시한다.
            if (area === 'comfy_parallel') return 'hybrid';
            if (area === 'vast_download') return 'background';
            if (area === 'modal_download' || area === 'video_postprocess') return 'background';
            return _queueAreaDefinitions.some(def => _queueDefinitionIncludesArea(def, area)) ? area : 'gpu';
        }

        function _updateIllustWaitTimer() {
            if (queueIllustWaiting && !_queueIllustWaitTimer) {
                _queueIllustWaitTimer = setInterval(() => {
                    const banner = document.getElementById('queue-illust-wait-banner');
                    if (!banner || !queueIllustWaiting || !queueIllustWaitStartedAt) return;
                    const elapsedMs = Date.now() - queueIllustWaitStartedAt;
                    const remainSec = Math.max(0, queueIllustWaitSeconds - Math.floor(elapsedMs / 1000));
                    banner.innerHTML = `⏳ <b>삽화 대기 중</b> - 새 삽화 도착 시 즉시 실행, 없으면 <b>${remainSec}초</b> 후 다음 작업`;
                }, 500);
            } else if (!queueIllustWaiting && _queueIllustWaitTimer) {
                clearInterval(_queueIllustWaitTimer);
                _queueIllustWaitTimer = null;
            }
        }

        function renderQueueModal() {
            if (!queueModalOpen) return;
            const wait = 200 - (Date.now() - (renderQueueModal.lastRender || 0));
            if (wait > 0) {
                if (!renderQueueModal.timer) renderQueueModal.timer = setTimeout(() => {
                    renderQueueModal.timer = null;
                    renderQueueModal();
                }, wait);
                return;
            }
            if (renderQueueModal.timer) clearTimeout(renderQueueModal.timer);
            renderQueueModal.timer = null;
            renderQueueModal.lastRender = Date.now();
            const body = document.getElementById('queue-modal-body');
            if (!body) { console.error('[QUEUE] renderQueueModal: queue-modal-body 요소 없음'); return; }
            // 삽화 대기 배너
            let waitBanner = document.getElementById('queue-illust-wait-banner');
            if (queueIllustWaiting && queueIllustWaitStartedAt) {
                const elapsedMs = Date.now() - queueIllustWaitStartedAt;
                const remainSec = Math.max(0, queueIllustWaitSeconds - Math.floor(elapsedMs / 1000));
                if (!waitBanner) {
                    waitBanner = document.createElement('div');
                    waitBanner.id = 'queue-illust-wait-banner';
                    waitBanner.style.cssText = 'background:rgba(255,193,7,0.12);border:1px solid rgba(255,193,7,0.5);color:#ffc107;padding:8px 10px;border-radius:6px;font-size:0.82rem;margin-bottom:8px;text-align:center;';
                }
                waitBanner.innerHTML = `⏳ <b>삽화 대기 중</b> - 새 삽화 도착 시 즉시 실행, 없으면 <b>${remainSec}초</b> 후 다음 작업`;
            } else if (waitBanner) {
                waitBanner.remove();
                // 변수 참조를 끊어야 함수 뒤쪽의 `if (waitBanner) body.appendChild(waitBanner)`가
                // 방금 제거한 배너를 다시 붙이지 않음 (대기 종료 후 배너가 안 사라지는 버그 수정)
                waitBanner = null;
            }
            // 일시정지 배너 — 큐는 계속 쌓이지만 새 작업 실행이 멈춰 있음을 표시
            let pauseBanner = document.getElementById('queue-pause-banner');
            if (queuePaused) {
                if (!pauseBanner) {
                    pauseBanner = document.createElement('div');
                    pauseBanner.id = 'queue-pause-banner';
                    pauseBanner.style.cssText = 'background:rgba(255,193,7,0.12);border:1px solid rgba(255,193,7,0.5);color:#ffc107;padding:8px 10px;border-radius:6px;font-size:0.82rem;margin-bottom:8px;text-align:center;';
                }
                pauseBanner.innerHTML = '⏸ <b>큐 일시정지 중</b> — 새 작업이 꺼내지지 않고 대기합니다 (현재 실행중 작업은 완료까지 진행).';
            } else if (pauseBanner) {
                pauseBanner.remove();
                pauseBanner = null;
            }
            let empty = document.getElementById('queue-modal-empty');
            // innerHTML='' 로 삭제된 경우 재생성
            if (!empty) {
                console.warn('[QUEUE] renderQueueModal: queue-modal-empty 요소가 DOM에서 사라짐, 재생성');
                empty = document.createElement('div');
                empty.id = 'queue-modal-empty';
                empty.style.cssText = 'text-align:center;color:var(--text2);padding:40px 0;font-size:0.9rem;';
                empty.textContent = '대기 중인 작업이 없습니다';
            }
            const history = _queueHistoryItems(queueModalData);
            const items = queueModalData.filter(item => !_queueItemFinished(item));
            // 큐가 완전히 비어 있어도 6개 lane 구조를 항상 보여준다.
            // 각 lane은 빈 상태에서 "대기 중인 작업 없음" 표시를 자체 처리한다.
            empty.style.display = 'none';
            body.innerHTML = '';
            body.appendChild(empty);
            if (pauseBanner) body.appendChild(pauseBanner);
            if (waitBanner) body.appendChild(waitBanner);
            const historySection = document.createElement('section');
            historySection.className = 'queue-history';
            historySection.innerHTML = `<h3>최근 작업 <span>최대 10개 · 최신순</span></h3>`;
            if (!history.length) {
                const emptyHistory = document.createElement('p');
                emptyHistory.className = 'queue-lane-empty';
                emptyHistory.textContent = '아직 작업 기록이 없습니다';
                historySection.appendChild(emptyHistory);
            }
            history.forEach(item => {
                historySection.appendChild(_renderQueueItemRow(item, queueModalData.indexOf(item), false));
                if (_queueSubtasksExpanded.has(item.id) && Array.isArray(item.subtasks)) {
                    item.subtasks.forEach(subtask => historySection.appendChild(
                        _renderQueueSubtaskRow(subtask, _queueItemArea(item))
                    ));
                }
            });
            body.appendChild(historySection);
            try {
                const lanes = document.createElement('div');
                lanes.className = 'queue-lanes';
                _queueAreaDefinitions.forEach(def => {
                    const laneItems = items.filter(item =>
                        _queueDefinitionIncludesArea(def, _queueItemArea(item))
                    );
                    // '실행 중' = 실제 처리 중(processing). LLM lane에서는 곧 슬롯 게이트를 잡아
                    // API를 호출 중인 항목 수(=실제 동시 호출 수). '대기' = pending + waiting(게이트 대기).
                    const processingCount = laneItems.filter(item => item.status === 'processing').length;
                    const queuedCount = laneItems.filter(
                        item => item.status === 'pending' || item.status === 'waiting'
                    ).length;
                    const laneCountHtml = queuedCount > 0
                        ? `<span style="color:var(--accent);font-weight:600;">${processingCount}</span><span style="color:var(--text3);"> / ${queuedCount}</span>`
                        : `<span>${processingCount}</span>`;
                    const lane = document.createElement('section');
                    lane.className = `queue-lane ${def.key}`;
                    lane.dataset.queueArea = def.key;
                    const laneNoteHtml = Array.isArray(def.legend)
                        ? `<span class="queue-cloud-legend" aria-label="Modal은 보라색, Vast는 초록색">${def.legend.map(entry => `
                            <span class="queue-cloud-key" data-provider="${entry.key}">
                                <span class="queue-cloud-dot" aria-hidden="true"></span>${entry.label}
                            </span>
                        `).join('')}</span>`
                        : `<span class="queue-lane-note">${def.note}</span>`;
                    lane.innerHTML = `
                        <div class="queue-lane-header">
                            <span aria-hidden="true">${def.icon}</span>
                            <span class="queue-lane-title">${def.title}</span>
                            ${laneNoteHtml}
                            <span class="queue-lane-count" title="실행 중 ${processingCount} · 대기 ${queuedCount} (슬롯 게이트 대기 포함)">${laneCountHtml}</span>
                        </div>
                    `;
                    const laneBody = document.createElement('div');
                    laneBody.className = 'queue-lane-items';
                    laneBody.dataset.queueArea = def.key;
                    _renderQueueAreaItems(laneBody, laneItems);
                    lane.appendChild(laneBody);
                    lanes.appendChild(lane);
                });
                body.appendChild(lanes);
            } catch (err) { console.error('[QUEUE] renderQueueModal 아이템 렌더링 실패:', err, 'items:', items); }
        }

        // 실행 영역 하나의 항목을 기존 배치 접기 규칙으로 렌더한다.
        function _renderQueueAreaItems(container, items) {
            if (!items.length) {
                const empty = document.createElement('div');
                empty.className = 'queue-lane-empty';
                empty.textContent = '대기 중인 작업 없음';
                container.appendChild(empty);
                return;
            }
            const rendered = new Set();
            const indices = new Map(queueModalData.map((item, index) => [item.id, index]));
            items.forEach(item => {
                if (rendered.has(item.id)) return;
                const idx = indices.get(item.id);
                if (item.batch_id) {
                    const itemArea = _queueItemArea(item);
                    const grp = items.filter(i =>
                        i.batch_id === item.batch_id && _queueItemArea(i) === itemArea
                    );
                    grp.forEach(groupItem => rendered.add(groupItem.id));
                    const total = item.batch_total || grp.length;
                    const pending = grp.filter(i => i.status === 'pending' || i.status === 'waiting').length;
                    const processing = grp.filter(i => i.status === 'processing').length;
                    const done = Math.max(0, total - pending - processing);
                    const anyPending = pending > 0;
                    const expanded = _queueBatchExpanded.has(item.batch_id);
                    const label = item.batch_label || item.label || '배치';
                    const typeLabel = _queueTypeLabels[item.type] || item.type || '';
                    const pct = total > 0 ? Math.round((done / total) * 100) : 0;
                    const el = document.createElement('div');
                    el.className = 'queue-modal-item queue-modal-batch' + (processing ? ' processing' : '') + ((pending === 0 && processing === 0) ? ' completed' : '');
                    el.dataset.queueArea = _queueItemArea(item);
                    el.innerHTML = `
                        <span class="qm-handle">&nbsp;</span>
                        <span class="qm-type">${escapeHtml(typeLabel)}</span>
                        <span class="qm-label" style="cursor:pointer" onclick="queueModalToggleBatch('${escapeHtml(item.batch_id)}')">${expanded ? '▼' : '▶'} ${escapeHtml(label)}</span>
                        <span class="qm-progress">${done}/${total} <span style="font-size:0.6rem;color:var(--text3);">${pct}%</span></span>
                        <span class="qm-actions">
                            ${anyPending ? '<button onclick="queueModalCancelBatch(\''+escapeHtml(item.batch_id)+'\')" title="배치 전체 취소">✕</button>' : ''}
                        </span>
                    `;
                    const batchLabelEl = el.querySelector('.qm-label');
                    if (batchLabelEl) batchLabelEl.title = label;
                    container.appendChild(el);
                    if (expanded) {
                        const pageSize = 50;
                        const pages = Math.ceil(grp.length / pageSize);
                        const page = Math.min(_queueBatchPages.get(item.batch_id) || 0, pages - 1);
                        _queueBatchPages.set(item.batch_id, page);
                        if (pages > 1) {
                            const navigation = document.createElement('div');
                            navigation.className = 'queue-batch-pages';
                            navigation.style.cssText = 'display:flex;align-items:center;justify-content:center;gap:8px;padding:6px;font-size:0.78rem;';
                            navigation.innerHTML = `
                                <button ${page === 0 ? 'disabled' : ''} onclick="queueModalToggleBatch('${escapeHtml(item.batch_id)}', ${page - 1})">이전</button>
                                <span>${page * pageSize + 1}–${Math.min((page + 1) * pageSize, grp.length)} / ${grp.length}</span>
                                <button ${page === pages - 1 ? 'disabled' : ''} onclick="queueModalToggleBatch('${escapeHtml(item.batch_id)}', ${page + 1})">다음</button>`;
                            container.appendChild(navigation);
                        }
                        grp.slice(page * pageSize, (page + 1) * pageSize).forEach(groupItem => {
                            const groupIdx = indices.get(groupItem.id);
                            container.appendChild(_renderQueueItemRow(groupItem, groupIdx, true));
                        });
                    }
                } else {
                    container.appendChild(_renderQueueItemRow(item, idx, false));
                    if (_queueSubtasksExpanded.has(item.id) && Array.isArray(item.subtasks)) {
                        item.subtasks.forEach(subtask => {
                            container.appendChild(_renderQueueSubtaskRow(subtask, _queueItemArea(item)));
                        });
                    }
                }
            });
        }

        // 배치 그룹 항목 1줄 렌더 헬퍼 (개별/펼침 자식 공용). indent=true면 자식 항목(↳ 들여쓰기).
        function _renderQueueItemRow(item, idx, indent) {
            const el = document.createElement('div');
            el.className = 'queue-modal-item'
                + (item.status === 'processing' ? ' processing' : '')
                + (item.status === 'waiting' ? ' waiting' : '')
                + (item.status === 'completed' ? ' completed' : '')
                + (item.status === 'failed' ? ' failed' : '')
                + (indent ? ' indented' : '');
            el.dataset.queueModalIdx = idx;
            el.dataset.queueItemId = item.id;
            el.dataset.queueArea = _queueItemArea(item);
            const isPending = item.status === 'pending';
            const isProcessing = item.status === 'processing';
            const isWaiting = item.status === 'waiting';
            const isComfyWaiting = isWaiting && item.type === 'illustration' && item.execution_area === 'gpu';
            const subtasks = Array.isArray(item.subtasks) ? item.subtasks : [];
            const hasSubtasks = subtasks.length > 0;
            const subtasksExpanded = hasSubtasks && _queueSubtasksExpanded.has(item.id);
            const pct = item.progress ? Math.round(item.progress) : 0;
            let progressLabel = pct + '%';
            if (isProcessing && item.progress_detail) {
                const d = item.progress_detail;
                if (d.phase === 'generating' || d.phase === 'preview') {
                    const cur = d.current ?? d.value ?? 0;
                    const tot = d.total ?? d.max ?? 0;
                    const phaseLabel = item.type === 'illustration_llm_build'
                        ? '합류'
                        : (d.phase === 'preview' ? '프리뷰' : '생성');
                    progressLabel = phaseLabel + ' <span style="font-size:0.65rem;color:var(--text3);">' + cur + '/' + tot + '</span>';
                } else if (d.phase === 'training' && d.step !== undefined && d.total) {
                    progressLabel = pct + '% <span style="font-size:0.65rem;color:var(--text3);">' + d.step + '/' + d.total + '</span>';
                } else if (d.phase === 'modal_downloading' || d.phase === 'modal_download_queued' || d.phase === 'vast_downloading') {
                    const done = Number(d.downloaded_bytes || 0);
                    const total = Number(d.total_bytes || 0);
                    progressLabel = (d.phase === 'modal_download_queued' ? '다운로드 대기' : pct + '%');
                    if (total > 0) {
                        progressLabel += ' <span style="font-size:0.65rem;color:var(--text3);">' +
                            comfyInstallerFormatBytes(done) + '/' + comfyInstallerFormatBytes(total) + '</span>';
                    }
                } else if (d.phase === 'h3_rendering') {
                    const current = Math.max(0, Number(d.current || 0));
                    const total = Math.max(0, Number(d.total || 0));
                    const renderPct = total > 0
                        ? Math.min(100, Math.round(current / total * 100))
                        : pct;
                    progressLabel = `H3 생성 ${renderPct}%`;
                    if (total > 0) {
                        progressLabel += ` <span style="font-size:0.65rem;color:var(--text3);">${current}/${total} 단계</span>`;
                    }
                } else if (d.phase === 'visual_profile_guide') {
                    const completed = Math.max(0, Number(d.completed || 0));
                    const total = Math.max(0, Number(d.total || 0));
                    const character = String(d.character || '').trim();
                    const isAppearanceStage = String(d.stage || '').startsWith('appearance_');
                    const profileCurrent = Math.max(0, Number(d.profile_current || 0));
                    const profileTotal = Math.max(0, Number(d.profile_total || 0));
                    progressLabel = isAppearanceStage
                        ? `외형 분석 ${profileCurrent}/${profileTotal}`
                        : `${pct}%`;
                    if (!isAppearanceStage && total > 0) {
                        progressLabel += ` <span style="font-size:0.65rem;color:var(--text3);">${completed}/${total}` +
                            `${character ? ' · ' + escapeHtml(character) : ''}</span>`;
                    } else if (isAppearanceStage && character) {
                        progressLabel += ` <span style="font-size:0.65rem;color:var(--text3);">${escapeHtml(character)}</span>`;
                    }
                } else if (String(d.phase || '').startsWith('video_')) {
                    const phaseLabels = {
                        video_postprocess_preparing: '후처리 준비',
                        video_extracting_frames: '프레임 추출',
                        video_frames_extracted: '프레임 추출 완료',
                        video_upscaler_preparing: '업스케일 준비',
                        video_upscaling: 'Real-ESRGAN',
                        video_upscaling_anime4k: 'Anime4K',
                        video_upscaling_lanczos: 'Lanczos',
                        video_upscale_skipped: '업스케일 생략',
                        video_encoding_raw: '원본 인코딩',
                        video_encoding_composite: '합성본 인코딩',
                        video_target_size_search: '목표 용량 탐색',
                        video_postprocess_validated: '결과 검증',
                        video_postprocess_complete: '후처리 완료',
                    };
                    progressLabel = `${phaseLabels[d.phase] || '영상 후처리'} ${pct}%`;
                    if (Number(d.total || 0) > 0 && Number(d.current || 0) >= 0) {
                        progressLabel += ` <span style="font-size:0.65rem;color:var(--text3);">${Number(d.current || 0)}/${Number(d.total)}</span>`;
                    }
                }
            }
            let subtaskSummary = '';
            if (hasSubtasks) {
                const finished = subtasks.filter(subtask =>
                    ['completed', 'failed', 'cancelled'].includes(subtask.status)
                ).length;
                const failed = subtasks.filter(subtask => subtask.status === 'failed').length;
                const groupLabel = subtasks[0].group_label || '하위 작업';
                subtaskSummary = `${groupLabel} ${finished}/${subtasks.length}`;
                if (failed > 0) subtaskSummary += ` · 오류 ${failed}`;
                progressLabel += ` <span style="font-size:0.65rem;color:var(--text3);">· ${escapeHtml(subtaskSummary)}</span>`;
            }
            const typeLabel = indent ? '' : (_queueTypeLabels[item.type] || item.type || '');
            const labelTxt = indent ? '↳ ' + (item.label || '') : (item.label || '');
            const labelHtml = hasSubtasks
                ? `<span class="qm-subtask-toggle" onclick="queueModalToggleSubtasks('${escapeHtml(item.id)}')">${subtasksExpanded ? '▼' : '▶'} ${escapeHtml(labelTxt)}</span>`
                : escapeHtml(labelTxt);
            let completedLabel = item.status === 'completed' ? '✓'
                : item.status === 'failed' ? '✗ 실패'
                : item.status === 'cancelled' ? '—'
                : '';
            if (!isProcessing && subtaskSummary) {
                completedLabel += ` <span style="font-size:0.65rem;color:var(--text3);">${escapeHtml(subtaskSummary)}</span>`;
            }
            el.innerHTML = `
                <span class="qm-handle" title="드래그하여 이동">${isPending ? '⠿' : '&nbsp;'}</span>
                <span class="qm-type">${typeLabel}</span>
                <span class="qm-label">${labelHtml}</span>
                <span class="qm-progress">${isProcessing ? progressLabel : (isWaiting ? '<span style="color:var(--text3);">' + (isComfyWaiting ? '생성 대기' : '슬롯 대기') + '</span>' : completedLabel)}</span>
                <span class="qm-actions">
                    ${isPending ? '<button onclick="queueModalMoveUp(\''+item.id+'\')" title="위로">▲</button><button onclick="queueModalMoveDown(\''+item.id+'\')" title="아래로">▼</button>' : ''}
                    ${isPending || isComfyWaiting ? '<button onclick="queueModalCancelItem(\''+item.id+'\')" title="취소">✕</button>' : ''}
                </span>
            `;
            if (item.status === 'failed') {
                el.appendChild(_renderQueueError(item));
            }
            const labelEl = el.querySelector('.qm-label');
            if (labelEl) labelEl.title = item.label || '';
            if (isPending) {
                const handle = el.querySelector('.qm-handle');
                handle.addEventListener('mousedown', (e) => queueModalDragStart(e, item.id));
            }
            return el;
        }

        function _renderQueueSubtaskRow(subtask, area) {
            const el = document.createElement('div');
            const status = ['pending', 'processing', 'completed', 'failed', 'cancelled'].includes(subtask.status)
                ? subtask.status
                : 'pending';
            el.className = 'queue-modal-item queue-modal-subtask ' + status;
            if (area) el.dataset.queueArea = area;
            const statusLabel = status === 'processing' ? '진행 중'
                : status === 'completed' ? '✓'
                : status === 'failed' ? '✗'
                : status === 'cancelled' ? '—'
                : '대기';
            const error = String(subtask.error || '');
            if (error) el.title = error;
            el.innerHTML = `
                <span class="qm-handle">&nbsp;</span>
                <span class="qm-type"></span>
                <span class="qm-label">↳ ${escapeHtml(subtask.label || '하위 작업')}</span>
                <span class="qm-progress">${statusLabel}</span>
                <span class="qm-actions"></span>
            `;
            const labelEl = el.querySelector('.qm-label');
            if (labelEl) labelEl.title = subtask.label || '하위 작업';
            if (status === 'failed') el.appendChild(_renderQueueError(subtask));
            return el;
        }

        const _queueErrorState = new Map();
        function _renderQueueError(item) {
            const key = String(item.id);
            if (!_queueErrorState.has(key)) _queueErrorState.set(key, { collapsed: false, scrollTop: 0 });
            const state = _queueErrorState.get(key);
            const details = document.createElement('details');
            details.className = 'queue-item-error';
            details.open = !state.collapsed;
            const summary = document.createElement('summary');
            summary.textContent = '실패 이유';
            const message = document.createElement('pre');
            message.tabIndex = 0;
            message.setAttribute('aria-label', `${item.label || '작업'} 실패 이유`);
            message.textContent = item.error || item.errorMsg || '실패 이유가 전달되지 않았습니다.';
            details.append(summary, message);
            details.addEventListener('toggle', () => {
                if (details.isConnected) state.collapsed = !details.open;
            });
            message.addEventListener('scroll', () => { state.scrollTop = message.scrollTop; });
            requestAnimationFrame(() => { if (details.isConnected) message.scrollTop = state.scrollTop; });
            return details;
        }

        const _queueBatchExpanded = new Set();
        const _queueBatchPages = new Map();
        const _queueSubtasksExpanded = new Set();
        function _expandActiveQueueSubtasks(item) {
            if (!item || !Array.isArray(item.subtasks)) return;
            if (item.subtasks.some(subtask => subtask.status === 'processing')) {
                _queueSubtasksExpanded.add(item.id);
            }
        }

        function queueModalToggleSubtasks(itemId) {
            if (!itemId) return;
            if (_queueSubtasksExpanded.has(itemId)) _queueSubtasksExpanded.delete(itemId);
            else _queueSubtasksExpanded.add(itemId);
            renderQueueModal();
        }

        function queueModalToggleBatch(batchId, page) {
            if (!batchId) return;
            if (page !== undefined) {
                _queueBatchPages.set(batchId, Math.max(0, page));
                _queueBatchExpanded.add(batchId);
            } else if (_queueBatchExpanded.has(batchId)) {
                _queueBatchExpanded.delete(batchId);
                _queueBatchPages.delete(batchId);
            }
            else _queueBatchExpanded.add(batchId);
            renderQueueModal();
        }

        async function queueModalCancelBatch(batchId) {
            if (!batchId) return;
            if (!confirm('이 배치의 남은 대기 항목을 모두 취소할까요? (처리 중인 1건은 완료됩니다)')) return;
            try {
                const resp = await fetchJSON('/api/queue/cancel_batch', {
                    method: 'POST', headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({ batch_id: batchId })
                });
                if (resp && resp.success) showToast(`배치 취소: ${resp.cancelled || 0}건`, 'success');
                else showToast((resp && resp.error) || '배치 취소 실패', 'error');
            } catch (e) { showToast(`배치 취소 실패: ${e.message || e}`, 'error'); }
        }

        function _queueItemFinished(item) {
            return ['completed', 'failed', 'cancelled'].includes(item.status);
        }

        function _queueHistoryItems(items) {
            return items.filter(_queueItemFinished)
                .sort((a, b) => (b.completed_at || b.created_at || 0) - (a.completed_at || a.created_at || 0))
                .slice(0, 10);
        }

        // 드래그 앤 드롭 (pending 항목끼리만)
        let _queueDragIdx = null;
        function queueModalDragStart(e, idx) {
            if (typeof idx === 'string') idx = queueModalData.findIndex(item => item.id === idx);
            _queueDragIdx = idx;
            const item = queueModalData[idx];
            if (!item || item.status !== 'pending') return;
            e.preventDefault();
            const body = document.getElementById('queue-modal-body');
            if (!body) { console.error('[QUEUE] queueModalDragStart: queue-modal-body 요소 없음'); return; }
            const area = _queueItemArea(item);
            const laneBody = body.querySelector(`.queue-lane-items[data-queue-area="${area}"]`)
                || (area === 'modal' || area === 'vast'
                    ? body.querySelector('.queue-lane-items[data-queue-area="cloud"]')
                    : null);
            if (!laneBody) { console.error('[QUEUE] 드래그 대상 실행 영역 없음:', area); return; }
            const el = laneBody.querySelector(`.queue-modal-item[data-queue-item-id="${item.id}"]`);
            if (el) el.classList.add('dragging');

            const onMove = (ev) => {
                const items = Array.from(
                    laneBody.querySelectorAll('.queue-modal-item[data-queue-modal-idx]')
                ).filter(child => child.dataset.queueArea === area);
                items.forEach(child => {
                    if (child.dataset.queueItemId === item.id) return;
                    const rect = child.getBoundingClientRect();
                    const mid = rect.top + rect.height / 2;
                    if (ev.clientY < mid) child.style.borderTop = '2px solid var(--accent)';
                    else if (ev.clientY > mid) child.style.borderBottom = '2px solid var(--accent)';
                    else { child.style.borderTop = ''; child.style.borderBottom = ''; }
                });
            };
            const onUp = (ev) => {
                document.removeEventListener('mousemove', onMove);
                document.removeEventListener('mouseup', onUp);
                laneBody.querySelectorAll('.queue-modal-item').forEach(c => { c.classList.remove('dragging'); c.style.borderTop = ''; c.style.borderBottom = ''; });
                const items = Array.from(
                    laneBody.querySelectorAll('.queue-modal-item[data-queue-modal-idx]')
                ).filter(child => child.dataset.queueArea === area);
                idx = queueModalData.findIndex(current => current.id === item.id && current.status === 'pending');
                if (idx < 0) {
                    console.warn('[QUEUE] 드래그 중 항목이 이동 불가능한 상태로 변경됨:', item.id);
                    renderQueueModal();
                    return;
                }
                let targetIdx = idx;
                let closestDistance = Number.POSITIVE_INFINITY;
                items.forEach(child => {
                    const childIdx = queueModalData.findIndex(current => current.id === child.dataset.queueItemId);
                    if (childIdx < 0 || childIdx === idx) return;
                    const rect = child.getBoundingClientRect();
                    const mid = rect.top + rect.height / 2;
                    const distance = Math.abs(ev.clientY - mid);
                    if (distance < closestDistance) {
                        closestDistance = distance;
                        targetIdx = childIdx;
                    }
                });
                if (
                    targetIdx !== idx
                    && queueModalData[targetIdx]?.status === 'pending'
                    && _queueItemArea(queueModalData[targetIdx]) === area
                ) {
                    const [moved] = queueModalData.splice(idx, 1);
                    const adjustedTarget = targetIdx > idx ? targetIdx - 1 : targetIdx;
                    queueModalData.splice(adjustedTarget, 0, moved);
                }
                renderQueueModal();
            };
            document.addEventListener('mousemove', onMove);
            document.addEventListener('mouseup', onUp);
        }

        function queueModalMoveUp(idx) {
            if (typeof idx === 'string') idx = queueModalData.findIndex(item => item.id === idx);
            const area = _queueItemArea(queueModalData[idx]);
            const pendingIndices = queueModalData.map(
                (item, ci) => item.status === 'pending' && _queueItemArea(item) === area ? ci : -1
            ).filter(ci => ci >= 0);
            const posInPending = pendingIndices.indexOf(idx);
            if (posInPending <= 0) return;
            const prevIdx = pendingIndices[posInPending - 1];
            [queueModalData[idx], queueModalData[prevIdx]] = [queueModalData[prevIdx], queueModalData[idx]];
            renderQueueModal();
        }
        function queueModalMoveDown(idx) {
            if (typeof idx === 'string') idx = queueModalData.findIndex(item => item.id === idx);
            const area = _queueItemArea(queueModalData[idx]);
            const pendingIndices = queueModalData.map(
                (item, ci) => item.status === 'pending' && _queueItemArea(item) === area ? ci : -1
            ).filter(ci => ci >= 0);
            const posInPending = pendingIndices.indexOf(idx);
            if (posInPending < 0 || posInPending >= pendingIndices.length - 1) return;
            const nextIdx = pendingIndices[posInPending + 1];
            [queueModalData[idx], queueModalData[nextIdx]] = [queueModalData[nextIdx], queueModalData[idx]];
            renderQueueModal();
        }

        async function queueModalCancelItem(id) {
            try { await fetchJSON('/api/queue/cancel', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ id }) }); } catch (e) {}
        }
        async function queueModalCancelAll() {
            if (!confirm('대기 중인 모든 작업을 취소하시겠습니까?')) return;
            try { await fetchJSON('/api/queue/cancel_all', { method: 'POST' }); } catch (e) { console.error('[QUEUE] 전체 취소 실패:', e); }
        }
        async function queueModalTogglePause() {
            const next = !queuePaused;
            try {
                const res = await fetchJSON('/api/queue/pause', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ paused: next }),
                });
                if (res && typeof res.paused === 'boolean') {
                    queuePaused = res.paused;
                    _updateQueuePauseUI();
                } else if (res && res.error) {
                    alert('일시정지 토글 실패: ' + res.error);
                }
            } catch (e) {
                console.error('[QUEUE] 일시정지 토글 실패:', e);
                alert('일시정지 토글 실패: ' + (e && e.message ? e.message : e));
            }
        }
        function _updateQueuePauseUI() {
            const btn = document.getElementById('queue-pause-btn');
            if (btn) {
                if (queuePaused) {
                    btn.textContent = '▶ 재개';
                    btn.style.background = 'var(--accent)';
                    btn.style.color = '#fff';
                    btn.style.borderColor = 'var(--accent)';
                } else {
                    btn.textContent = '⏸ 일시정지';
                    btn.style.background = 'transparent';
                    btn.style.color = 'var(--text2)';
                    btn.style.borderColor = 'var(--border)';
                }
            }
            // 상단 툴바 배지 색으로 일시정지 상태 표시 (정지 중엔 주황/경고색)
            const badge = document.getElementById('queue-badge');
            if (badge) badge.style.background = queuePaused ? 'var(--warning, #e8a33d)' : 'var(--accent)';
        }
        async function queueModalClearCompleted() {
            try {
                for (const item of _queueHistoryItems(queueModalData)) {
                    await removeQueueItemBackend(item.id);
                }
                const data = await fetchJSON('/api/queue/status');
                handleQueueUpdated(data);
                renderQueueModal();
            } catch (e) {
                showToast(`완료 정리 실패: ${e.message || e}`, 'error');
            }
        }

        // ─── 통합 큐 WebSocket 핸들러 ────────────────────────
        function handleQueueUpdated(data) {
            if (!data || !data.items) { console.warn('[QUEUE] handleQueueUpdated: 데이터 없음', data); return; }
            notifyModalWorkerQueueState(data);
            if (typeof atReconcileDefaultGenerationQueue === 'function') {
                atReconcileDefaultGenerationQueue(data.items);
            }
            // 백엔드 상태를 프론트엔드 assetQueue에 동기화
            assetQueue = data.items.map(item => ({
                id: item.id,
                type: item.type || 'asset_generation',
                label: item.label,
                status: item.status,
                progress: item.progress || 0,
                progress_detail: item.progress_detail || {},
                subtasks: Array.isArray(item.subtasks) ? item.subtasks : [],
                startTime: item.started_at ? item.started_at * 1000 : null,
                endTime: item.completed_at ? item.completed_at * 1000 : null,
                errorMsg: item.error || '',
                created_at: item.created_at,
                completed_at: item.completed_at,
                autoHideAt: null,
                batch_id: item.batch_id || null,
                batch_label: item.batch_label || null,
                batch_index: item.batch_index || null,
                batch_total: item.batch_total || null,
            }));

            // failed 큐 항목 → 토스트 알림 (ComfyUI 미실행 등 조용한 실패 방지).
            // 최근 작업 기록과 별개로 항목별 1회 즉시 알린다.
            const _nowFail = Date.now();
            _queueFailRecentMsgs = _queueFailRecentMsgs.filter(r => _nowFail - r.ts < QUEUE_FAIL_TOAST_RECENT_MS);
            data.items.forEach(item => {
                if (!item || item.status !== 'failed') return;
                if (_queueFailToastedIds.has(item.id)) return; // 항목별 1회 알림
                _queueFailToastedIds.add(item.id);
                setAssetQueuePanelExpanded(true);
                const queueBody = document.getElementById('queue-modal-body');
                if (queueBody) queueBody.scrollTop = 0;
                // 비동기 재생성은 하이브리드 폴백이 끝난 뒤 전용 WS 이벤트로
                // 최종 실패를 알린다. 첫 공급자 실패를 중간 오류로 띄우지 않는다.
                if (item.params?.regeneration_request_id) return;
                const failMsg = String(item.error || '큐 작업 실패').trim();
                if (_queueFailRecentMsgs.some(r => r.msg === failMsg)) return; // 동일 메시지 중복 억제
                _queueFailRecentMsgs.push({ msg: failMsg, ts: _nowFail });
                showToast(failMsg, 'error');
            });
            // 사라진 항목 id는 정리 (세션 장기화 시 Set 무한 증가 방지)
            const _liveQueueIds = new Set(data.items.map(i => i && i.id));
            data.items.forEach(item => (item.subtasks || []).forEach(subtask => _liveQueueIds.add(subtask.id)));
            for (const id of _queueErrorState.keys()) {
                if (!_liveQueueIds.has(id)) _queueErrorState.delete(id);
            }
            for (const _id of Array.from(_queueFailToastedIds)) {
                if (!_liveQueueIds.has(_id)) _queueFailToastedIds.delete(_id);
            }

            assetQueueProcessing = data.processing;
            assetCurrentQueueId = data.current ? data.current.id : null;
            renderAssetQueueUI();
            updateGenerateBtn();
            // 처리중이 아닐 때 상단 진행도 바 숨김
            if (!data.processing) hideTopProgress();

            // 큐 모달 상태 동기화
            const prevStatus = {};
            queueModalData.forEach(i => prevStatus[i.id] = i.status);
            queueModalData = data.items.map(item => ({
                id: item.id,
                type: item.type || '',
                label: item.label || '',
                status: item.status,
                error: item.error || '',
                created_at: item.created_at,
                completed_at: item.completed_at,
                progress: item.progress || 0,
                progress_detail: item.progress_detail || {},
                subtasks: Array.isArray(item.subtasks) ? item.subtasks : [],
                execution_area: item.execution_area || 'gpu',
                provider: item.provider || '',
                batch_id: item.batch_id || null,
                batch_label: item.batch_label || null,
                batch_index: item.batch_index || null,
                batch_total: item.batch_total || null,
            }));
            queueModalData.forEach(_expandActiveQueueSubtasks);
            updateQueueBadge();
            // 삽화 대기 상태 동기화
            const wasWaiting = queueIllustWaiting;
            queueIllustWaiting = !!data.illust_waiting;
            queueIllustWaitStartedAt = data.illust_wait_started_at ? data.illust_wait_started_at * 1000 : null;
            queueIllustWaitSeconds = data.illust_wait_seconds || 10;
            _updateIllustWaitTimer();
            const prevPaused = queuePaused;
            queuePaused = !!data.paused;
            if (prevPaused !== queuePaused) _updateQueuePauseUI();
            if (queueModalOpen) renderQueueModal();

            // 인스턴스 LoRA 관련 큐 완료 시 그리드 자동 갱신
            const instanceTypes = ['instance_lora_training', 'instance_lora_analysis'];
            const instanceCompleted = data.items.some(i =>
                    instanceTypes.includes(i.type) && (i.status === 'completed' || i.status === 'failed')
                    && prevStatus[i.id] !== i.status
            );
            if (instanceCompleted && typeof loadInstanceLoraGrid === 'function') {
                loadInstanceLoraGrid();
            }

            // 이미지 생성 계열 큐 완료 시 백업 탭 자동 갱신 (WS 불안정 폴백)
            const genTypes = ['restore_manual', 'illustration', 'regenerate', 'asset_generation', 'data_patch'];
            const genJustCompleted = data.items.some(i =>
                genTypes.includes(i.type) &&
                (i.status === 'completed' || i.status === 'failed') &&
                prevStatus[i.id] && prevStatus[i.id] !== i.status
            );
            if (genJustCompleted && typeof loadBackups === 'function') {
                loadBackups(true);
            }

            // 큐가 계산한 실제 종료 수로 일괄 작업 완료 및 후속 단계 전환.
            if (typeof _reconcileTagBatchesFromQueue === 'function') {
                _reconcileTagBatchesFromQueue(data.items, data.batches);
            }
        }

        function handleQueueProgress(data) {
            if (!data) { console.warn('[QUEUE] handleQueueProgress: 데이터 없음'); return; }
            _handleVisualGuideQueueProgress(data);
            const item = assetQueue.find(q => q.id === data.item_id);
            if (item) {
                item.progress = data.progress || 0;
                item.progress_detail = data.detail || {};
                if (Array.isArray(data.subtasks)) item.subtasks = data.subtasks;
                if (data.detail) {
                    if (data.detail.phase === 'generating') {
                        updateTopProgress(data.detail.value || 0, data.detail.max || 100);
                    } else if (data.detail.phase === 'training') {
                        updateTopProgress(data.detail.step || 0, data.detail.total || 100);
                    }
                }
            } else {
                console.warn('[QUEUE] handleQueueProgress: assetQueue에서 항목 못 찾음, item_id=', data.item_id, 'assetQueue IDs=', assetQueue.map(q => q.id));
            }
            renderAssetQueueUI();
            // 큐 모달 진행률 업데이트
            const modalItem = queueModalData.find(q => q.id === data.item_id);
            if (modalItem) {
                modalItem.progress = data.progress || 0;
                modalItem.progress_detail = data.detail || {};
                if (Array.isArray(data.subtasks)) {
                    modalItem.subtasks = data.subtasks;
                    _expandActiveQueueSubtasks(modalItem);
                }
            }
            if (queueModalOpen) renderQueueModal();
        }

        // 에셋 태그 분석 진행률 WebSocket 핸들러
        function handleAssetAnalyzeProgress(type, data) {
            console.log('[AU] 태그 분석 진행률 수신:', type, data);
            const statusEl = document.getElementById('au-analyze-status');
            if (!statusEl) return;
            statusEl.style.display = 'block';
            const current = data.current || 0;
            const total = data.total || 0;
            const label = type === 'asset_mode_batch_progress' ? '대표이미지' : '선택';
            const detail = data.filename ? ` - ${data.filename}` : (data.outfit ? ` - ${data.outfit}/${data.expression}` : '');
            statusEl.textContent = `${label} 분석 중... (${current}/${total})${detail}`;
        }

        // ─── 사이드바 리사이즈 ─────────────────────────────────
        (function() {
            const handle = document.getElementById('sidebar-resize-handle');
            const sidebar = document.getElementById('asset-sidebar');
            if (!handle || !sidebar) return;
            let dragging = false;
            let startX, startW;

            handle.addEventListener('mousedown', (e) => {
                e.preventDefault();
                dragging = true;
                startX = e.clientX;
                startW = sidebar.offsetWidth;
                handle.classList.add('active');
                document.body.style.cursor = 'col-resize';
                document.body.style.userSelect = 'none';
            });

            document.addEventListener('mousemove', (e) => {
                if (!dragging) return;
                const diff = startX - e.clientX; // 왼쪽으로 드래그 = 넓어짐
                let newW = startW + diff;
                newW = Math.max(280, Math.min(800, newW));
                sidebar.style.width = newW + 'px';
            });

            document.addEventListener('mouseup', () => {
                if (!dragging) return;
                dragging = false;
                handle.classList.remove('active');
                document.body.style.cursor = '';
                document.body.style.userSelect = '';
            });
        })();

